def _is_xr_dataset(obj):
    """Return whether ``obj`` behaves as an ``xarray.Dataset`` (checked without importing xarray).

    Parameters
    ----------
    obj : object
        Candidate result container; an xarray Dataset exposes data_vars, coords and attrs.
    """
    return hasattr(obj, "data_vars") and hasattr(obj, "coords") and hasattr(obj, "attrs")


def _is_xr_dataarray(obj):
    """Return whether ``obj`` behaves as an ``xarray.DataArray`` (labeled array, no data_vars).

    Parameters
    ----------
    obj : object
        Candidate array; an xarray DataArray exposes dims, coords and to_pandas but no data_vars.
    """
    return hasattr(obj, "dims") and hasattr(obj, "to_pandas") and not hasattr(obj, "data_vars")


def _axis_labels(index):
    """Coordinate labels for a pandas axis, matching ``vigor.results.to_dataarray``.

    Parameters
    ----------
    index : pandas.Index or array-like
        Axis labels; object-dtype labels are converted to strings exactly as the shared
        Dataset builder does, other dtypes are kept as their NumPy values.
    """
    idx = pd.Index(index)
    return np.asarray(idx).astype(str) if idx.dtype == object else idx.to_numpy()


def _as_pandas_input(value):
    """Convert a 1-D/2-D ``xarray.DataArray`` input to pandas; any other input passes through.

    Parameters
    ----------
    value : object
        Covariance matrix, kernel or vector. DataArrays (for example ``fit['G']`` from a Dataset
        result) become a DataFrame/Series labeled by their coordinates; a stored
        ``domino_covspec`` factor specification is carried into ``DataFrame.attrs``.
    """
    if not (_is_xr_dataarray(value) and value.ndim in (1, 2)):
        return value
    out = value.to_pandas()
    out.index.name = None
    if value.ndim == 2:
        out.columns.name = None
        if "domino_covspec" in value.attrs:
            out.attrs["domino_covspec"] = value.attrs["domino_covspec"]
    return out


def _kernel_input(grm):
    """Convert xarray kernel containers to the pandas/dict relationship-kernel forms used here.

    Parameters
    ----------
    grm : array-like, kernel operator, mapping, xarray.DataArray or xarray.Dataset
        Animal relationship kernel(s). A Dataset (for example ``genomic_grms_from_genotypes``
        output) becomes a dict of labeled DataFrames keyed by its 2-D data-variable names; a
        DataArray becomes one labeled DataFrame. Other inputs are returned unchanged.
    """
    if _is_xr_dataset(grm):
        return {str(k): _as_pandas_input(v) for k, v in grm.data_vars.items() if v.ndim == 2}
    return _as_pandas_input(grm)


def _dataarray_to_pandas(da, name=None):
    """Convert one result variable back to its historical pandas/NumPy container.

    Parameters
    ----------
    da : xarray.DataArray
        Result variable. A leading ``component`` dimension is unstacked into a dict keyed by
        component label; 1-D/2-D variables become labeled Series/DataFrames.
    name : str or None
        Historical key; keys whose legacy value was a bare NumPy array (for example
        ``E_matrix`` or ``valid_vg``) are returned as arrays. Default: ``None`` uses da.name.
    """
    key = str(da.name if name is None else name)
    if da.ndim >= 2 and da.dims[0] == "component":
        labels = [str(c) for c in (da["component"].values if "component" in da.coords else range(da.shape[0]))]
        return {c: _dataarray_to_pandas(da.isel(component=i), key) for i, c in enumerate(labels)}
    if da.ndim == 0:
        return da.values.item()
    if key in _VIEW_NDARRAY_KEYS or da.ndim > 2:
        return np.asarray(da.values)

    def axis(dim):
        """Return the pandas axis for one dimension from its coordinate (or a RangeIndex).

        Parameters
        ----------
        dim : str
            Dimension name of the enclosing variable whose coordinate labels are requested.
        """
        return pd.Index(da[dim].values) if dim in da.coords else pd.RangeIndex(da.sizes[dim])
    if da.ndim == 1:
        return pd.Series(np.asarray(da.values), index=axis(da.dims[0]))
    out = pd.DataFrame(np.asarray(da.values), index=axis(da.dims[0]), columns=axis(da.dims[1]))
    if "domino_covspec" in da.attrs:
        out.attrs["domino_covspec"] = da.attrs["domino_covspec"]
    return out


def _result_view(result):
    """Return a legacy dict view (pandas containers + attrs) of a VIGOR result Dataset.

    Parameters
    ----------
    result : xarray.Dataset, mapping or pandas.Series
        A Dataset is flattened into ``{**ds.attrs, name: pandas value}``: trait matrices become
        DataFrames, per-trait vectors Series, and ``component``-stacked variables dicts. Other
        objects (legacy dict/Series results) are returned unchanged.
    """
    if not _is_xr_dataset(result):
        return result
    out = dict(result.attrs)
    for name, da in result.data_vars.items():
        out[str(name)] = _dataarray_to_pandas(da, name)
    return out


def _covariance_input(value):
    """Normalize a covariance argument (fit Dataset, DataArray, dict fit) for prediction code.

    Parameters
    ----------
    value : object
        A genetic_varcov_PSD Dataset (or its dict view containing G_components) becomes the
        historical covariance-fit ``pandas.Series``; a DataArray becomes a DataFrame. Matrices,
        specifications and named component mappings are returned unchanged.
    """
    if _is_xr_dataset(value):
        return pd.Series(_result_view(value), dtype=object)
    if isinstance(value, dict) and ("G_components" in value or "G_components_prediction" in value):
        return pd.Series(value, dtype=object)
    return _as_pandas_input(value)


def _call_parameters(arguments):
    """Collect JSON-friendly scalar call parameters for ``ds.attrs['parameters']``.

    Parameters
    ----------
    arguments : mapping
        Bound call arguments. Scalars, strings, booleans, None, flat scalar tuples/lists, flat
        scalar dicts and NumPy dtypes (by name) are kept; arrays, tables, kernels and nested
        objects are omitted, as are ``save_path`` and private underscore names.
    """
    def scalar(v):
        """Return whether ``v`` is a JSON scalar (str, bool, int, float or None).

        Parameters
        ----------
        v : object
            Candidate parameter value inspected without conversion or evaluation.
        """
        return v is None or isinstance(v, (str, bool, int, float, np.generic))

    out = {}
    for k, v in dict(arguments or {}).items():
        k = str(k)
        if k == "save_path" or k.startswith("_"):
            continue
        if scalar(v):
            out[k] = v.item() if isinstance(v, np.generic) else v
        elif isinstance(v, type) and issubclass(v, np.generic):
            out[k] = np.dtype(v).name
        elif isinstance(v, np.dtype):
            out[k] = v.name
        elif isinstance(v, (tuple, list)) and all(scalar(x) for x in v):
            out[k] = [x.item() if isinstance(x, np.generic) else x for x in v]
        elif isinstance(v, dict) and all(scalar(x) for x in v.values()):
            out[k] = {str(a): (b.item() if isinstance(b, np.generic) else b) for a, b in v.items()}
    return out


def _dataset_result(converter):
    """Decorate a public function so its historical container is returned as an ``xarray.Dataset``.

    Parameters
    ----------
    converter : callable
        ``converter(result, arguments)`` building the Dataset from the undecorated return value
        and the bound call arguments (defaults applied, variable keywords flattened). The
        undecorated implementation stays available as ``function.__wrapped__``.
    """
    import functools
    import inspect

    def decorate(function):
        """Wrap ``function`` with Dataset conversion and optional Zarr persistence.

        Parameters
        ----------
        function : callable
            Public implementation returning its historical pandas/NumPy/dict container; its
            signature documents ``save_path`` which the wrapper consumes.
        """
        signature = inspect.signature(function)
        varkw = next((p.name for p in signature.parameters.values() if p.kind is p.VAR_KEYWORD), None)

        @functools.wraps(function)
        def wrapped(*args, save_path=None, **kwargs):
            """Call the implementation, convert its result to a Dataset and optionally save it.

            Parameters
            ----------
            *args : tuple
                Positional arguments forwarded unchanged to the wrapped implementation.
            save_path : str, os.PathLike or None
                Optional .zarr path; when given the result is written as consolidated, sharded
                Zarr v3 and returned reopened lazily. Default: ``None``.
            **kwargs : dict
                Keyword arguments forwarded unchanged to the wrapped implementation.
            """
            from .results import maybe_save
            result = function(*args, **kwargs)
            try:
                bound = signature.bind(*args, **kwargs)
                bound.apply_defaults()
                arguments = dict(bound.arguments)
            except TypeError:
                arguments = dict(kwargs)
            if varkw is not None and isinstance(arguments.get(varkw), dict):
                arguments.update(arguments.pop(varkw))
            return maybe_save(converter(result, arguments), save_path)
        return wrapped
    return decorate


def _var_attrs(table, keys):
    """Build ``long_name``/``units``/``description`` attributes for result variables.

    Parameters
    ----------
    table : mapping
        Key to ``(long_name, units, description)`` tuples; missing entries fall back to the key
        with underscores replaced by spaces.
    keys : iterable of str
        Data-variable names receiving attributes in the returned mapping.
    """
    out = {}
    for key in keys:
        long_name, units, description = table.get(key, (str(key).replace("_", " "), None, None))
        out[key] = {k: v for k, v in (("long_name", long_name), ("units", units), ("description", description)) if v is not None}
    return out


def _stack_components(mapping, key, labels=None, sample_labels=None, sample_dims=("sample_i", "sample_j"), inner_dims=None):
    """Stack a component-keyed mapping of equally shaped arrays along a ``component`` dimension.

    Parameters
    ----------
    mapping : mapping
        Component name to array/DataFrame/Series. Object arrays or unequal shapes return None
        so the caller keeps the mapping as an attribute.
    key : str
        Historical result key; used for the DataArray name and generic dimension names.
    labels : array-like or None
        Trait coordinate labels; t-by-t members use trait_i/trait_j and length-t members use
        trait. Default: ``None`` (no trait coordinates and shape-only dimensions).
    sample_labels : array-like or None
        Animal labels for animal-by-trait or animal-by-animal members. Default: ``None``.
    sample_dims : tuple of str
        Dimension names for square animal-by-animal members such as relationship kernels.
        Default: ``('sample_i', 'sample_j')``.
    inner_dims : tuple of str or None
        Explicit member dimension names (for example ('sample','trait')), overriding the
        shape-based choice; trait/sample coordinates are attached when their lengths match.
        Default: ``None`` infers dimensions from the member shape.
    """
    xr = _require_xarray()
    names = [str(k) for k in mapping]
    try:
        arrs = [np.asarray(v) for v in mapping.values()]
    except Exception:
        return None
    if not arrs or any(a.dtype == object for a in arrs) or len({a.shape for a in arrs}) != 1:
        return None
    shape = arrs[0].shape
    t = None if labels is None else len(labels)
    coords = {"component": np.asarray(names)}
    if inner_dims is not None:
        if len(inner_dims) != len(shape):
            return None
        known = {"trait": labels, "trait_i": labels, "trait_j": labels, "sample": sample_labels,
                 "sample_i": sample_labels, "sample_j": sample_labels}
        for d, size in zip(inner_dims, shape):
            if known.get(d) is not None and len(known[d]) == size:
                coords[d] = known[d]
        return xr.DataArray(np.stack(arrs), dims=("component",) + tuple(inner_dims), coords=coords, name=key)
    if t is not None and shape == (t, t):
        dims = ("component", "trait_i", "trait_j"); coords.update(trait_i=labels, trait_j=labels)
    elif t is not None and shape == (t,):
        dims = ("component", "trait"); coords.update(trait=labels)
    elif t is not None and len(shape) == 2 and shape[1] == t and sample_labels is not None and shape[0] == len(sample_labels):
        dims = ("component", "sample", "trait"); coords.update(sample=sample_labels, trait=labels)
    elif len(shape) == 2 and shape[0] == shape[1]:
        dims = ("component",) + tuple(sample_dims)
        first = next(iter(mapping.values()))
        if isinstance(first, pd.DataFrame):
            coords.update({sample_dims[0]: _axis_labels(first.index), sample_dims[1]: _axis_labels(first.columns)})
        elif sample_labels is not None and len(sample_labels) == shape[0]:
            coords.update({sample_dims[0]: sample_labels, sample_dims[1]: sample_labels})
    else:
        return None
    return xr.DataArray(np.stack(arrs), dims=dims, coords=coords, name=key)


def _ci_column_dim(key, frame):
    """Name the second dimension of a trait-indexed interval/summary table.

    Parameters
    ----------
    key : str
        Historical key, used for a unique fallback dimension name.
    frame : pandas.DataFrame
        Trait-indexed table; lower/upper columns use ``bound`` and q-labelled bootstrap
        quantile columns use ``quantile``.
    """
    cols = [str(c) for c in frame.columns]
    if cols == ["lower", "upper"]:
        return "bound"
    if cols and all(c.startswith("q") for c in cols):
        return "quantile"
    return f"{key}_column"


def _covariance_fit_dataset(out, arguments=None, *, software="vigor.multivariate.genetic_varcov_PSD",
                            title="Multivariate genetic and residual covariance fit"):
    """Convert a covariance-fit mapping (genetic_varcov_PSD layout) into a labeled Dataset.

    Parameters
    ----------
    out : mapping, pandas.Series or xarray.Dataset
        Historical covariance-fit container. Trait-by-trait tables become ('trait_i','trait_j')
        variables, per-trait vectors ('trait',), interval tables ('trait','bound'/'quantile'),
        component mappings ('component', ...), and everything else ``ds.attrs`` under its key.
        A Dataset is returned unchanged.
    arguments : mapping or None
        Bound call arguments recorded as ``ds.attrs['parameters']`` (scalars only). Default:
        ``None`` records no parameters.
    software : str
        Producing function recorded in ``ds.attrs['software']``. Default:
        ``'vigor.multivariate.genetic_varcov_PSD'``.
    title : str
        Human-readable title recorded in ``ds.attrs['title']``. Default: ``'Multivariate
        genetic and residual covariance fit'``.
    """
    from .results import result_dataset
    if _is_xr_dataset(out):
        return out
    out = dict(out.items())
    G0 = out.get("G", out.get("E"))
    if isinstance(G0, pd.DataFrame):
        cols = pd.Index(G0.columns)
    elif isinstance(G0, np.ndarray) and G0.ndim == 2:
        cols = pd.RangeIndex(G0.shape[0])
    else:
        cols = None
    labels = None if cols is None else _axis_labels(cols)
    T = None if cols is None else len(cols)
    values, dims, extra = {}, {}, {}
    for key, val in out.items():
        key = str(key)
        if val is None:
            extra[key] = None
            continue
        if key in _FIT_STACKED_KEYS and isinstance(val, dict) and val:
            fx = out.get("fixed_prediction")
            first = next(iter(val.values()))
            sl = (_axis_labels(first.index) if key == "gxe_kernels" and isinstance(first, pd.DataFrame)
                  else _axis_labels(fx.index) if isinstance(fx, pd.DataFrame) else None)
            da = _stack_components(val, key, labels, sample_labels=sl,
                                   inner_dims=("sample_i", "sample_j") if key == "gxe_kernels" else None)
            if da is not None:
                values[key] = da
                continue
        if isinstance(val, pd.DataFrame) and cols is not None:
            if val.index.equals(cols) and val.columns.equals(cols):
                dims[key] = ("trait_i", "trait_j")
            elif val.index.equals(cols):
                dims[key] = ("trait", _ci_column_dim(key, val))
            elif val.columns.equals(cols):
                dims[key] = ("sample", "trait") if key in _FIT_SAMPLE_KEYS else (f"{key}_row", "trait")
            else:
                extra[key] = val
                continue
            values[key] = val
            continue
        if isinstance(val, pd.Series) and cols is not None and len(val) == T and val.index.equals(cols) and val.dtype != object:
            dims[key] = ("trait",); values[key] = val
            continue
        if isinstance(val, np.ndarray) and val.dtype != object and T is not None and val.shape in {(T,), (T, T)}:
            dims[key] = ("trait",) if val.ndim == 1 else ("trait_i", "trait_j")
            values[key] = val
            continue
        if isinstance(val, (pd.DataFrame, pd.Series)) or (isinstance(val, np.ndarray) and val.ndim >= 1):
            extra[key] = val
            continue
        values[key] = val
    array_keys = [k for k, v in values.items() if isinstance(v, (pd.DataFrame, pd.Series, np.ndarray)) or _is_xr_dataarray(v)]
    var_attrs = _var_attrs(_COVARIANCE_VAR_ATTRS, array_keys)
    for key in array_keys:
        spec = getattr(values[key], "attrs", {}).get("domino_covspec") if isinstance(values[key], pd.DataFrame) else None
        if spec is not None:
            var_attrs[key]["domino_covspec"] = spec
    ds = result_dataset(values, dims=dims, var_attrs=var_attrs, attrs=extra, title=title, software=software,
                        parameters=None if arguments is None else _call_parameters(arguments))
    if labels is not None:
        ds = ds.assign_coords({d: labels for d in ("trait", "trait_i", "trait_j") if d in ds.dims and d not in ds.coords})
    return ds


def _labeled_result_dataset(values, *, traits=None, dims=None, stacked=(), var_table=None, title=None,
                            software=None, arguments=None):
    """Build a prediction-style Dataset on ``sample``/``trait`` axes from a historical mapping.

    Parameters
    ----------
    values : mapping
        Historical result fields. Explicit ``dims`` win; otherwise n x t arrays use
        ('sample','trait'), t x t ('trait_i','trait_j'), length-t ('trait',), length-n
        ('sample',); keys in ``stacked`` are component mappings; None and unclassified
        objects/tables become ``ds.attrs`` under their key.
    traits : pandas.DataFrame, array-like or None
        Input phenotype matrix defining n, t and (for DataFrames) the sample/trait coordinate
        labels. Default: ``None`` disables shape-based classification.
    dims : mapping or None
        Explicit per-key dimension names for arrays whose role is known. Default: ``None``.
    stacked : iterable of str
        Keys whose dict values are stacked along a ``component`` dimension. Default: ``()``.
    var_table : mapping or None
        ``(long_name, units, description)`` table for variable attributes. Default: ``None``
        uses the shared prediction table.
    title : str or None
        Human title stored in ``ds.attrs['title']``. Default: ``None``.
    software : str or None
        Producing function stored in ``ds.attrs['software']``. Default: ``None``.
    arguments : mapping or None
        Bound call arguments recorded (scalars only) in ``ds.attrs['parameters']``. Default:
        ``None``.
    """
    from .results import result_dataset
    dims = dict(dims or {})
    shape = np.shape(traits) if traits is not None else None
    n, t = (shape[0], shape[1]) if shape is not None and len(shape) == 2 else (None, None)
    sample_labels = _axis_labels(traits.index) if isinstance(traits, pd.DataFrame) else None
    trait_labels = _axis_labels(traits.columns) if isinstance(traits, pd.DataFrame) else None
    data, extra = {}, {}
    for key, val in dict(values).items():
        key = str(key)
        if val is None:
            extra[key] = None
            continue
        if key in tuple(stacked) and isinstance(val, dict):
            inner = dims.get(key)
            da = _stack_components(val, key, trait_labels if trait_labels is not None else (None if t is None else np.arange(t)),
                                   sample_labels=sample_labels if sample_labels is not None else (None if n is None else np.arange(n)),
                                   inner_dims=None if inner is None else tuple(inner)[1:])
            if da is not None:
                data[key] = da
                continue
        arr_like = isinstance(val, (pd.DataFrame, pd.Series)) or (isinstance(val, np.ndarray) and val.ndim >= 1 and val.dtype != object) or _is_xr_dataarray(val)
        if not arr_like:
            if isinstance(val, np.ndarray) and val.ndim >= 1:
                extra[key] = val
            else:
                data[key] = val
            continue
        if _is_xr_dataarray(val):
            data[key] = val
            continue
        d = dims.get(key)
        s = np.shape(val)
        if d is None:
            if n is not None and s == (n, t):
                d = ("sample", "trait")
            elif t is not None and s == (t, t):
                d = ("trait_i", "trait_j")
            elif t is not None and s == (t,):
                d = ("trait",)
            elif n is not None and s == (n,):
                d = ("sample",)
            elif len(s) == 1:
                d = (f"{key}_index",)
            elif isinstance(val, pd.DataFrame) and n is not None and s[0] == n:
                d = ("sample", f"{key}_column")
            else:
                extra[key] = val
                continue
        if isinstance(val, pd.Series) and val.dtype == object:
            val = val.astype(str)
        dims[key] = tuple(d)
        data[key] = val
    keys = [k for k, v in data.items() if isinstance(v, (pd.DataFrame, pd.Series, np.ndarray)) or _is_xr_dataarray(v)]
    ds = result_dataset(data, dims={k: v for k, v in dims.items() if k in data and not _is_xr_dataarray(data[k])},
                        var_attrs=_var_attrs(var_table or _PREDICTION_VAR_ATTRS, keys),
                        attrs=extra, title=title, software=software,
                        parameters=None if arguments is None else _call_parameters(arguments))
    coords = {}
    if sample_labels is not None:
        coords["sample"] = sample_labels
    if trait_labels is not None:
        coords.update(trait=trait_labels, trait_i=trait_labels, trait_j=trait_labels)
    coords = {d: c for d, c in coords.items() if d in ds.dims and d not in ds.coords and ds.sizes[d] == len(c)}
    return ds.assign_coords(coords) if coords else ds


def corr_se_matrix_fisher(df):
    """Estimate pairwise phenotype correlations and Fisher-transform standard errors using joint observation counts.

    Parameters
    ----------
    df : pandas.DataFrame
        Animal × trait observations; Pearson correlation uses each pair's nonmissing rows. At
        least four jointly observed values are required for a finite Fisher-based correlation
        SE; counts are returned for diagnosing unsupported pairs.

    Returns
    -------
    tuple of pandas.DataFrame
        (correlation, correlation_standard_error, joint_observation_count), with both axes
        labeled by traits. Standard errors are NaN below four pairwise observations.

    """
    r = df.corr(method='pearson')
    n = df.notna().astype(int).T @ df.notna().astype(int)
    se_z = 1 / np.sqrt(n - 3)
    se_r = (1 - r ** 2) * se_z
    se_r = se_r.where(n >= 4)
    return (r, se_r, n)

def _wrap_mvblup_output(Uhat, traits_is_df, row_index, col_index, return_numpy):
    """Restore animal/trait labels on breeding-value predictions unless array output is requested.

    Parameters
    ----------
    Uhat : object (see the cited input contract)
        Any Accepted as provided to the function.

    traits_is_df : object (see the cited input contract)
        Any Accepted as provided to the function.

    row_index : object (see the cited input contract)
        Any Accepted as provided to the function.

    col_index : object (see the cited input contract)
        Any Accepted as provided to the function.

    return_numpy : object (see the cited input contract)
        Any Accepted as provided to the function.
    """
    if traits_is_df and (not return_numpy): return pd.DataFrame(Uhat, index=row_index, columns=col_index)
    return Uhat

def _invsqrt_psd(M, eps=1e-10):
    """Compute the inverse square root of a symmetric covariance after flooring eigenvalues.

    Parameters
    ----------
    M : array-like or numeric scalar
        Numerical operand in ``_symmetrize(np.asarray(M, dtype=float))``. Shape must conform to
        that matrix/vector operation and the enclosing prepared state.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``.
    """
    M = _symmetrize(np.asarray(M, dtype=float))
    w, V = np.linalg.eigh(M)
    w = np.clip(w, eps, None)
    return V * (1.0 / np.sqrt(w)) @ V.T

def _project_psd(M, eps=1e-10):
    """Project a symmetric matrix onto the positive-semidefinite cone by flooring eigenvalues.

    Parameters
    ----------
    M : array-like or numeric scalar
        Numerical operand in ``_symmetrize(np.asarray(M, dtype=float))``. Shape must conform to
        that matrix/vector operation and the enclosing prepared state.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``.
    """
    M = _symmetrize(np.asarray(M, dtype=float))
    w, V = np.linalg.eigh(M)
    w = np.clip(w, eps, None)
    return V * w @ V.T

def _cov_to_corr(C, eps=1e-10):
    """Normalize covariance entries by the square root of their marginal variances.

    Parameters
    ----------
    C : array-like or numeric scalar
        Numerical operand in ``C / np.outer(d, d)``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``.
    """
    d = np.sqrt(np.clip(np.diag(C), eps, None))
    R = C / np.outer(d, d)
    R = _symmetrize(R)
    return (R, d)

def _corr_to_cov(R, scale):
    """Rescale a correlation matrix by the supplied trait standard deviations.

    Parameters
    ----------
    R : array-like or numeric scalar
        Numerical operand in ``R * np.outer(scale, scale)``. Shape must conform to that
        matrix/vector operation and the enclosing prepared state.

    scale : array-like or numeric scalar
        Any Accepted as provided to the function.
    """
    return _symmetrize(R * np.outer(scale, scale))

def _matrix_labels(C):
    """Trait coordinate labels of a labeled covariance input, or None for bare arrays.

    Parameters
    ----------
    C : array-like, pandas.DataFrame or xarray.DataArray
        Square trait covariance; DataFrame index labels or the first DataArray coordinate
        provide the trait labels used on the decomposition Dataset.
    """
    if isinstance(C, pd.DataFrame):
        return _axis_labels(C.index)
    if _is_xr_dataarray(C) and C.ndim == 2 and C.dims[0] in C.coords:
        return _axis_labels(C[C.dims[0]].values)
    return None


_DECOMPOSITION_VAR_ATTRS = {
    "loadings": ("factor loadings L", "square root of trait covariance units", "Columns are retained factors."),
    "specific_var": ("specific (unique) variance psi", "trait variance units", None),
    "lowrank": ("low-rank factor covariance L L'", "trait covariance units", None),
    "reconstructed": ("reconstructed covariance L L' + diag(psi)", "trait covariance units", None),
    "residual": ("approximation residual C - reconstructed", "trait covariance units", None),
    "eigenvalues": ("eigenvalues of the reconstructed covariance (descending)", "trait covariance units", None),
}
_DECOMPOSITION_DIMS = {"loadings": ("trait", "factor"), "specific_var": ("trait",), "lowrank": ("trait_i", "trait_j"),
                       "reconstructed": ("trait_i", "trait_j"), "residual": ("trait_i", "trait_j"),
                       "eigenvalues": ("eigen_index",)}


def _decomposition_dataset(result, arguments):
    """Convert a ``decompose_covariance`` mapping to a labeled Dataset.

    Parameters
    ----------
    result : mapping
        Historical decomposition fields: arrays become data variables (loadings on
        ('trait','factor'), matrices on ('trait_i','trait_j'), vectors on 'trait' /
        'eigen_index'); method, rank, explained fractions, success and message go to attrs.
    arguments : mapping
        Bound call arguments; ``C`` supplies trait labels and scalars become parameters.
    """
    from .results import result_dataset
    labels = _matrix_labels(arguments.get("C"))
    ds = result_dataset(result, dims=_DECOMPOSITION_DIMS, var_attrs=_var_attrs(_DECOMPOSITION_VAR_ATTRS, _DECOMPOSITION_DIMS),
                        title="Factor decomposition of a trait covariance matrix",
                        software="vigor.multivariate.decompose_covariance", parameters=_call_parameters(arguments))
    ds = ds.assign_coords(factor=[f"FA{i+1}" for i in range(ds.sizes.get("factor", 0))])
    if labels is not None and len(labels) == ds.sizes.get("trait"):
        ds = ds.assign_coords(trait=labels, trait_i=labels, trait_j=labels)
    return ds


def _decompose_GE_dataset(result, arguments):
    """Flatten the two ``decompose_GE`` decompositions into one labeled Dataset.

    Parameters
    ----------
    result : mapping
        Historical {'G': dict, 'E': dict, 'G_reconstructed', 'E_reconstructed'} output. The
        reconstructed matrices keep their names; array fields of each decomposition become
        ``<G|E>_<field>`` variables (factor dims ``factor_G``/``factor_E``) and the scalar
        fields stay in ``ds.attrs['G']``/``ds.attrs['E']``.
    arguments : mapping
        Bound call arguments; ``G``/``E`` supply trait labels and scalars become parameters.
    """
    from .results import result_dataset
    values, dims, var_attrs = {}, {}, {}
    for comp in ("G", "E"):
        dec = dict(result[comp])
        values[comp] = {k: v for k, v in dec.items() if k not in _DECOMPOSITION_DIMS}
        for field, d in _DECOMPOSITION_DIMS.items():
            if field == "reconstructed":
                continue
            name = f"{comp}_{field}"
            values[name] = dec[field]
            dims[name] = tuple(f"factor_{comp}" if x == "factor" else x for x in d)
            ln, units, desc = _DECOMPOSITION_VAR_ATTRS[field]
            var_attrs[name] = {k: v for k, v in (("long_name", f"{comp}: {ln}"), ("units", units), ("description", desc)) if v}
        values[f"{comp}_reconstructed"] = result[f"{comp}_reconstructed"]
        dims[f"{comp}_reconstructed"] = ("trait_i", "trait_j")
        var_attrs[f"{comp}_reconstructed"] = {"long_name": f"{comp}: reconstructed covariance L L' + diag(psi)",
                                              "units": "trait covariance units"}
    ds = result_dataset(values, dims=dims, var_attrs=var_attrs, title="Factor decompositions of genetic and residual covariances",
                        software="vigor.multivariate.decompose_GE", parameters=_call_parameters(arguments))
    ds = ds.assign_coords({f"factor_{c}": [f"{c}_FA{i+1}" for i in range(ds.sizes.get(f"factor_{c}", 0))] for c in ("G", "E")})
    labels = _matrix_labels(arguments.get("G"))
    if labels is None:
        labels = _matrix_labels(arguments.get("E"))
    if labels is not None and len(labels) == ds.sizes.get("trait"):
        ds = ds.assign_coords(trait=labels, trait_i=labels, trait_j=labels)
    return ds


@_dataset_result(_decomposition_dataset)
def decompose_covariance(C, rank=None, method='fa', *, standardize=False, preserve_diag=True, jitter=1e-08, maxiter=1000, tol=1e-08, save_path=None):
    """Approximate a trait covariance by factors and optional diagonal-specific variance.

    Parameters
    ----------
    C : square array-like or pandas.DataFrame
        Finite trait × trait covariance to approximate. Labels, when present, identify trait
        order. method=fa assigns unmodeled variance to a specific diagonal; PCA uses
        eigenfactors. The input need not already have the requested factor rank.

    rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value.

    method : str
        'fa'/'factor'/'factor_analytic' optimizes a factor-plus-specific-diagonal approximation;
        'pca'/'eigen'/'eig'/'svd' takes eigenfactors; see the local branch for supported
        spellings. Other spellings raise ValueError rather than invoking a generic estimator.
        Default: ``'fa'``. Additional source aliases/choices: ``factor_analysis``, ``spectral``.
        See the local dispatcher for their mapping.

    standardize : bool
        Whether to enable the named graph-model transformation, deterministic tracking or
        constraint. True follows its explicit construction branch; False omits it. See that
        branch for how model dimensions/priors are affected. Default: ``False``.

    preserve_diag : bool
        Whether the approximation preserves each input marginal variance by assigning remaining
        variance to the specific diagonal. Default: ``True``.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_cov_to_corr`` as ``eps``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``1000``. Passed to ``minimize`` as ``options``.

    tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-08``. Passed to ``minimize`` as ``options``.

    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.

    Returns
    -------
    xarray.Dataset
        Data variables: ``loadings`` ('trait','factor'), ``specific_var`` ('trait'),
        ``lowrank``/``reconstructed``/``residual`` ('trait_i','trait_j') and ``eigenvalues``
        ('eigen_index'), labeled by the input trait labels when C is labeled. Attributes:
        ``method``, ``rank``, ``explained_trace``, ``explained_fro``, ``success``, ``message``
        plus title/software/parameters provenance.
    """
    C = _symmetrize(np.asarray(C, dtype=float))
    p = C.shape[0]
    if C.shape != (p, p):
        raise ValueError('C must be square')
    rank = p if rank is None else int(rank)
    rank = max(1, min(rank, p))
    method = method.lower()
    if method in {'factor', 'factor_analysis'}:
        method = 'fa'
    if method in {'spectral', 'pca'}:
        method = 'eigen'
    if method not in {'fa', 'eigen'}:
        raise ValueError("method must be one of {'fa','eigen','spectral','pca','factor','factor_analysis'}")
    if standardize:
        C_work, scale = _cov_to_corr(C, eps=jitter)
    else:
        C_work = C.copy()
        scale = None
    C_work = _project_psd(C_work, eps=jitter)
    if method == 'eigen':
        w, V = np.linalg.eigh(C_work)
        idx = np.argsort(w)[::-1]
        w = w[idx]
        V = V[:, idx]
        w_r = np.clip(w[:rank], 0.0, None)
        L = V[:, :rank] * np.sqrt(w_r)[None, :]
        lowrank = L @ L.T
        if preserve_diag:
            psi = np.clip(np.diag(C_work - lowrank), 0.0, None)
        else:
            psi = np.zeros(p, dtype=float)
        recon = _symmetrize(lowrank + np.diag(psi))
        success = True
        message = 'eigen decomposition'
    else:
        w0, V0 = np.linalg.eigh(C_work)
        idx = np.argsort(w0)[::-1]
        w0 = w0[idx]
        V0 = V0[:, idx]
        w_r = np.clip(w0[:rank], 0.0, None)
        L0 = V0[:, :rank] * np.sqrt(w_r)[None, :]
        psi0 = np.clip(np.diag(C_work - L0 @ L0.T), jitter, None)
        x0 = np.concatenate([L0.ravel(), np.log(psi0)])

        def unpack(x):
            """Unpack optimizer coordinates into the enclosing matrix parameterization.

            Parameters
            ----------
            x : one-dimensional numpy.ndarray
                Flattened optimization coordinates in the parameter layout captured by this closure.
                Length and factor/path slice order must match that layout; the objective unpacks these
                entries before evaluation.

            Returns
            -------
            object
                Computed result from ``(L, psi)``; see the summary and the called implementation for its labeled/numerical representation.
            """
            L = x[:p * rank].reshape(p, rank)
            psi = np.exp(x[p * rank:])
            return (L, psi)

        def objective_and_grad(x):
            """Evaluate the constrained covariance objective and its analytical gradient together.

            Parameters
            ----------
            x : array-like
                Numerical operand in ``unpack(x)``. Shape must conform to that matrix/vector operation
                and the enclosing prepared state.

            Returns
            -------
            object
                Computed result from ``(float(f), g)``; see the summary and the called implementation for its labeled/numerical representation.
            """
            L, psi = unpack(x)
            M = L @ L.T + np.diag(psi) - C_work
            M = _symmetrize(M)
            f = 0.5 * np.sum(M * M)
            grad_L = 2.0 * M @ L
            grad_logpsi = np.diag(M) * psi
            g = np.concatenate([grad_L.ravel(), grad_logpsi])
            return (float(f), g)
        res = minimize(objective_and_grad, x0=x0, jac=True, method='L-BFGS-B', options={'maxiter': maxiter, 'ftol': tol, 'gtol': tol})
        L, psi = unpack(res.x)
        psi = np.clip(psi, jitter, None)
        lowrank = L @ L.T
        recon = _symmetrize(lowrank + np.diag(psi))
        success = bool(res.success)
        message = str(res.message)
    if standardize:
        L = scale[:, None] * L
        psi = scale ** 2 * psi
        lowrank = L @ L.T
        recon = _symmetrize(lowrank + np.diag(psi))
    residual = _symmetrize(C - recon)
    tr_total = np.trace(C)
    tr_lowrank = np.trace(lowrank)
    explained_trace = tr_lowrank / tr_total if tr_total > 0 else np.nan
    fro_total = np.sum(C * C)
    fro_resid = np.sum(residual * residual)
    explained_fro = 1.0 - fro_resid / fro_total if fro_total > 0 else np.nan
    eigvals_fit = np.linalg.eigvalsh(recon)
    eigvals_fit = np.sort(eigvals_fit)[::-1]
    return {'method': method, 'rank': rank, 'loadings': L, 'specific_var': psi, 'lowrank': _symmetrize(lowrank), 'reconstructed': recon, 'residual': residual, 'explained_trace': explained_trace, 'explained_fro': explained_fro, 'success': success, 'message': message, 'eigenvalues': eigvals_fit}

@_dataset_result(_decompose_GE_dataset)
def decompose_GE(G, E, rank_G=None, rank_E=None, method_G='fa', method_E='fa', *, standardize=False, preserve_diag=True, jitter=1e-08, maxiter=1000, tol=1e-08, save_path=None):
    """Decompose genetic and residual covariance separately using their requested factor ranks.

    Parameters
    ----------
    G : square array-like, pandas.DataFrame or xarray.DataArray
        Genetic trait covariance to decompose (for example ``fit['G']``); labels, when present,
        become the trait coordinates of the result.

    E : square array-like, pandas.DataFrame or xarray.DataArray
        Residual trait covariance to decompose, in the same trait order as G.

    rank_G : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value.

    rank_E : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value.

    method_G : str
        Covariance decomposition method: 'fa' fits a factor-analytic decomposition and
        'pca'/'eigen' uses spectral factors where supported; 'native' reuses fitted factors only
        in factorGWAS. See decompose_covariance or the selected factor helper for its accepted
        aliases. Default: ``'fa'``. Passed to ``decompose_covariance`` as ``method``.

    method_E : str
        Covariance decomposition method: 'fa' fits a factor-analytic decomposition and
        'pca'/'eigen' uses spectral factors where supported; 'native' reuses fitted factors only
        in factorGWAS. See decompose_covariance or the selected factor helper for its accepted
        aliases. Default: ``'fa'``. Passed to ``decompose_covariance`` as ``method``.

    standardize : bool
        Whether to enable the named graph-model transformation, deterministic tracking or
        constraint. True follows its explicit construction branch; False omits it. See that
        branch for how model dimensions/priors are affected. Default: ``False``. Passed to
        ``decompose_covariance`` as ``standardize``.

    preserve_diag : bool
        Whether the approximation preserves each input marginal variance by assigning remaining
        variance to the specific diagonal. Default: ``True``. Passed to ``decompose_covariance``
        as ``preserve_diag``.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``decompose_covariance`` as
        ``jitter``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``1000``. Passed to ``decompose_covariance`` as ``maxiter``.

    tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-08``. Passed to ``decompose_covariance`` as ``tol``.

    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.

    Returns
    -------
    xarray.Dataset
        Data variables ``G_reconstructed``/``E_reconstructed`` ('trait_i','trait_j') and, per
        component c in G/E, ``c_loadings`` ('trait','factor_c'), ``c_specific_var`` ('trait'),
        ``c_lowrank``/``c_residual`` ('trait_i','trait_j') and ``c_eigenvalues``
        ('eigen_index'). Attributes ``G``/``E`` hold each decomposition's scalar fields
        (method, rank, explained_trace, explained_fro, success, message).
    """
    dec_G = decompose_covariance.__wrapped__(G, rank=rank_G, method=method_G, standardize=standardize, preserve_diag=preserve_diag, jitter=jitter, maxiter=maxiter, tol=tol)
    dec_E = decompose_covariance.__wrapped__(E, rank=rank_E, method=method_E, standardize=standardize, preserve_diag=preserve_diag, jitter=jitter, maxiter=maxiter, tol=tol)
    return {'G': dec_G, 'E': dec_E, 'G_reconstructed': dec_G['reconstructed'], 'E_reconstructed': dec_E['reconstructed']}

def _prepare_traits(traits: pd.DataFrame, dtype=np.float64):
    """Coerce phenotype values and construct finite-observation masks and centered responses.

    Parameters
    ----------
    traits : pd.DataFrame
        pd.DataFrame Accepted as provided to the function.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``traits.to_numpy`` as
        ``dtype``.
    """
    Y = traits.to_numpy(dtype=dtype, copy=True)
    obs = np.isfinite(Y)
    n_obs = obs.sum(axis=0, keepdims=True)
    if np.any(n_obs == 0):
        bad = list(traits.columns[n_obs.ravel() == 0])
        raise ValueError(f'Traits with all values missing: {bad}')
    mu = np.divide(np.nansum(Y, axis=0, keepdims=True), n_obs, out=np.zeros((1, Y.shape[1]), dtype=dtype), where=n_obs > 0)
    Y -= mu
    Y[~obs] = 0.0
    Y0 = np.asarray(Y, dtype=dtype, order='C')
    R = np.asarray(obs, dtype=dtype, order='C')
    return (Y0, R)

def _pack_lower(M):
    """Flatten the lower triangle of a symmetric matrix in NumPy triangular-index order.

    Parameters
    ----------
    M : object (see the cited input contract)
        Numerical operand in ``M.shape[0]``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.
    """
    tri = np.tril_indices(M.shape[0])
    return M[tri]

def _unpack_lower(v, T, dtype=np.float64):
    """Reconstruct a symmetric matrix from its packed lower-triangle entries.

    Parameters
    ----------
    v : object (see the cited input contract)
        Any Accepted as provided to the function.

    T : array-like or numeric scalar
        Any Accepted as provided to the function.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``np.zeros`` as ``dtype``.
    """
    tri = np.tril_indices(T)
    M = np.zeros((T, T), dtype=dtype)
    M[tri] = v
    M = M + np.tril(M, -1).T
    return M

def _pack_symmetric_grad(G):
    """Pack a symmetric-matrix gradient with off-diagonal contributions combined.

    Parameters
    ----------
    G : object (see the cited input contract)
        Any Accepted as provided to the function.
    """
    tri = np.tril_indices(G.shape[0])
    out = G[tri].copy()
    offdiag = tri[0] > tri[1]
    out[offdiag] *= 2.0
    return out

def _psd_factor_from_sym(A, rank=None, eps=1e-12):
    """Extract a rank-limited square-root factor of a symmetric positive-semidefinite matrix.

    Parameters
    ----------
    A : array-like or numeric scalar
        Numerical input passed to ``np.zeros`` as ``dtype``; see that callable for required
        dimensions and matrix role.

    rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.
    """
    A = _symmetrize(np.asarray(A))
    w, V = np.linalg.eigh(A)
    w[w < 0] = 0.0
    idx = np.argsort(w)[::-1]
    w = w[idx]
    V = V[:, idx]
    keep = w > eps
    w = w[keep]
    V = V[:, keep]
    T = A.shape[0]
    if rank is None:
        rank = T
    rank = min(rank, T)
    if w.size == 0:
        return np.zeros((T, rank), dtype=A.dtype)
    w = w[:rank]
    V = V[:, :rank]
    F = V * np.sqrt(w)[None, :]
    if F.shape[1] < rank:
        pad = np.zeros((T, rank - F.shape[1]), dtype=A.dtype)
        F = np.hstack([F, pad])
    return F

def _rg_from_G_pairwise(G, eps=1e-12, dtype=np.float64):
    """Compute genetic correlations only for trait pairs with valid positive genetic variances.

    Parameters
    ----------
    G : array-like or numeric scalar
        Any Accepted as provided to the function.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``np.full_like`` as ``dtype``.
    """
    vg = np.diag(G).astype(dtype, copy=True)
    valid_vg = np.isfinite(vg) & (vg > eps)
    sdg = np.full_like(vg, np.nan, dtype=dtype)
    sdg[valid_vg] = np.sqrt(vg[valid_vg])
    scale = sdg[:, None] * sdg[None, :]
    Rg = np.divide(G, scale, out=np.full_like(G, np.nan, dtype=dtype), where=np.isfinite(scale) & (scale > 0))
    Rg[np.diag_indices_from(Rg)] = np.where(valid_vg, 1.0, np.nan)
    return (Rg, vg, valid_vg)

def _rg_from_G_psd(G, eps=1e-12, dtype=np.float64):
    """Compute genetic correlations with the covariance estimator's positive-variance boundary convention.

    Parameters
    ----------
    G : array-like or numeric scalar
        Any Accepted as provided to the function.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``np.full_like`` as ``dtype``.
    """
    vg = np.diag(G).astype(dtype, copy=True)
    vg = np.where(np.isfinite(vg), vg, np.nan)
    vg_clip = np.clip(vg, 0.0, None)
    sdg = np.full_like(vg_clip, np.nan, dtype=dtype)
    finite = np.isfinite(vg_clip)
    sdg[finite] = np.sqrt(vg_clip[finite])
    scale = sdg[:, None] * sdg[None, :]
    Rg = np.divide(G, scale, out=np.full_like(G, np.nan, dtype=dtype), where=np.isfinite(scale) & (scale > 0))
    valid_vg = np.isfinite(vg) & (vg_clip > eps)
    Rg[np.diag_indices_from(Rg)] = np.where(valid_vg, 1.0, np.nan)
    return (Rg, vg, valid_vg)

def _nanstd_stack(arrays):
    """Compute elementwise standard deviations across replicate arrays while ignoring NaN draws.

    Parameters
    ----------
    arrays : object (see the cited input contract)
        Any Accepted as provided to the function.
    """
    if len(arrays) == 0:
        return None
    X = np.stack(arrays, axis=0).astype(np.float64, copy=False)
    valid = np.isfinite(X)
    n = valid.sum(axis=0)
    mean = np.divide(np.nansum(X, axis=0), n, out=np.full(X.shape[1:], np.nan, dtype=np.float64), where=n > 0)
    sq = np.where(valid, (X - mean) ** 2, 0.0)
    var = np.divide(sq.sum(axis=0), n - 1, out=np.full(X.shape[1:], np.nan, dtype=np.float64), where=n > 1)
    return np.sqrt(var)


