def grm_moment_matrices_einsum(grm, traits: pd.DataFrame, *, mode='auto', block_size=1024, block_dtype=np.float32, accum_dtype=np.float64, square_dtype=None, dense_threshold_gb=4.0):
    """Select dense or blockwise exact pairwise-observed covariance moment accumulation.

    Parameters
    ----------
    grm : object (see the cited input contract)
        Any Accepted as provided to the function.

    traits : pd.DataFrame
        pd.DataFrame Accepted as provided to the function.

    mode : str
        Any allowed values: 'auto', 'blocked', 'dense'; default='auto'. Default: ``'auto'``.

    block_size : int
        Number of variants or rows processed together by the local block iterator. Supply a
        positive count; smaller blocks reduce peak memory at the cost of more iteration
        overhead. See the called iterator for which axis is blocked. Default: ``1024``. Passed
        to ``grm_moment_matrices_einsum_blocked`` as ``block_size``.

    block_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float32``. Passed to
        ``grm_moment_matrices_einsum_blocked`` as ``block_dtype``.

    accum_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to
        ``grm_moment_matrices_einsum_dense`` as ``accum_dtype``.

    square_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``grm_moment_matrices_einsum_dense`` as ``square_dtype``.

    dense_threshold_gb : float
        Estimated dense-working-memory cutoff in GiB for automatic moment mode selection;
        positive values permit the dense path below this bound. Default: ``4.0``.

    Returns
    -------
    object
        Computed result from ``grm_moment_matrices_einsum_blocked(grm, traits, block_size=block_size, block_dtype=block_dtype, accum_dtype=accum_dtype)``; see the summary and the called implementation for its labeled/numerical representation.
    """
    grm = np.asarray(grm)
    n = grm.shape[0]
    if mode not in {'auto', 'dense', 'blocked'}:
        raise ValueError("mode must be 'auto', 'dense', or 'blocked'")
    if mode == 'auto':
        sdtype = accum_dtype if square_dtype is None else square_dtype
        est_gb = n * n * np.dtype(sdtype).itemsize / 1024 ** 3
        mode = 'dense' if est_gb <= dense_threshold_gb else 'blocked'
    if mode == 'dense':
        return grm_moment_matrices_einsum_dense(grm, traits, accum_dtype=accum_dtype, square_dtype=square_dtype)
    return grm_moment_matrices_einsum_blocked(grm, traits, block_size=block_size, block_dtype=block_dtype, accum_dtype=accum_dtype)

def _bootstrap_standard_errors(fit_func, grm, traits, *, n_boot=100, random_state=None):
    """Bootstrap standard errors.

    Parameters
    ----------
    fit_func : object (see the cited input contract)
        Any Accepted as provided to the function.

    grm : array-like or numeric scalar
        Any Accepted as provided to the function.

    traits : object (see the cited input contract)
        Any Accepted as provided to the function.

    n_boot : int
        Number of bootstrap replicates. Zero disables bootstrap when supported; positive counts
        estimate sampling variation by the resampling scheme used here. Default: ``100``. Source
        comparisons: ``n_boot <= 0``. See the rejection/fallback branches for enforcement.
        Passed to ``tqdm`` as ``total``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``None``.
    """
    if n_boot <= 0:
        return {'G_se': None, 'E_se': None, 'rg_se': None, 'n_boot': 0, 'n_boot_success': 0}
    rng = np.random.default_rng(random_state)
    n = len(traits)
    G_samples = []
    E_samples = []
    Rg_samples = []
    for _ in tqdm(range(n_boot), desc='bootstrapping', total=n_boot):
        idx = rng.integers(0, n, size=n)
        grm_b = np.asarray(grm)[np.ix_(idx, idx)]
        traits_b = traits.iloc[idx].reset_index(drop=True)
        try:
            out_b = fit_func(grm_b, traits_b)
            G_b = np.asarray(out_b['G'], dtype=np.float64)
            E_b = np.asarray(out_b['E'], dtype=np.float64)
            Rg_b = np.asarray(out_b['Rg'], dtype=np.float64)
            G_samples.append(G_b)
            E_samples.append(E_b)
            Rg_samples.append(Rg_b)
        except Exception:
            continue
    return {'G_se': _nanstd_stack(G_samples), 'E_se': _nanstd_stack(E_samples), 'rg_se': _nanstd_stack(Rg_samples), 'n_boot': int(n_boot), 'n_boot_success': int(len(G_samples))}

def score_grm_pairwise_einsum(grm, traits: pd.DataFrame, *, mode='auto', block_size=1024, block_dtype=np.float32, accum_dtype=np.float64, square_dtype=None, dense_threshold_gb=4.0, eps=1e-12, n_boot=0, random_state=None):
    """Estimate unconstrained genetic/residual covariance from pairwise-observed GRM moments.

    Parameters
    ----------
    grm : array-like or numeric scalar
        Any Accepted as provided to the function.

    traits : pd.DataFrame
        pd.DataFrame Accepted as provided to the function.

    mode : str
        Input supplied to ``grm_moment_matrices_einsum`` as ``mode``. See that callable's
        documented ``mode`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Default: ``'auto'``.

    block_size : int
        Number of variants or rows processed together by the local block iterator. Supply a
        positive count; smaller blocks reduce peak memory at the cost of more iteration
        overhead. See the called iterator for which axis is blocked. Default: ``1024``. Passed
        to ``grm_moment_matrices_einsum`` as ``block_size``.

    block_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float32``. Passed to ``grm_moment_matrices_einsum``
        as ``block_dtype``.

    accum_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``grm_moment_matrices_einsum``
        as ``accum_dtype``.

    square_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``grm_moment_matrices_einsum`` as ``square_dtype``.

    dense_threshold_gb : float
        Estimated dense-working-memory cutoff in GiB for automatic moment mode selection;
        positive values permit the dense path below this bound. Default: ``4.0``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``_rg_from_G_pairwise`` as ``eps``.

    n_boot : int
        Number of bootstrap replicates. Zero disables bootstrap when supported; positive counts
        estimate sampling variation by the resampling scheme used here. Default: ``0``. Source
        comparisons: ``n_boot > 0``. See the rejection/fallback branches for enforcement. Passed
        to ``_bootstrap_standard_errors`` as ``n_boot``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``None``. Passed
        to ``_bootstrap_standard_errors`` as ``random_state``.

    Returns
    -------
    object
        Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
    """
    mom = grm_moment_matrices_einsum(grm, traits, mode=mode, block_size=block_size, block_dtype=block_dtype, accum_dtype=accum_dtype, square_dtype=square_dtype, dense_threshold_gb=dense_threshold_gb)
    A11, A12, A22 = (mom['A11'], mom['A12'], mom['A22'])
    B1, B2 = (mom['B1'], mom['B2'])
    den = A11 * A22 - A12 * A12
    G = np.full_like(B1, np.nan, dtype=accum_dtype)
    E = np.full_like(B2, np.nan, dtype=accum_dtype)
    ok = np.abs(den) > eps
    G[ok] = (B1[ok] * A22[ok] - B2[ok] * A12[ok]) / den[ok]
    E[ok] = (A11[ok] * B2[ok] - A12[ok] * B1[ok]) / den[ok]
    no_overlap = (A22 <= eps) & (np.abs(A12) <= eps) & (A11 > eps)
    G[no_overlap] = B1[no_overlap] / A11[no_overlap]
    E[no_overlap] = 0.0
    G = _symmetrize(G)
    E = _symmetrize(E)
    Rg, vg, valid_vg = _rg_from_G_pairwise(G, eps=eps, dtype=accum_dtype)
    out = {'G': G, 'E': E, 'Rg': Rg, 'vg': vg, 'valid_vg': valid_vg, 'invalid_var_mask': ~valid_vg, 'n_invalid_variances': int((~valid_vg).sum()), 'invalid_traits': list(traits.columns[~valid_vg]), 'G_se': None, 'E_se': None, 'rg_se': None, 'n_boot': 0, 'n_boot_success': 0, **mom}
    if n_boot > 0:
        boot = _bootstrap_standard_errors(lambda Kb, Tb: score_grm_pairwise_einsum(Kb, Tb, mode=mode, block_size=block_size, block_dtype=block_dtype, accum_dtype=accum_dtype, square_dtype=square_dtype, dense_threshold_gb=dense_threshold_gb, eps=eps, n_boot=0), grm, traits, n_boot=n_boot, random_state=random_state)
        out.update(boot)
    return out

def _gdec314_covariance(grm, traits: pd.DataFrame, *, mode='auto', block_size=1024, block_dtype=np.float32, accum_dtype=np.float64, square_dtype=None, dense_threshold_gb=4.0, rank_G=None, rank_E=None, psd_E=True, ridge_G=0.0, ridge_E=0.0, method='L-BFGS-B', maxiter=1000, gtol=1e-08, ftol=1e-12, init='pairwise', eps=1e-12, n_boot=0, random_state=None, shrink_G="auto", shrink_E="auto", E_structure="auto", min_E_pair_overlap=2, blas_threads="auto"):
    """Fit the pinned single-kernel GDEC 3.1.4 covariance profile.

    Parameters
    ----------
    grm : array-like, shape (n, n)
        Dense animal relationship matrix in phenotype row order.
    traits : pandas.DataFrame, shape (n, t)
        Numeric traits, with NaN for unobserved cells.
    mode : {'auto', 'dense', 'blocked'}
        Moment accumulation route; block_size/block_dtype/accum_dtype and
        dense_threshold_gb control its memory and arithmetic precision.
    rank_G, rank_E : int or None
        Factor ranks in [1, t]; None uses full rank. This compatibility profile
        has no trait-specific FA diagonal and is separate from the modern fit.
    psd_E : bool
        Constrain residual covariance to PSD when True.
    ridge_G, ridge_E : float
        Nonnegative quadratic penalties. method/maxiter/gtol/ftol select the
        scipy optimizer and its stopping rules; init is 'pairwise' or 'zero'.
    shrink_G, shrink_E : float or {'auto'}
        Off-diagonal retention; auto reproduces sample-size/overlap retention.
    E_structure : {'auto', 'full', 'diag'}
        Pinned residual overlap policy, with min_E_pair_overlap as support.
    eps : float
        Positive numerical floor. square_dtype is passed to moment accumulation.
    n_boot : int
        Must be zero; compatibility bootstrap parity is not established.
    random_state : int or None
        Reserved compatibility seed; unused with n_boot=0.
    blas_threads : int or {'auto'}
        BLAS thread context used for the retained optimization.

    Returns
    -------
    pandas.Series
        Covariance matrices G/E, Rg, variance validity masks, optimizer status,
        shrinkage policy and component specifications. The compatibility
        decorator supplies provenance; this is not GDEC 3.1.3.

    Complexity
    ----------
    Dense moments O(n²t+nt²) time/O(n²+nt+t²) space; blocked accumulation
    avoids a second n² work matrix. Each optimizer iteration costs O(t³) at
    full rank, or O(t²r), and stores O(t²+tr) values.
    """
    if int(n_boot) != 0:
        raise NotImplementedError("gdec314 compatibility requires n_boot=0")
    if rank_G == "auto": rank_G = _v31_auto_trait_rank(traits.shape[1])
    if rank_E == "auto": rank_E = _v31_auto_trait_rank(traits.shape[1])
    n_traits = len(traits.columns)
    pw = score_grm_pairwise_einsum(grm, traits, mode=mode, block_size=block_size, block_dtype=block_dtype, accum_dtype=accum_dtype, square_dtype=square_dtype, dense_threshold_gb=dense_threshold_gb, eps=eps, n_boot=0)
    A11, A12, A22 = (pw['A11'], pw['A12'], pw['A22'])
    B1, B2 = (pw['B1'], pw['B2'])
    T = A11.shape[0]
    if rank_G is None:
        rank_G = T
    if rank_E is None:
        rank_E = T
    if init == 'pairwise':
        G0 = np.nan_to_num(pw['G'], nan=0.0)
        E0 = np.nan_to_num(pw['E'], nan=0.0)
    elif init == 'zero':
        G0 = np.zeros((T, T), dtype=accum_dtype)
        E0 = np.zeros((T, T), dtype=accum_dtype)
    else:
        raise ValueError("init must be 'pairwise' or 'zero'")
    Fg0 = _psd_factor_from_sym(G0, rank=rank_G)
    if psd_E:
        Fe0 = _psd_factor_from_sym(E0, rank=rank_E)
        x0 = np.concatenate([Fg0.ravel(), Fe0.ravel()])
    else:
        E0 = _symmetrize(E0)
        x0 = np.concatenate([Fg0.ravel(), _pack_lower(E0)])
    nFg = T * rank_G

    def unpack(x):
        """Unpack optimizer coordinates into the enclosing matrix parameterization.

        Parameters
        ----------
        x : one-dimensional numpy.ndarray
            Flattened optimization coordinates in the parameter layout captured by this closure.
            Length and factor/path slice order must match that layout; the objective unpacks these
            entries before evaluation.

        Returns
        -------
        object
            Computed result from ``(Fg, G, E, None)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Fg = x[:nFg].reshape(T, rank_G)
        G = _symmetrize(Fg @ Fg.T)
        if psd_E:
            Fe = x[nFg:].reshape(T, rank_E)
            E = _symmetrize(Fe @ Fe.T)
            return (Fg, G, E, Fe)
        E = _symmetrize(_unpack_lower(x[nFg:], T, dtype=accum_dtype))
        return (Fg, G, E, None)

    def objective_and_grad(x):
        """Evaluate the constrained covariance objective and its analytical gradient together.

        Parameters
        ----------
        x : array-like
            Numerical operand in ``unpack(x)``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``(float(f), grad)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Fg, G, E, Fe = unpack(x)
        MG = _symmetrize(A11 * G + A12 * E - B1 + ridge_G * G)
        ME = _symmetrize(A22 * E + A12 * G - B2 + ridge_E * E)
        f = np.sum(A11 * (G * G)) + 2.0 * np.sum(A12 * (G * E)) + np.sum(A22 * (E * E)) - 2.0 * np.sum(B1 * G) - 2.0 * np.sum(B2 * E) + ridge_G * np.sum(G * G) + ridge_E * np.sum(E * E)
        grad_Fg = 4.0 * (MG @ Fg)
        if psd_E:
            grad_Fe = 4.0 * (ME @ Fe)
            grad = np.concatenate([grad_Fg.ravel(), grad_Fe.ravel()])
        else:
            grad_E = _pack_symmetric_grad(2.0 * ME)
            grad = np.concatenate([grad_Fg.ravel(), grad_E])
        return (float(f), grad)
    options = {'maxiter': maxiter}
    if method.upper() in {'L-BFGS-B', 'BFGS', 'CG'}:
        options['gtol'] = gtol
    if method.upper() in {'L-BFGS-B', 'TNC', 'SLSQP'}:
        options['ftol'] = ftol
    with _v31_thread_ctx(blas_threads, 'cov'):
        res = minimize(objective_and_grad, x0=x0, jac=True, method=method, options=options)
    success = bool(res.success)
    message = str(res.message)
    if np.any(~np.isfinite(res.x)):
        success = False
        message = f'{message}; non-finite optimizer parameters returned'
    try:
        _, G, E, _ = unpack(res.x)
    except Exception as exc:
        G = np.full((T, T), np.nan, dtype=accum_dtype)
        E = np.full((T, T), np.nan, dtype=accum_dtype)
        success = False
        message = f'{message}; unpack failed: {exc}'
    if np.any(~np.isfinite(G)):
        success = False
        message = f'{message}; estimated G contains non-finite values'
    if np.any(~np.isfinite(E)):
        success = False
        message = f'{message}; estimated E contains non-finite values'
    Rg, vg, valid_vg = _rg_from_G_psd(G, eps=eps, dtype=accum_dtype)
    out = pd.Series({'G': pd.DataFrame(G, columns=traits.columns, index=traits.columns), 
                     'E': pd.DataFrame(E, columns=traits.columns, index=traits.columns), 
                     'Rg': pd.DataFrame(Rg, columns=traits.columns, index=traits.columns), 
                     'vg': pd.Series(data=vg, index=traits.columns), 
                     'valid_vg': valid_vg, 'invalid_var_mask': ~valid_vg, 
                     'n_invalid_variances': int((~valid_vg).sum()), 
                     'invalid_traits': list(traits.columns[~valid_vg]), 
                     'G_se': pd.DataFrame(np.full((n_traits, n_traits), np.nan), columns=traits.columns, index=traits.columns), 
                     'E_se': pd.DataFrame(np.full((n_traits, n_traits), np.nan), columns=traits.columns, index=traits.columns), 
                     'rg_se': pd.DataFrame(np.full((n_traits, n_traits), np.nan), columns=traits.columns, index=traits.columns), 
                     'n_boot': 0, 'n_boot_success': 0, 'result': res, 'success': success, 'message': message, 
                     'nit': getattr(res, 'nit', None), 'fun': getattr(res, 'fun', np.nan), 'rank_G': rank_G, 
                     'rank_E': rank_E if psd_E else None, 'psd_E': psd_E, 'ridge_G': ridge_G, 'ridge_E': ridge_E})
    G0, E0 = out['G'].to_numpy(dtype=float), out['E'].to_numpy(dtype=float)
    overlap = traits.notna().astype(np.int32).T @ traits.notna().astype(np.int32)
    nobs = traits.notna().sum(axis=0).to_numpy(float); iu = np.triu_indices(len(nobs), 1); ov = overlap.to_numpy(dtype=float)
    alpha_G = float(np.median(nobs)/(np.median(nobs)+50.0)) if isinstance(shrink_G,str) and shrink_G.lower()=='auto' else float(shrink_G)
    med_overlap = float(np.median(ov[iu])) if len(iu[0]) else float(np.median(nobs))
    alpha_E = float(med_overlap/(med_overlap+400.0)) if isinstance(shrink_E,str) and shrink_E.lower()=='auto' else float(shrink_E)
    G1, E1 = _shrink_covariance_offdiag(G0, alpha_G), _shrink_covariance_offdiag(E0, alpha_E)
    E_mode = str(E_structure).lower()
    if E_mode == 'diag': E1 = np.diag(np.diag(E1)); E_resolved = 'diag'
    elif E_mode == 'auto':
        ov = overlap.to_numpy(); iu = np.triu_indices_from(ov, 1); zero_fraction = float(np.mean(ov[iu] < int(min_E_pair_overlap))) if len(iu[0]) else 0.0
        if zero_fraction >= 0.5:
            E1 = np.diag(np.diag(E1)); E_resolved = 'diag_sparse_overlap'
        else:
            keep = ov >= int(min_E_pair_overlap); np.fill_diagonal(keep, True); E1 = np.where(keep, E1, 0.0); E1 = _project_psd(E1, eps=max(eps,1e-10)); E_resolved = 'supported_full'
    elif E_mode == 'full': E_resolved = 'full'
    else: raise ValueError("E_structure must be 'full', 'diag', or 'auto'")
    cols = traits.columns; Rg, vg, valid = _rg_from_G_psd(G1, eps=eps)
    out['G'] = pd.DataFrame(G1,index=cols,columns=cols); out['E'] = pd.DataFrame(E1,index=cols,columns=cols)
    out['Rg'] = pd.DataFrame(Rg,index=cols,columns=cols); out['vg'] = pd.Series(vg,index=cols); out['valid_vg']=valid
    out['invalid_var_mask']=~valid; out['n_invalid_variances']=int((~valid).sum()); out['invalid_traits']=list(cols[~valid])
    out['shrink_G']=alpha_G; out['shrink_E']=alpha_E; out['shrink_G_requested']=shrink_G; out['shrink_E_requested']=shrink_E; out['E_structure']=E_mode; out['E_structure_resolved']=E_resolved; out['E_pair_overlap']=overlap
    out["version"] = V3_1_FINAL_VERSION
    return _v31_attach_single_specs(out, traits)


# Preserve the release-overlay binding for adapters defined below.

def _symmetrize(M):
    """Return the arithmetic symmetrization of a square matrix.

    Parameters
    ----------
    M : object (see the cited input contract)
        Numerical operand in ``0.5 * (M + M.T)``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.
    """
    return 0.5 * (M + M.T)

def _solve_spd(A, b, jitter=1e-08, max_tries=6):
    """Solve a positive-definite linear system, increasing diagonal jitter on failed factorizations.

    Parameters
    ----------
    A : array-like or numeric scalar
        Numerical input passed to ``np.eye`` as ``dtype``; see that callable for required
        dimensions and matrix role.

    b : array-like or numeric scalar
        Numerical operand in ``np.linalg.pinv(A) @ b``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``.

    max_tries : int
        Input for the operation ``range(max_tries)``. See ``vigor.multivariate._solve_spd`` and
        its caller for the scientific representation; the shown operation constrains the
        required type/shape. Default: ``6``.
    """
    A = _symmetrize(np.asarray(A, dtype=float))
    b = np.asarray(b, dtype=float)
    eye = np.eye(A.shape[0], dtype=A.dtype)
    cur_jitter = float(jitter)
    for _ in range(max_tries):
        try:
            c, lower = cho_factor(A + cur_jitter * eye, lower=True, check_finite=False)
            return cho_solve((c, lower), b, check_finite=False)
        except np.linalg.LinAlgError:
            cur_jitter *= 10.0
    return np.linalg.pinv(A) @ b

def _diag_cov(M):
    """Extract marginal variances from a covariance representation.

    Parameters
    ----------
    M : array-like or numeric scalar
        Numerical operand in ``np.diag(np.diag(M))``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.
    """
    M = np.asarray(M)
    return np.diag(np.diag(M))

def _normalize_grm_spec(spec, n=None, dtype=np.float64):
    """Normalize dense, diagonal or eigenfactor animal-kernel inputs into a common specification.

    Parameters
    ----------
    spec : object (see the cited input contract)
        Any Accepted as provided to the function. Source-recognized literal values: ``eigh``,
        ``full``. These select the corresponding branches below; comparison evidence alone does
        not establish an exhaustive enum.

    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit. Default: ``None``. None delegates to the
        local fallback shown in this body; it is not an additional numeric/category value.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``.
    """
    if isinstance(spec, dict):
        typ = spec['type'].lower()
        if typ == 'eigh':
            lam = np.asarray(spec['values'], dtype=dtype).reshape(-1)
            Q = np.asarray(spec['vectors'], dtype=dtype)
            if Q.shape[0] != Q.shape[1]:
                raise ValueError('GRM eigenvectors must be square')
            if len(lam) != Q.shape[0]:
                raise ValueError('GRM eigenvalues and eigenvectors shape mismatch')
            lam = np.clip(lam, 0.0, None)
            if n is not None and Q.shape[0] != n:
                raise ValueError('GRM eigendecomposition size does not match number of animals')
            return {'type': 'eigh', 'Q': Q, 'lam': lam, 'K': None}
        if typ == 'full':
            K = _symmetrize(np.asarray(spec['matrix'], dtype=dtype))
            if K.shape[0] != K.shape[1]:
                raise ValueError('GRM must be square')
            if n is not None and K.shape[0] != n:
                raise ValueError('GRM size does not match number of animals')
            lam, Q = np.linalg.eigh(K)
            return {'type': 'full', 'Q': Q, 'lam': np.clip(lam, 0.0, None), 'K': K}
        raise ValueError(f'Unknown GRM spec type: {typ}')
    if isinstance(spec, tuple):
        typ = spec[0].lower()
        if typ == 'eigh':
            lam = np.asarray(spec[1], dtype=dtype).reshape(-1)
            Q = np.asarray(spec[2], dtype=dtype)
            if Q.shape[0] != Q.shape[1]:
                raise ValueError('GRM eigenvectors must be square')
            if len(lam) != Q.shape[0]:
                raise ValueError('GRM eigenvalues and eigenvectors shape mismatch')
            lam = np.clip(lam, 0.0, None)
            if n is not None and Q.shape[0] != n:
                raise ValueError('GRM eigendecomposition size does not match number of animals')
            return {'type': 'eigh', 'Q': Q, 'lam': lam, 'K': None}
        if typ == 'full':
            K = _symmetrize(np.asarray(spec[1], dtype=dtype))
            if K.shape[0] != K.shape[1]:
                raise ValueError('GRM must be square')
            if n is not None and K.shape[0] != n:
                raise ValueError('GRM size does not match number of animals')
            lam, Q = np.linalg.eigh(K)
            return {'type': 'full', 'Q': Q, 'lam': np.clip(lam, 0.0, None), 'K': K}
        raise ValueError(f'Unknown GRM tuple type: {typ}')
    K = _symmetrize(np.asarray(spec, dtype=dtype))
    if K.shape[0] != K.shape[1]:
        raise ValueError('GRM must be square')
    if n is not None and K.shape[0] != n:
        raise ValueError('GRM size does not match number of animals')
    lam, Q = np.linalg.eigh(K)
    return {'type': 'full', 'Q': Q, 'lam': np.clip(lam, 0.0, None), 'K': K}

def _reconstruct_grm(grm_spec, dtype=np.float64):
    """Materialize a normalized animal relationship-kernel specification.

    Parameters
    ----------
    grm_spec : object (see the cited input contract)
        Any Accepted as provided to the function.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``.
    """
    if grm_spec['K'] is not None:
        return grm_spec['K']
    Q = grm_spec['Q']
    lam = grm_spec['lam']
    return _symmetrize(Q * lam @ Q.T)

def _normalize_traitcov_spec(spec, size, dtype=np.float64, diag_only=False, allow_none=False):
    """Normalize trait covariance representations and validate the trait dimension.

    Parameters
    ----------
    spec : object (see the cited input contract)
        Any Accepted as provided to the function. Source-recognized literal values: ``diag``,
        ``eigh``, ``factor``, ``full``. These select the corresponding branches below;
        comparison evidence alone does not establish an exhaustive enum.

    size : array-like or numeric scalar
        Any Accepted as provided to the function.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``np.zeros`` as ``dtype``.

    diag_only : bool
        Whether to remove cross-trait covariance terms and use only the diagonal trait variances
        for conditioning. Default: ``False``.

    allow_none : bool
        Whether to enforce/use complete observations or include the named
        decomposition/component output. The enabled branch below defines the returned
        representation; disabling skips that optional step. Default: ``False``.
    """
    if spec is None:
        if not allow_none:
            return {'mode': 'diag', 'diag': np.zeros(size, dtype=dtype), 'loadings': None, 'full': None}
        return {'mode': 'diag', 'diag': np.zeros(size, dtype=dtype), 'loadings': None, 'full': None}
    if isinstance(spec, dict):
        typ = spec['type'].lower()
        if typ == 'diag':
            d = np.asarray(spec['diag'], dtype=dtype).reshape(-1)
            if len(d) != size:
                raise ValueError('Diagonal covariance length mismatch')
            return {'mode': 'diag', 'diag': d, 'loadings': None, 'full': None}
        if typ == 'factor':
            L = np.asarray(spec['loadings'], dtype=dtype)
            psi = np.asarray(spec.get('diag', np.zeros(size)), dtype=dtype).reshape(-1)
            if L.shape[0] != size or len(psi) != size:
                raise ValueError('Factor covariance shape mismatch')
            if diag_only:
                d = np.einsum('ij,ij->i', L, L) + psi
                return {'mode': 'diag', 'diag': d, 'loadings': None, 'full': None}
            return {'mode': 'factor', 'diag': psi, 'loadings': L, 'full': None}
        if typ == 'eigh':
            w = np.asarray(spec['values'], dtype=dtype).reshape(-1)
            Q = np.asarray(spec['vectors'], dtype=dtype)
            if Q.shape[0] != size or Q.shape[1] != len(w):
                raise ValueError('Eigh covariance shape mismatch')
            w = np.clip(w, 0.0, None)
            L = Q * np.sqrt(w)[None, :]
            if diag_only:
                d = np.einsum('ij,ij->i', L, L)
                return {'mode': 'diag', 'diag': d, 'loadings': None, 'full': None}
            return {'mode': 'factor', 'diag': np.zeros(size, dtype=dtype), 'loadings': L, 'full': None}
        if typ == 'full':
            M = _symmetrize(np.asarray(spec['matrix'], dtype=dtype))
            if M.shape != (size, size):
                raise ValueError('Full covariance shape mismatch')
            if diag_only:
                return {'mode': 'diag', 'diag': np.diag(M), 'loadings': None, 'full': None}
            return {'mode': 'full', 'diag': None, 'loadings': None, 'full': M}
        raise ValueError(f'Unknown covariance spec type: {typ}')
    if isinstance(spec, tuple):
        typ = spec[0].lower()
        if typ == 'diag':
            d = np.asarray(spec[1], dtype=dtype).reshape(-1)
            if len(d) != size:
                raise ValueError('Diagonal covariance length mismatch')
            return {'mode': 'diag', 'diag': d, 'loadings': None, 'full': None}
        if typ == 'factor':
            L = np.asarray(spec[1], dtype=dtype)
            psi = np.asarray(spec[2], dtype=dtype).reshape(-1)
            if L.shape[0] != size or len(psi) != size:
                raise ValueError('Factor covariance shape mismatch')
            if diag_only:
                d = np.einsum('ij,ij->i', L, L) + psi
                return {'mode': 'diag', 'diag': d, 'loadings': None, 'full': None}
            return {'mode': 'factor', 'diag': psi, 'loadings': L, 'full': None}
        if typ == 'eigh':
            w = np.asarray(spec[1], dtype=dtype).reshape(-1)
            Q = np.asarray(spec[2], dtype=dtype)
            if Q.shape[0] != size or Q.shape[1] != len(w):
                raise ValueError('Eigh covariance shape mismatch')
            w = np.clip(w, 0.0, None)
            L = Q * np.sqrt(w)[None, :]
            if diag_only:
                d = np.einsum('ij,ij->i', L, L)
                return {'mode': 'diag', 'diag': d, 'loadings': None, 'full': None}
            return {'mode': 'factor', 'diag': np.zeros(size, dtype=dtype), 'loadings': L, 'full': None}
        if typ == 'full':
            M = _symmetrize(np.asarray(spec[1], dtype=dtype))
            if M.shape != (size, size):
                raise ValueError('Full covariance shape mismatch')
            if diag_only:
                return {'mode': 'diag', 'diag': np.diag(M), 'loadings': None, 'full': None}
            return {'mode': 'full', 'diag': None, 'loadings': None, 'full': M}
        raise ValueError(f'Unknown covariance tuple type: {typ}')
    arr = np.asarray(spec, dtype=dtype)
    if arr.ndim == 1:
        if len(arr) != size:
            raise ValueError('Diagonal covariance length mismatch')
        return {'mode': 'diag', 'diag': arr.copy(), 'loadings': None, 'full': None}
    M = _symmetrize(arr)
    if M.shape != (size, size):
        raise ValueError('Full covariance shape mismatch')
    if diag_only:
        return {'mode': 'diag', 'diag': np.diag(M), 'loadings': None, 'full': None}
    return {'mode': 'full', 'diag': None, 'loadings': None, 'full': M}

def _traitcov_to_full(spec):
    """Materialize a trait covariance from its normalized factor/diagonal representation.

    Parameters
    ----------
    spec : array-like or numeric scalar
        Any Accepted as provided to the function.
    """
    if spec['mode'] == 'full':
        return spec['full']
    if spec['mode'] == 'diag':
        return np.diag(spec['diag'])
    return _symmetrize(spec['loadings'] @ spec['loadings'].T + np.diag(spec['diag']))

def _traitcov_diag(spec):
    """Extract the full marginal diagonal of a trait covariance specification.

    Parameters
    ----------
    spec : array-like or numeric scalar
        Any Accepted as provided to the function.
    """
    if spec['mode'] == 'diag':
        return spec['diag']
    if spec['mode'] == 'factor':
        return np.einsum('ij,ij->i', spec['loadings'], spec['loadings']) + spec['diag']
    return np.diag(spec['full'])

def _apply_traitcov(spec, x):
    """Apply the normalized trait covariance to a vector or matrix.

    Parameters
    ----------
    spec : object (see the cited input contract)
        Any Accepted as provided to the function.

    x : object (see the cited input contract)
        Numerical operand in ``spec['diag'] * x``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.
    """
    x = np.asarray(x, dtype=float)
    if spec['mode'] == 'diag':
        return spec['diag'] * x
    if spec['mode'] == 'factor':
        L = spec['loadings']
        return spec['diag'] * x + L @ (L.T @ x)
    return spec['full'] @ x

def _can_use_factor_speed(G_spec, E_spec):
    """Test whether both trait covariances support the low-rank factor conditioning path.

    Parameters
    ----------
    G_spec : object (see the cited input contract)
        Any Accepted as provided to the function.

    E_spec : object (see the cited input contract)
        Any Accepted as provided to the function.
    """
    return G_spec['mode'] in {'diag', 'factor'} and E_spec['mode'] in {'diag', 'factor'}

def _row_diag_lowrank(li, G_spec, E_spec):
    """Form the diagonal-plus-factor covariance for one animal eigenvalue.

    Parameters
    ----------
    li : object (see the cited input contract)
        Any Accepted as provided to the function. Source comparisons: ``li > 0``. See the
        rejection/fallback branches for enforcement.

    G_spec : object (see the cited input contract)
        Any Accepted as provided to the function.

    E_spec : object (see the cited input contract)
        Any Accepted as provided to the function.
    """
    d = li * _traitcov_diag(G_spec) + _traitcov_diag(E_spec)
    U_parts = []
    if G_spec['mode'] == 'factor' and G_spec['loadings'] is not None and (G_spec['loadings'].shape[1] > 0) and (li > 0):
        U_parts.append(np.sqrt(li) * G_spec['loadings'])
    if E_spec['mode'] == 'factor' and E_spec['loadings'] is not None and (E_spec['loadings'].shape[1] > 0):
        U_parts.append(E_spec['loadings'])
    if len(U_parts) == 0:
        U = np.zeros((len(d), 0), dtype=float)
    else:
        U = np.concatenate(U_parts, axis=1)
    return (d, U)

def _solve_diag_plus_lowrank(d, U, b, jitter=1e-08):
    """Solve a diagonal-plus-low-rank system using the Woodbury identity.

    Parameters
    ----------
    d : object (see the cited input contract)
        Numerical operand in ``b / d``. Shape must conform to that matrix/vector operation and
        the enclosing prepared state.

    U : object (see the cited input contract)
        Numerical operand in ``U / d[:, None]``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    b : object (see the cited input contract)
        Numerical operand in ``b / d``. Shape must conform to that matrix/vector operation and
        the enclosing prepared state.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_solve_spd`` as ``jitter``.
    """
    d = np.asarray(d, dtype=float)
    b = np.asarray(b, dtype=float)
    d = np.clip(d, jitter, None)
    if U.shape[1] == 0:
        return b / d
    DinvU = U / d[:, None]
    M = np.eye(U.shape[1], dtype=float) + U.T @ DinvU
    rhs = U.T @ (b / d)
    tmp = _solve_spd(M, rhs, jitter=jitter)
    return b / d - DinvU @ tmp

def _cholupdate_lower(L, x):
    """Update a lower Cholesky factor after a rank-one covariance increment.

    Parameters
    ----------
    L : object (see the cited input contract)
        Numerical operand in ``r / L[k, k]``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.

    x : object (see the cited input contract)
        Numerical operand in ``x[k] / L[k, k]``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.
    """
    x = x.copy().astype(float)
    n = len(x)
    for k in range(n):
        r = np.hypot(L[k, k], x[k])
        c = r / L[k, k]
        s = x[k] / L[k, k]
        L[k, k] = r
        if k + 1 < n:
            L[k + 1:, k] = (L[k + 1:, k] + s * x[k + 1:]) / c
            x[k + 1:] = c * x[k + 1:] - s * L[k + 1:, k]
    return L

def _chol_diag_plus_lowrank(d, U, jitter=1e-08):
    """Construct a lower Cholesky factor for a diagonal-plus-low-rank covariance.

    Parameters
    ----------
    d : array-like or numeric scalar
        Numerical operand in ``np.clip(np.asarray(d, dtype=float), jitter, None)``. Shape must
        conform to that matrix/vector operation and the enclosing prepared state.

    U : object (see the cited input contract)
        Numerical operand in ``U.shape[1]``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``.
    """
    d = np.clip(np.asarray(d, dtype=float), jitter, None)
    L = np.diag(np.sqrt(d))
    for j in range(U.shape[1]):
        _cholupdate_lower(L, U[:, j])
    return L

def _prepare_mvblup_inputs(traits, GRM, G, E=None, center=True, dtype=np.float64, diag_only=False):
    """Align phenotype and kernel/covariance inputs for multivariate Gaussian conditioning.

    Parameters
    ----------
    traits : array-like or numeric scalar
        Any Accepted as provided to the function.

    GRM : array-like or numeric scalar
        Any Accepted as provided to the function.

    G : array-like or numeric scalar
        Any Accepted as provided to the function.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``.

    center : bool
        Whether to subtract the observed/training mean along the modeled observation axis.
        Disable only when inputs have already been centered using training data or a
        zero-intercept model is intended. Default: ``True``.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``traits.to_numpy`` as
        ``dtype``.

    diag_only : bool
        Whether to remove cross-trait covariance terms and use only the diagonal trait variances
        for conditioning. Default: ``False``. Passed to ``_normalize_traitcov_spec`` as
        ``diag_only``.
    """
    traits_is_df = isinstance(traits, pd.DataFrame)
    if traits_is_df:
        row_index = traits.index
        col_index = traits.columns
        Y = traits.to_numpy(dtype=dtype, copy=True)
    else:
        Y = np.asarray(traits, dtype=dtype)
        if Y.ndim != 2:
            raise ValueError('traits must be a 2D array or DataFrame')
        row_index = None
        col_index = None
    n, t = Y.shape
    grm_spec = _normalize_grm_spec(GRM, n=n, dtype=dtype)
    Q, lam, K_full = (grm_spec['Q'], grm_spec['lam'], grm_spec['K'])
    G_spec = _normalize_traitcov_spec(G, size=t, dtype=dtype, diag_only=diag_only)
    E_spec = _normalize_traitcov_spec(E, size=t, dtype=dtype, diag_only=diag_only, allow_none=True)
    means = np.zeros(t, dtype=dtype)
    if center:
        means = np.nanmean(Y, axis=0)
        Y = Y - means[None, :]
    return {'Y': Y, 'Q': Q, 'lam': lam, 'K': K_full, 'G_spec': G_spec, 'E_spec': E_spec, 'means': means, 'traits_is_df': traits_is_df, 'row_index': row_index, 'col_index': col_index, 'n': n, 't': t, 'diag_only': diag_only}

def _wrap_mv_output(M, traits_is_df, row_index, col_index, return_numpy):
    """Restore labeled multivariate output in the original phenotype axis order.

    Parameters
    ----------
    M : object (see the cited input contract)
        Numerical operand in ``pd.DataFrame(M, index=row_index, columns=col_index)``. Shape must
        conform to that matrix/vector operation and the enclosing prepared state.

    traits_is_df : object (see the cited input contract)
        Any Accepted as provided to the function.

    row_index : object (see the cited input contract)
        Any Accepted as provided to the function.

    col_index : object (see the cited input contract)
        Any Accepted as provided to the function.

    return_numpy : object (see the cited input contract)
        Any Accepted as provided to the function.
    """
    if traits_is_df and (not return_numpy):
        return pd.DataFrame(M, index=row_index, columns=col_index)
    return M


