def _v31_matrix_model(method,random_state=0,model_kwargs=None):
    """Construct the selected low-rank/iterative residual-matrix imputation estimator.

    Parameters
    ----------
    method : callable or str
        Algorithm/estimator selected for the operation described above. See the source-derived
        choices and called model factory for the accepted methods; callable methods must obey
        that factory's fit/predict or objective contract. Source-recognized literal values:
        ``iterative``, ``iterative_ridge``, ``iterativeimputer``, ``soft_impute``,
        ``softimpute``. These select the corresponding branches below; comparison evidence alone
        does not establish an exhaustive enum.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``IterativeRidgeResidual`` as ``random_state``.

    model_kwargs : mapping
        Additional keyword settings forwarded to the selected estimator/writer. See the called
        implementation for its accepted names and value domains; these are not unrestricted
        scientific options. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.
    """
    kw={} if model_kwargs is None else dict(model_kwargs); m=str(method).lower()
    if m in {'iterative','iterative_ridge','iterativeimputer'}: return IterativeRidgeResidual(random_state=random_state,**kw)
    if m in {'softimpute','soft_impute'}: return SoftImputeResidual(**kw)
    raise ValueError('unknown matrix residual model')

def fit_residual_matrix_expert(traits,blup,*,methods=('iterative_ridge','softimpute'),n_splits=3,random_state=0,min_gain=.01,stack_min_gain=.02,model_kwargs=None):
    """Cross-fitted matrix-completion selector on R = Y - BLUP. The zero-residual BLUP is always a candidate.

    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    blup : array-like or pandas.DataFrame
        Baseline predicted values in the response animal/trait order, used for conditioning,
        residual construction or evaluation. Supply predictions from the corresponding fit
        without including held-out outcomes in training.

    methods : sequence of str
        Candidate estimator names compared using held-out prediction error. Names must be
        supported by the called model factory; selection/refitting must occur within each
        training fold. Default: ``('iterative_ridge', 'softimpute')``.

    n_splits : int
        Number of cross-validation folds, ordinarily at least two and no larger than the
        eligible training sample count. Fold-specific fitting must exclude held-out outcomes.
        Default: ``3``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``.

    min_gain : float
        Minimum held-out prediction improvement required for promotion. Positive values require
        a gain relative to the baseline; the evaluator defines whether its loss reduction is
        relative or absolute. Default: ``0.01``.

    stack_min_gain : float
        Minimum held-out prediction improvement required for promotion. Positive values require
        a gain relative to the baseline; the evaluator defines whether its loss reduction is
        relative or absolute. Default: ``0.02``.

    model_kwargs : mapping
        Additional keyword settings forwarded to the selected estimator/writer. See the called
        implementation for its accepted names and value domains; these are not unrestricted
        scientific options. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    Returns
    -------
    dict
        Result fields: ``mode``, ``model``, ``method``, ``scores``, ``blup``, ``version``. Field arrays preserve the corresponding input axis order.
    """
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits); B=blup.reindex_like(Y) if isinstance(blup,pd.DataFrame) else pd.DataFrame(blup,index=Y.index,columns=Y.columns); R=(Y-B).to_numpy(float); F=_split_cells(Y.to_numpy(float),n_splits,random_state); pred={m:np.full(R.shape,np.nan) for m in methods}
    for k in range(int(n_splits)):
        hold=F==k; train=R.copy(); train[hold]=np.nan
        for mi,m in enumerate(methods):
            try: pred[m][hold]=_v31_matrix_model(m,random_state+100*k+mi,(model_kwargs or {}).get(m)).fit_transform(train)[hold]
            except Exception: pass
    obs=np.isfinite(R); scores={'blup':_corr_rmse(R[obs],np.zeros(obs.sum()))}; viable=[]
    for m in methods:
        ok=obs&np.isfinite(pred[m]); sc=_corr_rmse(R[ok],pred[m][ok]); gain,z=_paired_rmse_gain(R[ok],np.zeros(ok.sum()),pred[m][ok]); sc.update(gain_vs_blup=gain,gain_z=z); scores[m]=sc
        if gain>=float(min_gain) and z>=1.96: viable.append(m)
    if not viable: return {'mode':'blup','model':None,'method':'blup','scores':scores,'blup':B,'version':V3_1_FINAL_VERSION}
    best=min(viable,key=lambda m:scores[m]['rmse']); model=_v31_matrix_model(best,random_state+9000,(model_kwargs or {}).get(best)).fit(R); return {'mode':'single','model':model,'method':best,'scores':scores,'blup':B,'version':V3_1_FINAL_VERSION}

def predict_residual_matrix_expert(fit,traits,blup=None):
    """Predict residual matrix expert.

    Parameters
    ----------
    fit : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    blup : array-like or pandas.DataFrame
        Baseline predicted values in the response animal/trait order, used for conditioning,
        residual construction or evaluation. Supply predictions from the corresponding fit
        without including held-out outcomes in training. Default: ``None``. None delegates to
        the local fallback shown in this body; it is not an additional numeric/category value.

    Returns
    -------
    object
        Computed result from ``pd.DataFrame(out, index=Y.index, columns=Y.columns)``; see the summary and the called implementation for its labeled/numerical representation.
    """
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits,columns=fit['blup'].columns); B=fit['blup'].reindex(Y.index) if blup is None else (blup.reindex_like(Y) if isinstance(blup,pd.DataFrame) else pd.DataFrame(blup,index=Y.index,columns=Y.columns));
    if fit['mode']=='blup': return B.copy()
    R=(Y-B).to_numpy(float); add=fit['model'].transform(R); out=B.to_numpy(float)+add; no=Y.notna().sum(1).eq(0).to_numpy(); out[no]=B.to_numpy(float)[no]; return pd.DataFrame(out,index=Y.index,columns=Y.columns)

def _v31_attach_single_specs(out, traits):
    """Attach single specs.

    Parameters
    ----------
    out : object (see the cited input contract)
        Input for the operation ``out['result']``. See
        ``vigor.multivariate._v31_attach_single_specs`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.
    """
    try:
        T=len(traits.columns); r=int(out.get('rank_G',T)); a=float(out.get('shrink_G',1.0)); res=out['result']; x=np.asarray(res.x,float); F=x[:T*r].reshape(T,r); Graw=F@F.T; Gspec={'factor':np.sqrt(a)*F,'diag':(1-a)*np.diag(Graw),'matrix':out['G'].to_numpy(float),'rank':r,'alpha':a}; out['G_spec']=Gspec; out['G'].attrs['v31_spec']=Gspec
        E=out['E'].to_numpy(float)
        if str(out.get('E_structure_resolved','')).startswith('diag'): Espec={'factor':np.zeros((T,0)),'diag':np.diag(E),'matrix':E,'rank':0,'alpha':0.0}
        else:
            ew,V=np.linalg.eigh(_project_psd(E,eps=1e-12)); keep=ew>max(1e-12,1e-10*max(float(ew.max()),1)); Espec={'factor':V[:,keep]*np.sqrt(ew[keep])[None,:],'diag':np.zeros(T),'matrix':E,'rank':int(keep.sum()),'alpha':1.0}
        out['E_spec']=Espec; out['E'].attrs['v31_spec']=Espec
    except Exception: pass
    return out

