V3_1_FINAL_VERSION = '2.11.0'


def _gxe_as_frame(environment,index):
    """Align environment values to the phenotype observation index.

    Parameters
    ----------
    environment : array-like, pandas.Series or pandas.DataFrame
        Environment covariates/categories aligned to the observation rows. Training rows
        determine encoding/normalization; categorical inputs define shared environments and
        continuous columns define environmental similarity.

    index : sequence, index or scalar
        Axis/node identifiers or positions selected by the local lookup below. Values must refer
        to the supplied object and preserve the requested output ordering.
    """
    if isinstance(environment,pd.Series):
        name=environment.name or 'environment'; out=environment.rename(name).to_frame()
    elif isinstance(environment,pd.DataFrame): out=environment.copy()
    else:
        arr=np.asarray(environment)
        if arr.ndim==1: arr=arr[:,None]
        if arr.ndim!=2: raise ValueError('environment must be one- or two-dimensional')
        out=pd.DataFrame(arr,index=index,columns=[f'environment_{j+1}' for j in range(arr.shape[1])])
    if isinstance(environment,(pd.Series,pd.DataFrame)):
        missing=index.difference(out.index)
        if len(missing): raise ValueError(f'environment is missing {len(missing)} phenotype rows')
        out=out.reindex(index)
    if len(out)!=len(index): raise ValueError('environment and traits must have the same number of rows')
    if out.isna().any().any(): raise ValueError('environment contains missing values; impute or define them before fitting GxE')
    return out


def _gxe_encode_environment(environment,index,fit_mask,environment_type='auto'):
    """Fit categorical/continuous environment encoding using designated training observations.

    Parameters
    ----------
    environment : array-like, pandas.Series or pandas.DataFrame
        Environment covariates/categories aligned to the observation rows. Training rows
        determine encoding/normalization; categorical inputs define shared environments and
        continuous columns define environmental similarity.

    index : sequence, index or scalar
        Axis/node identifiers or positions selected by the local lookup below. Values must refer
        to the supplied object and preserve the requested output ordering.

    fit_mask : one-dimensional bool array or None
        Mask selecting training animals for fitting frequencies, scaling or model parameters.
        Length must equal the animal axis; None uses the routine's full eligible training set.
        Keep evaluation outcomes outside this mask.

    environment_type : str
        Environment interpretation: 'auto' infers categorical versus continuous columns,
        'categorical' encodes category membership and 'continuous' standardizes numeric
        covariates. See _gxe_encode_environment for accepted spellings and missing-value
        handling. Default: ``'auto'``.
    """
    env=_gxe_as_frame(environment,index); Z=[]; names=[]; details={}
    if environment_type not in {'auto','continuous','categorical'}:
        raise ValueError("environment_type must be 'auto', 'continuous', or 'categorical'")
    for name in env.columns:
        s=env[name]; categorical=environment_type=='categorical' or (environment_type=='auto' and
            (not pd.api.types.is_numeric_dtype(s) or pd.api.types.is_bool_dtype(s)))
        if categorical:
            levels=pd.Index(pd.unique(s.loc[fit_mask].astype(str))).sort_values()
            if len(levels)<2: raise ValueError(f"categorical environment '{name}' has fewer than two training levels")
            unknown=~s.astype(str).isin(levels)
            if unknown.any(): raise ValueError(f"categorical environment '{name}' has levels absent from the training rows")
            A=np.column_stack([(s.astype(str).to_numpy()==level).astype(float) for level in levels])
            freq=A[fit_mask].mean(0); A-=freq[None,:]
            Z.append(A); names.extend([f'{name}[{level}]' for level in levels])
            details[str(name)]={'type':'categorical','levels':levels.tolist(),'frequencies':freq.tolist()}
        else:
            x=pd.to_numeric(s,errors='raise').to_numpy(float); mean=float(x[fit_mask].mean()); sd=float(x[fit_mask].std())
            if not np.isfinite(sd) or sd<=np.finfo(float).eps: raise ValueError(f"continuous environment '{name}' has zero training variance")
            Z.append(((x-mean)/sd)[:,None]); names.append(str(name))
            details[str(name)]={'type':'continuous','mean':mean,'sd':sd}
    Z=np.concatenate(Z,axis=1)
    # Centering categorical indicators makes their columns rank deficient by design. SVD returns
    # an orthonormal basis, so Z Z' and the GxE kernel do not depend on the omitted reference level.
    _,s,Vt=np.linalg.svd(Z[fit_mask],full_matrices=False); tol=max(Z.shape)*np.finfo(float).eps*(s[0] if len(s) else 1)
    rank=int(np.sum(s>tol))
    if rank<1: raise ValueError('environment design has zero rank in the training rows')
    Z=Z@Vt[:rank].T
    scale=np.sqrt(np.mean(np.sum(Z[fit_mask]**2,axis=1)))
    Z/=max(float(scale),np.finfo(float).eps)
    return Z,{'columns':names,'rank':rank,'details':details,'basis_scale':float(scale)}


def _gxe_normalize_kernel(K,fit_mask,name):
    """Normalize an environment/genetic interaction kernel on the training animal scale.

    Parameters
    ----------
    K : array-like
        Numerical operand in ``0.5 * (K + K.T)``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    fit_mask : one-dimensional bool array or None
        Mask selecting training animals for fitting frequencies, scaling or model parameters.
        Length must equal the animal axis; None uses the routine's full eligible training set.
        Keep evaluation outcomes outside this mask.

    name : str
        Identifier used to select or label the relevant component, field or output quantity. It
        must match the names present in the supplied object where lookup is required.
    """
    K=np.asarray(K,float)
    if K.ndim!=2 or K.shape[0]!=K.shape[1]: raise ValueError(f"kernel '{name}' must be square")
    if not np.isfinite(K).all(): raise ValueError(f"kernel '{name}' contains non-finite values")
    K=0.5*(K+K.T); scale=float(np.mean(np.diag(K)[fit_mask]))
    if not np.isfinite(scale) or scale<=0: raise ValueError(f"kernel '{name}' has non-positive training mean diagonal")
    return K/scale,scale


def make_gxe_kernels(GRM,environment,*,index=None,fit_mask=None,environment_type='auto',
                     include_gxe=True,dtype=np.float32,observation_animal_ids=None,grm_ids=None,
                     include_permanent_animal=True,gxe_components=None):
    """Construct normalized additive/dominance and GxE kernels without phenotype leakage.

    ``GRM`` may be a single additive kernel or a mapping of named kernels such
    as ``{'additive': K_A, 'dominance': K_D}``.  All supplied kernels are kept
    in the joint multivariate covariance model.  By default GxE is constructed
    from the additive kernel, giving A + D + A×E when dominance is supplied.
    Set ``gxe_components=('additive','dominance')`` to additionally fit D×E.

    For encoded environment matrix Z, each interaction kernel is
    ``K_component_x_E = K_component * (Z @ Z.T)``. The Schur product theorem
    guarantees PSD when the source kernel is PSD. ``fit_mask`` controls all
    environment centering/scaling and kernel normalization.

    Parameters
    ----------
    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    environment : array-like, pandas.Series or pandas.DataFrame
        Environment covariates/categories aligned to the observation rows. Training rows
        determine encoding/normalization; categorical inputs define shared environments and
        continuous columns define environmental similarity.

    index : sequence, index or scalar
        Axis/node identifiers or positions selected by the local lookup below. Values must refer
        to the supplied object and preserve the requested output ordering. Default: ``None``.
        None delegates to the local fallback shown in this body; it is not an additional
        numeric/category value. Passed to ``info.update`` as ``environment_design``.

    fit_mask : one-dimensional bool array or None
        Mask selecting training animals for fitting frequencies, scaling or model parameters.
        Length must equal the animal axis; None uses the routine's full eligible training set.
        Keep evaluation outcomes outside this mask. Default: ``None``. Passed to ``info.update``
        as ``fit_mask``.

    environment_type : str
        Environment interpretation: 'auto' infers categorical versus continuous columns,
        'categorical' encodes category membership and 'continuous' standardizes numeric
        covariates. See _gxe_encode_environment for accepted spellings and missing-value
        handling. Default: ``'auto'``.

    include_gxe : bool or sequence of str
        Genetic/environmental components requested for kernel construction. Boolean controls
        include or omit the named term; component sequences select supported
        additive/dominance/environment terms described by the kernel builder. Default: ``True``.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float32``.

    observation_animal_ids : sequence
        Animal identifiers mapping repeated observation rows to the unique GRM animal axis.
        Every observed animal must resolve to a kernel identifier; duplicate observations are
        allowed only in the repeated-observation route. Default: ``None``. None delegates to the
        local fallback shown in this body; it is not an additional numeric/category value.

    grm_ids : sequence
        Animal identifiers mapping repeated observation rows to the unique GRM animal axis.
        Every observed animal must resolve to a kernel identifier; duplicate observations are
        allowed only in the repeated-observation route. Default: ``None``. None delegates to the
        local fallback shown in this body; it is not an additional numeric/category value.

    include_permanent_animal : bool or sequence of str
        Genetic/environmental components requested for kernel construction. Boolean controls
        include or omit the named term; component sequences select supported
        additive/dominance/environment terms described by the kernel builder. Default: ``True``.

    gxe_components : object (see the cited input contract)
        Input for the operation ``gxe_components is None``. See
        ``vigor.multivariate.make_gxe_kernels`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``None``.

    Returns
    -------
    object
        Computed result from ``(kernels, info)``; see the summary and the called implementation for its labeled/numerical representation.
    """
    if index is None:
        n=len(environment); index=pd.RangeIndex(n)
    else: index=pd.Index(index); n=len(index)
    obs=None
    if isinstance(GRM,dict) and not ('matrix' in GRM and len(GRM) <= 4):
        raw={str(k):np.asarray(v,float) for k,v in GRM.items()}
    else:
        raw={'additive':np.asarray(GRM,float)}
    if observation_animal_ids is not None:
        obs=np.asarray(observation_animal_ids).astype(str)
        if len(obs)!=n: raise ValueError('observation_animal_ids must align to index')
        if grm_ids is None: raise ValueError('grm_ids is required with observation_animal_ids')
        pos={str(x):i for i,x in enumerate(grm_ids)}
        try: take=np.array([pos[x] for x in obs],int)
        except KeyError as exc: raise ValueError(f'observation animal {exc.args[0]} is absent from grm_ids') from exc
        raw={name:K[np.ix_(take,take)] for name,K in raw.items()}
    for name,K in raw.items():
        if K.shape!=(n,n): raise ValueError(f"GRM {name!r} dimensions do not match the phenotype/environment rows")
    fit_mask=np.ones(n,bool) if fit_mask is None else np.asarray(fit_mask,bool)
    if fit_mask.shape!=(n,) or not fit_mask.any(): raise ValueError('fit_mask must select at least one aligned row')
    # Preserve every supplied genetic component (A, D, etc.) in the joint model.
    kernels={}; scales={}
    for name,K in raw.items():
        Kn,sc=_gxe_normalize_kernel(K,fit_mask,name)
        kernels[name]=Kn.astype(dtype,copy=False); scales[name]=sc
    if 'additive' in kernels: base_name='additive'
    elif 'genetic' in kernels: base_name='genetic'
    else: base_name=next(iter(kernels))
    info={'kernel_scales':scales,'gxe_base_kernel':base_name}
    if obs is not None and include_permanent_animal and len(np.unique(obs))<len(obs):
        P=(obs[:,None]==obs[None,:]).astype(float); P,pscale=_gxe_normalize_kernel(P,fit_mask,'permanent_animal')
        kernels['permanent_animal']=P.astype(dtype,copy=False); info['kernel_scales']['permanent_animal']=pscale
    Z,env_info=_gxe_encode_environment(environment,index,fit_mask,environment_type)
    info.update(environment=env_info,environment_design=pd.DataFrame(Z,index=index,
        columns=[f'environment_basis_{j+1}' for j in range(Z.shape[1])]),fit_mask=fit_mask.copy())
    if include_gxe:
        H=Z@Z.T
        comps=[base_name] if gxe_components is None else [str(x) for x in gxe_components]
        for comp in comps:
            if comp not in kernels: raise ValueError(f"GxE source kernel {comp!r} is unavailable; have {list(kernels)}")
            out_name='gxe' if comp==base_name else f'{comp}_gxe'
            Kgxe,gxe_scale=_gxe_normalize_kernel(np.asarray(kernels[comp],float)*H,fit_mask,out_name)
            kernels[out_name]=Kgxe.astype(dtype,copy=False); info['kernel_scales'][out_name]=gxe_scale
        info['gxe_components']=comps
    info.update(_v31_kernel_diagnostics(kernels))
    return kernels,info

def _fit_masked_fixed_effects(traits,design,fit_mask,ridge=1e-8):
    """Fit masked fixed effects.

    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    design : array-like or pandas.DataFrame or None
        Fixed-effect design, animals × covariate columns. Rows must match the phenotype/kernel
        animal order. None uses the routine's intercept-only or no-additional-covariate path;
        rank-deficient designs may be rejected or reduced.

    fit_mask : one-dimensional bool array or None
        Mask selecting training animals for fitting frequencies, scaling or model parameters.
        Length must equal the animal axis; None uses the routine's full eligible training set.
        Keep evaluation outcomes outside this mask.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``1e-08``.
    """
    Y=traits.to_numpy(float); X=np.asarray(design,float); X=np.column_stack([np.ones(len(X)),X])
    beta=np.zeros((X.shape[1],Y.shape[1])); fitted=np.zeros_like(Y)
    penalty=np.eye(X.shape[1])*float(ridge); penalty[0,0]=0
    for j in range(Y.shape[1]):
        ok=fit_mask&np.isfinite(Y[:,j])
        if ok.sum()<1: continue
        A=X[ok].T@X[ok]+penalty; b=X[ok].T@Y[ok,j]
        try: beta[:,j]=np.linalg.solve(A,b)
        except np.linalg.LinAlgError: beta[:,j]=np.linalg.pinv(A,rcond=1e-10)@b
        fitted[:,j]=X@beta[:,j]
    names=['intercept']+[str(x) for x in design.columns]
    return pd.DataFrame(fitted,index=traits.index,columns=traits.columns),pd.DataFrame(beta,index=names,columns=traits.columns)



# Preserve the release-overlay binding for adapters defined below.


def fit_gxe_mvblup(traits,GRM,environment,*,environment_type='auto',fit_mask=None,include_gxe=True,
                   include_environment_main=True,fixed_covariates=None,fixed_ridge=1e-8,
                   rank_G=6,rank_D=3,rank_GxE=3,rank_DxE=3,rank_permanent=None,rank_E=None,E_structure='auto',shrink_G='auto',
                   shrink_E='auto',ridge_G=0.0,n_boot=0,random_state=None,blas_threads='auto',
                   covariance_kwargs=None,prediction_kwargs=None,observation_animal_ids=None,grm_ids=None,
                   gxe_components=None):
    """Fit joint A/D/GxE multivariate BLUP and return component predictions.

    A mapping ``GRM={'additive': KA, 'dominance': KD}`` fits A + D + A×E by
    default; request ``gxe_components=('additive','dominance')`` for A×E + D×E.

    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    environment : array-like, pandas.Series or pandas.DataFrame
        Environment covariates/categories aligned to the observation rows. Training rows
        determine encoding/normalization; categorical inputs define shared environments and
        continuous columns define environmental similarity.

    environment_type : str
        Environment interpretation: 'auto' infers categorical versus continuous columns,
        'categorical' encodes category membership and 'continuous' standardizes numeric
        covariates. See _gxe_encode_environment for accepted spellings and missing-value
        handling. Default: ``'auto'``. Passed to ``make_gxe_kernels`` as ``environment_type``.

    fit_mask : one-dimensional bool array or None
        Mask selecting training animals for fitting frequencies, scaling or model parameters.
        Length must equal the animal axis; None uses the routine's full eligible training set.
        Keep evaluation outcomes outside this mask. Default: ``None``. Passed to
        ``make_gxe_kernels`` as ``fit_mask``.

    include_gxe : bool or sequence of str
        Genetic/environmental components requested for kernel construction. Boolean controls
        include or omit the named term; component sequences select supported
        additive/dominance/environment terms described by the kernel builder. Default: ``True``.
        Passed to ``make_gxe_kernels`` as ``include_gxe``.

    include_environment_main : bool or sequence of str
        Genetic/environmental components requested for kernel construction. Boolean controls
        include or omit the named term; component sequences select supported
        additive/dominance/environment terms described by the kernel builder. Default: ``True``.

    fixed_covariates : array-like or pandas.DataFrame or None
        Fixed-effect design, animals × covariate columns. Rows must match the phenotype/kernel
        animal order. None uses the routine's intercept-only or no-additional-covariate path;
        rank-deficient designs may be rejected or reduced. Default: ``None``.

    fixed_ridge : float
        Input supplied to ``_fit_masked_fixed_effects`` as ``ridge``. See that callable's
        documented ``ridge`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Default: ``1e-08``. Passed to ``_fit_masked_fixed_effects`` as
        ``ridge``.

    rank_G : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``6``.

    rank_D : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``3``.

    rank_GxE : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``3``.

    rank_DxE : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``3``.

    rank_permanent : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``None``.

    rank_E : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value.

    E_structure : str
        Residual structure: 'auto' splits only disconnected overlap-support components,
        otherwise retaining FA geometry; 'fa'/'full' keeps joint residual covariance;
        'diag'/'diagonal' removes factors; 'auto_supported' uses legacy overlap-supported
        blocks. 'auto_cv' selects structure using held-out moments. min_E_pair_overlap defines
        supported pairs. Default: ``'auto'``.

    shrink_G : float, str or mapping
        Genetic off-diagonal retention: numeric values conventionally lie in [0,1], with 1
        retaining all. 'auto'/'legacy_auto'/'historical_auto' uses sample-size retention
        n/(n+50); 'none'/'off' retains all; 'auto_cv'/'cv' invokes held-out moment policy
        selection. 'analytic_global'/'analytic_pairwise' (and aliases resolved by
        _analytic_shrink_mode) regularizes prediction after final SE, preserving unshrunk
        inference. Kernel-name mappings are accepted. Residual-only pairwise/EB spellings are
        not genetic policies. Default: ``'auto'``.

    shrink_E : float or str
        Residual retention: numeric 0..1 scales off-diagonals.
        'auto' shrinks each residual pair by overlap/(overlap+400) without rank preservation
        (the 3.1.3 policy; same as 'pairwise_full'); append '@s' ('auto@100') to set the
        per-pair strength s. 'linear_analytic' applies the closed-form overlap-aware
        Schafer-Strimmer linear intensity toward the diagonal. 'model_eb' ('model_eb@c')
        shrinks each pair by tau2/(tau2 + c s2_ij), with s2_ij the pair's sampling variance
        from the fit's own MoM precision. 'eb'/'fisher_eb'/'pairwise_eb' uses
        rank-preserving Fisher-z EB, while 'fisher_eb_full'/'pairwise_eb_full'/'eb_full'
        permits full-rank pair retention. 'pairwise'/'pairwise_overlap' uses overlap support
        with rank preservation; 'pairwise_full'/'pairwise_overlap_full' omits that rank
        restriction.
        'legacy_auto'/'historical_auto' uses median overlap/(overlap+400); 'none'/'off' retains
        all. 'auto_cv'/'cv' selects on held-out moments; analytic aliases use final-SE
        prediction retention. auto_supported E requires scalar-compatible retention. Default:
        ``'auto'``.

    ridge_G : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``0.0``.

    n_boot : int
        Number of bootstrap replicates. Zero disables bootstrap when supported; positive counts
        estimate sampling variation by the resampling scheme used here. Default: ``0``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``None``.

    blas_threads : int or str
        BLAS thread limit during numerical operations. Positive integers select an explicit
        thread count; auto uses the routine's workload-dependent thread policy. Default:
        ``'auto'``.

    covariance_kwargs : mapping
        Additional keyword settings forwarded to the selected estimator/writer. See the called
        implementation for its accepted names and value domains; these are not unrestricted
        scientific options. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    prediction_kwargs : mapping or None
        Named settings or metadata forwarded to the specific operation below. See that
        operation's argument/schema contract for accepted fields; None uses its default/empty
        configuration. Default: ``None``.

    observation_animal_ids : sequence
        Animal identifiers mapping repeated observation rows to the unique GRM animal axis.
        Every observed animal must resolve to a kernel identifier; duplicate observations are
        allowed only in the repeated-observation route. Default: ``None``. None delegates to the
        local fallback shown in this body; it is not an additional numeric/category value.
        Passed to ``make_gxe_kernels`` as ``observation_animal_ids``.

    grm_ids : sequence
        Animal identifiers mapping repeated observation rows to the unique GRM animal axis.
        Every observed animal must resolve to a kernel identifier; duplicate observations are
        allowed only in the repeated-observation route. Default: ``None``. None delegates to the
        local fallback shown in this body; it is not an additional numeric/category value.
        Passed to ``make_gxe_kernels`` as ``grm_ids``.

    gxe_components : object (see the cited input contract)
        Input supplied to ``make_gxe_kernels`` as ``gxe_components``. See that callable's
        documented ``gxe_components`` contract for its type, alignment and value domain. This
        wrapper retains that contract. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value. Passed to
        ``make_gxe_kernels`` as ``gxe_components``.

    Returns
    -------
    dict
        Result fields: ``version``, ``model``, ``kernels``, ``kernel_info``, ``fixed_coefficients``, ``fixed_prediction``, ``residualized_traits``, ``covariance``, ``prediction``, ``fit_mask``. Field arrays preserve the corresponding input axis order.
    """
    from .hyperparameter_cv import validate_cv_count
    if validate_cv_count((covariance_kwargs or {}).get('optimize_hyperparameters_cv', 0)):
        raise ValueError("optimize_hyperparameters_cv is not supported for environment/GxE routes")
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits)
    fit_mask=Y.notna().any(axis=1).to_numpy() if fit_mask is None else np.asarray(fit_mask,bool)
    kernels,kinfo=make_gxe_kernels(GRM,environment,index=Y.index,fit_mask=fit_mask,
        environment_type=environment_type,include_gxe=include_gxe,observation_animal_ids=observation_animal_ids,grm_ids=grm_ids,
        gxe_components=gxe_components)
    Z=kinfo['environment_design'] if include_environment_main else pd.DataFrame(index=Y.index)
    if fixed_covariates is not None:
        C=fixed_covariates.reindex(Y.index) if isinstance(fixed_covariates,pd.DataFrame) else pd.DataFrame(fixed_covariates,index=Y.index)
        if C.isna().any().any(): raise ValueError('fixed_covariates contains missing values')
        Z=pd.concat([Z,C.astype(float)],axis=1)
    fixed,beta=_fit_masked_fixed_effects(Y,Z,fit_mask,ridge=fixed_ridge)
    residual=Y-fixed; residual=Y.where(Y.isna(),residual)
    ranks={}
    for name in kernels:
        if name in {'additive','genetic'}: ranks[name]=rank_G
        elif name=='dominance': ranks[name]=rank_D
        elif name=='gxe': ranks[name]=rank_GxE
        elif name=='dominance_gxe': ranks[name]=rank_DxE
        elif name=='permanent_animal': ranks[name]=rank_permanent
        else: ranks[name]=rank_G
    ckw=dict(rank_G=ranks,rank_E=rank_E,E_structure=E_structure,shrink_G=shrink_G,
             shrink_E=shrink_E,ridge_G=ridge_G,n_boot=n_boot,random_state=random_state,blas_threads=blas_threads)
    if covariance_kwargs: ckw.update(covariance_kwargs)
    covariance=_genetic_varcov_PSD_raw(kernels,residual,**ckw)
    pkw=dict(solver_tol=1e-7,solver_maxiter=500,preconditioner='diag',work_dtype='auto',blas_threads=blas_threads)
    if prediction_kwargs: pkw.update(prediction_kwargs)
    pred=_mvPredict_raw(residual,kernels,covariance,E=covariance['E'],**pkw)
    residual_mean=np.asarray(pred['trait_mean'])[None,:]; genetic=pred['breeding_value']
    expected_trait=fixed+residual_mean+genetic
    phenotype=expected_trait+pred['residual_prediction']
    pred.update(fixed_prediction=fixed,fixed_coefficients=beta,expected_genetic_value=genetic,
                expected_trait=expected_trait,phenotype_prediction=phenotype)
    return {'version':V3_1_FINAL_VERSION,'model':'additive_gxe_mvblup' if include_gxe else 'additive_mvblup',
            'kernels':kernels,'kernel_info':kinfo,'fixed_coefficients':beta,'fixed_prediction':fixed,
            'residualized_traits':residual,'covariance':covariance,'prediction':pred,'fit_mask':fit_mask}





# ============================================================================
# v3.1.4: GPU LightGBM + exact marker decomposition + SHAP interpretation
# ============================================================================
V3_1_INTERPRETABILITY_VERSION = '2.11.0-interpretability'
_LIGHTGBM_DEVICE_CACHE = {}
_fit_single_residual_model_pre_gpu_shap = _fit_single_residual_model


def _lightgbm_device(device='auto'):
    """Resolve LightGBM device with a one-time tiny fit; auto falls back safely to CPU.

    Parameters
    ----------
    device : str
        Input for the operation ``str(device).lower()``. See
        ``vigor.multivariate._lightgbm_device`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``'auto'``.
    """
    requested = 'auto' if device is None else str(device).lower()
    if requested not in {'auto','cpu','gpu','cuda'}: return requested
    if requested != 'auto': return requested
    if 'auto' in _LIGHTGBM_DEVICE_CACHE: return _LIGHTGBM_DEVICE_CACHE['auto']
    import shutil
    # Avoid noisy failed CUDA/OpenCL initialization on CPU-only hosts. NVIDIA GPU nodes expose nvidia-smi.
    if shutil.which('nvidia-smi') is None:
        _LIGHTGBM_DEVICE_CACHE['auto']='cpu'; return 'cpu'
    from lightgbm import LGBMRegressor
    X=np.asarray([[0.,0.],[0.,1.],[1.,0.],[1.,1.]],dtype=np.float32); y=np.asarray([0.,1.,1.,0.],dtype=np.float32)
    for candidate in ('cuda','gpu'):
        try:
            LGBMRegressor(n_estimators=1,num_leaves=2,max_depth=1,min_child_samples=1,
                          device_type=candidate,verbosity=-1,n_jobs=1).fit(X,y)
            _LIGHTGBM_DEVICE_CACHE['auto']=candidate; return candidate
        except Exception: pass
    _LIGHTGBM_DEVICE_CACHE['auto']='cpu'; return 'cpu'


class SelectedLGBMRegressor:
    """Leakage-safe univariate feature selection performed inside each LightGBM fit.

    protected features are always retained; only candidate features are ranked using the
    current fit's y. This makes use inside the existing nested CV safe for phenotype-derived
    SNP selection.
    """
    def __init__(self,top_k=256,protect_indices=None,candidate_indices=None,random_state=0,**model_kwargs):
        """Initialize SelectedLGBMRegressor with the inputs and resource settings below.

        Parameters
        ----------
        top_k : int or None
            Maximum candidates/features retained by the corresponding ranking stage. Positive
            integers bound work/model size; None leaves retention to that stage's policy. Default:
            ``256``.

        protect_indices : sequence or integer array
            Identifiers or zero-based positions of selected/protected items on the corresponding
            input axis. Entries must exist; paired index arrays define the row/column pairs to
            compute. Default: ``None``. None delegates to the local fallback shown in this body; it
            is not an additional numeric/category value.

        candidate_indices : sequence or integer array
            Identifiers or zero-based positions of selected/protected items on the corresponding
            input axis. Entries must exist; paired index arrays define the row/column pairs to
            compute. Default: ``None``. None delegates to the local fallback shown in this body; it
            is not an additional numeric/category value.

        random_state : int or None
            Seed controlling randomized sampling, folds or projections for reproducibility. None
            uses the selected random-number backend without a fixed seed. Default: ``0``.

        **model_kwargs : mapping
            Additional keyword settings forwarded to the selected estimator/writer. See the called
            implementation for its accepted names and value domains; these are not unrestricted
            scientific options.
        """
        self.top_k=top_k; self.protect_indices=protect_indices; self.candidate_indices=candidate_indices
        self.random_state=random_state; self.model_kwargs=model_kwargs
    def fit(self,X,y):
        """Fit the estimator using the enclosing model configuration and aligned training inputs.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support. Passed to ``np.nan_to_num`` as ``nan``.

        y : array-like
            Numerical operand in ``len(y) > 2``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``self``; see the summary and the called implementation for its labeled/numerical representation.
        """
        from sklearn.feature_selection import f_regression
        X=np.asarray(X,float); y=np.asarray(y,float); p=X.shape[1]
        protect=np.array([],dtype=int) if self.protect_indices is None else np.unique(np.asarray(self.protect_indices,int))
        if self.candidate_indices is None:
            cand=np.setdiff1d(np.arange(p,dtype=int),protect,assume_unique=False)
        else: cand=np.unique(np.asarray(self.candidate_indices,int)); cand=cand[(cand>=0)&(cand<p)]
        protect=protect[(protect>=0)&(protect<p)]; protect=np.setdiff1d(protect,cand,assume_unique=False)
        k=min(max(0,int(self.top_k)),len(cand))
        if k and len(y)>2:
            Xc=np.nan_to_num(X[:,cand],nan=np.nanmedian(X[:,cand],axis=0)); score,_=f_regression(Xc,y,center=True)
            score=np.nan_to_num(score,nan=-np.inf,posinf=np.inf,neginf=-np.inf); chosen=cand[np.argsort(score)[-k:]]
        else: chosen=np.array([],int)
        self.selected_indices_=np.unique(np.r_[protect,chosen]).astype(int)
        kw=dict(self.model_kwargs); device=kw.pop('device',kw.pop('device_type','auto')); device=_lightgbm_device(device)
        pars=dict(n_estimators=96,num_leaves=15,max_depth=5,learning_rate=.04,verbosity=-1,
                  random_state=int(self.random_state),n_jobs=1,min_child_samples=15,subsample=.9,colsample_bytree=.9,
                  reg_lambda=.25)
        if device!='cpu': pars.update(device_type=device,max_bin=63)
        pars.update(kw)
        from lightgbm import LGBMRegressor
        self.model_=LGBMRegressor(**pars); self.model_.fit(X[:,self.selected_indices_],y); self.n_features_in_=p
        return self
    def predict(self,X): 
        """Return the predict result computed by ``np.asarray(self.model_.predict(np.asarray(X, float)[:, self.selected_indices_], validate_features=False)).reshape``.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``np.asarray(self.model_.predict(np.asarray(X, float)[:, self.selected_indices_], validate_features=False)).reshape(-1)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return np.asarray(self.model_.predict(np.asarray(X,float)[:,self.selected_indices_],validate_features=False)).reshape(-1)
    def pred_contrib(self,X):
        """Return per-feature tree contributions expanded to the original input feature axis.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
        """
        X=np.asarray(X,float); z=np.asarray(self.model_.predict(X[:,self.selected_indices_],pred_contrib=True,validate_features=False))
        out=np.zeros((len(X),self.n_features_in_+1),float); out[:,self.selected_indices_]=z[:,:-1]; out[:,-1]=z[:,-1]; return out



class SelectedRidgeRegressor:
    """Fold-local univariate screening followed by standardized ridge regression.

    Candidate SNP/dominance columns are selected using only the current fit's
    target. Protected BLUP/canonical/GRM-PC columns are always retained.
    """
    def __init__(self, top_k=256, protect_indices=None, candidate_indices=None, alpha=100.0, random_state=0, **model_kwargs):
        """Initialize SelectedRidgeRegressor with the inputs and resource settings below.

        Parameters
        ----------
        top_k : int or None
            Maximum candidates/features retained by the corresponding ranking stage. Positive
            integers bound work/model size; None leaves retention to that stage's policy. Default:
            ``256``.

        protect_indices : sequence or integer array
            Identifiers or zero-based positions of selected/protected items on the corresponding
            input axis. Entries must exist; paired index arrays define the row/column pairs to
            compute. Default: ``None``. None delegates to the local fallback shown in this body; it
            is not an additional numeric/category value.

        candidate_indices : sequence or integer array
            Identifiers or zero-based positions of selected/protected items on the corresponding
            input axis. Entries must exist; paired index arrays define the row/column pairs to
            compute. Default: ``None``. None delegates to the local fallback shown in this body; it
            is not an additional numeric/category value.

        alpha : float
            Regularization coefficient, mixing weight or statistical significance threshold selected
            by this estimator; the local validation and objective determine its precise scale.
            Default: ``100.0``.

        random_state : int or None
            Seed controlling randomized sampling, folds or projections for reproducibility. None
            uses the selected random-number backend without a fixed seed. Default: ``0``.

        **model_kwargs : mapping
            Additional keyword settings forwarded to the selected estimator/writer. See the called
            implementation for its accepted names and value domains; these are not unrestricted
            scientific options.
        """
        self.top_k=top_k; self.protect_indices=protect_indices; self.candidate_indices=candidate_indices
        self.alpha=alpha; self.random_state=random_state; self.model_kwargs=model_kwargs
    def fit(self, X, y):
        """Fit the estimator using the enclosing model configuration and aligned training inputs.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        y : array-like
            Numerical operand in ``len(y) > 2``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``self``; see the summary and the called implementation for its labeled/numerical representation.
        """
        from sklearn.feature_selection import f_regression
        from sklearn.preprocessing import StandardScaler
        from sklearn.linear_model import Ridge
        X=np.asarray(X,float); y=np.asarray(y,float); p=X.shape[1]
        protect=np.array([],dtype=int) if self.protect_indices is None else np.unique(np.asarray(self.protect_indices,int))
        if self.candidate_indices is None: cand=np.setdiff1d(np.arange(p,dtype=int),protect,assume_unique=False)
        else:
            cand=np.unique(np.asarray(self.candidate_indices,int)); cand=cand[(cand>=0)&(cand<p)]
        protect=protect[(protect>=0)&(protect<p)]; protect=np.setdiff1d(protect,cand,assume_unique=False)
        k=min(max(0,int(self.top_k)),len(cand))
        if k and len(y)>2:
            med=np.nanmedian(X[:,cand],axis=0); Xc=np.where(np.isfinite(X[:,cand]),X[:,cand],med[None,:])
            score,_=f_regression(Xc,y,center=True); score=np.nan_to_num(score,nan=-np.inf,posinf=np.inf,neginf=-np.inf)
            chosen=cand[np.argsort(score)[-k:]]
        else: chosen=np.array([],int)
        self.selected_indices_=np.unique(np.r_[protect,chosen]).astype(int)
        Z=np.asarray(X[:,self.selected_indices_],float); med=np.nanmedian(Z,axis=0); Z=np.where(np.isfinite(Z),Z,med[None,:]); self.median_=med
        self.scaler_=StandardScaler().fit(Z); pars=dict(alpha=float(self.alpha),solver='lsqr',tol=1e-5,max_iter=2000)
        pars.update(self.model_kwargs); self.model_=Ridge(**pars).fit(self.scaler_.transform(Z),y); self.n_features_in_=p
        return self
    def predict(self,X):
        """Return the predict result computed by ``np.asarray(self.model_.predict(self.scaler_.transform(Z))).reshape``.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``np.asarray(self.model_.predict(self.scaler_.transform(Z))).reshape(-1)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        X=np.asarray(X,float); Z=X[:,self.selected_indices_]; Z=np.where(np.isfinite(Z),Z,self.median_[None,:])
        return np.asarray(self.model_.predict(self.scaler_.transform(Z))).reshape(-1)


def _fit_single_residual_model(method,X,y,*,random_state=0,n_components=8,model_kwargs=None):
    """v3.1 residual-model dispatcher with GPU-aware LightGBM and fold-local SNP selection.

    Parameters
    ----------
    method : callable or str
        Algorithm/estimator selected for the operation described above. See the source-derived
        choices and called model factory for the accepted methods; callable methods must obey
        that factory's fit/predict or objective contract. Source-recognized literal values:
        ``lightgbm``, ``lightgbm_selected``, ``lightgbm_topk``, ``ridge_selected``,
        ``selected_ridge``. These select the corresponding branches below; comparison evidence
        alone does not establish an exhaustive enum.

    X : array-like
        Predictor matrix with observations in rows and features in columns. Its row order must
        match the response or operator to which it is applied; the selected fitting routine
        determines missing-value support.

    y : array-like
        Numerical operand in ``_fit_single_residual_model_pre_gpu_shap(method, X, y,
        random_state=random_state, n_components=n_components, model_kwargs=model_kwargs)``.
        Shape must conform to that matrix/vector operation and the enclosing prepared state.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_fit_single_residual_model_pre_gpu_shap`` as ``random_state``.

    n_components : int or None
        Number of retained latent components or feature directions. Must fit the available
        matrix dimensions; None delegates selection to the decomposition helper when supported.
        Default: ``8``. Passed to ``_fit_single_residual_model_pre_gpu_shap`` as
        ``n_components``.

    model_kwargs : mapping
        Additional keyword settings forwarded to the selected estimator/writer. See the called
        implementation for its accepted names and value domains; these are not unrestricted
        scientific options. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``_fit_single_residual_model_pre_gpu_shap`` as ``model_kwargs``.
    """
    m=str(method).lower(); kw={} if model_kwargs is None else dict(model_kwargs)
    if m not in {'lightgbm','lightgbm_selected','lightgbm_topk','ridge_selected','selected_ridge'}:
        return _fit_single_residual_model_pre_gpu_shap(method,X,y,random_state=random_state,n_components=n_components,model_kwargs=model_kwargs)
    if m in {'ridge_selected','selected_ridge'}:
        top_k=kw.pop('top_k',256); protect=kw.pop('protect_indices',None); cand=kw.pop('candidate_indices',None); alpha=kw.pop('alpha',100.0)
        return SelectedRidgeRegressor(top_k=top_k,protect_indices=protect,candidate_indices=cand,alpha=alpha,
                                      random_state=random_state,**kw).fit(X,y)
    if m in {'lightgbm_selected','lightgbm_topk'}:
        top_k=kw.pop('top_k',256); protect=kw.pop('protect_indices',None); cand=kw.pop('candidate_indices',None)
        return SelectedLGBMRegressor(top_k=top_k,protect_indices=protect,candidate_indices=cand,
                                     random_state=random_state,**kw).fit(X,y)
    from lightgbm import LGBMRegressor
    device=kw.pop('device',kw.pop('device_type','auto')); device=_lightgbm_device(device)
    pars=dict(n_estimators=96,num_leaves=15,max_depth=5,learning_rate=.04,verbosity=-1,random_state=random_state,
              n_jobs=1,min_child_samples=15,subsample=.9,colsample_bytree=.9,reg_lambda=.25)
    if device!='cpu': pars.update(device_type=device,max_bin=63)
    pars.update(kw); mdl=LGBMRegressor(**pars); mdl.fit(X,y); return mdl


def _kernel_pc_features(K,fit_mask=None,n_components=32,random_state=0,eps=1e-10,dtype=np.float32):
    """Kernel-PCA coordinates U sqrt(S); with fit_mask use a Nyström projection for all rows.

    Parameters
    ----------
    K : array-like
        Numerical operand in ``K[:, tr] @ U / np.sqrt(s)[None, :]``. Shape must conform to that
        matrix/vector operation and the enclosing prepared state.

    fit_mask : one-dimensional bool array or None
        Mask selecting training animals for fitting frequencies, scaling or model parameters.
        Length must equal the animal axis; None uses the routine's full eligible training set.
        Keep evaluation outcomes outside this mask. Default: ``None``.

    n_components : int or None
        Number of retained latent components or feature directions. Must fit the available
        matrix dimensions; None delegates selection to the decomposition helper when supported.
        Default: ``32``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``randomized_svd`` as ``random_state``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float32``. Passed to ``np.zeros`` as ``dtype``.
    """
    from sklearn.utils.extmath import randomized_svd
    K=np.asarray(K,float); n=K.shape[0]
    if K.shape!=(n,n): raise ValueError('kernel must be square')
    fit=np.ones(n,bool) if fit_mask is None else np.asarray(fit_mask,bool)
    if fit.shape!=(n,) or fit.sum()<2: raise ValueError('fit_mask must select at least two rows')
    tr=np.flatnonzero(fit); Ktt=_symmetrize(K[np.ix_(tr,tr)]); k=max(1,min(int(n_components),len(tr)-1))
    if len(tr)<=max(256,3*k):
        s,U=np.linalg.eigh(Ktt); o=np.argsort(s)[::-1][:k]; s=np.clip(s[o],0,None); U=U[:,o]
    else:
        U,s,_=randomized_svd(Ktt,n_components=k,n_iter=4,random_state=random_state); s=np.clip(s,0,None)
    keep=s>max(float(eps),float(s[0] if len(s) else 0)*1e-10); U=U[:,keep]; s=s[keep]
    if not len(s): return np.zeros((n,0),dtype=dtype),{'train_indices':tr,'vectors':U,'values':s}
    F=(K[:,tr]@U)/np.sqrt(s)[None,:]
    return np.asarray(F,dtype=dtype),{'train_indices':tr,'vectors':U,'values':s}


def _genomic_features_dataset(result, arguments):
    """Convert ``make_genomic_features`` output into a ('sample','feature') Dataset.

    Parameters
    ----------
    result : pandas.DataFrame or mapping
        Feature table, or {'features': table, 'state': mapping} when return_state=True; the
        table becomes the ``features`` variable and the reusable projection state the
        ``state`` attribute.
    arguments : mapping
        Bound call arguments; scalar options are recorded in ``ds.attrs['parameters']``.
    """
    from .results import result_dataset
    values = dict(result) if isinstance(result, dict) else {"features": result}
    return result_dataset(values, dims={"features": ("sample", "feature")},
                          var_attrs={"features": {"long_name": "leakage-safe genomic features",
                                                  "description": "Kernel PCs (U sqrt(S), Nystrom-projected) and optional SNP/dominance codes."}},
                          title="Genomic prediction features", software="vigor.multivariate.make_genomic_features",
                          parameters=_call_parameters(arguments))


def _genomic_features_input(features):
    """Return genomic features as a pandas table when supplied as an xarray result.

    Parameters
    ----------
    features : pandas.DataFrame, array-like, xarray.DataArray, xarray.Dataset or None
        ``make_genomic_features`` Dataset (its ``features`` variable is used), a DataArray, or
        an existing table/array returned unchanged.
    """
    if _is_xr_dataset(features):
        features = features["features"]
    return _as_pandas_input(features)


@_dataset_result(_genomic_features_dataset)
def make_genomic_features(GRM,*,fit_mask=None,n_grm_components=32,per_chromosome_grms=None,
                          n_chr_components=8,genotypes=None,selected_snps=None,snp_names=None,
                          include_dominance=False,index=None,random_state=0,dtype=np.float32,return_state=False,save_path=None):
    """Build leakage-safe genomic features from GRMs and optionally raw/selected SNPs.

    GRM features are U sqrt(S). If fit_mask is supplied, the eigensystem is estimated only in
    training animals and every row is Nyström-projected through K[:, train]. SNP means and allele
    frequencies are likewise learned from fit_mask only.

    Parameters
    ----------
    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    fit_mask : one-dimensional bool array or None
        Mask selecting training animals for fitting frequencies, scaling or model parameters.
        Length must equal the animal axis; None uses the routine's full eligible training set.
        Keep evaluation outcomes outside this mask. Default: ``None``.

    n_grm_components : array-like or numeric scalar
        Input for the operation ``_kernel_pc_features(K, fit, n_grm_components, random_state +
        ki, dtype=dtype)``. See ``vigor.multivariate.make_genomic_features`` and its caller for
        the scientific representation; the shown operation constrains the required type/shape.
        Default: ``32``.

    per_chromosome_grms : mapping
        Input for the operation ``enumerate(per_chromosome_grms.items())``. See
        ``vigor.multivariate.make_genomic_features`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.

    n_chr_components : array-like or numeric scalar
        Input for the operation ``_kernel_pc_features(K, fit, n_chr_components, random_state +
        1000 + ki, dtype=dtype)``. See ``vigor.multivariate.make_genomic_features`` and its
        caller for the scientific representation; the shown operation constrains the required
        type/shape. Default: ``8``.

    genotypes : array-like or pandas.DataFrame
        Genotype values with animals in rows and variants in columns, or the genotype source
        accepted by this entry point. Biallelic dosage uses 0/1/2; preserve sample/variant
        labels and the coding expected by the selected kernel or association model. Default:
        ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.

    selected_snps : sequence or integer array
        Identifiers or zero-based positions of selected/protected items on the corresponding
        input axis. Entries must exist; paired index arrays define the row/column pairs to
        compute. Default: ``None``. None delegates to the local fallback shown in this body; it
        is not an additional numeric/category value.

    snp_names : sequence of str
        Variant labels in genotype-column order, used to identify the association or
        fine-mapping rows. Default: ``None``. None delegates to the local fallback shown in this
        body; it is not an additional numeric/category value.

    include_dominance : bool or sequence of str
        Genetic/environmental components requested for kernel construction. Boolean controls
        include or omit the named term; component sequences select supported
        additive/dominance/environment terms described by the kernel builder. Default:
        ``False``.

    index : sequence, index or scalar
        Axis/node identifiers or positions selected by the local lookup below. Values must refer
        to the supplied object and preserve the requested output ordering. Default: ``None``.
        None delegates to the local fallback shown in this body; it is not an additional
        numeric/category value.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float32``. Passed to ``_kernel_pc_features`` as
        ``dtype``.

    return_state : bool
        Whether to also return the reusable projection state (fit mask, kernel eigensystems,
        SNP means/frequencies); it is stored as ``ds.attrs['state']`` only when this flag is
        set. Default: ``False``.

    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.

    Returns
    -------
    xarray.Dataset
        Data variable ``features`` ('sample','feature') with feature names such as
        ``grm_all_pc001``/``snp_<id>`` as coordinates; with return_state the ``state``
        attribute holds the projection state.
    """
    GRM=_kernel_input(GRM)
    kernels=_v31_named_kernels(GRM,dtype=np.float64) if _v31_is_multigrm(GRM) else {'all':np.asarray(GRM,float)}
    n=next(iter(kernels.values())).shape[0]; fit=np.ones(n,bool) if fit_mask is None else np.asarray(fit_mask,bool)
    if index is None:
        if isinstance(GRM,pd.DataFrame): index=GRM.index
        else:index=pd.RangeIndex(n)
    parts=[]; names=[]; state={'fit_mask':fit.copy(),'kernels':{},'snp':None}
    for ki,(name,K) in enumerate(kernels.items()):
        F,st=_kernel_pc_features(K,fit,n_grm_components,random_state+ki,dtype=dtype); parts.append(F)
        names.extend([f'grm_{name}_pc{j+1:03d}' for j in range(F.shape[1])]); state['kernels'][str(name)]=st
    if per_chromosome_grms is not None:
        for ki,(name,K) in enumerate(per_chromosome_grms.items()):
            F,st=_kernel_pc_features(K,fit,n_chr_components,random_state+1000+ki,dtype=dtype); parts.append(F)
            names.extend([f'grm_chr{name}_pc{j+1:03d}' for j in range(F.shape[1])]); state['kernels'][f'chr{name}']=st
    if genotypes is not None:
        X=genotypes.to_numpy(float) if isinstance(genotypes,pd.DataFrame) else np.asarray(genotypes,float)
        if X.shape[0]!=n: raise ValueError('genotypes and GRM must have the same number of animals')
        all_names=list(map(str,genotypes.columns)) if isinstance(genotypes,pd.DataFrame) else (list(map(str,snp_names)) if snp_names is not None else [f'snp{j}' for j in range(X.shape[1])])
        if selected_snps is None: take=np.arange(X.shape[1])
        elif len(selected_snps)==0: take=np.array([],int)
        elif isinstance(selected_snps[0],str):
            pos={x:i for i,x in enumerate(all_names)}; take=np.asarray([pos[str(x)] for x in selected_snps if str(x) in pos],int)
        else: take=np.asarray(selected_snps,int)
        X=X[:,take]; sn=[all_names[j] for j in take]; mu=np.nanmean(X[fit],axis=0); Xi=np.where(np.isfinite(X),X,mu[None,:])
        parts.append(np.asarray(Xi,dtype=dtype)); names.extend([f'snp_{x}' for x in sn])
        p=np.clip(np.nanmean(X[fit],axis=0)/2,1e-6,1-1e-6); st={'indices':take,'names':sn,'mean':mu,'p':p}
        if include_dominance:
            q=1-p; D=np.where(Xi==0,-2*p[None,:]**2,np.where(Xi==1,2*p[None,:]*q[None,:],np.where(Xi==2,-2*q[None,:]**2,0.0)))
            parts.append(np.asarray(D,dtype=dtype)); names.extend([f'dom_{x}' for x in sn])
        state['snp']=st
    F=np.concatenate(parts,axis=1) if parts else np.zeros((n,0),dtype=dtype); df=pd.DataFrame(F,index=index,columns=names)
    return {'features':df,'state':state} if return_state else df


def _expert_feature_names(Y,G,E,*,target=None,phenotype_assisted=False,genomic_features=None,n_ge_components=8):
    """Construct ordered names for baseline, genomic and phenotype-assisted expert features.

    Parameters
    ----------
    Y : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance.

    target : str, index or sequence
        Response/trait identifiers selected for this prediction, mediation or subset operation.
        Names/positions must exist in the supplied response axes; sequences preserve the
        requested ordering. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    phenotype_assisted : bool
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``False``.

    genomic_features : array-like
        Predictor matrix with observations in rows and features in columns. Its row order must
        match the response or operator to which it is applied; the selected fitting routine
        determines missing-value support. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value.

    n_ge_components : int or None
        Number of retained latent components or feature directions. Must fit the available
        matrix dimensions; None delegates selection to the decomposition helper when supported.
        Default: ``8``.
    """
    genomic_features=_genomic_features_input(genomic_features)
    cols=list(map(str,Y.columns)) if isinstance(Y,pd.DataFrame) else [f'trait{j}' for j in range(np.asarray(Y).shape[1])]
    t=len(cols); k=min(int(n_ge_components),t); names=[f'blup::{c}' for c in cols]+[f'genetic_canonical::{j+1}' for j in range(k)]
    if genomic_features is not None:
        if isinstance(genomic_features,pd.DataFrame): names+=list(map(str,genomic_features.columns))
        else:names += [f'genomic::{j+1}' for j in range(np.asarray(genomic_features).shape[1])]
    if phenotype_assisted:
        names += [f'residual::{c}' for c in cols]+[f'residual_white::{c}' for c in cols]+[f'observed::{c}' for c in cols]
    return names


_expert_features_base_gpu_shap = _expert_features
def _expert_features(Y,B,G,E,target=None,*,phenotype_assisted=False,genomic_features=None,n_ge_components=8):
    """Return the expert features result computed by ``_expert_features_base_gpu_shap``.

    Parameters
    ----------
    Y : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    B : array-like
        Numerical operand in ``_expert_features_base_gpu_shap(Y, B, G, E, target=target,
        phenotype_assisted=phenotype_assisted, genomic_features=genomic_features,
        n_ge_components=n_ge_components)``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.

    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance.

    target : str, index or sequence
        Response/trait identifiers selected for this prediction, mediation or subset operation.
        Names/positions must exist in the supplied response axes; sequences preserve the
        requested ordering. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``_expert_features_base_gpu_shap`` as ``target``.

    phenotype_assisted : bool
        Input supplied to ``_expert_features_base_gpu_shap`` as ``phenotype_assisted``. See that
        callable's documented ``phenotype_assisted`` contract for its type, alignment and value
        domain. This wrapper retains that contract. Default: ``False``. Passed to
        ``_expert_features_base_gpu_shap`` as ``phenotype_assisted``.

    genomic_features : array-like
        Predictor matrix with observations in rows and features in columns. Its row order must
        match the response or operator to which it is applied; the selected fitting routine
        determines missing-value support. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value. Passed to
        ``_expert_features_base_gpu_shap`` as ``genomic_features``.

    n_ge_components : int or None
        Number of retained latent components or feature directions. Must fit the available
        matrix dimensions; None delegates selection to the decomposition helper when supported.
        Default: ``8``. Passed to ``_expert_features_base_gpu_shap`` as ``n_ge_components``.
    """
    genomic_features=_genomic_features_input(genomic_features)
    if isinstance(genomic_features,pd.DataFrame) and isinstance(Y,pd.DataFrame): genomic_features=genomic_features.reindex(Y.index)
    return _expert_features_base_gpu_shap(Y,B,G,E,target=target,phenotype_assisted=phenotype_assisted,
                                          genomic_features=genomic_features,n_ge_components=n_ge_components)


def _residual_expert_covariances(G,E=None):
    """Return a dense total G only for expert feature rotations, preserving the exact covariance model separately.

    Parameters
    ----------
    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``.
    """
    G=_covariance_input(G); E=_as_pandas_input(E)
    if isinstance(G,pd.Series) and 'G_components' in G:
        comps={str(k):np.asarray(v,float) for k,v in G.get('G_components_prediction',G['G_components']).items()}
        Ef=np.asarray(G.get('E_prediction',G['E']) if E is None else E,float)
    elif isinstance(G,dict):
        comps={str(k):np.asarray(v,float) for k,v in G.items()}
        if E is None: raise ValueError('E is required when G is a plain component mapping')
        Ef=np.asarray(E,float)
    else:
        comps={'genetic':np.asarray(G,float)}; Ef=np.asarray(E,float)
    Gtot=sum(comps.values(),np.zeros_like(next(iter(comps.values()))))
    return Gtot,Ef,comps


def fit_blup_residual_experts(traits,GRM,G,E=None,*,blup=None,n_splits=3,methods=('pcr','pls','elasticnet','lightgbm'),
                              n_components=8,random_state=0,stack_min_gain=.02,genomic_min_gain=.03,phenotype_min_gain=.005,
                              genomic_min_z=2.33,phenotype_min_z=1.96,genomic_features=None,model_kwargs=None,solver='pcg',
                              solver_tol=2e-6,solver_maxiter=500,preconditioner='diag',crossfit_refit_covariance=True,
                              covariance_kwargs=None,allow_blup_only_nonlinear=False,store_oof=False):
    """Cross-fitted residual experts with multi-GRM support and fold-local selected-SNP LightGBM.

    For multiple GRMs, exact BLUP folds retain all K_k x G_k components.  Only the low-dimensional
    canonical expert rotation uses G_total=sum_k G_k; this does not alter the fitted mixed model.

    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``. Passed to ``mvBLUP`` as ``E``.

    blup : array-like or pandas.DataFrame
        Baseline predicted values in the response animal/trait order, used for conditioning,
        residual construction or evaluation. Supply predictions from the corresponding fit
        without including held-out outcomes in training. Default: ``None``. None delegates to
        the local fallback shown in this body; it is not an additional numeric/category value.

    n_splits : int
        Number of cross-validation folds, ordinarily at least two and no larger than the
        eligible training sample count. Fold-specific fitting must exclude held-out outcomes.
        Default: ``3``.

    methods : sequence of str
        Candidate estimator names compared using held-out prediction error. Names must be
        supported by the called model factory; selection/refitting must occur within each
        training fold. Default: ``('pcr', 'pls', 'elasticnet', 'lightgbm')``.

    n_components : int or None
        Number of retained latent components or feature directions. Must fit the available
        matrix dimensions; None delegates selection to the decomposition helper when supported.
        Default: ``8``. Passed to ``_expert_features`` as ``n_ge_components``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_fit_global_residual_models`` as ``random_state``.

    stack_min_gain : float
        Minimum held-out prediction improvement required for promotion. Positive values require
        a gain relative to the baseline; the evaluator defines whether its loss reduction is
        relative or absolute. Default: ``0.02``. Passed to ``_fit_global_residual_models`` as
        ``stack_min_gain``.

    genomic_min_gain : float
        Minimum held-out prediction improvement required for promotion. Positive values require
        a gain relative to the baseline; the evaluator defines whether its loss reduction is
        relative or absolute. Default: ``0.03``. Passed to ``_fit_global_residual_models`` as
        ``model_min_gain``.

    phenotype_min_gain : float
        Minimum held-out prediction improvement required for promotion. Positive values require
        a gain relative to the baseline; the evaluator defines whether its loss reduction is
        relative or absolute. Default: ``0.005``. Passed to ``_fit_global_residual_models`` as
        ``model_min_gain``.

    genomic_min_z : float
        Minimum standardized evidence statistic for promotion or stable effect classification.
        Positive thresholds require stronger support relative to the estimated uncertainty.
        Default: ``2.33``. Passed to ``_fit_global_residual_models`` as ``model_min_z``.

    phenotype_min_z : float
        Minimum standardized evidence statistic for promotion or stable effect classification.
        Positive thresholds require stronger support relative to the estimated uncertainty.
        Default: ``1.96``. Passed to ``_fit_global_residual_models`` as ``model_min_z``.

    genomic_features : array-like
        Predictor matrix with observations in rows and features in columns. Its row order must
        match the response or operator to which it is applied; the selected fitting routine
        determines missing-value support. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value. Passed to
        ``_expert_features`` as ``genomic_features``.

    model_kwargs : mapping
        Additional keyword settings forwarded to the selected estimator/writer. See the called
        implementation for its accepted names and value domains; these are not unrestricted
        scientific options. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    solver : str
        Input supplied to ``mvBLUP`` as ``solver``. See that callable's documented ``solver``
        contract for its type, alignment and value domain. This wrapper retains that contract.
        Default: ``'pcg'``.

    solver_tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``2e-06``. Passed to ``mvBLUP`` as ``solver_tol``.

    solver_maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``500``. Passed to ``mvBLUP`` as ``solver_maxiter``.

    preconditioner : str
        Input supplied to ``mvBLUP`` as ``preconditioner``. See that callable's documented
        ``preconditioner`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Default: ``'diag'``.

    crossfit_refit_covariance : bool
        Whether to perform the named persistence/materialization/refitting step. True enables
        it; False follows the bypass path in this routine. Refitting during CV must use training
        outcomes only. Default: ``True``.

    covariance_kwargs : mapping
        Additional keyword settings forwarded to the selected estimator/writer. See the called
        implementation for its accepted names and value domains; these are not unrestricted
        scientific options. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    allow_blup_only_nonlinear : bool
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``False``.

    store_oof : bool
        Whether to include the named optional output in the returned/stored result. Enabling
        this materializes or computes the additional table, effects, state or diagnostics
        described by the summary. Default: ``False``.

    Returns
    -------
    object
        Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
    """
    genomic_features=_genomic_features_input(genomic_features); GRM=_kernel_input(GRM)
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits); n,t=Y.shape
    Gf,Ef,Gcomponents=_residual_expert_covariances(G,E); covariance_kwargs={} if covariance_kwargs is None else dict(covariance_kwargs)
    mk={} if model_kwargs is None else {k:({} if v is None else dict(v)) for k,v in model_kwargs.items()}
    if any(str(m).lower() in {'lightgbm_selected','lightgbm_topk'} for m in methods) and isinstance(genomic_features,pd.DataFrame):
        base=t+min(int(n_components),t); gnames=list(map(str,genomic_features.columns)); snp=np.asarray([i for i,x in enumerate(gnames) if x.startswith('snp_')],int)
        total_base=base+len(gnames); candidate=base+snp; protect=np.setdiff1d(np.arange(total_base),candidate)
        for m in methods:
            if str(m).lower() in {'lightgbm_selected','lightgbm_topk'}:
                z=mk.setdefault(m,{}); z.setdefault('candidate_indices',candidate); z.setdefault('protect_indices',protect)
    B=_mvBLUP_raw(Y,GRM,G,E=E,missing='exact',solver=solver,solver_tol=solver_tol,solver_maxiter=solver_maxiter,
             preconditioner=preconditioner) if blup is None else (blup.reindex_like(Y) if isinstance(blup,pd.DataFrame) else pd.DataFrame(blup,index=Y.index,columns=Y.columns))
    def fold_blup(Yk):
        """Fit training-fold covariance and produce fold-safe genetic/conditional predictions.

        Parameters
        ----------
        Yk : array-like or pandas.DataFrame
            Phenotype observations, with animals in rows and traits in columns. Preserve the animal
            order used by the relationship kernel; NaN marks unobserved cells where the estimator
            supports missing data.

        Returns
        -------
        object
            Computed result from ``(Bk, Gcan, Ecan)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        if crossfit_refit_covariance:
            ge=_genetic_varcov_PSD_raw(GRM,Yk,n_boot=0,**covariance_kwargs); Gcan,Ecan,_=_residual_expert_covariances(ge,None)
            Bk=_mvBLUP_raw(Yk,GRM,ge,E=None if isinstance(ge,pd.Series) else Ecan,missing='exact',solver=solver,
                      solver_tol=solver_tol,solver_maxiter=solver_maxiter,preconditioner=preconditioner)
        else:
            Gcan,Ecan=Gf,Ef; Bk=_mvBLUP_raw(Yk,GRM,G,E=E,missing='exact',solver=solver,solver_tol=solver_tol,
                                       solver_maxiter=solver_maxiter,preconditioner=preconditioner)
        return Bk,Gcan,Ecan
    rf=_split_rows(n,n_splits,random_state); gx=[[] for _ in range(t)]; gy=[[] for _ in range(t)]; Xo=None; Ro=np.full((n,t),np.nan)
    for k in range(int(n_splits)):
        val=rf==k; Yk=Y.copy(); Yk.iloc[val,:]=np.nan; Bk,Gk,Ek=fold_blup(Yk)
        Xg=_expert_features(Yk,Bk,Gk,Ek,phenotype_assisted=False,genomic_features=genomic_features,n_ge_components=n_components)
        if Xo is None:Xo=np.full((n,Xg.shape[1]),np.nan)
        Xo[val]=Xg[val]; Ro[val]=Y.to_numpy(float)[val]-Bk.to_numpy(float)[val]
        for j in range(t):
            rows=np.flatnonzero(val&Y.iloc[:,j].notna().to_numpy())
            if len(rows): gx[j].append(Xg[rows]); gy[j].append(Y.iloc[rows,j].to_numpy(float)-Bk.iloc[rows,j].to_numpy(float))
    cf=_split_cells(Y.to_numpy(float),n_splits,random_state+101); px=[[] for _ in range(t)]; py=[[] for _ in range(t)]
    for k in range(int(n_splits)):
        hold=cf==k; Yk=Y.mask(hold); Bk,Gk,Ek=fold_blup(Yk)
        for j in range(t):
            rows=np.flatnonzero(hold[:,j])
            if len(rows):
                Xp=_expert_features(Yk,Bk,Gk,Ek,target=j,phenotype_assisted=True,genomic_features=genomic_features,n_ge_components=n_components)
                px[j].append(Xp[rows]); py[j].append(Y.iloc[rows,j].to_numpy(float)-Bk.iloc[rows,j].to_numpy(float))
    gx=[np.vstack(z) if z else None for z in gx]; gy=[np.concatenate(z) if z else None for z in gy]
    px=[np.vstack(z) if z else None for z in px]; py=[np.concatenate(z) if z else None for z in py]; cols=list(Y.columns)
    if genomic_features is not None or allow_blup_only_nonlinear:
        gm,gdiag=_fit_global_residual_models(gx,gy,methods,random_state=random_state,n_components=n_components,model_min_gain=genomic_min_gain,
            model_min_z=genomic_min_z,stack_min_gain=stack_min_gain,model_kwargs=mk); genmodels={cols[j]:gm.get(j,{'mode':'blup','models':{},'weights':{},'global':True}) for j in range(t)}
    else:
        gdiag={'mode':'blup','weights':{},'scores':{},'best_single':'blup','reason':'no additional genomic features beyond BLUP'}
        genmodels={c:{'mode':'blup','models':{},'weights':{},'global':True} for c in cols}
    pm,pdiag=_fit_global_residual_models(px,py,methods,random_state=random_state+1000,n_components=n_components,model_min_gain=phenotype_min_gain,
        model_min_z=phenotype_min_z,stack_min_gain=stack_min_gain,model_kwargs=mk); phenmodels={cols[j]:pm.get(j,{'mode':'blup','models':{},'weights':{},'global':True}) for j in range(t)}
    mt=None
    try:
        ok=np.isfinite(Xo).all(1)&np.isfinite(Ro).any(1)
        if (genomic_features is not None or allow_blup_only_nonlinear) and ok.sum()>30: mt=MaskedMultiTaskElasticNet().fit(Xo[ok],Ro[ok])
    except Exception: pass
    out={'blup':B,'G':pd.DataFrame(Gf,index=cols,columns=cols),'E':pd.DataFrame(Ef,index=cols,columns=cols),
         'G_components':{k:pd.DataFrame(v,index=cols,columns=cols) for k,v in Gcomponents.items()},'covariance_model':G,'E_model':E,
         'GRM_model':GRM,'genomic_models':genmodels,'phenotype_models':phenmodels,'multitask_genomic':mt,'methods':tuple(methods),'n_splits':int(n_splits),
         'diagnostics':{'genomic_global':gdiag,'phenotype_global':pdiag},'genomic_features':genomic_features,'n_components':int(n_components),
         'version':_V3_VERSION,'feature_names_genomic':_expert_feature_names(Y,Gf,Ef,phenotype_assisted=False,genomic_features=genomic_features,n_ge_components=n_components),
         'feature_names_phenotype':{str(c):_expert_feature_names(Y,Gf,Ef,target=j,phenotype_assisted=True,genomic_features=genomic_features,n_ge_components=n_components) for j,c in enumerate(Y.columns)},
         'lightgbm_device':_lightgbm_device('auto'),'model_kwargs':mk,'interpretability_version':V3_1_INTERPRETABILITY_VERSION}
    if store_oof:out['oof']={'genomic_X':gx,'genomic_y':gy,'phenotype_X':px,'phenotype_y':py}
    return out


def predict_blup_residual_experts(fit,traits,*,blup=None,GRM=None,genomic_features=None,include_multitask=False):
    """Predict breeding-value prediction residual experts.

    Parameters
    ----------
    fit : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes. Passed to ``_expert_features`` as ``n_ge_components``.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    blup : array-like or pandas.DataFrame
        Baseline predicted values in the response animal/trait order, used for conditioning,
        residual construction or evaluation. Supply predictions from the corresponding fit
        without including held-out outcomes in training. Default: ``None``. None delegates to
        the local fallback shown in this body; it is not an additional numeric/category value.

    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components. Default: ``None``. None delegates to the local fallback shown in this body;
        it is not an additional numeric/category value.

    genomic_features : array-like
        Predictor matrix with observations in rows and features in columns. Its row order must
        match the response or operator to which it is applied; the selected fitting routine
        determines missing-value support. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value.

    include_multitask : bool
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``False``.

    Returns
    -------
    dict
        Result fields: ``prediction``, ``genomic_only``, ``phenotype_assisted``, ``blup``, ``multitask_genomic``, ``has_phenotype``. Field arrays preserve the corresponding input axis order.
    """
    genomic_features=_genomic_features_input(genomic_features)
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits,columns=fit['blup'].columns); Gcan=fit['G'].to_numpy(); Ecan=fit['E'].to_numpy()
    if blup is not None: B=blup.reindex_like(Y) if isinstance(blup,pd.DataFrame) else pd.DataFrame(blup,index=Y.index,columns=Y.columns)
    elif GRM is None: B=fit['blup'].reindex(Y.index)
    else:
        cov=fit.get('covariance_model',fit['G']); Em=fit.get('E_model',fit['E'])
        B=_mvBLUP_raw(Y,GRM,cov,E=Em,missing='exact',solver='pcg',preconditioner='diag')
    gf=genomic_features if genomic_features is not None else fit.get('genomic_features')
    Xg=_expert_features(Y,B,Gcan,Ecan,phenotype_assisted=False,genomic_features=gf,n_ge_components=fit['n_components']); gen=B.copy(); phen=B.copy()
    for j,c in enumerate(Y.columns):
        if c in fit['genomic_models']: gen[c]=B[c].to_numpy()+_predict_stacked_target(fit['genomic_models'][c],Xg)
        if c in fit['phenotype_models']:
            Xp=_expert_features(Y,B,Gcan,Ecan,target=j,phenotype_assisted=True,genomic_features=gf,n_ge_components=fit['n_components'])
            phen[c]=B[c].to_numpy()+_predict_stacked_target(fit['phenotype_models'][c],Xp)
    mt=pd.DataFrame(B.to_numpy()+fit['multitask_genomic'].predict(Xg),index=Y.index,columns=Y.columns) if include_multitask and fit.get('multitask_genomic') is not None else None
    has=Y.notna().any(axis=1); hyb=gen.copy(); hyb.loc[has]=phen.loc[has]
    return {'prediction':hyb,'genomic_only':gen,'phenotype_assisted':phen,'blup':B,'multitask_genomic':mt,'has_phenotype':has}


_MVPREDICT_DIMS = {
    "trait_mean": ("trait",), "breeding_value": ("sample", "trait"), "genetic_mean": ("sample", "trait"),
    "residual_prediction": ("sample", "trait"), "phenotype_prediction": ("sample", "trait"),
    "genetic_expert_correction": ("sample", "trait"), "A": ("sample", "trait"), "alpha": ("observation",),
    "E_matrix": ("trait_i", "trait_j"), "components": ("component", "sample", "trait"),
    "G_matrices": ("component", "trait_i", "trait_j"), "row_profile": ("sample",),
}


def _prediction_traits(traits):
    """Return the phenotype input as a labeled DataFrame for result-coordinate construction.

    Parameters
    ----------
    traits : pandas.DataFrame, xarray.DataArray or array-like
        Animal-by-trait input of a prediction call; arrays receive positional labels exactly
        as the prediction code labels its outputs.
    """
    traits = _as_pandas_input(traits)
    return traits if isinstance(traits, pd.DataFrame) else pd.DataFrame(np.asarray(traits, dtype=float))


def _mvpredict_dataset(result, arguments, *, software="vigor.multivariate.mvPredict",
                       title="Multivariate genomic prediction (exact Gaussian conditioning)"):
    """Convert an ``mvPredict`` result mapping into a labeled ('sample','trait') Dataset.

    Parameters
    ----------
    result : mapping
        Historical mvPredict fields: prediction matrices on ('sample','trait'), trait_mean on
        'trait', per-kernel ``components``/``G_matrices`` stacked along 'component',
        ``E_matrix`` on ('trait_i','trait_j'), optional ``A``/``alpha`` state; solver and
        precision diagnostics, kernel names and nested covariance fits go to attrs.
    arguments : mapping
        Bound call arguments; ``traits`` supplies sample/trait labels and scalar options are
        recorded as parameters.
    software : str
        Producing function recorded in ``ds.attrs['software']``. Default:
        ``'vigor.multivariate.mvPredict'``.
    title : str
        Human-readable title stored in ``ds.attrs['title']``. Default: ``'Multivariate
        genomic prediction (exact Gaussian conditioning)'``.
    """
    return _labeled_result_dataset(result, traits=_prediction_traits(arguments.get("traits")), dims=_MVPREDICT_DIMS,
                                   stacked=("components", "G_matrices"), title=title, software=software,
                                   arguments=arguments)


@_dataset_result(_mvpredict_dataset)
@operation_progress('mvPredict')
def mvPredict(traits,GRM,G=None,E=None,*,solver_tol=1e-7,solver_maxiter=500,preconditioner='auto',
              work_dtype='auto',blas_threads='auto',jitter=1e-8,accuracy='auto',
              kernel_rank='full',return_alpha=False,return_state=False,center=True,progress=False,
              covariance_cv=2,optimize_hyperparameters_cv=0,covariance_cv_ranks=(3,5,8,12,'full'),
              covariance_kwargs=None,hpo_trials=12,save_path=None):
    """High-throughput full-kernel mvBLUP posterior means by default.
    
    accuracy='auto' uses exact float64 conditioning for small problems and switches
    to full-kernel float32 for n>=1024.  No spectral kernel compression is used
    by default. Set accuracy='exact' to force float64 at any sample size.
    Set center=False after externally applying training-only intercepts; the
    supplied centered observations then condition a zero-intercept posterior.
    If G is omitted, select and fit sparse FA for both G and E using
    training-only whole-animal CV with unseen-animal genetic prediction as the
    objective. optimize_hyperparameters_cv>=2 adds project-specific Optuna;
    explicit G/E matrices or a prior covariance fit bypass all refitting.
    
    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Animal × trait observations used for Gaussian conditioning; NaN cells are omitted from
        the observed-space solve. Completely unobserved animals can still receive genetic
        predictions through cross-animal kinship. DataFrame labels are restored on all
        prediction matrices. Centering uses supplied finite observations, so withhold test
        outcomes as NaN.
    
    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.
    
    G : array-like, covariance specification, xarray.DataArray, xarray.Dataset or None
        Genetic trait covariance in observation trait order. A pre-fitted
        covariance matrix (DataFrame or DataArray such as ``fit['G_prediction']``) or a
        genetic_varcov_PSD Dataset bypasses automatic fitting.
        None triggers training-only sparse G+E factor CV. Default: ``None``.
    
    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``. Passed to ``prepare_mvBLUP_plan`` as ``E``.
    
    covariance_cv : int
        Training-only whole-animal folds used to select sparse G+E factor rank when
        G is omitted. Every outer project test outcome must remain NaN. Default: ``2``.
    
    optimize_hyperparameters_cv : int
        Optional project-specific Optuna folds. Zero uses deterministic sparse
        rank-grid CV; an integer >=2 enables rank and regularization search
        maximizing unseen-animal genetic prediction. Default: ``0``.
    
    covariance_cv_ranks : tuple
        Candidate factor ranks applied to both G and E for the sparse-FA
        selection; includes full as a convergent candidate. Default: ``(3, 5, 8, 12, 'full')``.
    
    covariance_kwargs : dict or None
        Optional project-level fitting parameters, such as maxiter or
        shrink_E. Ignored only when absent; incompatible with supplied G.
        Default: ``None``.
    
    hpo_trials : int
        Number of Optuna sparse rank and shrinkage trials when optimization is
        enabled; positive integer controlling the search budget. Default: ``12``.
    
    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.
    
    solver_tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``. Passed to ``plan.solve`` as ``rtol``.
    
    solver_maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``500``. Passed to ``plan.solve`` as ``maxiter``.
    
    preconditioner : str or None
        PCG preconditioning: 'auto' selects 'sample_block' when 1<T<=64 and trait covariance is
        coupled, otherwise 'diag'; 'diag' uses observed marginal variances, 'sample_block'
        within-animal observed-trait blocks, and 'trait_block' within-trait animal blocks
        (requires cheap kernel submatrices). 'none'/None disables preconditioning. Default:
        ``'auto'``.
    
    work_dtype : str or NumPy float32/float64 dtype
        Working precision: 'auto'/'mixed' uses float32 in a fast plan; 'float32' and 'float64'
        explicitly select precision, with equivalent NumPy type/dtype objects accepted.
        accuracy='exact' resolves auto to float64 and rejects explicit float32/mixed. Other
        dtypes are rejected. Default: ``'auto'``.
    
    blas_threads : int or str
        BLAS thread limit during numerical operations. Positive integers select an explicit
        thread count; auto uses the routine's workload-dependent thread policy. Default:
        ``'auto'``. Passed to ``prepare_mvBLUP_plan`` as ``blas_threads``.
    
    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``prepare_mvBLUP_plan`` as
        ``jitter``.
    
    accuracy : str
        Conditioning precision: 'auto' selects 'exact' below 1024 animals and 'fast' at/above
        1024; 'exact' forces float64/full-kernel conditioning, while 'fast' permits float32 and
        requested kernel compression. prepare_mvBLUP_plan accepts only 'exact' and 'fast'.
        Default: ``'auto'``.
    
    kernel_rank : int, str or None
        Animal-kernel approximation rank. None, 0, False or 'full' retains the full kernel;
        'auto' uses a size-based rank in fast plans; a positive integer requests that many
        retained eigenvectors plus a residual bulk eigenvalue. Exact plans reject compression.
        This is distinct from trait covariance rank. Default: ``'full'``.
    
    return_alpha : bool
        Whether to add the observed-space dual solution ``alpha`` ('observation') to the
        Dataset for downstream projections; only added when set. Default: ``False``.
    
    return_state : bool
        Add the dense scattered dual matrix ``A`` ('sample','trait') and the
        ``kernel_names`` attribute, enabling marker/factor projections without refitting; only
        added when set. Trait-sized G_matrices and E_matrix are always included. Default:
        ``False``.
    
    center : bool
        Whether to subtract the observed/training mean along the modeled observation axis.
        Disable only when inputs have already been centered using training data or a
        zero-intercept model is intended. Default: ``True``. Passed to ``prepare_mvBLUP_plan``
        as ``center``.
    
    progress : bool
        Default False. True reports preparation, observed PCG solve, genetic
        propagation, residual calculation and output assembly. PCG iteration
        counts are genuine; its iteration cap is not a completion total.
    
    Returns
    -------
    xarray.Dataset
        Data variables on ('sample','trait'): breeding_value (genetic deviations),
        genetic_mean (intercept plus breeding value), residual_prediction and
        phenotype_prediction; ``components`` ('component','sample','trait') per kernel;
        ``trait_mean`` ('trait'); ``G_matrices`` ('component','trait_i','trait_j') and
        ``E_matrix`` ('trait_i','trait_j') identifying the prediction covariance; optional
        ``A``/``alpha``. Attributes: method, accuracy, accuracy_requested,
        resolved_work_dtype, operator_diagnostics, version, cg_info, cg_iterations,
        cg_relative_residual, preconditioner, optional kernel_names and (G=None)
        prediction_sparse_cv/covariance_fit.
    
    
    Examples
    --------
        prediction = mvPredict(training_traits, aligned_grm, covariance_fit,
                               accuracy='exact', return_state=True)
        predicted_outcomes = prediction['phenotype_prediction'].to_pandas()
        breeding_values = prediction['breeding_value']
    
    Complexity
    ----------
    For supplied G/E, dense-kernel PCG TIME O(I k (n²t+nt²)) plus plan preparation and preconditioning; SPACE O(k n²+nt+k t²+P). n is animals, t traits, k genetic kernels, I actual PCG iterations, and P preconditioner storage. Factor trait covariance can reduce nt² to nt r; a supplied rank-q kernel reduces n²t to nqt. Sample-block preparation costs O(n t³)/SPACE O(n t²), trait-block costs O(t n³)/SPACE O(t n²), both reduced by missing observations. With G=None add the rank-grid/CV/refit cost documented in fit_sparse_prediction_covariance. No dense (nt)² observed covariance is constructed.
    """
    traits=_as_pandas_input(traits); GRM=_kernel_input(GRM); G=_covariance_input(G); E=_as_pandas_input(E)
    covariance_fit=None
    if G is None:
        if E is not None:
            raise ValueError("E must be None when automatically fitting sparse G+E")
        from .prediction_sparse_cv import fit_sparse_prediction_covariance
        covariance_fit=fit_sparse_prediction_covariance(
            traits,GRM,covariance_cv=covariance_cv,
            optimize_hyperparameters_cv=optimize_hyperparameters_cv,
            covariance_cv_ranks=covariance_cv_ranks,covariance_kwargs=covariance_kwargs,
            hpo_trials=hpo_trials,blas_threads=blas_threads)
        covariance_view=_result_view(covariance_fit)
        G=covariance_view["G_prediction"]
        E=covariance_view["E_prediction"]
    elif covariance_kwargs is not None or optimize_hyperparameters_cv:
        raise ValueError("pre-fitted G/E cannot be simultaneously refitted or tuned; use G=None")
    operation_stage('mvPredict: preparation')
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits)
    requested_accuracy=str(accuracy).lower()
    accuracy=('fast' if len(Y)>=1024 else 'exact') if requested_accuracy=='auto' else requested_accuracy
    if accuracy not in {'exact','fast'}: raise ValueError("accuracy must be 'auto', 'exact', or 'fast'")
    plan=prepare_mvBLUP_plan(Y,GRM,G,E=E,center=center,work_dtype=work_dtype,jitter=jitter,
                            preconditioner=preconditioner,kernel_rank=kernel_rank,
                            blas_threads=blas_threads,accuracy=accuracy)
    with _v31_thread_ctx(blas_threads,'blup'):
        operation_stage('mvPredict: observed PCG solve')
        alpha,sinfo=plan.solve(rtol=solver_tol,maxiter=solver_maxiter)
        operation_stage('mvPredict: propagation')
        total,components=_predict_components(plan,alpha,out_dtype=np.float64)
    if sinfo['cg_info']!=0 or sinfo['cg_relative_residual']>max(20*solver_tol,2e-5): raise RuntimeError(f'exact mvPredict PCG did not converge: {sinfo}')
    operation_stage('mvPredict: residual')
    A=np.zeros((plan.n,plan.t),dtype=plan.dtype); A.ravel()[plan.obs_plan['flat']]=alpha; residual=_v31_apply_residual(A,plan.E_spec).astype(float,copy=False)
    operation_stage('mvPredict: output')
    means=np.asarray(plan.means,float); fixed=means[None,:]; wrap=lambda x:pd.DataFrame(x,index=Y.index,columns=Y.columns)
    out={'trait_mean':pd.Series(means,index=Y.columns),'breeding_value':wrap(total),'genetic_mean':wrap(fixed+total),
         'residual_prediction':wrap(residual),'phenotype_prediction':wrap(fixed+total+residual),
         'components':{name:wrap(value) for name,value in components.items()},
         'method':('exact_observed_gaussian_conditioning' if plan.accuracy=='exact' else 'observed_gaussian_conditioning_fast'),
         'accuracy':plan.accuracy,'accuracy_requested':requested_accuracy,'resolved_work_dtype':str(np.dtype(plan.dtype)),
         'operator_diagnostics':plan.operator_diagnostics,
         'version':VIGOR_MULTIVARIATE_VERSION,**sinfo}
    # Cheap trait-sized metadata identifies the covariance used for downstream
    # posterior-factor projections even when the large dual state is omitted.
    out['G_matrices']={name:plan.G_specs[name].materialize() for name in plan.kernels}
    out['E_matrix']=plan.E_spec.materialize()
    if covariance_fit is not None:
        out["prediction_sparse_cv"]=covariance_view["prediction_sparse_cv"]
        out["covariance_fit"]=covariance_fit
