def _local_grm_from_snps(snps, *, dtype=np.float32):
    """GRM numerator/denominator compatible with npplink.GRM weighted subtraction.

    Parameters
    ----------
    snps : array-like or pandas.DataFrame
        Genotype values with animals in rows and variants in columns, or the genotype source
        accepted by this entry point. Biallelic dosage uses 0/1/2; preserve sample/variant
        labels and the coding expected by the selected kernel or association model.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float32``. Passed to ``np.zeros`` as ``dtype``.
    """
    X=snps.to_numpy(float) if isinstance(snps,pd.DataFrame) else np.asarray(snps,float)
    n,m=X.shape
    if m < 2:
        return {'grm':np.zeros((n,n),dtype=dtype),'w':np.zeros((n,n),dtype=dtype),'zzt':np.zeros((n,n),dtype=dtype)}
    obs=np.isfinite(X); cnt=obs.sum(0); mu=np.divide(np.nansum(X,0),cnt,out=np.zeros(m),where=cnt>0)
    Z=X-mu[None,:]; ss=np.nansum(Z*Z,0); sd=np.sqrt(np.divide(ss,cnt,out=np.ones(m),where=cnt>0)); sd[~np.isfinite(sd)|(sd<=0)]=1.
    Z=np.where(obs,Z/sd[None,:],0.0).astype(dtype,copy=False)
    M=obs.astype(dtype,copy=False); zzt=Z@Z.T; counts=M@M.T; w=np.maximum(counts-1.0,1.0)
    grm=np.divide(zzt,w,out=np.zeros_like(zzt),where=w>0)
    return {'grm':grm,'w':w,'joint_count':counts,'zzt':zzt}


def _subtract_local_grm(allg, local):
    """Return the subtract local genomic relationship matrix result computed by ``_symmetrize``.

    Parameters
    ----------
    allg : array-like or numeric scalar
        Input for the operation ``np.asarray(allg['grm'], float) * np.asarray(allg['w'], float)
        - np.asarray(local['zzt'], float)``. See ``vigor.multivariate._subtract_local_grm`` and
        its caller for the scientific representation; the shown operation constrains the
        required type/shape.

    local : array-like or numeric scalar
        Input for the operation ``np.asarray(allg['grm'], float) * np.asarray(allg['w'], float)
        - np.asarray(local['zzt'], float)``. See ``vigor.multivariate._subtract_local_grm`` and
        its caller for the scientific representation; the shown operation constrains the
        required type/shape.
    """
    num=np.asarray(allg['grm'],float)*np.asarray(allg['w'],float)-np.asarray(local['zzt'],float)
    # Existing GRMs use count-c (typically c=1 per GRM component). Removing q SNPs
    # changes the denominator by q, not by q-1, so subtract raw joint counts.
    q=np.asarray(local.get('joint_count',np.asarray(local['w'],float)+1.0),float)
    den=np.asarray(allg['w'],float)-q
    K=np.divide(num,den,out=np.zeros_like(num),where=den>1)
    return _symmetrize(K)





