def simulate_hs_genotypes(n=800,n_snps=2400,n_chromosomes=20,n_founders=8,chromosome_length_mb=100.,
                          recombination_rate_cM_per_mb=.5,generations=80,maf_floor=.03,random_state=0,
                          return_founders=False):
    """Founder-mosaic genotype simulation approximating an advanced-intercross/HS population.

    Parameters
    ----------
    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit. Default: ``800``. Passed to ``rng.integers``
        as ``size``.

    n_snps : int or None
        Count limit for the corresponding sampled/retained/displayed items. Positive values
        bound work/output size; None uses all eligible items or the local default where
        supported. Default: ``2400``.

    n_chromosomes : int
        Input for the operation ``int(n_chromosomes)``. See
        ``vigor.multivariate.simulate_hs_genotypes`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default: ``20``.

    n_founders : int
        Input for the operation ``int(n_founders)``. See
        ``vigor.multivariate.simulate_hs_genotypes`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default: ``8``.

    chromosome_length_mb : float
        Physical span in megabases controlling the region, exclusion or sliding-window step
        named by this argument. Positive values determine extent; convert consistently with the
        variant base-pair coordinates. Default: ``100.0``.

    recombination_rate_cM_per_mb : float
        Physical-to-genetic map rate in centimorgans per megabase, used when approximating
        linkage/recombination from physical positions; positive values specify a nondegenerate
        map. Default: ``0.5``.

    generations : int or float
        Number of generations over which recombination attenuates linkage; nonnegative values
        scale the map-derived probability. Default: ``80``.

    maf_floor : float
        Input for the operation ``1 - float(maf_floor)``. See
        ``vigor.multivariate.simulate_hs_genotypes`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``0.03``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``.

    return_founders : bool
        Whether to enforce/use complete observations or include the named
        decomposition/component output. The enabled branch below defines the returned
        representation; disabling skips that optional step. Default: ``False``.

    Returns
    -------
    object
        Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
    """
    rng=np.random.default_rng(random_state); n=int(n); m=int(n_snps); C=int(n_chromosomes); F=int(n_founders)
    per=np.full(C,m//C,int); per[:m%C]+=1; chrom=np.repeat(np.arange(1,C+1),per); pos=np.concatenate([np.linspace(1,float(chromosome_length_mb)*1e6,k,dtype=int) for k in per])
    # Founder allele frequencies are heterogeneous; reject monomorphic/near-fixed variants.
    p=rng.beta(.8,.8,m); p=np.clip(p,float(maf_floor),1-float(maf_floor)); founders=(rng.random((F,m))<p).astype(np.int8)
    bad=(founders.sum(0)==0)|(founders.sum(0)==F)
    while bad.any(): founders[:,bad]=(rng.random((F,bad.sum()))<p[bad]).astype(np.int8); bad=(founders.sum(0)==0)|(founders.sum(0)==F)
    H=np.empty((2*n,m),np.int8); offset=0
    for ci,k in enumerate(per):
        ix=slice(offset,offset+k); cm=np.linspace(0,float(chromosome_length_mb)*float(recombination_rate_cM_per_mb),k); dm=np.diff(cm)/100.; psw=1-np.exp(-float(generations)*dm)
        state=rng.integers(0,F,size=2*n); H[:,offset]=founders[state,offset]
        for j in range(1,k):
            sw=rng.random(2*n)<psw[j-1]
            if sw.any():
                new=rng.integers(0,F-1,size=sw.sum()); old=state[sw]; new += (new>=old); state[sw]=new
            H[:,offset+j]=founders[state,offset+j]
        offset+=k
    X=H[0::2].astype(np.float32)+H[1::2].astype(np.float32); names=[f'{c}:{p}' for c,p in zip(chrom,pos)]
    df=pd.DataFrame(X,index=[f'rat{i:05d}' for i in range(n)],columns=names)
    meta=pd.DataFrame({'snp':names,'chrom':chrom.astype(str),'pos':pos,'founder_af':founders.mean(0)}).set_index('snp')
    out={'genotypes':df,'variant_info':meta}
    if return_founders:out['founders']=pd.DataFrame(founders,columns=names,index=[f'F{i+1}' for i in range(F)])
    return out


def _std_component(A,eps=1e-12):
    """Normalize a simulated genetic/environmental component to its target scale.

    Parameters
    ----------
    A : array-like
        Numerical operand in ``A - np.mean(A, axis=0, keepdims=True)``. Shape must conform to
        that matrix/vector operation and the enclosing prepared state.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.
    """
    A=np.asarray(A,float); A=A-np.mean(A,axis=0,keepdims=True); s=np.std(A,axis=0,ddof=1,keepdims=True); return A/np.where(s>eps,s,1.)



