    if isinstance(obj,pd.Series):
        s=pd.to_numeric(obj,errors='coerce');s.index=s.index.astype(str);return s.groupby(level=0).max().reindex(snps).fillna(0.)
    d=obj.copy();key=snp_col if snp_col in d.columns else ('SNP' if 'SNP' in d.columns else ('SNP_QTL' if 'SNP_QTL' in d.columns else None))
    if key is not None:d=d.set_index(key)
    d.index=d.index.astype(str); k=str(kind).lower()
    if k=='coding':
        cons=next((c for c in d.columns if c.lower() in {'consequence','annotation','impact','most_severe_consequence'}),None)
        if cons is not None:
            x=d[cons].astype(str).str.lower();score=pd.Series(.02,index=d.index)
            rules=[(('stop_gained','frameshift','splice_acceptor','splice_donor','transcript_ablation'),1.0),
                   (('missense','protein_altering','inframe'),.75),(('splice_region',),.65),(('synonymous',),.20),
                   (('utr','regulatory','promoter'),.15),(('intron','intergenic'),.03)]
            for pats,val in rules:
                mask=np.zeros(len(x),bool)
                for p in pats:mask|=x.str.contains(p,regex=False).to_numpy()
                score.loc[mask]=np.maximum(score.loc[mask],val)
            return score.groupby(level=0).max().reindex(snps).fillna(0.)
    num=d.select_dtypes(include=[np.number]).copy()
    if num.empty:return pd.Series(1.,index=d.index).groupby(level=0).max().reindex(snps).fillna(0.)
    vals=[]
    for c in num.columns:
        x=pd.to_numeric(num[c],errors='coerce');cl=c.lower()
        if cl in {'p','pval','pvalue'} or ('_p' in cl and 'log' not in cl):x=-np.log10(np.clip(x,1e-300,1.))
