    if A.ndim!=2: raise ValueError('X must be samples x variants')
    names=list(map(str,X.columns)) if isinstance(X,pd.DataFrame) else (list(map(str,feature_names)) if feature_names is not None else [f'v{i}' for i in range(A.shape[1])])
    if len(names)!=A.shape[1]: raise ValueError('feature_names length does not match X')
    cl=ld_clusters.copy();cl.index=cl.index.astype(str)
    lab=cl.reindex(names).ld_group
    miss=lab.isna().to_numpy(); lab=lab.astype(object)
    for i in np.flatnonzero(miss): lab.iloc[i]=f'singleton_{i}'
    labels=list(pd.unique(lab.astype(str))); groups=[np.flatnonzero(lab.astype(str).to_numpy()==g) for g in labels]
    rng=np.random.default_rng(random_state); n=A.shape[0]
    take=np.arange(n) if max_samples is None or n<=int(max_samples) else np.sort(rng.choice(n,int(max_samples),replace=False))
    E=A[take]
    if len(set(names))!=len(names):raise ValueError('X variant labels must be unique')
    if isinstance(background,pd.DataFrame):
        background=background.copy();background.columns=background.columns.map(str)
        if not background.columns.is_unique or set(background.columns)!=set(names):
            raise ValueError('background must contain exactly the unique X variant labels')
        background=background.reindex(columns=names)
    B=A if background is None else (background.to_numpy(float) if isinstance(background,pd.DataFrame) else np.asarray(background,float))
    if B.ndim!=2 or B.shape[1]!=A.shape[1]: raise ValueError('background must have the same variant columns as X')
    def pred(Z):
        """Compute predictions from the captured fitted model state.

        Parameters
        ----------
        Z : array-like
            Sample × variant numerical coding used in genotype moments. Raw inputs use biallelic
            dosage; centered/additive/dominance inputs must already follow the coding named by this
            operation. Missing entries are represented by the accompanying mask or NaN policy.

        Returns
        -------
        object
            Computed result from ``q[:, None] if q.ndim == 1 else q``; see the summary and the called implementation for its labeled/numerical representation.
        """
