def _sym(M):
    """Return the arithmetic symmetrization (M + M.T)/2.

    Parameters
    ----------
    M : array-like
        Numerical operand in ``0.5 * (M + M.T)``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.
    """
    M = np.asarray(M)
    return 0.5 * (M + M.T)


def _softplus(x):
    """Evaluate a stable positive transform for unconstrained variance coordinates.

    Parameters
    ----------
    x : array-like
        Numerical operand in ``np.log1p(np.exp(-np.abs(x))) + np.maximum(x, 0.0)``. Shape must
        conform to that matrix/vector operation and the enclosing prepared state.
    """
    x = np.asarray(x, dtype=float)
    return np.log1p(np.exp(-np.abs(x))) + np.maximum(x, 0.0)


def _inv_softplus(y):
    """Return the inv softplus result computed by ``np.where``.

    Parameters
    ----------
    y : array-like
        Numerical operand in ``np.maximum(np.asarray(y, dtype=float), 1e-12)``. Shape must
        conform to that matrix/vector operation and the enclosing prepared state. Source
        comparisons: ``y > 30.0``. See the rejection/fallback branches for enforcement.
    """
    y = np.maximum(np.asarray(y, dtype=float), 1e-12)
    # inverse of log(1 + exp(x)); stable for large y
    return np.where(y > 30.0, y, np.log(np.expm1(y)))


def _sigmoid(x):
    """Evaluate the logistic transform for variance-coordinate derivatives.

    Parameters
    ----------
    x : array-like
        Numerical operand in ``1.0 / (1.0 + np.exp(-x[pos]))``. Shape must conform to that
        matrix/vector operation and the enclosing prepared state. Source comparisons: ``x >=
        0``. See the rejection/fallback branches for enforcement.
    """
    x = np.asarray(x, dtype=float)
    out = np.empty_like(x)
    pos = x >= 0
    out[pos] = 1.0 / (1.0 + np.exp(-x[pos]))
    z = np.exp(x[~pos])
    out[~pos] = z / (1.0 + z)
    return out


