class KernelOperator:
    """Small GRM operator contract used by both mvBLUP and mvGWAS."""

    shape: tuple[int, int]
    dtype: np.dtype

    def matmat(self, X):  # pragma: no cover - abstract
        """Apply the enclosing covariance/kernel operator to multiple right-hand sides.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.
        """
        raise NotImplementedError

    def diag(self):  # pragma: no cover - abstract
        """Return the diagonal variances of the represented covariance/kernel.
        """
        raise NotImplementedError

    def row_block(self, start: int, stop: int):  # pragma: no cover - abstract
        """Retrieve the requested contiguous animal rows of the represented kernel.

        Parameters
        ----------
        start : int
            Boundary index or genomic coordinate for the requested interval. Use the coordinate
            convention of this reader/query; None leaves that boundary unrestricted where supported.

        stop : int
            Local position, index selection or step used by the stated slice/iteration. Indices must
            refer to the relevant axis; slice steps must be nonzero, and count/rank uses must match
            the enclosing dimensions.
        """
        raise NotImplementedError

    def submatrix(self, rows):
        """Retrieve the requested animal-index square/cross kernel block.

        Parameters
        ----------
        rows : sequence, index or scalar
            Axis/node identifiers or positions selected by the local lookup below. Values must refer
            to the supplied object and preserve the requested output ordering.

        Returns
        -------
        object
            Computed result from ``self.row_block(0, self.shape[0])[np.ix_(rows, rows)]``; see the summary and the called implementation for its labeled/numerical representation.
        """
        rows = np.asarray(rows, dtype=int)
        return self.row_block(0, self.shape[0])[np.ix_(rows, rows)]

    def aslinearoperator(self):
        """Return the aslinearoperator result computed by ``LinearOperator``.

        Returns
        -------
        object
            Computed result from ``LinearOperator((n, n), matvec=lambda x: self.matmat(np.asarray(x)[:, None])[:, 0], matmat=self.matmat, dtype=self.dtype)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        n = self.shape[0]
        return LinearOperator(
            (n, n),
            matvec=lambda x: self.matmat(np.asarray(x)[:, None])[:, 0],
            matmat=self.matmat,
            dtype=self.dtype,
        )




def _align_labeled_kernels_to_traits(grm, traits, *, warn_unlabeled=False):
    """Align labeled GRMs to a phenotype DataFrame before numerical conversion.

    This is an O(N) metadata check and does not alter the 2.6 operator/moment
    fast paths. Bare ndarrays remain supported for backward compatibility.

    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    warn_unlabeled : bool or str
        Annotation/report combination policy read by this routine. Boolean settings enable the
        named validation/formatting action; aggregation names select the explicit
        table-combination branch below. Default: ``False``.
    """
    grm = _kernel_input(grm)
    traits = _as_pandas_input(traits)
    if not isinstance(traits, pd.DataFrame):
        return grm
    ids = pd.Index(traits.index.astype(str))
    if ids.has_duplicates:
        raise ValueError("trait sample IDs must be unique")
    def one(K, name="GRM"):
        """Evaluate one component/replicate of the captured numerical operation.

        Parameters
        ----------
        K : array-like
            Numerical operand in ``K.copy().set_axis(ri, axis=0).set_axis(ci, axis=1).loc[ids,
            ids]``. Shape must conform to that matrix/vector operation and the enclosing prepared
            state.

        name : str
            Identifier used to select or label the relevant component, field or output quantity. It
            must match the names present in the supplied object where lookup is required. Default:
            ``'GRM'``.

        Returns
        -------
        object
            Computed result from ``K``; see the summary and the called implementation for its labeled/numerical representation.
        """
        if hasattr(K, "sample_ids"):
            ki=pd.Index(np.asarray(K.sample_ids).astype(str))
            if ki.has_duplicates:
                raise ValueError(f"{name} operator sample labels must be unique")
            if not ki.equals(ids):
                if set(ki)==set(ids):
                    raise ValueError(f"{name} operator sample order does not match traits; construct the operator with sample_ids=traits.index")
                miss=list(ids.difference(ki))[:5]
                raise ValueError(f"{name} operator sample labels do not match traits; missing examples: {miss}")
            return K
        if isinstance(K, pd.DataFrame):
            ri = pd.Index(K.index.astype(str)); ci = pd.Index(K.columns.astype(str))
            if ri.has_duplicates or ci.has_duplicates:
                raise ValueError(f"{name} sample labels must be unique")
            if set(ri) != set(ids) or set(ci) != set(ids):
                miss = list(ids.difference(ri))[:5]
                raise ValueError(f"{name} sample labels do not match traits; missing examples: {miss}")
            return K.copy().set_axis(ri, axis=0).set_axis(ci, axis=1).loc[ids, ids]
        return K
    if isinstance(grm, dict):
        return {k: one(v, str(k)) for k, v in grm.items()}
    return one(grm)


class DenseKernelOperator(KernelOperator):
    """DenseKernelOperator represents dense kernel operator.

    See ``__init__`` for complete input types, defaults and construction constraints.
    """
    def __init__(self, K, dtype=None):
        """Initialize DenseKernelOperator with the inputs and resource settings below.

        Parameters
        ----------
        K : array-like
            Numerical operand in ``np.asarray(K, dtype=dtype)``. Shape must conform to that
            matrix/vector operation and the enclosing prepared state.

        dtype : NumPy dtype or str
            Numerical element type for the corresponding output, working block or accumulated
            matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
            numerical precision. Default: ``None``. None delegates to the local fallback shown in
            this body; it is not an additional numeric/category value.
        """
        A = np.asarray(K, dtype=dtype)
        if A.ndim != 2 or A.shape[0] != A.shape[1]:
            raise ValueError("GRM must be square")
        self.K = A
        self.shape = A.shape
        self.dtype = A.dtype

    def matmat(self, X):
        """Apply the enclosing covariance/kernel operator to multiple right-hand sides.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``self.K @ X``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return self.K @ X

    def diag(self):
        """Return the diagonal variances of the represented covariance/kernel.

        Returns
        -------
        object
            Computed result from ``np.diag(self.K)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return np.diag(self.K)

    def row_block(self, start, stop):
        """Return the row block result computed by ``np.asarray``.

        Parameters
        ----------
        start : int or None
            Boundary index or genomic coordinate for the requested interval. Use the coordinate
            convention of this reader/query; None leaves that boundary unrestricted where supported.

        stop : int or index array
            Local position, index selection or step used by the stated slice/iteration. Indices must
            refer to the relevant axis; slice steps must be nonzero, and count/rank uses must match
            the enclosing dimensions.

        Returns
        -------
        object
            Computed result from ``np.asarray(self.K[int(start):int(stop), :])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return np.asarray(self.K[int(start):int(stop), :])

    def submatrix(self, rows):
        """Return the submatrix result computed by ``np.asarray``.

        Parameters
        ----------
        rows : sequence, index or scalar
            Axis/node identifiers or positions selected by the local lookup below. Values must refer
            to the supplied object and preserve the requested output ordering.

        Returns
        -------
        object
            Computed result from ``np.asarray(self.K[np.ix_(rows, rows)])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        rows = np.asarray(rows, dtype=int)
        return np.asarray(self.K[np.ix_(rows, rows)])


class LowRankKernelOperator(KernelOperator):
    """K ~= U diag(values-bulk) U' + bulk I.

    The trace-matched bulk term prevents the omitted eigenspace from being
    treated as zero.  The operator makes K @ X cost O(N q p) rather than
    O(N^2 p), including the trait-specific genetic diagonal term.
    """

    def __init__(self, U, values, *, bulk=0.0, dtype=np.float32, diagnostics=None):
        """Initialize LowRankKernelOperator with the inputs and resource settings below.

        Parameters
        ----------
        U : array-like
            Numerical operand in ``U.shape[1]``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state.

        values : array-like, table or labeled object
            Input values consumed by this conversion or analysis. Preserve the labels/axis ordering
            described in the summary; the local coercion/selection expression below defines the
            accepted representation.

        bulk : float
            Eigenvalue assigned to directions outside the retained basis. A nonnegative value
            supplies the bulk covariance contribution; zero discards that omitted-space
            contribution. Default: ``0.0``.

        dtype : NumPy dtype or str
            Numerical element type for the corresponding output, working block or accumulated
            matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
            numerical precision. Default: ``np.float32``.

        diagnostics : mapping or array-like
            Fit/operator error diagnostics consumed by this report or promotion check. Use the
            values produced by the corresponding evaluation step on the same fitted model. Default:
            ``None``. None delegates to the local fallback shown in this body; it is not an
            additional numeric/category value.
        """
        U = np.asarray(U, dtype=dtype)
        values = np.asarray(values, dtype=dtype).reshape(-1)
        if U.ndim != 2 or U.shape[1] != values.size:
            raise ValueError("U and eigenvalue dimensions do not agree")
        self.U = U
        self.values = values
        self.bulk = float(bulk)
        self.delta = values - np.asarray(self.bulk, dtype=dtype)
        self.shape = (U.shape[0], U.shape[0])
        self.dtype = U.dtype
        self.diagnostics = {} if diagnostics is None else dict(diagnostics)

    @classmethod
    def from_dense(cls, K, rank, *, dtype=np.float32, random_state=0, probe_vectors=4):
        """Construct a covariance factor specification from a dense symmetric trait matrix.

        Parameters
        ----------
        K : array-like
            Numerical input passed to ``op.diagnostics.update`` as ``diagonal_relative_error``; see
            that callable for required dimensions and matrix role. Passed to
            ``op.diagnostics.update`` as ``diagonal_relative_error``.

        rank : int, str, sequence or mapping
            Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
            or trait dimension. Full and automatic policies depend on the decomposition; see the
            rank resolver used by this routine. Passed to ``eigsh`` as ``k``.

        dtype : NumPy dtype or str
            Numerical element type for the corresponding output, working block or accumulated
            matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
            numerical precision. Default: ``np.float32``. Passed to ``cls`` as ``dtype``.

        random_state : int or None
            Seed controlling randomized sampling, folds or projections for reproducibility. None
            uses the selected random-number backend without a fixed seed. Default: ``0``.

        probe_vectors : array-like
            Sparse/sketch indexing or random-probe values used by the operator. CSR indptr indexes
            row offsets, sign supplies signed sketch weights and probes have the operator's leading
            dimension; preserve the matching index layout. Default: ``4``. Source comparisons:
            ``int(probe_vectors) > 0``. See the rejection/fallback branches for enforcement. Passed
            to ``rng.normal`` as ``size``.

        Returns
        -------
        object
            Computed result from ``op``; see the summary and the called implementation for its labeled/numerical representation.
        """
        K = _sym(np.asarray(K, dtype=float))
        n = K.shape[0]
        rank = max(1, min(int(rank), n - 1))
        if rank >= n - 1:
            w, U = np.linalg.eigh(K)
            order = np.argsort(w)[::-1]
            w, U = w[order], U[:, order]
            bulk = 0.0
        else:
            try:
                w, U = eigsh(K, k=rank, which="LA")
                order = np.argsort(w)[::-1]
                w, U = w[order], U[:, order]
            except Exception:
                # deterministic dense fallback; only used if ARPACK fails
                w0, U0 = np.linalg.eigh(K)
                order = np.argsort(w0)[::-1][:rank]
                w, U = w0[order], U0[:, order]
            omitted = max(n - rank, 1)
            bulk = max((float(np.trace(K)) - float(np.sum(w))) / omitted, 0.0)
        op = cls(U, np.maximum(w, 0.0), bulk=bulk, dtype=dtype)
        diag = op.diag()
        trace_fraction = float(np.sum(np.maximum(w, 0.0)) / max(np.trace(K), 1e-30))
        probe_error = np.nan
        if int(probe_vectors) > 0:
            rng = np.random.default_rng(random_state)
            P = rng.normal(size=(n, int(probe_vectors)))
            exact = K @ P
            approx = op.matmat(P)
            probe_error = float(np.linalg.norm(exact - approx) / max(np.linalg.norm(exact), 1e-30))
        op.diagnostics.update(
            rank=int(rank), bulk=float(bulk), trace_fraction=trace_fraction,
            probe_relative_error=probe_error,
            diagonal_relative_error=float(np.linalg.norm(np.diag(K) - diag) / max(np.linalg.norm(np.diag(K)), 1e-30)),
        )
        return op

    def matmat(self, X):
        """Apply the enclosing covariance/kernel operator to multiple right-hand sides.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``top``; see the summary and the called implementation for its labeled/numerical representation.
        """
        X = np.asarray(X)
        top = self.U @ (self.delta[:, None] * (self.U.T @ X))
        if self.bulk:
            top = top + self.bulk * X
        return top

    def diag(self):
        """Return the diagonal variances of the represented covariance/kernel.

        Returns
        -------
        object
            Computed result from ``np.asarray(d)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        d = (self.U * self.U) @ self.delta
        if self.bulk:
            d = d + self.bulk
        return np.asarray(d)

    def row_block(self, start, stop):
        """Retrieve the requested contiguous animal rows of the represented kernel.

        Parameters
        ----------
        start : int or None
            Boundary index or genomic coordinate for the requested interval. Use the coordinate
            convention of this reader/query; None leaves that boundary unrestricted where supported.

        stop : int or index array
            Local position, index selection or step used by the stated slice/iteration. Indices must
            refer to the relevant axis; slice steps must be nonzero, and count/rank uses must match
            the enclosing dimensions.

        Returns
        -------
        object
            Computed result from ``B``; see the summary and the called implementation for its labeled/numerical representation.
        """
        start, stop = int(start), int(stop)
        B = (self.U[start:stop] * self.delta[None, :]) @ self.U.T
        if self.bulk:
            rr = np.arange(start, stop)
            B[np.arange(stop - start), rr] += self.bulk
        return B

    def submatrix(self, rows):
        """Retrieve the requested animal-index square/cross kernel block.

        Parameters
        ----------
        rows : sequence, index or scalar
            Axis/node identifiers or positions selected by the local lookup below. Values must refer
            to the supplied object and preserve the requested output ordering.

        Returns
        -------
        object
            Computed result from ``A``; see the summary and the called implementation for its labeled/numerical representation.
        """
        rows = np.asarray(rows, dtype=int)
        U = self.U[rows]
        A = (U * self.delta[None, :]) @ U.T
        if self.bulk:
            A.flat[:: len(rows) + 1] += self.bulk
        return A


def as_kernel_operator(K, *, rank=None, dtype=np.float32, random_state=0):
    """Convert inputs to kernel operator.

    Parameters
    ----------
    K : array-like
        Numerical input passed to ``LowRankKernelOperator`` as ``bulk``; see that callable for
        required dimensions and matrix role. Source-recognized literal values: ``eigh``,
        ``full``, ``low_rank``, ``lowrank``. These select the corresponding branches below;
        comparison evidence alone does not establish an exhaustive enum. Passed to
        ``LowRankKernelOperator`` as ``bulk``.

    rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value.
        Source-recognized literal values: ``full``. These select the corresponding branches
        below; comparison evidence alone does not establish an exhaustive enum. Source
        comparisons: ``rank not in {None, 'full', False, 0}``. See the rejection/fallback
        branches for enforcement.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float32``. Passed to ``LowRankKernelOperator`` as
        ``dtype``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``LowRankKernelOperator.from_dense`` as ``random_state``.

    Returns
    -------
    object
        Computed result from ``DenseKernelOperator(K, dtype=dtype)``; see the summary and the called implementation for its labeled/numerical representation.
    """
    if isinstance(K, KernelOperator):
        return K
    if isinstance(K, dict):
        typ = str(K.get("type", "")).lower()
        if typ in {"eigh", "lowrank", "low_rank"}:
            U = K.get("vectors", K.get("U"))
            s = K.get("values", K.get("s"))
            return LowRankKernelOperator(U, s, bulk=float(K.get("bulk", K.get("residual_eigenvalue", 0.0))), dtype=dtype)
        if typ == "full":
            K = K["matrix"]
    if isinstance(K, tuple) and len(K) >= 3 and str(K[0]).lower() in {"eigh", "lowrank", "low_rank"}:
        return LowRankKernelOperator(K[2], K[1], bulk=float(K[3]) if len(K) > 3 else 0.0, dtype=dtype)
    if hasattr(K, "matmat") and hasattr(K, "diag") and hasattr(K, "shape"):
        return K
    if rank not in {None, "full", False, 0}:
        return LowRankKernelOperator.from_dense(K, int(rank), dtype=dtype, random_state=random_state)
    return DenseKernelOperator(K, dtype=dtype)


def _resolve_kernel_rank(rank, n):
    """Resolve kernel rank.

    Parameters
    ----------
    rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Source-recognized literal values: ``auto``,
        ``full``. These select the corresponding branches below; comparison evidence alone does
        not establish an exhaustive enum. Source comparisons: ``rank in {None, False, 0,
        'full'}``. See the rejection/fallback branches for enforcement.

    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit. Source comparisons: ``n <= 4000``. See the
        rejection/fallback branches for enforcement.
    """
    if rank in {None, False, 0, "full"}:
        return None
    if isinstance(rank, str) and rank.lower() == "auto":
        if n <= 4000:
            return None
        return min(n - 1, max(128, min(1000, int(math.ceil(4.0 * math.sqrt(n))))))
    return max(1, min(int(rank), n - 1))


# ---------------------------------------------------------------------------
# Trait covariance specifications
# ---------------------------------------------------------------------------
@dataclass
class FactorCovarianceSpec:
    """FactorCovarianceSpec represents factor covariance spec.

    Attributes
    ----------
    factor : np.ndarray
        Stored factor; its axis/order follows the construction inputs.
    diag_specific : np.ndarray
        Stored diag specific; its axis/order follows the construction inputs.
    name : str
        Stored name; its axis/order follows the construction inputs.
    support_mask : np.ndarray | None
        Stored support mask; its axis/order follows the construction inputs.
    structure : str
        Stored structure; its axis/order follows the construction inputs.
    rotation : str | None
        Stored rotation; its axis/order follows the construction inputs.

    Constructor fields
    ------------------
    factor : np.ndarray
        Trait × factor loadings F defining covariance F F.T + diag(diag_specific). Required
        construction field.

    diag_specific : np.ndarray
        Nonnegative trait-specific variance vector with one entry per loading row. Required
        construction field.

    name : str
        Stored name supplied by the corresponding fitting/planning routine. See that routine for
        the result-axis/value contract. Default: ``'covariance'``.

    support_mask : np.ndarray | None
        Boolean trait × factor support mask; fixed zeros define the selected sparse tangent.
        Default: ``None``.

    structure : str
        Factor geometry 'fa', 'pca', 'sparse_fa' or 'sparse_pca', interpreted by the covariance
        normalizer. Default: ``'fa'``.

    rotation : str | None
        Recorded factor orientation; None leaves it unspecified, 'varimax' indicates the
        selected orthogonal rotation. Default: ``None``.
    """
    factor: np.ndarray
    diag_specific: np.ndarray
    name: str = "covariance"
    support_mask: np.ndarray | None = None
    structure: str = "fa"
    rotation: str | None = None

    def __post_init__(self):
        """Validate/coerce the constructed dataclass fields for subsequent model operations.
                
        """
        self.factor = np.asarray(self.factor, dtype=float)
        self.diag_specific = np.asarray(self.diag_specific, dtype=float).reshape(-1)
        if self.factor.ndim != 2 or self.factor.shape[0] != self.diag_specific.size:
            raise ValueError("factor and specific diagonal dimensions do not agree")
        if np.any(self.diag_specific < -1e-12):
            raise ValueError("specific variances must be non-negative")
        self.diag_specific = np.maximum(self.diag_specific, 0.0)
        if self.support_mask is not None:
            self.support_mask = np.asarray(self.support_mask, dtype=bool)
            if self.support_mask.shape != self.factor.shape:
                raise ValueError("support_mask must have the same shape as factor")
        self.structure = str(self.structure).lower()
        if self.rotation is not None:
            self.rotation = str(self.rotation).lower()

    @property
    def rank(self):
        """Return the rank result computed by ``int``.

        Returns
        -------
        object
            Computed result from ``int(self.factor.shape[1])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return int(self.factor.shape[1])

    @property
    def n_traits(self):
        """Return the n traits result computed by ``int``.

        Returns
        -------
        object
            Computed result from ``int(self.factor.shape[0])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return int(self.factor.shape[0])

    def diagonal(self):
        """Return represented marginal variances, including factor and specific-diagonal contributions.

        Returns
        -------
        object
            Computed result from ``np.einsum('ij,ij->i', self.factor, self.factor) + self.diag_specific``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return np.einsum("ij,ij->i", self.factor, self.factor) + self.diag_specific

    def materialize(self):
        """Return the materialize result computed by ``_sym``.

        Returns
        -------
        object
            Computed result from ``_sym(self.factor @ self.factor.T + np.diag(self.diag_specific))``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return _sym(self.factor @ self.factor.T + np.diag(self.diag_specific))

    def apply_right(self, A):
        """Apply right.

        Parameters
        ----------
        A : array-like
            Numerical input passed to ``np.zeros_like`` as ``dtype``; see that callable for required
            dimensions and matrix role. Passed to ``np.zeros_like`` as ``dtype``.

        Returns
        -------
        object
            Computed result from ``Z``; see the summary and the called implementation for its labeled/numerical representation.
        """
        A = np.asarray(A)
        Z = np.zeros_like(A, dtype=np.result_type(A.dtype, self.factor.dtype))
        if self.rank:
            Z += (A @ self.factor) @ self.factor.T
        if np.any(self.diag_specific):
            Z += A * self.diag_specific[None, :]
        return Z

    def to_dict(self, *, include_matrix=True):
        """Serialize the object's numerical factors/configuration into the supported mapping schema.

        Parameters
        ----------
        include_matrix : bool
            Whether to enforce/use complete observations or include the named
            decomposition/component output. The enabled branch below defines the returned
            representation; disabling skips that optional step. Default: ``True``.

        Returns
        -------
        object
            Computed result from ``d``; see the summary and the called implementation for its labeled/numerical representation.
        """
        d = {
            "factor": np.asarray(self.factor),
            "diag": np.asarray(self.diag_specific),
            "rank": self.rank,
            "specific": bool(np.any(self.diag_specific > 0)),
            "parameterization": "factor_analytic",
            "structure": self.structure,
            "rotation": self.rotation,
            "support_mask": None if self.support_mask is None else np.asarray(self.support_mask, dtype=bool),
            "loading_density": (1.0 if self.support_mask is None else float(np.mean(self.support_mask)) if self.support_mask.size else 0.0),
        }
        if include_matrix:
            d["matrix"] = self.materialize()
        return d


def as_covariance_spec(C, *, name="covariance"):
    """Convert inputs to covariance spec.

    Parameters
    ----------
    C : array-like
        Numerical input passed to ``FactorCovarianceSpec`` as ``support_mask``; see that
        callable for required dimensions and matrix role. Passed to ``FactorCovarianceSpec`` as
        ``support_mask``.

    name : str
        Identifier used to select or label the relevant component, field or output quantity. It
        must match the names present in the supplied object where lookup is required. Default:
        ``'covariance'``. Passed to ``FactorCovarianceSpec`` as ``name``.

    Returns
    -------
    object
        Computed result from ``FactorCovarianceSpec(F, np.zeros(M.shape[0]), name=name)``; see the summary and the called implementation for its labeled/numerical representation.
    """
    if isinstance(C, FactorCovarianceSpec):
        return C
    C = _covariance_input(C)
    if isinstance(C, pd.Series) and "G_spec" in C:
        C = C["G_spec"]
    if isinstance(C, pd.DataFrame):
        attr = C.attrs.get("domino_covspec", C.attrs.get("v31_spec"))
        if attr is not None:
            C = attr
        else:
            C = C.to_numpy(float)
    if isinstance(C, dict):
        if "factor" in C:
            F = np.asarray(C.get("factor"), float)
            d = np.asarray(C.get("diag", np.zeros(F.shape[0])), float)
            return FactorCovarianceSpec(
                F, d, name=name, support_mask=C.get("support_mask", None),
                structure=C.get("structure", "fa"), rotation=C.get("rotation", None),
            )
        if "matrix" in C:
            C = C["matrix"]
    M = _sym(np.asarray(C, dtype=float))
    w, V = np.linalg.eigh(M)
    keep = w > max(1e-12, 1e-10 * max(float(np.max(w)), 1.0))
    F = V[:, keep] * np.sqrt(np.maximum(w[keep], 0.0))[None, :]
    return FactorCovarianceSpec(F, np.zeros(M.shape[0]), name=name)


def _rank_value(rank, T):
    """Resolve full/diagonal rank spellings and clip numerical ranks to the trait dimension.

    Parameters
    ----------
    rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Source-recognized literal values: ``diag``,
        ``full``. These select the corresponding branches below; comparison evidence alone does
        not establish an exhaustive enum.

    T : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.
    """
    if rank in {None, "full"}:
        return T
    if isinstance(rank, str) and rank.lower() == "diag":
        return 0
    return max(0, min(T, int(rank)))


def _initial_fa_spec(C, rank, *, eps=1e-8, warm=None, name="covariance"):
    """Initialize factor loadings and specific variances from a symmetric covariance or warm start.

    Parameters
    ----------
    C : array-like
        Numerical operand in ``C.shape[0]``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.

    rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Source comparisons: ``rank == 0``. See the
        rejection/fallback branches for enforcement.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_legacy._project_psd`` as ``eps``.

    warm : object (see the cited input contract)
        Input for the operation ``as_covariance_spec(warm, name=name)``. See
        ``vigor.multivariate._initial_fa_spec`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.

    name : str
        Identifier used to select or label the relevant component, field or output quantity. It
        must match the names present in the supplied object where lookup is required. Default:
        ``'covariance'``. Passed to ``as_covariance_spec`` as ``name``.
    """
    T = C.shape[0]
    rank = _rank_value(rank, T)
    if warm is not None:
        ws = as_covariance_spec(warm, name=name)
        # The common bootstrap case has unchanged rank: reuse the fitted
        # factors directly for a true optimizer warm start.  If rank changes,
        # re-factor the warm covariance; padding new factor columns with zeros
        # would make those columns a stationary point (grad ~ M@F) and prevent
        # the higher-rank model from using them.
        if rank == 0:
            return FactorCovarianceSpec(np.zeros((T, 0)), np.maximum(ws.diagonal(), eps), name=name)
        if ws.rank == rank:
            psi = np.zeros(T) if rank >= T else np.maximum(np.asarray(ws.diag_specific, float), eps)
            return FactorCovarianceSpec(np.asarray(ws.factor, float).copy(), psi, name=name)
        M = ws.materialize()
    else:
        M = _sym(np.nan_to_num(C, nan=0.0))
    M = _legacy._project_psd(M, eps=max(eps, 1e-12))
    if rank == 0:
        return FactorCovarianceSpec(np.zeros((T, 0)), np.maximum(np.diag(M), eps), name=name)
    w, V = np.linalg.eigh(M)
    order = np.argsort(w)[::-1]
    w, V = np.maximum(w[order], 0.0), V[:, order]
    r = min(rank, T)
    F = V[:, :r] * np.sqrt(w[:r])[None, :]
    if r >= T:
        psi = np.zeros(T)
    else:
        psi = np.maximum(np.diag(M - F @ F.T), eps)
    return FactorCovarianceSpec(F, psi, name=name)


# ---------------------------------------------------------------------------
# Moment construction and native FA fitting
# ---------------------------------------------------------------------------
@cached_moments
def _single_moments(K, traits, **kwargs):
    """Build one-kernel genetic/residual moment tensors from pairwise-observed traits.

    Parameters
    ----------
    K : array-like
        Numerical operand in ``_legacy.grm_moment_matrices_einsum(K, traits, **kwargs)``. Shape
        must conform to that matrix/vector operation and the enclosing prepared state.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    **kwargs : mapping
        Additional keyword arguments forwarded to ``_legacy.grm_moment_matrices_einsum``. See
        those callables for accepted keys and values. Passed to
        ``_legacy.grm_moment_matrices_einsum`` as ``**expanded mapping``.
    """
    mom = _legacy.grm_moment_matrices_einsum(K, traits, **kwargs)
    T = traits.shape[1]
    A = np.empty((2, 2, T, T), dtype=np.result_type(mom["A11"], np.float64))
    B = np.empty((2, T, T), dtype=A.dtype)
    A[0, 0], A[0, 1], A[1, 0], A[1, 1] = mom["A11"], mom["A12"], mom["A12"], mom["A22"]
    B[0], B[1] = mom["B1"], mom["B2"]
    return {"A": A, "B": B, "Y0": mom["Y0"], "R": mom["R"], "kernel_names": ["genetic"]}



def _phenotypic_variance_moment(traits, sample_weights=None, *, eps=1e-12):
    """Observed marginal trait variance and Gaussian moment precision.

    The phenotypic variance is an additional directly observed second moment.
    For Gaussian data, ``Var(s^2) ~= 2 Vp^2 / (n-1)``; its inverse therefore
    provides a natural information weight for a *soft* marginal-variance
    closure term.  Missing values are handled trait by trait.  Bootstrap count
    vectors can be supplied through ``sample_weights`` so each replicate uses
    its own observed-variance moment rather than the full-data target.

    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    sample_weights : one-dimensional array-like
        Weights for animals or observed trait marginal variances as named. Length follows the
        respective sample/trait axis; weights are nonnegative and variances use the observation
        scale. Default: ``None``. None delegates to the local fallback shown in this body; it is
        not an additional numeric/category value.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.
    """
    Y = traits.to_numpy(float) if isinstance(traits, pd.DataFrame) else np.asarray(traits, float)
    n, T = Y.shape
    w = np.ones(n, dtype=float) if sample_weights is None else np.asarray(sample_weights, float).reshape(-1)
    if w.size != n:
        raise ValueError('sample_weights must have one value per animal')
    obs = np.isfinite(Y)
    ww = obs * w[:, None]
    nobs = ww.sum(axis=0)
    Y0 = np.where(obs, Y, 0.0)
    mean = np.divide((ww * Y0).sum(axis=0), nobs, out=np.full(T, np.nan), where=nobs > 0)
    ss = (ww * np.where(obs, (Y - mean[None, :])**2, 0.0)).sum(axis=0)
    vp = np.divide(ss, nobs - 1.0, out=np.full(T, np.nan), where=nobs > 1.0)
    positive = vp[np.isfinite(vp) & (vp > 0)]
    scale = float(np.nanmedian(positive)) if positive.size else 1.0
    floor = max(float(eps), scale * 1e-12)
    var_s2 = np.divide(2.0 * np.maximum(vp, floor)**2, np.maximum(nobs - 1.0, 1.0),
                       out=np.full(T, np.inf), where=nobs > 1.0)
    precision = np.divide(1.0, var_s2, out=np.zeros(T), where=np.isfinite(var_s2) & (var_s2 > 0))
    precision[~np.isfinite(vp) | (nobs < 3)] = 0.0
    return {'variance': vp, 'nobs': nobs, 'se': np.sqrt(var_s2), 'precision': precision}


def _augment_moments_variance_closure(moments, target, weight):
    """Add ``sum_i weight_i (sum_c Cc[ii]-Vp_i)^2`` to the MoM objective.

    On each diagonal trait entry this is exactly the rank-one augmentation
    ``A_i <- A_i + lambda_i 11'`` and ``B_i <- B_i + lambda_i Vp_i 1``.
    It therefore works identically for spectral, L-BFGS and multi-kernel fits
    and remains a soft moment rather than an equality constraint.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    target : str, index or sequence
        Response/trait identifiers selected for this prediction, mediation or subset operation.
        Names/positions must exist in the supplied response axes; sequences preserve the
        requested ordering.

    weight : object (see the cited input contract)
        Input for the operation ``weight[i]``. See
        ``vigor.multivariate._augment_moments_variance_closure`` and its caller for the
        scientific representation; the shown operation constrains the required type/shape.
        Source comparisons: ``lam > 0``. See the rejection/fallback branches for enforcement.
    """
    A=np.asarray(moments['A'],float).copy(); B=np.asarray(moments['B'],float).copy()
    target=np.asarray(target,float).reshape(-1); weight=np.asarray(weight,float).reshape(-1)
    p=A.shape[0]; T=A.shape[-1]
    if target.size!=T or weight.size!=T:
        raise ValueError('variance closure target/weight length must match number of traits')
    for i in range(T):
        lam=float(weight[i])
        if not (np.isfinite(lam) and lam>0 and np.isfinite(target[i])):
            continue
        A[:,:,i,i] += lam
        B[:,i,i] += lam*float(target[i])
    out=dict(moments); out['A']=A; out['B']=B
    out['variance_closure_target']=target.copy(); out['variance_closure_weight']=weight.copy()
    return out


def _variance_boundary_diagnostics(G, E, phenotypic_variance, *, rtol=1e-8, atol=1e-12):
    """Scale-relative variance boundaries and marginal-variance closure QA.

    Parameters
    ----------
    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance.

    phenotypic_variance : one-dimensional array-like
        Weights for animals or observed trait marginal variances as named. Length follows the
        respective sample/trait axis; weights are nonnegative and variances use the observation
        scale.

    rtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-08``.

    atol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-12``.
    """
    G=_sym(np.asarray(G,float)); E=_sym(np.asarray(E,float))
    vg=np.maximum(np.diag(G),0.0); ve=np.maximum(np.diag(E),0.0); total=vg+ve
    vp=np.asarray(phenotypic_variance,float).reshape(-1)
    finite_pos=vp[np.isfinite(vp)&(vp>0)]
    global_scale=float(np.nanmedian(finite_pos)) if finite_pos.size else max(float(np.nanmedian(total)),1.0)
    local=np.maximum.reduce([np.nan_to_num(vp,nan=0.0), total, np.full_like(total,global_scale)])
    tol=np.maximum(float(atol),float(rtol)*np.maximum(local,float(atol)))
    g0=np.isfinite(vg)&(vg<=tol); e0=np.isfinite(ve)&(ve<=tol); t0=np.isfinite(total)&(total<=tol)
    closure=np.divide(total,vp,out=np.full_like(total,np.nan),where=np.isfinite(vp)&(vp>tol))
    h_model=np.divide(vg,total,out=np.full_like(vg,np.nan),where=~t0)
    h_pheno=np.divide(vg,vp,out=np.full_like(vg,np.nan),where=np.isfinite(vp)&(vp>tol))
    nanz=np.full_like(total,np.nan)
    return {
        'G_near_zero':g0,'E_near_zero':e0,'total_near_zero':t0,'tolerance':tol,
        'phenotypic_variance_observed':vp,'phenotypic_variance_model':total,
        'variance_closure_ratio':closure,'variance_closure_error':total-vp,
        'h2_model':h_model,'h2_phenotype':h_pheno,
        'G_exceeds_phenotypic_variance':np.isfinite(vp)&(vg>vp+tol),
    }


def _mask_rg_at_variance_boundary(Rg, boundary):
    """Mask genetic correlation at variance boundary.

    Parameters
    ----------
    Rg : array-like
        Genetic correlation or genetic/residual marginal variance quantity for the indicated
        component. Correlations align trait pairs; marginal variances align trait order and must
        support the boundary-aware transformation.

    boundary : array-like or numeric scalar
        Input for the operation ``np.asarray(boundary['G_near_zero'], bool) |
        np.asarray(boundary['total_near_zero'], bool)``. See
        ``vigor.multivariate._mask_rg_at_variance_boundary`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.
    """
    R=np.asarray(Rg,float).copy(); bad=np.asarray(boundary['G_near_zero'],bool)|np.asarray(boundary['total_near_zero'],bool)
    pair=bad[:,None]|bad[None,:]
    R[pair]=np.nan
    # A genetic self-correlation is only meaningful when genetic variance is estimable.
    for i in range(len(bad)):
        if not bad[i]: R[i,i]=1.0
    return R,pair

@report_work('Pairwise moment systems',total=lambda A,B,**kw:A.shape[2]**2,unit='pair')
def _pairwise_initial_from_moments(A, B, *, trait_chunk=64):
    """Exact closed-form MoM solve for every trait pair, batched in C/BLAS.

    This replaces the historical Python loop over O(T^2) trait pairs.  The
    local p x p normal systems (p = number of random-effect kernels + E) are
    solved in vectorized batches, which is important at T~1,000 and also
    supports additive + dominance + GxE models without changing the algebra.

    Parameters
    ----------
    A : array-like
        Numerical input passed to ``report_work`` as ``total``; see that callable for required
        dimensions and matrix role. Passed to ``report_work`` as ``total``.

    B : array-like
        Numerical operand in ``B[:, a0:a1, :]``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    trait_chunk : int
        Rows/traits per processing or storage tile, along the axis named by the routine.
        Positive counts bound the corresponding intermediate allocation. Default: ``64``.
    """
    A = np.asarray(A, dtype=float)
    B = np.asarray(B, dtype=float)
    p, _, T, _ = A.shape
    C = np.zeros((p, T, T), dtype=float)
    eye = np.eye(p, dtype=float)
    step = max(1, int(trait_chunk))
    for a0 in range(0, T, step):
        a1 = min(T, a0 + step)
        M = A[:, :, a0:a1, :].transpose(2, 3, 0, 1) + 1e-10 * eye
        y = B[:, a0:a1, :].transpose(1, 2, 0)
        try:
            th = np.linalg.solve(M, y[..., None])[..., 0]
        except np.linalg.LinAlgError:
            th = np.einsum('...ij,...j->...i', np.linalg.pinv(M, rcond=1e-10), y, optimize=True)
        C[:, a0:a1, :] = np.moveaxis(th, -1, 0)
        current_work().update((a1-a0)*T)
    return [_sym(C[r]) for r in range(p)]

def _normalize_factor_structure(structure):
    """Canonical covariance-factor structure name used by the PSD optimizer.

    Parameters
    ----------
    structure : str
        Input for the operation ``str(structure).lower().replace('-', '_')``. See
        ``vigor.multivariate._normalize_factor_structure`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.
    """
    key = "fa" if structure is None else str(structure).lower().replace("-", "_")
    aliases = {
        "factor": "fa", "factor_analytic": "fa", "varimax_fa": "fa",
        "low_rank_psd": "pca", "eigen": "pca", "spectral": "pca", "psd": "pca",
        "sparsefa": "sparse_fa", "sparse_factor": "sparse_fa", "sparse_factor_analytic": "sparse_fa",
        "sparsepca": "sparse_pca", "sparse_psd": "sparse_pca", "sparse_eigen": "sparse_pca",
        "sparse_varimax_fa": "sparse_fa",
    }
    key = aliases.get(key, key)
    if key not in {"fa", "pca", "sparse_fa", "sparse_pca"}:
        raise ValueError("factor structure must be one of 'fa', 'pca', 'sparse_fa', or 'sparse_pca'")
    return key


def _resolve_component_setting(value, names, default=None):
    """Resolve scalar/dict/sequence options to one value per named component.

    Parameters
    ----------
    value : mapping
        Input for the operation ``value.get(n, value.get('default', default))``. See
        ``vigor.multivariate._resolve_component_setting`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    default : mapping
        Input for the operation ``value.get(n, value.get('default', default))``. See
        ``vigor.multivariate._resolve_component_setting`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.
    """
    if isinstance(value, dict):
        return [value.get(n, value.get("default", default)) for n in names]
    if isinstance(value, (list, tuple, np.ndarray)) and not isinstance(value, str):
        vals = list(value)
        if len(vals) != len(names):
            raise ValueError(f"component option has {len(vals)} values but {len(names)} components were requested")
        return vals
    return [default if value is None else value for _ in names]


def _fa_parameter_layout(initial_specs, ranks, eps, structures=None):
    """Pack factor and specific-variance coordinates into componentwise optimizer slices.

    Parameters
    ----------
    initial_specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities.

    structures : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping. Default:
        ``None``.
    """
    chunks = []
    layout = []
    offset = 0
    if structures is None:
        structures = ["fa"] * len(initial_specs)
    for i, (sp, rank, structure) in enumerate(zip(initial_specs, ranks, structures)):
        rank = int(rank)
        structure = _normalize_factor_structure(structure)
        F = np.asarray(sp.factor[:, :rank], float)
        if F.shape[1] < rank:
            F = np.pad(F, ((0, 0), (0, rank - F.shape[1])))
        # PCA/PSD structures never have trait-specific diagonal residuals.
        # Full-rank FA also omits Psi because LL' is already a general PSD matrix.
        has_specific = structure in {"fa", "sparse_fa"} and rank < sp.n_traits
        psi = np.maximum(sp.diag_specific, eps) if has_specific else np.zeros(sp.n_traits)
        xF = F.ravel()
        chunks.append(xF)
        f_slice = slice(offset, offset + xF.size)
        offset += xF.size
        if not has_specific:
            p_slice = slice(offset, offset)
        else:
            eta = _inv_softplus(np.maximum(psi - eps, 1e-12))
            chunks.append(eta)
            p_slice = slice(offset, offset + eta.size)
            offset += eta.size
        layout.append((f_slice, p_slice, rank, has_specific, structure))
    return np.concatenate(chunks) if chunks else np.array([], float), layout


def _unpack_fa(x, layout, T, eps, names, support_masks=None, rotations=None):
    """Unpack factor-analytic covariance.

    Parameters
    ----------
    x : array-like
        Numerical operand in ``x[fs]``. Shape must conform to that matrix/vector operation and
        the enclosing prepared state.

    layout : str or sequence
        LD array layout or packed optimizer-coordinate slices. LD spellings 'dense'/'matrix' use a
        square matrix; 'offset'/'band'/'window'/'rolling' use banded offsets where supported.
        Optimization layouts must come from the same parameter-layout helper.

    T : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    support_masks : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``.

    rotations : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``.
    """
    specs = []
    support_masks = [None] * len(layout) if support_masks is None else support_masks
    rotations = [None] * len(layout) if rotations is None else rotations
    for name, (fs, ps, rank, has_specific, structure), support, rotation in zip(names, layout, support_masks, rotations):
        F = x[fs].reshape(T, rank)
        if has_specific:
            eta = x[ps]
            psi = _softplus(eta) + eps
            sig = _sigmoid(eta)
        else:
            psi = np.zeros(T)
            sig = None
        specs.append((FactorCovarianceSpec(F, psi, name=name, support_mask=support,
                                           structure=structure, rotation=rotation), sig, ps))
    return specs


def _factor_rotation_matrix(F, rotation):
    """Apply the requested orthogonal factor rotation without changing dense covariance.

    Parameters
    ----------
    F : array-like
        Numerical operand in ``F.shape[1]``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.

    rotation : str
        Factor rotation: None/'none'/'off'/'false' leaves factors unchanged; 'varimax' uses an
        orthogonal varimax rotation. Covariance remains invariant in the dense case.
    """
    rotation = None if rotation is None else str(rotation).lower()
    if rotation in {None, "none", "off", "false"} or F.shape[1] <= 1:
        return np.asarray(F, float), None
    if rotation == "varimax":
        Fr = _varimax_loadings(np.asarray(F, float))
        return Fr, "varimax"
    raise ValueError("factor rotation must be None/'none' or 'varimax'")


def _canonical_pca_spec(spec, *, name=None, support_mask=None):
    """Return canonical eigen loading orientation for a low-rank PSD matrix.

    Parameters
    ----------
    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Source comparisons: ``rank == 0``. See
        the rejection/fallback branches for enforcement. Passed to ``FactorCovarianceSpec`` as
        ``name``.

    name : str
        Identifier used to select or label the relevant component, field or output quantity. It
        must match the names present in the supplied object where lookup is required. Default:
        ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value. Passed to ``FactorCovarianceSpec`` as ``name``.

    support_mask : array-like
        Loading-support mask or nonnegative trait-specific diagonal variance, as named. Masks
        match trait × factor loadings; specific variances have one value per trait and augment
        the low-rank covariance. Default: ``None``. None delegates to the local fallback shown
        in this body; it is not an additional numeric/category value. Passed to
        ``FactorCovarianceSpec`` as ``support_mask``.
    """
    C = spec.materialize()
    rank = int(spec.factor.shape[1])
    if rank == 0:
        F = np.zeros((spec.n_traits, 0), dtype=float)
    else:
        w, V = _leading_eigh(C, rank)
        keep = w > max(1e-14, 1e-12 * max(float(np.max(w, initial=0.0)), 1.0))
        F = V[:, keep] * np.sqrt(np.maximum(w[keep], 0.0))[None, :]
    return FactorCovarianceSpec(F, np.zeros(spec.n_traits), name=spec.name if name is None else name,
                                support_mask=support_mask, structure="pca", rotation="eigen")


def _factor_composite_objective(A, B, factors, psi, *, ridge, W, lambdas, group_lambdas, adaptive_weights, sparse_flags, h2_penalty=None):
    """Evaluate the MoM fit plus sparse-loading and group penalties.

    Parameters
    ----------
    A : array-like
        Numerical operand in ``A[r, q] * C[q]``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    B : array-like
        Numerical operand in ``W * (-2.0 * B[r] * C[r] + ridge[r] * C[r] * C[r])``. Shape must
        conform to that matrix/vector operation and the enclosing prepared state.

    factors : bool or None
        Whether bootstrap tracks aligned factor loadings as well as covariance uncertainty. None
        enables factor tracking for trait-rank-reduced fits.

    psi : array-like
        Loading-support mask or nonnegative trait-specific diagonal variance, as named. Masks
        match trait × factor loadings; specific variances have one value per trait and augment
        the low-rank covariance.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order.

    W : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    lambdas : float or array-like
        Nonnegative sparse/group/ridge penalty strength(s), in the objective's coefficient/group
        order. Zero removes that penalty; vectors must match the affected entries/groups.

    group_lambdas : float or array-like
        Nonnegative sparse/group/ridge penalty strength(s), in the objective's coefficient/group
        order. Zero removes that penalty; vectors must match the affected entries/groups.

    adaptive_weights : array-like or numeric scalar
        Input for the operation ``float(lambdas[r]) * float(np.sum(adaptive_weights[r] *
        np.abs(factors[r])))``. See ``vigor.multivariate._factor_composite_objective`` and its
        caller for the scientific representation; the shown operation constrains the required
        type/shape.

    sparse_flags : bool, float or sequence
        Sparse-factor control: adaptive weights penalties by initial magnitude, auto_fraction
        sets a scale-relative penalty, support_tol thresholds active loadings and sparse flags
        select components using sparse geometry. Match componentwise flags to the model order.
    """
    p = len(factors)
    C = [_sym(F @ F.T + np.diag(psi[r])) for r, F in enumerate(factors)]
    M = []
    f = 0.0
    for r in range(p):
        Mr = -B[r].copy()
        for q in range(p):
            Mr += A[r, q] * C[q]
        if ridge[r]:
            Mr += ridge[r] * C[r]
        Mr = _sym(W * Mr)
        M.append(Mr)
        f += float(np.sum(W * (-2.0 * B[r] * C[r] + ridge[r] * C[r] * C[r])))
        for q in range(p):
            f += float(np.sum(W * A[r, q] * C[r] * C[q]))
    if h2_penalty is not None:
        from .h2_prior import penalty_terms
        value, diag_grads, _, _ = penalty_terms([np.diag(c) for c in C], h2_penalty)
        f += value
        for r in range(p):
            M[r] = M[r] + np.diag(0.5 * diag_grads[r])
    grads = [4.0 * (M[r] @ factors[r]) for r in range(p)]
    penalty = 0.0
    for r in range(p):
        if not sparse_flags[r]:
            continue
        if lambdas[r] > 0:
            penalty += float(lambdas[r]) * float(np.sum(adaptive_weights[r] * np.abs(factors[r])))
        if group_lambdas[r] > 0 and factors[r].shape[1]:
            penalty += float(group_lambdas[r]) * float(np.sum(np.linalg.norm(factors[r], axis=0)))
    return float(f + penalty), float(f), grads


@report_work('Sparse FA support (accepted steps)',unit='iter')
def _proximal_sparse_factor_stage(A, B, specs, structures, *, ridge, W, lambdas,
                                  group_lambdas, adaptive=True, maxiter=120, tol=1e-7,
                                  auto_fraction=0.05, support_tol=1e-7, h2_penalty=None):
    """Select sparse factor support with proximal gradient in trait space.

    Psi is held at the dense L-BFGS solution during support selection.  A final
    support-fixed L-BFGS refit subsequently re-estimates all active loadings and
    specific variances, removing most L1 shrinkage bias.

    Parameters
    ----------
    A : array-like
        Numerical operand in ``4.0 * float(np.nanmax(np.abs(A[r, q]))) * max(1.0, specnorm2[r] +
        specnorm2[q])``. Shape must conform to that matrix/vector operation and the enclosing
        prepared state.

    B : array-like
        Numerical operand in ``_factor_composite_objective(A, B, F, psi, ridge=ridge, W=W,
        lambdas=lam_resolved, group_lambdas=glam_resolved, adaptive_weights=aw,
        sparse_flags=sparse_flags)``. Shape must conform to that matrix/vector operation and the
        enclosing prepared state.

    specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state.

    structures : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Passed to ``_factor_composite_objective`` as ``ridge``.

    W : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations. Passed to ``_factor_composite_objective`` as ``W``.

    lambdas : float or array-like
        Nonnegative sparse/group/ridge penalty strength(s), in the objective's coefficient/group
        order. Zero removes that penalty; vectors must match the affected entries/groups.

    group_lambdas : float or array-like
        Nonnegative sparse/group/ridge penalty strength(s), in the objective's coefficient/group
        order. Zero removes that penalty; vectors must match the affected entries/groups.

    adaptive : bool, float or sequence
        Sparse-factor control: adaptive weights penalties by initial magnitude, auto_fraction
        sets a scale-relative penalty, support_tol thresholds active loadings and sparse flags
        select components using sparse geometry. Match componentwise flags to the model order.
        Default: ``True``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``120``. Passed to ``current_work().accepted`` as ``limit``.

    tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``.

    auto_fraction : bool, float or sequence
        Sparse-factor control: adaptive weights penalties by initial magnitude, auto_fraction
        sets a scale-relative penalty, support_tol thresholds active loadings and sparse flags
        select components using sparse geometry. Match componentwise flags to the model order.
        Default: ``0.05``.

    support_tol : bool, float or sequence
        Sparse-factor control: adaptive weights penalties by initial magnitude, auto_fraction
        sets a scale-relative penalty, support_tol thresholds active loadings and sparse flags
        select components using sparse geometry. Match componentwise flags to the model order.
        Default: ``1e-07``.
    """
    p = len(specs)
    F = [np.asarray(sp.factor, float).copy() for sp in specs]
    psi = [np.asarray(sp.diag_specific, float).copy() for sp in specs]
    sparse_flags = [s in {"sparse_fa", "sparse_pca"} for s in structures]
    med = []
    aw = []
    for r in range(p):
        vals = np.abs(F[r][np.isfinite(F[r])])
        m = float(np.median(vals[vals > 0])) if np.any(vals > 0) else 1.0
        med.append(max(m, 1e-12))
        if adaptive and sparse_flags[r]:
            w = med[-1] / (np.abs(F[r]) + 0.10 * med[-1])
            aw.append(np.clip(w, 0.20, 10.0))
        else:
            aw.append(np.ones_like(F[r]))

    # Conservative trait-space curvature bound.  It is used both for the first
    # step and to scale automatic penalties, so auto λ has a loading-scale
    # interpretation rather than depending on N or the raw moment magnitude.
    specnorm2 = [float(np.linalg.norm(fr, 2) ** 2) if fr.size else 0.0 for fr in F]
    curv = []
    for r in range(p):
        h = 4.0 * abs(float(ridge[r])) * max(1.0, specnorm2[r])
        for q in range(p):
            h += 4.0 * float(np.nanmax(np.abs(A[r, q]))) * max(1.0, specnorm2[r] + specnorm2[q])
        curv.append(max(h, 1e-12))
    L0 = max(curv) if curv else 1.0
    step = min(1.0, 1.0 / L0)

    lam_resolved = []
    glam_resolved = []
    for r in range(p):
        lv = lambdas[r]
        if sparse_flags[r] and (lv is None or (isinstance(lv, str) and str(lv).lower() == "auto")):
            lv = float(auto_fraction) * curv[r] * med[r]
        elif lv is None:
            lv = 0.0
        lv = float(lv)
        gv = group_lambdas[r]
        if sparse_flags[r] and isinstance(gv, str) and str(gv).lower() == "auto":
            gv = 0.5 * lv * np.sqrt(max(1, F[r].shape[0]))
        gv = 0.0 if gv is None else float(gv)
        lam_resolved.append(max(lv, 0.0))
        glam_resolved.append(max(gv, 0.0))

    prev, smooth_prev, _ = _factor_composite_objective(
        A, B, F, psi, ridge=ridge, W=W, lambdas=lam_resolved,
        group_lambdas=glam_resolved, adaptive_weights=aw, sparse_flags=sparse_flags, h2_penalty=h2_penalty)
    nit = 0
    converged = False
    for nit in range(1, int(maxiter) + 1):
        _, _, grads = _factor_composite_objective(
            A, B, F, psi, ridge=ridge, W=W, lambdas=lam_resolved,
            group_lambdas=glam_resolved, adaptive_weights=aw, sparse_flags=sparse_flags, h2_penalty=h2_penalty)
        accepted = False
        local_step = step
        Fnew = None
        val = None
        for _bt in range(30):
            trial = []
            for r in range(p):
                Z = F[r] - local_step * grads[r]
                if sparse_flags[r]:
                    thr = local_step * lam_resolved[r] * aw[r]
                    Z = np.sign(Z) * np.maximum(np.abs(Z) - thr, 0.0)
                    if glam_resolved[r] > 0 and Z.shape[1]:
                        norms = np.linalg.norm(Z, axis=0)
                        scale = np.maximum(0.0, 1.0 - local_step * glam_resolved[r] / np.maximum(norms, 1e-30))
                        Z = Z * scale[None, :]
                trial.append(Z)
            val, _, _ = _factor_composite_objective(
                A, B, trial, psi, ridge=ridge, W=W, lambdas=lam_resolved,
                group_lambdas=glam_resolved, adaptive_weights=aw, sparse_flags=sparse_flags, h2_penalty=h2_penalty)
            if np.isfinite(val) and val <= prev + 1e-12 * max(1.0, abs(prev)):
                Fnew = trial
                accepted = True
                break
            local_step *= 0.5
        if not accepted:
            break
        maxchange = max((float(np.max(np.abs(a-b))) if a.size else 0.0) for a, b in zip(Fnew, F))
        reldec = abs(prev - val) / max(1.0, abs(prev))
        F = Fnew
        prev = float(val)
        current_work().accepted(prev,limit=int(maxiter))
        step = min(local_step * 1.15, max(1.0 / L0, local_step))
        if maxchange <= float(tol) * max(1.0, max((float(np.max(np.abs(x))) if x.size else 0.0) for x in F)) or reldec <= float(tol):
            converged = True
            break

    supports = []
    density = []
    for r in range(p):
        if sparse_flags[r]:
            scale = max(float(np.max(np.abs(F[r]), initial=0.0)), 1.0)
            mask = np.abs(F[r]) > max(float(support_tol), float(support_tol) * scale)
            # Avoid a degenerate all-zero covariance component solely because a
            # conservative automatic penalty crossed every loading.
            if F[r].size and not np.any(mask):
                j = np.unravel_index(int(np.argmax(np.abs(F[r]))), F[r].shape)
                mask[j] = True
            F[r][~mask] = 0.0
        else:
            mask = np.ones_like(F[r], dtype=bool)
        supports.append(mask)
        density.append(float(np.mean(mask)) if mask.size else 0.0)
    return {
        "factors": F, "support_masks": supports, "lambda": lam_resolved,
        "group_lambda": glam_resolved, "density": density, "nit": int(nit),
        "objective_penalized": float(prev), "step": float(step),
        "adaptive": bool(adaptive), "auto_fraction": float(auto_fraction),
        "converged": converged,
    }


@report_work('FA L-BFGS (accepted iterations)',unit='iter')
def fit_mom_factor_analytic(
    moments,
    *,
    ranks,
    names=None,
    ridge=None,
    entry_weight=None,
    warm_start=None,
    structures=None,
    rotations=None,
    factor_lambda=None,
    factor_group_lambda=0.0,
    factor_adaptive=True,
    factor_relaxed_refit=True,
    factor_support_tol=1e-7,
    factor_sparse_maxiter=120,
    factor_sparse_tol=1e-7,
    factor_auto_fraction=0.05,
    maxiter=1000,
    gtol=1e-7,
    ftol=1e-8,
    eps=1e-8,
    method="L-BFGS-B",
    h2_penalty=None,
):
    """Joint PSD/FA MoM fit with optional sparse factor support selection.

    ``h2_penalty`` (from :func:`vigor.h2_prior.build_penalty`) adds the
    empirical-Bayes heritability prior to every stage of the objective:
    dense L-BFGS, proximal support selection and the support-fixed refit.

    ``structures`` is specified per covariance component and accepts ``fa``,
    ``pca`` (low-rank PSD), ``sparse_fa`` and ``sparse_pca``.  Dense fitting is
    performed first with L-BFGS-B. Sparse structures then run a trait-space
    proximal support-selection stage, followed by an optional support-fixed
    L-BFGS-B refit.  The latter is the returned inference estimator and is the
    target used by VIGOR's final analytic sandwich SE.
    
    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.
    
    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine.
    
    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Default:
        ``None``. Passed to ``_initial_fa_spec`` as ``warm``.
    
    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``_proximal_sparse_factor_stage`` as ``ridge``.
    
    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Default: ``None``.
    
    warm_start : mapping, array-like or None
        Initial covariance factors/matrices or optimization state from a compatible fit. None
        uses the solver's initialization; incompatible trait/component dimensions must not be
        reused. Default: ``None``. Passed to ``_initial_fa_spec`` as ``warm``.
    
    structures : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping. Default:
        ``None``.
    
    rotations : str, sequence, mapping or None
        Factor orientation: None/'none'/'off'/'false' leaves factors unchanged; 'varimax' uses
        orthogonal varimax, preserving dense covariance and choosing pre-sparsity orientation.
        'identity' is not accepted. Per-component settings follow component order. Default:
        ``None``.
    
    factor_lambda : float, str, mapping or None
        Loading L1 penalty. Nonnegative numeric values set it explicitly; None/'auto' uses the
        factor_auto_fraction scale rule for sparse factors. The G setting may map kernel names
        to penalties; dense geometry ignores sparse penalties. Default: ``None``.
    
    factor_group_lambda : float, str or mapping
        Row-group loading penalty for sparse factors. Zero disables group sparsity; positive
        values penalize each trait's loading-row norm; 'auto' chooses a scale-relative penalty.
        The G setting may be per kernel. Default: ``0.0``.
    
    factor_adaptive : bool
        Whether sparse loading penalties are weighted adaptively using the initial loading
        magnitudes rather than a common weight. Default: ``True``.
    
    factor_relaxed_refit : bool
        Whether to refit loadings without shrinkage after selecting their support, retaining
        zeros fixed by sparse selection. Default: ``True``.
    
    factor_support_tol : float
        Absolute loading magnitude threshold used to define selected sparse support; nonnegative
        values determine which entries are fixed at zero for refitting. Default: ``1e-07``.
    
    factor_sparse_maxiter : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``120``.
    
    factor_sparse_tol : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``1e-07``.
    
    factor_auto_fraction : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``0.05``.
    
    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``1000``. Passed to ``minimize`` as ``options``.
    
    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``. Passed to ``minimize`` as ``options``.
    
    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-08``. Passed to ``minimize`` as ``options``.
    
    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_initial_fa_spec`` as ``eps``.
    
    method : callable or str
        Algorithm/estimator selected for the operation described above. See the source-derived
        choices and called model factory for the accepted methods; callable methods must obey
        that factory's fit/predict or objective contract. Default: ``'L-BFGS-B'``. Passed to
        ``minimize`` as ``method``.
    
    Returns
    -------
    dict
        Result fields: ``specs``, ``matrices``, ``result``, ``dense_result``, ``optimizer_converged``, ``success``, ``message``, ``objective``, ``ranks``, ``effective_ranks``, ``factor_structures``, ``factor_rotations``, ``factor_support``, ``loading_density``, ``sparse_diagnostics``, ``n_parameters``, ``x``, ``optimizer_objective_scale``, ``optimizer_gradient_norm``. Field arrays preserve the corresponding input axis order.
    
    Complexity
    ----------
    TIME O(I (c²t²+t²R)+c t³+J(tR²+R³)); SPACE O(c²t²+tR+h tR), excluding supplied moments. c is covariance components including E, t traits, R summed factor ranks, I total objective/proximal/refit evaluations, J rotation sweeps and h L-BFGS history length. Initialization/projected full-rank paths can cost O(c t³). Sparsity does not remove dense moment matrices; support selection and relaxed refit add evaluations rather than guaranteeing convergence.
    """
    A = np.asarray(moments["A"], dtype=float)
    B = np.asarray(moments["B"], dtype=float)
    p, _, T, _ = A.shape
    if names is None:
        names = list(moments.get("kernel_names", [f"G{i}" for i in range(p - 1)])) + ["E"]
    if len(names) != p:
        raise ValueError("names length does not match moment components")
    if np.isscalar(ranks) or isinstance(ranks, str):
        ranks = [ranks] * p
    ranks = [_rank_value(r, T) for r in ranks]
    structures = _resolve_component_setting(structures, names, default="fa")
    structures = [_normalize_factor_structure(x) for x in structures]
    rotations = _resolve_component_setting(rotations, names, default=None)
    # sparse_varimax_fa is accepted as a convenient compound spelling
    for i, rv in enumerate(rotations):
        if rv is not None and str(rv).lower() in {"none", "off", "false"}:
            rotations[i] = None
    if ridge is None:
        ridge = np.zeros(p)
    elif np.isscalar(ridge):
        ridge = np.repeat(float(ridge), p)
    else:
        ridge = np.asarray(ridge, float)
    lambdas = _resolve_component_setting(factor_lambda, names, default=None)
    group_lambdas = _resolve_component_setting(factor_group_lambda, names, default=0.0)
    W = np.ones((T, T), float) if entry_weight is None else _sym(np.asarray(entry_weight, float))
    C0 = _pairwise_initial_from_moments(A, B)
    warm_start = {} if warm_start is None else warm_start
    init_specs = []
    for i in range(p):
        sp = _initial_fa_spec(C0[i], ranks[i], eps=eps, warm=warm_start.get(names[i]), name=names[i])
        # PCA/PSD starts from the rank-r PSD projection, not FA uniqueness.
        if structures[i] in {"pca", "sparse_pca"}:
            sp = FactorCovarianceSpec(sp.factor, np.zeros(T), name=names[i], structure=structures[i])
        init_specs.append(sp)
    x0, layout = _fa_parameter_layout(init_specs, ranks, eps, structures=structures)

    def unpack(x, support_masks=None):
        """Unpack optimizer coordinates into the enclosing matrix parameterization.

        Parameters
        ----------
        x : one-dimensional numpy.ndarray
            Flattened optimization coordinates in the parameter layout captured by this closure.
            Length and factor/path slice order must match that layout; the objective unpacks these
            entries before evaluation.

        support_masks : mapping or sequence or None
            Initial/final component specifications or selected factor/path support used by this
            fitting stage. Match the trait dimension, component names and factor ranks of the
            current model; None uses the local initial/default state. Default: ``None``. Passed to
            ``_unpack_fa`` as ``support_masks``.

        Returns
        -------
        object
            Computed result from ``(raw, specs, mats)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        raw = _unpack_fa(x, layout, T, eps, names, support_masks=support_masks, rotations=rotations)
        specs = [z[0] for z in raw]
        mats = [z.materialize() for z in specs]
        return raw, specs, mats

    def fg(x):
        """Evaluate the objective and gradient together at the optimizer coordinates.

        Parameters
        ----------
        x : one-dimensional numpy.ndarray
            Flattened optimization coordinates in the parameter layout captured by this closure.
            Length and factor/path slice order must match that layout; the objective unpacks these
            entries before evaluation.

        Returns
        -------
        object
            Computed result from ``(float(f), np.concatenate(grad_chunks))``; see the summary and the called implementation for its labeled/numerical representation.
        """
        raw, specs, C = unpack(x)
        M = []
        f = 0.0
        for r in range(p):
            Mr = -B[r].copy()
            for q in range(p):
                Mr += A[r, q] * C[q]
            if ridge[r]:
                Mr += ridge[r] * C[r]
            Mr = _sym(W * Mr)
            M.append(Mr)
        for r in range(p):
            f += float(np.sum(W * (-2.0 * B[r] * C[r] + ridge[r] * C[r] * C[r])))
            for q in range(p):
                f += float(np.sum(W * A[r, q] * C[r] * C[q]))
        if h2_penalty is not None:
            # df/dC_r = 2 M_r, so a diagonal penalty gradient enters M_r halved.
            value, diag_grads, _, _ = _h2_penalty_terms([np.diag(c) for c in C], h2_penalty)
            f += value
            for r in range(p):
                M[r] = M[r] + np.diag(0.5 * diag_grads[r])
        grad_chunks = []
        for r, (sp, sig, ps) in enumerate(raw):
            grad_chunks.append((4.0 * (M[r] @ sp.factor)).ravel())
            if sig is not None:
                grad_chunks.append(2.0 * np.diag(M[r]) * sig)
        return float(f), np.concatenate(grad_chunks)

    # L-BFGS gtol is an absolute parameter-gradient threshold.  The raw MoM
    # objective can be O(1e4-1e8), making a nominal gtol such as 1e-6 far more
    # stringent than intended and especially problematic along FA rotationally
    # flat directions.  Normalize only the optimizer objective/gradient; the
    # scientific MoM objective and returned covariance estimates remain raw.
    f0, _g0 = fg(x0)
    optimizer_scale = max(abs(float(f0)), float(np.linalg.norm(_g0)), 1.0)
    diagnostics={}
    optimizer_phase=['dense']
    optimizer_bar=current_work()
    def fg_opt(x):
        """Evaluate the objective/gradient on the currently free optimizer coordinates.

        Parameters
        ----------
        x : array-like
            Numerical operand in ``fg(x)``. Shape must conform to that matrix/vector operation and
            the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``(f / optimizer_scale, g / optimizer_scale)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        f, g = fg(x)
        if optimizer_bar.enabled:diagnostics.update(objective=f,gradient=g)
        return f / optimizer_scale, g / optimizer_scale
    def accepted(x):
        """Record one accepted optimizer iteration for progress and convergence reporting.

        Parameters
        ----------
        x : array-like
            Numerical operand in the matrix/vector transformation described above. Its dimensions
            must conform to the operations below; see the source expression and upstream preparation
            helper for the precise representation.
        """
        optimizer_bar.accepted(diagnostics.get('objective'),diagnostics.get('gradient'),limit=int(maxiter),phase=optimizer_phase[0])
    callback=accepted if optimizer_bar.enabled else None
    result_dense = minimize(
        fg_opt, x0, jac=True, method=method, callback=callback,
        options={"maxiter": int(maxiter), "gtol": float(gtol), "ftol": float(ftol), **optimizer_limits()},
    )
    optimizer_bar.finish('dense: '+str(result_dense.message))
    result_dense.optimizer_objective_scale = float(optimizer_scale)
    result_dense.fun_scaled = float(result_dense.fun)
    result_dense.fun, result_dense.jac = fg(result_dense.x)
    x_work = np.asarray(result_dense.x, float).copy()
    raw, dense_specs, _ = unpack(x_work)

    # Varimax is covariance-invariant for dense FA/PCA.  For sparse structures
    # it is used only to choose the orientation *before* support selection.
    for i, ((fs, ps, rank, has_specific, structure), rot) in enumerate(zip(layout, rotations)):
        if rot is None:
            continue
        F0 = x_work[fs].reshape(T, rank)
        Fr, _ = _factor_rotation_matrix(F0, rot)
        x_work[fs] = Fr.ravel()

    sparse_flags = [s in {"sparse_fa", "sparse_pca"} for s in structures]
    sparse_diag = None
    support_masks = [np.ones((T, ranks[i]), dtype=bool) for i in range(p)]
    result = result_dense
    if any(sparse_flags):
        raw_rot, specs_rot, _ = unpack(x_work)
        sparse_diag = _proximal_sparse_factor_stage(
            A, B, specs_rot, structures, ridge=np.asarray(ridge, float), W=W,
            lambdas=lambdas, group_lambdas=group_lambdas, adaptive=bool(factor_adaptive),
            maxiter=factor_sparse_maxiter, tol=factor_sparse_tol,
            auto_fraction=factor_auto_fraction, support_tol=factor_support_tol,
            h2_penalty=h2_penalty,
        )
        support_masks = sparse_diag["support_masks"]
        for i, (fs, ps, rank, has_specific, structure) in enumerate(layout):
            x_work[fs] = sparse_diag["factors"][i].ravel()
        if factor_relaxed_refit:
            bounds = [(None, None)] * int(x_work.size)
            for i, (fs, ps, rank, has_specific, structure) in enumerate(layout):
                if not sparse_flags[i]:
                    continue
                mask = support_masks[i].ravel()
                for off, active in enumerate(mask):
                    if not active:
                        bounds[fs.start + off] = (0.0, 0.0)
                        x_work[fs.start + off] = 0.0
            optimizer_phase[0]='support-fixed'
            result = minimize(
                fg_opt, x_work, jac=True, method="L-BFGS-B", bounds=bounds, callback=callback,
                options={"maxiter": int(maxiter), "gtol": float(gtol), "ftol": float(ftol), **optimizer_limits()},
            )
            optimizer_bar.finish('support-fixed: '+str(result.message))
            result.optimizer_objective_scale = float(optimizer_scale)
            result.fun_scaled = float(result.fun)
            result.fun, result.jac = fg(result.x)
            x_work = np.asarray(result.x, float)
        else:
            fval, gval = fg(x_work)
            result = OptimizeResult(x=x_work, fun=fval, jac=gval, success=True,
                                    message="proximal sparse support fit (no relaxed refit)", nit=sparse_diag["nit"])

    raw, specs0, mats0 = unpack(x_work, support_masks=support_masks)
    specs = []
    mats = []
    effective_ranks = {}
    loading_density = {}
    for i, sp in enumerate(specs0):
        structure = structures[i]
        support = support_masks[i]
        if sparse_flags[i]:
            F = np.asarray(sp.factor, float).copy()
            F[~support] = 0.0
            active_cols = np.any(support, axis=0) if support.size else np.zeros(F.shape[1], dtype=bool)
            F = F[:, active_cols]
            support = support[:, active_cols]
            sp = FactorCovarianceSpec(F, sp.diag_specific, name=sp.name, support_mask=support,
                                      structure=structure, rotation=(None if rotations[i] is None else str(rotations[i]).lower()))
        elif structure == "pca":
            sp = _canonical_pca_spec(sp, name=sp.name)
        elif rotations[i] is not None:
            Fr, rotname = _factor_rotation_matrix(sp.factor, rotations[i])
            sp = FactorCovarianceSpec(Fr, sp.diag_specific, name=sp.name,
                                      structure=structure, rotation=rotname)
        else:
            sp = FactorCovarianceSpec(sp.factor, sp.diag_specific, name=sp.name, structure=structure)
        specs.append(sp)
        mats.append(sp.materialize())
        effective_ranks[names[i]] = int(np.sum(np.linalg.norm(sp.factor, axis=0) > max(float(factor_support_tol), 1e-12)))
        loading_density[names[i]] = (1.0 if sp.support_mask is None else float(np.mean(sp.support_mask)) if sp.support_mask.size else 0.0)

    return {
        "specs": {n: s for n, s in zip(names, specs)},
        "matrices": {n: M for n, M in zip(names, mats)},
        "result": result,
        "dense_result": result_dense,
        "optimizer_converged": bool(result_dense.success and result.success
                                     and (sparse_diag is None or sparse_diag["converged"])),
        "success": bool(result.success and np.all(np.isfinite(result.x))),
        "message": str(result.message),
        "objective": float(_mom_objective(moments, mats, ridge=ridge, entry_weight=W)),
        "ranks": dict(zip(names, ranks)),
        "effective_ranks": effective_ranks,
        "factor_structures": dict(zip(names, structures)),
        "factor_rotations": dict(zip(names, rotations)),
        "factor_support": {n: s.support_mask for n, s in zip(names, specs)},
        "loading_density": loading_density,
        "sparse_diagnostics": sparse_diag,
        "n_parameters": int(result.x.size),
        "x": np.asarray(result.x),
        "optimizer_objective_scale": float(optimizer_scale),
        "optimizer_gradient_norm": float(np.linalg.norm(np.asarray(result.jac,float))),
        "h2_penalty_value": (None if h2_penalty is None else
                             float(_h2_penalty_terms([np.diag(M) for M in mats], h2_penalty)[0])),
    }



def _mom_objective(moments, matrices, *, ridge=None, entry_weight=None):
    """Evaluate the exact quadratic MoM objective for covariance matrices.

    This is shared by the iterative and spectral solvers so the fast spectral
    approximation can always be compared on the *same* objective used by the
    L-BFGS reference fit.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    matrices : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Default: ``None``.
    """
    A = np.asarray(moments["A"], dtype=float)
    B = np.asarray(moments["B"], dtype=float)
    C = [np.asarray(x, dtype=float) for x in matrices]
    p, _, T, _ = A.shape
    if len(C) != p:
        raise ValueError("number of covariance matrices does not match moment components")
    if ridge is None:
        ridge = np.zeros(p, dtype=float)
    elif np.isscalar(ridge):
        ridge = np.repeat(float(ridge), p)
    else:
        ridge = np.asarray(ridge, dtype=float)
    W = np.ones((T, T), dtype=float) if entry_weight is None else _sym(np.asarray(entry_weight, dtype=float))
    f = 0.0
    for r in range(p):
        f += float(np.sum(W * (-2.0 * B[r] * C[r] + ridge[r] * C[r] * C[r])))
        for q in range(p):
            f += float(np.sum(W * A[r, q] * C[r] * C[q]))
    return float(f)




def _mom_objective_gradient_matrices(moments, matrices, *, ridge=None, entry_weight=None):
    """MoM objective and Euclidean gradients with respect to covariance matrices.

    The returned gradients satisfy ``df = sum_r <grad[r], dC[r]>``.  This is
    the common bridge used by the FA/PSD and structural-SEM parameterizations,
    ensuring that both are fitted to the same original missingness-aware
    moment tensors rather than to post-hoc pairwise covariance estimates.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    matrices : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Default: ``None``.
    """
    A = np.asarray(moments["A"], dtype=float)
    Bmom = np.asarray(moments["B"], dtype=float)
    C = [_sym(np.asarray(x, dtype=float)) for x in matrices]
    p, _, T, _ = A.shape
    if len(C) != p:
        raise ValueError("number of covariance matrices does not match moment components")
    if ridge is None:
        ridge = np.zeros(p, dtype=float)
    elif np.isscalar(ridge):
        ridge = np.repeat(float(ridge), p)
    else:
        ridge = np.asarray(ridge, dtype=float)
    W = np.ones((T, T), dtype=float) if entry_weight is None else _sym(np.asarray(entry_weight, dtype=float))
    f = 0.0
    M = []
    for r in range(p):
        Mr = -Bmom[r].copy()
        for q in range(p):
            Mr += A[r, q] * C[q]
        if ridge[r]:
            Mr += ridge[r] * C[r]
        Mr = _sym(W * Mr)
        M.append(Mr)
        f += float(np.sum(W * (-2.0 * Bmom[r] * C[r] + ridge[r] * C[r] * C[r])))
        for q in range(p):
            f += float(np.sum(W * A[r, q] * C[r] * C[q]))
    return float(f), [2.0 * x for x in M]


def _sem_edge_layout(edge_mask, names, order=None):
    """Resolve a PC/ANM candidate graph to an acyclic SEM edge layout.

    B uses the convention ``B[target, source]``. Directed graph edges are
    respected when compatible with the supplied/topological order; unresolved
    undirected edges are oriented from earlier to later nodes in that order.

    Parameters
    ----------
    edge_mask : array-like or networkx.Graph or None
        Candidate trait paths, represented by a square trait adjacency mask or graph. Directions
        and node ordering must agree with names; None uses the fitter's candidate policy.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    order : sequence or None
        Topological trait/node ordering restricting paths to earlier-to-later edges. None lets
        the graph routine choose or infer a compatible acyclic ordering. Default: ``None``.
    """
    import networkx as nx
    names = list(map(str, names))
    p = len(names)
    if order is None:
        if isinstance(edge_mask,nx.Graph):
            topo=_sample_sem_orders(edge_mask,names,n_extensions=1)[0]
            order_idx=[names.index(x) for x in topo];order_source='consistent_cpdag_extension'
        else:
            order_idx=list(range(p));order_source='trait_order_assumption'
    else:
        order_idx=[names.index(str(x)) if isinstance(x,str) else int(x) for x in order]
        if sorted(order_idx)!=list(range(p)):
            raise ValueError('structural_order must contain every trait exactly once')
        order_source='user'
    rank = {node: i for i, node in enumerate(order_idx)}
    allow = np.zeros((p, p), dtype=bool)
    if edge_mask is None:
        for src in range(p):
            for dst in range(p):
                if rank[src] < rank[dst]:
                    allow[dst, src] = True
    elif isinstance(edge_mask, nx.Graph):
        for a, b in edge_mask.to_undirected().edges():
            ia, ib = names.index(str(a)), names.index(str(b))
            # Preserve an unambiguous PC/ANM direction if acyclic under order.
            if isinstance(edge_mask, nx.DiGraph):
                ab = edge_mask.has_edge(str(a), str(b)) and not edge_mask.has_edge(str(b), str(a))
                ba = edge_mask.has_edge(str(b), str(a)) and not edge_mask.has_edge(str(a), str(b))
            else:
                ab = ba = False
            if ab and rank[ia] < rank[ib]:
                allow[ib, ia] = True
            elif ba and rank[ib] < rank[ia]:
                allow[ia, ib] = True
            elif rank[ia] < rank[ib]:
                allow[ib, ia] = True
            else:
                allow[ia, ib] = True
    else:
        M = np.asarray(edge_mask, dtype=bool)
        if M.shape != (p, p):
            raise ValueError("structural edge mask must be T x T")
        for dst, src in zip(*np.where(M)):
            if rank[src] < rank[dst]:
                allow[dst, src] = True
    if isinstance(edge_mask,nx.Graph):
        for src,dst in edge_mask.edges():
            if isinstance(edge_mask,nx.DiGraph) and not edge_mask.has_edge(dst,src):
                if not allow[names.index(str(dst)),names.index(str(src))]:
                    raise ValueError('structural order contradicts an identified direction or feedback cycle')
        skeleton=edge_mask.to_undirected()
        for child in range(p):
            parents=np.flatnonzero(allow[child])
            for ii,a in enumerate(parents):
                for b in parents[ii+1:]:
                    if skeleton.has_edge(names[a],names[b]):continue
                    identified=isinstance(edge_mask,nx.DiGraph) and all(
                        edge_mask.has_edge(names[x],names[child]) and not edge_mask.has_edge(names[child],names[x]) for x in (a,b))
                    if not identified:raise ValueError('structural order creates a collider absent from the CPDAG')
    np.fill_diagonal(allow, False)
    edges = list(zip(*np.where(allow)))
    return allow, edges, order_idx, order_source


def _sem_factor_objective_gradient(
    moments, Bpath, innovation_specs, *, ridge=None, entry_weight=None,
    sem_l1=0.0, sem_weights=None, l1_smooth=1e-8,
):
    """Joint structural MoM objective and derivatives.

    ``C_s = H Psi_s H'`` with ``H=(I-B)^{-1}``.  All covariance sources share
    B and retain source-specific PSD innovation covariances Psi_s.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    Bpath : array-like or numeric scalar
        Input for the operation ``np.eye(T) - Bpath``. See
        ``vigor.multivariate._sem_factor_objective_gradient`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.

    innovation_specs : object (see the cited input contract)
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``_mom_objective_gradient_matrices`` as ``ridge``.

    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Default: ``None``. Passed to
        ``_mom_objective_gradient_matrices`` as ``entry_weight``.

    sem_l1 : float
        Nonnegative L1 penalty on shared SEM path coefficients; zero leaves paths unpenalized.
        Default: ``0.0``. Source comparisons: ``float(sem_l1) > 0``. See the rejection/fallback
        branches for enforcement.

    sem_weights : array-like or numeric scalar
        Input for the operation ``float(sem_l1) * float(np.sum(np.asarray(sem_weights, float) *
        z))``. See ``vigor.multivariate._sem_factor_objective_gradient`` and its caller for the
        scientific representation; the shown operation constrains the required type/shape.
        Default: ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.

    l1_smooth : float
        Input for the operation ``Bpath * Bpath + float(l1_smooth) ** 2``. See
        ``vigor.multivariate._sem_factor_objective_gradient`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``1e-08``.
    """
    Bpath = np.asarray(Bpath, dtype=float)
    T = Bpath.shape[0]
    H = np.linalg.solve(np.eye(T) - Bpath, np.eye(T))
    Psi = [sp.materialize() for sp in innovation_specs]
    C = [_sym(H @ P @ H.T) for P in Psi]
    f, grad_C = _mom_objective_gradient_matrices(moments, C, ridge=ridge, entry_weight=entry_weight)
    grad_Psi = [_sym(H.T @ G @ H) for G in grad_C]
    # dH = H dB H; for symmetric G and C, d f / dB = 2 H' G C.
    grad_B = np.zeros_like(Bpath)
    for G, Cr in zip(grad_C, C):
        grad_B += 2.0 * (H.T @ G @ Cr)
    if sem_weights is None:
        sem_weights = np.ones_like(Bpath)
    if float(sem_l1) > 0:
        z = np.sqrt(Bpath * Bpath + float(l1_smooth) ** 2)
        f += float(sem_l1) * float(np.sum(np.asarray(sem_weights, float) * z))
        grad_B += float(sem_l1) * np.asarray(sem_weights, float) * Bpath / z
    return float(f), grad_B, grad_Psi, C, H


def _proximal_sparse_sem_innovations(
    moments, Bpath, specs, structures, *, ridge, entry_weight, lambdas,
    group_lambdas, adaptive=True, maxiter=80, tol=1e-7,
    auto_fraction=0.05, support_tol=1e-7,
):
    """Select sparse innovation-factor support with B fixed.

    This is the structural analogue of VIGOR's sparse-FA proximal stage.  The
    final joint SEM fit subsequently holds these zeros fixed and re-estimates
    all active paths/loadings with L-BFGS-B, removing most L1 shrinkage bias.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    Bpath : object (see the cited input contract)
        Input for the operation ``_sem_factor_objective_gradient(moments, Bpath, tmp_specs,
        ridge=ridge, entry_weight=entry_weight)``. See
        ``vigor.multivariate._proximal_sparse_sem_innovations`` and its caller for the
        scientific representation; the shown operation constrains the required type/shape.

    specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Passed to
        ``FactorCovarianceSpec`` as ``name``.

    structures : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Passed to ``_sem_factor_objective_gradient`` as ``ridge``.

    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Passed to
        ``_sem_factor_objective_gradient`` as ``entry_weight``.

    lambdas : float or array-like
        Nonnegative sparse/group/ridge penalty strength(s), in the objective's coefficient/group
        order. Zero removes that penalty; vectors must match the affected entries/groups.

    group_lambdas : float or array-like
        Nonnegative sparse/group/ridge penalty strength(s), in the objective's coefficient/group
        order. Zero removes that penalty; vectors must match the affected entries/groups.

    adaptive : bool, float or sequence
        Sparse-factor control: adaptive weights penalties by initial magnitude, auto_fraction
        sets a scale-relative penalty, support_tol thresholds active loadings and sparse flags
        select components using sparse geometry. Match componentwise flags to the model order.
        Default: ``True``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``80``.

    tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``.

    auto_fraction : bool, float or sequence
        Sparse-factor control: adaptive weights penalties by initial magnitude, auto_fraction
        sets a scale-relative penalty, support_tol thresholds active loadings and sparse flags
        select components using sparse geometry. Match componentwise flags to the model order.
        Default: ``0.05``.

    support_tol : bool, float or sequence
        Sparse-factor control: adaptive weights penalties by initial magnitude, auto_fraction
        sets a scale-relative penalty, support_tol thresholds active loadings and sparse flags
        select components using sparse geometry. Match componentwise flags to the model order.
        Default: ``1e-07``.
    """
    p = len(specs)
    F = [np.asarray(sp.factor, float).copy() for sp in specs]
    psi = [np.asarray(sp.diag_specific, float).copy() for sp in specs]
    sparse_flags = [s in {"sparse_fa", "sparse_pca"} for s in structures]
    med, aw = [], []
    for r in range(p):
        vals = np.abs(F[r][np.isfinite(F[r])])
        m = float(np.median(vals[vals > 0])) if np.any(vals > 0) else 1.0
        med.append(max(m, 1e-12))
        if adaptive and sparse_flags[r]:
            w = med[-1] / (np.abs(F[r]) + 0.10 * med[-1])
            aw.append(np.clip(w, 0.20, 10.0))
        else:
            aw.append(np.ones_like(F[r]))
    # Resolve automatic lambda from the initial smooth gradient scale.
    tmp_specs = [FactorCovarianceSpec(F[r], psi[r], name=specs[r].name, structure=structures[r]) for r in range(p)]
    _, _, gpsi0, _, _ = _sem_factor_objective_gradient(
        moments, Bpath, tmp_specs, ridge=ridge, entry_weight=entry_weight)
    curv = [max(4.0 * float(np.linalg.norm(g, 2)) + 1e-12, 1e-12) for g in gpsi0]
    lam_resolved, glam_resolved = [], []
    for r in range(p):
        lv = lambdas[r]
        if sparse_flags[r] and (lv is None or (isinstance(lv, str) and str(lv).lower() == "auto")):
            lv = float(auto_fraction) * curv[r] * med[r]
        lv = 0.0 if lv is None else float(lv)
        gv = group_lambdas[r]
        if sparse_flags[r] and isinstance(gv, str) and str(gv).lower() == "auto":
            gv = 0.5 * lv * np.sqrt(max(1, F[r].shape[0]))
        gv = 0.0 if gv is None else float(gv)
        lam_resolved.append(max(lv, 0.0)); glam_resolved.append(max(gv, 0.0))

    def value_grad(Fnow):
        """Evaluate the current objective value and analytical gradient.

        Parameters
        ----------
        Fnow : array-like or fitted basis
            Trait/feature × retained-factor loading matrix or prepared basis. Column order
            identifies factor directions and must agree with the scores used for projection.

        Returns
        -------
        object
            Computed result from ``(val + pen, grads)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        ss = [FactorCovarianceSpec(Fnow[r], psi[r], name=specs[r].name, structure=structures[r]) for r in range(p)]
        val, _, gp, _, _ = _sem_factor_objective_gradient(
            moments, Bpath, ss, ridge=ridge, entry_weight=entry_weight)
        grads = [2.0 * gp[r] @ Fnow[r] for r in range(p)]
        pen = 0.0
        for r in range(p):
            if sparse_flags[r]:
                pen += lam_resolved[r] * float(np.sum(aw[r] * np.abs(Fnow[r])))
                if glam_resolved[r] > 0 and Fnow[r].shape[1]:
                    pen += glam_resolved[r] * float(np.sum(np.linalg.norm(Fnow[r], axis=0)))
        return val + pen, grads

    val, grads = value_grad(F)
    grad_scale = max([float(np.linalg.norm(g, 2)) for g in grads] + [1.0])
    step = min(1.0, 1.0 / grad_scale)
    nit = 0
    for nit in range(1, int(maxiter) + 1):
        val0, grads = value_grad(F)
        accepted = False
        local = step
        for _ in range(25):
            trial = []
            for r in range(p):
                Z = F[r] - local * grads[r]
                if sparse_flags[r]:
                    Z = np.sign(Z) * np.maximum(np.abs(Z) - local * lam_resolved[r] * aw[r], 0.0)
                    if glam_resolved[r] > 0 and Z.shape[1]:
                        norms = np.linalg.norm(Z, axis=0)
                        scale = np.maximum(0.0, 1.0 - local * glam_resolved[r] / np.maximum(norms, 1e-30))
                        Z *= scale[None, :]
                trial.append(Z)
            v1, _ = value_grad(trial)
            if np.isfinite(v1) and v1 <= val0 + 1e-12 * max(1.0, abs(val0)):
                accepted = True
                break
            local *= 0.5
        if not accepted:
            break
        change = max((float(np.max(np.abs(a-b))) if a.size else 0.0) for a, b in zip(trial, F))
        rel = abs(val0-v1) / max(1.0, abs(val0))
        F = trial; val = v1; step = min(local * 1.15, max(local, 1e-12))
        if change <= float(tol) * max(1.0, max((float(np.max(np.abs(x))) if x.size else 0.0) for x in F)) or rel <= float(tol):
            break
    supports, density = [], []
    for r in range(p):
        if sparse_flags[r]:
            scale = max(float(np.max(np.abs(F[r]), initial=0.0)), 1.0)
            mask = np.abs(F[r]) > max(float(support_tol), float(support_tol) * scale)
            if F[r].size and not np.any(mask):
                mask[np.unravel_index(int(np.argmax(np.abs(F[r]))), F[r].shape)] = True
            F[r][~mask] = 0.0
        else:
            mask = np.ones_like(F[r], dtype=bool)
        supports.append(mask); density.append(float(np.mean(mask)) if mask.size else 0.0)
    return {"factors": F, "support_masks": supports, "density": density,
            "lambda": lam_resolved, "group_lambda": glam_resolved,
            "nit": int(nit), "objective_penalized": float(val)}


@report_work('SEM L-BFGS (accepted iterations)',unit='iter')
def fit_mom_sem_factor_analytic(
    moments, *, ranks, names=None, trait_names=None, initial_specs=None, edge_mask=None, order=None,
    ridge=None, entry_weight=None, structures=None, rotations=None,
    factor_lambda=None, factor_group_lambda=0.0, factor_adaptive=True,
    factor_relaxed_refit=True, factor_support_tol=1e-7,
    factor_sparse_maxiter=80, factor_sparse_tol=1e-7, factor_auto_fraction=0.05,
    sem_l1=0.0, sem_weights=None, sem_bound=3.0, initial_B=None,
    maxiter=500, gtol=1e-7, ftol=1e-9, eps=1e-8,
):
    """Joint acyclic SEM + PSD innovation-factor fit against original MoM tensors.

    Each covariance source is ``C_s = H Psi_s H'``, ``H=(I-B)^-1``, with one
    shared acyclic path matrix B and source-specific PSD innovations
    ``Psi_s=L_s L_s' + diag(psi_s)``.  The function is intended as the
    structural block in VIGOR's PSD<->PC/ANM/SEM refinement loop.  Pairwise
    MoM estimates are used only for initialization; the objective is the exact
    same quadratic MoM objective used by ``fit_mom_factor_analytic``.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Default:
        ``None``.

    trait_names : sequence or pandas.Index
        Trait labels in matrix-column order, used to label or align the resulting trait
        quantities. Default: ``None``. None delegates to the local fallback shown in this body;
        it is not an additional numeric/category value.

    initial_specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``.

    edge_mask : array-like or networkx.Graph or None
        Candidate trait paths, represented by a square trait adjacency mask or graph. Directions
        and node ordering must agree with names; None uses the fitter's candidate policy.
        Default: ``None``.

    order : sequence or None
        Topological trait/node ordering restricting paths to earlier-to-later edges. None lets
        the graph routine choose or infer a compatible acyclic ordering. Default: ``None``.
        Passed to ``_sem_edge_layout`` as ``order``.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``_proximal_sparse_sem_innovations`` as ``ridge``.

    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Default: ``None``.

    structures : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping. Default:
        ``None``.

    rotations : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``.

    factor_lambda : float, str, mapping or None
        Loading L1 penalty. Nonnegative numeric values set it explicitly; None/'auto' uses the
        factor_auto_fraction scale rule for sparse factors. The G setting may map kernel names
        to penalties; dense geometry ignores sparse penalties. Default: ``None``.

    factor_group_lambda : float, str or mapping
        Row-group loading penalty for sparse factors. Zero disables group sparsity; positive
        values penalize each trait's loading-row norm; 'auto' chooses a scale-relative penalty.
        The G setting may be per kernel. Default: ``0.0``.

    factor_adaptive : bool
        Whether sparse loading penalties are weighted adaptively using the initial loading
        magnitudes rather than a common weight. Default: ``True``.

    factor_relaxed_refit : bool
        Whether to refit loadings without shrinkage after selecting their support, retaining
        zeros fixed by sparse selection. Default: ``True``.

    factor_support_tol : float
        Absolute loading magnitude threshold used to define selected sparse support; nonnegative
        values determine which entries are fixed at zero for refitting. Default: ``1e-07``.

    factor_sparse_maxiter : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``80``.

    factor_sparse_tol : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``1e-07``.

    factor_auto_fraction : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``0.05``.

    sem_l1 : float
        Nonnegative L1 penalty on shared SEM path coefficients; zero leaves paths unpenalized.
        Default: ``0.0``. Passed to ``_sem_factor_objective_gradient`` as ``sem_l1``.

    sem_weights : object (see the cited input contract)
        Input supplied to ``_sem_factor_objective_gradient`` as ``sem_weights``. See that
        callable's documented ``sem_weights`` contract for its type, alignment and value domain.
        This wrapper retains that contract. Default: ``None``. None delegates to the local
        fallback shown in this body; it is not an additional numeric/category value. Passed to
        ``_sem_factor_objective_gradient`` as ``sem_weights``.

    sem_bound : float
        Positive absolute bound on each fitted SEM path coefficient, limiting extreme path
        amplification. Default: ``3.0``.

    initial_B : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``500``. Passed to ``minimize`` as ``options``.

    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``. Passed to ``minimize`` as ``options``.

    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-09``. Passed to ``minimize`` as ``options``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_initial_fa_spec`` as ``eps``.

    Returns
    -------
    dict
        Result fields: ``B``, ``H``, ``trait_names``, ``innovation_specs``, ``innovation_matrices``, ``matrices``, ``edge_mask``, ``edges``, ``order_index``, ``order_source``, ``result``, ``dense_result``, ``success``, ``message``, ``objective``, ``n_parameters``, ``sparse_diagnostics``, ``optimizer_objective``, ``raw_gradient_norm``, ``final_parameter_objective``, ``projected_gradient_inf_norm``, ``iterations``, ``dense_iterations``, ``stationarity_scope``, ``objective_definition``, ``factor_support``, ``factor_structures``, ``innovation_identifiability``, ``residual_innovation_saturated``, ``path_identifiability_note``. Field arrays preserve the corresponding input axis order.
    """
    import networkx as nx
    A = np.asarray(moments["A"], float)
    p, _, T, _ = A.shape
    if names is None:
        names = list(moments.get("kernel_names", [f"G{i}" for i in range(p-1)])) + ["E"]
    names = list(map(str, names))
    if len(names) != p:
        raise ValueError("names length does not match moment components")
    trait_names = [str(i) for i in range(T)] if trait_names is None else list(map(str, trait_names))
    if len(trait_names) != T:
        raise ValueError("trait_names length does not match trait covariance dimension")
    if np.isscalar(ranks) or isinstance(ranks, str):
        ranks = [ranks] * p
    ranks = [_rank_value(r, T) for r in ranks]
    structures = [_normalize_factor_structure(x) for x in _resolve_component_setting(structures, names, default="fa")]
    rotations = _resolve_component_setting(rotations, names, default=None)
    lambdas = _resolve_component_setting(factor_lambda, names, default=None)
    group_lambdas = _resolve_component_setting(factor_group_lambda, names, default=0.0)
    if ridge is None: ridge = np.zeros(p)
    elif np.isscalar(ridge): ridge = np.repeat(float(ridge), p)
    else: ridge = np.asarray(ridge, float)
    W = np.ones((T,T), float) if entry_weight is None else _sym(np.asarray(entry_weight,float))
    allow, edges, order_idx, order_source = _sem_edge_layout(edge_mask, trait_names, order=order)

    C0 = _pairwise_initial_from_moments(A, np.asarray(moments["B"],float))
    initial_specs = {} if initial_specs is None else initial_specs
    init = []
    for i, n0 in enumerate(names):
        warm = initial_specs.get(n0) if isinstance(initial_specs, dict) else None
        sp = _initial_fa_spec(C0[i], ranks[i], eps=eps, warm=warm, name=n0)
        if structures[i] in {"pca", "sparse_pca"}:
            sp = FactorCovarianceSpec(sp.factor, np.zeros(T), name=n0, structure=structures[i])
        # A covariance-preserving varimax gives sparse stages a stable/simple orientation.
        if rotations[i] is not None:
            Fr, rot = _factor_rotation_matrix(sp.factor, rotations[i])
            sp = FactorCovarianceSpec(Fr, sp.diag_specific, name=n0, structure=structures[i], rotation=rot)
        init.append(sp)
    xfa0, layout = _fa_parameter_layout(init, ranks, eps, structures=structures)
    edge_index = {e:i for i,e in enumerate(edges)}
    b0 = np.zeros(len(edges), float)
    if initial_B is not None:
        B0 = np.asarray(initial_B, float)
        if B0.shape != (T,T): raise ValueError("initial_B must be T x T")
        for i,e in enumerate(edges): b0[i] = B0[e]
    x0 = np.concatenate([b0, xfa0])
    nB = len(edges)

    def unpack(x, support_masks=None):
        """Unpack optimizer coordinates into the enclosing matrix parameterization.

        Parameters
        ----------
        x : one-dimensional numpy.ndarray
            Flattened optimization coordinates in the parameter layout captured by this closure.
            Length and factor/path slice order must match that layout; the objective unpacks these
            entries before evaluation.

        support_masks : mapping or sequence or None
            Initial/final component specifications or selected factor/path support used by this
            fitting stage. Match the trait dimension, component names and factor ranks of the
            current model; None uses the local initial/default state. Default: ``None``. Passed to
            ``_unpack_fa`` as ``support_masks``.

        Returns
        -------
        object
            Computed result from ``(Bpath, raw, specs)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Bpath = np.zeros((T,T), float)
        for val,(dst,src) in zip(x[:nB], edges): Bpath[dst,src] = val
        raw = _unpack_fa(x[nB:], layout, T, eps, names, support_masks=support_masks, rotations=rotations)
        specs = [z[0] for z in raw]
        return Bpath, raw, specs

    optimizer_bar=current_work();diagnostics={};optimizer_phase=['dense']
    def fg(x):
        """Evaluate the objective and gradient together at the optimizer coordinates.

        Parameters
        ----------
        x : one-dimensional numpy.ndarray
            Flattened optimization coordinates in the parameter layout captured by this closure.
            Length and factor/path slice order must match that layout; the objective unpacks these
            entries before evaluation.

        Returns
        -------
        object
            Computed result from ``(float(val), gradient)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Bpath, raw, specs = unpack(x)
        val, gB, gPsi, _, _ = _sem_factor_objective_gradient(
            moments, Bpath, specs, ridge=ridge, entry_weight=W,
            sem_l1=sem_l1, sem_weights=sem_weights)
        chunks = [np.array([gB[e] for e in edges], float)]
        for r,(sp,sig,ps) in enumerate(raw):
            chunks.append((2.0 * gPsi[r] @ sp.factor).ravel())
            if sig is not None:
                chunks.append(np.diag(gPsi[r]) * sig)
        gradient=np.concatenate(chunks)
        if optimizer_bar.enabled:diagnostics.update(objective=float(val),gradient=gradient)
        return float(val), gradient

    def accepted(x):
        """Record one accepted optimizer iteration for progress and convergence reporting.

        Parameters
        ----------
        x : array-like
            Numerical operand in the matrix/vector transformation described above. Its dimensions
            must conform to the operations below; see the source expression and upstream preparation
            helper for the precise representation.
        """
        optimizer_bar.accepted(diagnostics.get('objective'),diagnostics.get('gradient'),limit=int(maxiter),phase=optimizer_phase[0])
    callback=accepted if optimizer_bar.enabled else None
    bounds = [(-float(sem_bound), float(sem_bound))] * nB + [(None,None)] * (len(x0)-nB)
    dense = minimize(fg, x0, jac=True, method="L-BFGS-B", bounds=bounds,callback=callback,
                     options={"maxiter":int(maxiter),"gtol":float(gtol),"ftol":float(ftol)})
    optimizer_bar.finish('dense: '+str(dense.message))
    final_bounds=list(bounds)
    xwork = np.asarray(dense.x,float).copy()
    Bpath, raw, specs = unpack(xwork)
    sparse_flags = [s in {"sparse_fa","sparse_pca"} for s in structures]
    support_masks = [np.ones((T,ranks[i]),bool) for i in range(p)]
    sparse_diag = None
    result = dense
    if any(sparse_flags):
        sparse_diag = _proximal_sparse_sem_innovations(
            moments, Bpath, specs, structures, ridge=np.asarray(ridge,float), entry_weight=W,
            lambdas=lambdas, group_lambdas=group_lambdas, adaptive=factor_adaptive,
            maxiter=factor_sparse_maxiter, tol=factor_sparse_tol,
            auto_fraction=factor_auto_fraction, support_tol=factor_support_tol)
        support_masks = sparse_diag["support_masks"]
        for i,(fs,ps,rank,has_specific,structure) in enumerate(layout):
            xwork[nB+fs.start:nB+fs.stop] = sparse_diag["factors"][i].ravel()
        if factor_relaxed_refit:
            rbounds = list(bounds)
            for i,(fs,ps,rank,has_specific,structure) in enumerate(layout):
                if not sparse_flags[i]: continue
                for off, active in enumerate(support_masks[i].ravel()):
                    if not active:
                        rbounds[nB+fs.start+off] = (0.0,0.0)
                        xwork[nB+fs.start+off] = 0.0
            optimizer_phase[0]='support-fixed'
            result = minimize(fg, xwork, jac=True, method="L-BFGS-B", bounds=rbounds,callback=callback,
                              options={"maxiter":int(maxiter),"gtol":float(gtol),"ftol":float(ftol)})
            optimizer_bar.finish('support-fixed: '+str(result.message))
            final_bounds=rbounds
            xwork = np.asarray(result.x,float)
    Bpath, raw, innovations = unpack(xwork, support_masks=support_masks)
    val, _, _, covs, H = _sem_factor_objective_gradient(
        moments, Bpath, innovations, ridge=ridge, entry_weight=W,
        sem_l1=sem_l1, sem_weights=sem_weights)
    # Diagnose the actual deployed parameter point, including sparse updates
    # when relaxed refitting was disabled; result.jac can describe an older fit.
    final_objective,final_gradient=fg(xwork)
    projected_gradient=final_gradient.copy()
    for j,(lower,upper) in enumerate(final_bounds):
        if lower is not None and xwork[j]<=lower and projected_gradient[j]>0:projected_gradient[j]=0.
        if upper is not None and xwork[j]>=upper and projected_gradient[j]<0:projected_gradient[j]=0.
    # Fixed sparse support is an equality constraint even without relaxed refit.
    for fs,mask in zip([a[0] for a in layout],support_masks):
        projected_gradient[nB+fs.start:nB+fs.stop][~mask.ravel()]=0.
    # Structural paths are not separately identifiable when an innovation
    # covariance has enough free parameters to reproduce an arbitrary T x T
    # covariance. Report a conservative parameter-capacity diagnostic rather
    # than silently interpreting B from a saturated innovation model.
    cov_dof=int(T*(T+1)//2); ident={}
    for n0,sp in zip(names,innovations):
        rr=int(sp.factor.shape[1]); support=getattr(sp,'support_mask',None)
        load_params=int(np.count_nonzero(support)) if support is not None else int(T*rr)
        # Rotational invariance reduces dense factor covariance degrees of
        # freedom; fixed sparse support does not generally retain full rotation.
        rot_redundancy=(rr*(rr-1)//2) if support is None else 0
        specific=int(T if str(getattr(sp,'structure','fa')).lower() in {'fa','sparse_fa'} else 0)
        nominal=max(0,load_params-rot_redundancy+specific)
        ident[str(n0)]={'structure':str(getattr(sp,'structure','fa')),'rank':rr,
            'active_loadings':load_params,'specific_variances':specific,
            'nominal_covariance_parameters':int(nominal),'covariance_dof':cov_dof,
            'capacity_ratio':float(nominal/max(cov_dof,1)),'saturated':bool(nominal>=cov_dof)}
    residual_name=str(names[-1]); residual_saturated=bool(ident[residual_name]['saturated'])
    if residual_saturated:
        warnings.warn(
            f"SEM residual innovation {residual_name!r} is nominally saturated ({ident[residual_name]['nominal_covariance_parameters']} parameters for {cov_dof} covariance degrees of freedom); shared path coefficients B may be weakly/non-identifiable. Use diagonal or lower-rank/sparse innovation structure for causal-path interpretation.",
            RuntimeWarning,stacklevel=2)
    return {
        "B": Bpath, "H": H, "trait_names": trait_names,
        "innovation_specs": {n:s for n,s in zip(names,innovations)},
        "innovation_matrices": {n:s.materialize() for n,s in zip(names,innovations)},
        "matrices": {n:_sym(C) for n,C in zip(names,covs)},
        "edge_mask": allow, "edges": edges, "order_index": order_idx,
        "order_source": order_source, "result": result, "dense_result": dense,
        "success": bool(result.success and np.all(np.isfinite(result.x))),
        "message": str(result.message), "objective": float(val),
        "n_parameters": int(result.x.size), "sparse_diagnostics": sparse_diag,
        "optimizer_objective":float(result.fun),"raw_gradient_norm":float(np.linalg.norm(final_gradient)),
        "final_parameter_objective":float(final_objective),
        "projected_gradient_inf_norm":float(np.max(np.abs(projected_gradient))) if projected_gradient.size else 0.,
        "iterations":int(result.nit),"dense_iterations":int(dense.nit),
        "stationarity_scope":"declared path bounds and selected fixed factor support; no graph/rank-selection uncertainty",
        "objective_definition":"structural MoM plus declared path penalty",
        "factor_support": {n:s.support_mask for n,s in zip(names,innovations)},
        "factor_structures": dict(zip(names,structures)),
        "innovation_identifiability": ident,
        "residual_innovation_saturated": residual_saturated,
        "path_identifiability_note": (
            "Residual innovation is saturated; B is not separately identified by covariance fit alone."
            if residual_saturated else
            "Innovation covariance is structurally constrained; B remains conditional on the discovered graph/order and model assumptions."),
    }


def _structural_graph_covariance(fit, knames, source="phenotypic", phenotypic_cov=None):
    """Select the covariance geometry used for PC graph updates.

    ``phenotypic`` means the empirical pairwise-observed phenotype covariance
    when supplied.  It must not inherit diagonal/sparse restrictions imposed on
    the fitted G/E parameterization, otherwise causal discovery can erase real
    phenotype covariance before PC sees it.

    Parameters
    ----------
    fit : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes.

    knames : array-like or numeric scalar
        Input for the operation ``sum((mats[n] for n in knames), np.zeros_like(mats['E'])) +
        mats['E']``. See ``vigor.multivariate._structural_graph_covariance`` and its caller for
        the scientific representation; the shown operation constrains the required type/shape.

    source : path-like or genotype source
        Input file/store location or opened source consumed by this adapter. See the selected
        reader for physical format, sample order and supported block representations. Default:
        ``'phenotypic'``. Source-recognized literal values: ``e``, ``environmental``, ``g``,
        ``genetic``, ``genetic_total``, ``p``, ``residual``, ``total``, ``vp``. These select the
        corresponding branches below; comparison evidence alone does not establish an exhaustive
        enum.

    phenotypic_cov : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance. Default: ``None``. None delegates to the local fallback shown in this body;
        it is not an additional numeric/category value.
    """
    source = str(source).lower()
    mats = fit["matrices"]
    if source in {"phenotypic","p","vp","total"}:
        if phenotypic_cov is not None: return _sym(np.asarray(phenotypic_cov,float))
        return _sym(sum((mats[n] for n in knames), np.zeros_like(mats["E"])) + mats["E"])
    if source in {"genetic","g","genetic_total"}:
        return _sym(sum((mats[n] for n in knames), np.zeros_like(mats["E"])))
    if source in {"e","environmental","residual"}:
        return _sym(mats["E"])
    for n in knames:
        if source == str(n).lower(): return _sym(mats[n])
    raise ValueError(f"unknown structural_pc_source={source!r}")



def _screen_pc_candidates(C, names, *, max_neighbors=20, min_abs_r=0.05):
    """Fast O(T^2) correlation screen used only to seed PC-stable.

    The screen is deliberately permissive (union of each node's top-k absolute
    correlations) and is not itself interpreted as a conditional-independence
    result. Set ``max_neighbors=None`` to recover complete-graph PC.

    Parameters
    ----------
    C : array-like
        Numerical input passed to ``np.divide`` as ``out``; see that callable for required
        dimensions and matrix role. Passed to ``np.divide`` as ``out``.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    max_neighbors : int
        Input for the operation ``int(max_neighbors) >= p - 1``. See
        ``vigor.multivariate._screen_pc_candidates`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default: ``20``.

    min_abs_r : float
        Minimum magnitude/asymmetry/stability evidence required for the corresponding graph edge
        or direction. Correlation/stability cutoffs use [0, 1]; directional score ratios use
        positive values, ordinarily greater than one. Default: ``0.05``.
    """
    import networkx as nx
    C=_sym(np.asarray(C,float)); d=np.sqrt(np.maximum(np.diag(C),1e-30)); R=np.divide(C,np.outer(d,d),out=np.zeros_like(C),where=np.outer(d,d)>0)
    np.fill_diagonal(R,0.0); p=len(names); G=nx.Graph();G.add_nodes_from(map(str,names))
    if max_neighbors is None or int(max_neighbors)>=p-1:
        for i in range(p):
            for j in range(i+1,p):
                if abs(R[i,j])>=float(min_abs_r): G.add_edge(str(names[i]),str(names[j]),screen_r=float(R[i,j]))
        return G
    k=max(1,min(int(max_neighbors),p-1))
    for i in range(p):
        row=np.abs(R[i]); cand=np.argpartition(row,-k)[-k:]
        for j in cand:
            if i==j or abs(R[i,j])<float(min_abs_r): continue
            a,b=str(names[i]),str(names[j]);G.add_edge(a,b,screen_r=float(R[i,j]))
    return G



def _resolve_structural_innovation_model(innovation_rank, ranks, names, T, *, sparse=True):
    """Resolve the causal-SEM innovation model independently of PSD inference ranks.

    A full unrestricted innovation covariance can absorb every directed path,
    making ``B`` non-identifiable.  Structural defaults therefore use diagonal
    innovations (rank 0). Small sparse factor ranks are available explicitly as
    latent-confounder sensitivity models without changing the ordinary G/E fit.

    Parameters
    ----------
    innovation_rank : int, str or sequence
        Innovation rank policy: 'diag'/'diagonal'/'identifiable'/'auto_identifiable' keeps
        identifiable diagonal innovations; 'inherit'/'covariance' reuses covariance ranks;
        integer ranks select constrained latent innovations. See
        _resolve_structural_innovation_model for componentwise behavior.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    T : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    sparse : bool, float or sequence
        Sparse-factor control: adaptive weights penalties by initial magnitude, auto_fraction
        sets a scale-relative penalty, support_tol thresholds active loadings and sparse flags
        select components using sparse geometry. Match componentwise flags to the model order.
        Default: ``True``.
    """
    if innovation_rank is None or str(innovation_rank).lower() in {'diagonal','diag','identifiable','auto_identifiable'}:
        rr=[0]*len(names); policy='diagonal_identifiable'
    elif isinstance(innovation_rank,dict):
        rr=[_rank_value(innovation_rank.get(n,0),T) for n in names]; policy='user_mapping'
    elif isinstance(innovation_rank,(list,tuple,np.ndarray)) and not isinstance(innovation_rank,str):
        if len(innovation_rank)!=len(names): raise ValueError('structural_sem_innovation_rank sequence must match covariance components')
        rr=[_rank_value(x,T) for x in innovation_rank]; policy='user_sequence'
    elif isinstance(innovation_rank,str) and innovation_rank.lower() in {'inherit','covariance'}:
        rr=[_rank_value(x,T) for x in ranks]; policy='inherit_nonidentifiable_risk'
    else:
        rr=[_rank_value(innovation_rank,T)]*len(names); policy='shared_user_rank'
    structures=[]; lambdas=[]
    for r in rr:
        structures.append('fa' if r==0 or not sparse else 'sparse_fa')
        lambdas.append(None if r==0 or not sparse else 'auto')
    return rr,structures,lambdas,policy


class _InconsistentPDAGError(ValueError):
    """Estimated orientation constraints admit no consistent DAG extension."""


def _sample_sem_orders(edge_graph, names, *, n_extensions=12, random_state=0):
    """Dor–Tarsi consistent extensions preserving skeleton and v-structures.

    A reciprocal directed edge represents an unresolved CPDAG edge. Cyclic or
    nonextendible inputs are rejected; identified directions are never deleted.

    Parameters
    ----------
    edge_graph : object (see the cited input contract)
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    n_extensions : int
        Input for the operation ``max(1, int(n_extensions))``. See
        ``vigor.multivariate._sample_sem_orders`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default: ``12``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``.
    """
    import networkx as nx
    names=list(map(str,names)); G=edge_graph
    P=nx.DiGraph(); P.add_nodes_from(names)
    for a,b in G.edges():
        a,b=str(a),str(b);P.add_edge(a,b)
        if not isinstance(G,nx.DiGraph):P.add_edge(b,a)
    strict=nx.DiGraph();strict.add_nodes_from(names)
    strict.add_edges_from((a,b) for a,b in P.edges() if not P.has_edge(b,a))
    if not nx.is_directed_acyclic_graph(strict):
        raise _InconsistentPDAGError('cyclic identified directions: DAG SEM does not support feedback')
    rng=np.random.default_rng(int(random_state));target=max(1,int(n_extensions));out=[];seen=set()
    for trial in range(max(8,target*8)):
        H=P.copy();sinks=[]
        while H:
            eligible=[]
            for x in sorted(H):
                if any(not H.has_edge(y,x) for y in H.successors(x)):continue
                neighbors=[y for y in H.successors(x) if H.has_edge(y,x)]
                parents=[y for y in H.predecessors(x) if not H.has_edge(x,y)]
                if all(H.has_edge(u,v) or H.has_edge(v,u)
                       for u in neighbors for v in neighbors+parents if u!=v):eligible.append(x)
            if not eligible:raise _InconsistentPDAGError('PDAG has no consistent DAG extension preserving its v-structures')
            x=eligible[0] if trial==0 else eligible[int(rng.integers(len(eligible)))]
            sinks.append(x);H.remove_node(x)
        order=tuple(reversed(sinks))
        if order not in seen:seen.add(order);out.append(list(order))
        if len(out)>=target:break
    return out


def _fit_sem_dag_ensemble(moments, edge_graph, *, ranks, names, trait_names,
                          initial_specs, ridge, structures, rotations, factor_lambda,
                          factor_group_lambda, factor_adaptive, factor_relaxed_refit,
                          factor_support_tol, factor_sparse_maxiter, factor_sparse_tol,
                          factor_auto_fraction, order=None, n_extensions=12, top_k=5,
                          sem_l1=0.0, sem_bound=3.0, initial_B=None, maxiter=500,
                          gtol=1e-7, ftol=1e-9, eps=1e-8, random_state=0,
                          path_min_abs=0.05):
    """Fit and score multiple DAG extensions instead of using one arbitrary trait order.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    edge_graph : object (see the cited input contract)
        Input supplied to ``fit_mom_sem_factor_analytic`` as ``edge_mask``. See that callable's
        documented ``edge_mask`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Passed to ``fit_mom_sem_factor_analytic`` as ``edge_mask``.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Passed to ``fit_mom_sem_factor_analytic`` as
        ``ranks``.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Passed to
        ``fit_mom_sem_factor_analytic`` as ``names``.

    trait_names : sequence or pandas.Index
        Trait labels in matrix-column order, used to label or align the resulting trait
        quantities. Passed to ``fit_mom_sem_factor_analytic`` as ``trait_names``.

    initial_specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Passed to
        ``fit_mom_sem_factor_analytic`` as ``initial_specs``.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Passed to ``fit_mom_sem_factor_analytic`` as ``ridge``.

    structures : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping.

    rotations : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state.

    factor_lambda : float, str, mapping or None
        Loading L1 penalty. Nonnegative numeric values set it explicitly; None/'auto' uses the
        factor_auto_fraction scale rule for sparse factors. The G setting may map kernel names
        to penalties; dense geometry ignores sparse penalties.

    factor_group_lambda : float, str or mapping
        Row-group loading penalty for sparse factors. Zero disables group sparsity; positive
        values penalize each trait's loading-row norm; 'auto' chooses a scale-relative penalty.
        The G setting may be per kernel.

    factor_adaptive : bool
        Whether sparse loading penalties are weighted adaptively using the initial loading
        magnitudes rather than a common weight.

    factor_relaxed_refit : bool
        Whether to refit loadings without shrinkage after selecting their support, retaining
        zeros fixed by sparse selection.

    factor_support_tol : float
        Absolute loading magnitude threshold used to define selected sparse support; nonnegative
        values determine which entries are fixed at zero for refitting.

    factor_sparse_maxiter : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity.

    factor_sparse_tol : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity.

    factor_auto_fraction : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity.

    order : sequence or None
        Topological trait/node ordering restricting paths to earlier-to-later edges. None lets
        the graph routine choose or infer a compatible acyclic ordering. Default: ``None``.

    n_extensions : int
        Input supplied to ``_sample_sem_orders`` as ``n_extensions``. See that callable's
        documented ``n_extensions`` contract for its type, alignment and value domain. This
        wrapper retains that contract. Default: ``12``. Passed to ``_sample_sem_orders`` as
        ``n_extensions``.

    top_k : int or None
        Maximum candidates/features retained by the corresponding ranking stage. Positive
        integers bound work/model size; None leaves retention to that stage's policy. Default:
        ``5``.

    sem_l1 : float
        Nonnegative L1 penalty on shared SEM path coefficients; zero leaves paths unpenalized.
        Default: ``0.0``. Passed to ``fit_mom_sem_factor_analytic`` as ``sem_l1``.

    sem_bound : float
        Positive absolute bound on each fitted SEM path coefficient, limiting extreme path
        amplification. Default: ``3.0``. Passed to ``fit_mom_sem_factor_analytic`` as
        ``sem_bound``.

    initial_B : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``. Passed to
        ``fit_mom_sem_factor_analytic`` as ``initial_B``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``500``. Passed to ``fit_mom_sem_factor_analytic`` as ``maxiter``.

    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``. Passed to ``fit_mom_sem_factor_analytic`` as ``gtol``.

    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-09``. Passed to ``fit_mom_sem_factor_analytic`` as ``ftol``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``fit_mom_sem_factor_analytic`` as
        ``eps``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_sample_sem_orders`` as ``random_state``.

    path_min_abs : float
        Minimum absolute correlation/path magnitude retained in the respective candidate or
        reporting stage; nonnegative values remove weak associations/paths. Default: ``0.05``.
    """
    orders=[list(order)] if order is not None else _sample_sem_orders(edge_graph,trait_names,n_extensions=n_extensions,random_state=random_state)
    fits=[]
    for oi,o in enumerate(orders):
        try:
            z=fit_mom_sem_factor_analytic(
                moments,ranks=ranks,names=names,trait_names=trait_names,initial_specs=initial_specs,
                edge_mask=edge_graph,order=o,ridge=ridge,structures=structures,rotations=rotations,
                factor_lambda=factor_lambda,factor_group_lambda=factor_group_lambda,
                factor_adaptive=factor_adaptive,factor_relaxed_refit=factor_relaxed_refit,
                factor_support_tol=factor_support_tol,factor_sparse_maxiter=factor_sparse_maxiter,
                factor_sparse_tol=factor_sparse_tol,factor_auto_fraction=factor_auto_fraction,
                sem_l1=sem_l1,sem_bound=sem_bound,initial_B=initial_B,maxiter=maxiter,
                gtol=gtol,ftol=ftol,eps=eps)
            if np.isfinite(z['objective']): fits.append((float(z['objective']),oi,o,z))
        except Exception:
            continue
    if not fits: raise RuntimeError('no acyclic SEM extension could be fitted')
    fits.sort(key=lambda x:x[0])
    converged=[x for x in fits if bool(x[3]['success'])]
    selectable=converged or fits
    best_obj=float(selectable[0][0]); tie_tol=max(1e-8,1e-6*max(1.0,abs(best_obj)))
    tied=[x for x in selectable if float(x[0])-best_obj<=tie_tol]
    keep=tied if len(tied)>1 else selectable[:max(1,min(int(top_k),len(selectable)))]; best=dict(keep[0][3])
    best['selection_status']='optimizer_success' if converged else 'finite_optimizer_failure_diagnostic'
    # Failed finite fits remain available for diagnostics and warm starts, but
    # cannot contribute numerical path support or identified path estimates.

    if order is None:
        import networkx as nx
        directed_constraints=(isinstance(edge_graph,nx.DiGraph) and any(
            edge_graph.has_edge(str(a),str(b)) and not edge_graph.has_edge(str(b),str(a))
            for a,b in edge_graph.edges()))
        best['order_source']='pc_anm_constrained_dag_extension' if directed_constraints else 'sampled_dag_extension'
    p=len(trait_names); rows=[]; total_rows=[]; threshold=float(path_min_abs)
    # Orientation sensitivity is computed across optimizer-successful sampled DAG
    # extensions, not just the numerically best one. A score preference among
    # Markov-compatible extensions is not treated as causal identification.
    for i in range(p) if converged else []:
        for j in range(i+1,p):
            a,b=str(trait_names[i]),str(trait_names[j]); ab=[];ba=[];vals_ab=[];vals_ba=[];te_ab=[];te_ba=[]
            for _,_,_,z in converged:
                B=np.asarray(z['B'],float);H=np.asarray(z['H'],float);va=float(B[j,i]);vb=float(B[i,j])
                ab.append(abs(va)>=threshold);ba.append(abs(vb)>=threshold);vals_ab.append(va);vals_ba.append(vb)
                te_ab.append(float(H[j,i]));te_ba.append(float(H[i,j]))
            fa=float(np.mean(ab));fb=float(np.mean(ba));active=max(fa,fb)
            if active<=0 and max(np.max(np.abs(te_ab)),np.max(np.abs(te_ba)))<threshold:continue
            if fa>fb:direction=f'{a}->{b}';vals=np.asarray(vals_ab);support=fa
            elif fb>fa:direction=f'{b}->{a}';vals=np.asarray(vals_ba);support=fb
            else:direction='unstable';vals=np.r_[vals_ab,vals_ba];support=active
            strict_ab=isinstance(edge_graph,__import__('networkx').DiGraph) and edge_graph.has_edge(a,b) and not edge_graph.has_edge(b,a)
            strict_ba=isinstance(edge_graph,__import__('networkx').DiGraph) and edge_graph.has_edge(b,a) and not edge_graph.has_edge(a,b)
            identified_direction=(f'{a}->{b}' if strict_ab else f'{b}->{a}' if strict_ba else None)
            source='pc_meek_or_stable_anm' if identified_direction is not None else ('user_order' if order is not None else 'unresolved_cpdag')
            nz=vals[np.abs(vals)>=threshold];sign_stability=float(max(np.mean(nz>0),np.mean(nz<0))) if len(nz) else 0.0
            rows.append((a,b,direction,support,active,sign_stability,float(np.median(nz)) if len(nz) else 0.0,identified_direction,source,identified_direction is not None))
            for src,tgt,te in [(a,b,np.asarray(te_ab)),(b,a,np.asarray(te_ba))]:
                total_rows.append((src,tgt,float(np.min(te)),float(np.median(te)),float(np.max(te)),float(np.mean(np.abs(te)>=threshold)),float(max(np.mean(te>=0),np.mean(te<=0)))))
    stab=pd.DataFrame(rows,columns=['trait_a','trait_b','score_preferred_direction','direction_support','active_support','sign_stability','median_path','identified_direction','orientation_source','direction_identified'])
    total_stab=pd.DataFrame(total_rows,columns=['source','target','total_effect_min','total_effect_median','total_effect_max','nonzero_fraction','sign_stability'])
    tab=pd.DataFrame([{'extension':k,'objective':obj,'success':bool(z['success']),'order':'|'.join(o),
                       'n_paths':int(np.count_nonzero(np.abs(z['B'])>=threshold))}
                      for k,(obj,_,o,z) in enumerate(fits)])
    return {'best':best,'fits':[z for _,_,_,z in keep],'extensions':tab,'path_stability':stab,
            'total_effect_sensitivity':total_stab,
            'n_extensions_fit':len(fits),'n_extensions_optimizer_success':len(converged),
            'selected_fit_status':best['selection_status'],
            'path_stability_scope':'optimizer-successful extensions only; all finite fits retained in extensions',
            'n_extensions_used':len(keep),'path_min_abs':threshold,
            'objective_tie_tolerance':float(tie_tol),'n_near_tied_extensions':int(len(tied))}


def _fit_structural_refinement_loop(
    moments, base_fit, traits, *, knames, names, ranks, ridge, structures, rotations,
    factor_lambda, factor_group_lambda, factor_adaptive, factor_relaxed_refit,
    factor_support_tol, factor_sparse_maxiter, factor_sparse_tol, factor_auto_fraction,
    outer_iter=2, pc_source="phenotypic", pc_alpha=0.01, pc_max_cond_set=2,
    pc_multiple_testing="none", pc_n_eff="overlap", pc_max_neighbors=20,
    pc_min_abs_r=0.05, pc_stability_bootstrap=12, pc_edge_stability=0.65,
    pc_direction_stability=0.75, anm=False, anm_min_ratio=1.20,
    anm_stability_bootstrap=8, anm_direction_stability=0.75,
    required_edges=None, forbidden_edges=None, order=None,
    sem_l1=0.0, sem_bound=3.0, sem_innovation_rank="diagonal",
    sem_innovation_sparse=True, dag_extensions=12, dag_topk=5,
    path_min_abs=0.05, maxiter=500, covariance_maxiter=None, gtol=1e-7, ftol=1e-9,
    eps=1e-8, random_state=0, progress=None,
):
    """Identifiability-aware PC/ANM -> DAG-extension -> structural MoM loop.

    The ordinary PSD/FA covariance fit remains unrestricted by this causal
    layer. PC uses test-wise complete observations plus bootstrap stability for
    phenotypic discovery; unresolved CPDAG edges are evaluated across multiple
    acyclic extensions; SEM innovations are constrained independently of the
    inference covariance rank so a saturated residual covariance cannot erase B.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    base_fit : array-like, table or fitted object
        Reference input or fitted state supplying alignment, initialization or baseline
        quantities. Match the axes/component order of the operation; see the corresponding
        fit/preparation routine for required fields.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    knames : object (see the cited input contract)
        Compatibility/callback input accepted but not consumed by this body. Any object is
        locally accepted; see the calling protocol for the supplied type.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Passed to
        ``_fit_sem_dag_ensemble`` as ``names``.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Passed to ``fit_mom_factor_analytic`` as ``ranks``.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Passed to ``_fit_sem_dag_ensemble`` as ``ridge``.

    structures : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping.

    rotations : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state.

    factor_lambda : float, str, mapping or None
        Loading L1 penalty. Nonnegative numeric values set it explicitly; None/'auto' uses the
        factor_auto_fraction scale rule for sparse factors. The G setting may map kernel names
        to penalties; dense geometry ignores sparse penalties.

    factor_group_lambda : float, str or mapping
        Row-group loading penalty for sparse factors. Zero disables group sparsity; positive
        values penalize each trait's loading-row norm; 'auto' chooses a scale-relative penalty.
        The G setting may be per kernel.

    factor_adaptive : bool
        Whether sparse loading penalties are weighted adaptively using the initial loading
        magnitudes rather than a common weight.

    factor_relaxed_refit : bool
        Whether to refit loadings without shrinkage after selecting their support, retaining
        zeros fixed by sparse selection.

    factor_support_tol : float
        Absolute loading magnitude threshold used to define selected sparse support; nonnegative
        values determine which entries are fixed at zero for refitting.

    factor_sparse_maxiter : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity.

    factor_sparse_tol : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity.

    factor_auto_fraction : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity.

    outer_iter : int
        Number of covariance/graph/SEM outer iterations when structural refinement is enabled; a
        positive cap bounds the alternating procedure. Default: ``2``.

    pc_source : str
        Covariance used for PC graph discovery: 'phenotypic' uses total modeled covariance;
        'genetic' uses summed genetic covariance; 'residual' uses E. See
        _structural_refinement_loop for accepted aliases and component-name support. Default:
        ``'phenotypic'``. Source-recognized literal values: ``p``, ``vp``. These select the
        corresponding branches below; comparison evidence alone does not establish an exhaustive
        enum.

    pc_alpha : float
        Conditional-independence significance level for PC skeleton tests, ordinarily between
        zero and one. Default: ``0.01``.

    pc_max_cond_set : int
        Largest conditioning-set size examined by PC independence tests; nonnegative integers
        limit combinatorial search. Default: ``2``.

    pc_multiple_testing : str
        PC edge-test correction: 'none' leaves nominal p-values; 'bonferroni' divides alpha by
        test count; 'fdr_bh' uses Benjamini-Hochberg FDR. See pc_from_covariance for aliases and
        stage-specific behavior. Default: ``'none'``.

    pc_n_eff : float, array-like or None
        Effective sample count(s) for covariance/conditional-independence calibration. Pair
        matrices match variable-pair order; None delegates to the routine's
        covariance-bootstrap/sample-count policy. Default: ``'overlap'``. Source-recognized
        literal values: ``auto``. These select the corresponding branches below; comparison
        evidence alone does not establish an exhaustive enum.

    pc_max_neighbors : int
        Maximum retained PC candidate neighbors per trait, bounding graph search work. Default:
        ``20``.

    pc_min_abs_r : float
        Minimum absolute correlation/path magnitude retained in the respective candidate or
        reporting stage; nonnegative values remove weak associations/paths. Default: ``0.05``.

    pc_stability_bootstrap : int
        Bootstrap replicate count for the corresponding graph edge/direction stability analysis;
        zero disables that resampling stage. Default: ``12``.

    pc_edge_stability : float
        Minimum resampling support fraction in [0, 1] required to retain the corresponding
        adjacency or direction. Default: ``0.65``.

    pc_direction_stability : float
        Minimum resampling support fraction in [0, 1] required to retain the corresponding
        adjacency or direction. Default: ``0.75``.

    anm : bool
        Whether additive-noise-model direction checks supplement PC orientation; directions
        remain observational and may abstain. Default: ``False``.

    anm_min_ratio : float
        Minimum forward/reverse additive-noise independence-score ratio required before
        proposing a direction; values above one demand stronger asymmetry. Default: ``1.2``.

    anm_stability_bootstrap : int
        Bootstrap replicate count for the corresponding graph edge/direction stability analysis;
        zero disables that resampling stage. Default: ``8``.

    anm_direction_stability : float
        Minimum resampling support fraction in [0, 1] required to retain the corresponding
        adjacency or direction. Default: ``0.75``.

    required_edges : sequence of pairs or None
        Trait-name/index pairs that must be retained or excluded respectively during graph
        refinement. None imposes no such constraints; required directions must remain compatible
        with acyclicity. Default: ``None``.

    forbidden_edges : sequence of pairs or None
        Trait-name/index pairs that must be retained or excluded respectively during graph
        refinement. None imposes no such constraints; required directions must remain compatible
        with acyclicity. Default: ``None``.

    order : sequence or None
        Topological trait/node ordering restricting paths to earlier-to-later edges. None lets
        the graph routine choose or infer a compatible acyclic ordering. Default: ``None``.
        Passed to ``_fit_sem_dag_ensemble`` as ``order``.

    sem_l1 : float
        Nonnegative L1 penalty on shared SEM path coefficients; zero leaves paths unpenalized.
        Default: ``0.0``. Passed to ``_fit_sem_dag_ensemble`` as ``sem_l1``.

    sem_bound : float
        Positive absolute bound on each fitted SEM path coefficient, limiting extreme path
        amplification. Default: ``3.0``. Passed to ``_fit_sem_dag_ensemble`` as ``sem_bound``.

    sem_innovation_rank : int, str or sequence
        Innovation rank policy: 'diag'/'diagonal'/'identifiable'/'auto_identifiable' keeps
        identifiable diagonal innovations; 'inherit'/'covariance' reuses covariance ranks;
        integer ranks select constrained latent innovations. See
        _resolve_structural_innovation_model for componentwise behavior. Default:
        ``'diagonal'``.

    sem_innovation_sparse : bool
        Whether innovation factors use sparse support when the SEM innovation rank includes
        latent factors. Default: ``True``. Passed to ``_resolve_structural_innovation_model`` as
        ``sparse``.

    dag_extensions : int
        Maximum acyclic extensions examined or best moment-scored DAGs retained, respectively;
        positive counts bound graph-model selection work. Default: ``12``. Passed to
        ``_fit_sem_dag_ensemble`` as ``n_extensions``.

    dag_topk : int
        Maximum acyclic extensions examined or best moment-scored DAGs retained, respectively;
        positive counts bound graph-model selection work. Default: ``5``. Passed to
        ``_fit_sem_dag_ensemble`` as ``top_k``.

    path_min_abs : float
        Minimum absolute correlation/path magnitude retained in the respective candidate or
        reporting stage; nonnegative values remove weak associations/paths. Default: ``0.05``.
        Passed to ``_fit_sem_dag_ensemble`` as ``path_min_abs``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``500``. Passed to ``_fit_sem_dag_ensemble`` as ``maxiter``.

    covariance_maxiter : object (see the cited input contract)
        Input supplied to ``fit_mom_factor_analytic`` as ``maxiter``. See that callable's
        documented ``maxiter`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``fit_mom_factor_analytic`` as ``maxiter``.

    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``. Passed to ``_fit_sem_dag_ensemble`` as ``gtol``.

    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-09``. Passed to ``_fit_sem_dag_ensemble`` as ``ftol``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_fit_sem_dag_ensemble`` as
        ``eps``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_fit_sem_dag_ensemble`` as ``random_state``.

    progress : bool
        Whether to emit progress/status reporting during this operation. False disables the
        corresponding reporting path. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value.
    """
    from .causal import pc_from_covariance, pc_stability_from_data, anm_orient_candidates
    from .results import _result_table
    if bool(anm) and str(pc_source).lower() not in {'phenotypic','p','vp','total'}:
        raise ValueError('ANM requires observed component data for non-phenotypic PC; phenotype outcomes cannot orient genetic/residual structure')
    import networkx as nx
    covariance_maxiter=int(maxiter if covariance_maxiter is None else covariance_maxiter)
    current=base_fit; history=[];pc_last=None;anm_last=None;sem_last=None;ensemble_last=None
    Y=traits if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits)
    trait_names=list(map(str,Y.columns));Y2=Y.copy();Y2.columns=trait_names;T=len(trait_names)
    if required_edges is not None:
        user_directions=nx.DiGraph((str(a),str(b)) for a,b in required_edges)
        if not set(user_directions).issubset(trait_names):raise ValueError('required structural edges reference unknown traits')
        if not nx.is_directed_acyclic_graph(user_directions):raise ValueError('cyclic user-required structural directions do not define a DAG')
    overlap=Y.notna().astype(np.int64).T@Y.notna().astype(np.int64)
    phenotypic_cov=Y2.cov(min_periods=4).to_numpy(float);diag=np.nanvar(Y2.to_numpy(float),axis=0,ddof=1)
    bad=~np.isfinite(phenotypic_cov);phenotypic_cov[bad]=0.0
    for j in range(len(diag)):phenotypic_cov[j,j]=diag[j] if np.isfinite(diag[j]) and diag[j]>0 else float(eps)
    phenotypic_cov=_sym(phenotypic_cov)
    if isinstance(pc_n_eff,str) and pc_n_eff.lower() in {"overlap","auto"}:
        ov=overlap.to_numpy(float);iu=np.triu_indices_from(ov,1);vals=ov[iu];vals=vals[vals>0]
        n_eff=float(np.quantile(vals,0.25)) if vals.size else float(Y.notna().sum().min())
    else:n_eff=float(pc_n_eff)
    n_eff=max(n_eff,4.0)
    sem_ranks,sem_structures,sem_lambdas,innovation_policy=_resolve_structural_innovation_model(
        sem_innovation_rank,ranks,names,T,sparse=bool(sem_innovation_sparse))
    B0=None;nouter=max(1,int(outer_iter));outer_stable=False

    def discover_graph(current_fit,seed_offset=0):
        """Discover a PC/optional ANM candidate graph from the current covariance and observations.

        Parameters
        ----------
        current_fit : array-like, table or fitted object
            Reference input or fitted state supplying alignment, initialization or baseline
            quantities. Match the axes/component order of the operation; see the corresponding
            fit/preparation routine for required fields.

        seed_offset : int
            Integer added to the base random seed for this fold/stage, separating reproducible
            random streams. Default: ``0``. Passed to ``pc_stability_from_data`` as
            ``random_state``.

        Returns
        -------
        object
            Computed result from ``(pc, anmres)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Cgraph=_structural_graph_covariance(current_fit,knames,source=pc_source,phenotypic_cov=phenotypic_cov)
        pc_seed=_screen_pc_candidates(Cgraph,trait_names,max_neighbors=pc_max_neighbors,min_abs_r=pc_min_abs_r)
        source=str(pc_source).lower()
        if source in {'phenotypic','p','vp','total'} and int(pc_stability_bootstrap)>0:
            pc=pc_stability_from_data(
                Y2,n_boot=int(pc_stability_bootstrap),edge_threshold=float(pc_edge_stability),
                direction_threshold=float(pc_direction_stability),random_state=int(random_state)+seed_offset,
                alpha=pc_alpha,max_cond_set=pc_max_cond_set,multiple_testing=pc_multiple_testing,
                required_edges=required_edges,forbidden_edges=forbidden_edges,initial_graph=pc_seed)
        else:
            pc=pc_from_covariance(Cgraph,names=trait_names,alpha=pc_alpha,n_eff=n_eff,
                max_cond_set=pc_max_cond_set,multiple_testing=pc_multiple_testing,
                required_edges=required_edges,forbidden_edges=forbidden_edges,initial_graph=pc_seed,
                data=Y2 if source in {'phenotypic','p','vp','total'} else None)
        anmres=None
        if bool(anm) and pc.sizes.get('edge',0):
            edges=pc[['source','target','orientation']].to_dataframe().reset_index(drop=True); unresolved=edges[edges['orientation'].eq('undirected')]
            if len(unresolved):
                anmres=anm_orient_candidates(Y2,unresolved,names=trait_names,min_ratio=anm_min_ratio,
                                              random_state=int(random_state)+seed_offset+7919,
                                              n_bootstrap=int(anm_stability_bootstrap),
                                              direction_stability=float(anm_direction_stability))
                P=pc.attrs['graph'].copy()
                for rr in _result_table(anmres,'orientations').itertuples(index=False):
                    a=getattr(rr,'source',None);b=getattr(rr,'target',None)
                    if a is None or b is None:continue
                    a,b=str(a),str(b)
                    if P.has_edge(a,b) and P.has_edge(b,a):
                        # accept ANM only if it does not create a directed cycle
                        P.remove_edge(b,a)
                        D=nx.DiGraph();D.add_nodes_from(trait_names)
                        for u,v in P.edges():
                            if not P.has_edge(v,u):D.add_edge(u,v)
                        if not nx.is_directed_acyclic_graph(D):P.add_edge(b,a)
                pc=pc.copy();pc.attrs['graph']=P;pc.attrs['orientation_evidence_applied']='ANM_unresolved_only'
        return pc,anmres

    def unsupported_graph(error,phase):
        # Keep the valid unrestricted covariance estimate and the failed graph.
        # NaN paths mean unavailable inference; zero would imply a fitted null.
        """Record an abstention when the estimated partial graph admits no supported DAG extension.

        Parameters
        ----------
        error : mapping or array-like
            Fit/operator error diagnostics consumed by this report or promotion check. Use the
            values produced by the corresponding evaluation step on the same fitted model.

        phase : object (see the cited input contract)
            Input for the operation ``history.append({'outer_iteration': len(history) + 1, 'phase':
            phase, 'structural_status': 'unsupported_pdag', 'message': str(error),
            'graph_signature': tuple(sorted(pc_last.attrs['graph'].edges())), 'dag_extensions': 0,
            'sem_optimizer_run': Fa...``. See
            ``vigor.multivariate._fit_structural_refinement_loop.unsupported_graph`` and its caller
            for the scientific representation; the shown operation constrains the required
            type/shape.

        Returns
        -------
        dict
            Result fields: ``fit``, ``sem``, ``sem_ensemble``, ``pc``, ``anm``, ``history``, ``pc_n_eff``, ``pc_source``, ``structural_status``, ``message``, ``innovation_ranks``, ``innovation_structures``, ``innovation_policy``, ``note``. Field arrays preserve the corresponding input axis order.
        """
        history.append({'outer_iteration':len(history)+1,'phase':phase,
                        'structural_status':'unsupported_pdag','message':str(error),
                        'graph_signature':tuple(sorted(pc_last.attrs['graph'].edges())),
                        'dag_extensions':0,'sem_optimizer_run':False})
        return {'fit':current,'sem':None,'sem_ensemble':None,'pc':pc_last,'anm':anm_last,
                'history':pd.DataFrame(history),'pc_n_eff':n_eff,'pc_source':pc_source,
                'structural_status':'unsupported_pdag','message':str(error),
                'innovation_ranks':dict(zip(names,sem_ranks)),
                'innovation_structures':dict(zip(names,sem_structures)),
                'innovation_policy':innovation_policy,
                'note':'Estimated PDAG is nonextendible; no directions deleted, invented or fit. Valid unrestricted covariance retained; any earlier completed refinement iterations remain in history.'}

    for oit in range(nouter):
        if progress is not None:
            try:progress.stage(f"Structural refinement: stable graph {oit+1}/{nouter}")
            except Exception:pass
        pc_last,anm_last=discover_graph(current,101*oit)
        if progress is not None:
            try:progress.stage(f"Structural refinement: DAG ensemble {oit+1}/{nouter}")
            except Exception:pass
        try:
            ensemble_last=_fit_sem_dag_ensemble(
                moments,pc_last.attrs['graph'],ranks=sem_ranks,names=names,trait_names=trait_names,
                initial_specs=current['specs'],ridge=ridge,structures=sem_structures,
                rotations=[None]*len(names),factor_lambda=sem_lambdas,factor_group_lambda=[0.0]*len(names),
                factor_adaptive=factor_adaptive,factor_relaxed_refit=factor_relaxed_refit,
                factor_support_tol=factor_support_tol,factor_sparse_maxiter=factor_sparse_maxiter,
                factor_sparse_tol=factor_sparse_tol,factor_auto_fraction=factor_auto_fraction,order=order,
                n_extensions=dag_extensions,top_k=dag_topk,sem_l1=sem_l1,sem_bound=sem_bound,
                initial_B=B0,maxiter=maxiter,gtol=gtol,ftol=ftol,eps=eps,
                random_state=int(random_state)+1009*oit,path_min_abs=path_min_abs)
        except _InconsistentPDAGError as error:
            return unsupported_graph(error,'outer_ensemble' if B0 is None else 'final_or_later_ensemble')
        sem_last=ensemble_last['best'];previous_B=B0;B0=sem_last['B'];previous_matrices=current['matrices']
        # Refit the ordinary covariance model at its original rank/support. This
        # preserves the inference estimand and uses SEM only as a structural warm start.
        warm={n:as_covariance_spec(sem_last['matrices'][n],name=n) for n in names}
        current=fit_mom_factor_analytic(
            moments,ranks=ranks,names=names,ridge=ridge,warm_start=warm,
            structures=structures,rotations=rotations,factor_lambda=factor_lambda,
            factor_group_lambda=factor_group_lambda,factor_adaptive=factor_adaptive,
            factor_relaxed_refit=factor_relaxed_refit,factor_support_tol=factor_support_tol,
            factor_sparse_maxiter=factor_sparse_maxiter,factor_sparse_tol=factor_sparse_tol,
            factor_auto_fraction=factor_auto_fraction,maxiter=covariance_maxiter,gtol=gtol,ftol=ftol,eps=eps)
        stable_paths=int(((ensemble_last['path_stability']['direction_support']>=float(pc_direction_stability)) & ensemble_last['path_stability']['direction_identified']).sum()) if len(ensemble_last['path_stability']) else 0
        history.append({'outer_iteration':oit+1,'sem_objective':float(sem_last['objective']),
                        'graph_signature':tuple(sorted(pc_last.attrs['graph'].edges())),
                        'B_relative_delta':float(np.linalg.norm(B0-previous_B)/max(1.,np.linalg.norm(previous_B))) if previous_B is not None else np.inf,
                        'covariance_relative_delta':max(float(np.linalg.norm(current['matrices'][n]-previous_matrices[n])/max(1.,np.linalg.norm(previous_matrices[n]))) for n in names),
                        'psd_objective':float(current['objective']),'covariance_maxiter':covariance_maxiter,'sem_maxiter':int(maxiter),
                        'covariance_success':bool(current['success']),'sem_success':bool(sem_last['success']),
                        'sem_warm_start_optimizer_success':bool(sem_last['success']),'pc_edges':int(pc_last.sizes.get('edge',0)),
                        'pc_stable_edges':int(pc_last.sizes.get('edge',0)),'dag_extensions':int(ensemble_last['n_extensions_fit']),
                        'stable_sem_paths':stable_paths,'sem_paths':int(np.count_nonzero(np.abs(sem_last['B'])>=float(path_min_abs)))})
        if len(history)>1:
            a,b=history[-2],history[-1];same=a['graph_signature']==b['graph_signature'] and a['stable_sem_paths']==b['stable_sem_paths']
            rel=abs(a['psd_objective']-b['psd_objective'])/max(1.0,abs(a['psd_objective']))
            if same and rel<1e-6 and b['B_relative_delta']<1e-5 and b['covariance_relative_delta']<1e-5:
                outer_stable=True
                break
    # Final graph/ensemble is reported from the final unrestricted covariance fit.
    pc_last,anm_last=discover_graph(current,9991)
    try:
        ensemble_last=_fit_sem_dag_ensemble(
            moments,pc_last.attrs['graph'],ranks=sem_ranks,names=names,trait_names=trait_names,
            initial_specs=current['specs'],ridge=ridge,structures=sem_structures,rotations=[None]*len(names),
            factor_lambda=sem_lambdas,factor_group_lambda=[0.0]*len(names),factor_adaptive=factor_adaptive,
            factor_relaxed_refit=factor_relaxed_refit,factor_support_tol=factor_support_tol,
            factor_sparse_maxiter=factor_sparse_maxiter,factor_sparse_tol=factor_sparse_tol,
            factor_auto_fraction=factor_auto_fraction,order=order,n_extensions=dag_extensions,top_k=dag_topk,
            sem_l1=sem_l1,sem_bound=sem_bound,initial_B=B0,maxiter=maxiter,gtol=gtol,ftol=ftol,eps=eps,
            random_state=int(random_state)+19991,path_min_abs=path_min_abs)
    except _InconsistentPDAGError as error:
        return unsupported_graph(error,'outer_ensemble' if B0 is None else 'final_or_later_ensemble')
    sem_last=ensemble_last['best']
    optimizer_success=bool(current['success'] and sem_last['success'])
    # Outer stability is a stopping diagnostic, not an optimizer stationarity test.
    loop_status=('stable_optimizer_success' if optimizer_success else 'stable_optimizer_failure') if outer_stable else 'outer_iteration_cap'
    return {'loop_status':loop_status,'outer_stable':outer_stable,
            'optimizer_success':optimizer_success,'stationary_convergence_certified':False,
            'structural_status':'optimizer_success' if sem_last['success'] else 'optimizer_failure',
            'fit':current,'sem':sem_last,'sem_ensemble':ensemble_last,'pc':pc_last,'anm':anm_last,
            'history':pd.DataFrame(history),'pc_n_eff':n_eff,'pc_source':pc_source,
            'pc_max_neighbors':pc_max_neighbors,'pc_min_abs_r':float(pc_min_abs_r),
            'pc_stability_bootstrap':int(pc_stability_bootstrap),'pc_edge_stability':float(pc_edge_stability),
            'pc_direction_stability':float(pc_direction_stability),'innovation_ranks':dict(zip(names,sem_ranks)),
            'innovation_structures':dict(zip(names,sem_structures)),'innovation_policy':innovation_policy,
            'note':'Causal SEM uses constrained innovations and DAG-extension stability; final bare G/E/Rg remain the unrestricted support-fixed PSD/FA inference estimator.'}


def _leading_eigh(M, rank):
    """Leading eigenpairs of a symmetric trait covariance.

    ARPACK can become extremely slow for phenome covariance matrices with a
    broad/flat leading spectrum.  LAPACK EVR supports index-subset extraction
    and is much faster and more predictable through the ~1000-trait regime.

    Parameters
    ----------
    M : array-like
        Numerical operand in ``M.shape[0]``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.

    rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Source comparisons: ``rank == 0``; ``rank >= 64``.
        See the rejection/fallback branches for enforcement. Passed to ``scipy_eigh`` as
        ``subset_by_index``.
    """
    M = _sym(np.nan_to_num(np.asarray(M, dtype=float), nan=0.0, posinf=0.0, neginf=0.0))
    T = M.shape[0]
    rank = max(0, min(int(rank), T))
    if rank == 0:
        return np.empty(0), np.zeros((T, 0))
    if rank >= T:
        w, V = scipy_eigh(M, driver="evr", check_finite=False)
        idx = np.argsort(w)[::-1]
        return w[idx], V[:, idx]
    # EVR subset is deterministic and robust for the intended 1k-trait
    # phenotype scale; use ARPACK only for substantially larger matrices with
    # a genuinely small requested rank.
    if T <= 1600 or rank >= 64 or rank >= max(32, T // 8):
        w, V = scipy_eigh(M, subset_by_index=(T-rank, T-1), driver="evr", check_finite=False)
        idx = np.argsort(w)[::-1]
        return w[idx], V[:, idx]
    try:
        w, V = eigsh(M, k=rank, which="LA", tol=1e-6, maxiter=max(1000, 10*T))
        idx = np.argsort(w)[::-1]
        return w[idx], V[:, idx]
    except Exception:
        w, V = scipy_eigh(M, subset_by_index=(T-rank, T-1), driver="evr", check_finite=False)
        idx = np.argsort(w)[::-1]
        return w[idx], V[:, idx]


def _rank1_weight_scale(W, eps=1e-12):
    """Approximate non-negative entry weights by d_i^2 d_j^2.

    If W ~= a a', D=diag(sqrt(a)) turns weighted Frobenius loss into an
    ordinary Frobenius loss on D C D.  This is exact for separable weights and
    is used only in the spectral projection stage; the optional refine solver
    subsequently optimizes the original exact MoM objective.

    Parameters
    ----------
    W : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.
    """
    W = np.maximum(_sym(np.asarray(W, dtype=float)), 0.0)
    T = W.shape[0]
    norm = float(np.linalg.norm(W))
    if not np.isfinite(norm) or norm <= eps:
        return np.ones(T, dtype=float), np.nan
    try:
        if T <= 192:
            ew, ev = np.linalg.eigh(W)
            lam = max(float(ew[-1]), 0.0)
            u = np.abs(ev[:, -1])
        else:
            ew, ev = eigsh(W, k=1, which="LA", tol=1e-6)
            lam = max(float(ew[0]), 0.0)
            u = np.abs(ev[:, 0])
    except Exception:
        ew, ev = np.linalg.eigh(W)
        lam = max(float(ew[-1]), 0.0)
        u = np.abs(ev[:, -1])
    if lam <= eps or not np.any(u > 0):
        return np.ones(T, dtype=float), 1.0
    a = np.sqrt(lam) * u
    # d_i^2 = a_i, so W_ij ~= d_i^2 d_j^2.
    floor = max(float(np.median(a[a > 0])) * 1e-8 if np.any(a > 0) else eps, eps)
    d = np.sqrt(np.maximum(a, floor))
    approx = np.outer(a, a)
    rel = float(np.linalg.norm(W - approx) / max(norm, eps))
    return d, rel


def _spectral_project_spec(target, rank, *, structure="fa", weights=None,
                           weight_mode="rank1", fa_sweeps=4, eps=1e-8, name="covariance"):
    """Fast PSD/low-rank projection used by the VIGOR 2.8 spectral solver.

    ``structure='psd'`` returns the closed-form rank-r positive spectral
    truncation. ``structure='fa'`` alternates that exact spectral update with
    the closed-form diagonal-specific-variance update.  When pairwise MoM
    information is heterogeneous, ``weight_mode='rank1'`` uses the best
    separable leading-rank approximation to the entry weights.  The exact
    weighted objective can then be polished with ``solver='spectral_refine'``.

    Parameters
    ----------
    target : str, index or sequence
        Response/trait identifiers selected for this prediction, mediation or subset operation.
        Names/positions must exist in the supplied response axes; sequences preserve the
        requested ordering.

    rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Source comparisons: ``rank == 0``. See the
        rejection/fallback branches for enforcement.

    structure : str
        Input for the operation ``str(structure).lower()``. See
        ``vigor.multivariate._spectral_project_spec`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``'fa'``. Source-recognized literal values: ``lowrank``, ``psd``, ``spectral``,
        ``strict``. These select the corresponding branches below; comparison evidence alone
        does not establish an exhaustive enum.

    weights : array-like or int
        Weights or multiplicities used in this accumulation/resampling step. Align vector
        entries with the indexed sample/variant axis; scalar counts specify the number of
        consecutive items. Default: ``None``. None delegates to the local fallback shown in this
        body; it is not an additional numeric/category value.

    weight_mode : str
        Input for the operation ``str(weight_mode).lower()``. See
        ``vigor.multivariate._spectral_project_spec`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``'rank1'``. Source-recognized literal values: ``information``, ``separable``. These
        select the corresponding branches below; comparison evidence alone does not establish an
        exhaustive enum.

    fa_sweeps : int
        Number of alternating/projection/relevance/eigenspace refinement iterations performed by
        the selected algorithm. Positive counts trade additional work for a more settled
        approximation. Default: ``4``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_rank1_weight_scale`` as ``eps``.

    name : str
        Identifier used to select or label the relevant component, field or output quantity. It
        must match the names present in the supplied object where lookup is required. Default:
        ``'covariance'``. Passed to ``FactorCovarianceSpec`` as ``name``.
    """
    C = _sym(np.nan_to_num(np.asarray(target, dtype=float), nan=0.0, posinf=0.0, neginf=0.0))
    T = C.shape[0]
    rank = _rank_value(rank, T)
    mode = str(weight_mode).lower()
    if weights is not None and mode in {"rank1", "separable", "information"}:
        d, weight_error = _rank1_weight_scale(weights, eps=max(eps, 1e-14))
    else:
        d, weight_error = np.ones(T, dtype=float), np.nan
    H = _sym((d[:, None] * C) * d[None, :])
    kind = str(structure).lower()
    if kind in {"psd", "strict", "lowrank", "spectral"} or rank >= T:
        w, V = _leading_eigh(H, rank)
        keep = w > max(eps, 1e-12 * max(float(np.max(np.abs(w))) if w.size else 1.0, 1.0))
        w = np.maximum(w[keep], 0.0)
        V = V[:, keep]
        Fh = V * np.sqrt(w)[None, :] if w.size else np.zeros((T, 0))
        psi_h = np.zeros(T, dtype=float)
        sweeps = 1
    elif rank == 0:
        Fh = np.zeros((T, 0), dtype=float)
        psi_h = np.maximum(np.diag(H), eps)
        sweeps = 1
    else:
        # Principal-factor iteration: each low-rank update is an exact spectral
        # solution conditional on Psi, and each Psi update is closed form.
        psi_h = np.maximum(0.10 * np.maximum(np.diag(H), 0.0), eps)
        Fh = np.zeros((T, rank), dtype=float)
        sweeps = 0
        for it in range(max(1, int(fa_sweeps))):
            R = _sym(H - np.diag(psi_h))
            w, V = _leading_eigh(R, rank)
            keep = w > max(eps, 1e-12 * max(float(np.max(np.abs(w))) if w.size else 1.0, 1.0))
            wp = np.maximum(w[keep], 0.0)
            Vp = V[:, keep]
            Fnew = Vp * np.sqrt(wp)[None, :] if wp.size else np.zeros((T, 0))
            common = Fnew @ Fnew.T
            pnew = np.maximum(np.diag(H - common), eps)
            sweeps = it + 1
            rel = float(np.linalg.norm(pnew - psi_h) / max(np.linalg.norm(psi_h), 1e-30))
            Fh, psi_h = Fnew, pnew
            if rel < 1e-6:
                break
    invd = 1.0 / np.maximum(d, max(eps, 1e-14))
    F = invd[:, None] * Fh
    psi = (invd * invd) * psi_h
    spec = FactorCovarianceSpec(F, np.maximum(psi, 0.0), name=name)
    return spec, {"weight_rank1_relative_error": weight_error, "fa_sweeps": int(sweeps)}



def _profile_component_information(Aeff, *, eps=1e-12, trait_chunk=64):
    """Diagonal Schur information for each covariance component, vectorized.

    For each trait pair the unconstrained MoM covariance is proportional to
    ``A^{-1}``; therefore ``1 / (A^{-1})_rr`` is the profile information for
    component r.  Batched inversion avoids Python loops over O(T^2) pairs and
    bounds temporary memory for thousand-trait phenomes.

    Parameters
    ----------
    Aeff : object (see the cited input contract)
        Input for the operation ``Aeff[:, :, a0:a1, :]``. See
        ``vigor.multivariate._profile_component_information`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``np.divide`` as ``where``.

    trait_chunk : int
        Rows/traits per processing or storage tile, along the axis named by the routine.
        Positive counts bound the corresponding intermediate allocation. Default: ``64``.
    """
    Aeff = np.asarray(Aeff, dtype=float)
    p, _, T, _ = Aeff.shape
    out = np.zeros((p, T, T), dtype=float)
    eye = np.eye(p, dtype=float)
    step = max(1, int(trait_chunk))
    for a0 in range(0, T, step):
        a1 = min(T, a0 + step)
        batch = Aeff[:, :, a0:a1, :].transpose(2, 3, 0, 1)
        batch = batch + eps * eye
        try:
            inv = np.linalg.inv(batch)
        except np.linalg.LinAlgError:
            inv = np.linalg.pinv(batch, rcond=1e-10)
        d = np.diagonal(inv, axis1=-2, axis2=-1)  # chunk x T x p
        info = np.divide(1.0, d, out=np.zeros_like(d), where=np.isfinite(d) & (d > eps))
        out[:, a0:a1, :] = np.moveaxis(info, -1, 0)
    return np.maximum(out, 0.0)

@report_work('Spectral PSD/FA components',total=lambda moments,**kw:len(moments['B']),unit='component')
def fit_mom_spectral(
    moments,
    *,
    ranks,
    names=None,
    ridge=None,
    entry_weight=None,
    structure="fa",
    spectral_weighting="rank1",
    spectral_fa_sweeps=4,
    eps=1e-8,
):
    """Closed-form MoM followed by fast component-wise spectral PSD/FA fitting.

    The unconstrained multi-kernel MoM system is solved *exactly* for every
    trait pair first. Each additive/dominance/GxE/residual covariance is then
    projected independently into a PSD low-rank or low-rank+specific-variance
    representation. This is the fastest 2.8 solver and has no high-dimensional
    nonlinear optimizer. For the exact heterogeneous-information joint MoM
    optimum use ``solver='spectral_refine'``.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications. Passed to ``report_work`` as
        ``total``.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Default:
        ``None``. Passed to ``_spectral_project_spec`` as ``name``.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to ``_mom_objective``
        as ``ridge``.

    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Default: ``None``. Passed to
        ``_mom_objective`` as ``entry_weight``.

    structure : str
        Input supplied to ``_spectral_project_spec`` as ``structure``. See that callable's
        documented ``structure`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Default: ``'fa'``. Source-recognized literal values: ``factor``,
        ``factor_analytic``. These select the corresponding branches below; comparison evidence
        alone does not establish an exhaustive enum. Passed to ``_spectral_project_spec`` as
        ``structure``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    spectral_fa_sweeps : int
        Number of alternating low-rank/specific-diagonal updates in each spectral FA projection;
        positive counts improve initializer consistency at extra cost. Default: ``4``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_profile_component_information``
        as ``eps``.

    Returns
    -------
    dict
        Result fields: ``specs``, ``matrices``, ``result``, ``success``, ``message``, ``objective``, ``ranks``, ``n_parameters``, ``x``, ``spectral_diagnostics``, ``solver``. Field arrays preserve the corresponding input axis order.
    """
    A = np.asarray(moments["A"], dtype=float)
    p, _, T, _ = A.shape
    if names is None:
        names = list(moments.get("kernel_names", [f"G{i}" for i in range(p - 1)])) + ["E"]
    if np.isscalar(ranks) or isinstance(ranks, str):
        ranks = [ranks] * p
    ranks = [_rank_value(r, T) for r in ranks]
    if ridge is None:
        ridge = np.zeros(p)
    elif np.isscalar(ridge):
        ridge = np.repeat(float(ridge), p)
    else:
        ridge = np.asarray(ridge, float)
    # Ridge changes the closed-form normal equations by adding ridge to A_rr.
    Aeff = A.copy()
    for r in range(p):
        if ridge[r]:
            Aeff[r, r] = Aeff[r, r] + float(ridge[r])
    meff = dict(moments)
    meff["A"] = Aeff
    C0 = _pairwise_initial_from_moments(Aeff, np.asarray(moments["B"], float))
    baseW = np.ones((T, T), float) if entry_weight is None else _sym(np.asarray(entry_weight, float))
    specs, diagnostics = {}, {}
    mats = []
    profile_info = _profile_component_information(Aeff, eps=max(eps * 1e-4, 1e-12))
    for r, name in enumerate(names):
        # Schur/profile information is a better projection weight than A_rr
        # alone: 1 / (A^{-1})_rr up to a common noise scale.
        W = baseW * profile_info[r]
        sp, dg = _spectral_project_spec(
            C0[r], ranks[r], structure=structure, weights=W,
            weight_mode=spectral_weighting, fa_sweeps=spectral_fa_sweeps,
            eps=eps, name=names[r],
        )
        specs[names[r]] = sp
        diagnostics[names[r]] = dg
        mats.append(sp.materialize())
        current_work().update()
    f = _mom_objective(moments, mats, ridge=ridge, entry_weight=entry_weight)
    npar = int(sum(sp.factor.size + sp.diag_specific.size for sp in specs.values()))
    result = OptimizeResult(
        x=np.array([], dtype=float), fun=float(f), success=True,
        message="closed-form MoM + spectral PSD/FA", nit=0,
    )
    return {
        "specs": specs,
        "matrices": {n: M for n, M in zip(names, mats)},
        "result": result,
        "success": True,
        "message": str(result.message),
        "objective": float(f),
        "ranks": dict(zip(names, ranks)),
        "n_parameters": npar,
        "x": np.array([], dtype=float),
        "spectral_diagnostics": diagnostics,
        "solver": "spectral_fa" if str(structure).lower() in {"fa", "factor", "factor_analytic"} else "spectral_psd",
    }



@report_work('Spectral FA (accepted joint iterations)',unit='iter')
def fit_mom_projected(
    moments, *, ranks, names=None, ridge=None, entry_weight=None,
    structure="fa", spectral_weighting="rank1", spectral_fa_sweeps=4,
    maxiter=80, tol=1e-7, step_scale=0.95, max_backtracks=12,
    eps=1e-8,
):
    """Joint projected-gradient solver for the exact quadratic MoM objective.

    Unlike the component-wise spectral initializer, every update uses the
    *joint* multi-component MoM gradient before projecting each covariance back
    to the requested PSD/FA set.  For full-rank ``structure='psd'`` this is a
    convex projected-gradient solve and converges to the same joint objective
    as the full-rank L-BFGS parameterization without using L-BFGS.  Low-rank
    PSD/FA fits retain the same descent/backtracking safeguard, but the rank
    constraint is non-convex and therefore remains a local estimator.

    This solver exists specifically to avoid the historical failure mode where
    independently projecting the closed-form G/E components could over-assign
    marginal variance to G and collapse E toward zero.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Passed to ``fit_mom_spectral`` as ``ranks``.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Default:
        ``None``. Passed to ``fit_mom_spectral`` as ``names``.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``fit_mom_spectral`` as ``ridge``.

    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Default: ``None``. Passed to
        ``fit_mom_spectral`` as ``entry_weight``.

    structure : str
        Input supplied to ``fit_mom_spectral`` as ``structure``. See that callable's documented
        ``structure`` contract for its type, alignment and value domain. This wrapper retains
        that contract. Default: ``'fa'``. Source-recognized literal values: ``factor``,
        ``factor_analytic``. These select the corresponding branches below; comparison evidence
        alone does not establish an exhaustive enum. Passed to ``fit_mom_spectral`` as
        ``structure``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    spectral_fa_sweeps : int
        Number of alternating low-rank/specific-diagonal updates in each spectral FA projection;
        positive counts improve initializer consistency at extra cost. Default: ``4``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``80``. Passed to ``current_work().accepted`` as ``limit``.

    tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``.

    step_scale : float
        Input for the operation ``float(step_scale) / L``. See
        ``vigor.multivariate.fit_mom_projected`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``0.95``.

    max_backtracks : int
        Input for the operation ``range(max(1, int(max_backtracks)))``. See
        ``vigor.multivariate.fit_mom_projected`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default: ``12``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``fit_mom_spectral`` as ``eps``.

    Returns
    -------
    dict
        Result fields: ``specs``, ``matrices``, ``result``, ``success``, ``message``, ``objective``, ``ranks``, ``n_parameters``, ``x``, ``spectral_diagnostics``, ``spectral_initializer_objective``, ``projected_backtracks``, ``solver``. Field arrays preserve the corresponding input axis order.
    """
    base = fit_mom_spectral(
        moments, ranks=ranks, names=names, ridge=ridge, entry_weight=entry_weight,
        structure=structure, spectral_weighting=spectral_weighting,
        spectral_fa_sweeps=spectral_fa_sweeps, eps=eps,
    )
    names2 = list(base["specs"])
    mats = [np.asarray(base["specs"][n].materialize(), float) for n in names2]
    A = np.asarray(moments["A"], dtype=float)
    B = np.asarray(moments["B"], dtype=float)
    pcomp, _, T, _ = A.shape
    if ridge is None:
        ridgev = np.zeros(pcomp, dtype=float)
    elif np.isscalar(ridge):
        ridgev = np.repeat(float(ridge), pcomp)
    else:
        ridgev = np.asarray(ridge, dtype=float)
    if np.isscalar(ranks) or isinstance(ranks, str):
        ranks2 = [_rank_value(ranks, T)] * pcomp
    else:
        ranks2 = [_rank_value(r, T) for r in ranks]
    W = np.ones((T, T), dtype=float) if entry_weight is None else _sym(np.asarray(entry_weight, dtype=float))
    # Safe global Lipschitz upper bound for the matrix-entry-wise quadratic.
    rowsum = np.sum(np.abs(A), axis=1) + ridgev[:, None, None]
    L = 2.0 * max(float(np.max(np.abs(W) * np.max(rowsum, axis=0))), float(eps))
    step = float(step_scale) / L
    f = _mom_objective(moments, mats, ridge=ridgev, entry_weight=entry_weight)
    initial_f = float(f)
    converged = False
    nit = 0
    n_backtracks = 0
    diagnostics = dict(base.get("spectral_diagnostics", {}))
    accepted_specs = None

    def project(M, r):
        """Project the supplied genotype block into the prepared eigen/phenotype/covariate bases.

        Parameters
        ----------
        M : array-like
            Numerical operand in ``_spectral_project_spec(M, ranks2[r], structure=structure,
            weights=None, weight_mode='none', fa_sweeps=max(2, int(spectral_fa_sweeps)), eps=eps,
            name=names2[r])``. Shape must conform to that matrix/vector operation and the enclosing
            prepared state.

        r : int or index array
            Local position, index selection or step used by the stated slice/iteration. Indices must
            refer to the relevant axis; slice steps must be nonzero, and count/rank uses must match
            the enclosing dimensions. Passed to ``_spectral_project_spec`` as ``name``.

        Returns
        -------
        object
            Computed result from ``(sp, dg)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        sp, dg = _spectral_project_spec(
            M, ranks2[r], structure=structure, weights=None, weight_mode="none",
            fa_sweeps=max(2, int(spectral_fa_sweeps)), eps=eps, name=names2[r],
        )
        return sp, dg

    for it in range(max(1, int(maxiter))):
        grads=[]
        for r in range(pcomp):
            g = -B[r] + ridgev[r] * mats[r]
            for q in range(pcomp):
                g = g + A[r, q] * mats[q]
            grads.append(2.0 * W * _sym(g))
        old = mats
        local_step = step
        accepted = False
        trial_specs = None
        trial_mats = None
        trial_f = np.inf
        for _ in range(max(1, int(max_backtracks))):
            ts=[]; tm=[]; td={}
            for r in range(pcomp):
                sp, dg = project(old[r] - local_step * grads[r], r)
                ts.append(sp); tm.append(sp.materialize()); td[names2[r]]=dg
            trial_f = _mom_objective(moments, tm, ridge=ridgev, entry_weight=entry_weight)
            if np.isfinite(trial_f) and trial_f <= f + 1e-10 * max(1.0, abs(f)):
                accepted=True; trial_specs=ts; trial_mats=tm; diagnostics=td
                break
            local_step *= 0.5
            n_backtracks += 1
        if not accepted:
            break
        accepted_specs = trial_specs
        delta = np.sqrt(sum(float(np.sum((a-b)**2)) for a,b in zip(trial_mats, old)))
        scale = max(np.sqrt(sum(float(np.sum(a*a)) for a in old)), 1e-30)
        mats = trial_mats
        f_old = f
        f = float(trial_f)
        step = min(local_step * 1.05, float(step_scale) / L)
        nit = it + 1
        current_work().accepted(f,np.concatenate([g.ravel() for g in grads]) if current_work().enabled else None,limit=int(maxiter))
        rel = delta / scale
        obj_rel = abs(f_old-f) / max(1.0, abs(f_old))
        if rel <= float(tol) or obj_rel <= float(tol) * 0.1:
            converged = True
            break
    # Build exact final specs from the accepted matrices.  Re-projecting is
    # unnecessary and can alter the accepted objective, so retain the last specs
    # when available; if no step was accepted, use the spectral start.
    if nit == 0:
        specs = base["specs"]
        mats = [np.asarray(specs[n].materialize(), float) for n in names2]
        f = initial_f
    else:
        specs = {n: sp for n,sp in zip(names2, accepted_specs)}
    result = OptimizeResult(
        x=np.array([], dtype=float), fun=float(f), success=bool(converged and np.isfinite(f)),
        message=("projected joint MoM converged" if converged else
                 "projected joint MoM reached its iteration/backtracking limit"),
        nit=int(nit),
    )
    current_work().finish(result.message)
    npar = int(sum(sp.factor.size + sp.diag_specific.size for sp in specs.values()))
    return {
        "specs": specs,
        "matrices": {n: M for n,M in zip(names2, mats)},
        "result": result,
        "success": bool(result.success),
        "message": str(result.message),
        "objective": float(f),
        "ranks": dict(zip(names2, ranks2)),
        "n_parameters": npar,
        "x": np.array([], dtype=float),
        "spectral_diagnostics": diagnostics,
        "spectral_initializer_objective": initial_f,
        "projected_backtracks": int(n_backtracks),
        "solver": "projected_fa" if str(structure).lower() in {"fa","factor","factor_analytic"} else "projected_psd",
    }


def fit_mom_spectral_refine(
    moments, *, ranks, names=None, ridge=None, entry_weight=None,
    structure="fa", spectral_weighting="rank1", spectral_fa_sweeps=4,
    refine_maxiter=5, gtol=1e-7, ftol=1e-10, eps=1e-8,
):
    """Spectral closed-form initializer plus a few exact weighted L-BFGS steps.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Passed to ``fit_mom_spectral`` as ``ranks``.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Default:
        ``None``. Passed to ``fit_mom_spectral`` as ``names``.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``fit_mom_spectral`` as ``ridge``.

    entry_weight : array-like or None
        Trait × trait weights on covariance moment entries. The dimensions must match the
        trait-pair tensors; None applies uniform entry weights. Default: ``None``. Passed to
        ``fit_mom_spectral`` as ``entry_weight``.

    structure : str
        Input supplied to ``fit_mom_spectral`` as ``structure``. See that callable's documented
        ``structure`` contract for its type, alignment and value domain. This wrapper retains
        that contract. Default: ``'fa'``. Passed to ``fit_mom_spectral`` as ``structure``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    spectral_fa_sweeps : int
        Number of alternating low-rank/specific-diagonal updates in each spectral FA projection;
        positive counts improve initializer consistency at extra cost. Default: ``4``.

    refine_maxiter : int
        Input supplied to ``fit_mom_factor_analytic`` as ``maxiter``. See that callable's
        documented ``maxiter`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Default: ``5``. Passed to ``fit_mom_factor_analytic`` as
        ``maxiter``.

    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``. Passed to ``fit_mom_factor_analytic`` as ``gtol``.

    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-10``. Passed to ``fit_mom_factor_analytic`` as ``ftol``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``fit_mom_spectral`` as ``eps``.

    Returns
    -------
    object
        Computed result from ``refined``; see the summary and the called implementation for its labeled/numerical representation.
    """
    base = fit_mom_spectral(
        moments, ranks=ranks, names=names, ridge=ridge, entry_weight=entry_weight,
        structure=structure, spectral_weighting=spectral_weighting,
        spectral_fa_sweeps=spectral_fa_sweeps, eps=eps,
    )
    names2 = list(base["specs"])
    refined = fit_mom_factor_analytic(
        moments, ranks=ranks, names=names2, ridge=ridge, entry_weight=entry_weight,
        warm_start=base["specs"], maxiter=max(1, int(refine_maxiter)),
        gtol=gtol, ftol=ftol, eps=eps,
    )
    # A deliberately tiny refinement budget often terminates by iteration cap.
    # Treat a finite objective improvement as a successful polished spectral
    # solution; otherwise fall back to the guaranteed finite spectral start.
    if (not np.isfinite(refined.get("objective", np.nan))) or refined.get("objective", np.inf) > base["objective"]:
        base["spectral_initializer_objective"] = float(base["objective"])
        base["solver"] = "spectral_refine_fallback"
        return base
    refined["spectral_initializer_objective"] = float(base["objective"])
    refined["spectral_diagnostics"] = base.get("spectral_diagnostics", {})
    refined["solver"] = "spectral_refine"
    refined["optimizer_converged"] = bool(refined.get("success",False))
    if not refined["success"] and np.isfinite(refined["objective"]):
        jac=np.asarray(getattr(refined.get("result"),"jac",np.array([np.inf])),float)
        stationarity=float(np.nanmax(np.abs(jac))) if jac.size else np.inf
        refined["stationarity_max_abs_gradient"]=stationarity
        # spectral_refine is explicitly a bounded polishing solver. A finite
        # objective no worse than the spectral initializer is a valid successful
        # result even when the tiny polish budget reaches its iteration cap.
        refined["success"] = True
        refined["message"] = ("spectral refinement reached covariance-factor stationarity"
                              if stationarity <= max(float(gtol)*10.0,1e-5)
                              else "spectral refinement reached its bounded polish budget with a finite improved objective")
        try:
            refined["result"].success = True
            refined["result"].message = refined["message"]
        except Exception:
            pass
    return refined


def _rank_validation_mask(n_traits, validation_fraction, random_state):
    """Hold out off-diagonal pairs without accidentally creating an empty fold.

    Parameters
    ----------
    n_traits : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    validation_fraction : float
        Fraction of eligible entries/animals selected for the corresponding holdout or
        resampling operation; use a value in (0, 1] compatible with nonempty training/evaluation
        subsets. Source comparisons: ``0 < fraction < 1``. See the rejection/fallback branches
        for enforcement.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed.
    """
    fraction = float(validation_fraction)
    if not 0 < fraction < 1:
        raise ValueError("rank_validation_fraction must be strictly between zero and one")
    pairs = np.triu_indices(int(n_traits), 1)
    mask = np.zeros((n_traits, n_traits), dtype=bool)
    if len(pairs[0]):
        count = max(1, int(round(len(pairs[0]) * fraction)))
        chosen = np.random.default_rng(random_state).choice(len(pairs[0]), count, replace=False)
        mask[pairs[0][chosen], pairs[1][chosen]] = True
        mask |= mask.T
    return mask


def select_mom_spectral_rank(
    moments, *, candidates=(10, 20, 40, 100, "full"), rank_E="same",
    random_state=0, validation_fraction=0.10, structure="fa",
    spectral_weighting="rank1", spectral_fa_sweeps=4, refine=False,
    refine_maxiter=5, gtol=1e-6, ftol=1e-9, eps=1e-8,
):
    """Fast rank selection using the same held-out moment criterion as 2.6.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    candidates : tuple
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``(10, 20, 40, 100, 'full')``.

    rank_E : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``'same'``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``.

    validation_fraction : float
        Fraction of eligible entries/animals selected for the corresponding holdout or
        resampling operation; use a value in (0, 1] compatible with nonempty training/evaluation
        subsets. Default: ``0.1``.

    structure : str
        Input supplied to ``fit_mom_spectral_refine`` as ``structure``. See that callable's
        documented ``structure`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Default: ``'fa'``. Passed to ``fit_mom_spectral_refine`` as
        ``structure``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    spectral_fa_sweeps : int
        Number of alternating low-rank/specific-diagonal updates in each spectral FA projection;
        positive counts improve initializer consistency at extra cost. Default: ``4``.

    refine : bool
        Whether to alternate sparse covariance fitting with PC/optional ANM graph discovery and
        a shared-path acyclic moment-fitted SEM. This is a conditional structural refinement,
        not proof of causal identification. Default: ``False``.

    refine_maxiter : int
        Input supplied to ``fit_mom_spectral_refine`` as ``refine_maxiter``. See that callable's
        documented ``refine_maxiter`` contract for its type, alignment and value domain. This
        wrapper retains that contract. Default: ``5``. Passed to ``fit_mom_spectral_refine`` as
        ``refine_maxiter``.

    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-06``. Passed to ``fit_mom_spectral_refine`` as ``gtol``.

    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-09``. Passed to ``fit_mom_spectral_refine`` as ``ftol``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``fit_mom_spectral_refine`` as
        ``eps``.

    Returns
    -------
    dict
        Result fields: ``selected``, ``table``, ``fit``. Field arrays preserve the corresponding input axis order.
    """
    A = np.asarray(moments["A"])
    p, _, T, _ = A.shape
    val = _rank_validation_mask(T, validation_fraction, random_state)
    val |= val.T
    train = ~val
    np.fill_diagonal(train, True)
    rows, fits, seen = [], {}, set()
    for cand in candidates:
        r = T if str(cand).lower() == "full" else min(T, int(cand))
        er = r if rank_E == "same" else _rank_value(rank_E, T)
        key = (r, er)
        if key in seen:
            continue
        seen.add(key)
        ranks = [r] * (p - 1) + [er]
        tic = time.perf_counter()
        if refine:
            fit = fit_mom_spectral_refine(
                moments, ranks=ranks, entry_weight=train.astype(float), structure=structure,
                spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps,
                refine_maxiter=refine_maxiter, gtol=gtol, ftol=ftol, eps=eps,
            )
        else:
            fit = fit_mom_spectral(
                moments, ranks=ranks, entry_weight=train.astype(float), structure=structure,
                spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps, eps=eps,
            )
        sec = time.perf_counter() - tic
        mats = [fit["matrices"][n] for n in list(moments.get("kernel_names", [])) + ["E"]]
        err = _moment_prediction_error(moments, mats, val)
        rows.append({
            "candidate": "full" if r == T else r, "rank_G": r, "rank_E": er,
            "seconds": sec, "success": fit["success"], "n_parameters": fit["n_parameters"], **err,
        })
        fits[key] = fit
    table = pd.DataFrame(rows)
    ok = table[table.success & np.isfinite(table.moment_nrmse)]
    if len(ok):
        best_row = ok.sort_values(["moment_nrmse", "n_parameters", "seconds"]).iloc[0]
    else:
        best_row = table.sort_values(["n_parameters", "seconds"]).iloc[0]
    key = (int(best_row.rank_G), int(best_row.rank_E))
    return {"selected": key, "table": table, "fit": fits[key]}

def _moment_prediction_error(moments, matrices, mask):
    """Measure held-out trait-pair moment reconstruction error for rank/policy selection.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    matrices : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    mask : bool or numeric mask array
        Observation/eligibility mask aligned to the corresponding input axis. True/one selects
        observed or eligible entries; false/zero excludes them. A sample mask is
        one-dimensional; cell masks match the matrix and packed masks follow the packed-byte
        axis.
    """
    A, B = np.asarray(moments["A"], float), np.asarray(moments["B"], float)
    C = list(matrices)
    p = len(C)
    mask = np.asarray(mask, bool)
    residuals = []
    scales = []
    for r in range(p):
        bhat = np.zeros_like(B[r])
        for s in range(p):
            bhat += A[r, s] * C[s]
        residuals.append((B[r] - bhat)[mask])
        scales.append(B[r][mask])
    rr = np.concatenate(residuals) if residuals else np.array([])
    bb = np.concatenate(scales) if scales else np.array([])
    rmse = float(np.sqrt(np.mean(rr * rr))) if rr.size else np.nan
    denom = float(np.sqrt(np.mean(bb * bb))) if bb.size else np.nan
    return {"moment_rmse": rmse, "moment_nrmse": rmse / max(denom, 1e-30) if np.isfinite(denom) else np.nan}


def select_mom_fa_rank(
    moments,
    *,
    candidates=(10, 20, 40, 100, "full"),
    rank_E="same",
    random_state=0,
    validation_fraction=0.10,
    maxiter=250,
    gtol=1e-6,
    ftol=1e-9,
    eps=1e-8,
    warm_start=None,
):
    """Select covariance rank by held-out MoM prediction, not explained variance.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    candidates : tuple
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``(10, 20, 40, 100, 'full')``.

    rank_E : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``'same'``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``.

    validation_fraction : float
        Fraction of eligible entries/animals selected for the corresponding holdout or
        resampling operation; use a value in (0, 1] compatible with nonempty training/evaluation
        subsets. Default: ``0.1``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``250``. Passed to ``fit_mom_factor_analytic`` as ``maxiter``.

    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-06``. Passed to ``fit_mom_factor_analytic`` as ``gtol``.

    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-09``. Passed to ``fit_mom_factor_analytic`` as ``ftol``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``fit_mom_factor_analytic`` as
        ``eps``.

    warm_start : mapping, array-like or None
        Initial covariance factors/matrices or optimization state from a compatible fit. None
        uses the solver's initialization; incompatible trait/component dimensions must not be
        reused. Default: ``None``. Passed to ``fit_mom_factor_analytic`` as ``warm_start``.

    Returns
    -------
    dict
        Result fields: ``selected``, ``table``, ``validation_mask``, ``fit``. Field arrays preserve the corresponding input axis order.
    """
    A = np.asarray(moments["A"])
    p, _, T, _ = A.shape
    val = _rank_validation_mask(T, validation_fraction, random_state)
    val = val | val.T
    train = ~val
    np.fill_diagonal(train, True)
    rows = []
    fits = {}
    seen = set()
    for cand in candidates:
        r = T if cand == "full" else min(T, int(cand))
        er = r if rank_E == "same" else _rank_value(rank_E, T)
        key = (r, er)
        if key in seen:
            continue
        seen.add(key)
        ranks = [r] * (p - 1) + [er]
        tic = time.perf_counter()
        fit = fit_mom_factor_analytic(
            moments, ranks=ranks, entry_weight=train.astype(float), warm_start=warm_start,
            maxiter=maxiter, gtol=gtol, ftol=ftol, eps=eps,
        )
        sec = time.perf_counter() - tic
        mats = [fit["matrices"][n] for n in list(moments.get("kernel_names", [])) + ["E"]]
        err = _moment_prediction_error(moments, mats, val)
        rows.append({
            "candidate": "full" if r == T else r,
            "rank_G": r, "rank_E": er,
            "seconds": sec, "success": fit["success"],
            "n_parameters": fit["n_parameters"], **err,
        })
        fits[key] = fit
    table = pd.DataFrame(rows)
    ok = table[table.success & np.isfinite(table.moment_nrmse)]
    if len(ok):
        best_row = ok.sort_values(["moment_nrmse", "n_parameters", "seconds"]).iloc[0]
    else:
        best_row = table.sort_values(["moment_nrmse", "n_parameters"], na_position="last").iloc[0]
    selected = (int(best_row.rank_G), int(best_row.rank_E))
    return {"selected": selected, "table": table, "validation_mask": val, "fit": fits[selected]}


def _apply_offdiag_shrink(spec: FactorCovarianceSpec, alpha: float):
    """Apply offdiag shrink.

    Parameters
    ----------
    spec : FactorCovarianceSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Passed to ``FactorCovarianceSpec`` as
        ``name``.

    alpha : float
        Regularization coefficient, mixing weight or statistical significance threshold selected
        by this estimator; the local validation and objective determine its precise scale.
    """
    alpha = float(alpha)
    alpha = min(max(alpha, 0.0), 1.0)
    if alpha >= 1.0 - 1e-15:
        return spec
    common_diag = np.einsum("ij,ij->i", spec.factor, spec.factor)
    return FactorCovarianceSpec(
        np.sqrt(alpha) * spec.factor,
        spec.diag_specific + (1.0 - alpha) * common_diag,
        name=spec.name, support_mask=spec.support_mask,
        structure=spec.structure, rotation=spec.rotation,
    )


def _auto_shrink(nobs, strength):
    """Compute overlap/sample-size covariance retention n/(n+strength).

    Parameters
    ----------
    nobs : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    strength : float or array-like
        Numerical scale/retention/step threshold controlling the transformation described above.
        Match vector scales to the affected axis; the exact formula and local comparisons below
        determine its admissible domain.
    """
    m = float(np.median(np.asarray(nobs, float)))
    return m / (m + float(strength))


def _linear_analytic_retention(spec, overlap, *, eps=1e-10):
    """Closed-form overlap-aware linear shrinkage of residual correlations.

    Schafer & Strimmer (2005) optimal intensity toward the diagonal,
    lambda = sum_ij Var(r_ij) / sum_ij r_ij^2 over supported off-diagonal pairs,
    with Var(r_ij) ~ (1 - r_ij^2)^2 / (n_ij - 1) from the pair's overlap n_ij.
    Returns the off-diagonal retention 1 - lambda in [0, 1]. Shrinking toward the
    diagonal keeps the matrix PSD and lifts its smallest eigenvalue to at least
    lambda (correlation scale), which is what conditions the mvBLUP system. O(t^2).
    """
    C = _sym(spec.materialize())
    sd = np.sqrt(np.maximum(np.diag(C), eps))
    R = C / np.outer(sd, sd)
    iu = np.triu_indices_from(R, 1)
    n = np.asarray(overlap, dtype=float)[iu]
    r = np.clip(R[iu], -1.0, 1.0)
    supported = n >= 4
    if not supported.any():
        return 1.0
    signal = float(np.sum(r[supported] ** 2))
    if signal <= 0:
        return 0.0
    noise = float(np.sum((1.0 - r[supported] ** 2) ** 2 / (n[supported] - 1.0)))
    return float(1.0 - min(1.0, max(0.0, noise / signal)))


def _model_eb_pair_weights(raw_specs, names, moments, overlap, *, multiplier=1.0, min_overlap=4, eps=1e-10):
    """Per-pair residual-correlation retention from the fitted model's own precision.

    For trait pair (i, j) the MoM estimate solves H theta = b with H = A[:, :, i, j]
    (component x component trace products on the pair's observed cells). Under a
    Gaussian null-style approximation Cov(b) ~ (Vp_i Vp_j + P_ij^2) H, so
    Var(E_ij) ~ (Vp_i Vp_j + P_ij^2) [H^-1]_EE, with P = sum of fitted components.
    Unlike overlap/(overlap+s) or Fisher-z 1/(n-3), this sees the G/E confounding of
    the pair (a near-collinear H inflates [H^-1]_EE) and the kernel structure.

    With r_ij = E_ij / sqrt(E_ii E_jj) and sampling variance s2_ij on that scale, a
    zero-mean prior r_ij ~ N(0, tau2) gives the posterior-mean retention
    alpha_ij = tau2 / (tau2 + c s2_ij). tau2 is the DerSimonian-Laird moment estimate
    with known zero mean, tau2 = max(0, (sum w r^2 - k) / sum w), w = 1/s2, which
    down-weights poorly identified pairs instead of letting them dominate.
    ``multiplier`` c rescales the approximate sampling variances (c > 1 shrinks
    more); CV can tune it. Unsupported or unidentified pairs get alpha = 0.
    Cost: one batched p x p eigendecomposition per pair, O(T^2 p^3).

    Returns ``(alpha, tau2, info)`` with alpha a T x T matrix (unit diagonal).
    """
    A = np.asarray(moments["A"], dtype=float)
    p, T = A.shape[0], A.shape[-1]
    if p != len(names) or A.shape != (p, p, T, T):
        raise ValueError("model_eb: moment tensor does not match the fitted components")
    P = sum((_sym(raw_specs[n].materialize()) for n in names), np.zeros((T, T)))
    E = _sym(raw_specs["E"].materialize())
    vp = np.maximum(np.diag(P), eps)
    de = np.maximum(np.diag(E), eps)
    iu, ju = np.triu_indices(T, 1)
    alpha = np.eye(T)
    if not len(iu):
        return alpha, 0.0, {"E_model_eb_pairs": 0}
    E_index = list(names).index("E")
    H = np.moveaxis(A[:, :, iu, ju], -1, 0)
    H = 0.5 * (H + np.swapaxes(H, 1, 2))
    w, U = np.linalg.eigh(H)
    ok = (np.asarray(overlap, dtype=float)[iu, ju] >= min_overlap) & (w[:, 0] > 1e-10 * np.maximum(w[:, -1], eps))
    inv_ee = np.full(len(iu), np.inf)
    if ok.any():
        inv_ee[ok] = np.sum(U[ok, E_index, :] ** 2 / w[ok], axis=1)
    s2 = (vp[iu] * vp[ju] + P[iu, ju] ** 2) * inv_ee / (de[iu] * de[ju])
    ok &= np.isfinite(s2) & (s2 > 0)
    r = E[iu, ju] / np.sqrt(de[iu] * de[ju])
    tau2 = 0.0
    if ok.any():
        wt = 1.0 / s2[ok]
        tau2 = max(float((np.sum(wt * r[ok] ** 2) - ok.sum()) / np.sum(wt)), 0.0)
    a = np.zeros(len(iu))
    if tau2 > 0:
        a[ok] = tau2 / (tau2 + float(multiplier) * s2[ok])
    alpha[iu, ju] = a
    alpha[ju, iu] = a
    info = {"E_model_eb_pairs": int(ok.sum()),
            "E_model_eb_median_sampling_sd": float(np.sqrt(np.median(s2[ok]))) if ok.any() else None}
    return alpha, tau2, info


def _scalar_shrink_spec(spec: FactorCovarianceSpec, alpha: float):
    """PSD-preserving scalar off-diagonal shrinkage with unchanged variances.

    Parameters
    ----------
    spec : FactorCovarianceSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity.

    alpha : float
        Regularization coefficient, mixing weight or statistical significance threshold selected
        by this estimator; the local validation and objective determine its precise scale.
    """
    return _apply_offdiag_shrink(spec, float(alpha))


def _fa_project_preserve_rank(target, template: FactorCovarianceSpec, *, eps=1e-10, fa_sweeps=8):
    """Project a PSD shrinkage target back to the template FA model.

    Pair-specific shrinkage is naturally a full-matrix operation.  Applying it
    directly after an ``L L' + Psi`` fit can therefore increase effective rank
    from ``rank(L)`` to the number of traits.  This helper makes the shrinkage
    *rank preserving*: the shrunken matrix is treated as a target and projected
    back onto the same factor-analytic family, followed by a diagonal rescaling
    that restores the original trait variances exactly.  PSD is structural and
    the returned common-factor rank can never exceed ``template.rank``.

    Parameters
    ----------
    target : str, index or sequence
        Response/trait identifiers selected for this prediction, mediation or subset operation.
        Names/positions must exist in the supplied response axes; sequences preserve the
        requested ordering.

    template : FactorCovarianceSpec
        Reference input or fitted state supplying alignment, initialization or baseline
        quantities. Match the axes/component order of the operation; see the corresponding
        fit/preparation routine for required fields. Passed to ``as_covariance_spec`` as
        ``name``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_spectral_project_spec`` as
        ``eps``.

    fa_sweeps : int
        Number of alternating/projection/relevance/eigenspace refinement iterations performed by
        the selected algorithm. Positive counts trade additional work for a more settled
        approximation. Default: ``8``. Passed to ``_spectral_project_spec`` as ``fa_sweeps``.
    """
    C = _sym(np.asarray(target, dtype=float))
    T = template.n_traits
    if C.shape != (T, T):
        raise ValueError("shrinkage target shape does not match factor covariance")
    wanted = np.maximum(np.diag(C), eps)
    if template.rank >= T:
        return as_covariance_spec(C, name=template.name)
    projected, _ = _spectral_project_spec(
        C, template.rank, structure="fa", weights=None, weight_mode="none",
        fa_sweeps=max(2, int(fa_sweeps)), eps=max(float(eps), 1e-12), name=template.name,
    )
    got = np.maximum(projected.diagonal(), eps)
    scale = np.sqrt(wanted / got)
    F = scale[:, None] * projected.factor
    psi = (scale * scale) * projected.diag_specific
    out = FactorCovarianceSpec(F, np.maximum(psi, 0.0), name=template.name)
    # Floating-point cleanup: preserve requested marginal variances exactly.
    common = np.einsum("ij,ij->i", out.factor, out.factor)
    psi = np.maximum(wanted - common, 0.0)
    # If a common-factor diagonal very slightly exceeds the target, one final
    # row scaling brings it back while retaining rank and PSD.
    excess = common > wanted
    if np.any(excess):
        row_scale = np.ones(T, dtype=float)
        row_scale[excess] = np.sqrt(wanted[excess] / np.maximum(common[excess], eps))
        F = row_scale[:, None] * out.factor
        common = np.einsum("ij,ij->i", F, F)
        psi = np.maximum(wanted - common, 0.0)
        out = FactorCovarianceSpec(F, psi, name=template.name)
    else:
        out = FactorCovarianceSpec(out.factor, psi, name=template.name)
    return out


def _pairwise_overlap_shrink_spec(spec: FactorCovarianceSpec, overlap, strength: float, *, eps=1e-10, rank_preserve=True):
    """Shrink residual correlations according to pair-specific phenotype overlap.

    ``alpha_ij = n_ij / (n_ij + strength)`` is applied on the correlation
    scale.  The full pairwise target is PSD-repaired and renormalized.  For a
    low-rank FA input the default then projects that target back to the same
    ``L L' + Psi`` rank, so adaptive shrinkage cannot silently turn a rank-50
    residual model into a full-rank matrix.  ``strength=0`` is identity.

    Parameters
    ----------
    spec : FactorCovarianceSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Passed to ``as_covariance_spec`` as
        ``name``.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    strength : float
        Numerical scale/retention/step threshold controlling the transformation described above.
        Match vector scales to the affected axis; the exact formula and local comparisons below
        determine its admissible domain. Source comparisons: ``strength <= 0``. See the
        rejection/fallback branches for enforcement. Passed to ``np.divide`` as ``where``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_legacy._project_psd`` as ``eps``.

    rank_preserve : bool
        Input for the operation ``bool(rank_preserve)``. See
        ``vigor.multivariate._pairwise_overlap_shrink_spec`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``True``.
    """
    strength = float(strength)
    if strength <= 0:
        return spec
    ov = np.maximum(np.asarray(overlap, dtype=float), 0.0)
    if ov.shape != (spec.n_traits, spec.n_traits):
        raise ValueError("overlap matrix shape does not match covariance")
    alpha = np.divide(ov, ov + strength, out=np.zeros_like(ov), where=(ov + strength) > 0)
    return _pairwise_alpha_shrink_spec(spec, alpha, eps=eps, rank_preserve=rank_preserve)


def _pairwise_alpha_shrink_spec(spec: FactorCovarianceSpec, alpha, *, eps=1e-10, rank_preserve=False):
    """Retain each residual correlation by its own factor ``alpha_ij`` in [0, 1].

    ``R_sh = I + alpha o (R - I)``, then PSD repair, renormalization to unit
    diagonal and the original variances. Shared by the overlap and the
    model-based EB policies; ``rank_preserve`` projects back to the FA rank.
    """
    C = _sym(spec.materialize())
    d = np.maximum(np.diag(C), eps)
    sd = np.sqrt(d)
    R = C / np.outer(sd, sd)
    R = _sym(R)
    np.fill_diagonal(R, 1.0)
    alpha = np.clip(_sym(np.asarray(alpha, dtype=float)), 0.0, 1.0)
    if alpha.shape != C.shape:
        raise ValueError("pairwise retention matrix shape does not match covariance")
    np.fill_diagonal(alpha, 1.0)
    Rsh = np.eye(C.shape[0], dtype=float) + alpha * (R - np.eye(C.shape[0], dtype=float))
    Rsh = _legacy._project_psd(_sym(Rsh), eps=max(float(eps), 1e-12))
    rdiag = np.sqrt(np.maximum(np.diag(Rsh), eps))
    Rsh = Rsh / np.outer(rdiag, rdiag)
    Rsh = np.clip(_sym(Rsh), -1.0, 1.0)
    np.fill_diagonal(Rsh, 1.0)
    Csh = _sym(Rsh * np.outer(sd, sd))
    np.fill_diagonal(Csh, d)
    if bool(rank_preserve) and spec.rank < spec.n_traits:
        return _fa_project_preserve_rank(Csh, spec, eps=eps)
    return as_covariance_spec(Csh, name=spec.name)


def _fisher_eb_overlap_spec(spec: FactorCovarianceSpec, overlap, tau2=None, *, eps=1e-10, rank_preserve=True):
    """Empirical-Bayes shrinkage of residual correlations with pairwise overlap.

    On the Fisher-z scale, ``z_ij`` is approximated as Normal(theta_ij,
    1/(n_ij-3)).  A zero-centered Normal prior theta_ij~N(0,tau2) gives the
    posterior-mean shrinkage factor ``tau2/(tau2 + 1/(n_ij-3))``.  ``tau2`` is
    estimated once from the full-data residual correlation matrix when omitted
    and can then be held fixed across bootstrap replicates.

    Parameters
    ----------
    spec : FactorCovarianceSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Passed to ``as_covariance_spec`` as
        ``name``.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    tau2 : float or None
        Nonnegative prior variance of Fisher-z correlation effects for empirical-Bayes
        retention. None estimates it from the supplied covariance and overlap information.
        Default: ``None``. Source comparisons: ``tau2 > 0``. See the rejection/fallback branches
        for enforcement.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_legacy._project_psd`` as ``eps``.

    rank_preserve : bool
        Input for the operation ``bool(rank_preserve)``. See
        ``vigor.multivariate._fisher_eb_overlap_spec`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``True``.
    """
    C = _sym(spec.materialize())
    d = np.maximum(np.diag(C), eps)
    sd = np.sqrt(d)
    R = np.clip(_sym(C / np.outer(sd, sd)), -1.0 + 1e-9, 1.0 - 1e-9)
    np.fill_diagonal(R, 1.0)
    ov = np.maximum(np.asarray(overlap, dtype=float), 0.0)
    if ov.shape != C.shape:
        raise ValueError("overlap matrix shape does not match covariance")
    iu = np.triu_indices_from(R, 1)
    nij = ov[iu]
    z = np.arctanh(R[iu])
    valid = np.isfinite(z) & (nij >= 4)
    s2 = np.full_like(nij, np.inf, dtype=float)
    s2[valid] = 1.0 / np.maximum(nij[valid] - 3.0, 1.0)
    if tau2 is None:
        if np.any(valid):
            raw = z[valid] ** 2 - s2[valid]
            # Positive-part MoM estimate of the across-pair Fisher-z variance.
            # Equal pair weights avoid letting a handful of densely observed
            # traits dominate the global prior scale.
            tau2 = max(float(np.mean(raw)), 0.0)
        else:
            tau2 = 0.0
    tau2 = max(float(tau2), 0.0)
    alpha = np.zeros_like(ov, dtype=float)
    valid_matrix = ov >= 4
    samp_var = np.full_like(ov, np.inf, dtype=float)
    samp_var[valid_matrix] = 1.0 / np.maximum(ov[valid_matrix] - 3.0, 1.0)
    if tau2 > 0:
        alpha[valid_matrix] = tau2 / (tau2 + samp_var[valid_matrix])
    np.fill_diagonal(alpha, 1.0)
    Z = np.arctanh(np.clip(R, -1.0 + 1e-9, 1.0 - 1e-9))
    Rsh = np.tanh(alpha * Z)
    np.fill_diagonal(Rsh, 1.0)
    Rsh = _legacy._project_psd(_sym(Rsh), eps=max(float(eps), 1e-12))
    rdiag = np.sqrt(np.maximum(np.diag(Rsh), eps))
    Rsh = np.clip(_sym(Rsh / np.outer(rdiag, rdiag)), -1.0, 1.0)
    np.fill_diagonal(Rsh, 1.0)
    Csh = _sym(Rsh * np.outer(sd, sd))
    np.fill_diagonal(Csh, d)
    if bool(rank_preserve) and spec.rank < spec.n_traits:
        out = _fa_project_preserve_rank(Csh, spec, eps=eps)
    else:
        out = as_covariance_spec(Csh, name=spec.name)
    return out, tau2, alpha




def _analytic_shrink_mode(value):
    """Resolve analytical-SE-driven prediction shrinkage request.

    Returns ``None`` for ordinary legacy policies, ``'global'`` for one
    PSD-preserving scalar risk shrinker, and ``'pairwise'`` for pair-specific
    Fisher-z empirical-Bayes shrinkage followed by PSD/FA reconciliation.

    Parameters
    ----------
    value : object (see the cited input contract)
        Input for the operation ``value.lower().replace('-', '_')``. See
        ``vigor.multivariate._analytic_shrink_mode`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.
        Source-recognized literal values: ``analytic``, ``analytic_eb``, ``analytic_fisher_eb``,
        ``analytic_global``, ``analytic_pairwise``, ``analytic_risk``, ``fisher_se_eb``,
        ``risk``, ``se_eb``, ``se_global``, ``se_pairwise``. These select the corresponding
        branches below; comparison evidence alone does not establish an exhaustive enum.
    """
    if not isinstance(value, str):
        return None
    key = value.lower().replace('-', '_')
    if key in {'analytic_global', 'se_global', 'analytic_risk', 'risk'}:
        return 'global'
    if key in {'analytic', 'analytic_eb', 'analytic_pairwise', 'analytic_fisher_eb',
               'se_eb', 'se_pairwise', 'fisher_se_eb'}:
        return 'pairwise'
    return None


def _analytic_corr_se_from_covariance(C, C_se, *, exact_corr_se=None, eps=1e-12):
    """Approximate correlation SE from covariance-entry analytical SEs.

    If an exact/delta-method correlation SE is already available (e.g. total
    genetic ``rg_se``), it is used directly. Otherwise the covariance-entry
    marginal variances are propagated while conservatively ignoring unavailable
    cross-entry covariance terms.  This is used only to choose a *prediction*
    regularizer; scientific inference continues to use the unshrunk covariance
    and its original analytical sandwich SE.

    Parameters
    ----------
    C : array-like
        Numerical operand in ``C / np.outer(sd, sd)``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    C_se : array-like or numeric scalar
        Input for the operation ``np.asarray(C_se, dtype=float)``. See
        ``vigor.multivariate._analytic_corr_se_from_covariance`` and its caller for the
        scientific representation; the shown operation constrains the required type/shape.

    exact_corr_se : array-like or numeric scalar
        Input for the operation ``np.asarray(exact_corr_se, dtype=float).copy()``. See
        ``vigor.multivariate._analytic_corr_se_from_covariance`` and its caller for the
        scientific representation; the shown operation constrains the required type/shape.
        Default: ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``np.divide`` as ``where``.
    """
    C = _sym(np.asarray(C, dtype=float))
    S = np.asarray(C_se, dtype=float)
    T = C.shape[0]
    if S.shape != (T, T):
        raise ValueError('analytical covariance SE shape does not match covariance')
    d = np.maximum(np.diag(C), float(eps))
    sd = np.sqrt(d)
    R = np.clip(_sym(C / np.outer(sd, sd)), -1.0 + 1e-10, 1.0 - 1e-10)
    np.fill_diagonal(R, 1.0)
    if exact_corr_se is not None:
        Sr = np.asarray(exact_corr_se, dtype=float).copy()
        if Sr.shape != (T, T):
            raise ValueError('exact correlation SE shape does not match covariance')
    else:
        var_c = np.square(S)
        denom2 = np.outer(d, d)
        var_r = np.divide(var_c, denom2, out=np.full_like(var_c, np.inf), where=denom2 > eps)
        vd = np.square(np.diag(S))
        rel_i = np.divide(vd, d*d, out=np.full_like(vd, np.inf), where=d > eps)
        # Delta method without off-diagonal covariance terms between C_ij and
        # the marginal variances.  The added diagonal-variance terms make this
        # more conservative than treating the denominator as fixed.
        var_r += 0.25 * (R*R) * (rel_i[:, None] + rel_i[None, :])
        Sr = np.sqrt(np.maximum(var_r, 0.0))
    Sr = _sym(Sr)
    np.fill_diagonal(Sr, 0.0)
    return R, Sr


def _analytic_global_risk_spec(spec: FactorCovarianceSpec, covariance_se, *, eps=1e-10):
    """One PSD-safe off-diagonal shrinkage factor estimated from analytical SE.

    Signal and noise are evaluated on the correlation scale so high-variance
    traits do not dominate.  The returned covariance preserves every marginal
    variance exactly and cannot increase rank.

    Parameters
    ----------
    spec : FactorCovarianceSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity.

    covariance_se : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to
        ``_analytic_corr_se_from_covariance`` as ``eps``.
    """
    C = spec.materialize()
    R, Sr = _analytic_corr_se_from_covariance(C, covariance_se, eps=eps)
    iu = np.triu_indices_from(R, 1)
    valid = np.isfinite(R[iu]) & np.isfinite(Sr[iu])
    if not np.any(valid):
        alpha = 1.0; tau2 = np.nan; noise = np.nan
    else:
        r = R[iu][valid]; s2 = np.square(Sr[iu][valid])
        signal = np.maximum(r*r - s2, 0.0)
        tau2 = float(np.mean(signal))
        noise = float(np.mean(s2))
        alpha = tau2 / (tau2 + noise) if (tau2 + noise) > 0 else 0.0
        alpha = float(np.clip(alpha, 0.0, 1.0))
    out = _scalar_shrink_spec(spec, alpha)
    weights = np.full_like(C, alpha, dtype=float); np.fill_diagonal(weights, 1.0)
    return out, {'mode':'analytic_global', 'alpha':alpha, 'tau2_corr':tau2,
                 'mean_noise_var_corr':noise, 'weights':weights,
                 'rank_preserved':True}


def _analytic_pairwise_fisher_eb_spec(spec: FactorCovarianceSpec, covariance_se, *,
                                      exact_corr_se=None, tau2=None, eps=1e-10,
                                      rank_preserve=True, fa_sweeps=8):
    """Pair-specific Fisher-z EB shrinkage driven by analytical estimator SE.

    This generalizes the older overlap-only E shrinker to any covariance
    component (A, D, GxE, total G or E).  Reliability comes from the analytical
    SE of the fitted covariance/correlation rather than from raw pair overlap.
    Pair-specific shrinkage is reconciled back to PSD and, for FA inputs,
    optionally to the same factor rank. Marginal variances are preserved.

    Parameters
    ----------
    spec : FactorCovarianceSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Passed to ``as_covariance_spec`` as
        ``name``.

    covariance_se : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    exact_corr_se : object (see the cited input contract)
        Input supplied to ``_analytic_corr_se_from_covariance`` as ``exact_corr_se``. See that
        callable's documented ``exact_corr_se`` contract for its type, alignment and value
        domain. This wrapper retains that contract. Default: ``None``. None delegates to the
        local fallback shown in this body; it is not an additional numeric/category value.
        Passed to ``_analytic_corr_se_from_covariance`` as ``exact_corr_se``.

    tau2 : float or None
        Nonnegative prior variance of Fisher-z correlation effects for empirical-Bayes
        retention. None estimates it from the supplied covariance and overlap information.
        Default: ``None``. Source comparisons: ``tau2 > 0``. See the rejection/fallback branches
        for enforcement.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to
        ``_analytic_corr_se_from_covariance`` as ``eps``.

    rank_preserve : bool
        Input for the operation ``bool(rank_preserve)``. See
        ``vigor.multivariate._analytic_pairwise_fisher_eb_spec`` and its caller for the
        scientific representation; the shown operation constrains the required type/shape.
        Default: ``True``.

    fa_sweeps : int
        Number of alternating/projection/relevance/eigenspace refinement iterations performed by
        the selected algorithm. Positive counts trade additional work for a more settled
        approximation. Default: ``8``. Passed to ``_fa_project_preserve_rank`` as ``fa_sweeps``.
    """
    C = _sym(spec.materialize())
    d = np.maximum(np.diag(C), float(eps)); sd = np.sqrt(d)
    R, Sr = _analytic_corr_se_from_covariance(C, covariance_se,
                                              exact_corr_se=exact_corr_se, eps=eps)
    Rc = np.clip(R, -1.0 + 1e-9, 1.0 - 1e-9)
    Z = np.arctanh(Rc); np.fill_diagonal(Z, 0.0)
    denom = np.maximum(1.0 - Rc*Rc, 1e-8)
    Sz = np.divide(Sr, denom, out=np.full_like(Sr, np.inf), where=np.isfinite(Sr))
    np.fill_diagonal(Sz, 0.0)
    iu = np.triu_indices_from(R, 1)
    valid = np.isfinite(Z[iu]) & np.isfinite(Sz[iu]) & (Sz[iu] >= 0)
    if tau2 is None:
        if np.any(valid):
            raw = np.square(Z[iu][valid]) - np.square(Sz[iu][valid])
            # Positive-part per-pair MoM: negative signal estimates are noise,
            # but should not cancel clearly estimable correlation pairs.
            tau2 = float(np.mean(np.maximum(raw, 0.0)))
        else:
            tau2 = 0.0
    tau2 = max(float(tau2), 0.0)
    alpha = np.zeros_like(C, dtype=float)
    finite = np.isfinite(Sz) & (Sz >= 0)
    if tau2 > 0:
        alpha[finite] = tau2 / (tau2 + np.square(Sz[finite]))
    np.fill_diagonal(alpha, 1.0)
    Rtarget = np.tanh(alpha * Z)
    np.fill_diagonal(Rtarget, 1.0)
    Rtarget = _legacy._project_psd(_sym(Rtarget), eps=max(float(eps), 1e-12))
    rr = np.sqrt(np.maximum(np.diag(Rtarget), eps))
    Rtarget = np.clip(_sym(Rtarget / np.outer(rr, rr)), -1.0, 1.0)
    np.fill_diagonal(Rtarget, 1.0)
    Ctarget = _sym(Rtarget * np.outer(sd, sd)); np.fill_diagonal(Ctarget, d)
    if bool(rank_preserve) and spec.rank < spec.n_traits:
        out = _fa_project_preserve_rank(Ctarget, spec, eps=eps, fa_sweeps=fa_sweeps)
    else:
        out = as_covariance_spec(Ctarget, name=spec.name)
    off = np.triu_indices_from(R, 1)
    return out, {'mode':'analytic_pairwise_fisher_eb', 'tau2_fisher':tau2,
                 'weights':alpha,
                 'median_corr_se':float(np.nanmedian(Sr[off])) if len(off[0]) else 0.0,
                 'median_fisher_se':float(np.nanmedian(Sz[off])) if len(off[0]) else 0.0,
                 'rank_preserved':bool(rank_preserve and spec.rank < spec.n_traits),
                 'rank_before':int(spec.rank), 'rank_after':int(out.rank)}


def _apply_analytic_prediction_shrinkage(spec, covariance_se, mode, *,
                                         exact_corr_se=None, eps=1e-10,
                                         rank_preserve=True):
    """Apply analytic prediction shrinkage.

    Parameters
    ----------
    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity.

    covariance_se : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    mode : str
        Input for the operation ``str(mode).lower()``. See
        ``vigor.multivariate._apply_analytic_prediction_shrinkage`` and its caller for the
        scientific representation; the shown operation constrains the required type/shape.
        Source-recognized literal values: ``global``, ``pairwise``. These select the
        corresponding branches below; comparison evidence alone does not establish an exhaustive
        enum.

    exact_corr_se : object (see the cited input contract)
        Input supplied to ``_analytic_pairwise_fisher_eb_spec`` as ``exact_corr_se``. See that
        callable's documented ``exact_corr_se`` contract for its type, alignment and value
        domain. This wrapper retains that contract. Default: ``None``. None delegates to the
        local fallback shown in this body; it is not an additional numeric/category value.
        Passed to ``_analytic_pairwise_fisher_eb_spec`` as ``exact_corr_se``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_analytic_global_risk_spec`` as
        ``eps``.

    rank_preserve : bool
        Input supplied to ``_analytic_pairwise_fisher_eb_spec`` as ``rank_preserve``. See that
        callable's documented ``rank_preserve`` contract for its type, alignment and value
        domain. This wrapper retains that contract. Default: ``True``. Passed to
        ``_analytic_pairwise_fisher_eb_spec`` as ``rank_preserve``.
    """
    mode = str(mode).lower()
    if mode == 'global':
        return _analytic_global_risk_spec(spec, covariance_se, eps=eps)
    if mode == 'pairwise':
        return _analytic_pairwise_fisher_eb_spec(
            spec, covariance_se, exact_corr_se=exact_corr_se, eps=eps,
            rank_preserve=rank_preserve,
        )
    raise ValueError(f'unknown analytical shrinkage mode {mode!r}')

def _overlap_components(overlap, min_overlap=2):
    """Find connected trait groups whose pairwise overlap meets the support threshold.

    Parameters
    ----------
    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    min_overlap : int
        Observation/sample-count threshold for the stage described above. Use nonnegative
        counts; the source comparison below defines whether it is a minimum support requirement
        or a full-matrix size cutoff. Default: ``2``.
    """
    ov = np.asarray(overlap, dtype=float)
    support = ov >= int(min_overlap)
    np.fill_diagonal(support, True)
    T = support.shape[0]
    seen = np.zeros(T, dtype=bool); components = []
    for root in range(T):
        if seen[root]:
            continue
        stack=[root]; seen[root]=True; comp=[]
        while stack:
            i=stack.pop(); comp.append(i)
            nxt=np.flatnonzero(support[i] & ~seen)
            if len(nxt):
                seen[nxt]=True; stack.extend(nxt.tolist())
        components.append(np.asarray(comp, dtype=int))
    return components


def _overlap_block_spec(spec: FactorCovarianceSpec, overlap, min_overlap=2, *, eps=1e-10):
    """Zero only residual covariance between disconnected overlap components.

    Unlike arbitrary edge masking, block diagonalization preserves PSD exactly
    because every retained block is a principal covariance submatrix.

    Parameters
    ----------
    spec : FactorCovarianceSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Passed to ``as_covariance_spec`` as
        ``name``.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    min_overlap : int
        Observation/sample-count threshold for the stage described above. Use nonnegative
        counts; the source comparison below defines whether it is a minimum support requirement
        or a full-matrix size cutoff. Default: ``2``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_legacy._project_psd`` as ``eps``.
    """
    C = _sym(spec.materialize())
    ov = np.asarray(overlap, dtype=float)
    support = ov >= int(min_overlap)
    np.fill_diagonal(support, True)
    T = C.shape[0]
    seen = np.zeros(T, dtype=bool)
    components = []
    for root in range(T):
        if seen[root]:
            continue
        stack = [root]; seen[root] = True; comp = []
        while stack:
            i = stack.pop(); comp.append(i)
            nxt = np.flatnonzero(support[i] & ~seen)
            if len(nxt):
                seen[nxt] = True; stack.extend(nxt.tolist())
        components.append(np.asarray(comp, dtype=int))
    if len(components) <= 1:
        return spec, components
    out = np.zeros_like(C)
    for idx in components:
        block = _legacy._project_psd(C[np.ix_(idx, idx)], eps=max(float(eps), 1e-12))
        out[np.ix_(idx, idx)] = block
    return as_covariance_spec(out, name=spec.name), components


def _legacy_supported_E_spec(spec, overlap, min_overlap=2, *, eps=1e-10):
    """2.8.2/gdec-style hard support masking retained as an explicit mode.

    Parameters
    ----------
    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Passed to ``FactorCovarianceSpec`` as
        ``name``.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    min_overlap : int
        Observation/sample-count threshold for the stage described above. Use nonnegative
        counts; the source comparison below defines whether it is a minimum support requirement
        or a full-matrix size cutoff. Default: ``2``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_legacy._project_psd`` as ``eps``.
    """
    C = spec.materialize()
    ov = np.asarray(overlap, dtype=float)
    support = ov >= int(min_overlap)
    np.fill_diagonal(support, True)
    iu = np.triu_indices_from(support, 1)
    unsupported = float(np.mean(~support[iu])) if len(iu[0]) else 0.0
    if unsupported >= 0.5:
        return FactorCovarianceSpec(np.zeros((C.shape[0], 0)), np.diag(C).copy(), name=spec.name), "diag_sparse_overlap"
    repaired = _legacy._project_psd(np.where(support, C, 0.0), eps=max(float(eps), 1e-10))
    return as_covariance_spec(repaired, name=spec.name), "supported_full"


def _apply_regularization_policy(raw_specs, names, overlap, policy, *, min_E_pair_overlap=2, eps=1e-10):
    """Apply an already-selected covariance regularization policy.

    This function is shared by the point estimate and every bootstrap replicate
    so uncertainty refers to the covariance matrices actually consumed by BLUP.

    Parameters
    ----------
    raw_specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    policy : str
        Residual retention policy: 'diag'/'diagonal' removes off-diagonals, 'full'/'none' keeps
        them, 'scalar' uses common retention, 'pairwise'/'overlap' uses overlap-dependent
        retention, and 'fisher_eb'/'eb' empirical-Bayes correlation retention. Supported-block
        aliases follow the local policy resolver. Source-recognized literal values:
        ``auto_supported``, ``blocks``, ``fa``, ``legacy_supported``, ``overlap_blocks``,
        ``pairwise_eb``, ``pairwise_overlap``. These select the corresponding branches below;
        comparison evidence alone does not establish an exhaustive enum. Passed to
        ``_pairwise_overlap_shrink_spec`` as ``rank_preserve``.

    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_pairwise_overlap_shrink_spec`` as
        ``eps``.
    """
    knames = [n for n in names if n != "E"]
    specs = {}
    galpha = policy.get("G_alpha", {})
    for name in knames:
        a = galpha.get(name, galpha.get("__all__", 1.0)) if isinstance(galpha, dict) else float(galpha)
        specs[name] = _scalar_shrink_spec(raw_specs[name], a)
    Espec = raw_specs["E"]
    emode = str(policy.get("E_mode", "none")).lower()
    if emode in {"none", "fa", "full"}:
        pass
    elif emode == "scalar":
        Espec = _scalar_shrink_spec(Espec, float(policy.get("E_alpha", 1.0)))
    elif emode in {"pairwise", "pairwise_overlap", "overlap"}:
        Espec = _pairwise_overlap_shrink_spec(
            Espec, overlap, float(policy.get("E_strength", 0.0)), eps=eps,
            rank_preserve=bool(policy.get("E_rank_preserve", True)),
        )
    elif emode in {"fisher_eb", "pairwise_eb", "eb"}:
        Espec, _, _ = _fisher_eb_overlap_spec(
            Espec, overlap, tau2=policy.get("E_tau2", None), eps=eps,
            rank_preserve=bool(policy.get("E_rank_preserve", True)),
        )
    elif emode == "pairwise_weights":
        # Per-pair retention fixed on the full fit (model_eb) and reused by bootstrap replicates.
        Espec = _pairwise_alpha_shrink_spec(
            Espec, np.asarray(policy["E_weights"], dtype=float), eps=eps,
            rank_preserve=bool(policy.get("E_rank_preserve", False)),
        )
    elif emode in {"blocks", "overlap_blocks"}:
        Espec, _ = _overlap_block_spec(Espec, overlap, min_overlap=min_E_pair_overlap, eps=eps)
    elif emode in {"diag", "diagonal"}:
        Espec = FactorCovarianceSpec(np.zeros((Espec.n_traits, 0)), Espec.diagonal().copy(), name="E")
    elif emode in {"legacy_supported", "auto_supported"}:
        if policy.get("E_alpha", None) is not None:
            Espec = _scalar_shrink_spec(Espec, float(policy["E_alpha"]))
        Espec, _ = _legacy_supported_E_spec(Espec, overlap, min_overlap=min_E_pair_overlap, eps=eps)
    else:
        raise ValueError(f"unknown residual regularization mode {emode!r}")

    # Structure is composable with smooth E shrinkage.  In particular,
    # E_structure='auto' uses blocks only when the phenotype-overlap graph is
    # genuinely disconnected; it does not invoke the 2.8.2 50%-unsupported
    # hard switch.
    estruct = str(policy.get("E_structure_mode", "none")).lower()
    if estruct in {"none", "fa", "full"}:
        pass
    elif estruct in {"blocks", "overlap_blocks"}:
        Espec, _ = _overlap_block_spec(Espec, overlap, min_overlap=min_E_pair_overlap, eps=eps)
    elif estruct in {"diag", "diagonal"}:
        Espec = FactorCovarianceSpec(np.zeros((Espec.n_traits, 0)), Espec.diagonal().copy(), name="E")
    elif estruct in {"legacy_supported", "auto_supported"}:
        Espec, _ = _legacy_supported_E_spec(Espec, overlap, min_overlap=min_E_pair_overlap, eps=eps)
    else:
        raise ValueError(f"unknown residual structure mode {estruct!r}")
    specs["E"] = Espec
    return specs


def _regularization_policy_from_requests(raw_specs, names, overlap, *, shrink_G, shrink_E, E_structure, moments=None,
                                         min_E_pair_overlap=2, eps=1e-10):
    """Resolve covariance regularization requests into one reusable policy.

    ``auto`` is prediction-oriented: G keeps the historically validated
    sample-size shrinkage n/(n+50), and E shrinks each residual pair by
    overlap/(overlap+400) without rank preservation (the 3.1.3 policy, restored
    in 2.12.1 after it outperformed the 2.8.3 Fisher-z EB default on held-out
    prediction). Fisher-z EB remains available as ``'eb'``.
    ``auto_cv`` remains available for the experimental held-out-moment selector.

    Parameters
    ----------
    raw_specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations.

    shrink_G : float, str or mapping
        Genetic off-diagonal retention: numeric values conventionally lie in [0,1], with 1
        retaining all. 'auto'/'legacy_auto'/'historical_auto' uses sample-size retention
        n/(n+50); 'none'/'off' retains all; 'auto_cv'/'cv' invokes held-out moment policy
        selection. 'analytic_global'/'analytic_pairwise' (and aliases resolved by
        _analytic_shrink_mode) regularizes prediction after final SE, preserving unshrunk
        inference. Kernel-name mappings are accepted. Residual-only pairwise/EB spellings are
        not genetic policies.

    shrink_E : float or str
        Residual retention: numeric 0..1 scales off-diagonals.
        'auto' shrinks each residual pair by overlap/(overlap+400) without rank preservation
        (the 3.1.3 policy; same as 'pairwise_full'); append '@s' ('auto@100') to set the
        per-pair strength s. 'linear_analytic' applies the closed-form overlap-aware
        Schafer-Strimmer linear intensity toward the diagonal. 'model_eb' ('model_eb@c')
        shrinks each pair by tau2/(tau2 + c s2_ij), with s2_ij the pair's sampling variance
        from the fit's own MoM precision. 'eb'/'fisher_eb'/'pairwise_eb' uses
        rank-preserving Fisher-z EB, while 'fisher_eb_full'/'pairwise_eb_full'/'eb_full'
        permits full-rank pair retention. 'pairwise'/'pairwise_overlap' uses overlap support
        with rank preservation; 'pairwise_full'/'pairwise_overlap_full' omits that rank
        restriction.
        'legacy_auto'/'historical_auto' uses median overlap/(overlap+400); 'none'/'off' retains
        all. 'auto_cv'/'cv' selects on held-out moments; analytic aliases use final-SE
        prediction retention. auto_supported E requires scalar-compatible retention.

    E_structure : str
        Residual structure: 'auto' splits only disconnected overlap-support components,
        otherwise retaining FA geometry; 'fa'/'full' keeps joint residual covariance;
        'diag'/'diagonal' removes factors; 'auto_supported' uses legacy overlap-supported
        blocks. 'auto_cv' selects structure using held-out moments. min_E_pair_overlap defines
        supported pairs.

    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_fisher_eb_overlap_spec`` as
        ``eps``.
    """
    knames = [n for n in names if n != "E"]
    ov = np.asarray(overlap, float)
    nobs = np.diag(ov)

    def resolve_g(v):
        """Resolve g.

        Parameters
        ----------
        v : array-like
            Numerical operand in ``v.lower()``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state. Source-recognized literal values: ``auto``,
            ``auto_cv``, ``cv``, ``historical_auto``, ``legacy_auto``, ``none``, ``off``. These
            select the corresponding branches below; comparison evidence alone does not establish an
            exhaustive enum.

        Returns
        -------
        object
            Computed result from ``float(v)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        if isinstance(v, str):
            key = v.lower()
            if key in {"auto", "legacy_auto", "historical_auto"}:
                return float(_auto_shrink(nobs, 50.0))
            if key in {"auto_cv", "cv"}:
                raise RuntimeError("internal: shrink_G='auto_cv' requires CV policy selection")
            if key in {"none", "off"}:
                return 1.0
            if _analytic_shrink_mode(v) is not None:
                # Analytical-SE shrinkage is intentionally post-fit: estimate
                # inference covariance/SE first, then derive prediction views.
                return 1.0
            raise ValueError(f"unknown shrink_G string {v!r}")
        return float(v)

    if isinstance(shrink_G, dict):
        ga = {name: resolve_g(shrink_G.get(name, 1.0)) for name in knames}
    else:
        gv = resolve_g(shrink_G)
        ga = {name: gv for name in knames}

    estruct = str(E_structure).lower()
    if estruct == "auto_cv":
        raise RuntimeError("internal: E_structure='auto_cv' requires CV policy selection")
    if estruct in {"diag", "diagonal"}:
        return {"G_alpha": ga, "E_mode": "none", "E_structure_mode": "diag",
                "E_structure_resolved": "diag"}
    if estruct == "auto_supported":
        ev = shrink_E
        if isinstance(ev, str) and ev.lower() in {"auto", "legacy_auto", "historical_auto"}:
            iu = np.triu_indices_from(ov, 1)
            med = float(np.median(ov[iu])) if len(iu[0]) else float(np.median(nobs))
            ev = med / (med + 400.0)
        return {"G_alpha": ga, "E_mode": "scalar", "E_alpha": float(ev),
                "E_structure_mode": "legacy_supported", "E_structure_resolved": "auto_supported"}

    # Smooth residual shrinkage.  The auto/EB scale is estimated once on the
    # full fit and then fixed across bootstrap replicates.
    if isinstance(shrink_E, str):
        key = shrink_E.lower()
        # 'auto@s' / 'pairwise@s' / 'pairwise_full@s' set the per-pair strength s in
        # overlap/(overlap+s); without '@' the strength is 400 (the 3.1.3 constant).
        # 'model_eb@c' sets the sampling-variance multiplier c of the model-based EB.
        strength = 400.0
        multiplier = 1.0
        if "@" in key:
            key, _, raw = key.partition("@")
            if key not in {"auto", "pairwise", "pairwise_overlap", "pairwise_full", "pairwise_overlap_full", "model_eb"}:
                raise ValueError(f"an '@' value applies only to auto/pairwise/model_eb shrink_E, not {shrink_E!r}")
            value = float(raw)
            if not np.isfinite(value) or value <= 0:
                raise ValueError(f"shrink_E '@' value must be positive: {shrink_E!r}")
            if key == "model_eb":
                multiplier = value
            else:
                strength = value
        if key == "auto":
            # 2.12.1: the 3.1.3 per-pair overlap/(overlap+400) residual shrinkage without
            # rank preservation. It matched or beat Fisher-z EB on every held-out panel of
            # the chromosome-GRM benchmark and keeps the mvBLUP system well conditioned
            # (24 vs ~200 PCG iterations). Fisher-z EB stays available as 'eb'.
            epol = {"E_mode": "pairwise_overlap", "E_strength": strength, "E_rank_preserve": False}
        elif key in {"linear_analytic", "schafer_strimmer"}:
            # Closed-form global intensity, estimated once and reused by bootstrap replicates.
            epol = {"E_mode": "scalar", "E_alpha": _linear_analytic_retention(raw_specs["E"], ov, eps=eps),
                    "E_shrinkage_estimator": "schafer_strimmer"}
        elif key == "model_eb":
            # Model-based per-pair EB: sampling variances from the fit's own MoM precision.
            if moments is None:
                raise ValueError("shrink_E='model_eb' needs the fit's method-of-moments tensors")
            weights, tau2, info = _model_eb_pair_weights(raw_specs, names, moments, ov,
                                                         multiplier=multiplier, eps=eps)
            epol = {"E_mode": "pairwise_weights", "E_weights": weights.tolist(), "E_tau2": float(tau2),
                    "E_rank_preserve": False, "E_model_eb_multiplier": float(multiplier),
                    "E_shrinkage_estimator": "model_eb", **info}
        elif key in {"eb", "fisher_eb", "pairwise_eb"}:
            _, tau2, _ = _fisher_eb_overlap_spec(raw_specs["E"], ov, tau2=None, eps=eps, rank_preserve=True)
            epol = {"E_mode": "fisher_eb", "E_tau2": float(tau2), "E_rank_preserve": True}
        elif key in {"fisher_eb_full", "pairwise_eb_full", "eb_full"}:
            _, tau2, _ = _fisher_eb_overlap_spec(raw_specs["E"], ov, tau2=None, eps=eps, rank_preserve=False)
            epol = {"E_mode": "fisher_eb", "E_tau2": float(tau2), "E_rank_preserve": False}
        elif key in {"auto_cv", "cv"}:
            raise RuntimeError("internal: shrink_E='auto_cv' requires CV policy selection")
        elif key in {"legacy_auto", "historical_auto"}:
            iu = np.triu_indices_from(ov, 1)
            med = float(np.median(ov[iu])) if len(iu[0]) else float(np.median(nobs))
            epol = {"E_mode": "scalar", "E_alpha": med / (med + 400.0)}
        elif key in {"none", "off"}:
            epol = {"E_mode": "none"}
        elif _analytic_shrink_mode(shrink_E) is not None:
            # Delayed until analytical covariance SEs are available.
            epol = {"E_mode": "none"}
        elif key in {"pairwise", "pairwise_overlap"}:
            epol = {"E_mode": "pairwise_overlap", "E_strength": strength, "E_rank_preserve": True}
        elif key in {"pairwise_full", "pairwise_overlap_full"}:
            epol = {"E_mode": "pairwise_overlap", "E_strength": strength, "E_rank_preserve": False}
        else:
            raise ValueError(f"unknown shrink_E string {shrink_E!r}")
    else:
        epol = {"E_mode": "scalar", "E_alpha": float(shrink_E)}

    # Automatic structure should only make a discrete structural change when
    # the phenotype-overlap graph is disconnected.  Sparse individual pairs
    # are handled continuously by the pair-specific E shrinkage above.
    if estruct == "auto":
        comps = _overlap_components(ov, min_overlap=min_E_pair_overlap)
        if len(comps) > 1:
            spol = {"E_structure_mode": "overlap_blocks", "E_structure_resolved": "overlap_blocks"}
        else:
            spol = {"E_structure_mode": "none", "E_structure_resolved": "fa"}
    elif estruct in {"fa", "full"}:
        spol = {"E_structure_mode": "none", "E_structure_resolved": estruct}
    else:
        raise ValueError(f"unknown E_structure {E_structure!r}")
    return {"G_alpha": ga, **epol, **spol}


def _select_regularization_policy(moments, ranks, names, *, shrink_G, shrink_E, E_structure,
                                  validation_fraction=0.10, random_state=0, min_E_pair_overlap=2,
                                  spectral_weighting="rank1", spectral_fa_sweeps=4, eps=1e-8):
    """Select post-fit shrinkage/structure by held-out moment prediction.

    The tuning fit is a fast spectral-FA fit on training moment entries.  This
    avoids arbitrary pseudocount constants while keeping auto-selection O(T^2)
    after one inexpensive covariance fit; it does not run candidate mvBLUPs.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Passed to ``fit_mom_spectral`` as ``ranks``.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Passed to
        ``fit_mom_spectral`` as ``names``.

    shrink_G : float, str or mapping
        Genetic off-diagonal retention: numeric values conventionally lie in [0,1], with 1
        retaining all. 'auto'/'legacy_auto'/'historical_auto' uses sample-size retention
        n/(n+50); 'none'/'off' retains all; 'auto_cv'/'cv' invokes held-out moment policy
        selection. 'analytic_global'/'analytic_pairwise' (and aliases resolved by
        _analytic_shrink_mode) regularizes prediction after final SE, preserving unshrunk
        inference. Kernel-name mappings are accepted. Residual-only pairwise/EB spellings are
        not genetic policies.

    shrink_E : float or str
        Residual retention: numeric 0..1 scales off-diagonals.
        'auto' shrinks each residual pair by overlap/(overlap+400) without rank preservation
        (the 3.1.3 policy; same as 'pairwise_full'); append '@s' ('auto@100') to set the
        per-pair strength s. 'linear_analytic' applies the closed-form overlap-aware
        Schafer-Strimmer linear intensity toward the diagonal. 'model_eb' ('model_eb@c')
        shrinks each pair by tau2/(tau2 + c s2_ij), with s2_ij the pair's sampling variance
        from the fit's own MoM precision. 'eb'/'fisher_eb'/'pairwise_eb' uses
        rank-preserving Fisher-z EB, while 'fisher_eb_full'/'pairwise_eb_full'/'eb_full'
        permits full-rank pair retention. 'pairwise'/'pairwise_overlap' uses overlap support
        with rank preservation; 'pairwise_full'/'pairwise_overlap_full' omits that rank
        restriction.
        'legacy_auto'/'historical_auto' uses median overlap/(overlap+400); 'none'/'off' retains
        all. 'auto_cv'/'cv' selects on held-out moments; analytic aliases use final-SE
        prediction retention. auto_supported E requires scalar-compatible retention.

    E_structure : str
        Residual structure: 'auto' splits only disconnected overlap-support components,
        otherwise retaining FA geometry; 'fa'/'full' keeps joint residual covariance;
        'diag'/'diagonal' removes factors; 'auto_supported' uses legacy overlap-supported
        blocks. 'auto_cv' selects structure using held-out moments. min_E_pair_overlap defines
        supported pairs.

    validation_fraction : float
        Fraction of eligible entries/animals selected for the corresponding holdout or
        resampling operation; use a value in (0, 1] compatible with nonempty training/evaluation
        subsets. Default: ``0.1``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``.

    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    spectral_fa_sweeps : int
        Number of alternating low-rank/specific-diagonal updates in each spectral FA projection;
        positive counts improve initializer consistency at extra cost. Default: ``4``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``fit_mom_spectral`` as ``eps``.
    """
    T = np.asarray(moments["B"]).shape[-1]
    val = _rank_validation_mask(T, validation_fraction, int(random_state) + 104729)
    train = ~val; np.fill_diagonal(train, True)
    tune = fit_mom_spectral(
        moments, ranks=ranks, names=names, entry_weight=train.astype(float), structure="fa",
        spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps, eps=eps,
    )
    raw = tune["specs"]
    overlap = np.asarray(moments["A"][-1, -1], float)
    knames = [n for n in names if n != "E"]
    nobs = np.diag(overlap)

    if isinstance(shrink_G, str) and shrink_G.lower() == "auto":
        g_candidates = [0.50, 0.70, 0.85, 0.93, 0.97, 0.99, 1.0]
    elif isinstance(shrink_G, dict) and any(isinstance(v, str) and v.lower()=="auto" for v in shrink_G.values()):
        # Coordinate-specific auto would make the grid exponential. Use one
        # shared CV-selected alpha for requested-auto components and fixed values
        # for the others.
        g_candidates = [0.50, 0.70, 0.85, 0.93, 0.97, 0.99, 1.0]
    else:
        base = _regularization_policy_from_requests(raw, names, overlap, shrink_G=shrink_G,
                 shrink_E=1.0, E_structure="fa", min_E_pair_overlap=min_E_pair_overlap, eps=eps)
        vals = list(base["G_alpha"].values())
        g_candidates = [float(vals[0]) if vals and np.allclose(vals, vals[0]) else 1.0]

    estruct = str(E_structure).lower()
    e_options = []
    if estruct in {"diag", "diagonal"}:
        e_options = [{"E_mode":"diag", "E_structure_resolved":"diag"}]
    elif estruct == "auto_supported":
        base = _regularization_policy_from_requests(raw, names, overlap, shrink_G=1.0, shrink_E=shrink_E,
                 E_structure="auto_supported", min_E_pair_overlap=min_E_pair_overlap, eps=eps)
        e_options = [{k:v for k,v in base.items() if k != "G_alpha"}]
    elif isinstance(shrink_E, str) and shrink_E.lower() == "auto":
        strengths = [0.0, 25.0, 50.0, 100.0, 200.0, 400.0, 800.0, 1600.0, 3200.0]
        resolved_pair = "pairwise_overlap" if estruct in {"auto", "auto_cv"} else estruct
        e_options = [{"E_mode":"pairwise_overlap", "E_strength":s, "E_rank_preserve":True, "E_structure_resolved":resolved_pair} for s in strengths]
        if estruct in {"auto", "auto_cv"}:
            e_options += [{"E_mode":"overlap_blocks", "E_structure_resolved":"overlap_blocks"},
                          {"E_mode":"diag", "E_structure_resolved":"diag"}]
    elif estruct in {"auto", "auto_cv"}:
        base = _regularization_policy_from_requests(raw, names, overlap, shrink_G=1.0, shrink_E=shrink_E,
                 E_structure="fa", moments=moments, min_E_pair_overlap=min_E_pair_overlap, eps=eps)
        ebase = {k:v for k,v in base.items() if k != "G_alpha"}
        e_options = [ebase, {"E_mode":"overlap_blocks", "E_structure_resolved":"overlap_blocks"},
                     {"E_mode":"diag", "E_structure_resolved":"diag"}]
    else:
        base = _regularization_policy_from_requests(raw, names, overlap, shrink_G=1.0, shrink_E=shrink_E,
                 E_structure=estruct, moments=moments, min_E_pair_overlap=min_E_pair_overlap, eps=eps)
        e_options = [{k:v for k,v in base.items() if k != "G_alpha"}]

    rows=[]; policies=[]
    for ga in g_candidates:
        if isinstance(shrink_G, dict):
            gamap={}
            for n in knames:
                v=shrink_G.get(n,1.0)
                gamap[n]=float(ga if isinstance(v,str) and v.lower()=="auto" else v)
        else:
            gamap={n:float(ga) for n in knames}
        for eo in e_options:
            pol={"G_alpha":gamap, **eo}
            specs=_apply_regularization_policy(raw,names,overlap,pol,min_E_pair_overlap=min_E_pair_overlap,eps=eps)
            mats=[specs[n].materialize() for n in names]
            err=_moment_prediction_error(moments,mats,val)
            rows.append({"G_alpha":float(ga),"E_mode":eo.get("E_mode"),
                         "E_strength":eo.get("E_strength",np.nan),"E_alpha":eo.get("E_alpha",np.nan),
                         "E_structure_resolved":eo.get("E_structure_resolved"),**err})
            policies.append(pol)
    table=pd.DataFrame(rows)
    good=np.isfinite(table["moment_nrmse"].to_numpy(float))
    if np.any(good):
        best_idx=int(np.flatnonzero(good)[np.argmin(table.loc[good,"moment_nrmse"].to_numpy(float))])
    else:
        best_idx=len(policies)-1
    return {"policy":policies[best_idx],"table":table,"validation_mask":val,"tuning_fit":tune}


def _resolve_rank_inputs(rank_G, rank_E, T, n_components):
    """Resolve rank inputs.

    Parameters
    ----------
    rank_G : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine.

    rank_E : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine.

    T : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    n_components : int or None
        Number of retained latent components or feature directions. Must fit the available
        matrix dimensions; None delegates selection to the decomposition helper when supported.
    """
    if isinstance(rank_G, dict):
        granks = [rank_G.get(n, "full") for n in n_components]
    else:
        granks = [rank_G] * len(n_components)
    erank = rank_E
    return granks, erank



# ---------------------------------------------------------------------------
# VIGOR 2.8 analytic uncertainty for strict spectral MoM covariance
# ---------------------------------------------------------------------------
def _spectral_tangent(V, spec):
    """Tangent-space derivative of the fixed-rank PSD map.

    For a true/near rank-r covariance the discarded eigenvalues are close to
    zero, giving J(V)=P V + V P - P V P. This is the scalable first-order
    derivative used by the 2.8 spectral analytic-SE path.

    Parameters
    ----------
    V : array-like
        Numerical operand in ``Q @ (Q.T @ V)``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity.
    """
    V = _sym(np.asarray(V, dtype=float))
    T = V.shape[0]
    F = np.asarray(spec.factor, dtype=float)
    if F.shape[1] == 0:
        return np.zeros_like(V)
    if F.shape[1] >= T:
        return V
    Q, _ = np.linalg.qr(F, mode="reduced")
    PV = Q @ (Q.T @ V)
    VP = (V @ Q) @ Q.T
    PVP = Q @ (Q.T @ V @ Q) @ Q.T
    return _sym(PV + VP - PVP)



@dataclass
class _FATangentProjector:
    """Local orthogonal projector for C=L L' + diag(Psi).

    The low-rank PSD tangent is ``{L D' + D L'}``.  Adding free diagonal
    specific variances enlarges the tangent by the diagonal subspace.  The
    orthogonal complement is therefore the intersection of matrices R with
    ``R @ span(L) = 0`` and zero diagonal on interior Psi coordinates.

    For the residual after projecting away the low-rank tangent,
    ``R=P_perp V P_perp``, projection onto the residualized diagonal basis
    solves ``(P_perp ∘ P_perp) c = diag(R)``.  This is exact for interior
    factor-analysis points and avoids a Hessian over all factor parameters.

    Constructor fields
    ------------------
    Q : np.ndarray
        Stored Q consumed by ``n_traits``/``rank``/``_lowrank_project``/``_gram_matvec_full``;
        see those methods for the numerical/label contract. Required construction field.

    active_diag : np.ndarray
        Stored active diag consumed by ``_solve_diag_coeff``/``apply``; see those methods for
        the numerical/label contract. Required construction field.

    chol : Any | None
        Stored chol consumed by ``_solve_diag_coeff``; see those methods for the numerical/label
        contract. Default: ``None``.

    gram : np.ndarray | None
        Stored gram consumed by ``_solve_diag_coeff``; see those methods for the numerical/label
        contract. Default: ``None``.

    cg_operator : LinearOperator | None
        Stored cg operator consumed by ``_solve_diag_coeff``; see those methods for the
        numerical/label contract. Default: ``None``.

    cg_precond : LinearOperator | None
        Stored cg precond consumed by ``_solve_diag_coeff``; see those methods for the
        numerical/label contract. Default: ``None``.

    cg_rtol : float
        Stored cg rtol consumed by ``_solve_diag_coeff``; see those methods for the
        numerical/label contract. Default: ``1e-09``.

    cg_maxiter : int
        Stored cg maxiter consumed by ``_solve_diag_coeff``; see those methods for the
        numerical/label contract. Default: ``400``.

    boundary_count : int
        Stored boundary count supplied by the corresponding fitting/planning routine. See that
        routine for the result-axis/value contract. Default: ``0``.

    direct : bool
        Stored direct consumed by ``_solve_diag_coeff``; see those methods for the
        numerical/label contract. Default: ``True``.
    """
    Q: np.ndarray
    active_diag: np.ndarray
    chol: Any | None = None
    gram: np.ndarray | None = None
    cg_operator: LinearOperator | None = None
    cg_precond: LinearOperator | None = None
    cg_rtol: float = 1e-9
    cg_maxiter: int = 400
    boundary_count: int = 0
    direct: bool = True

    @property
    def n_traits(self):
        """Return the n traits result computed by ``int``.

        Returns
        -------
        object
            Computed result from ``int(self.Q.shape[0])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return int(self.Q.shape[0])

    @property
    def rank(self):
        """Return the rank result computed by ``int``.

        Returns
        -------
        object
            Computed result from ``int(self.Q.shape[1])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return int(self.Q.shape[1])

    def _lowrank_project(self, V):
        """Construct low-rank project.

        Parameters
        ----------
        V : array-like
            Numerical operand in ``V @ Q``. Shape must conform to that matrix/vector operation and
            the enclosing prepared state.
        """
        V = _sym(np.asarray(V, dtype=float))
        T = self.n_traits
        if self.rank == 0:
            return np.zeros_like(V)
        if self.rank >= T:
            return V
        Q = self.Q
        VQ = V @ Q
        QtVQ = Q.T @ VQ
        return _sym(Q @ VQ.T + VQ @ Q.T - Q @ QtVQ @ Q.T)

    def _gram_matvec_full(self, c_full):
        """(Pperp ∘ Pperp)c without forming Pperp.

        Parameters
        ----------
        c_full : array-like or numeric scalar
            Input for the operation ``Q.T @ (c_full[:, None] * Q)``. See
            ``vigor.multivariate._FATangentProjector._gram_matvec_full`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.
        """
        c_full = np.asarray(c_full, dtype=float)
        if self.rank == 0:
            return c_full.copy()
        Q = self.Q
        h = np.einsum('ij,ij->i', Q, Q)
        S = Q.T @ (c_full[:, None] * Q)
        pdp_diag = np.einsum('ij,ij->i', Q @ S, Q)
        return (1.0 - 2.0 * h) * c_full + pdp_diag

    def _solve_diag_coeff(self, rhs):
        """Solve diag coeff.

        Parameters
        ----------
        rhs : array-like or None
            Right-hand side of the prepared linear system. Its length must match the operator's
            observed-cell dimension; None uses the response stored in the solver plan when
            supported.
        """
        idx = self.active_diag
        if idx.size == 0:
            return np.zeros(self.n_traits, dtype=float)
        rhs = np.asarray(rhs, dtype=float)[idx]
        if self.direct:
            try:
                c = cho_solve(self.chol, rhs, check_finite=False)
            except Exception:
                c = np.linalg.lstsq(self.gram, rhs, rcond=1e-10)[0]
        else:
            c, info = cg(self.cg_operator, rhs, M=self.cg_precond,
                         rtol=float(self.cg_rtol), atol=0.0,
                         maxiter=int(self.cg_maxiter))
            if info != 0 or not np.all(np.isfinite(c)):
                # This branch is only used for very large trait counts.  A
                # diagonal preconditioned least-squares fallback is safer than
                # returning a silently non-finite projector.
                d = np.asarray(self.cg_precond.matvec(np.ones_like(rhs)))
                c = rhs * d
        out = np.zeros(self.n_traits, dtype=float)
        out[idx] = c
        return out

    def apply(self, V):
        """Apply the enclosing covariance/tangent transformation to the supplied operand.

        Parameters
        ----------
        V : array-like
            Numerical operand in ``V - PA``. Shape must conform to that matrix/vector operation and
            the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``_sym(PA + corr)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        V = _sym(np.asarray(V, dtype=float))
        T = self.n_traits
        if self.rank >= T:
            return V
        PA = self._lowrank_project(V)
        if self.active_diag.size == 0:
            return PA
        R = _sym(V - PA)  # = Pperp V Pperp up to roundoff
        c = self._solve_diag_coeff(np.diag(R))
        if not np.any(c):
            return PA
        if self.rank == 0:
            return _sym(PA + np.diag(c))
        # Pperp diag(c) Pperp = D - P D - D P + P D P.
        Q = self.Q
        QTD = Q.T * c[None, :]
        PD = Q @ QTD
        DP = PD.T
        S = Q.T @ (c[:, None] * Q)
        PDP = Q @ S @ Q.T
        corr = np.diag(c) - PD - DP + PDP
        return _sym(PA + corr)


@dataclass
class _SparseFATangentProjector:
    """Orthogonal tangent projector for a fixed sparse loading support.

    For C=FF'+diag(psi), with selected loading zeros held fixed, the local
    tangent is J(dF,dpsi)=dF F'+F dF'+diag(dpsi).  Projection is performed in
    parameter space with matrix-free CG on J'J, avoiding a T^2 x parameter
    Jacobian.  This makes final analytical SE conditional on the selected
    sparse support while retaining the existing moment-sandwich machinery.

    Constructor fields
    ------------------
    F : np.ndarray
        Stored F consumed by ``__post_init__``/``n_traits``/``rank``/``_jt``; see those methods
        for the numerical/label contract. Required construction field.

    support : np.ndarray
        Stored support consumed by ``__post_init__``; see those methods for the numerical/label
        contract. Required construction field.

    active_diag : np.ndarray
        Stored active diag consumed by ``__post_init__``/``_jt``/``_j``; see those methods for
        the numerical/label contract. Required construction field.

    cg_rtol : float
        Stored cg rtol consumed by ``apply``; see those methods for the numerical/label
        contract. Default: ``1e-09``.

    cg_maxiter : int
        Stored cg maxiter consumed by ``apply``; see those methods for the numerical/label
        contract. Default: ``400``.

    eps : float
        Stored eps consumed by ``__post_init__``; see those methods for the numerical/label
        contract. Default: ``1e-10``.

    boundary_count : int
        Stored boundary count supplied by the corresponding fitting/planning routine. See that
        routine for the result-axis/value contract. Default: ``0``.
    """
    F: np.ndarray
    support: np.ndarray
    active_diag: np.ndarray
    cg_rtol: float = 1e-9
    cg_maxiter: int = 400
    eps: float = 1e-10
    boundary_count: int = 0

    def __post_init__(self):
        """Validate/coerce the constructed dataclass fields for subsequent model operations.
                
        """
        self.F = np.asarray(self.F, float)
        self.support = np.asarray(self.support, bool)
        self.active_diag = np.asarray(self.active_diag, dtype=int)
        self.rows, self.cols = np.where(self.support)
        self.n_load = int(len(self.rows))
        self.n_diag = int(len(self.active_diag))
        self.n_param = self.n_load + self.n_diag
        # Diagonal preconditioner from Frobenius norms of Jacobian basis terms.
        if self.n_load:
            cn = np.sum(self.F * self.F, axis=0)
            dload = 2.0 * cn[self.cols] + 2.0 * self.F[self.rows, self.cols] ** 2
        else:
            dload = np.empty(0, float)
        ddiag = np.ones(self.n_diag, float)
        diag = np.concatenate([dload, ddiag]) if self.n_param else np.empty(0, float)
        scale = max(float(np.nanmedian(diag[diag > 0])) if np.any(diag > 0) else 1.0, 1.0)
        self.jitter = max(float(self.eps), 1e-12) * scale
        self.diag_precond = np.maximum(diag + self.jitter, self.jitter)

    @property
    def n_traits(self):
        """Return the n traits result computed by ``int``.

        Returns
        -------
        object
            Computed result from ``int(self.F.shape[0])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return int(self.F.shape[0])

    @property
    def rank(self):
        """Return the rank result computed by ``int``.

        Returns
        -------
        object
            Computed result from ``int(self.F.shape[1])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return int(self.F.shape[1])

    @property
    def direct(self):
        """Evaluate the direct (non-iterative) path of the enclosing covariance uncertainty calculation.

        Returns
        -------
        object
            Computed result from ``False``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return False

    def _jt(self, V):
        """Apply the transpose of the enclosing covariance tangent Jacobian.

        Parameters
        ----------
        V : array-like
            Numerical operand in ``V @ self.F``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state.
        """
        V = _sym(np.asarray(V, float))
        VF = V @ self.F
        parts = []
        if self.n_load:
            parts.append(2.0 * VF[self.rows, self.cols])
        if self.n_diag:
            parts.append(np.diag(V)[self.active_diag])
        return np.concatenate(parts) if parts else np.empty(0, float)

    def _j(self, theta):
        """Return the j result computed by ``_sym``.

        Parameters
        ----------
        theta : array-like or mapping
            Model parameter/prior-weight values in the fitting layout consumed here. Weights must
            align prior mixture states and parameters the declared coefficient slices; use the
            matching preparation routine.
        """
        theta = np.asarray(theta, float)
        dF = np.zeros_like(self.F)
        if self.n_load:
            dF[self.rows, self.cols] = theta[:self.n_load]
        out = dF @ self.F.T + self.F @ dF.T
        if self.n_diag:
            d = np.zeros(self.n_traits, float)
            d[self.active_diag] = theta[self.n_load:self.n_load + self.n_diag]
            out = out + np.diag(d)
        return _sym(out)

    def apply(self, V):
        """Apply the enclosing covariance/tangent transformation to the supplied operand.

        Parameters
        ----------
        V : array-like
            Numerical operand in ``self._jt(V)``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``self._j(sol)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        if self.n_param == 0:
            return np.zeros((self.n_traits, self.n_traits), float)
        rhs = self._jt(V)
        if not np.any(np.isfinite(rhs)):
            return np.zeros((self.n_traits, self.n_traits), float)
        def mv(x):
            """Compute mv.

            Parameters
            ----------
            x : one-dimensional array-like
                Vector supplied by the linear operator/iterative-solver callback. Length equals the
                enclosing operator dimension; observed-cell operators use the prepared finite-cell
                order.

            Returns
            -------
            object
                Computed result from ``self._jt(self._j(x)) + self.jitter * np.asarray(x, float)``; see the summary and the called implementation for its labeled/numerical representation.
            """
            return self._jt(self._j(x)) + self.jitter * np.asarray(x, float)
        Aop = LinearOperator((self.n_param, self.n_param), matvec=mv, rmatvec=mv, dtype=float)
        Mop = LinearOperator(
            (self.n_param, self.n_param),
            matvec=lambda x: np.asarray(x, float) / self.diag_precond,
            rmatvec=lambda x: np.asarray(x, float) / self.diag_precond,
            dtype=float,
        )
        sol, info = cg(Aop, rhs, M=Mop, rtol=float(self.cg_rtol), atol=0.0,
                       maxiter=int(self.cg_maxiter))
        if info != 0 or not np.all(np.isfinite(sol)):
            # A small least-squares solve is useful for tiny sparse supports;
            # otherwise the preconditioned diagonal approximation is safer than
            # returning non-finite uncertainty.
            if self.n_param <= 256:
                E = np.eye(self.n_param)
                H = np.column_stack([mv(E[:, j]) for j in range(self.n_param)])
                sol = np.linalg.lstsq(H, rhs, rcond=1e-10)[0]
            else:
                sol = rhs / self.diag_precond
        return self._j(sol)


def _prepare_fa_tangent_projector(spec, *, eps=1e-10, boundary_tol=1e-8,
                                  direct_max_traits=2200, cg_rtol=1e-9,
                                  cg_maxiter=400):
    """Precompute the local FA tangent projector for repeated Hutchinson probes.

    Parameters
    ----------
    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_SparseFATangentProjector`` as
        ``eps``.

    boundary_tol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-08``.

    direct_max_traits : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``2200``.

    cg_rtol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-09``. Passed to ``_SparseFATangentProjector`` as ``cg_rtol``.

    cg_maxiter : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``400``. Passed to ``_SparseFATangentProjector`` as ``cg_maxiter``.
    """
    F = np.asarray(spec.factor, dtype=float)
    psi = np.asarray(spec.diag_specific, dtype=float)
    T = int(spec.n_traits)
    support = getattr(spec, "support_mask", None)
    if support is not None:
        support = np.asarray(support, dtype=bool)
        if support.shape != F.shape:
            raise ValueError("sparse FA support mask shape does not match factor loadings")
        if not np.all(support):
            scale = max(float(np.nanmedian(np.maximum(spec.diagonal(), 0.0))), float(eps), 1e-12)
            threshold = max(float(eps) * 10.0, float(boundary_tol) * scale)
            active = np.flatnonzero(np.isfinite(psi) & (psi > threshold))
            return _SparseFATangentProjector(
                F=F, support=support, active_diag=active, cg_rtol=cg_rtol,
                cg_maxiter=cg_maxiter, eps=eps, boundary_count=int(T-active.size),
            )
    if F.shape[1] >= T:
        Q = np.eye(T, dtype=float)
        return _FATangentProjector(Q=Q, active_diag=np.array([], dtype=int),
                                   boundary_count=0, direct=True)
    if F.shape[1]:
        Q, R = np.linalg.qr(F, mode='reduced')
        keep = np.abs(np.diag(R)) > max(float(eps), 1e-12)
        Q = Q[:, keep]
    else:
        Q = np.zeros((T, 0), dtype=float)
    scale = max(float(np.nanmedian(np.maximum(spec.diagonal(), 0.0))), float(eps), 1e-12)
    threshold = max(float(eps) * 10.0, float(boundary_tol) * scale)
    active = np.flatnonzero(np.isfinite(psi) & (psi > threshold))
    boundary_count = int(T - active.size)
    if active.size == 0:
        return _FATangentProjector(Q=Q, active_diag=active,
                                   boundary_count=boundary_count, direct=True)

    # Gram of residualized diagonal directions: M_ij=(Pperp_ij)^2.
    if active.size <= int(direct_max_traits):
        Qa = Q[active]
        Paa = np.eye(active.size, dtype=float)
        if Q.shape[1]:
            Paa -= Qa @ Qa.T
        M = Paa * Paa
        # Singularities can occur when a diagonal direction is already in the
        # low-rank tangent.  A scale-relative jitter makes the same projector
        # numerically identifiable without changing well-conditioned cases.
        diagm = np.diag(M)
        jitter = max(float(eps), 1e-12) * max(float(np.nanmax(diagm, initial=1.0)), 1.0)
        M.flat[::M.shape[0] + 1] += jitter
        try:
            cf = cho_factor(M, lower=True, check_finite=False)
        except Exception:
            cf = None
        return _FATangentProjector(Q=Q, active_diag=active, chol=cf, gram=M,
                                   boundary_count=boundary_count, direct=True)

    # For phenomes much larger than the intended ~1000-trait use case, keep
    # the solve matrix-free.  M c is evaluated through Q in O(T r^2).
    h = np.einsum('ij,ij->i', Q, Q) if Q.shape[1] else np.zeros(T)
    diagM = np.maximum((1.0 - h[active]) ** 2, max(float(eps), 1e-10))

    def mv(ca):
        """Compute mv.

        Parameters
        ----------
        ca : object (see the cited input contract)
            Context/control value read by the enclosing operation; its contract follows the explicit
            local use and the caller.

        Returns
        -------
        object
            Computed result from ``y[active]``; see the summary and the called implementation for its labeled/numerical representation.
        """
        cfull = np.zeros(T, dtype=float)
        cfull[active] = ca
        if Q.shape[1]:
            S = Q.T @ (cfull[:, None] * Q)
            pdp = np.einsum('ij,ij->i', Q @ S, Q)
            y = (1.0 - 2.0 * h) * cfull + pdp
        else:
            y = cfull
        return y[active]

    Aop = LinearOperator((active.size, active.size), matvec=mv, rmatvec=mv, dtype=float)
    Mop = LinearOperator((active.size, active.size),
                         matvec=lambda x: np.asarray(x, float) / diagM,
                         rmatvec=lambda x: np.asarray(x, float) / diagM, dtype=float)
    return _FATangentProjector(Q=Q, active_diag=active, cg_operator=Aop,
                               cg_precond=Mop, cg_rtol=cg_rtol,
                               cg_maxiter=cg_maxiter, boundary_count=boundary_count,
                               direct=False)



@dataclass
class _FATangentDerivative:
    """Jacobian/adjoint for a (possibly weighted) local FA projection.

    Constructor fields
    ------------------
    projector : _FATangentProjector
        Stored projector consumed by ``apply``/``transpose``; see those methods for the
        numerical/label contract. Required construction field.

    scale : np.ndarray
        Stored scale consumed by ``apply``/``transpose``; see those methods for the
        numerical/label contract. Required construction field.
    """
    projector: _FATangentProjector
    scale: np.ndarray

    def apply(self, V):
        """Return the apply result computed by ``_sym``.

        Parameters
        ----------
        V : array-like
            Numerical operand in ``d[:, None] * _sym(np.asarray(V, float)) * d[None, :]``. Shape
            must conform to that matrix/vector operation and the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``_sym(invd[:, None] * PH * invd[None, :])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        d = np.asarray(self.scale, dtype=float)
        invd = 1.0 / np.maximum(d, 1e-14)
        H = (d[:, None] * _sym(np.asarray(V, float))) * d[None, :]
        PH = self.projector.apply(H)
        return _sym((invd[:, None] * PH) * invd[None, :])

    def transpose(self, Z):
        # J = D^-1 P D, with D(V)=diag(d)Vdiag(d), so J' = D P D^-1.
        """Return the transpose result computed by ``_sym``.

        Parameters
        ----------
        Z : array-like
            Sample × variant numerical coding used in genotype moments. Raw inputs use biallelic
            dosage; centered/additive/dominance inputs must already follow the coding named by this
            operation. Missing entries are represented by the accompanying mask or NaN policy.

        Returns
        -------
        object
            Computed result from ``_sym(d[:, None] * PH * d[None, :])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        d = np.asarray(self.scale, dtype=float)
        invd = 1.0 / np.maximum(d, 1e-14)
        H = (invd[:, None] * _sym(np.asarray(Z, float))) * invd[None, :]
        PH = self.projector.apply(H)
        return _sym((d[:, None] * PH) * d[None, :])


def _prepare_fa_tangent_derivative(spec, *, scale=None, eps=1e-10,
                                   boundary_tol=1e-8, direct_max_traits=2200,
                                   cg_rtol=1e-9, cg_maxiter=400):
    """Prepare factor-analytic covariance tangent derivative.

    Parameters
    ----------
    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Passed to ``FactorCovarianceSpec`` as
        ``name``.

    scale : float or array-like
        Numerical scale/retention/step threshold controlling the transformation described above.
        Match vector scales to the affected axis; the exact formula and local comparisons below
        determine its admissible domain. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_prepare_fa_tangent_projector`` as
        ``eps``.

    boundary_tol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-08``. Passed to ``_prepare_fa_tangent_projector`` as
        ``boundary_tol``.

    direct_max_traits : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``2200``. Passed to ``_prepare_fa_tangent_projector`` as
        ``direct_max_traits``.

    cg_rtol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-09``. Passed to ``_prepare_fa_tangent_projector`` as ``cg_rtol``.

    cg_maxiter : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``400``. Passed to ``_prepare_fa_tangent_projector`` as ``cg_maxiter``.
    """
    d = np.ones(spec.n_traits, dtype=float) if scale is None else np.asarray(scale, dtype=float)
    # The weighted solver operates on H=D C D.  Construct that equivalent
    # factor-analytic point before preparing the Euclidean tangent projector.
    wsp = FactorCovarianceSpec(
        d[:, None] * np.asarray(spec.factor, float),
        (d*d) * np.asarray(spec.diag_specific, float),
        name=spec.name,
    )
    proj = _prepare_fa_tangent_projector(
        wsp, eps=eps, boundary_tol=boundary_tol,
        direct_max_traits=direct_max_traits, cg_rtol=cg_rtol,
        cg_maxiter=cg_maxiter,
    )
    return _FATangentDerivative(proj, d)


def _spectral_component_scales(moments, ridge=(0.0, 0.0), *, eps=1e-10):
    """Reproduce the separable trait weights used by the spectral solver.

    Parameters
    ----------
    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``(0.0, 0.0)``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_profile_component_information``
        as ``eps``.
    """
    A = np.asarray(moments['A'], dtype=float).copy()
    ridge = np.asarray(ridge, dtype=float)
    for r in range(min(len(ridge), A.shape[0])):
        if ridge[r]:
            A[r, r] += float(ridge[r])
    info = _profile_component_information(A, eps=max(float(eps)*1e-4, 1e-12))
    scales = []
    errors = []
    for r in range(A.shape[0]):
        d, err = _rank1_weight_scale(info[r], eps=max(float(eps), 1e-14))
        scales.append(d); errors.append(err)
    return scales, errors

@dataclass
class _RegularizationDerivative:
    """Local derivative of the fixed 2.9.2 covariance-regularization policy.

    Constructor fields
    ------------------
    mode : str
        Stored mode consumed by ``apply``/``transpose``; see those methods for the
        numerical/label contract. Required construction field.

    alpha : np.ndarray | float | None
        Stored alpha consumed by ``apply``; see those methods for the numerical/label contract.
        Default: ``None``.

    k_offdiag : np.ndarray | None
        Stored k offdiag consumed by ``apply``/``transpose``; see those methods for the
        numerical/label contract. Default: ``None``.

    diag_coef_left : np.ndarray | None
        Stored diag coef left consumed by ``apply``/``transpose``; see those methods for the
        numerical/label contract. Default: ``None``.

    diag_coef_right : np.ndarray | None
        Stored diag coef right consumed by ``apply``/``transpose``; see those methods for the
        numerical/label contract. Default: ``None``.

    blocks : list[np.ndarray] | None
        Stored blocks consumed by ``apply``; see those methods for the numerical/label contract.
        Default: ``None``.

    notes : tuple[str, ...]
        Stored notes supplied by the corresponding fitting/planning routine. See that routine
        for the result-axis/value contract. Default: ``()``.

    diagnostics : dict | None
        Stored diagnostics supplied by the corresponding fitting/planning routine. See that
        routine for the result-axis/value contract. Default: ``None``.
    """
    mode: str
    alpha: np.ndarray | float | None = None
    k_offdiag: np.ndarray | None = None
    diag_coef_left: np.ndarray | None = None
    diag_coef_right: np.ndarray | None = None
    blocks: list[np.ndarray] | None = None
    notes: tuple[str, ...] = ()
    diagnostics: dict | None = None

    def apply(self, V):
        """Apply the enclosing covariance/tangent transformation to the supplied operand.

        Parameters
        ----------
        V : array-like
            Numerical operand in ``a * V``. Shape must conform to that matrix/vector operation and
            the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``V``; see the summary and the called implementation for its labeled/numerical representation.
        """
        V = _sym(np.asarray(V, dtype=float))
        T = V.shape[0]
        mode = self.mode
        if mode == 'identity':
            return V
        if mode == 'scalar':
            a = float(self.alpha)
            out = a * V
            np.fill_diagonal(out, np.diag(V))
            return _sym(out)
        if mode == 'pairwise':
            A = np.asarray(self.alpha, dtype=float)
            out = A * V
            np.fill_diagonal(out, np.diag(V))
            return _sym(out)
        if mode == 'fisher_eb':
            K = np.asarray(self.k_offdiag, dtype=float)
            L = np.asarray(self.diag_coef_left, dtype=float)
            R = np.asarray(self.diag_coef_right, dtype=float)
            d = np.diag(V)
            out = K * V + L * d[:, None] + R * d[None, :]
            np.fill_diagonal(out, d)
            return _sym(out)
        if mode == 'diag':
            return np.diag(np.diag(V))
        if mode == 'blocks':
            out = np.zeros_like(V)
            for idx in self.blocks or []:
                out[np.ix_(idx, idx)] = V[np.ix_(idx, idx)]
            return _sym(out)
        return V

    def transpose(self, Z):
        """Apply the transposed local derivative map to the supplied covariance coordinates.

        Parameters
        ----------
        Z : array-like
            Sample × variant numerical coding used in genotype moments. Raw inputs use biallelic
            dosage; centered/additive/dominance inputs must already follow the coding named by this
            operation. Missing entries are represented by the accompanying mask or NaN policy.

        Returns
        -------
        object
            Computed result from ``Z``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Z = _sym(np.asarray(Z, dtype=float))
        T = Z.shape[0]
        mode = self.mode
        if mode in {'identity', 'scalar', 'pairwise', 'diag', 'blocks'}:
            return self.apply(Z)
        if mode == 'fisher_eb':
            K = np.asarray(self.k_offdiag, dtype=float)
            L = np.asarray(self.diag_coef_left, dtype=float)
            R = np.asarray(self.diag_coef_right, dtype=float)
            out = K * Z
            # Frobenius inner product on symmetric matrices counts off-diagonal
            # entries twice; hence the factor 2 in diagonal adjoint terms.
            diag = np.diag(Z).copy()
            off = Z.copy(); np.fill_diagonal(off, 0.0)
            diag += 2.0 * np.sum(off * L, axis=1)
            diag += 2.0 * np.sum(off * R, axis=0)
            np.fill_diagonal(out, diag)
            return _sym(out)
        return Z


def _regularization_derivative(spec, policy, overlap, *, component='G',
                               min_E_pair_overlap=2, eps=1e-10):
    """Derivative conditional on the already selected shrinkage policy.

    Automatic hyperparameter/rank selection uncertainty is deliberately not
    differentiated.  That distinction is reported in the analytic-SE metadata.

    Parameters
    ----------
    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity.

    policy : str
        Residual retention policy: 'diag'/'diagonal' removes off-diagonals, 'full'/'none' keeps
        them, 'scalar' uses common retention, 'pairwise'/'overlap' uses overlap-dependent
        retention, and 'fisher_eb'/'eb' empirical-Bayes correlation retention. Supported-block
        aliases follow the local policy resolver. Source-recognized literal values:
        ``auto_supported``, ``blocks``, ``legacy_supported``, ``overlap_blocks``,
        ``pairwise_eb``, ``pairwise_overlap``. These select the corresponding branches below;
        comparison evidence alone does not establish an exhaustive enum. Passed to
        ``_RegularizationDerivative`` as ``alpha``.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations. Passed to ``_RegularizationDerivative`` as ``blocks``.

    component : str
        Identifier used to select or label the relevant component, field or output quantity. It
        must match the names present in the supplied object where lookup is required. Default:
        ``'G'``.

    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``. Passed to ``_legacy._project_psd`` as ``eps``.
    """
    C = _sym(spec.materialize())
    T = C.shape[0]
    notes = []
    if component == 'G':
        galpha = policy.get('G_alpha', 1.0)
        if isinstance(galpha, dict):
            a = float(galpha.get(spec.name, galpha.get('__all__', 1.0)))
        else:
            a = float(galpha)
        return _RegularizationDerivative('identity' if a >= 1-1e-15 else 'scalar', alpha=a)

    emode = str(policy.get('E_mode', 'none')).lower()
    op = _RegularizationDerivative('identity')
    if emode == 'scalar':
        op = _RegularizationDerivative('scalar', alpha=float(policy.get('E_alpha', 1.0)))
    elif emode in {'pairwise', 'pairwise_overlap', 'overlap'}:
        strength = float(policy.get('E_strength', 0.0))
        ov = np.asarray(overlap, float)
        A = np.divide(ov, ov + strength, out=np.zeros_like(ov), where=(ov+strength)>0)
        np.fill_diagonal(A, 1.0)
        op = _RegularizationDerivative('pairwise', alpha=A,
                                       notes=('conditional on fixed pairwise shrinkage weights',))
    elif emode in {'fisher_eb', 'pairwise_eb', 'eb'}:
        ov = np.asarray(overlap, float)
        tau2 = max(float(policy.get('E_tau2', 0.0)), 0.0)
        A = np.zeros_like(ov)
        ok = ov >= 4
        sv = np.full_like(ov, np.inf)
        sv[ok] = 1.0 / np.maximum(ov[ok]-3.0, 1.0)
        if tau2 > 0:
            A[ok] = tau2 / (tau2 + sv[ok])
        np.fill_diagonal(A, 1.0)
        d = np.maximum(np.diag(C), eps); sd = np.sqrt(d)
        den = np.outer(sd, sd)
        R0 = np.clip(C / den, -1+1e-9, 1-1e-9)
        np.fill_diagonal(R0, 1.0)
        Z0 = np.arctanh(np.clip(R0, -1+1e-9, 1-1e-9))
        Rsh = np.tanh(A * Z0)
        np.fill_diagonal(Rsh, 1.0)
        _Rproj = _legacy._project_psd(_sym(Rsh), eps=max(float(eps), 1e-12))
        _rd = np.sqrt(np.maximum(np.diag(_Rproj), eps))
        _Rproj = _sym(_Rproj / np.outer(_rd, _rd))
        repair_rel = float(np.linalg.norm(_Rproj - Rsh) / max(np.linalg.norm(Rsh), 1e-30))
        K = A * (1.0 - Rsh*Rsh) / np.maximum(1.0 - R0*R0, 1e-10)
        np.fill_diagonal(K, 0.0)
        # dCsh_ij = K_ij dC_ij + b_i dC_ii + b_j dC_jj.
        L = den / (2.0 * d[:, None]) * (Rsh - R0*K)
        RR = den / (2.0 * d[None, :]) * (Rsh - R0*K)
        np.fill_diagonal(L, 0.0); np.fill_diagonal(RR, 0.0)
        op = _RegularizationDerivative(
            'fisher_eb', alpha=A, k_offdiag=K,
            diag_coef_left=L, diag_coef_right=RR,
            notes=(
                'conditional on fixed empirical-Bayes tau2/overlap weights',
                'local derivative is taken before any active nearest-PSD repair/renormalization',
            ),
            diagnostics={'psd_repair_relative_norm': repair_rel},
        )
    elif emode in {'diag', 'diagonal'}:
        op = _RegularizationDerivative('diag')
    elif emode in {'blocks', 'overlap_blocks'}:
        op = _RegularizationDerivative('blocks', blocks=_overlap_components(overlap, min_E_pair_overlap))
    elif emode in {'legacy_supported', 'auto_supported'}:
        # The legacy supported mode includes a potentially active PSD repair.
        # Use its fixed linear support mask only when it resolves to diagonal;
        # otherwise report an identity local approximation rather than silently
        # differentiating through eigenvalue clipping.
        ov = np.asarray(overlap, float)
        support = ov >= int(min_E_pair_overlap); np.fill_diagonal(support, True)
        iu = np.triu_indices_from(support, 1)
        unsupported = float(np.mean(~support[iu])) if len(iu[0]) else 0.0
        if unsupported >= 0.5:
            op = _RegularizationDerivative('diag', notes=('legacy E support resolved to diagonal',))
        else:
            op = _RegularizationDerivative('identity', notes=('legacy nearest-PSD support repair derivative approximated as identity',))

    estruct = str(policy.get('E_structure_mode', 'none')).lower()
    if estruct in {'diag', 'diagonal'}:
        return _RegularizationDerivative('diag', notes=op.notes)
    if estruct in {'blocks', 'overlap_blocks'}:
        blocks = _overlap_components(overlap, min_E_pair_overlap)
        # Composition with nonlinear fisher shrinkage is uncommon for
        # disconnected overlap.  Encode the block mask in a wrapper-like
        # derivative by retaining it in notes and apply it explicitly below.
        if op.mode == 'identity':
            return _RegularizationDerivative('blocks', blocks=blocks, notes=op.notes)
        op.notes = tuple(op.notes) + ('E overlap-block structure applied after shrinkage',)
        setattr(op, '_post_blocks', blocks)
    return op


def _reg_apply(op, V, *, transpose=False):
    """Apply the fitted residual/genetic covariance retention policy.

    Parameters
    ----------
    op : kernel/linear operator or mapping
        Prepared matrix operator exposing the multiplication methods used below; shape and
        sample order must match the right-hand side or phenotype matrix.

    V : array-like
        Numerical operand in ``np.asarray(V)[np.ix_(idx, idx)]``. Shape must conform to that
        matrix/vector operation and the enclosing prepared state.

    transpose : bool
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``False``.
    """
    blocks = getattr(op, '_post_blocks', None)
    if transpose and blocks is not None:
        z = np.zeros_like(V, dtype=float)
        for idx in blocks:
            z[np.ix_(idx, idx)] = np.asarray(V)[np.ix_(idx, idx)]
        return op.transpose(_sym(z))
    out = op.transpose(V) if transpose else op.apply(V)
    if (not transpose) and blocks is not None:
        z = np.zeros_like(out)
        for idx in blocks:
            z[np.ix_(idx, idx)] = out[np.ix_(idx, idx)]
        out = _sym(z)
    return out

def _cov_sandwich_trait(left_spec, V, right_spec):
    """Propagate moment covariance through the trait covariance estimator's local derivative.

    Parameters
    ----------
    left_spec : covariance specification or array-like
        Left/right or pre/post-regularization trait covariance used in the
        uncertainty/prediction transformation. Preserve trait order and the estimator stage
        named by this argument.

    V : array-like
        Numerical operand in ``A @ (A.T @ V @ B) @ B.T``. Shape must conform to that
        matrix/vector operation and the enclosing prepared state.

    right_spec : covariance specification or array-like
        Left/right or pre/post-regularization trait covariance used in the
        uncertainty/prediction transformation. Preserve trait order and the estimator stage
        named by this argument.
    """
    V = np.asarray(V, dtype=float)
    A = np.asarray(left_spec.factor, dtype=float)
    B = np.asarray(right_spec.factor, dtype=float)
    dl = np.asarray(left_spec.diag_specific, dtype=float)
    dr = np.asarray(right_spec.diag_specific, dtype=float)
    out = np.zeros_like(V, dtype=float)
    if A.shape[1] and B.shape[1]:
        out += A @ (A.T @ V @ B) @ B.T
    if np.any(dl) and B.shape[1]:
        out += (dl[:, None] * (V @ B)) @ B.T
    if A.shape[1] and np.any(dr):
        out += A @ (A.T @ V) * dr[None, :]
    if np.any(dl) and np.any(dr):
        out += (dl[:, None] * V) * dr[None, :]
    return out


def _subset_kernel_for_trace(grm, mask, *, kernel_rank="auto", max_full_n=2500,
                             random_state=0, dtype=np.float64):
    """Resolve K on a common-mask subset without forcing dense reconstruction.

    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components. Passed to ``LowRankKernelOperator`` as ``bulk``.

    mask : bool or numeric mask array
        Observation/eligibility mask aligned to the corresponding input axis. True/one selects
        observed or eligible entries; false/zero excludes them. A sample mask is
        one-dimensional; cell masks match the matrix and packed masks follow the packed-byte
        axis.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``LowRankKernelOperator.from_dense`` as ``random_state``.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``LowRankKernelOperator`` as
        ``dtype``.
    """
    mask = np.asarray(mask, dtype=bool)
    idx = np.flatnonzero(mask)
    if isinstance(grm, LowRankKernelOperator):
        return LowRankKernelOperator(grm.U[idx], grm.values, bulk=grm.bulk, dtype=dtype,
                                     diagnostics={**getattr(grm, "diagnostics", {}), "subset": True})
    if isinstance(grm, DenseKernelOperator):
        A = np.asarray(grm.K[np.ix_(idx, idx)], dtype=float)
    elif isinstance(grm, pd.DataFrame) or isinstance(grm, np.ndarray):
        A0 = np.asarray(grm, dtype=float)
        A = np.asarray(A0[np.ix_(idx, idx)], dtype=float)
    else:
        op = as_kernel_operator(grm, dtype=dtype)
        if isinstance(op, LowRankKernelOperator):
            return LowRankKernelOperator(op.U[idx], op.values, bulk=op.bulk, dtype=dtype,
                                         diagnostics={**getattr(op, "diagnostics", {}), "subset": True})
        A = np.asarray(op.submatrix(idx), dtype=float)
    n = A.shape[0]
    req = kernel_rank
    if isinstance(req, str) and req.lower() == "auto":
        req = "full" if n <= int(max_full_n) else min(128, n - 1)
    if req in {None, "full", False}:
        return DenseKernelOperator(A, dtype=dtype)
    return LowRankKernelOperator.from_dense(A, rank=max(1, min(int(req), n - 1)),
                                            dtype=dtype, random_state=random_state, probe_vectors=0)


def _spectral_mom_trace_tensor(grm, common_mask, *, n_probes=16, kernel_rank="auto",
                               max_full_n=2500, random_state=0):
    """Estimate the 2x2x2x2 Gaussian quadratic-form trace tensor.

    Hutchinson trace probes make this O(probes * K-matvec) and avoid any N x N
    inverse or repeated covariance fit. With a supplied LowRankKernelOperator
    this remains practical for tens of thousands of animals.

    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    common_mask : bool or numeric mask array
        Observation/eligibility mask aligned to the corresponding input axis. True/one selects
        observed or eligible entries; false/zero excludes them. A sample mask is
        one-dimensional; cell masks match the matrix and packed masks follow the packed-byte
        axis.

    n_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``16``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``. Passed to
        ``_subset_kernel_for_trace`` as ``max_full_n``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_subset_kernel_for_trace`` as ``random_state``.
    """
    op = _subset_kernel_for_trace(grm, common_mask, kernel_rank=kernel_rank,
                                  max_full_n=max_full_n, random_state=random_state)
    n = op.shape[0]
    h = max(4, int(n_probes))
    rng = np.random.default_rng(random_state)
    Z = rng.choice(np.array([-1.0, 1.0]), size=(n, h))
    def center(X):
        """Find the display center of the selected haplotype graph node.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``X - np.mean(X, axis=0, keepdims=True)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return X - np.mean(X, axis=0, keepdims=True)
    def Q(i, X):
        """Apply the captured residual/tangent projector to the numerical operand.

        Parameters
        ----------
        i : int or index array
            Local position, index selection or step used by the stated slice/iteration. Indices must
            refer to the relevant axis; slice steps must be nonzero, and count/rank uses must match
            the enclosing dimensions. Source comparisons: ``i == 0``. See the rejection/fallback
            branches for enforcement.

        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``op.matmat(X) if i == 0 else X``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return op.matmat(X) if i == 0 else X
    def C(a, X):
        """Apply the captured covariance/uncertainty map to the numerical operand.

        Parameters
        ----------
        a : array-like
            Numerical operand in ``a == 0``. Shape must conform to that matrix/vector operation and
            the enclosing prepared state. Source comparisons: ``a == 0``. See the rejection/fallback
            branches for enforcement.

        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``center(X)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        if a == 0:
            return center(op.matmat(center(X)))
        return center(X)
    operation_stage(f'analytic SE: masks/trace ({h} batched trace vectors)')
    _trace_bar = current_work()
    if _trace_bar is not None: _trace_bar.add_total(16)
    TT = np.empty((2, 2, 2, 2), dtype=float)
    for i in range(2):
        for j in range(2):
            for a in range(2):
                for b in range(2):
                    X = C(b, Z)
                    X = Q(j, X)
                    X = C(a, X)
                    X = Q(i, X)
                    TT[i, j, a, b] = float(np.mean(np.sum(Z * X, axis=0)))
                    if _trace_bar is not None: _trace_bar.update()
    return TT, {"trace_probes": h, "kernel_rank": getattr(op, "U", np.empty((n, n))).shape[1] if isinstance(op, LowRankKernelOperator) else n,
                "kernel_operator": type(op).__name__, "n_observed": n}


def _symmetric_rademacher_coordinate_probe(T, rng):
    """Random vector in an orthonormal vech basis, represented as a matrix.

    Parameters
    ----------
    T : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension. Passed to ``rng.choice`` as ``size``.

    rng : numpy.random.Generator
        Random-number generator used for draws; its current state is consumed by sampling.
    """
    Zc = np.zeros((T, T), dtype=float)
    d = rng.choice(np.array([-1.0, 1.0]), size=T)
    np.fill_diagonal(Zc, d)
    iu = np.triu_indices(T, 1)
    z = rng.choice(np.array([-1.0, 1.0]), size=len(iu[0]))
    Zc[iu] = z
    Zc[(iu[1], iu[0])] = z
    V = Zc.copy()
    V[iu] /= np.sqrt(2.0)
    V[(iu[1], iu[0])] /= np.sqrt(2.0)
    return Zc, V


def _coordinate_matrix(U):
    """Construct the symmetric trait-matrix basis element for one covariance coordinate.

    Parameters
    ----------
    U : array-like
        Numerical operand in ``U.shape[0]``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.
    """
    U = _sym(np.asarray(U, dtype=float))
    C = U.copy()
    iu = np.triu_indices(U.shape[0], 1)
    C[iu] *= np.sqrt(2.0)
    C[(iu[1], iu[0])] *= np.sqrt(2.0)
    return C


@operation_progress('analytic SE')
def spectral_mom_analytic_se(grm, traits, moments, Gspec, Espec, *,
                             n_probes=32, trace_probes=16, kernel_rank="auto",
                             max_full_n=2500, random_state=0, eps=1e-12, progress=None):
    """Scalable first-order analytic SE for strict spectral MoM G/E.

    Conditions: one GRM, common trait observation mask, fixed spectral ranks.
    The quadratic-form covariance is Gaussian analytic; animal-space traces and
    the diagonal of the projected sandwich are estimated with Hutchinson probes.
    This is *not* a bootstrap and performs no covariance refits.

    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    n_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``32``. Passed to ``masked_multi_fa_mom_analytic_se`` as ``n_probes``.

    trace_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``16``. Passed to ``_spectral_mom_trace_tensor`` as ``n_probes``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``max_full_n``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``random_state``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``masked_multi_fa_mom_analytic_se``
        as ``eps``.

    progress : bool or None
        Default None inherits enclosing covariance reporting. True enables
        named analytic phases and real completed probe counts; False is silent.

    Returns
    -------
    dict
        Result fields: ``G_se``, ``E_se``, ``rg_se``, ``h2``, ``h2_se``, ``h2_ci95``, ``method``, ``n_probes``, ``conditional_on_rank``, ``notes``. Field arrays preserve the corresponding input axis order.
    """
    operation_stage('analytic SE: masks/trace')
    Y = traits.to_numpy(float) if isinstance(traits, pd.DataFrame) else np.asarray(traits, float)
    mask = _common_trait_mask(Y)
    if mask is None:
        _kn=str(list(moments.get('kernel_names',('genetic',)))[0])
        return masked_multi_fa_mom_analytic_se(
            {_kn: grm}, traits, moments, {_kn: Gspec, 'E': Espec}, {_kn: Gspec, 'E': Espec},
            regularization_policy={'E_mode':'none','E_structure_mode':'none'},
            ridge=[0.0,0.0], n_probes=n_probes, kernel_rank=kernel_rank,
            max_full_n=max_full_n, random_state=random_state, eps=eps,
        )
    if np.asarray(Gspec.diag_specific).max(initial=0.0) > 1e-10 or np.asarray(Espec.diag_specific).max(initial=0.0) > 1e-10:
        raise ValueError("spectral analytic SE requires strict low-rank PSD specs (solver='spectral', shrink_G=shrink_E=1)")
    _ase_bar = current_work()
    if _ase_bar is not None: _ase_bar.add_total(max(8, int(n_probes)))
    A = np.asarray(moments["A"], dtype=float)
    H = _sym(A[:, :, 0, 0])
    if H.shape != (2, 2):
        raise ValueError("spectral analytic SE currently supports one genetic kernel plus E")
    try:
        Hinv = np.linalg.inv(H)
    except np.linalg.LinAlgError:
        Hinv = np.linalg.pinv(H, rcond=1e-10)
    TT, tdiag = _spectral_mom_trace_tensor(
        grm, mask, n_probes=trace_probes, kernel_rank=kernel_rank,
        max_full_n=max_full_n, random_state=random_state,
    )
    specs = [Gspec, Espec]
    T = Y.shape[1]

    def cov_theta_apply(Vlist):
        # theta = H^{-1} q; move H^{-T} through the input, apply Cov(q), then H^{-1}.
        """Apply the local covariance sandwich in free-parameter coordinates.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Hinv[d, j] * Vlist[d]``. See
            ``vigor.multivariate.spectral_mom_analytic_se.cov_theta_apply`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``U``; see the summary and the called implementation for its labeled/numerical representation.
        """
        W = []
        for j in range(2):
            Wj = np.zeros((T, T), dtype=float)
            for d in range(2):
                Wj += Hinv[d, j] * Vlist[d]
            W.append(_sym(Wj))
        Zq = []
        for i in range(2):
            Zi = np.zeros((T, T), dtype=float)
            for j in range(2):
                for a in range(2):
                    for b in range(2):
                        coef = 2.0 * TT[i, j, a, b]
                        if coef:
                            Zi += coef * _cov_sandwich_trait(specs[a], W[j], specs[b])
            Zq.append(_sym(Zi))
        U = []
        for c in range(2):
            Uc = np.zeros((T, T), dtype=float)
            for i in range(2):
                Uc += Hinv[c, i] * Zq[i]
            U.append(_sym(Uc))
        return U

    operation_stage('analytic SE: tangent prep')
    rng = np.random.default_rng(random_state + 99173)
    npr = max(8, int(n_probes))
    var_acc = [np.zeros((T, T), dtype=float) for _ in range(2)]
    cov_ts_tt = np.zeros((T, T), dtype=float)
    cov_ts_ss = np.zeros((T, T), dtype=float)
    cov_diagdiag = np.zeros((T, T), dtype=float)
    cov_GE_diag = np.zeros(T, dtype=float)
    for _probe in range(npr):
        operation_stage(f'analytic SE: probe {_probe+1}/{npr}')
        Zcoord, V = zip(*[_symmetric_rademacher_coordinate_probe(T, rng) for _c in range(2)])
        Vj = [_spectral_tangent(V[c], specs[c]) for c in range(2)]
        U = cov_theta_apply(Vj)
        U = [_spectral_tangent(U[c], specs[c]) for c in range(2)]
        Ycoord = [_coordinate_matrix(U[c]) for c in range(2)]
        for c in range(2):
            var_acc[c] += Zcoord[c] * Ycoord[c]
        # Extra covariance terms needed by the delta method for rG and h2.
        zg = Zcoord[0]; yg = Ycoord[0]
        zgd = np.diag(zg); ygd = np.diag(yg)
        cov_ts_tt += zg * ygd[:, None]
        cov_ts_ss += zg * ygd[None, :]
        cov_diagdiag += zgd[:, None] * ygd[None, :]
        cov_GE_diag += 0.5 * (np.diag(Zcoord[0]) * np.diag(Ycoord[1]) + np.diag(Zcoord[1]) * np.diag(Ycoord[0]))
        if _ase_bar is not None: _ase_bar.update()
    varcoord = [v / npr for v in var_acc]
    # Convert orthonormal vech-coordinate variances back to matrix-entry variances.
    iu = np.triu_indices(T, 1)
    var_entry = []
    for v in varcoord:
        vv = _sym(v)
        vv[iu] *= 0.5
        vv[(iu[1], iu[0])] *= 0.5
        var_entry.append(np.maximum(vv, 0.0))
    Gvar, Evar = var_entry
    Gse, Ese = np.sqrt(Gvar), np.sqrt(Evar)
    cov_ts_tt /= npr * np.sqrt(2.0)
    cov_ts_ss /= npr * np.sqrt(2.0)
    cov_diagdiag /= npr
    cov_GE_diag /= npr
    operation_stage('analytic SE: delta/rG/h2')
    G = Gspec.materialize(); E = Espec.materialize()
    dg = np.diag(G); de = np.diag(E)
    denom = np.sqrt(np.maximum(dg[:, None] * dg[None, :], eps))
    Rg = np.divide(G, denom, out=np.full_like(G, np.nan), where=denom > eps)
    rg_var = np.full((T, T), np.nan, dtype=float)
    for t in range(T):
        rg_var[t, t] = 0.0
    for t in range(T):
        for u in range(t + 1, T):
            if dg[t] <= eps or dg[u] <= eps:
                continue
            r = Rg[t, u]
            dxy = 1.0 / np.sqrt(dg[t] * dg[u])
            dtt = -r / (2.0 * dg[t]); duu = -r / (2.0 * dg[u])
            cv_xy_tt = cov_ts_tt[t, u]
            cv_xy_uu = cov_ts_ss[t, u]
            cv_tt_uu = cov_diagdiag[t, u]
            vr = (dxy*dxy*Gvar[t,u] + dtt*dtt*Gvar[t,t] + duu*duu*Gvar[u,u]
                  + 2*dxy*dtt*cv_xy_tt + 2*dxy*duu*cv_xy_uu + 2*dtt*duu*cv_tt_uu)
            rg_var[t,u] = rg_var[u,t] = max(float(vr), 0.0)
    rg_se = np.sqrt(rg_var)
    tot = dg + de
    h2 = np.divide(dg, tot, out=np.full(T, np.nan), where=tot > eps)
    dG = np.divide(de, tot*tot, out=np.zeros(T), where=tot > eps)
    dE = np.divide(-dg, tot*tot, out=np.zeros(T), where=tot > eps)
    h2_var = dG*dG*np.diag(Gvar) + dE*dE*np.diag(Evar) + 2*dG*dE*cov_GE_diag
    h2_se = np.sqrt(np.maximum(h2_var, 0.0))
    return {
        "G_se": Gse, "E_se": Ese, "rg_se": rg_se,
        "h2": h2, "h2_se": h2_se,
        "h2_ci95": np.column_stack([np.maximum(0.0, h2-1.96*h2_se), np.minimum(1.0, h2+1.96*h2_se)]),
        "method": "gaussian_mom_spectral_tangent_hutchinson",
        "n_probes": npr, **tdiag,
        "conditional_on_rank": True,
        "notes": "fixed-rank tangent-space delta method; does not include rank-selection uncertainty",
    }

@operation_progress('analytic SE')
def mom_preconstraint_analytic_se(grm, traits, moments, Gspec, Espec, *,
                                  n_probes=32, trace_probes=16, kernel_rank="auto",
                                  max_full_n=2500, random_state=0, eps=1e-12, progress=None):
    """Fast Gaussian MoM sandwich SE before the PSD/FA constraint map.

    This uses the exact two-component MoM estimating equations for one GRM and
    a shared phenotype observation mask.  Animal-space trace terms are
    estimated with Hutchinson probes, while trait-space covariance is evaluated
    using the supplied low-rank-plus-diagonal G/E specs.  No covariance model
    is refit.

    The returned SEs describe the *unconstrained/local* MoM covariance-entry
    estimator evaluated at ``Gspec``/``Espec``.  They therefore provide a fast
    large-N uncertainty approximation and a bootstrap calibration target, not a
    replacement for final constrained-estimator bootstrap uncertainty.

    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    n_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``32``.

    trace_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``16``. Passed to ``_spectral_mom_trace_tensor`` as ``n_probes``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``. Passed to
        ``_spectral_mom_trace_tensor`` as ``max_full_n``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_spectral_mom_trace_tensor`` as ``random_state``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``np.divide`` as ``where``.

    progress : bool or None
        Default None inherits enclosing covariance reporting. True enables
        named analytic phases and real completed probe counts; False is silent.

    Returns
    -------
    dict
        Result fields: ``G_se``, ``E_se``, ``rg_se``, ``h2``, ``h2_se``, ``h2_ci95``, ``G_variance_ci95``, ``E_variance_ci95``, ``rg_ci95_low``, ``rg_ci95_high``, ``method``, ``n_probes``, ``conditional_on_rank``, ``constraint_note``. Field arrays preserve the corresponding input axis order.
    """
    operation_stage('analytic SE: masks/trace')
    Y = traits.to_numpy(float) if isinstance(traits, pd.DataFrame) else np.asarray(traits, float)
    mask = _common_trait_mask(Y)
    if mask is None:
        raise ValueError("pre-constraint analytic MoM SE currently requires all traits to share the same observation mask")
    _ase_bar = current_work()
    if _ase_bar is not None: _ase_bar.add_total(max(8, int(n_probes)))
    A = np.asarray(moments["A"], dtype=float)
    H = _sym(A[:, :, 0, 0])
    if H.shape != (2, 2):
        raise ValueError("pre-constraint analytic MoM SE currently supports one genetic kernel plus E")
    try:
        Hinv = np.linalg.inv(H)
    except np.linalg.LinAlgError:
        Hinv = np.linalg.pinv(H, rcond=1e-10)
    TT, tdiag = _spectral_mom_trace_tensor(
        grm, mask, n_probes=trace_probes, kernel_rank=kernel_rank,
        max_full_n=max_full_n, random_state=random_state,
    )
    specs = [Gspec, Espec]
    T = Y.shape[1]

    def cov_theta_apply(Vlist):
        """Apply the local covariance sandwich in free-parameter coordinates.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Hinv[d, j] * Vlist[d]``. See
            ``vigor.multivariate.mom_preconstraint_analytic_se.cov_theta_apply`` and its caller for
            the scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``U``; see the summary and the called implementation for its labeled/numerical representation.
        """
        W = []
        for j in range(2):
            Wj = np.zeros((T, T), dtype=float)
            for d in range(2):
                Wj += Hinv[d, j] * Vlist[d]
            W.append(_sym(Wj))
        Zq = []
        for i in range(2):
            Zi = np.zeros((T, T), dtype=float)
            for j in range(2):
                for a in range(2):
                    for b in range(2):
                        coef = 2.0 * TT[i, j, a, b]
                        if coef:
                            Zi += coef * _cov_sandwich_trait(specs[a], W[j], specs[b])
            Zq.append(_sym(Zi))
        U = []
        for c in range(2):
            Uc = np.zeros((T, T), dtype=float)
            for i in range(2):
                Uc += Hinv[c, i] * Zq[i]
            U.append(_sym(Uc))
        return U

    rng = np.random.default_rng(random_state + 190237)
    npr = max(8, int(n_probes))
    var_acc = [np.zeros((T, T), dtype=float) for _ in range(2)]
    cov_ts_tt = np.zeros((T, T), dtype=float)
    cov_ts_ss = np.zeros((T, T), dtype=float)
    cov_diagdiag = np.zeros((T, T), dtype=float)
    cov_GE_diag = np.zeros(T, dtype=float)
    for _probe in range(npr):
        operation_stage(f'analytic SE: probe {_probe+1}/{npr}')
        Zcoord, V = zip(*[_symmetric_rademacher_coordinate_probe(T, rng) for _c in range(2)])
        U = cov_theta_apply(list(V))
        Ycoord = [_coordinate_matrix(U[c]) for c in range(2)]
        for c in range(2):
            var_acc[c] += Zcoord[c] * Ycoord[c]
        zg = Zcoord[0]; yg = Ycoord[0]
        zgd = np.diag(zg); ygd = np.diag(yg)
        cov_ts_tt += zg * ygd[:, None]
        cov_ts_ss += zg * ygd[None, :]
        cov_diagdiag += zgd[:, None] * ygd[None, :]
        cov_GE_diag += 0.5 * (np.diag(Zcoord[0]) * np.diag(Ycoord[1]) +
                              np.diag(Zcoord[1]) * np.diag(Ycoord[0]))
        if _ase_bar is not None: _ase_bar.update()
    varcoord = [v / npr for v in var_acc]
    iu = np.triu_indices(T, 1)
    var_entry = []
    for v in varcoord:
        vv = _sym(v)
        vv[iu] *= 0.5
        vv[(iu[1], iu[0])] *= 0.5
        var_entry.append(np.maximum(vv, 0.0))
    Gvar, Evar = var_entry
    Gse, Ese = np.sqrt(Gvar), np.sqrt(Evar)
    cov_ts_tt /= npr * np.sqrt(2.0)
    cov_ts_ss /= npr * np.sqrt(2.0)
    cov_diagdiag /= npr
    cov_GE_diag /= npr

    operation_stage('analytic SE: delta/rG/h2')
    G = Gspec.materialize(); E = Espec.materialize()
    dg = np.diag(G); de = np.diag(E)
    denom = np.sqrt(np.maximum(dg[:, None] * dg[None, :], eps))
    Rg = np.divide(G, denom, out=np.full_like(G, np.nan), where=denom > eps)
    rg_var = np.full((T, T), np.nan, dtype=float)
    np.fill_diagonal(rg_var, 0.0)
    for t in range(T):
        for u in range(t + 1, T):
            if dg[t] <= eps or dg[u] <= eps:
                continue
            r = Rg[t, u]
            dxy = 1.0 / np.sqrt(dg[t] * dg[u])
            dtt = -r / (2.0 * dg[t]); duu = -r / (2.0 * dg[u])
            vr = (dxy*dxy*Gvar[t,u] + dtt*dtt*Gvar[t,t] + duu*duu*Gvar[u,u]
                  + 2*dxy*dtt*cov_ts_tt[t,u] + 2*dxy*duu*cov_ts_ss[t,u]
                  + 2*dtt*duu*cov_diagdiag[t,u])
            rg_var[t,u] = rg_var[u,t] = max(float(vr), 0.0)
    rg_se = np.sqrt(rg_var)

    tot = dg + de
    h2 = np.divide(dg, tot, out=np.full(T, np.nan), where=tot > eps)
    dG = np.divide(de, tot*tot, out=np.zeros(T), where=tot > eps)
    dE = np.divide(-dg, tot*tot, out=np.zeros(T), where=tot > eps)
    h2_var = dG*dG*np.diag(Gvar) + dE*dE*np.diag(Evar) + 2*dG*dE*cov_GE_diag
    h2_se = np.sqrt(np.maximum(h2_var, 0.0))

    z95 = 1.959963984540054
    Gv_ci = np.column_stack([np.maximum(0.0, dg-z95*np.diag(Gse)), dg+z95*np.diag(Gse)])
    Ev_ci = np.column_stack([np.maximum(0.0, de-z95*np.diag(Ese)), de+z95*np.diag(Ese)])
    rg_lo = np.full_like(Rg, np.nan); rg_hi = np.full_like(Rg, np.nan)
    for t in range(T):
        rg_lo[t,t] = rg_hi[t,t] = 1.0
        for u in range(t+1, T):
            r = float(np.clip(Rg[t,u], -1.0+1e-10, 1.0-1e-10))
            sr = float(rg_se[t,u])
            if not np.isfinite(sr):
                continue
            sez = sr / max(1.0-r*r, 1e-10)
            zl, zh = np.arctanh(r) - z95*sez, np.arctanh(r) + z95*sez
            lo, hi = np.tanh(zl), np.tanh(zh)
            rg_lo[t,u] = rg_lo[u,t] = lo
            rg_hi[t,u] = rg_hi[u,t] = hi
    return {
        "G_se": Gse, "E_se": Ese, "rg_se": rg_se,
        "h2": h2, "h2_se": h2_se,
        "h2_ci95": np.column_stack([np.maximum(0.0, h2-z95*h2_se), np.minimum(1.0, h2+z95*h2_se)]),
        "G_variance_ci95": Gv_ci, "E_variance_ci95": Ev_ci,
        "rg_ci95_low": rg_lo, "rg_ci95_high": rg_hi,
        "method": "gaussian_mom_preconstraint_hutchinson",
        "n_probes": npr, **tdiag,
        "conditional_on_rank": False,
        "constraint_note": (
            "SEs are for the unconstrained/local MoM covariance-entry estimator evaluated at the fitted G/E. "
            "They do not include the nonlinear PSD/FA projection, regularization-selection, or rank-selection uncertainty; "
            "use percentile bootstrap intervals for final constrained-estimator inference."
        ),
    }


def _analytic_delta_summaries(G, E, Gvar, Evar, cov_ts_tt, cov_ts_ss,
                              cov_diagdiag, cov_GE_diag, *, eps=1e-12,
                              ci_level=0.95):
    """Derived rG/h2 uncertainty and bounded delta-method intervals.

    Parameters
    ----------
    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result. Passed to ``np.divide`` as ``out``.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance.

    Gvar : array-like
        Genetic correlation or genetic/residual marginal variance quantity for the indicated
        component. Correlations align trait pairs; marginal variances align trait order and must
        support the boundary-aware transformation.

    Evar : array-like
        Genetic correlation or genetic/residual marginal variance quantity for the indicated
        component. Correlations align trait pairs; marginal variances align trait order and must
        support the boundary-aware transformation.

    cov_ts_tt : object (see the cited input contract)
        Input for the operation ``dxy * dxy * Gvar[t, u] + dtt * dtt * Gvar[t, t] + duu * duu *
        Gvar[u, u] + 2 * dxy * dtt * cov_ts_tt[t, u] + 2 * dxy * duu * cov_ts_ss[t, u] + 2 * dtt
        * duu * cov_diagdiag[t, u]``. See ``vigor.multivariate._analytic_delta_summaries`` and
        its caller for the scientific representation; the shown operation constrains the
        required type/shape.

    cov_ts_ss : object (see the cited input contract)
        Input for the operation ``dxy * dxy * Gvar[t, u] + dtt * dtt * Gvar[t, t] + duu * duu *
        Gvar[u, u] + 2 * dxy * dtt * cov_ts_tt[t, u] + 2 * dxy * duu * cov_ts_ss[t, u] + 2 * dtt
        * duu * cov_diagdiag[t, u]``. See ``vigor.multivariate._analytic_delta_summaries`` and
        its caller for the scientific representation; the shown operation constrains the
        required type/shape.

    cov_diagdiag : object (see the cited input contract)
        Input for the operation ``dxy * dxy * Gvar[t, u] + dtt * dtt * Gvar[t, t] + duu * duu *
        Gvar[u, u] + 2 * dxy * dtt * cov_ts_tt[t, u] + 2 * dxy * duu * cov_ts_ss[t, u] + 2 * dtt
        * duu * cov_diagdiag[t, u]``. See ``vigor.multivariate._analytic_delta_summaries`` and
        its caller for the scientific representation; the shown operation constrains the
        required type/shape.

    cov_GE_diag : array-like or numeric scalar
        Input for the operation ``dG * dG * np.diag(Gvar) + dE * dE * np.diag(Evar) + 2 * dG *
        dE * cov_GE_diag``. See ``vigor.multivariate._analytic_delta_summaries`` and its caller
        for the scientific representation; the shown operation constrains the required
        type/shape.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``np.divide`` as ``where``.

    ci_level : float
        Posterior/analytical interval coverage probability, strictly between zero and one; the
        routine determines whether intervals use posterior quantiles or a normal approximation.
        Default: ``0.95``.
    """
    from scipy.stats import norm as _norm
    G = _sym(np.asarray(G, float)); E = _sym(np.asarray(E, float))
    Gvar = np.maximum(_sym(np.asarray(Gvar, float)), 0.0)
    Evar = np.maximum(_sym(np.asarray(Evar, float)), 0.0)
    Gse = np.sqrt(Gvar); Ese = np.sqrt(Evar)
    T = G.shape[0]
    dg = np.maximum(np.diag(G), 0.0); de = np.maximum(np.diag(E), 0.0)
    denom = np.sqrt(np.maximum(dg[:, None] * dg[None, :], eps))
    Rg = np.divide(G, denom, out=np.full_like(G, np.nan), where=denom > eps)
    rg_var = np.full((T, T), np.nan, dtype=float)
    np.fill_diagonal(rg_var, 0.0)
    for t in range(T):
        for u in range(t + 1, T):
            if dg[t] <= eps or dg[u] <= eps:
                continue
            r = float(Rg[t, u])
            dxy = 1.0 / np.sqrt(dg[t] * dg[u])
            dtt = -r / (2.0 * dg[t]); duu = -r / (2.0 * dg[u])
            vr = (dxy*dxy*Gvar[t,u] + dtt*dtt*Gvar[t,t] + duu*duu*Gvar[u,u]
                  + 2*dxy*dtt*cov_ts_tt[t,u] + 2*dxy*duu*cov_ts_ss[t,u]
                  + 2*dtt*duu*cov_diagdiag[t,u])
            rg_var[t,u] = rg_var[u,t] = max(float(vr), 0.0)
    rg_se = np.sqrt(rg_var)

    total = dg + de
    h2 = np.divide(dg, total, out=np.full(T, np.nan), where=total > eps)
    dG = np.divide(de, total*total, out=np.zeros(T), where=total > eps)
    dE = np.divide(-dg, total*total, out=np.zeros(T), where=total > eps)
    h2_var = dG*dG*np.diag(Gvar) + dE*dE*np.diag(Evar) + 2*dG*dE*cov_GE_diag
    h2_se = np.sqrt(np.maximum(h2_var, 0.0))

    alpha = 1.0 - float(ci_level)
    zcrit = float(_norm.ppf(1.0 - alpha/2.0))

    # Positive variance-component intervals on the log scale.  Near zero,
    # retain 0 as the natural boundary and use a one-sided normal upper scale.
    def positive_ci(v, s):
        """Return the positive confidence interval result computed by ``np.column_stack``.

        Parameters
        ----------
        v : array-like
            Numerical operand in ``np.isfinite(v) & np.isfinite(s) & (v > eps)``. Shape must conform
            to that matrix/vector operation and the enclosing prepared state.

        s : array-like
            Numerical operand in ``np.isfinite(v) & np.isfinite(s) & (v > eps)``. Shape must conform
            to that matrix/vector operation and the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``np.column_stack([lo, hi])``; see the summary and the called implementation for its labeled/numerical representation.
        """
        v = np.asarray(v, float); s = np.asarray(s, float)
        lo = np.zeros_like(v); hi = np.zeros_like(v)
        good = np.isfinite(v) & np.isfinite(s) & (v > eps)
        slog = np.zeros_like(v)
        slog[good] = s[good] / np.maximum(v[good], eps)
        lo[good] = np.exp(np.log(v[good]) - zcrit*slog[good])
        hi[good] = np.exp(np.log(v[good]) + zcrit*slog[good])
        edge = np.isfinite(v) & np.isfinite(s) & ~good
        hi[edge] = np.maximum(0.0, v[edge] + zcrit*s[edge])
        lo[~np.isfinite(v) | ~np.isfinite(s)] = np.nan
        hi[~np.isfinite(v) | ~np.isfinite(s)] = np.nan
        return np.column_stack([lo, hi])

    Gv_ci = positive_ci(dg, np.diag(Gse))
    Ev_ci = positive_ci(de, np.diag(Ese))

    # Fisher-z intervals stay inside [-1,1].
    rg_lo = np.full_like(Rg, np.nan); rg_hi = np.full_like(Rg, np.nan)
    for t in range(T):
        rg_lo[t,t] = rg_hi[t,t] = 1.0
        for u in range(t+1, T):
            r = float(np.clip(Rg[t,u], -1.0+1e-10, 1.0-1e-10))
            sr = float(rg_se[t,u])
            if not np.isfinite(sr):
                continue
            sez = sr / max(1.0-r*r, 1e-10)
            zz = np.arctanh(r)
            lo, hi = np.tanh(zz-zcrit*sez), np.tanh(zz+zcrit*sez)
            rg_lo[t,u] = rg_lo[u,t] = lo
            rg_hi[t,u] = rg_hi[u,t] = hi

    # h2 intervals on logit scale stay inside [0,1].
    h2_lo = np.full(T, np.nan); h2_hi = np.full(T, np.nan)
    for i, (h, sh) in enumerate(zip(h2, h2_se)):
        if not (np.isfinite(h) and np.isfinite(sh)):
            continue
        hc = float(np.clip(h, 1e-10, 1.0-1e-10))
        slogit = sh / max(hc*(1.0-hc), 1e-10)
        eta = np.log(hc/(1.0-hc))
        a, b = eta-zcrit*slogit, eta+zcrit*slogit
        h2_lo[i] = 1.0/(1.0+np.exp(-a))
        h2_hi[i] = 1.0/(1.0+np.exp(-b))

    return {
        'G_se': Gse, 'E_se': Ese, 'rg_se': rg_se,
        'G_variance_se': np.diag(Gse).copy(),
        'E_variance_se': np.diag(Ese).copy(),
        'h2': h2, 'h2_se': h2_se,
        'h2_ci95': np.column_stack([h2_lo, h2_hi]),
        'G_variance_ci95': Gv_ci, 'E_variance_ci95': Ev_ci,
        'rg_ci95_low': rg_lo, 'rg_ci95_high': rg_hi,
        'cov_GE_diag': np.asarray(cov_GE_diag, float),
        'ci_level': float(ci_level),
    }


@operation_progress('analytic SE')
def fa_mom_analytic_se(grm, traits, moments, raw_Gspec, raw_Espec,
                       final_Gspec=None, final_Espec=None, *,
                       regularization_policy=None, overlap=None,
                       min_E_pair_overlap=2, ridge_G=0.0, ridge_E=0.0,
                       spectral_weighting='rank1', use_spectral_weights=False,
                       n_probes=32, trace_probes=16, kernel_rank='auto',
                       max_full_n=2500, random_state=0, eps=1e-12,
                       fa_boundary_tol=1e-8, fa_direct_max_traits=2200,
                       fa_cg_rtol=1e-9, fa_cg_maxiter=400,
                       ci_level=0.95, progress=None):
    """Final fixed-rank PSD/FA analytic SE via tangent-space sandwich.

    This is the VIGOR 2.9.2 primary large-phenome uncertainty path.  It uses
    the Gaussian covariance of the MoM quadratic statistics, then propagates it
    through the local tangent of ``L L' + diag(Psi)`` and through the fixed
    covariance-regularization policy.  Hutchinson probes estimate only the
    required diagonal/cross-diagonal entries of the resulting covariance
    operator; no bootstrap covariance refits and no factor-parameter Hessian
    are formed.

    A common observation mask uses the fast separable 2.8 MoM trace derivation.
    With trait-specific missingness, 2.9.2 automatically switches to the
    fixed-mask Gaussian moment-probe sandwich while preserving the pair-specific
    MoM systems. Rank selection and automatic regularization hyperparameters are
    treated as fixed; bootstrap remains useful for uncertainty in those choices.

    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    raw_Gspec : covariance specification or array-like
        Left/right or pre/post-regularization trait covariance used in the
        uncertainty/prediction transformation. Preserve trait order and the estimator stage
        named by this argument.

    raw_Espec : covariance specification or array-like
        Left/right or pre/post-regularization trait covariance used in the
        uncertainty/prediction transformation. Preserve trait order and the estimator stage
        named by this argument.

    final_Gspec : covariance specification or array-like
        Left/right or pre/post-regularization trait covariance used in the
        uncertainty/prediction transformation. Preserve trait order and the estimator stage
        named by this argument. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    final_Espec : covariance specification or array-like
        Left/right or pre/post-regularization trait covariance used in the
        uncertainty/prediction transformation. Preserve trait order and the estimator stage
        named by this argument. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    regularization_policy : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``regularization_policy``.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``overlap``.

    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``.

    ridge_G : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``0.0``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``ridge``.

    ridge_E : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``0.0``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``ridge``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    use_spectral_weights : bool
        Input supplied to ``masked_multi_fa_mom_analytic_se`` as ``use_spectral_weights``. See
        that callable's documented ``use_spectral_weights`` contract for its type, alignment and
        value domain. This wrapper retains that contract. Default: ``False``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``use_spectral_weights``.

    n_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``32``. Passed to ``masked_multi_fa_mom_analytic_se`` as ``n_probes``.

    trace_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``16``. Passed to ``_spectral_mom_trace_tensor`` as ``n_probes``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``max_full_n``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``random_state``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``masked_multi_fa_mom_analytic_se``
        as ``eps``.

    fa_boundary_tol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-08``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``fa_boundary_tol``.

    fa_direct_max_traits : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``2200``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``fa_direct_max_traits``.

    fa_cg_rtol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-09``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``fa_cg_rtol``.

    fa_cg_maxiter : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``400``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``fa_cg_maxiter``.

    ci_level : float
        Posterior/analytical interval coverage probability, strictly between zero and one; the
        routine determines whether intervals use posterior quantiles or a normal approximation.
        Default: ``0.95``. Passed to ``masked_multi_fa_mom_analytic_se`` as ``ci_level``.

    progress : bool or None
        Default None inherits enclosing covariance reporting. True enables
        named analytic phases and real completed probe counts; False is silent.

    Returns
    -------
    object
        Computed result from ``summary``; see the summary and the called implementation for its labeled/numerical representation.
    """
    operation_stage('analytic SE: masks/trace')
    Y = traits.to_numpy(float) if isinstance(traits, pd.DataFrame) else np.asarray(traits, float)
    mask = _common_trait_mask(Y)
    if mask is None:
        _kn=str(list(moments.get('kernel_names',('genetic',)))[0])
        return masked_multi_fa_mom_analytic_se(
            {_kn: grm}, traits, moments,
            {_kn: raw_Gspec, 'E': raw_Espec},
            {_kn: (raw_Gspec if final_Gspec is None else final_Gspec),
             'E': (raw_Espec if final_Espec is None else final_Espec)},
            regularization_policy=regularization_policy, overlap=overlap,
            min_E_pair_overlap=min_E_pair_overlap, ridge=[float(ridge_G), float(ridge_E)],
            spectral_weighting=spectral_weighting, use_spectral_weights=use_spectral_weights,
            n_probes=n_probes, kernel_rank=kernel_rank, max_full_n=max_full_n,
            random_state=random_state, eps=eps, fa_boundary_tol=fa_boundary_tol,
            fa_direct_max_traits=fa_direct_max_traits, fa_cg_rtol=fa_cg_rtol,
            fa_cg_maxiter=fa_cg_maxiter, ci_level=ci_level,
        )
    _ase_bar = current_work()
    if _ase_bar is not None: _ase_bar.add_total(max(8, int(n_probes)))
    A = np.asarray(moments['A'], dtype=float)
    H = _sym(A[:, :, 0, 0])
    if H.shape != (2, 2):
        raise ValueError('final FA analytic SE currently supports one genetic kernel plus E')
    Hfit = H.copy()
    Hfit[0,0] += float(ridge_G)
    Hfit[1,1] += float(ridge_E)
    try:
        Hinv = np.linalg.inv(Hfit)
    except np.linalg.LinAlgError:
        Hinv = np.linalg.pinv(Hfit, rcond=1e-10)

    TT, tdiag = _spectral_mom_trace_tensor(
        grm, mask, n_probes=trace_probes, kernel_rank=kernel_rank,
        max_full_n=max_full_n, random_state=random_state,
    )
    final_Gspec = raw_Gspec if final_Gspec is None else final_Gspec
    final_Espec = raw_Espec if final_Espec is None else final_Espec
    model_specs = [final_Gspec, final_Espec]
    T = Y.shape[1]

    scales = [np.ones(T), np.ones(T)]
    weight_errors = [np.nan, np.nan]
    if use_spectral_weights and str(spectral_weighting).lower() in {'rank1','separable','information'}:
        try:
            scales, weight_errors = _spectral_component_scales(
                moments, ridge=(ridge_G, ridge_E), eps=max(float(eps), 1e-12)
            )
        except Exception:
            scales = [np.ones(T), np.ones(T)]

    operation_stage('analytic SE: tangent prep')
    tg = _prepare_fa_tangent_derivative(
        raw_Gspec, scale=scales[0], eps=max(float(eps),1e-12),
        boundary_tol=fa_boundary_tol, direct_max_traits=fa_direct_max_traits,
        cg_rtol=fa_cg_rtol, cg_maxiter=fa_cg_maxiter,
    )
    te = _prepare_fa_tangent_derivative(
        raw_Espec, scale=scales[1], eps=max(float(eps),1e-12),
        boundary_tol=fa_boundary_tol, direct_max_traits=fa_direct_max_traits,
        cg_rtol=fa_cg_rtol, cg_maxiter=fa_cg_maxiter,
    )
    pol = {} if regularization_policy is None else regularization_policy
    ov = np.full((T,T), Y.shape[0], dtype=float) if overlap is None else np.asarray(overlap, float)
    rgop = _regularization_derivative(raw_Gspec, pol, ov, component='G',
                                      min_E_pair_overlap=min_E_pair_overlap, eps=eps)
    reop = _regularization_derivative(raw_Espec, pol, ov, component='E',
                                      min_E_pair_overlap=min_E_pair_overlap, eps=eps)
    # Pair-specific E shrinkage is projected back into the requested FA rank.
    # Propagate the local sandwich through that final FA projection as well;
    # otherwise analytic SEs would correspond to the full-rank shrinkage target
    # rather than to the actual rank-preserving covariance used by mvBLUP.
    e_rank_preserve = bool(pol.get('E_rank_preserve', False)) and str(pol.get('E_mode', 'none')).lower() in {
        'pairwise', 'pairwise_overlap', 'overlap', 'fisher_eb', 'pairwise_eb', 'eb'
    } and final_Espec.rank < final_Espec.n_traits
    te_post = (_prepare_fa_tangent_derivative(
        final_Espec, scale=np.ones(T), eps=max(float(eps),1e-12),
        boundary_tol=fa_boundary_tol, direct_max_traits=fa_direct_max_traits,
        cg_rtol=fa_cg_rtol, cg_maxiter=fa_cg_maxiter,
    ) if e_rank_preserve else None)

    def j_transpose(Vlist):
        """Map covariance-coordinate perturbations back through the transpose Jacobian.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Vlist[1]``. See
            ``vigor.multivariate.fa_mom_analytic_se.j_transpose`` and its caller for the scientific
            representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``[tg.transpose(_reg_apply(rgop, Vlist[0], transpose=True)), te.transpose(_reg_apply(reop, eback, transpose=True))]``; see the summary and the called implementation for its labeled/numerical representation.
        """
        eback = te_post.transpose(Vlist[1]) if te_post is not None else Vlist[1]
        return [
            tg.transpose(_reg_apply(rgop, Vlist[0], transpose=True)),
            te.transpose(_reg_apply(reop, eback, transpose=True)),
        ]

    def j_apply(Vlist):
        """Map free-parameter perturbations into covariance-coordinate changes.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Vlist[1]``. See
            ``vigor.multivariate.fa_mom_analytic_se.j_apply`` and its caller for the scientific
            representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``[_reg_apply(rgop, tg.apply(Vlist[0]), transpose=False), efwd]``; see the summary and the called implementation for its labeled/numerical representation.
        """
        efwd = _reg_apply(reop, te.apply(Vlist[1]), transpose=False)
        if te_post is not None:
            efwd = te_post.apply(efwd)
        return [
            _reg_apply(rgop, tg.apply(Vlist[0]), transpose=False),
            efwd,
        ]

    def cov_raw_apply(Vlist):
        # theta=(H+ridge)^-1 q.  Move the right inverse through the input,
        # apply Cov(q), then the left inverse.
        """Apply the unconstrained moment-covariance operator to a coordinate vector.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Hinv[d, j] * Vlist[d]``. See
            ``vigor.multivariate.fa_mom_analytic_se.cov_raw_apply`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``U``; see the summary and the called implementation for its labeled/numerical representation.
        """
        W = []
        for j in range(2):
            Wj = np.zeros((T,T), dtype=float)
            for d in range(2):
                Wj += Hinv[d,j] * Vlist[d]
            W.append(_sym(Wj))
        Zq = []
        for i in range(2):
            Zi = np.zeros((T,T), dtype=float)
            for j in range(2):
                for a in range(2):
                    for b in range(2):
                        coef = 2.0 * TT[i,j,a,b]
                        if coef:
                            Zi += coef * _cov_sandwich_trait(model_specs[a], W[j], model_specs[b])
            Zq.append(_sym(Zi))
        U=[]
        for c in range(2):
            Uc=np.zeros((T,T),dtype=float)
            for i in range(2):
                Uc += Hinv[c,i] * Zq[i]
            U.append(_sym(Uc))
        return U

    def cov_final_apply(Vlist):
        """Apply the final rank/support-conditioned covariance uncertainty operator.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``j_apply(cov_raw_apply(j_transpose(Vlist)))``. See
            ``vigor.multivariate.fa_mom_analytic_se.cov_final_apply`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``j_apply(cov_raw_apply(j_transpose(Vlist)))``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return j_apply(cov_raw_apply(j_transpose(Vlist)))

    rng = np.random.default_rng(int(random_state) + 284917)
    npr = max(8, int(n_probes))
    var_acc = [np.zeros((T,T), dtype=float) for _ in range(2)]
    cov_ts_tt = np.zeros((T,T), dtype=float)
    cov_ts_ss = np.zeros((T,T), dtype=float)
    cov_diagdiag = np.zeros((T,T), dtype=float)
    cov_GE_diag = np.zeros(T, dtype=float)
    for _probe in range(npr):
        operation_stage(f'analytic SE: probe {_probe+1}/{npr}')
        Zcoord, V = zip(*[_symmetric_rademacher_coordinate_probe(T, rng) for _c in range(2)])
        U = cov_final_apply(list(V))
        Ycoord = [_coordinate_matrix(U[c]) for c in range(2)]
        for c in range(2):
            var_acc[c] += Zcoord[c] * Ycoord[c]
        zg = Zcoord[0]; yg = Ycoord[0]
        zgd = np.diag(zg); ygd = np.diag(yg)
        cov_ts_tt += zg * ygd[:,None]
        cov_ts_ss += zg * ygd[None,:]
        cov_diagdiag += zgd[:,None] * ygd[None,:]
        cov_GE_diag += 0.5 * (np.diag(Zcoord[0])*np.diag(Ycoord[1]) +
                              np.diag(Zcoord[1])*np.diag(Ycoord[0]))
        if _ase_bar is not None: _ase_bar.update()
    varcoord = [v/npr for v in var_acc]
    iu = np.triu_indices(T,1)
    var_entry=[]
    for v in varcoord:
        vv=_sym(v)
        vv[iu] *= 0.5; vv[(iu[1],iu[0])] *= 0.5
        var_entry.append(np.maximum(vv,0.0))
    Gvar,Evar=var_entry
    cov_ts_tt /= npr*np.sqrt(2.0)
    cov_ts_ss /= npr*np.sqrt(2.0)
    cov_diagdiag /= npr
    cov_GE_diag /= npr

    operation_stage('analytic SE: delta/rG/h2')
    summary = _analytic_delta_summaries(
        final_Gspec.materialize(), final_Espec.materialize(), Gvar, Evar,
        cov_ts_tt, cov_ts_ss, cov_diagdiag, cov_GE_diag,
        eps=eps, ci_level=ci_level,
    )
    summary.update({
        'method': 'gaussian_mom_final_fa_tangent_hutchinson',
        'n_probes': npr, **tdiag,
        'conditional_on_rank': True,
        'conditional_on_regularization_policy': True,
        'G_fa_boundary_count': int(tg.projector.boundary_count),
        'E_fa_boundary_count': int(te.projector.boundary_count),
        'G_tangent_rank': int(tg.projector.rank),
        'E_tangent_rank': int(te.projector.rank),
        'tangent_solver_G': 'direct' if tg.projector.direct else 'cg',
        'tangent_solver_E': 'direct' if te.projector.direct else 'cg',
        'spectral_weight_rank1_error_G': float(weight_errors[0]) if np.isfinite(weight_errors[0]) else np.nan,
        'spectral_weight_rank1_error_E': float(weight_errors[1]) if np.isfinite(weight_errors[1]) else np.nan,
        'regularization_notes': tuple(rgop.notes) + tuple(reop.notes) + ((
            'pair-specific E shrinkage projected back into fixed-rank FA tangent',
        ) if te_post is not None else ()),
        'regularization_psd_repair_relative_norm': (
            np.nan if not reop.diagnostics else float(reop.diagnostics.get('psd_repair_relative_norm', np.nan))
        ),
        'constraint_note': (
            'Final fixed-rank PSD/FA local sandwich. Rank choice and automatic shrinkage hyperparameters are held fixed; '
            'near-boundary Psi directions are treated as active constraints. Bootstrap remains appropriate for selection uncertainty.'
        ),
    })
    return summary


def _multi_mom_trace_tensor(kernels, common_mask, *, n_probes=16,
                            kernel_rank="auto", max_full_n=2500,
                            random_state=0):
    """Gaussian quadratic-form trace tensor for q kernels plus residual I.

    For the joint MoM system with coefficient/moment operators
    ``(K_1, ..., K_q, I)``, this estimates

        tr(Q_i C_a Q_j C_b)

    on the common observed-animal subspace. ``C_a`` uses the same centered
    covariance operator as the phenotype model.  The result has shape
    ``(p,p,p,p)`` with ``p=q+1`` and is the animal-space part of the exact
    Gaussian covariance of the multivariate quadratic moments.

    The calculation is matrix-free when kernel operators are supplied and uses
    Hutchinson probes only for animal-space traces; trait-space propagation is
    analytic/linear conditional on the fitted ranks and regularization policy.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    common_mask : bool or numeric mask array
        Observation/eligibility mask aligned to the corresponding input axis. True/one selects
        observed or eligible entries; false/zero excludes them. A sample mask is
        one-dimensional; cell masks match the matrix and packed masks follow the packed-byte
        axis.

    n_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``16``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``. Passed to
        ``_subset_kernel_for_trace`` as ``max_full_n``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_subset_kernel_for_trace`` as ``random_state``.
    """
    mask=np.asarray(common_mask,dtype=bool)
    names=list(kernels)
    ops=[]
    for k,name in enumerate(names):
        ops.append(_subset_kernel_for_trace(
            kernels[name], mask, kernel_rank=kernel_rank,
            max_full_n=max_full_n, random_state=int(random_state)+37*k,
        ))
    n=int(mask.sum()); p=len(ops)+1
    h=max(4,int(n_probes)); rng=np.random.default_rng(random_state)
    Z=rng.choice(np.array([-1.0,1.0]),size=(n,h))

    def center(X):
        """Find the display center of the selected haplotype graph node.

        Parameters
        ----------
        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``X - np.mean(X, axis=0, keepdims=True)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return X-np.mean(X,axis=0,keepdims=True)
    def qapply(i,X):
        """Apply the enclosing covariance projector to one uncertainty/probe vector.

        Parameters
        ----------
        i : int or index array
            Local position, index selection or step used by the stated slice/iteration. Indices must
            refer to the relevant axis; slice steps must be nonzero, and count/rank uses must match
            the enclosing dimensions.

        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``ops[i].matmat(X) if i < len(ops) else X``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return ops[i].matmat(X) if i < len(ops) else X
    def capply(a,X):
        """Apply the enclosing covariance/precision operator to the supplied numerical vector.

        Parameters
        ----------
        a : array-like
            Numerical operand in ``ops[a]``. Shape must conform to that matrix/vector operation and
            the enclosing prepared state.

        X : array-like
            Predictor matrix with observations in rows and features in columns. Its row order must
            match the response or operator to which it is applied; the selected fitting routine
            determines missing-value support.

        Returns
        -------
        object
            Computed result from ``center(Xc)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Xc=center(X)
        if a < len(ops):
            return center(ops[a].matmat(Xc))
        return center(Xc)

    # Cache the first three levels. This reduces the naive p^4 repeated kernel
    # matvecs substantially for the usual A+D(+GxE)+E models.
    cb=[capply(b,Z) for b in range(p)]
    qjcb=[[qapply(j,cb[b]) for b in range(p)] for j in range(p)]
    caqjcb=[[[capply(a,qjcb[j][b]) for b in range(p)] for j in range(p)] for a in range(p)]
    operation_stage(f'analytic SE: masks/trace ({h} batched trace vectors)')
    _trace_bar = current_work()
    if _trace_bar is not None: _trace_bar.add_total(p**4)
    TT=np.empty((p,p,p,p),dtype=float)
    for i in range(p):
        for j in range(p):
            for a in range(p):
                for b in range(p):
                    X=qapply(i,caqjcb[a][j][b])
                    TT[i,j,a,b]=float(np.mean(np.sum(Z*X,axis=0)))
                    if _trace_bar is not None: _trace_bar.update()
    ranks=[]; kinds=[]
    for op in ops:
        if isinstance(op,LowRankKernelOperator):
            ranks.append(int(op.U.shape[1])); kinds.append(type(op).__name__)
        else:
            ranks.append(n); kinds.append(type(op).__name__)
    return TT, {
        'trace_probes':h, 'kernel_ranks':dict(zip(names,ranks)),
        'kernel_operators':dict(zip(names,kinds)), 'n_observed':n,
        'kernel_names':tuple(names),
    }


@operation_progress('analytic SE')
def multi_fa_mom_analytic_se(kernels, traits, moments, raw_specs, final_specs,
                             *, regularization_policy=None, overlap=None,
                             min_E_pair_overlap=2, ridge=None,
                             spectral_weighting='rank1', use_spectral_weights=False,
                             n_probes=32, trace_probes=16, kernel_rank='auto',
                             max_full_n=2500, random_state=0, eps=1e-12,
                             fa_boundary_tol=1e-8, fa_direct_max_traits=2200,
                             fa_cg_rtol=1e-9, fa_cg_maxiter=400,
                             ci_level=0.95, progress=None):
    """Joint multi-kernel final PSD/FA Gaussian sandwich SE.

    Notes
    -----
    The estimator is joint.  It uses the full ``(q+1)x(q+1)`` per-entry MoM
    normal system and therefore retains covariance between additive, dominance,
    GxE and residual covariance estimates.  Final uncertainty for total G,
    genetic correlation and h2 is obtained only after collapsing those joint
    blocks.  Rank selection and shrinkage-hyperparameter selection are treated
    as fixed, exactly as in the one-kernel final-FA sandwich.

    Parameters
    ----------
    kernels : object (see the cited input contract)
        mapping Named covariance kernels, e.g. additive, dominance and GxE.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    raw_specs : object (see the cited input contract)
        mapping Fixed-rank FA covariance specifications for every named kernel and E, before and
        after the selected regularization policy.

    final_specs : object (see the cited input contract)
        mapping Fixed-rank FA covariance specifications for every named kernel and E, before and
        after the selected regularization policy.

    regularization_policy : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``regularization_policy``.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``overlap``.

    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``ridge``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    use_spectral_weights : bool
        Input supplied to ``masked_multi_fa_mom_analytic_se`` as ``use_spectral_weights``. See
        that callable's documented ``use_spectral_weights`` contract for its type, alignment and
        value domain. This wrapper retains that contract. Default: ``False``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``use_spectral_weights``.

    n_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``32``. Passed to ``masked_multi_fa_mom_analytic_se`` as ``n_probes``.

    trace_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``16``. Passed to ``_multi_mom_trace_tensor`` as ``n_probes``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``max_full_n``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``masked_multi_fa_mom_analytic_se`` as ``random_state``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``masked_multi_fa_mom_analytic_se``
        as ``eps``.

    fa_boundary_tol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-08``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``fa_boundary_tol``.

    fa_direct_max_traits : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``2200``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``fa_direct_max_traits``.

    fa_cg_rtol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-09``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``fa_cg_rtol``.

    fa_cg_maxiter : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``400``. Passed to ``masked_multi_fa_mom_analytic_se`` as
        ``fa_cg_maxiter``.

    ci_level : float
        Posterior/analytical interval coverage probability, strictly between zero and one; the
        routine determines whether intervals use posterior quantiles or a normal approximation.
        Default: ``0.95``. Passed to ``masked_multi_fa_mom_analytic_se`` as ``ci_level``.

    progress : bool or None
        Default None inherits enclosing covariance reporting. True enables
        named analytic phases and real completed probe counts; False is silent.

    Returns
    -------
    object
        Computed result from ``summary``; see the summary and the called implementation for its labeled/numerical representation.
    """
    operation_stage('analytic SE: masks/trace')
    Y=traits.to_numpy(float) if isinstance(traits,pd.DataFrame) else np.asarray(traits,float)
    mask=_common_trait_mask(Y)
    if mask is None:
        return masked_multi_fa_mom_analytic_se(
            kernels, traits, moments, raw_specs, final_specs,
            regularization_policy=regularization_policy, overlap=overlap,
            min_E_pair_overlap=min_E_pair_overlap, ridge=ridge,
            spectral_weighting=spectral_weighting, use_spectral_weights=use_spectral_weights,
            n_probes=n_probes, kernel_rank=kernel_rank, max_full_n=max_full_n,
            random_state=random_state, eps=eps, fa_boundary_tol=fa_boundary_tol,
            fa_direct_max_traits=fa_direct_max_traits, fa_cg_rtol=fa_cg_rtol,
            fa_cg_maxiter=fa_cg_maxiter, ci_level=ci_level,
        )
    knames=list(moments.get('kernel_names',list(kernels)))
    names=knames+['E']; p=len(names); T=Y.shape[1]
    _ase_bar = current_work()
    if _ase_bar is not None: _ase_bar.add_total(2 * max(8, int(n_probes)))
    A=np.asarray(moments['A'],dtype=float)
    H=_sym(A[:,:,0,0])
    if H.shape != (p,p):
        raise ValueError(f'multi-kernel moment system has shape {H.shape}, expected {(p,p)}')
    if ridge is None: ridge=np.zeros(p,dtype=float)
    ridge=np.asarray(ridge,dtype=float).reshape(-1)
    if len(ridge)!=p: raise ValueError('ridge must have one value per genetic kernel plus E')
    Hfit=H.copy(); Hfit[np.diag_indices(p)] += ridge
    try: Hinv=np.linalg.inv(Hfit)
    except np.linalg.LinAlgError: Hinv=np.linalg.pinv(Hfit,rcond=1e-10)

    TT,tdiag=_multi_mom_trace_tensor(
        kernels,mask,n_probes=trace_probes,kernel_rank=kernel_rank,
        max_full_n=max_full_n,random_state=random_state,
    )
    model_specs=[final_specs[n] for n in names]
    pol={} if regularization_policy is None else regularization_policy
    ov=np.full((T,T),Y.shape[0],dtype=float) if overlap is None else np.asarray(overlap,float)

    scales=[np.ones(T) for _ in range(p)]; weight_errors=[np.nan]*p
    if use_spectral_weights and str(spectral_weighting).lower() in {'rank1','separable','information'}:
        try:
            scales,weight_errors=_spectral_component_scales(moments,ridge=ridge,eps=max(float(eps),1e-12))
        except Exception as exc:
            warnings.warn(
                f"spectral component weighting failed; falling back to unit scales: {exc}",
                RuntimeWarning, stacklevel=2,
            )
            scales=[np.ones(T) for _ in range(p)]

    operation_stage('analytic SE: tangent prep')
    tangents=[]; regops=[]
    for c,nm in enumerate(names):
        tangents.append(_prepare_fa_tangent_derivative(
            raw_specs[nm],scale=scales[c],eps=max(float(eps),1e-12),
            boundary_tol=fa_boundary_tol,direct_max_traits=fa_direct_max_traits,
            cg_rtol=fa_cg_rtol,cg_maxiter=fa_cg_maxiter,
        ))
        regops.append(_regularization_derivative(
            raw_specs[nm],pol,ov,component=('E' if nm=='E' else 'G'),
            min_E_pair_overlap=min_E_pair_overlap,eps=eps,
        ))

    # Pair-specific E shrinkage may be projected back into a requested FA rank.
    eidx=p-1
    emode=str(pol.get('E_mode','none')).lower()
    e_rank_preserve=bool(pol.get('E_rank_preserve',False)) and emode in {
        'pairwise','pairwise_overlap','overlap','fisher_eb','pairwise_eb','eb'
    } and final_specs['E'].rank < final_specs['E'].n_traits
    epost=(_prepare_fa_tangent_derivative(
        final_specs['E'],scale=np.ones(T),eps=max(float(eps),1e-12),
        boundary_tol=fa_boundary_tol,direct_max_traits=fa_direct_max_traits,
        cg_rtol=fa_cg_rtol,cg_maxiter=fa_cg_maxiter,
    ) if e_rank_preserve else None)

    def j_transpose(Vlist):
        """Map covariance-coordinate perturbations back through the transpose Jacobian.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Vlist[c]``. See
            ``vigor.multivariate.multi_fa_mom_analytic_se.j_transpose`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
        """
        out=[]
        for c in range(p):
            V=Vlist[c]
            if c==eidx and epost is not None: V=epost.transpose(V)
            out.append(tangents[c].transpose(_reg_apply(regops[c],V,transpose=True)))
        return out
    def j_apply(Vlist):
        """Map free-parameter perturbations into covariance-coordinate changes.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Vlist[c]``. See
            ``vigor.multivariate.multi_fa_mom_analytic_se.j_apply`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
        """
        out=[]
        for c in range(p):
            V=_reg_apply(regops[c],tangents[c].apply(Vlist[c]),transpose=False)
            if c==eidx and epost is not None: V=epost.apply(V)
            out.append(V)
        return out
    def cov_raw_apply(Vlist):
        # Move right H^-1 through the test direction.
        """Apply the unconstrained moment-covariance operator to a coordinate vector.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Hinv[d, j] * Vlist[d]``. See
            ``vigor.multivariate.multi_fa_mom_analytic_se.cov_raw_apply`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``U``; see the summary and the called implementation for its labeled/numerical representation.
        """
        W=[]
        for j in range(p):
            Wj=np.zeros((T,T),float)
            for d in range(p): Wj += Hinv[d,j]*Vlist[d]
            W.append(_sym(Wj))
        Zq=[]
        for i in range(p):
            Zi=np.zeros((T,T),float)
            for j in range(p):
                for a in range(p):
                    for b in range(p):
                        coef=2.0*TT[i,j,a,b]
                        if coef: Zi += coef*_cov_sandwich_trait(model_specs[a],W[j],model_specs[b])
            Zq.append(_sym(Zi))
        U=[]
        for c in range(p):
            Uc=np.zeros((T,T),float)
            for i in range(p): Uc += Hinv[c,i]*Zq[i]
            U.append(_sym(Uc))
        return U
    def cov_final_apply(Vlist): 
        """Apply the final rank/support-conditioned covariance uncertainty operator.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``j_apply(cov_raw_apply(j_transpose(Vlist)))``. See
            ``vigor.multivariate.multi_fa_mom_analytic_se.cov_final_apply`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``j_apply(cov_raw_apply(j_transpose(Vlist)))``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return j_apply(cov_raw_apply(j_transpose(Vlist)))

    rng=np.random.default_rng(int(random_state)+284991)
    npr=max(8,int(n_probes)); iu=np.triu_indices(T,1)

    # Component-wise marginal SEs from one block-Hutchinson stream. Cross-kernel
    # covariance is retained by the operator even though these outputs report
    # only each block's marginal diagonal.
    var_acc=[np.zeros((T,T),float) for _ in range(p)]
    for _probe in range(npr):
        operation_stage(f'analytic SE: component probe {_probe+1}/{npr}')
        probes=[_symmetric_rademacher_coordinate_probe(T,rng) for _c in range(p)]
        Zcoord=[z for z,v in probes]; V=[v for z,v in probes]
        U=cov_final_apply(V); Ycoord=[_coordinate_matrix(u) for u in U]
        for c in range(p): var_acc[c] += Zcoord[c]*Ycoord[c]
        if _ase_bar is not None: _ase_bar.update()
    component_var=[]
    for v in var_acc:
        vv=_sym(v/npr); vv[iu]*=.5; vv[(iu[1],iu[0])]*=.5
        component_var.append(np.maximum(vv,0.0))

    # Total genetic + E target.  L' maps a total-G test direction into every
    # genetic block; L sums the resulting genetic outputs. This includes all
    # Cov(G_k,G_l) terms rather than treating kernels as independent.
    def target_apply(VG,VE):
        """Apply the target covariance operator used for randomized uncertainty probes.

        Parameters
        ----------
        VG : array-like
            Genetic correlation or genetic/residual marginal variance quantity for the indicated
            component. Correlations align trait pairs; marginal variances align trait order and must
            support the boundary-aware transformation.

        VE : array-like
            Genetic correlation or genetic/residual marginal variance quantity for the indicated
            component. Correlations align trait pairs; marginal variances align trait order and must
            support the boundary-aware transformation.

        Returns
        -------
        object
            Computed result from ``(_sym(sum(U[:-1], np.zeros((T, T)))), _sym(U[-1]))``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Vin=[VG for _ in knames]+[VE]
        U=cov_final_apply(Vin)
        return _sym(sum(U[:-1],np.zeros((T,T)))),_sym(U[-1])
    Gvar_acc=np.zeros((T,T)); Evar_acc=np.zeros((T,T))
    cov_ts_tt=np.zeros((T,T)); cov_ts_ss=np.zeros((T,T)); cov_diagdiag=np.zeros((T,T)); cov_GE_diag=np.zeros(T)
    for _probe in range(npr):
        operation_stage(f'analytic SE: probe {_probe+1}/{npr}')
        zg,vg=_symmetric_rademacher_coordinate_probe(T,rng)
        ze,ve=_symmetric_rademacher_coordinate_probe(T,rng)
        ug,ue=target_apply(vg,ve); yg=_coordinate_matrix(ug); ye=_coordinate_matrix(ue)
        Gvar_acc += zg*yg; Evar_acc += ze*ye
        zgd=np.diag(zg); ygd=np.diag(yg)
        cov_ts_tt += zg*ygd[:,None]
        cov_ts_ss += zg*ygd[None,:]
        cov_diagdiag += zgd[:,None]*ygd[None,:]
        cov_GE_diag += .5*(np.diag(zg)*np.diag(ye)+np.diag(ze)*np.diag(yg))
        if _ase_bar is not None: _ase_bar.update()
    Gvar=_sym(Gvar_acc/npr); Evar=_sym(Evar_acc/npr)
    Gvar[iu]*=.5; Gvar[(iu[1],iu[0])]*=.5; Evar[iu]*=.5; Evar[(iu[1],iu[0])]*=.5
    Gvar=np.maximum(Gvar,0.0); Evar=np.maximum(Evar,0.0)
    cov_ts_tt/=npr*np.sqrt(2.0); cov_ts_ss/=npr*np.sqrt(2.0); cov_diagdiag/=npr; cov_GE_diag/=npr

    Gtotal=sum((final_specs[n].materialize() for n in knames),np.zeros((T,T)))
    Efinal=final_specs['E'].materialize()
    operation_stage('analytic SE: delta/rG/h2')
    summary=_analytic_delta_summaries(
        Gtotal,Efinal,Gvar,Evar,cov_ts_tt,cov_ts_ss,cov_diagdiag,cov_GE_diag,
        eps=eps,ci_level=ci_level,
    )
    summary.update({
        'method':'gaussian_multi_mom_final_fa_tangent_hutchinson',
        'kernel_names':tuple(knames),'n_kernels':len(knames),'n_probes':npr,**tdiag,
        'component_se':{nm:np.sqrt(component_var[c]) for c,nm in enumerate(names)},
        'component_var':{nm:component_var[c] for c,nm in enumerate(names)},
        'conditional_on_rank':True,'conditional_on_regularization_policy':True,
        'joint_kernel_covariance_retained':True,
        'tangent_ranks':{nm:int(tangents[c].projector.rank) for c,nm in enumerate(names)},
        'fa_boundary_counts':{nm:int(tangents[c].projector.boundary_count) for c,nm in enumerate(names)},
        'tangent_solvers':{nm:('direct' if tangents[c].projector.direct else 'cg') for c,nm in enumerate(names)},
        'spectral_weight_rank1_errors':{nm:(float(weight_errors[c]) if np.isfinite(weight_errors[c]) else np.nan) for c,nm in enumerate(names)},
        'regularization_notes':tuple(note for op in regops for note in op.notes)+((
            'pair-specific E shrinkage projected back into fixed-rank FA tangent',
        ) if epost is not None else ()),
        'constraint_note':(
            'Joint final fixed-rank PSD/FA sandwich for all named kernels plus E. '
            'Cross-kernel covariance is retained. Rank choice and automatic shrinkage hyperparameters are held fixed; '
            'bootstrap remains appropriate for selection uncertainty and non-common missingness.'
        ),
    })
    return summary


# ---------------------------------------------------------------------------
# Common-mask MINQUE and analytic Gaussian sandwich uncertainty
# ---------------------------------------------------------------------------

class _GaussianKernelSampler:
    """Square-root sampler for one animal covariance kernel.

    The sampler uses the exact dense eigensystem up to ``max_full_n`` and the
    same trace-matched low-rank-plus-isotropic representation used elsewhere in
    VIGOR for larger kernels.  It is created once and reused by all Gaussian
    sandwich probes.
    """
    def __init__(self, K, *, kernel_rank='auto', max_full_n=2500, random_state=0):
        """Initialize _GaussianKernelSampler with the inputs and resource settings below.

        Parameters
        ----------
        K : array-like
            Numerical operand in ``as_kernel_operator(K, dtype=np.float64)``. Shape must conform to
            that matrix/vector operation and the enclosing prepared state.

        kernel_rank : int, str or None
            Retained rank of the corresponding kernel/trait covariance or genomic feature group.
            Rank must fit that matrix dimension; full/auto/None semantics follow the specific
            resolver invoked below. Default: ``'auto'``. Source comparisons: ``req in {None, 'full',
            False, 0}``. See the rejection/fallback branches for enforcement.

        max_full_n : int
            Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
            larger problems use the configured approximation policy. Default: ``2500``.

        random_state : int or None
            Seed controlling randomized sampling, folds or projections for reproducibility. None
            uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
            ``LowRankKernelOperator.from_dense`` as ``random_state``.
        """
        op=K if isinstance(K,KernelOperator) else as_kernel_operator(K,dtype=np.float64)
        n=int(op.shape[0]); req=kernel_rank
        if isinstance(op,LowRankKernelOperator):
            self.op=op; self.approximation='supplied_lowrank'; self.n=n
            return
        if isinstance(req,str) and req.lower()=='auto':
            req='full' if n<=int(max_full_n) else min(256,n-1)
        if req in {None,'full',False,0}:
            if n>int(max_full_n):
                # A full dense square root at very large N would defeat the
                # purpose of the analytical path.  Use the same explicit
                # low-rank kernel approximation as trace-Hutchinson instead.
                req=min(256,n-1); self.approximation='auto_lowrank_large_n'
            else:
                A=np.asarray(op.K if isinstance(op,DenseKernelOperator) else op.submatrix(np.arange(n)),float)
                w,U=np.linalg.eigh(_sym(A)); keep=w>max(1e-12,1e-12*max(float(np.max(np.abs(w))),1.0))
                self.U=np.asarray(U[:,keep],float); self.values=np.maximum(np.asarray(w[keep],float),0.0)
                self.bulk=0.0; self.op=None; self.n=n; self.approximation='exact_eigh'
                return
        if not isinstance(op,DenseKernelOperator):
            A=np.asarray(op.submatrix(np.arange(n)),float)
        else:
            A=np.asarray(op.K,float)
        lr=LowRankKernelOperator.from_dense(A,max(1,min(int(req),n-1)),dtype=np.float64,
                                            random_state=random_state,probe_vectors=0)
        self.op=lr; self.n=n; self.approximation='trace_matched_lowrank'

    def sample(self,rng,ncols):
        """Draw/summarize the next value from the enclosing random or resource-monitor process.

        Parameters
        ----------
        rng : numpy.random.Generator
            Random-number generator used for draws; its current state is consumed by sampling.

        ncols : object (see the cited input contract)
            Input for the operation ``int(ncols)``. See
            ``vigor.multivariate._GaussianKernelSampler.sample`` and its caller for the scientific
            representation; the shown operation constrains the required type/shape. Source
            comparisons: ``m <= 0``. See the rejection/fallback branches for enforcement.

        Returns
        -------
        object
            Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
        """
        m=int(ncols)
        if m<=0: return np.zeros((self.n,0),float)
        if self.op is None:
            Z=rng.normal(size=(len(self.values),m))
            return self.U @ (np.sqrt(self.values)[:,None]*Z)
        op=self.op; U=np.asarray(op.U,float); vals=np.maximum(np.asarray(op.values,float),0.0)
        out=U @ (np.sqrt(vals)[:,None]*rng.normal(size=(len(vals),m)))
        bulk=max(float(op.bulk),0.0)
        if bulk>0:
            Z=rng.normal(size=(self.n,m))
            # Isotropic omitted eigenspace.  Eigenvectors from VIGOR's
            # spectral operators are orthonormal up to numerical precision.
            Z-=U@(U.T@Z)
            out+=math.sqrt(bulk)*Z
        return out


def _sample_kernel_trait_gaussian(sampler, spec, rng):
    """Sample N x T from matrix-normal covariance K (x) C.

    Parameters
    ----------
    sampler : callable or None
        Callback invoked at the corresponding fitting/prediction/scan stage. Accept the argument
        order shown by its call below and return the representation consumed there; None
        disables an optional callback or uses the default implementation.

    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity.

    rng : numpy.random.Generator
        Random-number generator used for draws; its current state is consumed by sampling.
    """
    spec=as_covariance_spec(spec)
    n=sampler.n; T=spec.n_traits; out=np.zeros((n,T),float)
    if spec.rank:
        out += sampler.sample(rng,spec.rank) @ np.asarray(spec.factor,float).T
    psi=np.maximum(np.asarray(spec.diag_specific,float),0.0)
    if np.any(psi>0):
        out += sampler.sample(rng,T)*np.sqrt(psi)[None,:]
    return out


def _sample_identity_trait_gaussian(n, spec, rng):
    """Sample identity trait gaussian.

    Parameters
    ----------
    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit. Passed to ``rng.normal`` as ``size``.

    spec : covariance specification or importlib.ModuleSpec
        Prepared matrix representation for numerical helpers, or importlib specification in the
        Domino import facade. Use the object supplied by the corresponding normalizer/import
        protocol, with unchanged shape/module identity. Passed to ``rng.normal`` as ``size``.

    rng : numpy.random.Generator
        Random-number generator used for draws; its current state is consumed by sampling.
    """
    spec=as_covariance_spec(spec); T=spec.n_traits; out=np.zeros((int(n),T),float)
    if spec.rank:
        out += rng.normal(size=(int(n),spec.rank)) @ np.asarray(spec.factor,float).T
    psi=np.maximum(np.asarray(spec.diag_specific,float),0.0)
    if np.any(psi>0): out += rng.normal(size=(int(n),T))*np.sqrt(psi)[None,:]
    return out


def _masked_moment_B_only(kernel_ops, names, Ydraw, obs):
    """Quadratic MoM statistics for a fixed heterogeneous phenotype mask.

    Parameters
    ----------
    kernel_ops : kernel/linear operator or mapping
        Prepared matrix operator exposing the multiplication methods used below; shape and
        sample order must match the right-hand side or phenotype matrix.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    Ydraw : array-like or numeric scalar
        Input for the operation ``np.asarray(Ydraw, float)``. See
        ``vigor.multivariate._masked_moment_B_only`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.

    obs : mapping
        Observed-cell plan containing animal/trait indices, trait slices and finite-response
        values. Obtain it from the observation-plan helper for the same phenotype matrix.
    """
    Y=np.asarray(Ydraw,float); R=np.asarray(obs,bool)
    den=R.sum(0); means=np.divide(np.sum(np.where(R,Y,0.0),axis=0),den,
                                  out=np.zeros(Y.shape[1]),where=den>0)
    Y0=np.where(R,Y-means[None,:],0.0)
    p=len(names)+1; T=Y.shape[1]; B=np.empty((p,T,T),float)
    for k,nm in enumerate(names): B[k]=_sym(Y0.T@kernel_ops[nm].matmat(Y0))
    B[-1]=_sym(Y0.T@Y0)
    return B


def _pairwise_moment_inverse(A, ridge, *, eps=1e-10, chunk=65536):
    """Pseudo-inverse of every trait-pair MoM normal system.

    Parameters
    ----------
    A : array-like
        Numerical operand in ``A.shape[0]``. Shape must conform to that matrix/vector operation
        and the enclosing prepared state.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-10``.

    chunk : int
        Variants per I/O/scoring/LD work block; positive counts bound loaded genotype columns
        and intermediate matrix size. Default: ``65536``.
    """
    A=np.asarray(A,float); p=A.shape[0]; T=A.shape[2]
    H=np.transpose(A,(2,3,0,1)).copy(); rr=np.asarray(ridge,float).reshape(-1)
    if len(rr)!=p: raise ValueError('ridge length must equal the MoM component count')
    ii=np.arange(p); H[...,ii,ii]+=rr
    flat=H.reshape(-1,p,p); out=np.empty_like(flat)
    for j0 in range(0,len(flat),int(chunk)):
        x=_sym_batch(flat[j0:j0+int(chunk)])
        w,V=np.linalg.eigh(x)
        scale=np.maximum(np.max(np.abs(w),axis=1),1.0)
        iw=np.zeros_like(w, dtype=float)
        good=w>float(eps)*scale[:,None]
        np.divide(1.0,w,out=iw,where=good)
        out[j0:j0+len(x)]=(V*iw[:,None,:])@np.swapaxes(V,-1,-2)
    return out.reshape(T,T,p,p)


def _sym_batch(A):
    """Symmetrize each square matrix in a stacked batch.

    Parameters
    ----------
    A : array-like
        Numerical operand in ``0.5 * (A + np.swapaxes(A, -1, -2))``. Shape must conform to that
        matrix/vector operation and the enclosing prepared state.
    """
    A=np.asarray(A,float)
    return .5*(A+np.swapaxes(A,-1,-2))


@operation_progress('analytic SE')
def masked_multi_fa_mom_analytic_se(kernels, traits, moments, raw_specs, final_specs,
                                     *, regularization_policy=None, overlap=None,
                                     min_E_pair_overlap=2, ridge=None,
                                     spectral_weighting='rank1', use_spectral_weights=False,
                                     n_probes=64, kernel_rank='auto', max_full_n=2500,
                                     random_state=0, eps=1e-12,
                                     fa_boundary_tol=1e-8, fa_direct_max_traits=2200,
                                     fa_cg_rtol=1e-9, fa_cg_maxiter=400,
                                     ci_level=.95, progress=None):
    """Final PSD/FA Gaussian sandwich for arbitrary trait-specific missingness.

    Heterogeneous observation masks destroy the animal/trait Kronecker
    separability used by the common-mask trace formula.  VIGOR 2.8.5 handles
    that case without complete-case deletion and without covariance refits:

    1. keep the exact observed mask of every trait and the pair-specific MoM
       normal systems ``H_ab`` already used by the estimator;
    2. draw Gaussian *moment probes* from the fitted covariance model under
       that fixed missingness pattern;
    3. map each probe through ``H_ab^-1`` and the same fixed-rank FA/
       regularization derivative used by the final estimator;
    4. estimate the sandwich covariance of the final covariance entries.

    The randomization evaluates the analytical Gaussian quadratic-form
    covariance numerically; it is not a phenotype/bootstrap refit.  Thus one
    probe requires only kernel matrix multiplications and small pairwise MoM
    solves, not an optimization.  Rank/shrinkage choices remain conditioned on
    their fitted values, as in the common-mask analytical sandwich.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    moments : mapping
        Method-of-moments tensors: A contains component-pair × trait-pair coefficients and B
        contains component × trait-pair response moments. Component and trait ordering must
        agree with ranks, names and covariance specifications.

    raw_specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state.

    final_specs : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state.

    regularization_policy : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``.

    overlap : array-like
        Pairwise weights or jointly observed counts, aligned to the trait/variant-pair axes of
        the associated covariance/LD matrix. Missing-data precision calculations must use the
        actual shared observations. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value.

    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``_spectral_component_scales`` as ``ridge``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    use_spectral_weights : bool
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``False``.

    n_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``64``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``. Passed to
        ``_GaussianKernelSampler`` as ``max_full_n``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_GaussianKernelSampler`` as ``random_state``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``_pairwise_moment_inverse`` as
        ``eps``.

    fa_boundary_tol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-08``. Passed to ``_prepare_fa_tangent_derivative`` as
        ``boundary_tol``.

    fa_direct_max_traits : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``2200``. Passed to ``_prepare_fa_tangent_derivative`` as
        ``direct_max_traits``.

    fa_cg_rtol : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``1e-09``. Passed to ``_prepare_fa_tangent_derivative`` as ``cg_rtol``.

    fa_cg_maxiter : float or int
        Analytical tangent-solve control: boundary_tol detects near-zero variances,
        direct_max_traits sets the direct-solve size cutoff, cg_rtol the relative iterative
        tolerance and cg_maxiter its iteration cap. Use nonnegative tolerances and positive
        counts. Default: ``400``. Passed to ``_prepare_fa_tangent_derivative`` as
        ``cg_maxiter``.

    ci_level : float
        Posterior/analytical interval coverage probability, strictly between zero and one; the
        routine determines whether intervals use posterior quantiles or a normal approximation.
        Default: ``0.95``. Passed to ``_analytic_delta_summaries`` as ``ci_level``.

    progress : bool or None
        Default None inherits enclosing covariance reporting. True enables
        named analytic phases and real completed probe counts; False is silent.

    Returns
    -------
    object
        Computed result from ``summary``; see the summary and the called implementation for its labeled/numerical representation.
    """
    operation_stage('analytic SE: masks/trace')
    Y=traits.to_numpy(float) if isinstance(traits,pd.DataFrame) else np.asarray(traits,float)
    obs=np.isfinite(Y); n,T=Y.shape; knames=list(moments.get('kernel_names',list(kernels)))
    names=knames+['E']; p=len(names)
    _ase_bar = current_work()
    if _ase_bar is not None: _ase_bar.add_total(max(16, int(n_probes)))
    A=np.asarray(moments['A'],float)
    if A.shape[:2]!=(p,p): raise ValueError(f'moment system has shape {A.shape[:2]}, expected {(p,p)}')
    if ridge is None: ridge=np.zeros(p,float)
    ridge=np.asarray(ridge,float).reshape(-1)
    Hinv=_pairwise_moment_inverse(A,ridge,eps=max(float(eps),1e-10))
    pol={} if regularization_policy is None else regularization_policy
    ov=(obs.astype(np.int64).T@obs.astype(np.int64)).astype(float) if overlap is None else np.asarray(overlap,float)

    scales=[np.ones(T) for _ in range(p)]; weight_errors=[np.nan]*p
    if use_spectral_weights and str(spectral_weighting).lower() in {'rank1','separable','information'}:
        try:
            scales,weight_errors=_spectral_component_scales(moments,ridge=ridge,eps=max(float(eps),1e-12))
        except Exception as exc:
            warnings.warn(
                f"spectral component weighting failed; falling back to unit scales: {exc}",
                RuntimeWarning, stacklevel=2,
            )
    operation_stage('analytic SE: tangent prep')
    tangents=[]; regops=[]
    for c,nm in enumerate(names):
        tangents.append(_prepare_fa_tangent_derivative(
            raw_specs[nm],scale=scales[c],eps=max(float(eps),1e-12),
            boundary_tol=fa_boundary_tol,direct_max_traits=fa_direct_max_traits,
            cg_rtol=fa_cg_rtol,cg_maxiter=fa_cg_maxiter))
        regops.append(_regularization_derivative(
            raw_specs[nm],pol,ov,component=('E' if nm=='E' else 'G'),
            min_E_pair_overlap=min_E_pair_overlap,eps=eps))
    eidx=p-1; emode=str(pol.get('E_mode','none')).lower()
    e_rank_preserve=bool(pol.get('E_rank_preserve',False)) and emode in {
        'pairwise','pairwise_overlap','overlap','fisher_eb','pairwise_eb','eb'
    } and final_specs['E'].rank<final_specs['E'].n_traits
    epost=(_prepare_fa_tangent_derivative(
        final_specs['E'],scale=np.ones(T),eps=max(float(eps),1e-12),
        boundary_tol=fa_boundary_tol,direct_max_traits=fa_direct_max_traits,
        cg_rtol=fa_cg_rtol,cg_maxiter=fa_cg_maxiter) if e_rank_preserve else None)

    def j_apply(Vlist):
        """Map free-parameter perturbations into covariance-coordinate changes.

        Parameters
        ----------
        Vlist : object (see the cited input contract)
            Input for the operation ``Vlist[c]``. See
            ``vigor.multivariate.masked_multi_fa_mom_analytic_se.j_apply`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
        """
        out=[]
        for c in range(p):
            V=_reg_apply(regops[c],tangents[c].apply(Vlist[c]),transpose=False)
            if c==eidx and epost is not None: V=epost.apply(V)
            out.append(_sym(V))
        return out

    # Build reusable kernel operators and square-root samplers once.
    kop={nm:as_kernel_operator(kernels[nm],dtype=np.float64) for nm in knames}
    samplers={nm:_GaussianKernelSampler(kernels[nm],kernel_rank=kernel_rank,
                                       max_full_n=max_full_n,random_state=int(random_state)+113*k)
              for k,nm in enumerate(knames)}
    rng=np.random.default_rng(int(random_state)+285025)
    npr=max(16,int(n_probes))
    sum_comp=[np.zeros((T,T),float) for _ in range(p)]
    sum2_comp=[np.zeros((T,T),float) for _ in range(p)]
    sumG=np.zeros((T,T),float); sumG2=np.zeros((T,T),float)
    sumE=np.zeros((T,T),float); sumE2=np.zeros((T,T),float)
    sum_G_entry_diagrow=np.zeros((T,T),float)
    sum_G_entry_diagcol=np.zeros((T,T),float)
    sum_G_diag_outer=np.zeros((T,T),float)
    sum_GE_diag=np.zeros(T,float)

    for _probe in range(npr):
        operation_stage(f'analytic SE: probe {_probe+1}/{npr}')
        Yd=np.zeros((n,T),float)
        for nm in knames: Yd += _sample_kernel_trait_gaussian(samplers[nm],final_specs[nm],rng)
        Yd += _sample_identity_trait_gaussian(n,final_specs['E'],rng)
        B=_masked_moment_B_only(kop,knames,Yd,obs)
        # theta[c,a,b] = H_ab^{-1}[c,j] B[j,a,b]
        raw=np.einsum('abij,jab->iab',Hinv,B,optimize=True)
        draw=j_apply([_sym(raw[c]) for c in range(p)])
        for c,X in enumerate(draw):
            sum_comp[c]+=X; sum2_comp[c]+=X*X
        Gx=_sym(sum(draw[:-1],np.zeros((T,T),float))); Ex=_sym(draw[-1])
        sumG+=Gx; sumG2+=Gx*Gx; sumE+=Ex; sumE2+=Ex*Ex
        dg=np.diag(Gx); de=np.diag(Ex)
        sum_G_entry_diagrow += Gx*dg[:,None]
        sum_G_entry_diagcol += Gx*dg[None,:]
        sum_G_diag_outer += dg[:,None]*dg[None,:]
        sum_GE_diag += dg*de

        if _ase_bar is not None: _ase_bar.update()
    den=max(npr-1,1); component_var=[]
    for sx,sx2 in zip(sum_comp,sum2_comp):
        vv=(sx2-sx*sx/npr)/den; component_var.append(np.maximum(_sym(vv),0.0))
    Gvar=np.maximum(_sym((sumG2-sumG*sumG/npr)/den),0.0)
    Evar=np.maximum(_sym((sumE2-sumE*sumE/npr)/den),0.0)
    meanG=sumG/npr; meanE=sumE/npr; mdg=np.diag(meanG); mde=np.diag(meanE)
    cov_ts_tt=(sum_G_entry_diagrow-sumG*mdg[:,None])/den
    cov_ts_ss=(sum_G_entry_diagcol-sumG*mdg[None,:])/den
    cov_diagdiag=(sum_G_diag_outer-(np.diag(sumG)[:,None]*np.diag(sumG)[None,:]/npr))/den
    cov_GE_diag=(sum_GE_diag-(np.diag(sumG)*np.diag(sumE)/npr))/den
    Gtotal=sum((final_specs[n].materialize() for n in knames),np.zeros((T,T)))
    Efinal=final_specs['E'].materialize()
    operation_stage('analytic SE: delta/rG/h2')
    summary=_analytic_delta_summaries(Gtotal,Efinal,Gvar,Evar,cov_ts_tt,cov_ts_ss,
                                      cov_diagdiag,cov_GE_diag,eps=eps,ci_level=ci_level)
    # Count unique row-wise observation patterns without materializing strings.
    packed=np.packbits(obs,axis=1); mask_patterns=int(len(np.unique(packed,axis=0)))
    summary.update({
        'method':'gaussian_masked_mom_final_fa_sandwich_probes',
        'masked_backend':'gaussian_moment_probes','common_trait_mask':False,
        'mask_pattern_count':mask_patterns,'n_probes':npr,
        'probe_se_relative_mc_error_approx':float(1.0/math.sqrt(2.0*max(npr-1,1))),
        'kernel_names':tuple(knames),'n_kernels':len(knames),
        'kernel_sampling_approximations':{nm:samplers[nm].approximation for nm in knames},
        'component_se':{nm:np.sqrt(component_var[c]) for c,nm in enumerate(names)},
        'component_var':{nm:component_var[c] for c,nm in enumerate(names)},
        'conditional_on_rank':True,'conditional_on_regularization_policy':True,
        'joint_kernel_covariance_retained':True,
        'tangent_ranks':{nm:int(tangents[c].projector.rank) for c,nm in enumerate(names)},
        'fa_boundary_counts':{nm:int(tangents[c].projector.boundary_count) for c,nm in enumerate(names)},
        'spectral_weight_rank1_errors':{nm:(float(weight_errors[c]) if np.isfinite(weight_errors[c]) else np.nan)
                                        for c,nm in enumerate(names)},
        'constraint_note':('Fixed-mask Gaussian final PSD/FA sandwich. Trait-specific missingness is retained exactly in the '
                           'pairwise MoM systems; Gaussian moment covariance is evaluated by randomized probes without covariance refits. '
                           'Rank and shrinkage-hyperparameter selection are conditioned on their fitted values.'),
    })
    return summary

def _common_trait_mask(Y):
    """Return a shared observation mask, or None when trait masks differ.

    Parameters
    ----------
    Y : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.
    """
    A = np.isfinite(np.asarray(Y, dtype=float))
    if A.ndim != 2 or A.shape[1] == 0:
        return np.ones(A.shape[0], dtype=bool)
    first = A[:, 0]
    if np.all(A == first[:, None]):
        return first.copy()
    return None


def _spectral_kernel_for_minque(K, *, kernel_rank="auto", max_full_n=2500,
                                dtype=np.float64, random_state=0):
    """Resolve a single GRM to a spectral operator for fast MINQUE.

    A supplied :class:`LowRankKernelOperator` is reused without work.  Dense
    matrices use a full eigensystem only for moderate N; for larger N an
    explicit low-rank request (or ``kernel_rank='auto'``) uses the same
    trace-matched low-rank operator as the 2.6 mvBLUP/mvGWAS fast path.

    Parameters
    ----------
    K : array-like
        Numerical input passed to ``LowRankKernelOperator`` as ``bulk``; see that callable for
        required dimensions and matrix role. Passed to ``LowRankKernelOperator`` as ``bulk``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``LowRankKernelOperator`` as
        ``dtype``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``LowRankKernelOperator.from_dense`` as ``random_state``.
    """
    if isinstance(K, LowRankKernelOperator):
        return K
    if isinstance(K, DenseKernelOperator):
        A = np.asarray(K.K, dtype=float)
    elif isinstance(K, np.ndarray) or isinstance(K, pd.DataFrame):
        A = np.asarray(K, dtype=float)
    elif hasattr(K, "U") and hasattr(K, "values") and hasattr(K, "bulk"):
        return LowRankKernelOperator(K.U, K.values, bulk=float(K.bulk), dtype=dtype)
    else:
        op = as_kernel_operator(K, dtype=dtype)
        if isinstance(op, LowRankKernelOperator):
            return op
        if not isinstance(op, DenseKernelOperator):
            raise TypeError("MINQUE requires a dense or spectral/low-rank GRM operator")
        A = np.asarray(op.K, dtype=float)
    n = A.shape[0]
    requested = kernel_rank
    if isinstance(requested, str) and requested.lower() == "auto":
        requested = "full" if n <= int(max_full_n) else min(256, n - 1)
    if requested in {None, "full", False}:
        if n > int(max_full_n):
            raise ValueError(
                "exact dense MINQUE would require a full GRM eigendecomposition; "
                "pass a LowRankKernelOperator/eigensystem or set minque_kernel_rank"
            )
        w, U = np.linalg.eigh(_sym(A))
        order = np.argsort(w)[::-1]
        w, U = w[order], U[:, order]
        return LowRankKernelOperator(U, np.maximum(w, 0.0), bulk=0.0, dtype=dtype,
                                     diagnostics={"source": "full_eigh_minque"})
    rank = max(1, min(int(requested), n - 1))
    return LowRankKernelOperator.from_dense(A, rank, dtype=dtype,
                                            random_state=random_state, probe_vectors=0)


def _spectral_reduced_projection(op, *, h2_ref=0.5, residualize_intercept=True, eps=1e-12):
    """Compact spectral representation of P for V0=h2*K+(1-h2)*I.

    The omitted eigenspace of ``LowRankKernelOperator`` is isotropic with
    eigenvalue ``bulk``.  Only the component of the intercept in that space
    needs to be represented explicitly; all remaining directions contribute a
    scalar multiplicity to trace expressions.  This makes the MINQUE trace
    system exact for the supplied kernel representation without N x N matrices.

    Parameters
    ----------
    op : kernel/linear operator or mapping
        Prepared matrix operator exposing the multiplication methods used below; shape and
        sample order must match the right-hand side or phenotype matrix.

    h2_ref : float or one-dimensional array
        Genetic variance fraction in [0, 1], scalar or ordered by trait as required. This is the
        working/reference heritability when the routine builds a null precision rather than
        estimating the final fraction. Default: ``0.5``. Source comparisons: ``0.0 <= h < 1.0``.
        See the rejection/fallback branches for enforcement.

    residualize_intercept : bool
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``True``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.
    """
    if not isinstance(op, LowRankKernelOperator):
        raise TypeError("spectral MINQUE requires LowRankKernelOperator")
    h = float(h2_ref)
    if not (0.0 <= h < 1.0):
        raise ValueError("minque_h2_ref must lie in [0,1)")
    n, q = op.shape[0], op.U.shape[1]
    one = np.ones(n, dtype=float)
    c_top = np.asarray(op.U, float).T @ one
    resid2 = max(float(n) - float(c_top @ c_top), 0.0)
    use_resid = resid2 > max(float(eps), 1e-10 * max(float(n), 1.0))
    if use_resid:
        lam = np.r_[np.asarray(op.values, float), float(op.bulk)]
        c = np.r_[c_top, math.sqrt(resid2)]
        complement = max(n - q - 1, 0)
    else:
        lam = np.asarray(op.values, float).copy()
        c = c_top.copy()
        complement = max(n - q, 0)
    e = 1.0 - h
    v = np.maximum(h * lam + e, eps)
    D = 1.0 / v
    if residualize_intercept:
        a = D * c
        den = float(c @ a)
        if den <= eps:
            raise np.linalg.LinAlgError("MINQUE intercept projection is singular")
        P = np.diag(D) - np.outer(a, a) / den
    else:
        P = np.diag(D)
        den = np.nan
    bulk_v = max(h * float(op.bulk) + e, eps)
    p_bulk = 1.0 / bulk_v
    return {
        "lambda": lam, "coord_one": c, "P": P, "p_bulk": p_bulk,
        "complement": int(complement), "h2_ref": h, "intercept_den": den,
    }


def _apply_minque_P(op, X, *, h2_ref=0.5, residualize_intercept=True, eps=1e-12):
    """Apply P=V0^-1-X(X'V0^-1X)^-1X'V0^-1 for an intercept-only model.

    Parameters
    ----------
    op : kernel/linear operator or mapping
        Prepared matrix operator exposing the multiplication methods used below; shape and
        sample order must match the right-hand side or phenotype matrix.

    X : array-like
        Predictor matrix with observations in rows and features in columns. Its row order must
        match the response or operator to which it is applied; the selected fitting routine
        determines missing-value support.

    h2_ref : float or one-dimensional array
        Genetic variance fraction in [0, 1], scalar or ordered by trait as required. This is the
        working/reference heritability when the routine builds a null precision rather than
        estimating the final fraction. Default: ``0.5``.

    residualize_intercept : bool
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``True``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.
    """
    X = np.asarray(X, dtype=float)
    vector = X.ndim == 1
    if vector:
        X = X[:, None]
    h = float(h2_ref)
    e = 1.0 - h
    bulk_v = max(e + h * float(op.bulk), eps)
    inv_bulk = 1.0 / bulk_v
    top_inv = 1.0 / np.maximum(e + h * np.asarray(op.values, float), eps)
    corr = top_inv - inv_bulk

    def vinv(Z):
        """Apply the prepared inverse covariance to the supplied observed-space right-hand side.

        Parameters
        ----------
        Z : array-like
            Sample × variant numerical coding used in genotype moments. Raw inputs use biallelic
            dosage; centered/additive/dominance inputs must already follow the coding named by this
            operation. Missing entries are represented by the accompanying mask or NaN policy.

        Returns
        -------
        object
            Computed result from ``inv_bulk * Z + np.asarray(op.U, float) @ (corr[:, None] * (np.asarray(op.U, float).T @ Z))``; see the summary and the called implementation for its labeled/numerical representation.
        """
        Z = np.asarray(Z, dtype=float)
        return inv_bulk * Z + np.asarray(op.U, float) @ (corr[:, None] * (np.asarray(op.U, float).T @ Z))

    out = vinv(X)
    if residualize_intercept:
        one = np.ones((op.shape[0], 1), dtype=float)
        a = vinv(one)
        den = float((one.T @ a).item())
        out = out - a @ ((one.T @ out) / max(den, eps))
    return out[:, 0] if vector else out


def _minque_trace_system(op, *, h2_ref=0.5, residualize_intercept=True, eps=1e-12):
    """Return MINQUE S and Gaussian fourth-moment trace tensor.

    ``S[i,j] = tr(P K_i P K_j)`` with ``K_0=K`` and ``K_1=I``.
    ``T[i,j,a,b] = tr(H_i K_a H_j K_b)``, ``H_i=P K_i P``.
    These are sufficient for the exact Gaussian sandwich of the *unconstrained*
    two-component MINQUE covariance estimator under a common observation mask.

    Parameters
    ----------
    op : kernel/linear operator or mapping
        Prepared matrix operator exposing the multiplication methods used below; shape and
        sample order must match the right-hand side or phenotype matrix.

    h2_ref : float or one-dimensional array
        Genetic variance fraction in [0, 1], scalar or ordered by trait as required. This is the
        working/reference heritability when the routine builds a null precision rather than
        estimating the final fraction. Default: ``0.5``. Passed to
        ``_spectral_reduced_projection`` as ``h2_ref``.

    residualize_intercept : bool
        Input supplied to ``_spectral_reduced_projection`` as ``residualize_intercept``. See
        that callable's documented ``residualize_intercept`` contract for its type, alignment
        and value domain. This wrapper retains that contract. Default: ``True``. Passed to
        ``_spectral_reduced_projection`` as ``residualize_intercept``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``_spectral_reduced_projection`` as
        ``eps``.
    """
    red = _spectral_reduced_projection(
        op, h2_ref=h2_ref, residualize_intercept=residualize_intercept, eps=eps
    )
    lam = red["lambda"]
    P = red["P"]
    comp = red["complement"]
    pb = float(red["p_bulk"])
    Kb = [np.diag(lam), np.eye(len(lam), dtype=float)]
    H = [P @ Kb[0] @ P, P @ P]
    bulk_k = [float(op.bulk), 1.0]
    bulk_h = [pb * pb * bulk_k[0], pb * pb]
    S = np.zeros((2, 2), dtype=float)
    TT = np.zeros((2, 2, 2, 2), dtype=float)
    for i in range(2):
        for j in range(2):
            S[i, j] = float(np.trace(P @ Kb[i] @ P @ Kb[j]))
            if comp:
                S[i, j] += comp * (pb * pb * bulk_k[i] * bulk_k[j])
            for a in range(2):
                for b in range(2):
                    TT[i, j, a, b] = float(np.trace(H[i] @ Kb[a] @ H[j] @ Kb[b]))
                    if comp:
                        TT[i, j, a, b] += comp * bulk_h[i] * bulk_k[a] * bulk_h[j] * bulk_k[b]
    return _sym(S), TT, red


def minque_moments_single_kernel(
    grm,
    traits,
    *,
    h2_ref=0.5,
    kernel_rank="auto",
    max_full_n=2500,
    random_state=0,
    residualize_intercept=True,
    eps=1e-12,
):
    """Fast common-mask MINQUE moments for one GRM.

    This is a genuine fixed-prior MINQUE construction: P is built once from
    ``V0 = h2_ref*K + (1-h2_ref)I`` and reused for all trait pairs.  The same
    two 2x2 trace equations then estimate every G_ts/E_ts entry.  The path is
    intentionally restricted to a common trait mask; exact mask-specific
    MINQUE would require a distinct P per mask and would defeat the large-T
    speed objective.

    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    h2_ref : float or one-dimensional array
        Genetic variance fraction in [0, 1], scalar or ordered by trait as required. This is the
        working/reference heritability when the routine builds a null precision rather than
        estimating the final fraction. Default: ``0.5``. Passed to ``_apply_minque_P`` as
        ``h2_ref``.

    kernel_rank : int, str or None
        Retained rank of the corresponding kernel/trait covariance or genomic feature group.
        Rank must fit that matrix dimension; full/auto/None semantics follow the specific
        resolver invoked below. Default: ``'auto'``.

    max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``. Passed to
        ``_spectral_kernel_for_minque`` as ``max_full_n``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``_spectral_kernel_for_minque`` as ``random_state``.

    residualize_intercept : bool
        Input supplied to ``_apply_minque_P`` as ``residualize_intercept``. See that callable's
        documented ``residualize_intercept`` contract for its type, alignment and value domain.
        This wrapper retains that contract. Default: ``True``. Passed to ``_apply_minque_P`` as
        ``residualize_intercept``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``. Passed to ``_apply_minque_P`` as ``eps``.

    Returns
    -------
    dict
        Result fields: ``A``, ``B``, ``Y0``, ``R``, ``means``, ``kernel_names``, ``minque``. Field arrays preserve the corresponding input axis order.
    """
    Ydf = traits if isinstance(traits, pd.DataFrame) else pd.DataFrame(traits)
    Yraw = Ydf.to_numpy(float)
    mask = _common_trait_mask(Yraw)
    if mask is None:
        raise ValueError(
            "moment_estimator='minque' currently requires all traits to share the same observation mask; "
            "use the default MoM estimator for arbitrary missingness"
        )
    if not np.any(mask):
        raise ValueError("no observed animals for MINQUE")
    base_op = as_kernel_operator(grm, dtype=np.float64)
    if not np.all(mask):
        nobs = int(mask.sum())
        if nobs > int(max_full_n):
            raise ValueError(
                "common-mask MINQUE with omitted animals needs a sub-kernel eigensystem; "
                "for large N pass traits on the observed rows or use default MoM"
            )
        Ksub = base_op.submatrix(np.flatnonzero(mask))
        op = _spectral_kernel_for_minque(
            Ksub, kernel_rank=kernel_rank, max_full_n=max_full_n,
            dtype=np.float64, random_state=random_state,
        )
        Y = Yraw[mask]
    else:
        op = _spectral_kernel_for_minque(
            base_op, kernel_rank=kernel_rank, max_full_n=max_full_n,
            dtype=np.float64, random_state=random_state,
        )
        Y = Yraw
    Z = _apply_minque_P(
        op, Y, h2_ref=h2_ref, residualize_intercept=residualize_intercept, eps=eps
    )
    KZ = op.matmat(Z)
    B0 = _sym(Z.T @ KZ)
    B1 = _sym(Z.T @ Z)
    S, TT, red = _minque_trace_system(
        op, h2_ref=h2_ref, residualize_intercept=residualize_intercept, eps=eps
    )
    if not np.isfinite(np.linalg.det(S)) or np.linalg.det(S) <= eps:
        raise np.linalg.LinAlgError("MINQUE two-component information is singular")
    T = Y.shape[1]
    A = np.empty((2, 2, T, T), dtype=float)
    for i in range(2):
        for j in range(2):
            A[i, j].fill(S[i, j])
    return {
        "A": A,
        "B": np.stack([B0, B1], axis=0),
        "Y0": Y,
        "R": np.ones_like(Y, dtype=float),
        "means": np.zeros(T, dtype=float),
        "kernel_names": ["genetic"],
        "minque": {
            "S": S,
            "trace_tensor": TT,
            "h2_ref": float(h2_ref),
            "kernel_rank": int(op.U.shape[1]),
            "kernel_bulk": float(op.bulk),
            "kernel_diagnostics": dict(getattr(op, "diagnostics", {})),
            "n_observed": int(Y.shape[0]),
            "residualize_intercept": bool(residualize_intercept),
            "reduced_dimension": int(len(red["lambda"])),
        },
    }


def _minque_sandwich_se(base_G, base_E, *, S, trace_tensor,
                         shrink_G=1.0, shrink_E=1.0, eps=1e-12):
    """Gaussian sandwich SEs for common-mask two-component MINQUE.

    The sandwich is for the unconstrained covariance-entry estimator.  VIGOR's
    FA/PSD fit is a smooth constrained M-estimator, but factor rotations are
    non-identifiable and the constraint changes the covariance.  Therefore
    these SEs are returned as a fast *pre-constraint/local* approximation and
    the weighted/cluster bootstrap remains the reference uncertainty estimate.

    Parameters
    ----------
    base_G : covariance specification or array-like
        Left/right or pre/post-regularization trait covariance used in the
        uncertainty/prediction transformation. Preserve trait order and the estimator stage
        named by this argument.

    base_E : covariance specification or array-like
        Left/right or pre/post-regularization trait covariance used in the
        uncertainty/prediction transformation. Preserve trait order and the estimator stage
        named by this argument.

    S : array-like
        Numerical operand in ``np.linalg.pinv(np.asarray(S, float), rcond=1e-12)``. Shape must
        conform to that matrix/vector operation and the enclosing prepared state.

    trace_tensor : array-like or numeric scalar
        Input for the operation ``np.asarray(trace_tensor, float)``. See
        ``vigor.multivariate._minque_sandwich_se`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.

    shrink_G : float, str or mapping
        Genetic off-diagonal retention: numeric values conventionally lie in [0,1], with 1
        retaining all. 'auto'/'legacy_auto'/'historical_auto' uses sample-size retention
        n/(n+50); 'none'/'off' retains all; 'auto_cv'/'cv' invokes held-out moment policy
        selection. 'analytic_global'/'analytic_pairwise' (and aliases resolved by
        _analytic_shrink_mode) regularizes prediction after final SE, preserving unshrunk
        inference. Kernel-name mappings are accepted. Residual-only pairwise/EB spellings are
        not genetic policies. Default: ``1.0``.

    shrink_E : float or str
        Residual retention: numeric 0..1 scales off-diagonals.
        'auto' shrinks each residual pair by overlap/(overlap+400) without rank preservation
        (the 3.1.3 policy; same as 'pairwise_full'); append '@s' ('auto@100') to set the
        per-pair strength s. 'linear_analytic' applies the closed-form overlap-aware
        Schafer-Strimmer linear intensity toward the diagonal. 'model_eb' ('model_eb@c')
        shrinks each pair by tau2/(tau2 + c s2_ij), with s2_ij the pair's sampling variance
        from the fit's own MoM precision. 'eb'/'fisher_eb'/'pairwise_eb' uses
        rank-preserving Fisher-z EB, while 'fisher_eb_full'/'pairwise_eb_full'/'eb_full'
        permits full-rank pair retention. 'pairwise'/'pairwise_overlap' uses overlap support
        with rank preservation; 'pairwise_full'/'pairwise_overlap_full' omits that rank
        restriction.
        'legacy_auto'/'historical_auto' uses median overlap/(overlap+400); 'none'/'off' retains
        all. 'auto_cv'/'cv' selects on held-out moments; analytic aliases use final-SE
        prediction retention. auto_supported E requires scalar-compatible retention. Default:
        ``1.0``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-12``.
    """
    G0 = _sym(np.asarray(base_G, dtype=float))
    E0 = _sym(np.asarray(base_E, dtype=float))
    if G0.shape != E0.shape or G0.ndim != 2:
        raise ValueError("G and E must be square and have the same shape")
    Tn = G0.shape[0]
    Sinv = np.linalg.pinv(np.asarray(S, float), rcond=1e-12)
    TT = np.asarray(trace_tensor, float)
    Theta = np.stack([G0, E0], axis=0)  # component x trait x trait
    D = np.stack([np.diag(G0), np.diag(E0)], axis=0)
    J = np.zeros((2, 2, Tn, Tn), dtype=float)
    for i in range(2):
        for j in range(2):
            Tij = TT[i, j]
            # Cov(y_t'H_i y_s, y_t'H_j y_s)
            term_diag = np.einsum("as,ab,bt->ts", D, Tij, D, optimize=True)
            term_cross = np.einsum("ats,ab,bts->ts", Theta, Tij, Theta, optimize=True)
            J[i, j] = _sym(term_diag + term_cross)
    var_g = np.einsum("i,ijts,j->ts", Sinv[0], J, Sinv[:, 0], optimize=True)
    var_e = np.einsum("i,ijts,j->ts", Sinv[1], J, Sinv[:, 1], optimize=True)
    cov_ge = np.einsum("i,ijts,j->ts", Sinv[0], J, Sinv[:, 1], optimize=True)
    var_g = np.maximum(_sym(var_g), 0.0)
    var_e = np.maximum(_sym(var_e), 0.0)
    aG = float(shrink_G)
    aE = float(shrink_E)
    scaleG = np.full((Tn, Tn), aG, dtype=float); np.fill_diagonal(scaleG, 1.0)
    scaleE = np.full((Tn, Tn), aE, dtype=float); np.fill_diagonal(scaleE, 1.0)
    G_se = np.sqrt(var_g) * scaleG
    E_se = np.sqrt(var_e) * scaleE

    # Delta-method genetic-correlation SE.  The estimator transformation is
    # G_ts -> aG*G_ts off diagonal while the variances remain unchanged.
    w = Sinv[:, 0]
    Tbar = np.einsum("i,ijab,j->ab", w, TT, w, optimize=True)
    base_var_gts = (
        np.einsum("as,ab,bt->ts", D, Tbar, D, optimize=True)
        + np.einsum("ats,ab,bts->ts", Theta, Tbar, Theta, optimize=True)
    )
    cov_gts_gtt = 2.0 * np.einsum("ats,ab,bt->ts", Theta, Tbar, D, optimize=True)
    cov_gts_gss = 2.0 * np.einsum("ats,ab,bs->ts", Theta, Tbar, D, optimize=True)
    cross_same = np.einsum("ats,ab,bts->ts", Theta, Tbar, Theta, optimize=True)
    cov_gtt_gss = 2.0 * cross_same
    vg = np.diag(G0).copy()
    denom = np.sqrt(np.maximum(vg[:, None] * vg[None, :], eps))
    r = aG * G0 / denom
    np.fill_diagonal(r, 1.0)
    d_ts = np.full((Tn, Tn), aG, dtype=float) / denom
    d_tt = -0.5 * r / np.maximum(vg[:, None], eps)
    d_ss = -0.5 * r / np.maximum(vg[None, :], eps)
    var_tt = np.diag(base_var_gts)[:, None]
    var_ss = np.diag(base_var_gts)[None, :]
    var_r = (
        d_ts*d_ts*base_var_gts + d_tt*d_tt*var_tt + d_ss*d_ss*var_ss
        + 2.0*d_ts*d_tt*cov_gts_gtt
        + 2.0*d_ts*d_ss*cov_gts_gss
        + 2.0*d_tt*d_ss*cov_gtt_gss
    )
    var_r = np.maximum(_sym(var_r), 0.0)
    rg_se = np.sqrt(var_r)
    np.fill_diagonal(rg_se, 0.0)

    # Heritability SE uses the full 2x2 sandwich for diagonal (G_tt,E_tt).
    h2 = np.full(Tn, np.nan, dtype=float)
    h2_se = np.full(Tn, np.nan, dtype=float)
    for t in range(Tn):
        g, e = float(G0[t, t]), float(E0[t, t])
        total = g + e
        if total <= eps:
            continue
        h2[t] = g / total
        Jtt = J[:, :, t, t]
        Ctt = Sinv @ Jtt @ Sinv
        grad = np.array([e/(total*total), -g/(total*total)], dtype=float)
        h2_se[t] = math.sqrt(max(float(grad @ Ctt @ grad), 0.0))
    return {
        "G_se": G_se,
        "E_se": E_se,
        "rg_se": rg_se,
        "h2": h2,
        "h2_se": h2_se,
        "h2_ci95": np.column_stack([
            np.maximum(0.0, h2 - 1.96*h2_se),
            np.minimum(1.0, h2 + 1.96*h2_se),
        ]),
        "cov_GE_entry": cov_ge,
        "method": "gaussian_minque_sandwich_preconstraint",
        "constraint_note": (
            "Sandwich covariance is for the unconstrained common-mask MINQUE covariance-entry estimator; "
            "the native FA/PSD fit is smooth but has rotationally non-identifiable factor coordinates, so bootstrap "
            "remains preferred for final constrained G/E and factor uncertainty."
        ),
    }


# ---------------------------------------------------------------------------
# Exact weighted no-copy bootstrap moments
# ---------------------------------------------------------------------------
def _weighted_center_traits(Yraw, weights):
    """Compute weighted training means while retaining trait-specific observation masks.

    Parameters
    ----------
    Yraw : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data. Passed to ``np.divide`` as ``out``.

    weights : array-like or int
        Weights or multiplicities used in this accumulation/resampling step. Align vector
        entries with the indexed sample/variant axis; scalar counts specify the number of
        consecutive items.
    """
    Yraw = np.asarray(Yraw, float)
    w = np.asarray(weights, float).reshape(-1)
    R = np.isfinite(Yraw)
    wr = w[:, None] * R
    denom = wr.sum(axis=0)
    means = np.divide(np.nansum(np.where(R, Yraw * w[:, None], 0.0), axis=0), denom, out=np.zeros(Yraw.shape[1]), where=denom > 0)
    Y = np.where(R, Yraw - means[None, :], 0.0)
    return Y, R.astype(float), means


def _commonmask_lowrank_moments(kernels, Yraw, weights, *, accum_dtype=np.float64):
    """Fast exact unweighted moments for a shared trait observation mask.

    This is especially important for the 30k x 1000 analytic-SE workflow.
    For K=U diag(delta) U' + bulk I,

        Y' K Y = (U'Y)' diag(delta) (U'Y) + bulk Y'Y,

    so a low-rank GRM never incurs a second O(N T^2) multiplication.  The A
    moment matrices are constants over trait pairs under a common mask and are
    obtained from trace/Frobenius identities in the observed animal subset.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Yraw : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    weights : array-like or int
        Weights or multiplicities used in this accumulation/resampling step. Align vector
        entries with the indexed sample/variant axis; scalar counts specify the number of
        consecutive items.

    accum_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``np.empty`` as ``dtype``.
    """
    w = np.asarray(weights, float).reshape(-1)
    if not np.all(w == 1.0):
        return None
    Y, R, means = _weighted_center_traits(Yraw, w)
    if R.shape[1] == 0 or not np.all(R == R[:, [0]]):
        return None
    names = list(kernels)
    ops = {str(k): as_kernel_operator(v, dtype=np.float32) for k, v in kernels.items()}
    n, T = Y.shape
    mask = R[:, 0].astype(bool)
    m = int(mask.sum())
    Y = np.asarray(Y, dtype=accum_dtype)
    q, p = len(names), len(names) + 1
    A = np.empty((p, p, T, T), dtype=accum_dtype)
    B = np.empty((p, T, T), dtype=accum_dtype)
    B_E = _sym(Y.T @ Y)
    B[q] = B_E

    cache = {}
    for name in names:
        op = ops[name]
        if isinstance(op, LowRankKernelOperator):
            Uo = np.asarray(op.U[mask], dtype=accum_dtype)
            d = np.asarray(op.delta, dtype=accum_dtype)
            UtY = np.asarray(op.U, dtype=accum_dtype).T @ Y
            BK = (UtY.T * d[None, :]) @ UtY
            if op.bulk:
                BK += float(op.bulk) * B_E
            colgram = Uo.T @ Uo
            tr_lr = float(np.dot(d, np.diag(colgram)))
            cache[name] = dict(kind='lowrank', U=Uo, d=d, bulk=float(op.bulk), gram=colgram,
                               trace=tr_lr + float(op.bulk) * m)
            B[names.index(name)] = _sym(BK)
        else:
            BK = Y.T @ np.asarray(op.matmat(Y), dtype=accum_dtype)
            B[names.index(name)] = _sym(BK)
            idx = np.flatnonzero(mask)
            Ksub = np.asarray(op.submatrix(idx), dtype=accum_dtype)
            cache[name] = dict(kind='dense', K=Ksub, trace=float(np.trace(Ksub)))

    def frob(a, b):
        """Compute a Frobenius inner product without materializing unnecessary intermediate matrices.

        Parameters
        ----------
        a : array-like
            Numerical operand in ``cache[a]``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state.

        b : array-like
            Numerical operand in ``cache[b]``. Shape must conform to that matrix/vector operation
            and the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``float(np.sum(D * L))``; see the summary and the called implementation for its labeled/numerical representation.
        """
        ca, cb = cache[a], cache[b]
        if ca['kind'] == 'lowrank' and cb['kind'] == 'lowrank':
            Ua, da, ba = ca['U'], ca['d'], ca['bulk']
            Ub, db, bb = cb['U'], cb['d'], cb['bulk']
            C = Ua.T @ Ub
            main = float(np.sum((da[:, None] * db[None, :]) * (C*C)))
            tr_a_lr = ca['trace'] - ba*m
            tr_b_lr = cb['trace'] - bb*m
            return main + bb*tr_a_lr + ba*tr_b_lr + ba*bb*m
        if ca['kind'] == 'dense' and cb['kind'] == 'dense':
            return float(np.sum(ca['K'] * cb['K']))
        # Mixed dense/low-rank case is uncommon in the intended operator path;
        # form only the observed submatrix of the low-rank side.
        if ca['kind'] == 'dense':
            D = ca['K']; lo = cb
        else:
            D = cb['K']; lo = ca
        L = (lo['U'] * lo['d'][None, :]) @ lo['U'].T
        if lo['bulk']:
            L.flat[::m+1] += lo['bulk']
        return float(np.sum(D * L))

    for r, na in enumerate(names):
        for ss in range(r, q):
            nb = names[ss]
            val = frob(na, nb)
            A[r, ss].fill(val); A[ss, r].fill(val)
        tr = cache[na]['trace']
        A[r, q].fill(tr); A[q, r].fill(tr)
    A[q, q].fill(float(m))
    return {'A': A, 'B': B, 'Y0': Y, 'R': R.astype(accum_dtype), 'means': means,
            'kernel_names': names, 'common_mask_fastpath': True}


@cached_moments
def weighted_multi_moments(kernels, Yraw, weights, *, block_size=512, accum_dtype=np.float64):
    """Exact bootstrap moments from animal multiplicities without K[idx,idx].

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Yraw : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    weights : array-like or int
        Weights or multiplicities used in this accumulation/resampling step. Align vector
        entries with the indexed sample/variant axis; scalar counts specify the number of
        consecutive items.

    block_size : int
        Number of variants or rows processed together by the local block iterator. Supply a
        positive count; smaller blocks reduce peak memory at the cost of more iteration
        overhead. See the called iterator for which axis is blocked. Default: ``512``.

    accum_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``_commonmask_lowrank_moments``
        as ``accum_dtype``.

    Returns
    -------
    dict
        Result fields: ``A``, ``B``, ``Y0``, ``R``, ``means``, ``kernel_names``. Field arrays preserve the corresponding input axis order.
    """
    fast = _commonmask_lowrank_moments(kernels, Yraw, weights, accum_dtype=accum_dtype)
    if fast is not None:
        return fast
    ops = {str(k): as_kernel_operator(v, dtype=np.float32) for k, v in kernels.items()}
    names = list(ops)
    n = next(iter(ops.values())).shape[0]
    Y, R, means = _weighted_center_traits(Yraw, weights)
    Y = np.asarray(Y, dtype=accum_dtype)
    R = np.asarray(R, dtype=accum_dtype)
    w = np.asarray(weights, dtype=accum_dtype).reshape(-1)
    wY = w[:, None] * Y
    wR = w[:, None] * R
    T = Y.shape[1]
    q, p = len(names), len(names) + 1
    A = np.zeros((p, p, T, T), dtype=accum_dtype)
    B = np.zeros((p, T, T), dtype=accum_dtype)
    # B_k = Y' D_w K D_w Y; B_I = Y' D_w Y
    for r, name in enumerate(names):
        B[r] = Y.T @ (w[:, None] * ops[name].matmat(wY))
        A[r, q] = A[q, r] = R.T @ ((w * ops[name].diag())[:, None] * R)
    A[q, q] = R.T @ wR
    B[q] = Y.T @ wY
    # A_kl = R' D_w (K_k o K_l) D_w R.
    for r, na in enumerate(names):
        for s in range(r, q):
            nb = names[s]
            M = np.zeros((T, T), dtype=accum_dtype)
            for i0 in range(0, n, int(block_size)):
                i1 = min(n, i0 + int(block_size))
                H = np.asarray(ops[na].row_block(i0, i1), dtype=np.float32) * np.asarray(ops[nb].row_block(i0, i1), dtype=np.float32)
                M += wR[i0:i1].T @ (H @ wR)
            A[r, s] = A[s, r] = _sym(M)
    for r in range(p):
        B[r] = _sym(B[r])
    return {"A": A, "B": B, "Y0": Y, "R": R, "means": means, "kernel_names": names}


class _Welford:
    """Elementwise online moments with NaN-safe counts."""
    def __init__(self, shape):
        """Initialize _Welford with the inputs and resource settings below.

        Parameters
        ----------
        shape : tuple of int or None
            Requested array/distribution extents in axis order. Nonnegative sizes must agree with
            the associated data; None uses the backend's inferred scalar/default shape.
        """
        self.n = np.zeros(shape, dtype=np.int64)
        self.mean = np.zeros(shape, dtype=np.float64)
        self.M2 = np.zeros(shape, dtype=np.float64)

    def update(self, x):
        """Advance the progress counter by the requested increment.

        Parameters
        ----------
        x : array-like
            Numerical operand in ``x[valid] - self.mean[valid]``. Shape must conform to that
            matrix/vector operation and the enclosing prepared state.
        """
        x = np.asarray(x, dtype=float)
        valid = np.isfinite(x)
        n1 = self.n[valid] + 1
        d = x[valid] - self.mean[valid]
        self.mean[valid] += d / n1
        self.M2[valid] += d * (x[valid] - self.mean[valid])
        self.n[valid] = n1

    def merge(self, other):
        """Combine online moment/uncertainty accumulator states.

        Parameters
        ----------
        other : object (see the cited input contract)
            Input for the operation ``other['n']``. See ``vigor.multivariate._Welford.merge`` and
            its caller for the scientific representation; the shown operation constrains the
            required type/shape.
        """
        if isinstance(other, dict):
            on = np.asarray(other["n"], dtype=np.int64)
            om = np.asarray(other["mean"], dtype=float)
            oM2 = np.asarray(other["M2"], dtype=float)
        else:
            on, om, oM2 = other.n, other.mean, other.M2
        valid = on > 0
        both = valid & (self.n > 0)
        only = valid & (self.n == 0)
        if np.any(only):
            self.n[only] = on[only]
            self.mean[only] = om[only]
            self.M2[only] = oM2[only]
        if np.any(both):
            n1 = self.n[both].astype(float)
            n2 = on[both].astype(float)
            nt = n1 + n2
            d = om[both] - self.mean[both]
            self.mean[both] += d * (n2 / nt)
            self.M2[both] += oM2[both] + d * d * (n1 * n2 / nt)
            self.n[both] += on[both]

    def state(self):
        """Fit the training-fold covariance and prepare its conditional prediction state.

        Returns
        -------
        dict
            Result fields: ``n``, ``mean``, ``M2``. Field arrays preserve the corresponding input axis order.
        """
        return {"n": self.n, "mean": self.mean, "M2": self.M2}

    def std(self):
        """Extract standard deviations from the online replicate variance accumulator.

        Returns
        -------
        object
            Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
        """
        out = np.full_like(self.mean, np.nan)
        good = self.n > 1
        out[good] = np.sqrt(self.M2[good] / (self.n[good] - 1))
        return out


def align_factor_loadings(reference, loadings):
    """Procrustes + Hungarian + sign alignment for bootstrap FA draws.

    Parameters
    ----------
    reference : array-like, table or fitted object
        Reference input or fitted state supplying alignment, initialization or baseline
        quantities. Match the axes/component order of the operation; see the corresponding
        fit/preparation routine for required fields.

    loadings : array-like or fitted basis
        Trait/feature × retained-factor loading matrix or prepared basis. Column order
        identifies factor directions and must agree with the scores used for projection.

    Returns
    -------
    object
        Computed result from ``(L, {'permutation': order, 'sign': signs, 'congruence': congruence})``; see the summary and the called implementation for its labeled/numerical representation.
    """
    R = np.asarray(reference, float)
    L = np.asarray(loadings, float)
    if R.shape[0] != L.shape[0]:
        raise ValueError("loading row dimensions differ")
    r = min(R.shape[1], L.shape[1])
    R = R[:, :r]
    L = L[:, :r]
    try:
        Q, _ = orthogonal_procrustes(L, R)
        L = L @ Q
    except Exception:
        pass
    nr = np.sqrt(np.sum(R * R, axis=0))
    nl = np.sqrt(np.sum(L * L, axis=0))
    corr = (R.T @ L) / np.maximum(nr[:, None] * nl[None, :], 1e-30)
    ri, ci = linear_sum_assignment(-np.abs(corr))
    order = ci[np.argsort(ri)]
    L = L[:, order]
    c = np.sum(R * L, axis=0)
    signs = np.where(c < 0, -1.0, 1.0)
    L = L * signs[None, :]
    congruence = np.sum(R * L, axis=0) / np.maximum(np.sqrt(np.sum(R * R, axis=0) * np.sum(L * L, axis=0)), 1e-30)
    return L, {"permutation": order, "sign": signs, "congruence": congruence}


def _varimax_loadings(loadings, *, maxiter=500, tol=1e-7):
    """Orthogonal varimax rotation; preserves ``L @ L.T``.

    Parameters
    ----------
    loadings : array-like or fitted basis
        Trait/feature × retained-factor loading matrix or prepared basis. Column order
        identifies factor directions and must agree with the scores used for projection.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``500``.

    tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``.
    """
    L = np.asarray(loadings, dtype=float)
    if L.ndim != 2 or L.shape[1] <= 1:
        return L.copy()
    p, k = L.shape
    R = np.eye(k)
    last = 0.0
    for _ in range(int(maxiter)):
        X = L @ R
        col_ss = np.sum(X * X, axis=0)
        U, sing, Vt = np.linalg.svd(
            L.T @ (X**3 - (1.0 / max(p, 1)) * X * col_ss[None, :]),
            full_matrices=False,
        )
        R = U @ Vt
        obj = float(np.sum(sing))
        if last and abs(obj - last) <= float(tol) * max(1.0, abs(last)):
            break
        last = obj
    return L @ R


def _stability_loadings(C, config):
    """Post-fit decomposition used only for bootstrap factor-stability output.

    This preserves the 2.5.1 distinction between covariance-estimation rank and
    the lower rank used for interpretable/bootstrapped FA loadings.

    Parameters
    ----------
    C : array-like
        Numerical operand in ``np.asarray(C).shape[0]``. Shape must conform to that
        matrix/vector operation and the enclosing prepared state.

    config : mapping or None
        Named settings or metadata forwarded to the specific operation below. See that
        operation's argument/schema contract for accepted fields; None uses its default/empty
        configuration.
    """
    cfg = {} if config is None else (dict(config) if isinstance(config, dict) else {"rank": int(config)})
    rank = int(cfg.get("rank", min(10, np.asarray(C).shape[0])))
    method = str(cfg.get("method", "fa"))
    standardize = bool(cfg.get("standardize", False))
    preserve_diag = bool(cfg.get("preserve_diag", True))
    jitter = float(cfg.get("jitter", 1e-8))
    maxiter = int(cfg.get("maxiter", 1000))
    tol = float(cfg.get("tol", 1e-8))
    dec = _legacy.decompose_covariance(
        np.asarray(C, float), rank=rank, method=method,
        standardize=standardize, preserve_diag=preserve_diag,
        jitter=jitter, maxiter=maxiter, tol=tol,
    )
    L = np.asarray(dec["loadings"], float)
    rotation = cfg.get("rotation", None)
    if rotation is not None and str(rotation).lower() not in {"none", "false", "off"}:
        if str(rotation).lower() != "varimax":
            raise ValueError("bootstrap factor rotation must be None or 'varimax'")
        L = _varimax_loadings(L)
    return L


def _factor_target_matrix(mats, source, genetic_names):
    """Select or sum covariance components for a requested bootstrap factor target.

    Parameters
    ----------
    mats : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    source : path-like or genotype source
        Input file/store location or opened source consumed by this adapter. See the selected
        reader for physical format, sample order and supported block representations.

    genetic_names : array-like or numeric scalar
        Input for the operation ``sum((mats[n] for n in genetic_names),
        np.zeros_like(next(iter(mats.values()))))``. See
        ``vigor.multivariate._factor_target_matrix`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape.
    """
    src = str(source)
    if src.upper() == "G":
        return sum((mats[n] for n in genetic_names), np.zeros_like(next(iter(mats.values()))))
    if src.upper() == "E":
        return mats["E"]
    if src in mats:
        return mats[src]
    # tolerate case-only differences in named A/D components
    by_lower = {str(k).lower(): k for k in mats}
    if src.lower() in by_lower:
        return mats[by_lower[src.lower()]]
    raise KeyError(f"unknown bootstrap factor component {source!r}; available={list(mats)} plus 'G'")


_BOOTSTRAP_STATE = None


def _bootstrap_worker_init(state):
    """Bootstrap worker init.

    Parameters
    ----------
    state : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes.
    """
    global _BOOTSTRAP_STATE
    _BOOTSTRAP_STATE = state


def _bootstrap_fit_counts(counts, state=None):
    """Bootstrap fit counts.

    Parameters
    ----------
    counts : array-like or int
        Weights or multiplicities used in this accumulation/resampling step. Align vector
        entries with the indexed sample/variant axis; scalar counts specify the number of
        consecutive items. Passed to ``_phenotypic_variance_moment`` as ``sample_weights``.

    state : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes. Default: ``None``. None delegates to the local fallback shown in this
        body; it is not an additional numeric/category value.
    """
    st = _BOOTSTRAP_STATE if state is None else state
    if st is None:
        raise RuntimeError("bootstrap worker state is not initialized")
    ctx = threadpool_limits(limits=int(st["blas_threads"]), user_api="blas") if threadpool_limits is not None else nullcontext()
    with ctx:
        prepared = st.get("prepared_moments")
        moments = prepared.compute(counts) if prepared is not None else weighted_multi_moments(st["kernels"], st["Yraw"], counts, block_size=st["block_size"])
        overlap_raw = np.asarray(moments["A"][-1, -1], dtype=float).copy()
        if st.get("variance_closure", False):
            cm = _phenotypic_variance_moment(st["Yraw"], sample_weights=counts, eps=max(float(st["eps"]),1e-12))
            cw = np.asarray(cm["precision"],float) * max(float(st.get("variance_closure_strength",1.0)),0.0)
            moments = _augment_moments_variance_closure(moments, cm["variance"], cw)
        solver = str(st.get("solver", "lbfgs")).lower()
        if solver in {"spectral", "spectral_psd", "closed_form", "projected_psd"}:
            fit = fit_mom_projected(
                moments, ranks=st["ranks"], names=st["names"], ridge=st["ridge"],
                structure="psd", spectral_weighting=st.get("spectral_weighting", "rank1"),
                spectral_fa_sweeps=st.get("spectral_fa_sweeps", 4),
                maxiter=st.get("projected_maxiter", 80), tol=st.get("projected_tol", 1e-7),
                step_scale=st.get("projected_step_scale", 0.95), eps=st["eps"],
            )
        elif solver in {"spectral_fa", "fa_spectral", "projected", "projected_fa"}:
            fit = fit_mom_projected(
                moments, ranks=st["ranks"], names=st["names"], ridge=st["ridge"],
                structure="fa", spectral_weighting=st.get("spectral_weighting", "rank1"),
                spectral_fa_sweeps=st.get("spectral_fa_sweeps", 4),
                maxiter=st.get("projected_maxiter", 80), tol=st.get("projected_tol", 1e-7),
                step_scale=st.get("projected_step_scale", 0.95), eps=st["eps"],
            )
        elif solver in {"spectral_init", "spectral_psd_init"}:
            fit = fit_mom_spectral(
                moments, ranks=st["ranks"], names=st["names"], ridge=st["ridge"],
                structure="psd", spectral_weighting=st.get("spectral_weighting", "rank1"),
                spectral_fa_sweeps=st.get("spectral_fa_sweeps", 4), eps=st["eps"],
            )
        elif solver in {"spectral_fa_init", "fa_spectral_init"}:
            fit = fit_mom_spectral(
                moments, ranks=st["ranks"], names=st["names"], ridge=st["ridge"],
                structure="fa", spectral_weighting=st.get("spectral_weighting", "rank1"),
                spectral_fa_sweeps=st.get("spectral_fa_sweeps", 4), eps=st["eps"],
            )
        elif solver in {"spectral_refine", "spectral_fa_refine"}:
            fit = fit_mom_spectral_refine(
                moments, ranks=st["ranks"], names=st["names"], ridge=st["ridge"],
                structure="fa", spectral_weighting=st.get("spectral_weighting", "rank1"),
                spectral_fa_sweeps=st.get("spectral_fa_sweeps", 4),
                refine_maxiter=st.get("spectral_refine_maxiter", 5), gtol=st["gtol"],
                ftol=st["ftol"], eps=st["eps"],
            )
        else:
            fit = fit_mom_factor_analytic(
                moments, ranks=st["ranks"], names=st["names"], ridge=st["ridge"],
                warm_start=st["warm_specs"], maxiter=st["maxiter"], gtol=st["gtol"],
                ftol=st["ftol"], eps=st["eps"],
                structures=st["structures"], rotations=st["rotations"],
                factor_lambda=st["factor_lambda"], factor_group_lambda=st["factor_group_lambda"],
                factor_adaptive=st["factor_adaptive"], factor_relaxed_refit=st["factor_relaxed_refit"],
                factor_support_tol=st["factor_support_tol"], factor_sparse_maxiter=st["factor_sparse_maxiter"],
                factor_sparse_tol=st["factor_sparse_tol"], factor_auto_fraction=st["factor_auto_fraction"],
            )

        # The bootstrap must summarize the same estimator used by mvBLUP.
        # 2.8.2 stopped at the raw replicate fit, silently omitting G/E shrinkage
        # and overlap-aware E structure from bootstrap uncertainty.
        policy = st.get("regularization_policy")
        if policy is not None and isinstance(fit.get("specs"), dict):
            overlap = overlap_raw
            raw_specs = fit["specs"]
            final_specs = _apply_regularization_policy(
                raw_specs, st["names"], overlap, policy,
                min_E_pair_overlap=st.get("min_E_pair_overlap", 2), eps=st["eps"],
            )
            fit = dict(fit)
            fit["raw_specs"] = raw_specs
            fit["specs"] = final_specs
            fit["matrices"] = {name: final_specs[name].materialize() for name in st["names"]}
            fit["bootstrap_overlap"] = overlap
        return fit

def _bootstrap_batch(batch, progress_callback=None):
    """Fit a batch and return Welford summaries, not full replicate matrices.

    Parameters
    ----------
    batch : object (see the cited input contract)
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller.

    progress_callback : callable or None
        Callback invoked at the corresponding fitting/prediction/scan stage. Accept the argument
        order shown by its call below and return the representation consumed there; None
        disables an optional callback or uses the default implementation. Default: ``None``.
    """
    st = _BOOTSTRAP_STATE
    T = st["T"]
    names = st["names"]
    genetic_names = [n0 for n0 in names if n0 != "E"]
    local = {name: _Welford((T, T)) for name in names}
    rg_local = _Welford((T, T))
    factor_refs = st["factor_refs"]
    factor_targets = st["factor_targets"]
    target_names = list(factor_refs)
    congruence = {name: [] for name in target_names}
    loading_stats = {name: _Welford(factor_refs[name].shape) for name in target_names}
    draws = {name: [] for name in target_names} if st["factor_draws"] else None
    failures = []
    h2_draws = []
    entry_components = list(st.get("bootstrap_draw_components", []))
    entry_rows = np.asarray(st.get("bootstrap_entry_rows", []), dtype=np.intp)
    entry_cols = np.asarray(st.get("bootstrap_entry_cols", []), dtype=np.intp)
    entry_draws = {name: [] for name in entry_components}
    entry_ids = []
    success = 0
    for b, counts in batch:
        try:
            fit = _bootstrap_fit_counts(counts)
        except Exception as exc:
            failures.append((int(b), repr(exc)))
            if progress_callback is not None: progress_callback(1)
            continue
        if not fit["success"]:
            # L-BFGS can hit its iteration cap after producing a valid PSD
            # iterate.  Retain that replicate for uncertainty summaries and
            # factor draws; callers still receive the diagnostic failure.
            failures.append((int(b), fit.get("message", "fit did not converge")))
            if not isinstance(fit.get("matrices"), dict):
                if progress_callback is not None: progress_callback(1)
                continue
        success += 1
        mats = fit["matrices"]
        for name in names:
            local[name].update(mats[name])
        for target in target_names:
            target_spec = factor_targets[target]
            source = target_spec["source"]
            if target_spec.get("native", False):
                L0 = fit["specs"][source].factor
            else:
                C = _factor_target_matrix(mats, source, genetic_names)
                L0 = _stability_loadings(C, target_spec.get("config"))
            if factor_refs[target].shape[1] and L0.shape[1]:
                # Bootstrap PSD clipping can change the *effective* number of
                # nonzero factor columns even when the requested rank is fixed
                # (especially for rank='full').  Factor summaries are ancillary
                # to covariance uncertainty, so align them in the fixed reference
                # width rather than letting a replicate-specific rank crash the
                # whole bootstrap.  Native spectral factors are ordered by
                # decreasing retained variance; zero padding represents clipped
                # boundary directions.
                rref = factor_refs[target].shape[1]
                if L0.shape[1] < rref:
                    L0 = np.pad(L0, ((0, 0), (0, rref - L0.shape[1])))
                elif L0.shape[1] > rref:
                    L0 = L0[:, :rref]
                L, info = align_factor_loadings(factor_refs[target], L0)
                congruence[target].append(info["congruence"])
                loading_stats[target].update(L)
                if draws is not None:
                    draws[target].append(L.astype(np.float32, copy=False))
        G = sum((mats[n0] for n0 in genetic_names), np.zeros((T, T)))
        Rg, _, _ = _legacy._rg_from_G_psd(G)
        rg_local.update(Rg)
        total_diag = np.diag(G) + np.diag(mats["E"])
        h2_draws.append(np.divide(np.diag(G), total_diag, out=np.full(T, np.nan), where=total_diag > 0))
        if entry_rows.size:
            available = {"G": G, "E": mats["E"], "Rg": Rg, **{n0: mats[n0] for n0 in genetic_names}}
            entry_ids.append(int(b))
            for component in entry_components:
                if component not in available:
                    raise KeyError(f"bootstrap draw component {component!r} is unavailable")
                entry_draws[component].append(np.asarray(available[component][entry_rows, entry_cols], dtype=np.float32))
        if progress_callback is not None: progress_callback(1)
    return {
        "success": success,
        "failures": failures,
        "stats": {name: local[name].state() for name in names},
        "rg": rg_local.state(),
        "congruence": {name: np.asarray(congruence[name]) for name in target_names},
        "loading_stats": {name: loading_stats[name].state() for name in target_names},
        "draws": None if draws is None else {
            name: (np.stack(draws[name]) if draws[name] else None) for name in target_names
        },
        "h2_draws": np.stack(h2_draws) if h2_draws else np.empty((0, T)),
        "entry_ids": np.asarray(entry_ids, dtype=np.int64),
        "entry_draws": {name: (np.stack(entry_draws[name]) if entry_draws[name] else np.empty((0, entry_rows.size), dtype=np.float32))
                        for name in entry_components},
    }

def bootstrap_factor_analytic(
    kernels,
    traits,
    *,
    full_fit,
    ranks,
    names,
    ridge=None,
    n_boot=100,
    random_state=None,
    n_jobs="auto",
    cache_gb=0.0,
    batch_size=None,
    progress=True,
    block_size=512,
    maxiter=250,
    gtol=1e-6,
    ftol=1e-9,
    eps=1e-8,
    blas_threads_per_worker=1,
    factor_draws="auto",
    factor_targets=None,
    bootstrap_groups=None,
    bootstrap_unit="auto",
    solver="lbfgs",
    spectral_weighting="rank1",
    spectral_fa_sweeps=4,
    spectral_refine_maxiter=5,
    projected_maxiter=80,
    projected_tol=1e-7,
    projected_step_scale=0.95,
    structures=None,
    rotations=None,
    factor_lambda=None,
    factor_group_lambda=None,
    factor_adaptive=True,
    factor_relaxed_refit=True,
    factor_support_tol=1e-7,
    factor_sparse_maxiter=120,
    factor_sparse_tol=1e-7,
    factor_auto_fraction=0.05,
    regularization_policy=None,
    min_E_pair_overlap=2,
    ci=(0.025, 0.50, 0.975),
    ci_entries="diag",
    return_draws=0,
    draw_components=("G", "E", "Rg"),
    variance_closure=False,
    variance_closure_strength=1.0,
):
    """Exact multiplicity bootstrap without materialising ``K[idx, idx]``.

    Replicates are represented only by animal count vectors.  A full-data FA
    fit initializes every replicate; covariance and genetic-correlation SEs are
    reduced online with Welford accumulators.  Parallel workers process batches
    so full T x T replicate matrices never cross the process boundary.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    full_fit : array-like, table or fitted object
        Reference input or fitted state supplying alignment, initialization or baseline
        quantities. Match the axes/component order of the operation; see the corresponding
        fit/preparation routine for required fields.

    ranks : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine.

    names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names.

    ridge : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    n_boot : int
        Number of bootstrap replicates. Zero disables bootstrap when supported; positive counts
        estimate sampling variation by the resampling scheme used here. Default: ``100``. Passed
        to ``StageProgress`` as ``total``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``None``.

    n_jobs : int or str
        Worker-process count for bootstrap; a positive integer fixes concurrency, while 'auto'
        resolves a bounded process count from CPU availability and the replicate workload.
        Default: ``'auto'``. Source comparisons: ``int(n_jobs) <= 1``; ``n_jobs == 1``. See the
        rejection/fallback branches for enforcement.

    cache_gb : float
        Memory budget in GiB for cached moment terms. Zero disables the cache; positive budgets
        permit only cached terms fitting within the limit. Default: ``0.0``.

    batch_size : int or None
        Replicates dispatched together to each worker. Positive integers set dispatch
        granularity; None chooses the worker-count/replicate-dependent batch size. Default:
        ``None``.

    progress : bool
        Whether to emit progress/status reporting during this operation. False disables the
        corresponding reporting path. Default: ``True``. Passed to ``StageProgress`` as
        ``enabled``.

    block_size : int
        Number of variants or rows processed together by the local block iterator. Supply a
        positive count; smaller blocks reduce peak memory at the cost of more iteration
        overhead. See the called iterator for which axis is blocked. Default: ``512``. Passed to
        ``PreparedWeightedMoments`` as ``block_size``.

    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``250``.

    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-06``.

    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-09``.

    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``.

    blas_threads_per_worker : int or str
        BLAS thread limit during numerical operations. Positive integers select an explicit
        thread count; auto uses the routine's workload-dependent thread policy. Default: ``1``.

    factor_draws : bool or str
        Whether to retain aligned factor draws. In bootstrap_factor_analytic, 'auto' checks the
        complete loading-draw allocation against 512 MiB; True retains and False omits draws.
        Other draw helpers follow their local boolean/count contract. Default: ``'auto'``.

    factor_targets : mapping or None
        Named bootstrap factor targets containing source component, reference loadings and
        optional decomposition config. None uses native fitted component factors; references
        must match current trait rows/ranks. Default: ``None``.

    bootstrap_groups : sequence, str or None
        Grouping labels used to select a store subgroup or partition observations. For
        resampling, give one cluster label per animal so a cluster is sampled as a unit.
        Default: ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.

    bootstrap_unit : str
        Resampling unit: 'auto' chooses clusters when bootstrap_groups is supplied and
        individuals otherwise; 'individual' samples animals separately; 'cluster' samples whole
        groups and requires one group label per animal. Default: ``'auto'``.

    solver : str
        Input for the operation ``str(solver)``. See
        ``vigor.multivariate.bootstrap_factor_analytic`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``'lbfgs'``.

    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.

    spectral_fa_sweeps : int
        Number of alternating low-rank/specific-diagonal updates in each spectral FA projection;
        positive counts improve initializer consistency at extra cost. Default: ``4``.

    spectral_refine_maxiter : int
        Maximum L-BFGS polishing iterations after spectral initialization; positive values
        control this optional refinement stage. Default: ``5``.

    projected_maxiter, projected_tol, projected_step_scale : int, float, float
        Projected-solver iteration cap, stopping tolerance and step scale. These
        must match the original covariance estimator.
    structures, rotations : str, sequence, mapping or None
        Per-component factor geometry and orientation. None inherits the full
        fit's recorded geometry; sparse/PCA fits are never replaced by dense FA.
    factor_lambda, factor_group_lambda : float, sequence, mapping or None
        Loading and group penalties, passed unchanged to replicate refits.
    factor_adaptive, factor_relaxed_refit : bool
        Adaptive penalty weights and support-fixed relaxed refitting controls.
    factor_support_tol, factor_sparse_tol, factor_auto_fraction : float
        Support cutoff, sparse convergence tolerance and automatic penalty scale.
    factor_sparse_maxiter : int
        Maximum sparse selection iterations per bootstrap refit.

    regularization_policy : mapping or sequence or None
        Initial/final component specifications or selected factor/path support used by this
        fitting stage. Match the trait dimension, component names and factor ranks of the
        current model; None uses the local initial/default state. Default: ``None``.

    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``.

    ci : sequence of float
        Quantile probabilities for bootstrap summaries, each finite and in [0, 1]. They
        determine the reported lower/central/upper intervals rather than changing the fitted
        covariance. Default: ``(0.025, 0.5, 0.975)``.

    ci_entries : str, sequence of pairs or None
        Bootstrap covariance entry selection: 'diag'/'diagonal'/'variances' uses variances,
        'all'/'lower'/'lower_triangle' the lower triangle, and None/'none'/'off' omits entries.
        Explicit pairs contain valid trait indices/names. Default: ``'diag'``.

    return_draws : int
        Maximum raw covariance/posterior draws included in the result. Zero omits raw draws; a
        positive count caps stored output according to the draw backend. Default: ``0``.
        Source-recognized literal values: ``all``. These select the corresponding branches
        below; comparison evidence alone does not establish an exhaustive enum.

    draw_components : sequence of str
        Covariance/correlation components for raw bootstrap draws: 'G' is total genetic
        covariance, 'E' residual covariance and 'Rg' genetic correlation. Names must match the
        draw components supported by bootstrap_factor_analytic. Default: ``('G', 'E', 'Rg')``.

    variance_closure : bool, str or None
        Marginal variance closure: True/'auto'/'soft'/'moment'/'weighted' adds the
        information-weighted observed-variance moment (except MINQUE);
        False/None/'off'/'none'/'false'/'diagnostic' omits that objective term while retaining
        diagnostics. Default: ``False``.

    variance_closure_strength : float
        Multiplier on the observed marginal-variance moment precision. Positive values favor
        agreement between summed modeled variances and observed phenotype variance; negative
        values are clamped to zero. Default: ``1.0``.

    Returns
    -------
    object
        Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
    """
    Yraw = traits.to_numpy(float, copy=True) if isinstance(traits, pd.DataFrame) else np.asarray(traits, float)
    n, T = Yraw.shape
    probs = np.asarray(ci, dtype=float).reshape(-1)
    if probs.size == 0 or np.any(~np.isfinite(probs)) or np.any((probs < 0) | (probs > 1)):
        raise ValueError("bootstrap ci probabilities must lie in [0,1]")
    if isinstance(ci_entries, str):
        key = ci_entries.lower()
        if key in {"diag", "diagonal", "variances"}:
            entry_rows = np.arange(T, dtype=np.intp); entry_cols = entry_rows.copy()
        elif key in {"all", "lower", "lower_triangle"}:
            entry_rows, entry_cols = np.tril_indices(T)
        elif key in {"none", "off"}:
            entry_rows = entry_cols = np.array([], dtype=np.intp)
        else:
            raise ValueError("bootstrap ci_entries must be 'diag', 'all', 'none', or a sequence of pairs")
    elif ci_entries is None:
        entry_rows = entry_cols = np.array([], dtype=np.intp)
    else:
        pairs = list(ci_entries)
        colnames = list(traits.columns) if isinstance(traits, pd.DataFrame) else list(range(T))
        name_to_i = {str(v): i for i, v in enumerate(colnames)}
        rr=[]; cc=[]
        for pair in pairs:
            if len(pair) != 2:
                raise ValueError("every bootstrap ci entry must be a (trait_i, trait_j) pair")
            a,b = pair
            ia = int(a) if isinstance(a, (int, np.integer)) else name_to_i.get(str(a), None)
            ib = int(b) if isinstance(b, (int, np.integer)) else name_to_i.get(str(b), None)
            if ia is None or ib is None or not (0 <= ia < T and 0 <= ib < T):
                raise KeyError(f"unknown bootstrap CI trait pair {pair!r}")
            rr.append(ia); cc.append(ib)
        entry_rows=np.asarray(rr,dtype=np.intp); entry_cols=np.asarray(cc,dtype=np.intp)
    draw_components = [str(x) for x in draw_components]
    if n_jobs == "auto":
        n_jobs = min(max(1, (os.cpu_count() or 2) - 1), 15, max(1, int(n_boot)))
    n_jobs = max(1, min(int(n_jobs), max(1,int(n_boot))))
    from .bootstrap_moments import PreparedWeightedMoments
    fork_available = "fork" in mp.get_all_start_methods()
    # Avoid copying a large optional product cache into every spawn worker.
    cache_budget = cache_gb if n_jobs == 1 or fork_available else 0.0
    prep_start = time.perf_counter()
    prepared_moments = PreparedWeightedMoments(kernels, Yraw, block_size=block_size, cache_gb=cache_budget)
    preparation_seconds = time.perf_counter() - prep_start
    warm_specs = {name: full_fit["specs"][name] for name in names}
    genetic_names = [n0 for n0 in names if n0 != "E"]
    if factor_targets is None:
        factor_targets = {
            name: {"source": name, "native": True, "reference": full_fit["specs"][name].factor}
            for name in names
        }
    else:
        factor_targets = {str(k): dict(v) for k, v in factor_targets.items()}
    factor_refs = {name: np.asarray(spec["reference"], float) for name, spec in factor_targets.items()}
    target_names = list(factor_refs)
    if factor_draws == "auto":
        # Keep aligned draws by default while bounding their storage.  Covariance
        # matrices themselves are never retained.
        total_rank = sum(factor_refs[name].shape[1] for name in target_names)
        factor_draws = (int(n_boot) * T * total_rank * np.dtype(np.float32).itemsize) <= (512 * 1024**2)
    factor_draws = bool(factor_draws)
    rng = np.random.default_rng(random_state)
    unit = str(bootstrap_unit).lower()
    if unit == "auto":
        unit = "cluster" if bootstrap_groups is not None else "individual"
    if unit not in {"individual", "cluster"}:
        raise ValueError("bootstrap_unit must be 'auto', 'individual', or 'cluster'")
    if unit == "cluster":
        if bootstrap_groups is None:
            raise ValueError("bootstrap_unit='cluster' requires bootstrap_groups")
        g = np.asarray(bootstrap_groups)
        if g.shape[0] != n:
            raise ValueError("bootstrap_groups must have one label per animal")
        # Sample groups with replacement, but represent every replicate only by
        # per-animal multiplicities. This retains the 2.6 weighted/no-GRM-copy path.
        unique, inv = np.unique(g.astype(str), return_inverse=True)
        counts_list = []
        for _ in range(int(n_boot)):
            gc = np.bincount(rng.integers(0, len(unique), size=len(unique)), minlength=len(unique))
            counts_list.append(gc[inv].astype(np.int32, copy=False))
    else:
        counts_list = [np.bincount(rng.integers(0, n, size=n), minlength=n).astype(np.int32, copy=False) for _ in range(int(n_boot))]
    stat = {name: _Welford((T, T)) for name in names}
    rg_stat = _Welford((T, T))
    draws_acc = {name: [] for name in target_names} if factor_draws else None
    cong_acc = {name: [] for name in target_names}
    loading_stat = {name: _Welford(factor_refs[name].shape) for name in target_names}
    h2_draws_acc = []
    entry_ids_acc = []
    entry_draws_acc = {name: [] for name in draw_components}
    success = 0
    failures = []
    state = {
        "kernels": kernels, "Yraw": Yraw, "prepared_moments": prepared_moments, "ranks": ranks, "names": names,
        "ridge": ridge, "warm_specs": warm_specs, "block_size": int(block_size),
        "maxiter": int(maxiter), "gtol": float(gtol), "ftol": float(ftol),
        "eps": float(eps), "blas_threads": int(blas_threads_per_worker),
        "T": T, "factor_refs": factor_refs, "factor_targets": factor_targets,
        "factor_draws": bool(factor_draws),
        "solver": str(solver),
        "spectral_weighting": str(spectral_weighting),
        "spectral_fa_sweeps": int(spectral_fa_sweeps),
        "spectral_refine_maxiter": int(spectral_refine_maxiter),
        "projected_maxiter": int(projected_maxiter),
        "projected_tol": float(projected_tol),
        "projected_step_scale": float(projected_step_scale),
        "structures": structures if structures is not None else full_fit.get("factor_structures"),
        "rotations": rotations if rotations is not None else full_fit.get("factor_rotations"),
        "factor_lambda": factor_lambda,
        "factor_group_lambda": factor_group_lambda,
        "factor_adaptive": bool(factor_adaptive),
        "factor_relaxed_refit": bool(factor_relaxed_refit),
        "factor_support_tol": float(factor_support_tol),
        "factor_sparse_maxiter": int(factor_sparse_maxiter),
        "factor_sparse_tol": float(factor_sparse_tol),
        "factor_auto_fraction": float(factor_auto_fraction),
        "regularization_policy": regularization_policy,
        "min_E_pair_overlap": int(min_E_pair_overlap),
        "bootstrap_entry_rows": entry_rows,
        "bootstrap_entry_cols": entry_cols,
        "bootstrap_draw_components": draw_components,
        "variance_closure": bool(variance_closure),
        "variance_closure_strength": float(variance_closure_strength),
    }

    def consume(summary):
        """Update online summaries with one completed bootstrap replicate.

        Parameters
        ----------
        summary : str
            Posterior reduction: 'mean' averages chain/draw values, 'median' takes their median and
            'none' preserves draws where that method supports unreduced output.
        """
        nonlocal success
        success += int(summary["success"])
        failures.extend(summary["failures"])
        for name in names:
            stat[name].merge(summary["stats"][name])
        for name in target_names:
            cc = summary["congruence"][name]
            if cc.size:
                cong_acc[name].append(cc)
            loading_stat[name].merge(summary["loading_stats"][name])
            if draws_acc is not None and summary["draws"][name] is not None:
                draws_acc[name].append(summary["draws"][name])
        rg_stat.merge(summary["rg"])
        if summary.get("h2_draws") is not None and len(summary["h2_draws"]):
            h2_draws_acc.append(summary["h2_draws"])
        if summary.get("entry_ids") is not None and len(summary["entry_ids"]):
            entry_ids_acc.append(summary["entry_ids"])
            for component in draw_components:
                arr = summary.get("entry_draws", {}).get(component)
                if arr is not None and len(arr):
                    entry_draws_acc[component].append(arr)

    global _BOOTSTRAP_STATE
    resolved_batch_size = (min(8, max(1, int(math.ceil(int(n_boot) / max(n_jobs * 8, 1)))))) if batch_size is None else int(batch_size)
    if resolved_batch_size < 1:
        raise ValueError("bootstrap_batch_size must be positive")
    bootstrap_start = time.perf_counter()
    with StageProgress(total=int(n_boot), desc="Bootstrapping", enabled=progress, unit="replicate") as bbar:
        bbar.stage(f"Bootstrapping: {n_jobs} workers, {blas_threads_per_worker} BLAS threads/worker")
        try:
            if int(n_jobs) <= 1:
                _bootstrap_worker_init(state)
                consume(_bootstrap_batch(list(enumerate(counts_list)), progress_callback=bbar.update))
            else:
                # Small completed batches provide responsive progress and work
                # balancing; each worker keeps the same immutable prepared state.
                indexed = list(enumerate(counts_list))
                batches = [indexed[i:i+resolved_batch_size] for i in range(0,len(indexed),resolved_batch_size)]
                nj = min(int(n_jobs), int(n_boot))
                mp_context = mp.get_context("fork") if fork_available else None
                _BOOTSTRAP_STATE = state if fork_available else None
                ex_kwargs = {"max_workers": nj, "mp_context": mp_context}
                if not fork_available:
                    ex_kwargs.update(initializer=_bootstrap_worker_init, initargs=(state,))
                with ProcessPoolExecutor(**ex_kwargs) as ex:
                    futures = {ex.submit(_bootstrap_batch, batch): len(batch) for batch in batches}
                    for future in as_completed(futures):
                        try:
                            consume(future.result())
                            bbar.update(futures[future])
                        except Exception as exc:
                            failures.append((-1, repr(exc)))
                        bbar.stage(f"Bootstrapping: {n_jobs} workers, {success} accepted")
        finally:
            # Release GRM/cache references on serial runs and on exceptions too.
            _BOOTSTRAP_STATE = None
    bootstrap_seconds = time.perf_counter() - bootstrap_start

    out = {
        "n_boot": int(n_boot), "n_boot_success": int(success), "failures": failures,
        "cov_se": {name: stat[name].std() for name in names},
        "cov_mean": {name: stat[name].mean for name in names},
        "rg_se": rg_stat.std(), "rg_mean": rg_stat.mean,
        "strategy": "weighted_no_grm_copy", "warm_start": True,
        "n_jobs": int(n_jobs), "worker_reduction": "welford_batch",
        "batch_size": resolved_batch_size,
        "preparation_seconds": preparation_seconds, "fit_seconds": bootstrap_seconds,
        "moment_cache": dict(prepared_moments.diagnostics),
        "factor_draws_enabled": bool(factor_draws),
        "bootstrap_unit": unit,
        "no_grm_copy": True,
        "covariance_solver": str(solver),
    }
    h2d = np.concatenate(h2_draws_acc, axis=0) if h2_draws_acc else np.empty((0, T))
    out["h2_draws"] = h2d.astype(np.float32, copy=False)
    out["ci_probs"] = probs.copy()
    if len(h2d):
        out["h2_percentile_ci"] = np.nanquantile(h2d, probs, axis=0)
    else:
        out["h2_percentile_ci"] = np.full((len(probs), T), np.nan)

    # Exact percentile intervals for requested covariance entries.  The default
    # is only the diagonal, which is tiny even for T=1000 and guarantees that
    # variance plots can use one-sided/non-negative bootstrap intervals instead
    # of estimate +/- 1.96*SE.  Full lower-triangle draws are opt-in.
    if entry_ids_acc:
        entry_ids_all = np.concatenate(entry_ids_acc)
        order = np.argsort(entry_ids_all)
        entry_ids_all = entry_ids_all[order]
    else:
        entry_ids_all = np.array([], dtype=np.int64); order = np.array([], dtype=np.int64)
    cov_entry_ci = {}
    cov_entry_draws = {}
    for component in draw_components:
        if entry_draws_acc[component]:
            vals = np.concatenate(entry_draws_acc[component], axis=0)[order]
            cov_entry_ci[component] = np.nanquantile(vals, probs, axis=0)
            keep = 0
            if isinstance(return_draws, str) and return_draws.lower() == "all":
                keep = len(vals)
            elif return_draws is True:
                keep = len(vals)
            elif return_draws not in {False, None}:
                keep = max(0, min(int(return_draws), len(vals)))
            if keep:
                if keep >= len(vals):
                    take = np.arange(len(vals))
                else:
                    rrng = np.random.default_rng((0 if random_state is None else int(random_state)) + 8675309)
                    take = np.sort(rrng.choice(len(vals), size=keep, replace=False))
                cov_entry_draws[component] = vals[take].astype(np.float32, copy=False)
                cov_entry_draws.setdefault("replicate_ids", entry_ids_all[take])
        else:
            cov_entry_ci[component] = np.full((len(probs), entry_rows.size), np.nan)
    out["covariance_ci"] = cov_entry_ci
    out["covariance_ci_entries"] = {"row": entry_rows.copy(), "col": entry_cols.copy()}
    out["covariance_draws"] = cov_entry_draws
    out["covariance_draw_count"] = int(len(entry_ids_all))
    out["regularization_policy"] = regularization_policy
    if entry_rows.size == T and np.array_equal(entry_rows, entry_cols) and np.array_equal(entry_rows, np.arange(T)):
        out["variance_ci"] = {k: np.maximum(v, 0.0) if k in {"G", "E"} else v for k, v in cov_entry_ci.items()}

    out["factor_stability"] = {}
    for name in target_names:
        cc = np.concatenate(cong_acc[name], axis=0) if cong_acc[name] else np.empty((0, factor_refs[name].shape[1]))
        if draws_acc is not None and draws_acc[name]:
            draw_array = np.concatenate(draws_acc[name], axis=0)
        else:
            draw_array = None
        if draw_array is not None and len(draw_array):
            lo = np.quantile(draw_array, 0.025, axis=0)
            hi = np.quantile(draw_array, 0.975, axis=0)
        else:
            lo = hi = None
        out["factor_stability"][name] = {
            "congruence": cc,
            "mean_congruence": np.nanmean(cc, axis=0) if cc.size else np.array([]),
            "min_congruence": np.nanmin(cc, axis=0) if cc.size else np.array([]),
            "loading_mean": loading_stat[name].mean,
            "loading_se": loading_stat[name].std(),
            "loading_ci_low": lo,
            "loading_ci_high": hi,
            "draws": draw_array,
        }
    return out


# ---------------------------------------------------------------------------
# Public covariance estimator
# ---------------------------------------------------------------------------
@_dataset_result(_covariance_fit_dataset)
@hyperopt_options
@covariance_workflow
@prediction_rank_options
@covariance_runtime
@covariance_compatibility
@shared_kernel_eigensystems
def genetic_varcov_PSD(
    grm,
    traits: pd.DataFrame,
    *,
    covariance_structure="fa",
    rank_G="full",
    rank_E="full",
    rank_candidates=(10, 20, 40, 100, "full"),
    rank_selection="none",
    optimize_hyperparameters_cv: int = 0,
    rank_validation_fraction=0.10,
    E_structure="auto",
    min_E_pair_overlap=2,
    ridge_G=0.0,
    ridge_E=0.0,
    shrink_G="auto",
    shrink_E=0.5263454565339929,
    block_size=512,
    block_dtype=np.float32,
    accum_dtype=np.float64,
    mode="auto",
    square_dtype=None,
    dense_threshold_gb=4.0,
    maxiter=1000,
    gtol=1e-7,
    ftol=1e-8,
    eps=1e-8,
    random_state=None,
    n_boot=0,
    bootstrap_strategy="weighted",
    bootstrap_n_jobs="auto",
    bootstrap_cache_gb=0.0,
    bootstrap_batch_size=None,
    progress=True,
    bootstrap_maxiter=250,
    bootstrap_factors=None,
    bootstrap_factor_draws="auto",
    bootstrap_blas_threads=1,
    bootstrap_groups=None,
    bootstrap_unit="auto",
    bootstrap_ci=(0.025, 0.50, 0.975),
    bootstrap_ci_entries="diag",
    bootstrap_return_draws=0,
    bootstrap_draw_components=("G", "E", "Rg"),
    blas_threads="auto",
    warm_start=None,
    factor_structure_G=None,
    factor_structure_E=None,
    factor_rotation_G=None,
    factor_rotation_E=None,
    factor_lambda_G=None,
    factor_lambda_E=None,
    factor_group_lambda_G=0.0,
    factor_group_lambda_E=0.0,
    factor_adaptive=True,
    factor_relaxed_refit=True,
    factor_support_tol=1e-7,
    factor_sparse_maxiter=120,
    factor_sparse_tol=1e-7,
    factor_auto_fraction=0.05,
    structural_refine=False,
    structural_outer_iter=2,
    structural_pc_source="phenotypic",
    structural_pc_alpha=0.01,
    structural_pc_max_cond_set=2,
    structural_pc_multiple_testing="none",
    structural_pc_n_eff="overlap",
    structural_pc_max_neighbors=20,
    structural_pc_min_abs_r=0.05,
    structural_pc_stability_bootstrap=12,
    structural_pc_edge_stability=0.65,
    structural_pc_direction_stability=0.75,
    structural_anm=False,
    structural_anm_min_ratio=1.20,
    structural_anm_stability_bootstrap=8,
    structural_anm_direction_stability=0.75,
    structural_required_edges=None,
    structural_forbidden_edges=None,
    structural_order=None,
    structural_sem_l1=0.0,
    structural_sem_bound=3.0,
    structural_sem_innovation_rank="diagonal",
    structural_sem_innovation_sparse=True,
    structural_dag_extensions=12,
    structural_dag_topk=5,
    structural_path_min_abs=0.05,
    structural_maxiter=500,
    structural_plots="auto",
    solver="lbfgs",
    spectral_weighting="rank1",
    spectral_fa_sweeps=4,
    spectral_refine_maxiter=5,
    projected_maxiter=80,
    projected_tol=1e-7,
    projected_step_scale=0.95,
    moment_estimator="mom",
    minque_h2_ref=0.5,
    minque_kernel_rank="auto",
    minque_max_full_n=2500,
    analytic_se=False,
    analytic_se_probes=64,
    analytic_se_max_probes=None,
    analytic_se_mc_rtol=None,
    analytic_trace_probes=None,
    analytic_ci_level=0.95,
    analytic_kernel_factor="paired",
    fa_se_boundary_tol=1e-8,
    fa_se_direct_max_traits=2200,
    fa_se_cg_rtol=1e-3,
    fa_se_cg_maxiter=2000,
    spectral_se_probes=32,
    spectral_trace_probes=16,
    spectral_se_kernel_rank="auto",
    spectral_se_max_full_n=2500,
    variance_closure="auto",
    variance_closure_strength=1.0,
    variance_boundary_rtol=1e-8,
    variance_boundary_atol=1e-12,
    h2_prior_strength=0.0,
    h2_prior_groups=None,
    h2_prior_probes=64,
    h2_prior_pilot="analytic",
    save_path=None,
    **legacy_kwargs,
):
    """Joint MoM covariance fit with native factor-analytic G and E.
    
    Low-rank fits estimate ``L L' + Psi`` directly; ``Psi`` is not a post-hoc
    decomposition. ``solver='spectral'`` uses exact closed-form pairwise MoM
    followed by rank-r PSD spectral initialization and a joint projected-gradient
    correction; ``solver='spectral_fa'`` does the same with FA projections. This
    prevents independent G/E projection from collapsing E. ``solver='spectral_init'``
    and ``'spectral_fa_init'`` retain the old initializer-only diagnostics, while
    ``solver='spectral_refine'`` retains the L-BFGS polishing option. Named multi-kernel models (e.g. additive + dominance + GxE) are
    preserved throughout. Defaults use full-rank FA for G and E, no rank
    selection, auto residual structure, scalar E off-diagonal retention 0.5263454565339929, zero ridges, and auto variance
    closure with strength 1. Explicit ``rank_G='auto'``/``rank_E='auto'`` remain
    supported; use ``rank_selection='cv'`` for held-out moment rank selection.
    
    The prediction residual-retention default ``shrink_E=0.5263454565339929`` was
    transferred from an n=7616, 26-trait GDEC comparison. This value scales
    off-diagonal residual covariances after fitting and is not a universal
    optimum. Set ``shrink_E="auto"`` for the per-pair overlap/(overlap+400)
    policy of GDEC 3.1.3, ``"eb"`` for Fisher-z empirical Bayes, ``"model_eb"`` for
    model-based per-pair EB, or supply a different number on datasets with
    different trait overlap.
    
    ``hyper_opt=True`` enables the supervised compound Optuna TPE controller;
    ``hyper_opt_kwargs`` defines metadata-based CV, independent G/E and named
    component ranks, conditional geometry/retention/h2-prior choices, bounded
    workers and durable recovery. The legacy integer ``optimize_hyperparameters_cv``
    maps >=2 to an unseen-animal/partial-cell preset. It cannot be combined with
    hyper_opt or another rank-selection controller. Zero disables HPO without
    importing Optuna; booleans, 1 and negative fold counts are invalid.
    Completed models return HPO status, best/selected settings, fold/table paths
    and uncertainty availability separately. Use predict_hyperopt
    for the verified covariance view and frozen nuisance mapping. See
    docs/HYPER_OPT.md; source/static review does not establish runtime validity.
    Outer/test outcomes must remain missing; full-data warm starts are discarded.

    ``analytic_se=True``/``'final'`` propagates Gaussian moment
    uncertainty through the local fixed-rank PSD/FA tangent and selected
    shrinkage policy for both one- and multi-kernel models. A shared phenotype
    mask uses the separable trace-Hutchinson sandwich; heterogeneous
    trait-specific missingness automatically switches to the fixed-mask
    Gaussian moment-probe sandwich, retaining the actual pairwise MoM systems
    without complete-case deletion or covariance refits. ``'preconstraint'``
    retains the unconstrained MoM diagnostic. Rank/shrinkage-selection
    uncertainty remains conditional and is still a bootstrap sensitivity target.
    Pair-specific residual shrinkage is rank-preserving by default. In 2.9.4,
    ``shrink_G`` and ``shrink_E`` additionally accept ``'analytic_global'``
    and ``'analytic_pairwise'``. These policies estimate prediction shrinkage
    from the final analytical SE for every named covariance component while
    retaining unshrunk inference matrices and analytical uncertainty.
    
    VIGOR 2.10 adds factor geometry directly inside the PSD fit.
    ``factor_structure_G``/``factor_structure_E`` accept ``'fa'``, ``'pca'``,
    ``'sparse_fa'`` and ``'sparse_pca'`` (the G option may be a per-kernel
    mapping). ``factor_rotation_*='varimax'`` is covariance-invariant for dense
    models and is used as the pre-sparsity orientation for sparse models. Sparse
    support is selected by proximal updates and, by default, refit with support-
    fixed L-BFGS-B. ``analytic_se='final'`` then conditions on the selected
    rank/support; support-selection uncertainty remains a bootstrap sensitivity.
    
    VIGOR 2.11 optionally sets ``structural_refine=True`` to alternate the
    sparse PSD/FA fit with PC/ANM graph updates and a shared-path acyclic SEM
    fitted directly to the *original* MoM tensors.  The SEM reconstruction is
    fed back as the warm start for another support-selecting PSD/FA L-BFGS fit.
    The final support-fixed PSD/FA block remains the inference estimator used
    by the existing analytic sandwich SE, while ``structural_sem`` reports the
    moment-fitted path model. ``structural_tabs`` contains an optional Panel
    hvPlot/NetworkX report when the plotting extra is installed.
    
    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.
    
    traits : pd.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.
    
    covariance_structure : str
        Global trait covariance geometry: 'fa'/'factor'/'factor_analytic' uses low-rank factors
        plus specific variances; 'psd'/'pca'/'eigen' uses factors without specific variance;
        'varimax_fa' rotates dense FA; 'sparse_fa', 'sparse_pca' and 'sparse_varimax_fa' select
        sparse factor geometry. Explicit factor_structure_G/E override this global choice.
        Default: ``'fa'``.
    
    rank_G : int, str, mapping or None
        Trait factor rank: 'full'/None uses T factors, 'diag' uses zero factors, and integers
        are clipped to [0, T] by _rank_value. 'auto' invokes the covariance estimator's
        heuristic or held-out moment selection. rank_G may map kernel names to ranks.
        Rank-selection helpers additionally accept rank_E='same' to follow the tested genetic
        rank. Default: ``'full'``.
    
    rank_E : int, str, mapping or None
        Trait factor rank: 'full'/None uses T factors, 'diag' uses zero factors, and integers
        are clipped to [0, T] by _rank_value. 'auto' invokes the covariance estimator's
        heuristic or held-out moment selection. rank_G may map kernel names to ranks.
        Rank-selection helpers additionally accept rank_E='same' to follow the tested genetic
        rank. Default: ``'full'``.
    
    rank_candidates : sequence of int or str
        Ranks tested by held-out moment selection. Positive integers and 'full' are candidates;
        the high-level auto selector drops full when there are more than 300 traits to bound
        cost. Default: ``(10, 20, 40, 100, 'full')``.
    
    rank_selection : str
        Policy used only when a requested trait rank is 'auto': 'none' (and unrecognized non-CV
        spellings) uses min(T, max(10, min(100, ceil(2*sqrt(T))))); 'cv', 'moment_cv' and 'auto'
        compare held-out trait-pair moment error. This is moment validation, not prediction HPO,
        and explicit full ranks bypass it. Default: ``'none'``.
    
    optimize_hyperparameters_cv : int
        Legacy compound-HPO preset fold count: 0 disables search without importing
        Optuna; integers >=2 enable unseen-animal/partial-cell CV. Booleans, 1,
        negatives and nonintegers are rejected. Cannot combine with hyper_opt or
        rank CV. Independent ranks/geometry are searched on the MoM L-BFGS path.
        Leave protected outer/test outcomes NaN. Default: ``0``.
    
    rank_validation_fraction : float
        Fraction of eligible trait-pair moments reserved for rank validation. Choose a fraction
        strictly between zero and one; the selector must retain nonempty training and validation
        information. Default: ``0.1``.
    
    E_structure : str
        Residual structure: 'auto' splits only disconnected overlap-support components,
        otherwise retaining FA geometry; 'fa'/'full' keeps joint residual covariance;
        'diag'/'diagonal' removes factors; 'auto_supported' uses legacy overlap-supported
        blocks. 'auto_cv' selects structure using held-out moments. min_E_pair_overlap defines
        supported pairs. Default: ``'auto'``.
    
    min_E_pair_overlap : int
        Minimum number of jointly observed animals supporting an off-diagonal residual trait
        pair; pairs below this overlap threshold are unsupported under the selected residual
        policy. Default: ``2``. Source comparisons: ``int(min_E_pair_overlap) < 1``. See the
        rejection/fallback branches for enforcement.
    
    ridge_G : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``0.0``. Passed to ``genetic_varcov_PSD`` as ``ridge_G``.
    
    ridge_E : float or array-like
        Regularization strength added to the fitted objective or linear system. Nonnegative
        values describe a penalty; zero removes that penalty. Componentwise arrays must match
        the component order. Default: ``0.0``. Passed to ``genetic_varcov_PSD`` as ``ridge_E``.
    
    shrink_G : float, str or mapping
        Genetic off-diagonal retention: numeric values conventionally lie in [0,1], with 1
        retaining all. 'auto'/'legacy_auto'/'historical_auto' uses sample-size retention
        n/(n+50); 'none'/'off' retains all; 'auto_cv'/'cv' invokes held-out moment policy
        selection. 'analytic_global'/'analytic_pairwise' (and aliases resolved by
        _analytic_shrink_mode) regularizes prediction after final SE, preserving unshrunk
        inference. Kernel-name mappings are accepted. Residual-only pairwise/EB spellings are
        not genetic policies. Default: ``'auto'``.
    
    shrink_E : float or str
        Residual retention: numeric 0..1 scales off-diagonals.
        'auto' shrinks each residual pair by overlap/(overlap+400) without rank preservation
        (the 3.1.3 policy; same as 'pairwise_full'); append '@s' ('auto@100') to set the
        per-pair strength s. 'linear_analytic' applies the closed-form overlap-aware
        Schafer-Strimmer linear intensity toward the diagonal. 'model_eb' ('model_eb@c')
        shrinks each pair by tau2/(tau2 + c s2_ij), with s2_ij the pair's sampling variance
        from the fit's own MoM precision. 'eb'/'fisher_eb'/'pairwise_eb' uses
        rank-preserving Fisher-z EB, while 'fisher_eb_full'/'pairwise_eb_full'/'eb_full'
        permits full-rank pair retention. 'pairwise'/'pairwise_overlap' uses overlap support
        with rank preservation; 'pairwise_full'/'pairwise_overlap_full' omits that rank
        restriction.
        'legacy_auto'/'historical_auto' uses median overlap/(overlap+400); 'none'/'off' retains
        all. 'auto_cv'/'cv' selects on held-out moments; analytic aliases use final-SE
        prediction retention. auto_supported E requires scalar-compatible retention. Default:
        ``0.5263454565339929``.
    
    block_size : int
        Animal-row block size for exact moment accumulation, not a genotype-variant block size.
        Positive counts control temporary pairwise matrix products in the blocked/multi-kernel
        moment paths. Default: ``512``.
    
    block_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float32``. Passed to ``genetic_varcov_PSD`` as
        ``block_dtype``.
    
    accum_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``genetic_varcov_PSD`` as
        ``accum_dtype``.
    
    mode : str
        Moment accumulation mode: 'auto' selects dense or blocked computation using the
        dense_threshold_gb estimate; 'dense' materializes dense intermediates; 'blocked'/'block'
        streams matrix blocks. See grm_moment_matrices_einsum for the exact accepted mode
        spellings. Default: ``'auto'``.
    
    square_dtype : NumPy dtype or None
        Element dtype for the squared GRM intermediate in the dense single-kernel moment path.
        None uses accum_dtype; it also controls the automatic dense-memory estimate. The blocked
        path does not materialize that full squared matrix. Default: ``None``.
    
    dense_threshold_gb : float
        Estimated dense-working-memory cutoff in GiB for automatic moment mode selection;
        positive values permit the dense path below this bound. Default: ``4.0``.
    
    maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``1000``. Passed to ``genetic_varcov_PSD`` as ``maxiter``.
    
    gtol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``. Passed to ``genetic_varcov_PSD`` as ``gtol``.
    
    ftol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-08``. Passed to ``genetic_varcov_PSD`` as ``ftol``.
    
    eps : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``genetic_varcov_PSD`` as ``eps``.
    
    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``None``. Passed
        to ``genetic_varcov_PSD`` as ``random_state``.
    
    n_boot : int
        Number of bootstrap replicates. Zero disables bootstrap when supported; positive counts
        estimate sampling variation by the resampling scheme used here. Default: ``0``. Source
        comparisons: ``int(n_boot) > 0``. See the rejection/fallback branches for enforcement.
        Passed to ``genetic_varcov_PSD`` as ``n_boot``.
    
    bootstrap_strategy : str
        Animal multiplicity bootstrap without copying the GRM: 'weighted', 'weighted_no_copy'
        and 'weighted_no_grm_copy' are equivalent accepted names. Indexed GRM-copy bootstrap is
        rejected by this engine. Default: ``'weighted'``.
    
    bootstrap_n_jobs : int or str
        Worker-process count for bootstrap; a positive integer fixes concurrency, while 'auto'
        resolves a bounded process count from CPU availability and the replicate workload.
        Default: ``'auto'``.
    
    bootstrap_cache_gb : float
        Memory budget in GiB for cached moment terms. Zero disables the cache; positive budgets
        permit only cached terms fitting within the limit. Default: ``0.0``. Passed to
        ``genetic_varcov_PSD`` as ``bootstrap_cache_gb``.
    
    bootstrap_batch_size : int or None
        Replicates dispatched together to each worker. Positive integers set dispatch
        granularity; None chooses the worker-count/replicate-dependent batch size. Default:
        ``None``.
    
    progress : bool
        Whether to emit progress/status reporting during this operation. False disables the
        corresponding reporting path. Default: ``True``. Passed to ``genetic_varcov_PSD`` as
        ``progress``.
    
    bootstrap_maxiter : int
        Maximum covariance-fit iterations per bootstrap replicate; a positive cap bounds
        refitting work and may leave replicate fits unconverged. Default: ``250``.
    
    bootstrap_factors : mapping or None
        Optional map from output factor labels to decomposition config or integer rank. Config
        supports component (G/E or named kernel), rank, method, standardize, preserve_diag and
        the settings consumed by _stability_loadings. None uses the native fitted factor
        targets. Extra decompositions track stability and do not replace the inference
        covariance. Default: ``None``.
    
    bootstrap_factor_draws : bool or str
        Whether to retain all aligned factor-loading draws. 'auto' enables them only when
        n_boot*T*total_factor_rank*sizeof(float32) is at most 512 MiB; True enables and False
        disables them. Other values are coerced with bool rather than treated as a draw-count
        limit. Default: ``'auto'``.
    
    bootstrap_blas_threads : int or str
        BLAS thread limit during numerical operations. Positive integers select an explicit
        thread count; auto uses the routine's workload-dependent thread policy. Default: ``1``.
        Passed to ``genetic_varcov_PSD`` as ``bootstrap_blas_threads``.
    
    bootstrap_groups : sequence, str or None
        Grouping labels used to select a store subgroup or partition observations. For
        resampling, give one cluster label per animal so a cluster is sampled as a unit.
        Default: ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value. Passed to ``genetic_varcov_PSD`` as
        ``bootstrap_groups``.
    
    bootstrap_unit : str
        Resampling unit: 'auto' chooses clusters when bootstrap_groups is supplied and
        individuals otherwise; 'individual' samples animals separately; 'cluster' samples whole
        groups and requires one group label per animal. Default: ``'auto'``.
    
    bootstrap_ci : sequence of float
        Bootstrap quantile probabilities, each in [0, 1], used for uncertainty summaries. The
        default gives lower 2.5%, median and upper 97.5% quantiles. Default: ``(0.025, 0.5,
        0.975)``.
    
    bootstrap_ci_entries : str, sequence of pairs or None
        Entries for covariance bootstrap intervals: 'diag'/'diagonal'/'variances' selects
        variances; 'all'/'lower'/'lower_triangle' selects the lower triangle; None/'none'/'off'
        omits entry intervals. Explicit pairs contain valid trait indices or names. 'full' is
        not accepted. Default: ``'diag'``.
    
    bootstrap_return_draws : int
        Maximum covariance draws to return. Zero omits raw draws; positive integers cap stored
        draws to bound memory. Default: ``0``.
    
    bootstrap_draw_components : sequence of str
        Covariance/correlation components for raw bootstrap draws: 'G' is total genetic
        covariance, 'E' residual covariance and 'Rg' genetic correlation. Names must match the
        draw components supported by bootstrap_factor_analytic. Default: ``('G', 'E', 'Rg')``.
    
    blas_threads : int or str
        BLAS thread limit during numerical operations. Positive integers select an explicit
        thread count; auto uses the routine's workload-dependent thread policy. Default:
        ``'auto'``. Passed to ``genetic_varcov_PSD`` as ``blas_threads``.
    
    warm_start : mapping, array-like or None
        Initial covariance factors/matrices or optimization state from a compatible fit. None
        uses the solver's initialization; incompatible trait/component dimensions must not be
        reused. Default: ``None``. Passed to ``genetic_varcov_PSD`` as ``warm_start``.
    
    factor_structure_G : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping. Default:
        ``None``.
    
    factor_structure_E : str, sequence, mapping or None
        Factor geometry: 'fa' has specific diagonal variance; 'pca' omits it; 'sparse_fa' and
        'sparse_pca' select sparse loadings in the corresponding geometry. None inherits the
        global covariance structure; the G setting can be a per-kernel mapping. Default:
        ``None``.
    
    factor_rotation_G : str, sequence, mapping or None
        Factor orientation: None/'none'/'off'/'false' leaves factors unchanged; 'varimax' uses
        orthogonal varimax, preserving dense covariance and choosing pre-sparsity orientation.
        'identity' is not accepted. Per-component settings follow component order. Default:
        ``None``.
    
    factor_rotation_E : str, sequence, mapping or None
        Factor orientation: None/'none'/'off'/'false' leaves factors unchanged; 'varimax' uses
        orthogonal varimax, preserving dense covariance and choosing pre-sparsity orientation.
        'identity' is not accepted. Per-component settings follow component order. Default:
        ``None``.
    
    factor_lambda_G : float, str, mapping or None
        Loading L1 penalty. Nonnegative numeric values set it explicitly; None/'auto' uses the
        factor_auto_fraction scale rule for sparse factors. The G setting may map kernel names
        to penalties; dense geometry ignores sparse penalties. Default: ``None``.
    
    factor_lambda_E : float, str, mapping or None
        Loading L1 penalty. Nonnegative numeric values set it explicitly; None/'auto' uses the
        factor_auto_fraction scale rule for sparse factors. The G setting may map kernel names
        to penalties; dense geometry ignores sparse penalties. Default: ``None``.
    
    factor_group_lambda_G : float, str or mapping
        Row-group loading penalty for sparse factors. Zero disables group sparsity; positive
        values penalize each trait's loading-row norm; 'auto' chooses a scale-relative penalty.
        The G setting may be per kernel. Default: ``0.0``.
    
    factor_group_lambda_E : float, str or mapping
        Row-group loading penalty for sparse factors. Zero disables group sparsity; positive
        values penalize each trait's loading-row norm; 'auto' chooses a scale-relative penalty.
        The G setting may be per kernel. Default: ``0.0``.
    
    factor_adaptive : bool
        Whether sparse loading penalties are weighted adaptively using the initial loading
        magnitudes rather than a common weight. Default: ``True``.
    
    factor_relaxed_refit : bool
        Whether to refit loadings without shrinkage after selecting their support, retaining
        zeros fixed by sparse selection. Default: ``True``.
    
    factor_support_tol : float
        Absolute loading magnitude threshold used to define selected sparse support; nonnegative
        values determine which entries are fixed at zero for refitting. Default: ``1e-07``.
    
    factor_sparse_maxiter : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``120``.
    
    factor_sparse_tol : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``1e-07``.
    
    factor_auto_fraction : float or int
        Sparse proximal optimizer control: maxiter caps iterations; tol stops small relative
        updates; auto_fraction sets the penalty as a fraction of the initial loading-gradient
        scale. Use positive values suited to convergence and sparsity. Default: ``0.05``.
    
    structural_refine : bool
        Whether to alternate sparse covariance fitting with PC/optional ANM graph discovery and
        a shared-path acyclic moment-fitted SEM. This is a conditional structural refinement,
        not proof of causal identification. Default: ``False``.
    
    structural_outer_iter : int
        Number of covariance/graph/SEM outer iterations when structural refinement is enabled; a
        positive cap bounds the alternating procedure. Default: ``2``.
    
    structural_pc_source : str
        PC discovery covariance: 'phenotypic'/'p'/'vp'/'total' uses empirical pairwise-observed
        phenotype covariance when supplied, otherwise modeled G+E; 'genetic'/'g'/'genetic_total'
        sums genetic components; 'residual'/'e'/'environmental' uses E; an exact kernel
        component name selects that component. Phenotypic discovery does not inherit fitted
        diagonal/sparse restrictions. Default: ``'phenotypic'``.
    
    structural_pc_alpha : float
        Conditional-independence significance level for PC skeleton tests, ordinarily between
        zero and one. Default: ``0.01``.
    
    structural_pc_max_cond_set : int
        Maximum number of conditioning traits in a PC independence test; nonnegative values cap
        combinatorial work. Default: ``2``.
    
    structural_pc_multiple_testing : str
        PC skeleton correction: 'none' uses nominal alpha; 'bonferroni' divides alpha by the
        number of tests at each conditioning depth. Other spellings are rejected by
        pc_from_covariance. Default: ``'none'``.
    
    structural_pc_n_eff : str or float
        PC effective sample count: 'overlap'/'auto' uses the lower quartile of positive pair
        overlaps (or minimum observed trait count if none), floored at 4. Numeric values supply
        a count, also floored at 4. Phenotypic PC tests using data retain test-wise complete
        samples. Default: ``'overlap'``.
    
    structural_pc_max_neighbors : int
        Maximum retained PC candidate neighbors per trait, bounding graph search work. Default:
        ``20``.
    
    structural_pc_min_abs_r : float
        Minimum absolute correlation/path magnitude retained in the respective candidate or
        reporting stage; nonnegative values remove weak associations/paths. Default: ``0.05``.
    
    structural_pc_stability_bootstrap : int
        Bootstrap replicate count for the corresponding graph edge/direction stability analysis;
        zero disables that resampling stage. Default: ``12``.
    
    structural_pc_edge_stability : float
        Minimum resampling support fraction in [0, 1] required to retain the corresponding
        adjacency or direction. Default: ``0.65``.
    
    structural_pc_direction_stability : float
        Minimum resampling support fraction in [0, 1] required to retain the corresponding
        adjacency or direction. Default: ``0.75``.
    
    structural_anm : bool
        Whether additive-noise-model direction checks supplement PC orientation; directions
        remain observational and may abstain. Default: ``False``.
    
    structural_anm_min_ratio : float
        Minimum forward/reverse additive-noise independence-score ratio required before
        proposing a direction; values above one demand stronger asymmetry. Default: ``1.2``.
    
    structural_anm_stability_bootstrap : int
        Bootstrap replicate count for the corresponding graph edge/direction stability analysis;
        zero disables that resampling stage. Default: ``8``.
    
    structural_anm_direction_stability : float
        Minimum resampling support fraction in [0, 1] required to retain the corresponding
        adjacency or direction. Default: ``0.75``.
    
    structural_required_edges : sequence of pairs or None
        Trait-name/index pairs that must be retained or excluded respectively during graph
        refinement. None imposes no such constraints; required directions must remain compatible
        with acyclicity. Default: ``None``.
    
    structural_forbidden_edges : sequence of pairs or None
        Trait-name/index pairs that must be retained or excluded respectively during graph
        refinement. None imposes no such constraints; required directions must remain compatible
        with acyclicity. Default: ``None``.
    
    structural_order : sequence or None
        Topological trait/node ordering restricting paths to earlier-to-later edges. None lets
        the graph routine choose or infer a compatible acyclic ordering. Default: ``None``.
        Passed to ``genetic_varcov_PSD`` as ``structural_order``.
    
    structural_sem_l1 : float
        Nonnegative L1 penalty on shared SEM path coefficients; zero leaves paths unpenalized.
        Default: ``0.0``.
    
    structural_sem_bound : float
        Positive absolute bound on each fitted SEM path coefficient, limiting extreme path
        amplification. Default: ``3.0``.
    
    structural_sem_innovation_rank : int or str
        SEM innovation covariance factor rank. 'diagonal' keeps source-specific independent
        innovations; an integer requests additional innovation factors according to the SEM
        fitter. Default: ``'diagonal'``.
    
    structural_sem_innovation_sparse : bool
        Whether innovation factors use sparse support when the SEM innovation rank includes
        latent factors. Default: ``True``.
    
    structural_dag_extensions : int
        Maximum acyclic extensions examined or best moment-scored DAGs retained, respectively;
        positive counts bound graph-model selection work. Default: ``12``.
    
    structural_dag_topk : int
        Maximum acyclic extensions examined or best moment-scored DAGs retained, respectively;
        positive counts bound graph-model selection work. Default: ``5``.
    
    structural_path_min_abs : float
        Minimum absolute correlation/path magnitude retained in the respective candidate or
        reporting stage; nonnegative values remove weak associations/paths. Default: ``0.05``.
    
    structural_maxiter : int
        Maximum optimizer iterations in each structural SEM fit; positive values bound
        graph-refinement computation. Default: ``500``.
    
    structural_plots : bool or str
        Whether to build optional structural report views; 'auto' attempts them when plotting
        dependencies are available, True requests them and False omits them. Default:
        ``'auto'``.
    
    solver : str
        Covariance optimizer: 'lbfgs' optimizes factor geometry; 'spectral' uses PSD projected
        joint MoM updates; 'spectral_fa' uses FA projected updates;
        'spectral_init'/'spectral_fa_init' return initializer-only diagnostics;
        'spectral_refine' adds L-BFGS polishing. Aliases: 'l-bfgs-b'/'factor' -> lbfgs;
        'closed_form'/'spectral_psd'/'projected_psd' -> spectral;
        'projected'/'projected_fa'/'fa_spectral' -> spectral_fa; 'spectral_psd_init' ->
        spectral_init; 'fa_spectral_init' -> spectral_fa_init; 'spectral_fa_refine' ->
        spectral_refine. Default: ``'lbfgs'``.
    
    spectral_weighting : str
        Spectral projection weighting: 'rank1'/'separable'/'information' uses the best separable
        approximation to supplied entry information weights. Other strings, including 'none',
        take the unweighted projection branch; this helper does not enforce an exhaustive string
        enum. Default: ``'rank1'``.
    
    spectral_fa_sweeps : int
        Number of alternating low-rank/specific-diagonal updates in each spectral FA projection;
        positive counts improve initializer consistency at extra cost. Default: ``4``.
    
    spectral_refine_maxiter : int
        Maximum L-BFGS polishing iterations after spectral initialization; positive values
        control this optional refinement stage. Default: ``5``.
    
    projected_maxiter : int or float
        Joint projected-gradient control: maxiter caps accepted iterations, tol sets the
        relative update stopping threshold, and step_scale scales the inverse Lipschitz bound
        before backtracking. Use positive values; step scales below one give conservative
        initial steps. Default: ``80``.
    
    projected_tol : int or float
        Joint projected-gradient control: maxiter caps accepted iterations, tol sets the
        relative update stopping threshold, and step_scale scales the inverse Lipschitz bound
        before backtracking. Use positive values; step scales below one give conservative
        initial steps. Default: ``1e-07``.
    
    projected_step_scale : int or float
        Joint projected-gradient control: maxiter caps accepted iterations, tol sets the
        relative update stopping threshold, and step_scale scales the inverse Lipschitz bound
        before backtracking. Use positive values; step scales below one give conservative
        initial steps. Default: ``0.95``.
    
    moment_estimator : str
        Moment system: 'mom' and 'score' use the pairwise MoM path; 'minque' uses a
        fixed-reference single-kernel precision and excludes weighted animal bootstrap. MINQUE
        working precision uses minque_h2_ref and kernel-rank controls. Default: ``'mom'``.
    
    minque_h2_ref : float or one-dimensional array
        Genetic variance fraction in [0, 1], scalar or ordered by trait as required. This is the
        working/reference heritability when the routine builds a null precision rather than
        estimating the final fraction. Default: ``0.5``. Passed to ``genetic_varcov_PSD`` as
        ``minque_h2_ref``.
    
    minque_kernel_rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``'auto'``. Passed to
        ``genetic_varcov_PSD`` as ``minque_kernel_rank``.
    
    minque_max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``.
    
    analytic_se : bool or str or None
        Analytical uncertainty: False/None/'false'/'none'/'off'/'0' disables it; True uses final
        fixed-rank/support uncertainty; 'preconstraint'/'pre_constraint'/'mom'/'raw' uses
        unconstrained MoM uncertainty. 'final'/'auto' and other non-disabled non-preconstraint
        strings take the final branch. Model/rank/support-selection uncertainty remains
        conditional. Default: ``False``.
    
    analytic_se_probes : int
        Probe count (probe pairs for 'paired') of the final FA sandwich
        (``analytic_se='final'``). Exactly this many are used unless ``analytic_se_mc_rtol`` is
        set. Each SE's relative Monte Carlo error is reported in
        ``analytic_se['se_relative_mc_error']`` (about 9% at 64). Negative paired variance
        estimates are reported as NaN, never clipped. Default: ``64``.

    analytic_se_max_probes : int or None
        Probe cap when ``analytic_se_mc_rtol`` is set; None means 1024. Default: ``None``.

    analytic_se_mc_rtol : float or None
        Optional Monte Carlo target. When set, probes are added in blocks of 32 beyond
        ``analytic_se_probes`` until the 90th percentile of the monitored SEs' relative errors
        (marginal G/E variances and h2 of traits off the variance boundary) is at most this
        value and no monitored variance is negative, or the cap is reached
        (``mc_target_met``). None uses exactly ``analytic_se_probes``. Default: ``None``.

    analytic_trace_probes : int or None
        Trace-probe count used only by the legacy spectral and pre-constraint uncertainty
        routes. None uses spectral_trace_probes. Default: ``None``.

    analytic_ci_level : float
        Coverage of analytical intervals, strictly between zero and one. h2 uses a logit
        interval, marginal variances log-scale intervals and rG Fisher-z intervals. With an
        active h2 prior, h2 and marginal-variance intervals are robust empirical-Bayes
        intervals that account for the shrinkage bias. All intervals condition on the selected
        rank, sparse support and prior strength. Default: ``0.95``.

    analytic_kernel_factor : {'paired', 'grm2us', 'cholesky'}
        Moment-covariance backend of the final FA sandwich. 'paired' is factorization free:
        independent masked Rademacher probes u, w give E[(u'AVw)(u'VBw)] = tr(AVBV), so
        moment covariances come from kernel products only and keep the full supplied kernel
        (2 kernel products of n x t blocks per probe, no O(n^3) step, no extra n x n storage).
        'grm2us' draws Gaussian phenotypes and forms their moments on one ``npplink.grm2Us``
        randomized eigensystem of rank ``spectral_se_kernel_rank`` ('auto' = 512) plus a
        trace-matched isotropic remainder: O(n r t) per probe after one O(n^2 r)
        eigensystem. Differences from the full kernel are approximation error, recorded as
        ``analytic_se['kernel_retained_trace_fraction']``. 'cholesky' draws from one exact
        factor per kernel (O(n^3/3), final fit only) and is the small-data reference.
        Default: ``'paired'``.

    fa_se_boundary_tol : float
        Nonnegative variance/loading boundary tolerance used when choosing the active FA tangent
        for analytical uncertainty. Default: ``1e-08``.
    
    fa_se_direct_max_traits : int
        Trait-count cutoff for direct analytical tangent solves; larger problems use the
        iterative covariance-uncertainty solve. Default: ``2200``.
    
    fa_se_cg_rtol : float
        Relative energy-norm error ||J(x - x*)||_H / ||J x*||_H of each projected sandwich
        draw, for the batched preconditioned CG onto the fitted FA tangent in the
        moment-objective metric (Hestenes-Stiefel delay estimate). 1e-3 is far below the
        ~9% Monte Carlo error of 64 probes. Default: ``1e-03``.

    fa_se_cg_maxiter : int
        Iteration cap of that CG. Non-convergence makes analytical SEs unavailable with an
        explicit reason; there is no approximate fallback. Default: ``2000``.

    spectral_se_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``32``. Passed to ``genetic_varcov_PSD`` as ``spectral_se_probes``.
    
    spectral_trace_probes : int
        Number of random probe vectors for approximate moment/trace uncertainty calculations.
        Positive counts trade additional computation for lower Monte Carlo noise. Default:
        ``16``. Passed to ``genetic_varcov_PSD`` as ``spectral_trace_probes``.
    
    spectral_se_kernel_rank : int, str, sequence or mapping
        Retained matrix/factor rank. Integer ranks must be compatible with the relevant animal
        or trait dimension. Full and automatic policies depend on the decomposition; see the
        rank resolver used by this routine. Default: ``'auto'``. Passed to
        ``genetic_varcov_PSD`` as ``spectral_se_kernel_rank``.
    
    spectral_se_max_full_n : int
        Animal-count threshold below which full-kernel precision/eigensystem work is allowed;
        larger problems use the configured approximation policy. Default: ``2500``.
    
    variance_closure : bool, str or None
        Marginal variance closure: True/'auto'/'soft'/'moment'/'weighted' adds the
        information-weighted observed-variance moment (except MINQUE);
        False/None/'off'/'none'/'false'/'diagnostic' omits that objective term while retaining
        diagnostics. Default: ``'auto'``.
    
    variance_closure_strength : float
        Multiplier on the observed marginal-variance moment precision. Positive values favor
        agreement between summed modeled variances and observed phenotype variance; negative
        values are clamped to zero. Default: ``1.0``.
    
    variance_boundary_rtol : float
        Relative/absolute near-zero variance tolerances used for boundary-safe
        heritability/correlation diagnostics; choose nonnegative values on the covariance scale.
        Default: ``1e-08``.
    
    variance_boundary_atol : float
        Relative/absolute near-zero variance tolerances used for boundary-safe
        heritability/correlation diagnostics; choose nonnegative values on the covariance scale.
        Default: ``1e-12``.

    h2_prior_strength : float
        Empirical-Bayes heritability prior inside the L-BFGS objective (``solver='lbfgs'``):
        ``kappa_j (h2_j - mu_g)^2`` with h2 = sum_c G_c[jj] / (sum_c G_c[jj] + E[jj]) and the
        group mean mu_g estimated jointly. 1 reproduces normal-normal EB shrinkage
        tau2/(tau2+se_j^2) with tau2 the DerSimonian-Laird between-trait variance; 0 disables
        the prior; other values scale the prior precision. Like other penalty weights it is
        not identified by training loss; hyper_opt searches it. See :mod:`vigor.h2_prior`.
        Default: ``0.0``.

    h2_prior_groups : None, 'global', Series, mapping or sequence
        Prior domains: one global prior, or one label per trait (Series/mapping keyed by trait,
        or positional). Groups with fewer than three traits are pooled. hyper_opt searches
        'global' versus ``cv['trait_projects']`` by default. Default: ``None``.

    h2_prior_pilot : {'analytic', 'probes'}
        How the pilot per-trait h2 SEs (which set the prior weights) are computed.
        'analytic' uses the Gaussian null approximation Cov(B) ~ 2 Vp^2 tr(A_a A_b) from the
        trace matrix already in the moments: no probes or kernel products, O(t c^3). It is
        most accurate at modest h2. 'probes' estimates the full Gaussian covariance with
        Rademacher trace probes (see h2_prior_probes). Default: ``'analytic'``.

    h2_prior_probes : int
        Rademacher trace probes for the pilot per-trait sandwich SEs that set the prior
        weights (h2_prior_pilot='probes' only). Geometry is computed once per distinct observation mask and cached per
        training fold in hyper_opt. The pilot uses the grm2Us kernel approximation of rank
        ``spectral_se_kernel_rank`` ('auto' = 512; 'full' for the exact kernel), whose
        eigensystem is computed once per kernel and shared with the grm2us sandwich and every
        hyper_opt fold. Default: ``64``.

    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.
    
    **legacy_kwargs : dict
        Historical/environment controls forwarded to the compatibility route. bootstrap_method
        accepts weights/weighted aliases. environment supplies observation-aligned
        categories/covariates; environment_type, fit_mask, include_gxe,
        include_environment_main, fixed_covariates, fixed_ridge, rank_D, rank_GxE, rank_DxE,
        rank_permanent, observation_animal_ids, grm_ids and gxe_components configure the
        existing GxE route (see make_gxe_kernels and fit_gxe_mvblup). Unsupported
        covariance_structure spellings route to the original legacy estimator rather than
        defining new native geometry.
    
    Returns
    -------
    xarray.Dataset
        Labeled covariance fit. Every historical key keeps its name. Data variables:
        trait-by-trait matrices on ('trait_i','trait_j') -- G, E, G_prediction, E_prediction,
        Rg, Rg_prediction, Rg_shrunk, G/E/Rg_unshrunk, G/E/Rg_inference, rg_boundary,
        E_shrinkage_weights, E_pair_overlap, E_support_mask, G_se, E_se, rg_se (and the
        *_inference_se/*_unshrunk_se and rg_ci95_low/high aliases when available); per-trait
        vectors on ('trait',) -- vg, vg_unshrunk, valid_vg, invalid_var_mask,
        phenotypic_variance_observed/model, variance_closure_ratio/error/z/flag, h2, h2_model,
        h2_phenotype, h2_se, E_specific_var, G_variance_se, E_variance_se, cov_GE_diag;
        intervals on ('trait','bound') -- h2_ci95, G_variance_ci95, E_variance_ci95 -- and
        bootstrap quantiles on ('trait','quantile'); per-kernel matrices on
        ('component','trait_i','trait_j') -- G_components, G_components_prediction,
        G_components_unshrunk, G_components_inference, G_component_se -- and G_specific_var on
        ('component','trait'). Attributes (``ds.attrs[key]``): component_specs,
        component_specs_prediction/unshrunk, G_spec, G_spec_prediction, E_spec,
        E_spec_prediction, rank_G/E (+requested), shrink_G/E settings, regularization policy
        and selection tables, variance_boundary, variance_closure, analytic_se,
        uncertainty_method, bootstrap/factor_stability, optimizer result/success/message/nit/
        fun, covariance_structure/solver, factor diagnostics, structural_* reports,
        optimize_hyperparameters_cv, hyperparameter_optimization, runtime, version, plus
        title/software/parameters provenance. G/E/Rg and named genetic components are
        unshrunk inference estimands matching their SE/CI fields; *_prediction variables and
        prediction component specs hold retention-adjusted prediction views. Undefined
        genetic correlations are NaN at variance boundaries. Pass the Dataset (or
        ``fit['G_prediction']``) directly to mvPredict/mvBLUP.
    
    
    Examples
    --------
        import numpy as np
        import pandas as pd
        from vigor import genetic_varcov_PSD, mvPredict
        rng = np.random.default_rng(7)
        Y = pd.DataFrame(rng.normal(size=(24, 3)), columns=['a', 'b', 'c'])
        K = np.eye(len(Y))  # Replace with an aligned, informative relationship kernel.
        Y.iloc[0, 1] = np.nan
        fit = genetic_varcov_PSD(K, Y, n_boot=0, progress=False)
        prediction = mvPredict(Y, K, fit, accuracy='exact')
        # For independent validation, hide test outcomes before fitting, not afterwards.
    
    Complexity
    ----------
    For dense-kernel MoM/FA without SE/bootstrap/structural refinement, TIME O(c²(n²t+nt²)+I(c²t²+t²R)+c t³); SPACE O(c n²+c²t²+nt+tR+b n), where n is animals, t traits, c covariance components including E, R summed FA ranks, I actual fit evaluations and b row-block size. Blocked moment formation avoids an extra whole-kernel square but still retains dense kernels; supplied low-rank/operators replace contractions by operator-specific costs. Rank/regularization search repeats trait fits; q bootstrap replicates add q weighted moment/fit workloads (concurrent workers multiply peak memory). Analytic SE adds probe/trace/tangent-solve work controlled by its own iteration/probe counts; structural PC may be combinatorial in conditioning depth. These optional workloads are not covered by the base bound. Native defaults do not imply a convergence or calibration guarantee.
    """
    from .hyperparameter_cv import validate_cv_count

    grm = _kernel_input(grm)
    traits = _as_pandas_input(traits)
    optimize_hyperparameters_cv = validate_cv_count(optimize_hyperparameters_cv)
    if optimize_hyperparameters_cv:
        from .hyperparameter_cv import fit_with_hyperparameter_cv

        # Folds and the selected refit use the undecorated estimator/predictor;
        # the public decorator converts the returned fit to a Dataset once.
        return fit_with_hyperparameter_cv(_genetic_varcov_PSD_raw, _mvPredict_raw, locals())
    pbar = legacy_kwargs.pop("_runtime_progress")
    # 2.9.4: analytical-SE-driven shrinkage is a post-fit prediction layer.
    # The inference estimator is fitted unshrunk, its analytical sandwich SE is
    # computed, and only then are prediction covariance views regularized.
    if isinstance(shrink_G, dict):
        _analytic_g_modes = {str(k): _analytic_shrink_mode(v) for k, v in shrink_G.items()
                             if _analytic_shrink_mode(v) is not None}
    else:
        _gm = _analytic_shrink_mode(shrink_G)
        _analytic_g_modes = {"__all__": _gm} if _gm is not None else {}
    _analytic_e_mode = _analytic_shrink_mode(shrink_E)
    _analytic_post_requested = bool(_analytic_g_modes) or (_analytic_e_mode is not None)
    _analytic_se_auto_enabled = False
    if _analytic_post_requested and (analytic_se is False or analytic_se is None or str(analytic_se).lower() in {"false","none","off","0"}):
        analytic_se = "final"
        _analytic_se_auto_enabled = True
    pbar.stage("Covariance: align samples",phase_key="align")
    if "bootstrap_method" in legacy_kwargs:
        method = legacy_kwargs.pop("bootstrap_method")
        if method not in {"weights", "weighted"}:
            raise ValueError("bootstrap_method supports weights/weighted; use bootstrap_strategy for current options")
    grm = _align_labeled_kernels_to_traits(grm, traits)
    if str(bootstrap_strategy).lower() not in {"weighted", "weighted_no_copy", "weighted_no_grm_copy"}:
        raise ValueError("VIGOR 2.6.0 uses bootstrap_strategy='weighted' by default; legacy indexed bootstrap is intentionally not used by the 2.6 FA engine")
    # Direct environment=... construction is an existing GxE convenience API.
    # In 2.8 it is routed back through the same spectral/FA engine so callers do
    # not lose the new solver when requesting additive + dominance + GxE terms.
    # A mapping such as {'additive': K_A, 'dominance': K_D} therefore supports
    # A + D + A×E by default, and ``gxe_components=('additive','dominance')``
    # additionally requests D×E.
    if legacy_kwargs.get("environment", None) is not None:
        env_kw = dict(legacy_kwargs)
        environment = env_kw.pop("environment")
        environment_type = env_kw.pop("environment_type", "auto")
        fit_mask = env_kw.pop("fit_mask", None)
        include_gxe = bool(env_kw.pop("include_gxe", True))
        include_environment_main = bool(env_kw.pop("include_environment_main", True))
        fixed_covariates = env_kw.pop("fixed_covariates", None)
        fixed_ridge = float(env_kw.pop("fixed_ridge", 1e-8))
        rank_D = env_kw.pop("rank_D", 3)
        rank_GxE = env_kw.pop("rank_GxE", 3)
        rank_DxE = env_kw.pop("rank_DxE", 3)
        rank_permanent = env_kw.pop("rank_permanent", None)
        observation_animal_ids = env_kw.pop("observation_animal_ids", None)
        grm_ids = env_kw.pop("grm_ids", None)
        gxe_components = env_kw.pop("gxe_components", None)
        Yenv = traits.copy() if isinstance(traits, pd.DataFrame) else pd.DataFrame(traits)
        fmask = Yenv.notna().any(axis=1).to_numpy() if fit_mask is None else np.asarray(fit_mask, bool)
        kernels, kinfo = _legacy.make_gxe_kernels(
            grm, environment, index=Yenv.index, fit_mask=fmask,
            environment_type=environment_type, include_gxe=include_gxe,
            observation_animal_ids=observation_animal_ids, grm_ids=grm_ids,
            gxe_components=gxe_components,
        )
        Z = kinfo["environment_design"] if include_environment_main else pd.DataFrame(index=Yenv.index)
        if fixed_covariates is not None:
            C = fixed_covariates.reindex(Yenv.index) if isinstance(fixed_covariates, pd.DataFrame) else pd.DataFrame(fixed_covariates, index=Yenv.index)
            if C.isna().any().any():
                raise ValueError("fixed_covariates contains missing values")
            Z = pd.concat([Z, C.astype(float)], axis=1)
        fixed, beta = _legacy._fit_masked_fixed_effects(Yenv, Z, fmask, ridge=fixed_ridge)
        residual = Yenv.where(Yenv.isna(), Yenv - fixed)
        ranks = {}
        for name in kernels:
            if name in {"additive", "genetic"}:
                ranks[name] = rank_G
            elif name == "dominance":
                ranks[name] = rank_D
            elif name == "gxe":
                ranks[name] = rank_GxE
            elif name == "dominance_gxe":
                ranks[name] = rank_DxE
            elif name == "permanent_animal":
                ranks[name] = rank_permanent
            else:
                ranks[name] = rank_G
        out = _genetic_varcov_PSD_raw(
            kernels, residual, covariance_structure=covariance_structure,
            optimize_hyperparameters_cv=0,
            rank_G=ranks, rank_E=rank_E, rank_candidates=rank_candidates,
            rank_selection=rank_selection, rank_validation_fraction=rank_validation_fraction,
            E_structure=E_structure, min_E_pair_overlap=min_E_pair_overlap, ridge_G=ridge_G, ridge_E=ridge_E,
            shrink_G=shrink_G, shrink_E=shrink_E, block_size=block_size,
            block_dtype=block_dtype, accum_dtype=accum_dtype, mode=mode,
            square_dtype=square_dtype, dense_threshold_gb=dense_threshold_gb,
            maxiter=maxiter, gtol=gtol, ftol=ftol, eps=eps, random_state=random_state,
            n_boot=n_boot, bootstrap_strategy=bootstrap_strategy,
            bootstrap_n_jobs=bootstrap_n_jobs, bootstrap_cache_gb=bootstrap_cache_gb,
            bootstrap_batch_size=bootstrap_batch_size, progress=progress, bootstrap_maxiter=bootstrap_maxiter,
            bootstrap_factors=bootstrap_factors, bootstrap_factor_draws=bootstrap_factor_draws,
            bootstrap_blas_threads=bootstrap_blas_threads, bootstrap_groups=bootstrap_groups,
            bootstrap_unit=bootstrap_unit, bootstrap_ci=bootstrap_ci,
            bootstrap_ci_entries=bootstrap_ci_entries, bootstrap_return_draws=bootstrap_return_draws,
            bootstrap_draw_components=bootstrap_draw_components,
            blas_threads=blas_threads, warm_start=warm_start,
            factor_structure_G=factor_structure_G, factor_structure_E=factor_structure_E,
            factor_rotation_G=factor_rotation_G, factor_rotation_E=factor_rotation_E,
            factor_lambda_G=factor_lambda_G, factor_lambda_E=factor_lambda_E,
            factor_group_lambda_G=factor_group_lambda_G, factor_group_lambda_E=factor_group_lambda_E,
            factor_adaptive=factor_adaptive, factor_relaxed_refit=factor_relaxed_refit,
            factor_support_tol=factor_support_tol, factor_sparse_maxiter=factor_sparse_maxiter,
            factor_sparse_tol=factor_sparse_tol, factor_auto_fraction=factor_auto_fraction,
            structural_refine=structural_refine, structural_outer_iter=structural_outer_iter,
            structural_pc_source=structural_pc_source, structural_pc_alpha=structural_pc_alpha,
            structural_pc_max_cond_set=structural_pc_max_cond_set,
            structural_pc_multiple_testing=structural_pc_multiple_testing, structural_pc_n_eff=structural_pc_n_eff,
            structural_pc_max_neighbors=structural_pc_max_neighbors, structural_pc_min_abs_r=structural_pc_min_abs_r,
            structural_pc_stability_bootstrap=structural_pc_stability_bootstrap,
            structural_pc_edge_stability=structural_pc_edge_stability,
            structural_pc_direction_stability=structural_pc_direction_stability,
            structural_anm=structural_anm, structural_anm_min_ratio=structural_anm_min_ratio,
            structural_anm_stability_bootstrap=structural_anm_stability_bootstrap,
            structural_anm_direction_stability=structural_anm_direction_stability,
            structural_required_edges=structural_required_edges, structural_forbidden_edges=structural_forbidden_edges,
            structural_order=structural_order, structural_sem_l1=structural_sem_l1,
            structural_sem_bound=structural_sem_bound,
            structural_sem_innovation_rank=structural_sem_innovation_rank,
            structural_sem_innovation_sparse=structural_sem_innovation_sparse,
            structural_dag_extensions=structural_dag_extensions, structural_dag_topk=structural_dag_topk,
            structural_path_min_abs=structural_path_min_abs, structural_maxiter=structural_maxiter,
            structural_plots=structural_plots,
            solver=solver, spectral_weighting=spectral_weighting,
            spectral_fa_sweeps=spectral_fa_sweeps, spectral_refine_maxiter=spectral_refine_maxiter,
            projected_maxiter=projected_maxiter, projected_tol=projected_tol,
            projected_step_scale=projected_step_scale,
            moment_estimator=moment_estimator, minque_h2_ref=minque_h2_ref,
            minque_kernel_rank=minque_kernel_rank, minque_max_full_n=minque_max_full_n,
            analytic_se=analytic_se, analytic_se_probes=analytic_se_probes,
            analytic_se_max_probes=analytic_se_max_probes, analytic_se_mc_rtol=analytic_se_mc_rtol,
            analytic_trace_probes=analytic_trace_probes, analytic_ci_level=analytic_ci_level,
            analytic_kernel_factor=analytic_kernel_factor,
            fa_se_boundary_tol=fa_se_boundary_tol, fa_se_direct_max_traits=fa_se_direct_max_traits,
            fa_se_cg_rtol=fa_se_cg_rtol, fa_se_cg_maxiter=fa_se_cg_maxiter,
            spectral_se_probes=spectral_se_probes, spectral_trace_probes=spectral_trace_probes,
            spectral_se_kernel_rank=spectral_se_kernel_rank,
            spectral_se_max_full_n=spectral_se_max_full_n,
            variance_closure=variance_closure, variance_closure_strength=variance_closure_strength,
            variance_boundary_rtol=variance_boundary_rtol, variance_boundary_atol=variance_boundary_atol,
            h2_prior_strength=h2_prior_strength, h2_prior_groups=h2_prior_groups, h2_prior_probes=h2_prior_probes,
            h2_prior_pilot=h2_prior_pilot,
            **env_kw,
        )
        out["gxe_kernels"] = kernels
        out["gxe_kernel_info"] = kinfo
        out["fixed_prediction"] = fixed
        out["fixed_coefficients"] = beta
        out["traits_for_prediction"] = residual
        return out
    if legacy_kwargs.get("environment", ...) is None:
        legacy_kwargs.pop("environment")
    if legacy_kwargs:
        raise TypeError("unsupported genetic_varcov_PSD keyword argument(s): " + ", ".join(sorted(legacy_kwargs)))
    _covstruct_key = str(covariance_structure).lower().replace("-", "_")
    _new_factor_covstruct = {"fa", "factor", "factor_analytic", "psd", "pca", "eigen",
                             "varimax_fa", "sparse_fa", "sparse_pca", "sparse_varimax_fa"}
    if _covstruct_key not in _new_factor_covstruct:
        raise ValueError("unsupported covariance_structure; use FA/PCA/PSD or compatibility='gdec314'")
    residual_mode = str(E_structure).lower()
    if residual_mode not in {"fa", "full", "diag", "diagonal", "auto", "auto_cv", "auto_supported"}:
        raise ValueError("E_structure must be 'fa', 'full', 'diag', 'auto'/'auto_cv', or 'auto_supported'")
    if int(min_E_pair_overlap) < 1:
        raise ValueError("min_E_pair_overlap must be positive")
    Y = traits if isinstance(traits, pd.DataFrame) else pd.DataFrame(traits)
    T = Y.shape[1]
    estimator = str(moment_estimator).lower()
    if estimator not in {"mom", "score", "minque"}:
        raise ValueError("moment_estimator must be 'mom'/'score' or 'minque'")
    cov_solver = str(solver).lower()
    solver_alias = {
        "l-bfgs-b": "lbfgs", "factor": "lbfgs",
        "closed_form": "spectral", "spectral_psd": "spectral",
        "projected": "spectral_fa", "projected_psd": "spectral", "projected_fa": "spectral_fa",
        "spectral_psd_init": "spectral_init", "fa_spectral_init": "spectral_fa_init",
        "fa_spectral": "spectral_fa", "spectral_fa_refine": "spectral_refine",
    }
    cov_solver = solver_alias.get(cov_solver, cov_solver)
    if cov_solver not in {"lbfgs", "spectral", "spectral_fa", "spectral_init", "spectral_fa_init", "spectral_refine"}:
        raise ValueError("solver must be 'lbfgs', 'spectral'/'projected_psd', 'spectral_fa'/'projected', 'spectral_init', 'spectral_fa_init', or 'spectral_refine'")
    pbar.stage("Covariance: moment matrices",phase_key="moments")
    is_multi = _legacy._v31_is_multigrm(grm) if hasattr(_legacy, "_v31_is_multigrm") else isinstance(grm, dict)
    if estimator == "minque":
        if is_multi:
            raise ValueError("moment_estimator='minque' currently supports one GRM; use default MoM for multi-kernel models")
        if int(n_boot) > 0:
            raise ValueError(
                "weighted no-copy animal bootstrap is not algebraically equivalent for fixed-P MINQUE; "
                "use analytic_se=True for the fast MINQUE sandwich or use moment_estimator='mom' with bootstrap"
            )
        moments = minque_moments_single_kernel(
            grm, Y, h2_ref=minque_h2_ref, kernel_rank=minque_kernel_rank,
            max_full_n=minque_max_full_n, random_state=0 if random_state is None else random_state, eps=eps,
        )
        kernels = {"genetic": as_kernel_operator(grm, dtype=block_dtype)}
        knames = ["genetic"]
    elif is_multi:
        # Preserve the existing dense multi-GRM moment kernel, but accept 2.6
        # low-rank/matrix-free operators without forcing dense reconstruction.
        operator_input = any(
            isinstance(v, KernelOperator)
            or (hasattr(v, "matmat") and hasattr(v, "diag") and hasattr(v, "shape"))
            or (isinstance(v, dict) and str(v.get("type", "")).lower() in {"eigh", "lowrank", "low_rank"})
            for v in grm.values()
        )
        if operator_input:
            kernels = {str(k): as_kernel_operator(v, dtype=block_dtype) for k, v in grm.items()}
            moments = weighted_multi_moments(kernels, Y.to_numpy(float), np.ones(len(Y)), block_size=block_size, accum_dtype=accum_dtype)
        else:
            kernels = _legacy._v31_named_kernels(grm, dtype=block_dtype)
            moments = _legacy._v31_multi_moments(kernels, Y, block_size=block_size, block_dtype=block_dtype, accum_dtype=accum_dtype, blas_threads=blas_threads)
        knames = list(moments["kernel_names"])
    else:
        operator_input = (
            isinstance(grm, KernelOperator)
            or (hasattr(grm, "matmat") and hasattr(grm, "diag") and hasattr(grm, "shape"))
            or (isinstance(grm, dict) and str(grm.get("type", "")).lower() in {"eigh", "lowrank", "low_rank"})
            or (isinstance(grm, tuple) and len(grm) >= 3 and str(grm[0]).lower() in {"eigh", "lowrank", "low_rank"})
        )
        if operator_input:
            op = as_kernel_operator(grm, dtype=block_dtype)
            kernels = {"genetic": op}
            moments = weighted_multi_moments(kernels, Y.to_numpy(float), np.ones(len(Y)), block_size=block_size, accum_dtype=accum_dtype)
        else:
            K = np.asarray(grm if not isinstance(grm, dict) else grm.get("matrix"), dtype=block_dtype)
            kernels = {"genetic": K}
            moments = _single_moments(K, Y, mode=mode, block_size=block_size, block_dtype=block_dtype,
                                      accum_dtype=accum_dtype, square_dtype=square_dtype, dense_threshold_gb=dense_threshold_gb)
        knames = ["genetic"]
    names = knames + ["E"]

    # 2.9.2 marginal-variance closure: observed trait variance is an additional
    # second moment.  The default is a soft Gaussian-information-weighted term;
    # diagnostic/off modes retain the original MoM objective.
    closure_key = "auto" if variance_closure is True else str(variance_closure).lower()
    if variance_closure is False or variance_closure is None or closure_key in {"off","none","false","diagnostic"}:
        closure_enabled = False
    elif closure_key in {"auto","soft","moment","weighted"}:
        closure_enabled = True
    else:
        raise ValueError("variance_closure must be 'auto'/'soft', 'diagnostic', or 'off'")
    closure_moment = _phenotypic_variance_moment(Y, eps=max(float(eps),1e-12))
    closure_weight = np.asarray(closure_moment['precision'],float) * max(float(variance_closure_strength),0.0)
    if closure_enabled and estimator != "minque":
        moments = _augment_moments_variance_closure(moments, closure_moment['variance'], closure_weight)

    if isinstance(rank_G, dict):
        granks = []
        for n in knames:
            rv = rank_G.get(n, "full")
            granks.append(None if isinstance(rv, str) and rv.lower() == "auto" else _rank_value(rv, T))
    else:
        granks = [_rank_value(rank_G, T) if rank_G != "auto" else None for _ in knames]
    erank = _rank_value(rank_E, T) if rank_E != "auto" else None
    selection = None
    if any(r is None for r in granks) or erank is None:
        if str(rank_selection).lower() in {"cv", "moment_cv", "auto"}:
            auto_candidates = [c for c in rank_candidates if not (str(c).lower() == "full" and T > 300)]
            if not auto_candidates:
                auto_candidates = [min(T, 100)]
            if cov_solver == "lbfgs":
                selection = select_mom_fa_rank(
                    moments, candidates=auto_candidates, rank_E="same" if erank is None else erank,
                    random_state=0 if random_state is None else random_state,
                    validation_fraction=rank_validation_fraction,
                    maxiter=min(int(maxiter), 300), gtol=max(float(gtol), 1e-6), ftol=max(float(ftol), 1e-9), eps=eps,
                    warm_start=warm_start,
                )
            else:
                selection = select_mom_spectral_rank(
                    moments, candidates=auto_candidates, rank_E="same" if erank is None else erank,
                    random_state=0 if random_state is None else random_state,
                    validation_fraction=rank_validation_fraction,
                    structure="psd" if cov_solver in {"spectral","spectral_init"} else "fa",
                    spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps,
                    refine=(cov_solver == "spectral_refine"), refine_maxiter=spectral_refine_maxiter,
                    gtol=max(float(gtol), 1e-6), ftol=max(float(ftol), 1e-9), eps=eps,
                )
            srG, srE = selection["selected"]
            granks = [srG if r is None else r for r in granks]
            erank = srE if erank is None else erank
        else:
            default = min(T, max(10, min(100, int(math.ceil(2.0 * math.sqrt(T))))))
            granks = [default if r is None else r for r in granks]
            erank = default if erank is None else erank
    if str(E_structure).lower() in {"diag", "diagonal"}:
        erank = 0
    ranks = granks + [erank]

    # Resolve 2.10 factor geometry per covariance component.  The historical
    # covariance_structure spelling remains a convenient global default while
    # factor_structure_G may be a named-kernel mapping.
    if _covstruct_key in {"psd", "pca", "eigen"}:
        _global_factor_structure = "pca"
        _global_rotation = None
    elif _covstruct_key == "varimax_fa":
        _global_factor_structure = "fa"
        _global_rotation = "varimax"
    elif _covstruct_key == "sparse_pca":
        _global_factor_structure = "sparse_pca"
        _global_rotation = None
    elif _covstruct_key == "sparse_varimax_fa":
        _global_factor_structure = "sparse_fa"
        _global_rotation = "varimax"
    elif _covstruct_key == "sparse_fa":
        _global_factor_structure = "sparse_fa"
        _global_rotation = None
    else:
        _global_factor_structure = "fa"
        _global_rotation = None

    _gstruct_raw = _resolve_component_setting(factor_structure_G, knames, default=_global_factor_structure)
    _grot_raw = _resolve_component_setting(factor_rotation_G, knames, default=_global_rotation)
    _gstruct = []
    _grot = []
    for _sv, _rv in zip(_gstruct_raw, _grot_raw):
        _sk = "fa" if _sv is None else str(_sv).lower().replace("-", "_")
        if _sk == "varimax_fa":
            _sk, _rv = "fa", ("varimax" if _rv is None else _rv)
        elif _sk == "sparse_varimax_fa":
            _sk, _rv = "sparse_fa", ("varimax" if _rv is None else _rv)
        _gstruct.append(_normalize_factor_structure(_sk))
        _grot.append(_rv)
    _estruct_raw = _global_factor_structure if factor_structure_E is None else factor_structure_E
    _erot = _global_rotation if factor_rotation_E is None else factor_rotation_E
    _esk = str(_estruct_raw).lower().replace("-", "_")
    if _esk == "varimax_fa":
        _esk, _erot = "fa", ("varimax" if _erot is None else _erot)
    elif _esk == "sparse_varimax_fa":
        _esk, _erot = "sparse_fa", ("varimax" if _erot is None else _erot)
    _estruct = _normalize_factor_structure(_esk)
    factor_structures = _gstruct + [_estruct]
    factor_rotations = _grot + [_erot]
    factor_lambdas = _resolve_component_setting(factor_lambda_G, knames, default=None) + [factor_lambda_E]
    factor_group_lambdas = _resolve_component_setting(factor_group_lambda_G, knames, default=0.0) + [factor_group_lambda_E]
    # Asking for a sparse structure without an explicit lambda requests the
    # conservative curvature-scaled automatic support selector.
    factor_lambdas = [("auto" if (st in {"sparse_fa", "sparse_pca"} and lv is None) else lv)
                      for st, lv in zip(factor_structures, factor_lambdas)]

    ridge = [float(ridge_G.get(n, 0.0)) if isinstance(ridge_G, dict) else float(ridge_G) for n in knames] + [float(ridge_E)]
    if isinstance(h2_prior_strength, bool) or not isinstance(h2_prior_strength, numbers.Real) \
            or not np.isfinite(h2_prior_strength) or h2_prior_strength < 0:
        raise ValueError("h2_prior_strength must be a finite nonnegative number")
    h2_penalty = None
    if h2_prior_strength > 0:
        if cov_solver != "lbfgs" or estimator == "minque":
            raise ValueError("h2_prior_strength>0 requires solver='lbfgs' with MoM/score moments")
        if bool(structural_refine):
            raise ValueError("h2_prior_strength>0 is not supported with structural_refine")
        if int(n_boot) > 0:
            raise ValueError("h2_prior_strength>0 uses the analytic sandwich (analytic_se='final'); "
                             "bootstrap refits do not re-estimate the prior, so n_boot must be 0")
        from .h2_prior import pilot_uncertainty, build_penalty
        pbar.stage("Covariance: h² prior pilot", phase_key="fit")
        _applied_closure = closure_weight if closure_enabled else np.zeros(T)
        _pilot = pilot_uncertainty({n: kernels[n] for n in knames}, Y, moments, ridge, _applied_closure,
                                   n_probes=int(h2_prior_probes), method=h2_prior_pilot,
                                   probe_seed=42 if random_state is None else int(random_state),
                                   kernel_rank=spectral_se_kernel_rank)
        h2_penalty = build_penalty(float(h2_prior_strength), h2_prior_groups, Y.columns, _pilot)
    pbar.stage(f"Covariance: {cov_solver} fit",phase_key="fit")
    if cov_solver == "spectral":
        fit = fit_mom_projected(
            moments, ranks=ranks, names=names, ridge=ridge, structure="psd",
            spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps,
            maxiter=projected_maxiter, tol=projected_tol, step_scale=projected_step_scale, eps=eps,
        )
    elif cov_solver == "spectral_fa":
        fit = fit_mom_projected(
            moments, ranks=ranks, names=names, ridge=ridge, structure="fa",
            spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps,
            maxiter=projected_maxiter, tol=projected_tol, step_scale=projected_step_scale, eps=eps,
        )
    elif cov_solver == "spectral_init":
        fit = fit_mom_spectral(
            moments, ranks=ranks, names=names, ridge=ridge, structure="psd",
            spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps, eps=eps,
        )
    elif cov_solver == "spectral_fa_init":
        fit = fit_mom_spectral(
            moments, ranks=ranks, names=names, ridge=ridge, structure="fa",
            spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps, eps=eps,
        )
    elif cov_solver == "spectral_refine":
        fit = fit_mom_spectral_refine(
            moments, ranks=ranks, names=names, ridge=ridge, structure="fa",
            spectral_weighting=spectral_weighting, spectral_fa_sweeps=spectral_fa_sweeps,
            refine_maxiter=spectral_refine_maxiter, gtol=gtol, ftol=ftol, eps=eps,
        )
    else:
        # Inside hyper_opt workers, candidates that differ only in post-fit settings share this fit.
        from .fit_cache import cached_fit
        fit = cached_fit(
            fit_mom_factor_analytic,
            moments, ranks=ranks, names=names, ridge=ridge, warm_start=warm_start,
            structures=factor_structures, rotations=factor_rotations,
            factor_lambda=factor_lambdas, factor_group_lambda=factor_group_lambdas,
            factor_adaptive=factor_adaptive, factor_relaxed_refit=factor_relaxed_refit,
            factor_support_tol=factor_support_tol, factor_sparse_maxiter=factor_sparse_maxiter,
            factor_sparse_tol=factor_sparse_tol, factor_auto_fraction=factor_auto_fraction,
            maxiter=maxiter, gtol=gtol, ftol=ftol, eps=eps, h2_penalty=h2_penalty,
        )
    structural_result = None
    if bool(structural_refine):
        if cov_solver != "lbfgs":
            raise ValueError("structural_refine currently requires solver='lbfgs' so the final inference fit remains support-fixed PSD/FA L-BFGS")
        structural_result = _fit_structural_refinement_loop(
            moments, fit, Y, knames=knames, names=names, ranks=ranks, ridge=ridge,
            structures=factor_structures, rotations=factor_rotations,
            factor_lambda=factor_lambdas, factor_group_lambda=factor_group_lambdas,
            factor_adaptive=factor_adaptive, factor_relaxed_refit=factor_relaxed_refit,
            factor_support_tol=factor_support_tol, factor_sparse_maxiter=factor_sparse_maxiter,
            factor_sparse_tol=factor_sparse_tol, factor_auto_fraction=factor_auto_fraction,
            outer_iter=structural_outer_iter, pc_source=structural_pc_source,
            pc_alpha=structural_pc_alpha, pc_max_cond_set=structural_pc_max_cond_set,
            pc_multiple_testing=structural_pc_multiple_testing, pc_n_eff=structural_pc_n_eff,
            pc_max_neighbors=structural_pc_max_neighbors, pc_min_abs_r=structural_pc_min_abs_r,
            pc_stability_bootstrap=structural_pc_stability_bootstrap,
            pc_edge_stability=structural_pc_edge_stability, pc_direction_stability=structural_pc_direction_stability,
            anm=structural_anm, anm_min_ratio=structural_anm_min_ratio,
            anm_stability_bootstrap=structural_anm_stability_bootstrap,
            anm_direction_stability=structural_anm_direction_stability,
            required_edges=structural_required_edges, forbidden_edges=structural_forbidden_edges,
            order=structural_order, sem_l1=structural_sem_l1, sem_bound=structural_sem_bound,
            sem_innovation_rank=structural_sem_innovation_rank, sem_innovation_sparse=structural_sem_innovation_sparse,
            dag_extensions=structural_dag_extensions, dag_topk=structural_dag_topk,
            path_min_abs=structural_path_min_abs,
            maxiter=int(structural_maxiter), covariance_maxiter=int(maxiter), gtol=gtol, ftol=ftol, eps=eps,
            random_state=0 if random_state is None else int(random_state), progress=pbar,
        )
        fit = structural_result["fit"]

    # 2.8.3: regularization is resolved explicitly and then reused unchanged by
    # the bootstrap. Plain ``auto`` uses mild G sample-size shrinkage plus
    # per-pair overlap/(overlap+400) E shrinkage; held-out moment CV is opt-in
    # through ``auto_cv`` because moment error is not identical to BLUP loss.
    overlap = Y.notna().astype(np.int64).T @ Y.notna().astype(np.int64)
    overlap_arr = overlap.to_numpy(dtype=float)
    support = overlap_arr >= int(min_E_pair_overlap)
    np.fill_diagonal(support, True)
    cv_G = (isinstance(shrink_G, str) and shrink_G.lower() in {"auto_cv", "cv"}) or (
        isinstance(shrink_G, dict) and any(isinstance(v, str) and v.lower() in {"auto_cv", "cv"} for v in shrink_G.values())
    )
    cv_E = isinstance(shrink_E, str) and shrink_E.lower() in {"auto_cv", "cv"}
    cv_structure = residual_mode == "auto_cv"
    regularization_selection = None
    if cv_G or cv_E or cv_structure:
        # Experimental held-out-moment CV remains opt-in.  Plain ``auto`` no
        # longer uses this criterion because direct mvBLUP benchmarks showed
        # that moment NRMSE and prediction loss need not rank shrinkage equally.
        def cv_token(v):
            """Construct a cache identifier for the current cross-validation configuration.

            Parameters
            ----------
            v : array-like
                Numerical operand in ``v.lower() in {'auto_cv', 'cv'}``. Shape must conform to that
                matrix/vector operation and the enclosing prepared state.

            Returns
            -------
            object
                Computed result from ``'auto' if isinstance(v, str) and v.lower() in {'auto_cv', 'cv'} else v``; see the summary and the called implementation for its labeled/numerical representation.
            """
            return "auto" if isinstance(v, str) and v.lower() in {"auto_cv", "cv"} else v
        sg_cv = ({k: cv_token(v) for k, v in shrink_G.items()} if isinstance(shrink_G, dict) else cv_token(shrink_G))
        se_cv = cv_token(shrink_E)
        es_cv = "auto" if residual_mode == "auto_cv" else residual_mode
        regularization_selection = _select_regularization_policy(
            moments, ranks, names, shrink_G=sg_cv, shrink_E=se_cv, E_structure=es_cv,
            validation_fraction=rank_validation_fraction,
            random_state=0 if random_state is None else int(random_state),
            min_E_pair_overlap=min_E_pair_overlap, spectral_weighting=spectral_weighting,
            spectral_fa_sweeps=spectral_fa_sweeps, eps=eps,
        )
        regularization_policy = regularization_selection["policy"]
        regularization_policy = dict(regularization_policy, selection_objective="held_out_moment_nrmse_experimental")
    else:
        regularization_policy = _regularization_policy_from_requests(
            fit["specs"], names, overlap_arr, shrink_G=shrink_G, shrink_E=shrink_E,
            E_structure=residual_mode, moments=moments, min_E_pair_overlap=min_E_pair_overlap, eps=eps,
        )
        regularization_policy = dict(regularization_policy, selection_objective="analytic_heuristic")
    final_specs = _apply_regularization_policy(
        fit["specs"], names, overlap_arr, regularization_policy,
        min_E_pair_overlap=min_E_pair_overlap, eps=eps,
    )
    specs = {n0: final_specs[n0] for n0 in knames}
    Espec = final_specs["E"]
    spec_alpha = dict(regularization_policy.get("G_alpha", {n0: 1.0 for n0 in knames}))
    emode = str(regularization_policy.get("E_mode", "none")).lower()
    if emode == "scalar":
        ealpha = float(regularization_policy.get("E_alpha", 1.0))
        amat = np.full_like(overlap_arr, ealpha, dtype=float)
        np.fill_diagonal(amat, 1.0)
    elif emode in {"pairwise", "pairwise_overlap", "overlap"}:
        estrength = float(regularization_policy.get("E_strength", 0.0))
        amat = np.divide(overlap_arr, overlap_arr + estrength, out=np.ones_like(overlap_arr), where=(overlap_arr + estrength) > 0)
        np.fill_diagonal(amat, 1.0)
        iu = np.triu_indices(T, 1)
        ealpha = float(np.median(amat[iu])) if len(iu[0]) else 1.0
    elif emode in {"fisher_eb", "pairwise_eb", "eb"}:
        tau2 = max(float(regularization_policy.get("E_tau2", 0.0)), 0.0)
        amat = np.zeros_like(overlap_arr, dtype=float)
        ok_ov = overlap_arr >= 4
        svar = np.full_like(overlap_arr, np.inf, dtype=float)
        svar[ok_ov] = 1.0 / np.maximum(overlap_arr[ok_ov] - 3.0, 1.0)
        if tau2 > 0:
            amat[ok_ov] = tau2 / (tau2 + svar[ok_ov])
        np.fill_diagonal(amat, 1.0)
        iu = np.triu_indices(T, 1)
        ealpha = float(np.median(amat[iu])) if len(iu[0]) else 1.0
    elif emode == "pairwise_weights":
        amat = np.asarray(regularization_policy["E_weights"], dtype=float).copy()
        np.fill_diagonal(amat, 1.0)
        iu = np.triu_indices(T, 1)
        ealpha = float(np.median(amat[iu])) if len(iu[0]) else 1.0
    elif emode in {"diag", "diagonal"}:
        ealpha = 0.0
        amat = np.eye(T)
    else:
        ealpha = 1.0
        amat = np.ones_like(overlap_arr, dtype=float)
    residual_resolved = str(regularization_policy.get("E_structure_resolved", residual_mode))
    Gcomp = {n0: specs[n0].materialize() for n0 in knames}
    G = sum(Gcomp.values(), np.zeros((T, T)))
    E = Espec.materialize()
    # Preserve a strict estimand contract: bare G/E/Rg are the inference
    # estimates whose analytical SE/CI fields are reported beside them.
    # Prediction-only regularization is exposed exclusively through explicit
    # *_prediction fields and consumed explicitly by prediction APIs.
    Gcomp_unshrunk = {n0: fit["specs"][n0].materialize() for n0 in knames}
    G_unshrunk = sum(Gcomp_unshrunk.values(), np.zeros((T, T)))
    E_unshrunk = fit["specs"]["E"].materialize()
    Rg_unshrunk0, vg_unshrunk, valid_vg_unshrunk = _legacy._rg_from_G_psd(
        G_unshrunk, eps=max(float(eps),1e-15)
    )
    boundary_unshrunk = _variance_boundary_diagnostics(
        G_unshrunk, E, closure_moment['variance'], rtol=variance_boundary_rtol, atol=variance_boundary_atol
    )
    Rg_unshrunk, _ = _mask_rg_at_variance_boundary(Rg_unshrunk0, boundary_unshrunk)
    boundary = _variance_boundary_diagnostics(
        G, E, closure_moment['variance'], rtol=variance_boundary_rtol, atol=variance_boundary_atol
    )
    _vpse=np.asarray(closure_moment['se'],float)
    boundary['variance_closure_z']=np.divide(
        boundary['variance_closure_error'],_vpse,out=np.full(T,np.nan),where=np.isfinite(_vpse)&(_vpse>0)
    )
    boundary['variance_closure_flag']=np.isfinite(boundary['variance_closure_z']) & (np.abs(boundary['variance_closure_z'])>3.0)
    Rg0, vg, valid = _legacy._rg_from_G_psd(G, eps=max(float(eps),1e-15))
    Rg, rg_boundary = _mask_rg_at_variance_boundary(Rg0, boundary)
    valid = np.asarray(valid,bool) & ~np.asarray(boundary['G_near_zero'],bool) & ~np.asarray(boundary['total_near_zero'],bool)
    columns = Y.columns
    Gdf = pd.DataFrame(G, index=columns, columns=columns)
    Edf = pd.DataFrame(E, index=columns, columns=columns)
    Gspec_total = FactorCovarianceSpec(
        np.concatenate([specs[n0].factor for n0 in knames], axis=1) if knames else np.zeros((T, 0)),
        sum((specs[n0].diag_specific for n0 in knames), np.zeros(T)),
        name="G",
    )
    Gdf.attrs["domino_covspec"] = Gspec_total.to_dict(include_matrix=False)
    Edf.attrs["domino_covspec"] = Espec.to_dict(include_matrix=False)
    out = pd.Series({
        "G": pd.DataFrame(G_unshrunk, index=columns, columns=columns),
        "E": pd.DataFrame(E_unshrunk, index=columns, columns=columns),
        "G_prediction": Gdf,
        "E_prediction": Edf,
        "Rg": pd.DataFrame(Rg_unshrunk, index=columns, columns=columns),
        "Rg_prediction": pd.DataFrame(Rg, index=columns, columns=columns),
        "Rg_shrunk": pd.DataFrame(Rg, index=columns, columns=columns),
        "G_unshrunk": pd.DataFrame(G_unshrunk, index=columns, columns=columns),
        "G_inference": pd.DataFrame(G_unshrunk, index=columns, columns=columns),
        "E_unshrunk": pd.DataFrame(E_unshrunk, index=columns, columns=columns),
        "E_inference": pd.DataFrame(E_unshrunk, index=columns, columns=columns),
        "Rg_unshrunk": pd.DataFrame(Rg_unshrunk, index=columns, columns=columns),
        "Rg_inference": pd.DataFrame(Rg_unshrunk, index=columns, columns=columns),
        "vg_unshrunk": pd.Series(vg_unshrunk, index=columns),
        "vg": pd.Series(vg, index=columns),
        "valid_vg": valid,
        "invalid_var_mask": ~valid,
        "n_invalid_variances": int((~valid).sum()),
        "invalid_traits": list(columns[~valid]),
        "phenotypic_variance_observed": pd.Series(boundary['phenotypic_variance_observed'], index=columns),
        "phenotypic_variance_model": pd.Series(boundary['phenotypic_variance_model'], index=columns),
        "variance_closure_ratio": pd.Series(boundary['variance_closure_ratio'], index=columns),
        "variance_closure_error": pd.Series(boundary['variance_closure_error'], index=columns),
        "variance_closure_z": pd.Series(boundary['variance_closure_z'], index=columns),
        "variance_closure_flag": pd.Series(boundary['variance_closure_flag'], index=columns),
        "h2_model": pd.Series(boundary['h2_model'], index=columns),
        "h2_phenotype": pd.Series(boundary['h2_phenotype'], index=columns),
        "variance_boundary": {
            "G_near_zero": pd.Series(boundary['G_near_zero'], index=columns),
            "E_near_zero": pd.Series(boundary['E_near_zero'], index=columns),
            "total_near_zero": pd.Series(boundary['total_near_zero'], index=columns),
            "tolerance": pd.Series(boundary['tolerance'], index=columns),
            "G_exceeds_phenotypic_variance": pd.Series(boundary['G_exceeds_phenotypic_variance'], index=columns),
        },
        "rg_boundary": pd.DataFrame(rg_boundary, index=columns, columns=columns),
        "variance_closure": {
            "mode": ("soft" if closure_enabled else closure_key),
            "enabled": bool(closure_enabled and estimator != "minque"),
            "strength": float(variance_closure_strength),
            "target": pd.Series(closure_moment['variance'], index=columns),
            "target_se": pd.Series(closure_moment['se'], index=columns),
            "weight": pd.Series(closure_weight, index=columns),
            "included_in_analytic_se": bool(closure_enabled and estimator != "minque"),
        },
        "G_components": {n0: pd.DataFrame(Gcomp_unshrunk[n0], index=columns, columns=columns) for n0 in knames},
        "G_components_prediction": {n0: pd.DataFrame(Gcomp[n0], index=columns, columns=columns) for n0 in knames},
        "G_components_unshrunk": {n0: pd.DataFrame(Gcomp_unshrunk[n0], index=columns, columns=columns) for n0 in knames},
        "G_components_inference": {n0: pd.DataFrame(Gcomp_unshrunk[n0], index=columns, columns=columns) for n0 in knames},
        "component_specs": {n0: fit["specs"][n0].to_dict(include_matrix=False) for n0 in knames},
        "component_specs_prediction": {n0: specs[n0].to_dict(include_matrix=False) for n0 in knames},
        "component_specs_unshrunk": {n0: fit["specs"][n0].to_dict(include_matrix=False) for n0 in knames},
        "G_spec": FactorCovarianceSpec(
            np.concatenate([fit["specs"][n0].factor for n0 in knames], axis=1) if knames else np.zeros((T,0)),
            sum((fit["specs"][n0].diag_specific for n0 in knames), np.zeros(T)), name="G"
        ).to_dict(include_matrix=False),
        "G_spec_prediction": Gspec_total.to_dict(include_matrix=False),
        "E_spec": fit["specs"]["E"].to_dict(include_matrix=False),
        "E_spec_prediction": Espec.to_dict(include_matrix=False),
        "rank_G": {n0: specs[n0].rank for n0 in knames} if len(knames) > 1 else specs[knames[0]].rank,
        "rank_E": Espec.rank,
        "rank_G_requested": rank_G,
        "rank_E_requested": rank_E,
        "shrink_G": spec_alpha[knames[0]] if len(knames) == 1 else dict(spec_alpha),
        "shrink_G_requested": shrink_G,
        "reporting_recommendation": "Bare G/E/Rg are inference estimands and match their SE/CI fields. Use G_prediction/E_prediction explicitly for mvBLUP and other prediction-only geometry.",
        "shrink_E": float(ealpha),
        "shrink_E_requested": shrink_E,
        "shrink_E_mode": emode,
        "shrink_E_strength": regularization_policy.get("E_strength", None),
        "shrink_E_tau2": regularization_policy.get("E_tau2", None),
        "E_rank_preserving_shrinkage": bool(regularization_policy.get("E_rank_preserve", False)),
        "E_rank_before_shrinkage": int(fit["specs"]["E"].rank),
        "E_rank_after_shrinkage": int(Espec.rank),
        "E_shrinkage_weights": pd.DataFrame(amat, index=columns, columns=columns),
        "regularization_policy": regularization_policy,
        "regularization_selection": None if regularization_selection is None else regularization_selection["table"],
        "E_pair_overlap": overlap,
        "E_support_mask": pd.DataFrame(support, index=columns, columns=columns),
        "E_structure_requested": E_structure,
        "E_structure_resolved": residual_resolved,
        "G_specific_var": {name: spec.diag_specific.copy() for name, spec in specs.items()},
        "E_specific_var": Espec.diag_specific.copy(),
        "rank_selection": None if selection is None else selection["table"],
        "optimize_hyperparameters_cv": 0,
        "hyperparameter_optimization": None,
        "rank_selection_note": (None if selection is None else
            ("full rank skipped during automatic CV for T>300; use an explicit full-rank fit or benchmark_rank_260.py"
             if T > 300 and any(str(c).lower() == "full" for c in rank_candidates) else "held-out MoM entry CV")),
        "result": fit["result"],
        "success": fit["success"],
        "optimizer_converged": fit.get("optimizer_converged", fit["success"]),
        "message": fit["message"],
        "nit": getattr(fit["result"], "nit", None),
        "fun": fit["objective"],
        "n_parameters": fit["n_parameters"],
        "covariance_structure": (
            "sparse_factor_analytic" if cov_solver == "lbfgs" and all(st == "sparse_fa" for st in factor_structures) else
            "sparse_low_rank_psd" if cov_solver == "lbfgs" and all(st == "sparse_pca" for st in factor_structures) else
            "low_rank_psd" if cov_solver in {"spectral", "spectral_init"} or (cov_solver == "lbfgs" and all(st == "pca" for st in factor_structures)) else
            "factor_analytic" if cov_solver == "lbfgs" and all(st == "fa" for st in factor_structures) else
            "mixed_factor_geometry"
        ),
        "covariance_solver": cov_solver,
        "factor_structures": fit.get("factor_structures", dict(zip(names, factor_structures))),
        "factor_rotations": fit.get("factor_rotations", dict(zip(names, factor_rotations))),
        "factor_support": fit.get("factor_support", {n0: None for n0 in names}),
        "factor_loading_density": fit.get("loading_density", {n0: 1.0 for n0 in names}),
        "factor_effective_ranks": fit.get("effective_ranks", dict(zip(names, ranks))),
        "factor_sparse_diagnostics": fit.get("sparse_diagnostics", None),
        "factor_relaxed_refit": bool(factor_relaxed_refit),
        "spectral_weighting": (str(spectral_weighting) if cov_solver != "lbfgs" else None),
        "spectral_diagnostics": fit.get("spectral_diagnostics", None),
        "G_se": pd.DataFrame(np.nan, index=columns, columns=columns),
        "E_se": pd.DataFrame(np.nan, index=columns, columns=columns),
        "rg_se": pd.DataFrame(np.nan, index=columns, columns=columns),
        "n_boot": 0,
        "n_boot_success": 0,
        "version": VIGOR_MULTIVARIATE_VERSION,
        "moment_estimator": "minque" if estimator == "minque" else "mom",
    })
    if structural_result is not None and structural_result.get("sem") is not None:
        _sr = structural_result
        _sem = _sr["sem"]
        _tn = list(map(str, columns))
        out["structural_refine"] = True
        out["structural_status"] = _sr["structural_status"]
        out["structural_loop_status"] = _sr["loop_status"]
        out["structural_outer_stable"] = _sr["outer_stable"]
        out["structural_stationary_convergence_certified"] = False
        out["structural_history"] = _sr["history"]
        out["structural_pc"] = _sr["pc"]
        out["structural_anm"] = _sr["anm"]
        out["structural_graph"] = _sr["pc"].attrs["graph"]
        _pc_edges=_sr["pc"][["source","target","orientation"]].to_dataframe() if "orientation" in _sr["pc"] else pd.DataFrame(columns=["source","target","orientation"])
        _ndir=int((_pc_edges["orientation"]=="directed").sum()) if len(_pc_edges) else 0
        _nundir=int((_pc_edges["orientation"]=="undirected").sum()) if len(_pc_edges) else 0
        out["structural_graph_summary"] = {
            "skeleton_edges": int(len(_pc_edges)),
            "pc_directed_edges": _ndir,
            "pc_unresolved_edges": _nundir,
            "graph_arc_count_internal": int(_sr["pc"].attrs["graph"].number_of_edges()),
        }
        out["structural_pc_n_eff"] = float(_sr["pc_n_eff"])
        out["structural_pc_source"] = str(_sr["pc_source"])
        # Primary causal-path output contains only directions identified by the
        # CPDAG/Meek rules or a stability-qualified ANM orientation.  One fitted
        # DAG extension is retained separately for diagnostics; it is never
        # promoted to causal evidence merely because it has the best SEM score.
        _Brep=np.asarray(_sem["B"],float)
        _Bidentified=np.zeros_like(_Brep)
        _pst=_sr.get("sem_ensemble",{}).get("path_stability")
        _dir_thr=float(_sr.get("pc_direction_stability",0.75))
        if isinstance(_pst,pd.DataFrame) and len(_pst):
            _pos={str(x):i for i,x in enumerate(_tn)}
            for _rr in _pst.itertuples(index=False):
                if not bool(getattr(_rr,"direction_identified",False)): continue
                if float(getattr(_rr,"direction_support",0.0)) < _dir_thr: continue
                _dd=getattr(_rr,"identified_direction",None)
                if not isinstance(_dd,str) or "->" not in _dd: continue
                _src,_tgt=map(str.strip,_dd.split("->",1))
                if _src in _pos and _tgt in _pos:
                    _Bidentified[_pos[_tgt],_pos[_src]]=_Brep[_pos[_tgt],_pos[_src]]
        if not _sem['success']:
            _Bidentified[:]=np.nan
        _Hidentified=np.linalg.inv(np.eye(len(_tn))-_Bidentified) if _sem['success'] else np.full_like(_Bidentified,np.nan)
        out["structural_sem"] = {
            "B": pd.DataFrame(_Bidentified, index=_tn, columns=_tn),
            "B_identified": pd.DataFrame(_Bidentified, index=_tn, columns=_tn),
            "B_representative_extension": pd.DataFrame(_Brep, index=_tn, columns=_tn),
            "total_effect_matrix": pd.DataFrame(_Hidentified, index=_tn, columns=_tn),
            "total_effect_representative_extension": pd.DataFrame(_sem["H"], index=_tn, columns=_tn),
            "innovation_covariances": {n0: pd.DataFrame(M, index=_tn, columns=_tn) for n0, M in _sem["innovation_matrices"].items()},
            "reconstructed_covariances": {n0: pd.DataFrame(M, index=_tn, columns=_tn) for n0, M in _sem["matrices"].items()},
            "innovation_specs": {n0: sp.to_dict(include_matrix=False) for n0, sp in _sem["innovation_specs"].items()},
            "edge_mask": pd.DataFrame(_sem["edge_mask"], index=_tn, columns=_tn),
            "order": [_tn[i] for i in _sem["order_index"]],
            "order_source": _sem["order_source"],
            "objective": float(_sem["objective"]),
            "success": bool(_sem["success"]),
            "status": _sr["structural_status"],
            "selected_fit_status": _sem["selection_status"],
            "loop_status": _sr["loop_status"],
            "outer_stable": _sr["outer_stable"],
            "stationary_convergence_certified": False,
            "path_stability_scope": _sr["sem_ensemble"]["path_stability_scope"],
            "n_extensions_optimizer_success": _sr["sem_ensemble"]["n_extensions_optimizer_success"],
            "message": str(_sem["message"]),
            "n_parameters": int(_sem["n_parameters"]),
            "optimizer_diagnostics":{k:_sem.get(k) for k in ['iterations','dense_iterations','optimizer_objective',
                'final_parameter_objective','raw_gradient_norm','projected_gradient_inf_norm','stationarity_scope','objective_definition']},
            "factor_support": _sem.get("factor_support"),
            "factor_structures": _sem.get("factor_structures"),
            "innovation_identifiability": _sem.get("innovation_identifiability"),
            "residual_innovation_saturated": bool(_sem.get("residual_innovation_saturated",False)),
            "path_identifiability_note": _sem.get("path_identifiability_note"),
            "pc_skeleton_edges": int(len(_pc_edges)),
            "pc_directed_edges": _ndir,
            "pc_unresolved_edges": _nundir,
            "orientation_identified_by_pc": bool(_nundir == 0),
            "n_identified_paths": int(np.count_nonzero(np.abs(_Bidentified)>=float(_sr.get("sem_ensemble",{}).get("path_min_abs",0.05)))),
            "representative_extension_is_causal_output": False,
            "innovation_policy": _sr.get("innovation_policy"),
            "innovation_ranks": _sr.get("innovation_ranks"),
            "pc_stability_bootstrap": int(_sr.get("pc_stability_bootstrap",0)),
            "path_stability": _sr.get("sem_ensemble",{}).get("path_stability"),
            "total_effect_sensitivity": _sr.get("sem_ensemble",{}).get("total_effect_sensitivity"),
            "dag_extensions": _sr.get("sem_ensemble",{}).get("extensions"),
            "path_min_abs": _sr.get("sem_ensemble",{}).get("path_min_abs"),
        }
        out["structural_orientation_contract"] = (
            "PC/Meek/ANM orientations are reported separately from unresolved CPDAG adjacencies. "
            "When pc_unresolved_edges>0, VIGOR scores multiple acyclic DAG extensions rather than using one trait-order fallback. "
            "structural_sem['B'] contains only stability-qualified identified directions from optimizer-successful fits; failed selected fits yield unavailable NaN paths; structural_sem['B_representative_extension'] is diagnostic only and must not be interpreted as an identified causal direction. "
            "Unresolved directions are summarized by path_stability and total_effect_sensitivity rather than silently selected by trait order or SEM score."
        )
        out["structural_inference_contract"] = (
            "SEM is fitted directly to the original MoM tensors and feeds back into sparse PSD/FA warm starts/support selection. "
            "Bare G/E/Rg remain the final support-fixed PSD/FA inference estimator so analytic_se='final' uses its valid fixed-support tangent; "
            "SEM path-selection uncertainty is not included in those covariance SEs."
        )
        out["structural_uncertainty"] = {
            "covariance_analytic_se": "final support-fixed PSD/FA tangent conditional on selected rank, factor support, and structural graph",
            "sem_path_se": None,
            "graph_selection_uncertainty_included": False,
            "anm_selection_uncertainty_included": False,
            "anm_default": False,
            "anm_note": "ANM orientation is opt-in because linear-Gaussian direction is not identifiable by additive-noise asymmetry.",
            "bootstrap_replays_structural_selection": False,
        }
    elif structural_result is not None:
        _sr=structural_result;_tn=list(map(str,columns));_unknown=pd.DataFrame(np.nan,index=_tn,columns=_tn)
        _unsupported_fields=dict(structural_refine=True,structural_status='unsupported_pdag',
                   structural_history=_sr['history'],structural_pc=_sr['pc'],structural_anm=_sr['anm'],
                   structural_graph=_sr['pc'].attrs['graph'],structural_pc_source=str(_sr['pc_source']),
                   structural_pc_n_eff=float(_sr['pc_n_eff']),structural_graph_summary={
                       'graph_arc_count_internal':int(_sr['pc'].attrs['graph'].number_of_edges()),
                       'consistent_extensions':0,'status':'unsupported_pdag'},
                   structural_sem={'success':False,'status':'unsupported_pdag','message':_sr['message'],
                       'B':_unknown,'B_identified':_unknown.copy(),'B_representative_extension':_unknown.copy(),
                       'order':None,'objective':np.nan,'path_stability':pd.DataFrame(),'dag_extensions':pd.DataFrame(),
                       'optimizer_diagnostics':{'status':'not_run','reason':_sr['message']},
                       'representative_extension_is_causal_output':False},
                   structural_orientation_contract='Estimated PDAG admits no consistent DAG extension. Directions are unavailable, not a fitted null or a forced trait-order DAG.',
                   structural_inference_contract=_sr['note'])
        for _key,_value in _unsupported_fields.items():out[_key]=_value
    else:
        out["structural_refine"] = False

    if h2_penalty is not None:
        _diags = [np.diag(fit["specs"][n0].materialize()) for n0 in names]
        _pen_value, _, _h_fit, _mu_fit = _h2_penalty_terms(_diags, h2_penalty)
        _codes = h2_penalty["codes"]
        out["h2_prior_mean"] = pd.Series(_mu_fit[_codes], index=columns)
        out["h2_prior_tau2"] = pd.Series(h2_penalty["tau2"], index=columns)
        out["h2_prior_weight"] = pd.Series(h2_penalty["weight"], index=columns)
        out["h2_prior_kappa"] = pd.Series(h2_penalty["kappa"], index=columns)
        out["h2_pilot"] = pd.Series(h2_penalty["h2_pilot"], index=columns)
        out["h2_pilot_se"] = pd.Series(h2_penalty["se_pilot"], index=columns)
        out["h2_prior"] = {
            "active": True, "strength": h2_penalty["strength"],
            "groups": list(h2_penalty["group_names"]),
            "trait_group": [str(x) for x in h2_penalty["group_labels"]],
            "group_mean": [float(x) for x in _mu_fit],
            "group_tau2": [float(x) for x in h2_penalty["tau2_group"]],
            "tau2_floor": float(h2_penalty["tau2_floor"]),
            "penalty_value": float(_pen_value),
            "n_probes": h2_penalty["n_probes"], "probe_cache_hit": h2_penalty["cache_hit"],
            "pilot": h2_penalty.get("pilot_method"),
            "n_traits_without_pilot_se": int((~h2_penalty["valid"]).sum()),
            "pilot_valid": [bool(x) for x in h2_penalty["valid"]],
            "definition": "h2 = sum_c G_c[jj] / (sum_c G_c[jj] + E[jj]); penalty kappa_j (h2_j - mu_g)^2 inside the L-BFGS MoM objective",
            "weights": "kappa_j = strength * curvature_j * se_j^2 / (2 tau2_g); weight = 1/(1 + strength*se_j^2/tau2_g)",
        }
    else:
        out["h2_prior"] = {"active": False, "strength": float(h2_prior_strength)}

    checkpoint_point_fit(out)
    pbar.stage("Covariance: final uncertainty",phase_key="uncertainty")
    analytic_requested = not (analytic_se is False or analytic_se is None or str(analytic_se).lower() in {"false", "none", "off", "0"})
    # 2.8.5: True/auto means uncertainty for the final fixed-rank PSD/FA
    # estimator whenever the supported one-kernel/common-mask geometry is
    # available.  ``preconstraint`` retains the faster raw-MoM diagnostic.
    analytic_mode = "final" if analytic_se is True else str(analytic_se).lower()
    if analytic_se_probes is None:
        analytic_se_probes = 64
    ase_probes = int(analytic_se_probes)
    analytic_probe_policy = "explicit"
    if analytic_requested and ase_probes < 8:
        raise ValueError("analytic_se_probes must be at least 8")
    atrace_probes = int(spectral_trace_probes if analytic_trace_probes is None else analytic_trace_probes)
    pre_modes = {"preconstraint", "pre_constraint", "mom", "raw"}
    if estimator == "minque":
        out["minque"] = moments.get("minque", {})
        if analytic_requested:
            if len(knames) != 1:
                raise RuntimeError("analytic MINQUE SE currently requires one GRM")
            base_Gcomp = {n0: fit["specs"][n0].materialize() for n0 in knames}
            base_G = sum(base_Gcomp.values(), np.zeros((T, T)))
            base_E = fit["specs"]["E"].materialize()
            ase = _minque_sandwich_se(
                base_G, base_E, S=moments["minque"]["S"],
                trace_tensor=moments["minque"]["trace_tensor"],
                shrink_G=1.0,
                shrink_E=1.0, eps=eps,
            )
            out["G_se"] = pd.DataFrame(ase["G_se"], index=columns, columns=columns)
            out["E_se"] = pd.DataFrame(ase["E_se"], index=columns, columns=columns)
            out["rg_se"] = pd.DataFrame(ase["rg_se"], index=columns, columns=columns)
            out["h2"] = pd.Series(ase["h2"], index=columns)
            out["h2_se"] = pd.Series(ase["h2_se"], index=columns)
            out["h2_ci95"] = pd.DataFrame(ase["h2_ci95"], index=columns, columns=["lower", "upper"])
            out["analytic_se"] = {k: v for k, v in ase.items() if k not in {"G_se", "E_se", "rg_se", "h2", "h2_se", "h2_ci95", "cov_GE_entry"}}
            out["uncertainty_method"] = ase["method"]
    elif analytic_requested:
        try:
            if h2_penalty is not None and analytic_mode in pre_modes:
                raise ValueError("an active h2 prior requires analytic_se='final'; pre-constraint moment SEs ignore the prior")
            strict_legacy = False
            if len(knames) == 1:
                # Strict spectral tangent for analytic_se=True on unregularized
                # strict PSD spectral fits.
                _emode0 = str(regularization_policy.get("E_mode", "none")).lower()
                _eidentity = (_emode0 in {"none", "fa", "full"}) or (
                    _emode0 == "scalar" and float(regularization_policy.get("E_alpha", 1.0)) >= 1.0 - 1e-15
                )
                strict_legacy = (
                    cov_solver == "spectral" and (analytic_se is True)
                    and float(spec_alpha[knames[0]]) >= 1.0 - 1e-15
                    and _eidentity
                    and str(regularization_policy.get("E_structure_mode", "none")).lower() in {"none", "fa", "full"}
                )
            if analytic_mode in pre_modes and len(knames) != 1:
                raise ValueError("multi-kernel analytic SE currently supports the final PSD/FA sandwich; use analytic_se='final'")
            if analytic_mode in pre_modes:
                ase = mom_preconstraint_analytic_se(
                    grm, Y, moments, Gspec_total, Espec,
                    n_probes=ase_probes, trace_probes=atrace_probes,
                    kernel_rank=spectral_se_kernel_rank, max_full_n=spectral_se_max_full_n,
                    random_state=0 if random_state is None else int(random_state), eps=eps,
                )
            elif strict_legacy:
                ase = spectral_mom_analytic_se(
                    grm, Y, moments, specs[knames[0]], Espec,
                    n_probes=ase_probes, trace_probes=atrace_probes,
                    kernel_rank=spectral_se_kernel_rank, max_full_n=spectral_se_max_full_n,
                    random_state=0 if random_state is None else int(random_state), eps=eps,
                )
            else:
                from .fa_sandwich import final_fa_sandwich_se
                ase = final_fa_sandwich_se(
                    {n0: kernels[n0] for n0 in knames}, Y, moments,
                    {n0: fit["specs"][n0] for n0 in names}, ridge=ridge, h2_penalty=h2_penalty,
                    n_probes=ase_probes, max_probes=analytic_se_max_probes, mc_rtol=analytic_se_mc_rtol,
                    kernel_factor=analytic_kernel_factor, kernel_rank=spectral_se_kernel_rank,
                    random_state=0 if random_state is None else int(random_state), eps=eps,
                    boundary_tol=fa_se_boundary_tol, cg_rtol=fa_se_cg_rtol, cg_maxiter=fa_se_cg_maxiter,
                    ci_level=analytic_ci_level,
                )
            if h2_penalty is not None:
                from .h2_prior import robust_intervals
                _G_total = sum((fit["specs"][n0].materialize() for n0 in knames), np.zeros((T, T)))
                _robust = robust_intervals(
                    ase["h2"], ase["h2_se"], np.diag(_G_total), ase["G_variance_se"],
                    np.diag(fit["specs"]["E"].materialize()), ase["E_variance_se"],
                    h2_penalty, ci_level=analytic_ci_level)
                ase.update(_robust)
                out["h2_ci_critical_value"] = pd.Series(_robust["h2_ci_critical_value"], index=columns)
                out["h2_ci_bias_m2"] = pd.Series(_robust["h2_ci_bias_m2"], index=columns)
            out["G_se"] = pd.DataFrame(ase["G_se"], index=columns, columns=columns)
            out["E_se"] = pd.DataFrame(ase["E_se"], index=columns, columns=columns)
            out["rg_se"] = pd.DataFrame(ase["rg_se"], index=columns, columns=columns)
            out["h2"] = pd.Series(ase["h2"], index=columns)
            out["h2_se"] = pd.Series(ase["h2_se"], index=columns)
            out["h2_ci95"] = pd.DataFrame(ase["h2_ci95"], index=columns, columns=["lower", "upper"])
            if "component_se" in ase:
                out["G_component_se"] = {
                    n0: pd.DataFrame(ase["component_se"][n0], index=columns, columns=columns) for n0 in knames
                }
            if "G_variance_se" in ase:
                out["G_variance_se"] = pd.Series(ase["G_variance_se"], index=columns)
                out["E_variance_se"] = pd.Series(ase["E_variance_se"], index=columns)
            if "G_variance_ci95" in ase:
                out["G_variance_ci95"] = pd.DataFrame(ase["G_variance_ci95"], index=columns, columns=["lower", "upper"])
                out["E_variance_ci95"] = pd.DataFrame(ase["E_variance_ci95"], index=columns, columns=["lower", "upper"])
                out["rg_ci95_low"] = pd.DataFrame(ase["rg_ci95_low"], index=columns, columns=columns)
                out["rg_ci95_high"] = pd.DataFrame(ase["rg_ci95_high"], index=columns, columns=columns)
            if "cov_GE_diag" in ase:
                out["cov_GE_diag"] = pd.Series(ase["cov_GE_diag"], index=columns)
            out["analytic_se"] = {k: v for k, v in ase.items() if k not in {
                "G_se", "E_se", "rg_se", "h2", "h2_se", "h2_ci95",
                "G_variance_se", "E_variance_se", "G_variance_ci95", "E_variance_ci95",
                "rg_ci95_low", "rg_ci95_high", "cov_GE_diag", "component_se", "component_var",
                "h2_ci_critical_value", "h2_ci_bias_m2",
            }}
            out["analytic_se"]["probe_policy"] = analytic_probe_policy
            out["analytic_se"]["conditional_on_rank"] = True
            out["analytic_se"]["conditional_on_sparse_support"] = bool(any(st in {"sparse_fa", "sparse_pca"} for st in factor_structures))
            out["analytic_se"]["includes_support_selection_uncertainty"] = False
            out["analytic_se"]["h2_interval"] = ("robust empirical-Bayes interval (Armstrong, Kolesar and Plagborg-Moller 2022)"
                                                 if h2_penalty is not None else "logit-scale Wald interval")
            out["uncertainty_method"] = ase["method"]
        except ValueError as exc:
            out["analytic_se"] = {"available": False, "reason": str(exc)}
    # Boundary-safe inference.  rG is undefined when either marginal genetic
    # variance is effectively zero; h2 remains a valid bounded estimate when
    # exactly one component is on its variance boundary.
    _badg=np.asarray(boundary['G_near_zero'],bool)|np.asarray(boundary['total_near_zero'],bool)
    _pairbad=_badg[:,None]|_badg[None,:]
    out['Rg']=out['Rg'].mask(pd.DataFrame(_pairbad,index=columns,columns=columns))
    if 'rg_se' in out:
        out['rg_se']=out['rg_se'].mask(pd.DataFrame(_pairbad,index=columns,columns=columns))
    for _k in ('rg_ci95_low','rg_ci95_high'):
        if _k in out:
            out[_k]=out[_k].mask(pd.DataFrame(_pairbad,index=columns,columns=columns))
    if 'h2' not in out:
        out['h2']=pd.Series(boundary['h2_model'],index=columns)
    if 'h2_ci95' in out:
        _ci=np.asarray(out['h2_ci95'],float).copy()
        _g0=np.asarray(boundary['G_near_zero'],bool); _e0=np.asarray(boundary['E_near_zero'],bool); _t0=np.asarray(boundary['total_near_zero'],bool)
        _ci[_g0 & ~_t0,0]=0.0; _ci[_e0 & ~_t0,1]=1.0; _ci[_t0,:]=np.nan
        out['h2_ci95']=pd.DataFrame(_ci,index=columns,columns=['lower','upper'])

    pbar.stage("Covariance: summaries and uncertainty",phase_key="summaries")
    if int(n_boot) > 0:
        pbar.stage("Covariance: bootstrap preparation and fits")
        full_fit = {"specs": {n0: fit["specs"][n0] for n0 in names}}
        factor_targets = None
        if bootstrap_factors is not None:
            if not isinstance(bootstrap_factors, dict):
                raise TypeError("bootstrap_factors must be a dict mapping G/E/component name to decomposition options")
            full_mats = {**Gcomp, "E": E, "G": G}
            factor_targets = {}
            for label, cfg0 in bootstrap_factors.items():
                cfg = dict(cfg0) if isinstance(cfg0, dict) else {"rank": int(cfg0)}
                source = cfg.pop("component", label)
                Cref = _factor_target_matrix(full_mats, source, knames)
                factor_targets[str(label)] = {
                    "source": source,
                    "native": False,
                    "config": cfg,
                    "reference": _stability_loadings(Cref, cfg),
                }
        boot = bootstrap_factor_analytic(
            kernels, Y, full_fit=full_fit, ranks=ranks, names=names, ridge=ridge,
            n_boot=n_boot, random_state=random_state, n_jobs=bootstrap_n_jobs,
            cache_gb=bootstrap_cache_gb, batch_size=bootstrap_batch_size, progress=progress,
            block_size=block_size, maxiter=bootstrap_maxiter, gtol=max(gtol, 1e-6), ftol=max(ftol, 1e-9), eps=eps,
            blas_threads_per_worker=bootstrap_blas_threads, factor_draws=bootstrap_factor_draws,
            factor_targets=factor_targets,
            bootstrap_groups=bootstrap_groups, bootstrap_unit=bootstrap_unit,
            solver=cov_solver, spectral_weighting=spectral_weighting,
            spectral_fa_sweeps=spectral_fa_sweeps, spectral_refine_maxiter=spectral_refine_maxiter,
            projected_maxiter=projected_maxiter, projected_tol=projected_tol,
            projected_step_scale=projected_step_scale,
            structures=factor_structures, rotations=factor_rotations,
            factor_lambda=factor_lambdas, factor_group_lambda=factor_group_lambdas,
            factor_adaptive=factor_adaptive, factor_relaxed_refit=factor_relaxed_refit,
            factor_support_tol=factor_support_tol, factor_sparse_maxiter=factor_sparse_maxiter,
            factor_sparse_tol=factor_sparse_tol, factor_auto_fraction=factor_auto_fraction,
            regularization_policy=None, min_E_pair_overlap=min_E_pair_overlap,
            ci=bootstrap_ci, ci_entries=bootstrap_ci_entries, return_draws=bootstrap_return_draws,
            draw_components=bootstrap_draw_components,
            variance_closure=closure_enabled, variance_closure_strength=variance_closure_strength,
        )
        out["bootstrap"] = boot
        out["factor_stability"] = boot["factor_stability"]
        out["bootstrap_factor_stability"] = boot["factor_stability"]
        out["n_boot"] = int(n_boot)
        out["n_boot_success"] = int(boot["n_boot_success"])
        out["E_se"] = pd.DataFrame(boot["cov_se"]["E"], index=columns, columns=columns)
        out["rg_se"] = pd.DataFrame(boot["rg_se"], index=columns, columns=columns)
        if len(knames) == 1:
            out["G_se"] = pd.DataFrame(boot["cov_se"][knames[0]], index=columns, columns=columns)
        else:
            out["G_component_se"] = {n0: pd.DataFrame(boot["cov_se"][n0], index=columns, columns=columns) for n0 in knames}
            # SE of total G is not the sum of component SEs; retain component SEs only.
        if "variance_ci" in boot:
            probs = np.asarray(boot["ci_probs"], float)
            labels = [f"q{p:g}" for p in probs]
            if "G" in boot["variance_ci"]:
                out["G_variance_ci"] = pd.DataFrame(boot["variance_ci"]["G"].T, index=columns, columns=labels)
            if "E" in boot["variance_ci"]:
                out["E_variance_ci"] = pd.DataFrame(boot["variance_ci"]["E"].T, index=columns, columns=labels)
            if "Rg" in boot["variance_ci"]:
                out["Rg_diagonal_ci"] = pd.DataFrame(boot["variance_ci"]["Rg"].T, index=columns, columns=labels)
    # 2.9.4 analytical-SE empirical-Bayes prediction shrinkage.  This runs
    # after analytical uncertainty (and, if requested, bootstrap summaries) so
    # reliability is estimated from the covariance estimator itself rather than
    # raw N/overlap.  The unshrunk *_inference fields and their SEs remain the
    # scientific estimand; only prediction views are replaced.
    if _analytic_post_requested:
        shrink_diag = {
            'available': True,
            'se_auto_enabled': bool(_analytic_se_auto_enabled),
            'G': {}, 'E': None,
            'note': ('Analytical-SE shrinkage changes prediction covariances only; '
                     'G/E inference matrices and analytical SEs remain unshrunk.'),
        }
        pred_specs = dict(specs)
        try:
            for n0 in knames:
                mode0 = _analytic_g_modes.get(n0, _analytic_g_modes.get('__all__', None))
                if mode0 is None:
                    continue
                if len(knames) == 1:
                    se0 = np.asarray(out['G_se'], float)
                    # At this point the identity pre-regularizer means rg_se is
                    # the inference total-G correlation SE and can be used
                    # directly on the Fisher scale.
                    corrse0 = np.asarray(out['rg_se'], float) if 'rg_se' in out else None
                else:
                    se0 = np.asarray(out['G_component_se'][n0], float)
                    corrse0 = None
                if not np.isfinite(se0).any():
                    raise ValueError(f'analytical SE unavailable for component {n0!r}')
                ps, dg = _apply_analytic_prediction_shrinkage(
                    specs[n0], se0, mode0, exact_corr_se=corrse0, eps=eps,
                    rank_preserve=True,
                )
                pred_specs[n0] = ps
                w = np.asarray(dg.pop('weights'), float)
                dg['weights'] = pd.DataFrame(w.astype(np.float32), index=columns, columns=columns)
                iu0 = np.triu_indices(T, 1)
                dg['median_alpha'] = float(np.nanmedian(w[iu0])) if len(iu0[0]) else 1.0
                shrink_diag['G'][n0] = dg

            if _analytic_e_mode is not None:
                ese = np.asarray(out['E_se'], float)
                if not np.isfinite(ese).any():
                    raise ValueError('analytical SE unavailable for E')
                ps, dg = _apply_analytic_prediction_shrinkage(
                    Espec, ese, _analytic_e_mode, exact_corr_se=None, eps=eps,
                    rank_preserve=True,
                )
                pred_specs['E'] = ps
                w = np.asarray(dg.pop('weights'), float)
                dg['weights'] = pd.DataFrame(w.astype(np.float32), index=columns, columns=columns)
                iu0 = np.triu_indices(T, 1)
                dg['median_alpha'] = float(np.nanmedian(w[iu0])) if len(iu0[0]) else 1.0
                shrink_diag['E'] = dg

            # Materialize only trait-space covariance matrices; animal-space
            # complexity and the GRM representation are unchanged.
            Gcomp_pred = {n0: pred_specs[n0].materialize() for n0 in knames}
            Gpred = sum(Gcomp_pred.values(), np.zeros((T, T)))
            Epred = pred_specs['E'].materialize()
            Rgpred, _, _ = _legacy._rg_from_G_psd(Gpred, eps=max(float(eps),1e-15))
            out['G_components_prediction'] = {n0: pd.DataFrame(Gcomp_pred[n0], index=columns, columns=columns) for n0 in knames}
            out['G_prediction'] = pd.DataFrame(Gpred, index=columns, columns=columns)
            out['E_prediction'] = pd.DataFrame(Epred, index=columns, columns=columns)
            out['Rg_prediction'] = pd.DataFrame(Rgpred, index=columns, columns=columns)
            out['component_specs_prediction'] = {n0: pred_specs[n0].to_dict(include_matrix=False) for n0 in knames}
            out['E_spec_prediction'] = pred_specs['E'].to_dict(include_matrix=False)
            if shrink_diag['G']:
                _ga = {n0: float(shrink_diag['G'][n0]['median_alpha']) for n0 in shrink_diag['G']}
                out['shrink_G'] = _ga[knames[0]] if len(knames)==1 and knames[0] in _ga else _ga
            if shrink_diag['E'] is not None:
                out['shrink_E'] = float(shrink_diag['E']['median_alpha'])
                out['shrink_E_mode'] = 'analytic_' + str(_analytic_e_mode)
                out['E_shrinkage_weights'] = shrink_diag['E']['weights']
            # Publication-facing shrinkage diagnostics: quantify how much cross-trait
            # correlation mass is retained and warn if regularization is very strong.
            def _corr_mass(C):
                """Sum absolute off-diagonal correlation mass for retained-covariance diagnostics.

                Parameters
                ----------
                C : array-like
                    Numerical operand in ``C / np.outer(d, d)``. Shape must conform to that matrix/vector
                    operation and the enclosing prepared state.
                """
                C=np.asarray(C,float); d=np.sqrt(np.maximum(np.diag(C),1e-30)); R=_sym(C/np.outer(d,d));
                iu=np.triu_indices_from(R,1); return float(np.nansum(np.abs(R[iu]))) if len(iu[0]) else 0.0
            _retained={}
            for _n0 in knames:
                _raw=Gcomp_unshrunk[_n0]; _pr=Gcomp_pred[_n0]; _den=_corr_mass(_raw)
                _retained[_n0]=(_corr_mass(_pr)/_den if _den>0 else 1.0)
            _eden=_corr_mass(E_unshrunk); _eret=(_corr_mass(Epred)/_eden if _eden>0 else 1.0)
            out['shrinkage_retained_correlation_mass']={'G_components':_retained,'E':float(_eret)}
            _strong=[f"{k}={v:.3f}" for k,v in _retained.items() if np.isfinite(v) and v<0.30]
            if np.isfinite(_eret) and _eret<0.30: _strong.append(f"E={_eret:.3f}")
            if _strong:
                warnings.warn('strong prediction-covariance shrinkage retained <30% of off-diagonal correlation mass: '+', '.join(_strong)+'. Inference G/E/Rg remain unshrunk.', RuntimeWarning, stacklevel=2)
            out['analytic_shrinkage'] = shrink_diag
            out['regularization_policy'] = dict(out.get('regularization_policy', {}),
                post_analytic_shrinkage={
                    'G': {n0: str(_analytic_g_modes.get(n0, _analytic_g_modes.get('__all__'))) for n0 in knames if _analytic_g_modes.get(n0, _analytic_g_modes.get('__all__')) is not None},
                    'E': _analytic_e_mode,
                })
            out['reporting_recommendation'] = ('Bare G/E/Rg and component fields are inference estimands and match analytical uncertainty; '
                                               'use G_prediction/E_prediction and G_components_prediction explicitly for mvBLUP.')
        except Exception as exc:
            shrink_diag['available'] = False; shrink_diag['reason'] = str(exc)
            out['analytic_shrinkage'] = shrink_diag
            warnings.warn(f'analytical prediction shrinkage was requested but not applied: {exc}', RuntimeWarning, stacklevel=2)

    # Estimand contract: uncertainty fields belong to the bare inference
    # covariance. Prediction regularization is a separate decision layer.
    if 'rg_se' in out:
        out['rg_inference_se'] = out['rg_se']
        out['rg_unshrunk_se'] = out['rg_se']
    if 'G_se' in out:
        out['G_inference_se'] = out['G_se']
        out['G_unshrunk_se'] = out['G_se']
    if 'E_se' in out:
        out['E_inference_se'] = out['E_se']
        out['E_unshrunk_se'] = out['E_se']
    if 'rg_ci95_low' in out and 'rg_ci95_high' in out:
        out['rg_inference_ci95_low'] = out['rg_ci95_low']
        out['rg_inference_ci95_high'] = out['rg_ci95_high']
        out['rg_unshrunk_ci95_low'] = out['rg_ci95_low']
        out['rg_unshrunk_ci95_high'] = out['rg_ci95_high']
    out['uncertainty_estimand'] = 'inference_unshrunk'

    if structural_result is not None and structural_result.get("sem") is not None:
        _plot_mode = str(structural_plots).lower() if not isinstance(structural_plots, bool) else ("true" if structural_plots else "false")
        if _plot_mode not in {"false", "none", "off", "0"}:
            try:
                from .causal import structural_sem_tabs
                out["structural_tabs"] = structural_sem_tabs(out)
                out["structural_plot_note"] = "Panel pn.Tabs report built with hvPlot/HoloViews and NetworkX."
            except ImportError as exc:
                if _plot_mode in {"true", "on", "1", "yes"}:
                    raise
                out["structural_tabs"] = None
                out["structural_plot_note"] = "Install VIGOR[plot] to build the pn.Tabs structural report: " + str(exc)
        else:
            out["structural_tabs"] = None
            out["structural_plot_note"] = "Structural plots disabled by structural_plots."

    if structural_result is not None and structural_result.get('sem') is None:
        out['structural_tabs']=None
        out['structural_plot_note']='SEM unavailable: nonextendible estimated PDAG; no structural path plot fabricated.'

    # Bootstrap replaces rg_se after the initial boundary pass; reapply the
    # scientific boundary contract to every uncertainty backend.
    _pairmask=pd.DataFrame(_pairbad,index=columns,columns=columns)
    out['Rg']=out['Rg_inference'].mask(_pairmask)
    out['Rg_inference']=out['Rg']
    out['Rg_unshrunk']=out['Rg']
    if 'rg_se' in out: out['rg_se']=out['rg_se'].mask(_pairmask)
    for _k in ('rg_ci95_low','rg_ci95_high'):
        if _k in out: out[_k]=out[_k].mask(_pairmask)
    return out




def prediction_covariance_view(result, profile="partial_traits"):
    """Return G/E covariance matrices for a declared prediction information state.

    ``partial_traits`` uses the current overlap-aware empirical-Bayes E
    regularization. ``unseen_animals`` reproduces the 3.1.3 residual-covariance
    regularizer (median-overlap/(median-overlap+400)) while retaining VIGOR's
    prediction-grade G shrinkage.  The latter is consistently better in the
    package's row-held-out synthetic benchmark, while the EB view is better for
    completing missing traits in already observed animals. ``inference`` returns
    the unshrunk G and E fit for reporting rather than prediction.

    Parameters
    ----------
    result : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes.

    profile : str
        Covariance prediction view: inference/unshrunk/report keeps inferential matrices;
        unseen/unseen_animals/new_animals targets new animals,
        partial/partial_traits/phenotype_assisted targets partially observed rows, and
        legacy_prediction retains the historical prediction policy. See
        prediction_covariance_view for accepted aliases. Default: ``'partial_traits'``.
        Source-recognized literal values: ``313``, ``eb``. These select the corresponding
        branches below; comparison evidence alone does not establish an exhaustive enum.

    Returns
    -------
    dict
        Result fields: ``G``, ``E``, ``profile``, ``shrink_E``, ``shrink_E_pairwise``, ``historical_profile``. Field arrays preserve the corresponding input axis order.
    """
    result=_result_view(result)
    key=str(profile).lower()
    _profiles=result.get("prediction_profiles",{}) if hasattr(result,"get") else {}
    _canon=("partial_traits" if key in {"partial","partial_traits","phenotype_assisted","eb"} else
            "unseen_animals" if key in {"unseen","unseen_animals","new_animals"} else None)
    if _canon is not None and _canon in _profiles:
        v=dict(_profiles[_canon]); v.setdefault("profile",_canon); return v
    def _gview(prediction=True):
        """Extract the named genetic covariance view from the fit/prediction result.

        Parameters
        ----------
        prediction : array-like or pandas.DataFrame
            Baseline predicted values in the response animal/trait order, used for conditioning,
            residual construction or evaluation. Supply predictions from the corresponding fit
            without including held-out outcomes in training. Default: ``True``.
        """
        comp_key="G_components_prediction" if prediction else "G_components_inference"
        comps=result.get(comp_key)
        # Multi-kernel BLUP requires the named component mapping.  Preserve the
        # simpler aggregate covariance for a single-kernel fit.
        if isinstance(comps,dict) and len(comps)>1:
            return comps
        return result.get("G_prediction" if prediction else "G_unshrunk",result["G"])
    if key in {"partial","partial_traits","phenotype_assisted","eb"}:
        return {"G":_gview(True),
                "E":result.get("E_prediction",result["E"]),
                "profile":"partial_traits"}
    if key in {"inference","report","unshrunk"}:
        return {"G":_gview(False),
                "E":result.get("E_unshrunk",result["E"]),
                "profile":"inference"}
    if key in {"unseen","unseen_animals","new_animals","313","legacy_prediction"}:
        G=_gview(True)
        ash=result.get("analytic_shrinkage",{})
        if key not in {"313","legacy_prediction"} and isinstance(ash,dict) and ash.get("available") and ash.get("E") is not None:
            return {"G":G, "E":result.get("E_prediction",result["E"]),
                    "profile":"unseen_animals_analytic_se_eb"}
        Eraw=result.get("E_unshrunk",result["E"])
        E0=np.asarray(Eraw,float)
        ov=np.asarray(result.get("E_pair_overlap",np.eye(E0.shape[0])),float)
        # Exact 3.1.3-style pair-specific residual shrinkage:
        # alpha_ij = n_ij/(n_ij+400) on the correlation scale, then PSD repair
        # and variance-preserving renormalization.  Using the pairwise matrix
        # matters when trait missingness is heterogeneous; a single median alpha
        # only happened to be nearly equivalent in row-complete benchmarks.
        d=np.maximum(np.diag(E0).copy(),1e-30); sd=np.sqrt(d)
        R=_sym(E0/np.outer(sd,sd)); np.fill_diagonal(R,1.0)
        alpha_pair=np.divide(ov,ov+400.0,out=np.zeros_like(ov),where=(ov+400.0)>0)
        np.fill_diagonal(alpha_pair,1.0)
        Rlegacy=np.eye(E0.shape[0])+alpha_pair*(R-np.eye(E0.shape[0]))
        Rlegacy=_legacy._project_psd(_sym(Rlegacy),eps=1e-12)
        rd=np.sqrt(np.maximum(np.diag(Rlegacy),1e-30))
        Rlegacy=_sym(Rlegacy/np.outer(rd,rd)); np.fill_diagonal(Rlegacy,1.0)
        Elegacy=_sym(Rlegacy*np.outer(sd,sd)); np.fill_diagonal(Elegacy,np.diag(E0))
        # 3.1.3 E_structure='auto' masked only unsupported trait pairs before a
        # final PSD repair. Reproduce that behavior when the fitted result says
        # the user requested automatic structure.
        if str(result.get("E_structure_requested","auto")).lower()=="auto":
            support=ov>=2; np.fill_diagonal(support,True)
            Elegacy=_legacy._project_psd(np.where(support,Elegacy,0.0),eps=1e-12)
            # Preserve the original residual variances after the repair.
            ed=np.sqrt(np.maximum(np.diag(Elegacy),1e-30)); sc=sd/ed
            Elegacy=_sym(Elegacy*np.outer(sc,sc)); np.fill_diagonal(Elegacy,np.diag(E0))
        if isinstance(Eraw,pd.DataFrame):
            Elegacy=pd.DataFrame(Elegacy,index=Eraw.index,columns=Eraw.columns)
        iu=np.triu_indices(E0.shape[0],1)
        med_alpha=float(np.median(alpha_pair[iu])) if len(iu[0]) else 1.0
        return {"G":G,"E":Elegacy,"profile":"unseen_animals",
                "shrink_E":med_alpha,"shrink_E_pairwise":alpha_pair,
                "historical_profile":"gdec_3.1.3_pairwise_overlap"}
    raise ValueError("profile must be 'partial_traits', 'unseen_animals', or 'inference'")



def _mvblup_adaptive_dataset(result, arguments):
    """Convert an ``mvBLUP_adaptive`` return value to a labeled Dataset.

    Parameters
    ----------
    result : pandas.DataFrame, numpy.ndarray or mapping
        Adaptive breeding values become ``prediction`` ('sample','trait'); with
        return_profiles the ``partial_traits``/``unseen_animals`` predictions (same dims),
        ``row_profile`` ('sample') and the ``unseen_E_shrink`` attribute are added.
    arguments : mapping
        Bound call arguments; ``traits`` supplies sample/trait labels and scalar options are
        recorded as parameters.
    """
    values = dict(result) if isinstance(result, dict) else {"prediction": result}
    dims = {k: ("sample", "trait") for k in ("prediction", "partial_traits", "unseen_animals")}
    dims["row_profile"] = ("sample",)
    return _labeled_result_dataset(values, traits=_prediction_traits(arguments.get("traits")), dims=dims,
                                   title="Information-state adaptive mvBLUP", software="vigor.multivariate.mvBLUP_adaptive",
                                   arguments=arguments)


@_dataset_result(_mvblup_adaptive_dataset)
def mvBLUP_adaptive(traits, GRM, covariance_result, *, missing="exact", return_profiles=False, save_path=None, **kwargs):
    """Information-state adaptive mvBLUP using one covariance fit.

    Fully unphenotyped animals use the 3.1.3-compatible residual-covariance
    regularization, while animals with at least one observed trait use VIGOR's
    overlap-aware EB residual covariance.  Both views share the same fitted raw
    MoM covariance and prediction-grade G shrinkage, so no covariance refit is
    required.  This targets the empirical trade-off seen in the 2.9.2 benchmark:
    legacy E shrinkage is better for new animals, EB E shrinkage is better for
    completion of missing traits in seen animals.

    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    covariance_result : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    missing : str
        Missing-data handling selected by this entry point: 'auto' resolves a policy from matrix
        size/model; 'mask' models observed cells, 'pattern' groups observation patterns,
        'impute' treats missing values as latent, and 'row' uses complete rows where supported.
        'mean'/'mean_impute' fills with the observed mean only in helpers explicitly supporting
        it. See the local validator for the accepted subset. Default: ``'exact'``. Passed to
        ``mvBLUP`` as ``missing``.

    return_profiles : bool
        Also add the per-profile predictions ``partial_traits``/``unseen_animals``, the
        ``row_profile`` variable and the ``unseen_E_shrink`` attribute; only added when set.
        Default: ``False``.

    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.

    **kwargs : mapping
        Additional keyword arguments forwarded to ``mvBLUP``. See those callables for accepted
        keys and values. Passed to ``mvBLUP`` as ``**expanded mapping``.

    Returns
    -------
    xarray.Dataset
        Data variable ``prediction`` ('sample','trait'): adaptive breeding values. With
        return_profiles also ``partial_traits``/``unseen_animals`` ('sample','trait'),
        ``row_profile`` ('sample') and attribute ``unseen_E_shrink``.
    """
    traits=_as_pandas_input(traits); GRM=_kernel_input(GRM)
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits)
    partial=prediction_covariance_view(covariance_result,"partial_traits")
    unseen=prediction_covariance_view(covariance_result,"unseen_animals")
    Ppartial=_mvBLUP_raw(Y,GRM,partial["G"],E=partial["E"],missing=missing,**kwargs)
    mask=Y.notna().sum(axis=1).eq(0).to_numpy()
    if not np.any(mask):
        return {"prediction":Ppartial,"partial_traits":Ppartial,"unseen_animals":None,
                "row_profile":pd.Series("partial_traits",index=Y.index)} if return_profiles else Ppartial
    Punseen=_mvBLUP_raw(Y,GRM,unseen["G"],E=unseen["E"],missing=missing,**kwargs)
    if isinstance(Ppartial,pd.DataFrame):
        out=Ppartial.copy(); out.iloc[np.flatnonzero(mask),:]=Punseen.iloc[np.flatnonzero(mask),:].to_numpy()
    else:
        out=np.asarray(Ppartial).copy(); out[mask]=np.asarray(Punseen)[mask]
    if not return_profiles: return out
    row_profile=pd.Series("partial_traits",index=Y.index,dtype="object"); row_profile.iloc[np.flatnonzero(mask)]="unseen_animals"
    return {"prediction":out,"partial_traits":Ppartial,"unseen_animals":Punseen,
            "row_profile":row_profile,"unseen_E_shrink":unseen.get("shrink_E")}



def _prediction_corr_shrink(C, alpha):
    """Variance-preserving scalar correlation shrinkage for prediction only.

    Parameters
    ----------
    C : array-like
        Numerical operand in ``C / np.outer(sd, sd)``. Shape must conform to that matrix/vector
        operation and the enclosing prepared state.

    alpha : float
        Regularization coefficient, mixing weight or statistical significance threshold selected
        by this estimator; the local validation and objective determine its precise scale.
    """
    C=np.asarray(C,float); d=np.maximum(np.diag(C),1e-30); sd=np.sqrt(d)
    R=_sym(C/np.outer(sd,sd)); np.fill_diagonal(R,1.0)
    a=float(np.clip(alpha,0.0,1.0)); R=np.eye(len(R))+a*(R-np.eye(len(R)))
    R=_legacy._project_psd(_sym(R),eps=1e-12)
    rd=np.sqrt(np.maximum(np.diag(R),1e-30)); R=_sym(R/np.outer(rd,rd)); np.fill_diagonal(R,1.0)
    out=_sym(R*np.outer(sd,sd)); np.fill_diagonal(out,d)
    return out


def prediction_covariance_candidates(result, *, g_alphas=(0.0,0.1,0.25,0.5,0.75,1.0), e_overlap_strengths=(100.,250.,400.,800.)):
    """Candidate prediction-only covariance views; inference G/E are never modified.

    Parameters
    ----------
    result : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes.

    g_alphas : tuple
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``(0.0, 0.1, 0.25, 0.5, 0.75, 1.0)``.

    e_overlap_strengths : tuple
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``(100.0, 250.0, 400.0, 800.0)``.

    Returns
    -------
    object
        Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
    """
    result=_result_view(result)
    cols=result['G'].index if isinstance(result['G'],pd.DataFrame) else None
    Graw=result.get('G_components_inference',result.get('G_components',None))
    if Graw is None: Graw={'genetic':result.get('G_inference',result['G'])}
    Eraw=np.asarray(result.get('E_inference',result['E']),float)
    ov=np.asarray(result.get('E_pair_overlap',np.ones_like(Eraw)),float)
    out={}
    def wrapg(gs): 
        """Restore genetic covariance labels and container type after transformation.

        Parameters
        ----------
        gs : mapping
            Input for the operation ``gs.items()``. See
            ``vigor.multivariate.prediction_covariance_candidates.wrapg`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``{k: pd.DataFrame(v, index=cols, columns=cols) if cols is not None else v for k, v in gs.items()}``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return {k:(pd.DataFrame(v,index=cols,columns=cols) if cols is not None else v) for k,v in gs.items()}
    def wrape(e): 
        """Restore residual covariance labels and container type after transformation.

        Parameters
        ----------
        e : object (see the cited input contract)
            Input for the operation ``pd.DataFrame(e, index=cols, columns=cols)``. See
            ``vigor.multivariate.prediction_covariance_candidates.wrape`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        Returns
        -------
        object
            Computed result from ``pd.DataFrame(e, index=cols, columns=cols) if cols is not None else e``; see the summary and the called implementation for its labeled/numerical representation.
        """
        return pd.DataFrame(e,index=cols,columns=cols) if cols is not None else e
    # Existing analytical prediction geometry.
    Gcur=result.get('G_components_prediction',Graw); Ecur=result.get('E_prediction',Eraw)
    out['analytic_current']={'G':Gcur,'E':Ecur,'policy':'analytic_current'}
    out['unshrunk']={'G':Graw,'E':wrape(Eraw),'policy':'unshrunk'}
    for ga in g_alphas:
        gs={k:_prediction_corr_shrink(np.asarray(v,float),ga) for k,v in Graw.items()}
        for strength in e_overlap_strengths:
            a=np.divide(ov,ov+float(strength),out=np.zeros_like(ov),where=(ov+float(strength))>0); np.fill_diagonal(a,1.0)
            d=np.maximum(np.diag(Eraw),1e-30); sd=np.sqrt(d); R=_sym(Eraw/np.outer(sd,sd)); np.fill_diagonal(R,1.0)
            Re=np.eye(len(R))+a*(R-np.eye(len(R))); Re=_legacy._project_psd(_sym(Re),eps=1e-12)
            rd=np.sqrt(np.maximum(np.diag(Re),1e-30)); Re=_sym(Re/np.outer(rd,rd)); np.fill_diagonal(Re,1.0)
            Ep=_sym(Re*np.outer(sd,sd)); np.fill_diagonal(Ep,d)
            name=f'g{ga:g}_eov{strength:g}'; out[name]={'G':wrapg(gs),'E':wrape(Ep),'policy':name,'g_alpha':float(ga),'e_overlap_strength':float(strength)}
    return out


def select_prediction_covariance_cv(traits, GRM, *, covariance_kwargs=None, n_splits=3, validation_fraction=0.12,
                                    profiles=('unseen_animals','partial_traits'), random_state=0,
                                    g_alphas=(0.0,0.1,0.25,0.5,0.75,1.0), e_overlap_strengths=(100.,250.,400.,800.),
                                    solver_tol=2e-6, solver_maxiter=400, blas_threads='auto',
                                    cv_accuracy='fast', cv_kernel_rank='full',
                                    selection_metric='mean_trait_r2'):
    """Nested prediction-loss CV for prediction-only G/E regularization.

    Each fold refits the covariance model after masking validation observations.
    ``unseen_animals`` masks complete validation rows; ``partial_traits`` masks
    random observed cells while retaining >=1 observed trait per selected row.

    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    covariance_kwargs : mapping
        Additional keyword settings forwarded to the selected estimator/writer. See the called
        implementation for its accepted names and value domains; these are not unrestricted
        scientific options. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    n_splits : int
        Number of cross-validation folds, ordinarily at least two and no larger than the
        eligible training sample count. Fold-specific fitting must exclude held-out outcomes.
        Default: ``3``.

    validation_fraction : float
        Fraction of eligible entries/animals selected for the corresponding holdout or
        resampling operation; use a value in (0, 1] compatible with nonempty training/evaluation
        subsets. Default: ``0.12``.

    profiles : tuple
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``('unseen_animals', 'partial_traits')``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``as_kernel_operator`` as ``random_state``.

    g_alphas : tuple
        Input supplied to ``prediction_covariance_candidates`` as ``g_alphas``. See that
        callable's documented ``g_alphas`` contract for its type, alignment and value domain.
        This wrapper retains that contract. Default: ``(0.0, 0.1, 0.25, 0.5, 0.75, 1.0)``.
        Passed to ``prediction_covariance_candidates`` as ``g_alphas``.

    e_overlap_strengths : tuple
        Input supplied to ``prediction_covariance_candidates`` as ``e_overlap_strengths``. See
        that callable's documented ``e_overlap_strengths`` contract for its type, alignment and
        value domain. This wrapper retains that contract. Default: ``(100.0, 250.0, 400.0,
        800.0)``. Passed to ``prediction_covariance_candidates`` as ``e_overlap_strengths``.

    solver_tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``2e-06``. Passed to ``mvPredict`` as ``solver_tol``.

    solver_maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``400``. Passed to ``mvPredict`` as ``solver_maxiter``.

    blas_threads : int or str
        BLAS thread limit during numerical operations. Positive integers select an explicit
        thread count; auto uses the routine's workload-dependent thread policy. Default:
        ``'auto'``. Passed to ``mvPredict`` as ``blas_threads``.

    cv_accuracy : str
        Input for the operation ``str(cv_accuracy).lower()``. See
        ``vigor.multivariate.select_prediction_covariance_cv`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``'fast'``. Source-recognized literal values: ``exact``. These select the corresponding
        branches below; comparison evidence alone does not establish an exhaustive enum.

    cv_kernel_rank : str
        Input supplied to ``mvPredict`` as ``kernel_rank``. See that callable's documented
        ``kernel_rank`` contract for its type, alignment and value domain. This wrapper retains
        that contract. Default: ``'full'``. Passed to ``mvPredict`` as ``kernel_rank``.

    selection_metric : str
        Held-out selection metric: 'mse' minimizes mean squared error; 'pooled_r2' maximizes
        pooled predictive R-squared. Scaling/fold aggregation follows the selection helper.
        Default: ``'mean_trait_r2'``.

    Returns
    -------
    dict
        Result fields: ``selected``, ``table``, ``objective``, ``selection_metric``, ``inference_unchanged``, ``cv_accuracy``, ``cv_kernel_rank``, ``cached_kernel_operators``, ``candidate_config``. Field arrays preserve the corresponding input axis order.
    """
    traits=_as_pandas_input(traits); GRM=_kernel_input(GRM)
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits)
    rng=np.random.default_rng(random_state); ckw={} if covariance_kwargs is None else dict(covariance_kwargs)
    ckw.setdefault('n_boot',0); ckw.setdefault('progress',False)
    # Cache animal-space operators once: CV candidates differ only in the small
    # trait-space covariance.  Recomputing randomized GRM eigenspaces per candidate
    # dominated runtime at n~5000 and is mathematically unnecessary.
    aligned=_align_labeled_kernels_to_traits(GRM,Y)
    raw=aligned if _legacy._v31_is_multigrm(aligned) else {'genetic':aligned}
    acc=str(cv_accuracy).lower(); kr=None if acc=='exact' else _resolve_kernel_rank(cv_kernel_rank,len(Y))
    wd=np.float64 if acc=='exact' else np.float32
    pred_grm={str(name):as_kernel_operator(K,rank=kr,dtype=wd,random_state=int(random_state)) for name,K in raw.items()}
    records=[]
    for profile in profiles:
        for fold in range(max(2,int(n_splits))):
            Ytr=Y.copy(); val=np.zeros(Y.shape,bool)
            if profile=='unseen_animals':
                eligible=np.flatnonzero(Y.notna().any(axis=1).to_numpy()); q=max(1,int(np.ceil(len(eligible)*float(validation_fraction))))
                rows=np.sort(rng.choice(eligible,size=min(q,len(eligible)),replace=False)); val[rows]=Y.iloc[rows].notna().to_numpy(); Ytr.iloc[rows,:]=np.nan
            else:
                for i in range(len(Y)):
                    obs=np.flatnonzero(Y.iloc[i].notna().to_numpy())
                    if len(obs)<2: continue
                    q=max(1,min(len(obs)-1,int(np.ceil(len(obs)*float(validation_fraction)))))
                    jj=rng.choice(obs,size=q,replace=False); val[i,jj]=True; Ytr.iloc[i,jj]=np.nan
            if not val.any(): continue
            fit=_genetic_varcov_PSD_raw(GRM,Ytr,**ckw)
            cand=prediction_covariance_candidates(fit,g_alphas=g_alphas,e_overlap_strengths=e_overlap_strengths)
            truth=Y.to_numpy(float)
            for name,view in cand.items():
                PR=_mvPredict_raw(Ytr,pred_grm,view['G'],E=view['E'],solver_tol=solver_tol,
                             solver_maxiter=solver_maxiter,preconditioner='diag',blas_threads=blas_threads,
                             accuracy=acc,kernel_rank=cv_kernel_rank)
                # Optimize the quantity actually used by each information state:
                # new animals have no residual phenotype information; partially
                # observed animals use conditional residual cross-trait prediction.
                P=np.asarray(PR['genetic_mean'] if profile=='unseen_animals' else PR['phenotype_prediction'],float)
                ok=val&np.isfinite(truth)&np.isfinite(P)
                if not ok.any(): continue
                err=truth[ok]-P[ok]
                trait_r2=[]; trait_n=[]
                for tj in range(truth.shape[1]):
                    q=val[:,tj]&np.isfinite(truth[:,tj])&np.isfinite(P[:,tj])
                    if int(q.sum())>=4 and np.std(truth[q,tj])>0 and np.std(P[q,tj])>0:
                        rr=float(np.corrcoef(truth[q,tj],P[q,tj])[0,1]); trait_r2.append(rr*rr); trait_n.append(int(q.sum()))
                pooled_r2=np.nan
                yy=truth[ok]; pp=P[ok]
                if len(yy)>=4 and np.std(yy)>0 and np.std(pp)>0:
                    pooled_r2=float(np.corrcoef(yy,pp)[0,1]**2)
                records.append({'profile':profile,'fold':fold,'candidate':name,'n':int(ok.sum()),
                    'mse':float(np.mean(err*err)),'mean_trait_r2':float(np.mean(trait_r2)) if trait_r2 else np.nan,
                    'n_traits_r2':int(len(trait_r2)),'pooled_r2':pooled_r2})
    tab=pd.DataFrame(records)
    metric=str(selection_metric).lower(); selected={}
    if metric not in {'mse','mean_trait_r2','pooled_r2'}:
        raise ValueError("selection_metric must be 'mse', 'mean_trait_r2', or 'pooled_r2'")
    for profile in profiles:
        z=tab[tab.profile==profile]
        if not len(z): continue
        if metric=='mse':
            score=z.groupby('candidate',sort=False).apply(lambda q:np.average(q.mse,weights=q.n),include_groups=False); chosen=score.idxmin()
        elif metric=='mean_trait_r2':
            zz=z[np.isfinite(z.mean_trait_r2)]
            score=zz.groupby('candidate',sort=False).apply(lambda q:np.average(q.mean_trait_r2,weights=np.maximum(q.n_traits_r2,1)),include_groups=False); chosen=score.idxmax()
        else:
            zz=z[np.isfinite(z.pooled_r2)]
            score=zz.groupby('candidate',sort=False).apply(lambda q:np.average(q.pooled_r2,weights=q.n),include_groups=False); chosen=score.idxmax()
        selected[profile]=str(chosen)
    return {'selected':selected,'table':tab,'objective':f'nested_prediction_{metric}','selection_metric':metric,'inference_unchanged':True,
            'cv_accuracy':acc,'cv_kernel_rank':cv_kernel_rank,'cached_kernel_operators':True,
            'candidate_config':{'g_alphas':tuple(float(x) for x in g_alphas),
                                'e_overlap_strengths':tuple(float(x) for x in e_overlap_strengths)}}


def fit_prediction_covariance_cv(grm, traits, *, covariance_kwargs=None, cv_kwargs=None,
                                 component_scale_cv="auto", component_scale_profiles=("unseen_animals",),
                                 component_scale_candidates=(0.0,0.25,0.5,0.75,1.0),
                                 component_scale_accuracy='exact', component_scale_kernel_rank='full',
                                 component_scale_selection_metric='mean_trait_r2'):
    """Fit inference covariance once and attach leakage-safe prediction profiles.

    G/E/Rg inference and uncertainty are never altered.  Nested CV first chooses
    correlation regularization.  For multi-kernel models, ``component_scale_cv``
    can additionally downweight noisy non-additive prediction components for
    declared information states (by default fully unseen animals only).

    Parameters
    ----------
    grm : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    covariance_kwargs : mapping
        Additional keyword settings forwarded to the selected estimator/writer. See the called
        implementation for its accepted names and value domains; these are not unrestricted
        scientific options. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    cv_kwargs : object (see the cited input contract)
        Input for the operation ``dict(cv_kwargs)``. See
        ``vigor.multivariate.fit_prediction_covariance_cv`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.

    component_scale_cv : str
        Input for the operation ``str(component_scale_cv).lower() == 'auto'``. See
        ``vigor.multivariate.fit_prediction_covariance_cv`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``'auto'``.

    component_scale_profiles : tuple
        Input supplied to ``select_prediction_component_scales_cv`` as ``profiles``. See that
        callable's documented ``profiles`` contract for its type, alignment and value domain.
        This wrapper retains that contract. Default: ``('unseen_animals',)``. Passed to
        ``select_prediction_component_scales_cv`` as ``profiles``.

    component_scale_candidates : tuple
        Input supplied to ``select_prediction_component_scales_cv`` as ``scales``. See that
        callable's documented ``scales`` contract for its type, alignment and value domain. This
        wrapper retains that contract. Default: ``(0.0, 0.25, 0.5, 0.75, 1.0)``. Passed to
        ``select_prediction_component_scales_cv`` as ``scales``.

    component_scale_accuracy : str
        Input supplied to ``select_prediction_component_scales_cv`` as ``accuracy``. See that
        callable's documented ``accuracy`` contract for its type, alignment and value domain.
        This wrapper retains that contract. Default: ``'exact'``. Passed to
        ``select_prediction_component_scales_cv`` as ``accuracy``.

    component_scale_kernel_rank : str
        Input supplied to ``select_prediction_component_scales_cv`` as ``kernel_rank``. See that
        callable's documented ``kernel_rank`` contract for its type, alignment and value domain.
        This wrapper retains that contract. Default: ``'full'``. Passed to
        ``select_prediction_component_scales_cv`` as ``kernel_rank``.

    component_scale_selection_metric : str
        Input supplied to ``select_prediction_component_scales_cv`` as ``selection_metric``. See
        that callable's documented ``selection_metric`` contract for its type, alignment and
        value domain. This wrapper retains that contract. Default: ``'mean_trait_r2'``. Passed
        to ``select_prediction_component_scales_cv`` as ``selection_metric``.

    Returns
    -------
    xarray.Dataset
        The genetic_varcov_PSD Dataset with attrs ``prediction_cv`` (selection report),
        ``prediction_profiles`` (selected G/E views per information state) and
        ``prediction_cv_estimand_note``; inference variables are unchanged.
    """
    traits=_as_pandas_input(traits); grm=_kernel_input(grm)
    ckw={} if covariance_kwargs is None else dict(covariance_kwargs)
    vkw={} if cv_kwargs is None else dict(cv_kwargs)
    sel=select_prediction_covariance_cv(traits,grm,covariance_kwargs=ckw,**vkw)
    do_scale=(_v31_is_multigrm(grm) if str(component_scale_cv).lower()=="auto" else bool(component_scale_cv))
    if do_scale and _v31_is_multigrm(grm):
        nonadd=[str(k) for k in grm if str(k).lower() not in {"additive","a","genetic"}]
        scale_tables={}; merged={}
        for ci,comp in enumerate(nonadd):
            sc=select_prediction_component_scales_cv(
                traits,grm,sel,component=comp,scales=component_scale_candidates,
                covariance_kwargs=ckw,profiles=tuple(component_scale_profiles),
                n_splits=int(vkw.get('n_splits',2)),validation_fraction=float(vkw.get('validation_fraction',.08)),
                random_state=int(vkw.get('random_state',0))+7919*ci,solver_tol=1e-4,solver_maxiter=250,
                blas_threads=vkw.get('blas_threads','auto'),accuracy=str(component_scale_accuracy),
                kernel_rank=component_scale_kernel_rank,selection_metric=str(component_scale_selection_metric))
            scale_tables[comp]=sc['table']
            for prof,d in sc.get('component_scales',{}).items(): merged.setdefault(prof,{}).update(d)
        if merged: sel['component_scales']=merged
        sel['component_scale_tables']=scale_tables
        sel['component_scale_profiles']=tuple(component_scale_profiles)
        sel['component_scale_accuracy']=str(component_scale_accuracy)
        sel['component_scale_kernel_rank']=component_scale_kernel_rank
        sel['component_scale_selection_metric']=str(component_scale_selection_metric)
    fit=genetic_varcov_PSD(grm,traits,**ckw)
    profiles={}
    for profile in ('unseen_animals','partial_traits'):
        if profile in sel.get('selected',{}): profiles[profile]=apply_prediction_covariance_selection(fit,sel,profile)
    fit.attrs['prediction_cv']=sel; fit.attrs['prediction_profiles']=profiles
    fit.attrs['prediction_cv_estimand_note']='CV selects prediction-only G/E/component reliability views; inference G/E/Rg and uncertainty are unchanged.'
    return fit


def _mvpredict_adaptive_dataset(result, arguments):
    """Convert an ``mvPredict_adaptive`` mapping into a labeled Dataset.

    Parameters
    ----------
    result : mapping
        mvPredict-style fields (see ``_mvpredict_dataset``) plus ``row_profile`` ('sample'),
        optional ``genetic_expert_correction`` ('sample','trait') and profile/expert metadata in
        attrs. With return_profiles the per-profile mvPredict results are stored in attrs
        ``partial_result``/``unseen_result`` as their own Datasets.
    arguments : mapping
        Bound call arguments; ``traits`` supplies sample/trait labels and scalar options are
        recorded as parameters.
    """
    values = dict(result)
    for key in ("partial_result", "unseen_result"):
        if isinstance(values.get(key), dict):
            values[key] = _mvpredict_dataset(values[key], arguments)
    return _mvpredict_dataset(values, arguments, software="vigor.multivariate.mvPredict_adaptive",
                              title="Information-state adaptive multivariate prediction")


@_dataset_result(_mvpredict_adaptive_dataset)
def mvPredict_adaptive(traits, GRM, covariance_result, *, return_profiles=False,
                       genomic_expert=None, expert_feature_bank=None, save_path=None, **kwargs):
    """Exact mvPredict with profile-specific covariance and optional genomic expert.

    ``genomic_expert`` is applied to the genetic mean for both completely new
    animals and animals with partially observed phenotypes.  It must have been
    fitted with all phenotype-dependent discovery/feature selection confined to
    the training fold.  Conditional residual prediction is then added only by
    the ordinary mvPredict path, so the expert never substitutes phenotype
    leakage for genomic prediction.

    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.

    covariance_result : array-like, mapping or fitted result
        Covariance quantity or component collection consumed by the stated transformation.
        Square matrices use a common trait order; uncertainty matrices match their corresponding
        covariance entries. See the caller for whether this is genetic, residual or total
        covariance.

    return_profiles : bool
        Also store the per-profile mvPredict Datasets in attrs ``partial_result`` and
        ``unseen_result`` (None when no animal is unseen); only added when set. Default:
        ``False``.

    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.

    genomic_expert : object (see the cited input contract)
        Input for the operation ``genomic_expert.predict(out['genetic_mean'],
        feature_bank=expert_feature_bank)``. See ``vigor.multivariate.mvPredict_adaptive`` and
        its caller for the scientific representation; the shown operation constrains the
        required type/shape. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value.

    expert_feature_bank : object (see the cited input contract)
        Input supplied to ``genomic_expert.predict`` as ``feature_bank``. See that callable's
        documented ``feature_bank`` contract for its type, alignment and value domain. This
        wrapper retains that contract. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value. Passed to
        ``genomic_expert.predict`` as ``feature_bank``.

    **kwargs : mapping
        Additional keyword arguments forwarded to ``mvPredict``. See those callables for
        accepted keys and values. Passed to ``mvPredict`` as ``**expanded mapping``.

    Returns
    -------
    xarray.Dataset
        mvPredict layout (breeding_value, genetic_mean, residual_prediction,
        phenotype_prediction on ('sample','trait'), components, trait_mean, G_matrices,
        E_matrix) with unseen rows taken from the unseen-animal profile, plus ``row_profile``
        ('sample') and, with an expert, ``genetic_expert_correction``. Attrs include
        prediction_profiles_used, genomic_expert_applied/contract and solver diagnostics.
    """
    traits=_as_pandas_input(traits); GRM=_kernel_input(GRM)
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits)
    partial=prediction_covariance_view(covariance_result,'partial_traits')
    unseen=prediction_covariance_view(covariance_result,'unseen_animals')
    def _api_g(view):
        """Resolve the genetic covariance representation accepted by the prediction wrapper.

        Parameters
        ----------
        view : object (see the cited input contract)
            Input for the operation ``view['G']``. See
            ``vigor.multivariate.mvPredict_adaptive._api_g`` and its caller for the scientific
            representation; the shown operation constrains the required type/shape.
        """
        g=view['G']
        if not _v31_is_multigrm(GRM) and isinstance(g,dict) and len(g)==1: return next(iter(g.values()))
        return g
    pp=_mvPredict_raw(Y,GRM,_api_g(partial),E=partial['E'],**kwargs)
    empty=~Y.notna().any(axis=1).to_numpy()
    if np.any(empty):
        pu=_mvPredict_raw(Y,GRM,_api_g(unseen),E=unseen['E'],**kwargs)
    else: pu=None
    out={k:v for k,v in pp.items()}
    for key in ('breeding_value','genetic_mean','residual_prediction','phenotype_prediction'):
        if key not in out: continue
        A=out[key].copy() if isinstance(out[key],pd.DataFrame) else np.asarray(out[key]).copy()
        if pu is not None:
            B=pu[key]
            if isinstance(A,pd.DataFrame): A.iloc[np.flatnonzero(empty),:]=np.asarray(B)[empty]
            else: A[empty]=np.asarray(B)[empty]
        out[key]=A
    out['row_profile']=pd.Series(np.where(empty,'unseen_animals','partial_traits'),index=Y.index)
    out['prediction_profiles_used']={'partial_traits':partial.get('policy',partial.get('profile')),
                                     'unseen_animals':unseen.get('policy',unseen.get('profile'))}
    if genomic_expert is not None:
        base=np.asarray(out['genetic_mean'],float)
        try:
            corrected=np.asarray(genomic_expert.predict(out['genetic_mean'],feature_bank=expert_feature_bank),float)
        except TypeError:
            corrected=np.asarray(genomic_expert.predict(out['genetic_mean']),float)
        if corrected.shape != base.shape:
            raise ValueError('genomic_expert prediction must have sample x trait shape')
        delta=corrected-base
        def _replace_like(x, arr):
            """Replace numerical values while preserving the reference matrix's row/column labels.

            Parameters
            ----------
            x : array-like
                Numerical operand in ``pd.DataFrame(arr, index=x.index, columns=x.columns)``. Shape must
                conform to that matrix/vector operation and the enclosing prepared state.

            arr : array-like, table or labeled object
                Input values consumed by this conversion or analysis. Preserve the labels/axis ordering
                described in the summary; the local coercion/selection expression below defines the
                accepted representation.
            """
            return pd.DataFrame(arr,index=x.index,columns=x.columns) if isinstance(x,pd.DataFrame) else arr
        out['genetic_expert_correction']=_replace_like(out['genetic_mean'],delta)
        out['genetic_mean']=_replace_like(out['genetic_mean'],corrected)
        if 'breeding_value' in out:
            bv=np.asarray(out['breeding_value'],float)+delta
            out['breeding_value']=_replace_like(out['breeding_value'],bv)
        if 'phenotype_prediction' in out:
            ph=np.asarray(out['phenotype_prediction'],float)+delta
            out['phenotype_prediction']=_replace_like(out['phenotype_prediction'],ph)
        out['genomic_expert_applied']=True
        out['genomic_expert_contract']='expert must be trained with all phenotype-dependent selection inside the training fold'
    else:
        out['genomic_expert_applied']=False
    if return_profiles: out['partial_result']=pp; out['unseen_result']=pu
    return out


def apply_prediction_covariance_selection(result, selection, profile):
    """Apply a CV-selected prediction policy to the final full-training covariance fit.

    Parameters
    ----------
    result : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes.

    selection : object (see the cited input contract)
        Input for the operation ``selection['selected'][str(profile)]``. See
        ``vigor.multivariate.apply_prediction_covariance_selection`` and its caller for the
        scientific representation; the shown operation constrains the required type/shape.

    profile : str
        Covariance prediction view: inference/unshrunk/report keeps inferential matrices;
        unseen/unseen_animals/new_animals targets new animals,
        partial/partial_traits/phenotype_assisted targets partially observed rows, and
        legacy_prediction retains the historical prediction policy. See
        prediction_covariance_view for accepted aliases.

    Returns
    -------
    object
        Computed result from ``out``; see the summary and the called implementation for its labeled/numerical representation.
    """
    name=selection['selected'][str(profile)] if isinstance(selection,dict) and 'selected' in selection else str(selection)
    cfg={}
    if isinstance(selection,dict):
        cfg=dict(selection.get('candidate_config',{}) or {})
    cands=prediction_covariance_candidates(result,**cfg)
    if name not in cands:
        raise KeyError(f'prediction policy {name!r} unavailable under candidate_config={cfg!r}')
    out=dict(cands[name])
    if isinstance(selection,dict):
        cs=selection.get('component_scales',{}).get(str(profile),{})
        if cs: out=_scale_prediction_components(out,cs)
    out['profile']=str(profile); out['selected_by']='nested_prediction_cv'; return out

def _organize_scores_dataset(result, arguments):
    """Convert ``organize_scores`` tables into a labeled Dataset.

    Parameters
    ----------
    result : pandas.Series or mapping
        ``G``/``E``/``rG_SE`` trait matrices become ('trait_i','trait_j') variables;
        ``heritability_table`` becomes a float ('trait','heritability_field') variable (boolean
        flags as 0/1); ``g_corr_table`` becomes ('trait_pair','g_corr_field') with ``trait1``
        and ``trait2`` coordinates along trait_pair.
    arguments : mapping
        Bound call arguments; unused except that scalar options would be recorded.
    """
    from .results import result_dataset
    xr = _require_xarray()
    her = result["heritability_table"]
    g = result["g_corr_table"]
    values = {k: result[k] for k in ("G", "E", "rG_SE")}
    dims = {k: ("trait_i", "trait_j") for k in values}
    values["heritability_table"] = her.astype(float)
    dims["heritability_table"] = ("trait", "heritability_field")
    pair_labels = [_axis_labels(g.index.get_level_values(i)) for i in range(2)]
    values["g_corr_table"] = xr.DataArray(
        g.to_numpy(dtype=float), dims=("trait_pair", "g_corr_field"),
        coords={"trait_pair": np.arange(len(g)), "g_corr_field": np.asarray(list(map(str, g.columns))),
                "trait1": ("trait_pair", pair_labels[0]), "trait2": ("trait_pair", pair_labels[1])})
    va = {"G": {"long_name": "genetic covariance (inference)", "units": "trait covariance units"},
          "E": {"long_name": "residual covariance", "units": "trait covariance units"},
          "rG_SE": {"long_name": "standard error of the genetic correlation", "units": "1"},
          "heritability_table": {"long_name": "per-trait variance components, heritability and closure QA",
                                 "description": "Columns along heritability_field; boolean flags stored as 0/1."},
          "g_corr_table": {"long_name": "pairwise phenotypic/genetic correlations with SEs and p-values",
                           "description": "One row per trait pair (trait1 < trait2); boundary flag stored as 0/1."}}
    dataset = result_dataset(values, dims=dims, var_attrs=va,
                          title="Covariance, heritability and genetic-correlation summary tables",
                          software="vigor.multivariate.organize_scores", parameters=_call_parameters(arguments))
    source = _result_view(arguments.get('SCORE_output', {}))
    if 'uncertainty_method' in source:
        dataset.attrs['uncertainty_method'] = str(source['uncertainty_method'])
    prior = source.get('h2_prior', {})
    if isinstance(prior, dict) and prior.get('active'):
        dataset.attrs['h2_prior_strength'] = float(prior.get('strength', 0.0))
        dataset['heritability_table'].attrs['h2_interval'] = 'robust empirical-Bayes interval; normal-null h2 p-values withheld'
    return dataset


@_dataset_result(_organize_scores_dataset)
def organize_scores(df, SCORE_output, *, save_path=None):
    """Organize covariance, closure-QA and boundary-safe uncertainty tables.

    Parameters
    ----------
    df : array-like, table or labeled object
        Input values consumed by this conversion or analysis. Preserve the labels/axis ordering
        described in the summary; the local coercion/selection expression below defines the
        accepted representation.

    SCORE_output : xarray.Dataset or mapping
        genetic_varcov_PSD result (Dataset, or a legacy dict/Series) providing G/E/Rg,
        their SEs, h2 fields and variance-boundary/closure diagnostics.

    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.

    Returns
    -------
    xarray.Dataset
        ``G``, ``E`` and ``rG_SE`` on ('trait_i','trait_j'); ``heritability_table``
        ('trait','heritability_field') with vG, vE, closure QA, h2, SEs, p-values and boundary
        flags (0/1); ``g_corr_table`` ('trait_pair','g_corr_field') with phenotypic/genetic
        correlations, SEs, p-values and boundary flag, labeled by ``trait1``/``trait2``
        coordinates. Use ``ds['heritability_table'].to_pandas()`` for the wide table.
    """
    SCORE_output=_result_view(SCORE_output)
    columns=pd.Index(df.columns)
    Ecov=pd.DataFrame(np.asarray(SCORE_output['E'],float),index=columns,columns=columns)
    Gcov=pd.DataFrame(np.asarray(SCORE_output.get('G_unshrunk', SCORE_output['G']),float),index=columns,columns=columns)
    RG=pd.DataFrame(np.asarray(SCORE_output.get('Rg_unshrunk', SCORE_output['Rg']),float),index=columns,columns=columns)
    RG_se=(pd.DataFrame(np.asarray(SCORE_output.get('rg_unshrunk_se', SCORE_output['rg_se']),float),index=columns,columns=columns)
           if 'rg_se' in SCORE_output else pd.DataFrame(np.nan,index=columns,columns=columns))
    b=SCORE_output.get('variance_boundary',{})
    g0=np.asarray(b.get('G_near_zero',np.zeros(len(columns),bool)),bool)
    e0=np.asarray(b.get('E_near_zero',np.zeros(len(columns),bool)),bool)
    t0=np.asarray(b.get('total_near_zero',np.zeros(len(columns),bool)),bool)
    pair_boundary=g0[:,None]|g0[None,:]|t0[:,None]|t0[None,:]
    RG=RG.mask(pd.DataFrame(pair_boundary,index=columns,columns=columns))
    RG_se=RG_se.mask(pd.DataFrame(pair_boundary,index=columns,columns=columns))
    phenocorr=_legacy.corr_se_matrix_fisher(df)
    zrg=RG.divide(RG_se).where((RG_se>0)&~pd.DataFrame(pair_boundary,index=columns,columns=columns))
    p_rg=erfc(np.abs(zrg)/np.sqrt(2.0))
    boundary_df=pd.DataFrame(pair_boundary,index=columns,columns=columns)
    prior=SCORE_output.get('h2_prior',{})
    prior_active=bool(isinstance(prior,dict) and prior.get('active'))
    rg_ci=[]
    for key in ('rg_ci95_low','rg_ci95_high'):
        mat=(pd.DataFrame(np.asarray(SCORE_output[key],float),index=columns,columns=columns)
             if key in SCORE_output else pd.DataFrame(np.nan,index=columns,columns=columns))
        rg_ci.append(mat.mask(boundary_df))
    def _melt_score_matrix(mat, value_name):
        # Trait labels are allowed to literally be ``trait1`` or ``trait2``.
        # Avoid reset_index/melt column-name collisions by constructing the
        # long representation from the matrix coordinates directly.
        """Return the melt score matrix result computed by ``pd.DataFrame({'trait1': ii, 'trait2': jj, value_name: vv}).set_index``.

        Parameters
        ----------
        mat : object (see the cited input contract)
            Input for the operation ``mat.copy()``. See
            ``vigor.multivariate.organize_scores._melt_score_matrix`` and its caller for the
            scientific representation; the shown operation constrains the required type/shape.

        value_name : str
            Identifier used to select or label the relevant component, field or output quantity. It
            must match the names present in the supplied object where lookup is required.
        """
        z=mat.copy()
        ii=np.repeat(np.asarray(z.index,dtype=object),len(z.columns))
        jj=np.tile(np.asarray(z.columns,dtype=object),len(z.index))
        vv=np.asarray(z).reshape(-1)
        return pd.DataFrame({'trait1':ii,'trait2':jj,value_name:vv}).set_index(['trait1','trait2'])
    gcorr_melted=pd.concat([
        _melt_score_matrix(i,j)
        for i,j in zip([phenocorr[0],phenocorr[1],RG,RG_se,rg_ci[0],rg_ci[1],p_rg,boundary_df],
                       ['phenotypic_correlation','rP_SE','genetic_correlation','rG_SE','rG_ci_low','rG_ci_high','pval','boundary'])
    ],axis=1).query('trait1 < trait2')
    vg=np.asarray(SCORE_output.get('G_diag',np.diag(Gcov)),float)
    ve=np.asarray(SCORE_output.get('E_diag',np.diag(Ecov)),float);total=vg+ve
    vp=np.asarray(SCORE_output.get('phenotypic_variance_observed',df.var(axis=0,ddof=1)),float)
    closure=np.asarray(SCORE_output.get('variance_closure_ratio',np.divide(total,vp,out=np.full(len(vg),np.nan),where=vp>0)),float)
    closure_z=np.asarray(SCORE_output.get('variance_closure_z',np.full(len(vg),np.nan)),float)
    closure_flag=np.asarray(SCORE_output.get('variance_closure_flag',np.zeros(len(vg),bool)),bool)
    h2=np.asarray(SCORE_output.get('h2',np.divide(vg,total,out=np.full(len(vg),np.nan),where=~t0)),float)
    h2_pheno=np.asarray(SCORE_output.get('h2_phenotype',np.divide(vg,vp,out=np.full(len(vg),np.nan),where=vp>0)),float)
    svg=np.diag(np.asarray(SCORE_output['G_se'],float)) if 'G_se' in SCORE_output else np.full(len(vg),np.nan)
    sve=np.diag(np.asarray(SCORE_output['E_se'],float)) if 'E_se' in SCORE_output else np.full(len(vg),np.nan)
    svg=np.asarray(SCORE_output.get('G_variance_se',svg),float)
    sve=np.asarray(SCORE_output.get('E_variance_se',sve),float)
    if 'h2_se' in SCORE_output:
        h2_se=np.asarray(SCORE_output['h2_se'],float)
    else:
        dg=np.divide(ve,total*total,out=np.zeros(len(vg)),where=total>0); de=np.divide(-vg,total*total,out=np.zeros(len(vg)),where=total>0)
        h2_se=np.sqrt(np.maximum(dg*dg*svg*svg+de*de*sve*sve,0.0))
    # Normal p-values are not valid exactly on a variance-component boundary.
    h2_boundary=(g0|e0|t0)
    h2_pvalue=.5*erfc(np.abs(np.divide(h2,h2_se,out=np.full_like(h2,np.nan),where=(h2_se>0)&~h2_boundary))/np.sqrt(2.0))
    def _interval(key):
        if key not in SCORE_output:
            return np.full(len(vg),np.nan),np.full(len(vg),np.nan)
        ci=np.asarray(SCORE_output[key],float)
        return ci[:,0],ci[:,1]
    h2_lo,h2_hi=_interval('h2_ci95')
    vg_lo,vg_hi=_interval('G_variance_ci95')
    ve_lo,ve_hi=_interval('E_variance_ci95')
    if prior_active:
        # A normal null p-value of a shrunk estimate is not a valid test; the
        # robust EB interval carries the inference instead.
        h2_pvalue[:]=np.nan
        significance=(h2_lo>0)&~h2_boundary
    else:
        significance=(h2_pvalue<.05)&~h2_boundary
    her=pd.DataFrame({
        'vG':vg,'vE':ve,'phenotypic_variance_model':total,'phenotypic_variance_observed':vp,
        'variance_closure_ratio':closure,'variance_closure_z':closure_z,'variance_closure_flag':closure_flag,
        'h2':h2,'h2_phenotype':h2_pheno,
        'vG_se':svg,'vG_ci_low':vg_lo,'vG_ci_high':vg_hi,
        'vE_se':sve,'vE_ci_low':ve_lo,'vE_ci_high':ve_hi,
        'h2_se':h2_se,'h2_ci_low':h2_lo,'h2_ci_high':h2_hi,'pval':h2_pvalue,
        'G_boundary':g0,'E_boundary':e0,'total_boundary':t0,'boundary':h2_boundary,
        'significance':significance,
    },index=columns)
    if prior_active:
        for key,column in (('h2_prior_mean','h2_prior_mean'),('h2_prior_weight','h2_prior_weight'),
                           ('h2_pilot','h2_pilot'),('h2_pilot_se','h2_pilot_se')):
            if key in SCORE_output:
                her[column]=np.asarray(SCORE_output[key],float)
    return pd.Series({'heritability_table':her,'g_corr_table':gcorr_melted,'G':Gcov,'rG_SE':RG_se,'E':Ecov})


# ---------------------------------------------------------------------------
# Shared mvBLUP / mvGWAS observed-space PCG plan
# ---------------------------------------------------------------------------
@dataclass
class PreparedMultivariatePlan:
    """Reusable Gaussian conditioning system on finite phenotype cells.

    The plan stores centered observations and their mask, matched animal kernels,
    trait covariance factors, and the observed covariance/preconditioner operators.
    It does not automatically rebuild when traits/covariances change. See
    prepare_mvBLUP_plan for construction parameters, precision and rank constraints.

    Examples
    --------
        plan = prepare_mvBLUP_plan(traits, grm, covariance_fit, accuracy='exact')
        alpha, diagnostics = plan.solve()
        assert diagnostics['cg_info'] == 0

    Constructor fields
    ------------------
    kernels : dict[str, KernelOperator]
        Named animal kernels sharing one sample axis. Required construction field.

    G_specs : dict[str, FactorCovarianceSpec]
        Genetic trait covariance specification for each matching kernel name. Required
        construction field.

    E_spec : FactorCovarianceSpec
        Residual trait covariance specification in the same trait order. Required construction
        field.

    obs_plan : dict
        Finite-cell index/response plan used by the covariance operator and solver. Required
        construction field.

    operator : LinearOperator
        Observed-cell covariance LinearOperator for the current phenotype mask. Required
        construction field.

    preconditioner : LinearOperator | None
        Inverse/preconditioning LinearOperator, or None to disable it. Required construction
        field.

    n : int
        Stored n supplied by the corresponding fitting/planning routine. See that routine for
        the result-axis/value contract. Required construction field.

    t : int
        Stored t supplied by the corresponding fitting/planning routine. See that routine for
        the result-axis/value contract. Required construction field.

    dtype : Any
        Stored dtype consumed by ``solve``; see those methods for the numerical/label contract.
        Required construction field.

    jitter : float
        Stored jitter supplied by the corresponding fitting/planning routine. See that routine
        for the result-axis/value contract. Required construction field.

    preconditioner_name : str
        Stored preconditioner name consumed by ``solve``; see those methods for the
        numerical/label contract. Required construction field.

    means : np.ndarray
        Training/observed trait means subtracted before preparing the finite-cell solve.
        Required construction field.

    index : Any
        Stored index supplied by the corresponding fitting/planning routine. See that routine
        for the result-axis/value contract. Default: ``None``.

    columns : Any
        Stored columns supplied by the corresponding fitting/planning routine. See that routine
        for the result-axis/value contract. Default: ``None``.

    operator_diagnostics : dict | None
        Stored operator diagnostics supplied by the corresponding fitting/planning routine. See
        that routine for the result-axis/value contract. Default: ``None``.

    accuracy : str
        Plan conditioning mode: 'exact' full-kernel float64 or 'fast' configured working
        precision. Default: ``'fast'``.

    diag_only : bool
        Whether the prepared plan drops cross-trait covariance terms. Default: ``False``.
    """
    kernels: dict[str, KernelOperator]
    G_specs: dict[str, FactorCovarianceSpec]
    E_spec: FactorCovarianceSpec
    obs_plan: dict
    operator: LinearOperator
    preconditioner: LinearOperator | None
    n: int
    t: int
    dtype: Any
    jitter: float
    preconditioner_name: str
    means: np.ndarray
    index: Any = None
    columns: Any = None
    operator_diagnostics: dict | None = None
    accuracy: str = "fast"
    diag_only: bool = False

    @operation_progress('mvPredict: observed PCG solve')
    def solve(self, y=None, rtol=1e-7, maxiter=500, *, progress=None, iteration_callback=None):
        """Solve the prepared linear system and return convergence diagnostics.

        Parameters
        ----------
        y : array-like
            Numerical operand in ``np.asarray(self.obs_plan['y'] if y is None else y,
            dtype=self.dtype)``. Shape must conform to that matrix/vector operation and the
            enclosing prepared state. Default: ``None``.

        rtol : float
            Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
            value; relative, gradient and objective criteria follow the underlying solver named in
            this routine. Default: ``1e-07``. Passed to ``cg`` as ``rtol``.

        maxiter : int
            Maximum solver iteration count. A positive integer caps work; convergence diagnostics
            must still be checked rather than assuming the cap guarantees convergence. Default:
            ``500``. Passed to ``cg`` as ``maxiter``.

        progress : bool or None
            Default None inherits the active operation; True enables counted
            PCG iterations with unknown completion total; False disables output.

        iteration_callback : callable or None
            Default None. Called with (iteration, iterate) after each actual
            PCG iteration. Treat the solver-owned iterate as read-only. No
            additional residual or matrix-vector calculation is performed.

        Returns
        -------
        object
            Computed result from ``(x, {'cg_info': int(info), 'cg_iterations': int(nit[0]), 'cg_relative_residual': float(res), 'preconditioner': self.preconditioner_name})``; see the summary and the called implementation for its labeled/numerical representation.
        """
        b = np.asarray(self.obs_plan["y"] if y is None else y, dtype=self.dtype)
        operation_stage('mvPredict: observed PCG solve')
        _solve_bar = current_work()
        nit = [0]
        def cb(_): 
            """Record progress for an accepted iterative-solver update.

            Parameters
            ----------
            _ : one-dimensional array-like
                Vector supplied by the linear operator/iterative-solver callback. Length equals the
                enclosing operator dimension; observed-cell operators use the prepared finite-cell
                order.
            """
            nit[0] += 1
            if _solve_bar is not None: _solve_bar.update()
            from .progress import _emit_progress
            _emit_progress({'phase':'prediction_pcg','iteration':nit[0]})
            if iteration_callback is not None: iteration_callback(nit[0], _)
        x, info = cg(self.operator, b, M=self.preconditioner, rtol=float(rtol), atol=0.0, maxiter=int(maxiter), callback=cb)
        residual = np.asarray(self.operator @ x, dtype=np.float64) - np.asarray(b, dtype=np.float64)
        res = np.linalg.norm(residual) / max(np.linalg.norm(np.asarray(b, dtype=np.float64)), 1e-30)
        return x, {"cg_info": int(info), "cg_iterations": int(nit[0]), "cg_relative_residual": float(res), "preconditioner": self.preconditioner_name}


def _extract_component_specs(G, E, kernel_names):
    """Extract component specs.

    Parameters
    ----------
    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance.

    kernel_names : sequence of str or None
        Ordered component identifiers used for lookup and labeling. Length/order must match the
        corresponding matrices; None uses the implementation's inferred/default names. Passed to
        ``as_covariance_spec`` as ``name``.
    """
    G = _covariance_input(G)
    E = _as_pandas_input(E)
    if isinstance(G, pd.Series) and ("G_components_prediction" in G or "G_components" in G):
        ge = G
        components = ge.get("G_components_prediction", ge["G_components"])
        specs0 = ge.get("component_specs_prediction", {})
        E0 = ge.get("E_prediction", ge["E"]) if E is None else E
        Gspec = {n: as_covariance_spec(specs0.get(n, components[n]), name=n) for n in kernel_names}
        Espec = as_covariance_spec(ge.get("E_spec_prediction", E0) if E is None else E, name="E")
        return Gspec, Espec
    if len(kernel_names) == 1 and (not isinstance(G, dict) or any(k in G for k in ("factor", "matrix", "diag"))):
        return {kernel_names[0]: as_covariance_spec(G, name=kernel_names[0])}, as_covariance_spec(E, name="E")
    if not isinstance(G, dict):
        raise ValueError("multiple GRMs require a component mapping or genetic_varcov_PSD result")
    return {n: as_covariance_spec(G[n], name=n) for n in kernel_names}, as_covariance_spec(E, name="E")


def _make_observed_operator_generic(kernels, Gspec, Espec, obs, n, t, dtype, jitter=0.0):
    """Construct observed operator generic.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    obs : mapping
        Observed-cell plan containing animal/trait indices, trait slices and finite-response
        values. Obtain it from the observation-plan helper for the same phenotype matrix.

    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit.

    t : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Passed to ``np.zeros`` as ``dtype``.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``0.0``.
    """
    A=np.zeros((n,t),dtype=dtype);out=np.empty(obs["m"],dtype=dtype)
    flat=obs.get("flat",obs["animals"].astype(np.int64)*t+obs["traits"].astype(np.int64))
    dense_cov={name:np.asarray(sp.materialize(),dtype=dtype) for name,sp in Gspec.items()
               if 2*sp.rank >= t}
    def matvec(v):
        """Apply the enclosing covariance/kernel operator to one vector.

        Parameters
        ----------
        v : one-dimensional array-like
            Vector supplied by the linear operator/iterative-solver callback. Length equals the
            enclosing operator dimension; observed-cell operators use the prepared finite-cell
            order.

        Returns
        -------
        object
            Computed result from ``out.copy()``; see the summary and the called implementation for its labeled/numerical representation.
        """
        A.fill(0);A.ravel()[flat]=v;Z=np.zeros((n,t),dtype=dtype)
        for name,Kop in kernels.items():
            sp=Gspec[name]
            if name in dense_cov:
                Z += Kop.matmat(A) @ dense_cov[name]
            elif np.any(sp.diag_specific):
                # Positive uniqueness needs all kernel RHS, but not dense G.
                # Apply the low-rank factor and diagonal to ONE shared K@A.
                Z += sp.apply_right(Kop.matmat(A))
            else:
                if sp.rank: Z += Kop.matmat(A @ sp.factor) @ sp.factor.T
                if np.any(sp.diag_specific): Z += Kop.matmat(A * sp.diag_specific[None,:])
        Z += Espec.apply_right(A)
        if jitter: Z += float(jitter)*A
        out[:]=Z.ravel()[flat];return out.copy()
    op=LinearOperator((obs["m"],obs["m"]),matvec=matvec,dtype=np.dtype(dtype))
    op.domino_diagnostics={"mask_aware_specific_diagonal":False,"engine":"generic_dense_rhs"}
    return op


def _make_observed_operator_masked_dense(kernels,Gspec,Espec,obs,n,t,dtype,jitter,submatrices):
    """Exact observed operator using small GRM blocks for FA-specific variance.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    obs : mapping
        Observed-cell plan containing animal/trait indices, trait slices and finite-response
        values. Obtain it from the observation-plan helper for the same phenotype matrix.

    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit.

    t : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Passed to ``np.zeros`` as ``dtype``.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities.

    submatrices : object (see the cited input contract)
        Compatibility/callback input accepted but not consumed by this body. Any object is
        locally accepted; see the calling protocol for the supplied type.
    """
    A=np.zeros((n,t),dtype=dtype);Z=np.zeros((n,t),dtype=dtype);out=np.empty(obs["m"],dtype=dtype)
    flat=obs.get("flat",obs["animals"].astype(np.int64)*t+obs["traits"].astype(np.int64))
    def matvec(v):
        """Apply the enclosing covariance/kernel operator to one vector.

        Parameters
        ----------
        v : one-dimensional array-like
            Vector supplied by the linear operator/iterative-solver callback. Length equals the
            enclosing operator dimension; observed-cell operators use the prepared finite-cell
            order.

        Returns
        -------
        object
            Computed result from ``out.copy()``; see the summary and the called implementation for its labeled/numerical representation.
        """
        A.fill(0);A.ravel()[flat]=v;Z[:]=Espec.apply_right(A)
        for name,Kop in kernels.items():
            sp=Gspec[name]
            if sp.rank: Z[:] += Kop.matmat(A @ sp.factor) @ sp.factor.T
            d=sp.diag_specific;mats=submatrices[name]
            for j,sl in enumerate(obs["slices"]):
                if sl.stop==sl.start or abs(float(d[j]))<=1e-30: continue
                ib=obs["idx"][j];Z[ib,j] += float(d[j])*(mats[j] @ np.asarray(v[sl],dtype=dtype))
        if jitter: Z[:] += float(jitter)*A
        out[:]=Z.ravel()[flat];return out.copy()
    op=LinearOperator((obs["m"],obs["m"]),matvec=matvec,dtype=np.dtype(dtype))
    op.domino_diagnostics={"mask_aware_specific_diagonal":True,"engine":"dense_grm_sparse_trait_diagonal"}
    return op


def _make_observed_operator_sparse_columns(kernels,Gspec,Espec,obs,n,t,dtype,jitter):
    """Cache only observed kernel columns and active rows, within 1 GiB.

    Unlike low-rank compression, removing zero entries of the right hand side
    leaves the observed covariance operator mathematically unchanged.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    obs : mapping
        Observed-cell plan containing animal/trait indices, trait slices and finite-response
        values. Obtain it from the observation-plan helper for the same phenotype matrix.

    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit.

    t : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Passed to ``np.zeros`` as ``dtype``.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities.
    """
    active=np.unique(obs["animals"]);lookup=np.full(n,-1,int);lookup[active]=np.arange(len(active))
    flat=lookup[obs["animals"]]*t+obs["traits"]
    blocks={name:[np.asarray(K.K[np.ix_(active,ib)],dtype=dtype,order="C") for ib in obs["idx"]] for name,K in kernels.items()}
    gm={name:np.asarray(sp.materialize(),dtype=dtype) for name,sp in Gspec.items()}
    em=np.asarray(Espec.materialize(),dtype=dtype)
    A=np.zeros((len(active),t),dtype=dtype);B=np.empty_like(A)
    def matvec(v):
        """Apply the enclosing covariance/kernel operator to one vector.

        Parameters
        ----------
        v : one-dimensional array-like
            Vector supplied by the linear operator/iterative-solver callback. Length equals the
            enclosing operator dimension; observed-cell operators use the prepared finite-cell
            order.

        Returns
        -------
        object
            Computed result from ``Z.ravel()[flat].copy()``; see the summary and the called implementation for its labeled/numerical representation.
        """
        A.fill(0);A.ravel()[flat]=v;Z=A@em
        for name,mats in blocks.items():
            for j,sl in enumerate(obs["slices"]):B[:,j]=mats[j]@v[sl]
            Z+=B@gm[name]
        if jitter:Z+=float(jitter)*A
        return Z.ravel()[flat].copy()
    op=LinearOperator((obs["m"],obs["m"]),matvec=matvec,dtype=np.dtype(dtype))
    op.domino_diagnostics={"engine":"observed_kernel_columns","exact":True,"cache_bytes":sum(b.nbytes for bs in blocks.values() for b in bs)}
    return op


def _make_observed_operator(kernels,Gspec,Espec,obs,n,t,dtype,jitter=0.0):
    """Construct observed operator.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    obs : mapping
        Observed-cell plan containing animal/trait indices, trait slices and finite-response
        values. Obtain it from the observation-plan helper for the same phenotype matrix.

    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit.

    t : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``0.0``. Passed to ``_make_observed_operator_generic`` as
        ``jitter``.
    """
    frac=float(obs["m"])/max(float(n*t),1.0)
    all_dense=all(isinstance(k,DenseKernelOperator) for k in kernels.values())
    sparse_bytes=len(np.unique(obs["animals"]))*obs["m"]*np.dtype(dtype).itemsize*len(kernels)
    if all_dense and frac<0.20 and sparse_bytes<=1024**3:
        return _make_observed_operator_sparse_columns(kernels,Gspec,Espec,obs,n,t,dtype,jitter)
    # Only FA-specific diagonals require observed-trait GRM blocks. PCA and
    # zero-specific traits use the shared factor product exclusively.
    bytes_est=sum(len(ib)**2 for name in kernels for j,ib in enumerate(obs["idx"])
                  if abs(float(Gspec[name].diag_specific[j]))>1e-30)*np.dtype(dtype).itemsize
    use=all_dense and frac<0.55 and bytes_est<=512*1024**2
    if not use:return _make_observed_operator_generic(kernels,Gspec,Espec,obs,n,t,dtype,jitter=jitter)
    mats={name:[np.asarray(Kop.K[np.ix_(ib,ib)],dtype=dtype,order="C") if len(ib) and abs(float(Gspec[name].diag_specific[j]))>1e-30 else None for j,ib in enumerate(obs["idx"])] for name,Kop in kernels.items()}
    op=_make_observed_operator_masked_dense(kernels,Gspec,Espec,obs,n,t,dtype,jitter,mats)
    op.domino_diagnostics.update(observed_fraction=frac,specific_block_cache_bytes=int(bytes_est))
    return op


def _diag_preconditioner(kernels, Gspec, Espec, obs, jitter, dtype):
    """Return the diag preconditioner result computed by ``LinearOperator``.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    obs : mapping
        Observed-cell plan containing animal/trait indices, trait slices and finite-response
        values. Obtain it from the observation-plan helper for the same phenotype matrix.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Passed to ``LinearOperator`` as ``dtype``.
    """
    d = np.zeros(obs["m"], dtype=np.float64)
    for name, Kop in kernels.items():
        d += Kop.diag()[obs["animals"]] * Gspec[name].diagonal()[obs["traits"]]
    d += Espec.diagonal()[obs["traits"]] + float(jitter)
    d = np.maximum(d, float(jitter)).astype(dtype)
    return LinearOperator((obs["m"], obs["m"]), matvec=lambda v: np.asarray(v) / d, dtype=np.dtype(dtype))


def _sample_block_preconditioner(kernels, Gspec, Espec, obs, n, t, jitter, dtype):
    """Exact block Jacobi within each animal, grouped by observed-trait mask.

    Construction is independent of n-by-n kernel factorizations.  Each block
    contains E plus the diagonal kernel-weighted G components; only observed
    traits enter the block, so irregular missingness is handled exactly.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    obs : mapping
        Observed-cell plan containing animal/trait indices, trait slices and finite-response
        values. Obtain it from the observation-plan helper for the same phenotype matrix.

    n : int
        Number of animals/rows in the aligned sample axis. Supply the actual nonnegative axis
        length, not an arbitrary truncation limit.

    t : int
        Number of traits in the ordered response/covariance axis; must agree with every
        corresponding matrix dimension.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Passed to ``np.zeros`` as ``dtype``.
    """
    mask=np.zeros((n,t),bool);mask[obs["animals"],obs["traits"]]=True
    patterns,inv=np.unique(mask,axis=0,return_inverse=True)
    ordered=np.argsort(inv,kind="stable");bounds=np.r_[0,np.cumsum(np.bincount(inv,minlength=len(patterns)))]
    flat=obs["flat"];blocks=[]
    kd={name:np.asarray(K.diag(),dtype=np.float64) for name,K in kernels.items()}
    gm={name:np.asarray(sp.materialize(),dtype=np.float64) for name,sp in Gspec.items()}
    em=np.asarray(Espec.materialize(),dtype=np.float64)
    for q,pat in enumerate(patterns):
        jj=np.flatnonzero(pat);ii=ordered[bounds[q]:bounds[q+1]]
        if not len(jj):continue
        ix=np.ix_(jj,jj);b=np.broadcast_to(em[ix],(len(ii),len(jj),len(jj))).copy()
        for name in kernels:b+=kd[name][ii,None,None]*gm[name][ix][None,:,:]
        b[:,np.arange(len(jj)),np.arange(len(jj))]+=float(jitter)
        try:
            chol = np.linalg.cholesky(b)
            eye = np.broadcast_to(np.eye(len(jj)), b.shape)
            bi = np.linalg.solve(np.swapaxes(chol, -1, -2), np.linalg.solve(chol, eye))
        except np.linalg.LinAlgError as exc:
            raise ValueError("sample_block preconditioner is not positive definite; check covariance components and jitter") from exc
        blocks.append((ii[:,None]*t+jj[None,:],np.asarray(bi,dtype=dtype)))
    a=np.zeros(n*t,dtype=dtype);z=np.zeros_like(a)
    def matvec(v):
        """Apply the enclosing covariance/kernel operator to one vector.

        Parameters
        ----------
        v : one-dimensional array-like
            Vector supplied by the linear operator/iterative-solver callback. Length equals the
            enclosing operator dimension; observed-cell operators use the prepared finite-cell
            order.

        Returns
        -------
        object
            Computed result from ``z[flat].copy()``; see the summary and the called implementation for its labeled/numerical representation.
        """
        a[flat]=v
        for index,bi in blocks:z[index]=np.einsum("nij,nj->ni",bi,a[index],optimize=False)
        return z[flat].copy()
    return LinearOperator((obs["m"],obs["m"]),matvec=matvec,dtype=np.dtype(dtype))


def _trait_block_preconditioner(kernels, Gspec, Espec, obs, jitter, dtype):
    """Return the trait block preconditioner result computed by ``LinearOperator``.

    Parameters
    ----------
    kernels : mapping
        Named animal relationship kernels; each matrix/operator must use the same animal order.
        Names identify the matching trait covariance components.

    Gspec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    Espec : covariance/kernel specification
        Normalized matrix representation produced by the corresponding specification helper.
        Dense, factor and diagonal pieces must use compatible dimensions and axis order.

    obs : mapping
        Observed-cell plan containing animal/trait indices, trait slices and finite-response
        values. Obtain it from the observation-plan helper for the same phenotype matrix.

    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities.

    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Passed to ``np.eye`` as ``dtype``.
    """
    unsupported=[name for name,Kop in kernels.items() if getattr(Kop,"supports_submatrix",True) is False]
    if unsupported:
        raise ValueError(f"trait_block preconditioner requires cheap kernel submatrices; unsupported: {unsupported}. Use preconditioner='diag'.")
    fac = []
    diag_fallback = []
    for j, ib in enumerate(obs["idx"]):
        if not len(ib):
            fac.append(None)
            diag_fallback.append(np.empty(0, dtype=dtype))
            continue
        P = np.eye(len(ib), dtype=dtype) * (Espec.diagonal()[j] + float(jitter))
        for name, Kop in kernels.items():
            P += float(Gspec[name].diagonal()[j]) * np.asarray(Kop.submatrix(ib), dtype=dtype)
        diag_fallback.append(np.maximum(np.diag(P).copy(), np.finfo(np.dtype(dtype)).tiny))
        try:
            fac.append(cho_factor(_sym(P), lower=True, check_finite=False))
        except np.linalg.LinAlgError:
            fac.append(None)
    def mv(v):
        """Compute mv.

        Parameters
        ----------
        v : one-dimensional array-like
            Vector supplied by the linear operator/iterative-solver callback. Length equals the
            enclosing operator dimension; observed-cell operators use the prepared finite-cell
            order.

        Returns
        -------
        object
            Computed result from ``z``; see the summary and the called implementation for its labeled/numerical representation.
        """
        z = np.empty_like(v, dtype=dtype)
        for j, sl in enumerate(obs["slices"]):
            if sl.stop == sl.start:
                continue
            if fac[j] is None:
                z[sl] = v[sl] / diag_fallback[j]
            else:
                z[sl] = cho_solve(fac[j], v[sl], check_finite=False)
        return z
    return LinearOperator((obs["m"], obs["m"]), matvec=mv, dtype=np.dtype(dtype))


@operation_progress('mvPredict: preparation')
def prepare_mvBLUP_plan(
    traits,
    GRM,
    G,
    E=None,
    *,
    center=True,
    work_dtype="auto",
    jitter=1e-8,
    preconditioner="auto",
    kernel_rank="auto",
    kernel_random_state=0,
    blas_threads="auto",
    diag_only=False,
    accuracy="fast",
    progress=None,
):
    """Prepare multivariate breeding-value prediction plan.
    
    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data. Passed to ``PreparedMultivariatePlan`` as ``index``.
    
    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.
    
    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result.
    
    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``.
    
    center : bool
        Whether to subtract the observed/training mean along the modeled observation axis.
        Disable only when inputs have already been centered using training data or a
        zero-intercept model is intended. Default: ``True``.
    
    work_dtype : str or NumPy float32/float64 dtype
        Working precision: 'auto'/'mixed' uses float32 in a fast plan; 'float32' and 'float64'
        explicitly select precision, with equivalent NumPy type/dtype objects accepted.
        accuracy='exact' resolves auto to float64 and rejects explicit float32/mixed. Other
        dtypes are rejected. Default: ``'auto'``.
    
    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to ``_make_observed_operator`` as
        ``jitter``.
    
    preconditioner : str or None
        PCG preconditioning: 'auto' selects 'sample_block' when 1<T<=64 and trait covariance is
        coupled, otherwise 'diag'; 'diag' uses observed marginal variances, 'sample_block'
        within-animal observed-trait blocks, and 'trait_block' within-trait animal blocks
        (requires cheap kernel submatrices). 'none'/None disables preconditioning. Default:
        ``'auto'``.
    
    kernel_rank : int, str or None
        Animal-kernel approximation rank. None, 0, False or 'full' retains the full kernel;
        'auto' uses a size-based rank in fast plans; a positive integer requests that many
        retained eigenvectors plus a residual bulk eigenvalue. Exact plans reject compression.
        This is distinct from trait covariance rank. Default: ``'auto'``. Source comparisons:
        ``kernel_rank not in {None, False, 0, 'full', 'auto'}``. See the rejection/fallback
        branches for enforcement.
    
    kernel_random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``as_kernel_operator`` as ``random_state``.
    
    blas_threads : int or str
        BLAS thread limit during numerical operations. Positive integers select an explicit
        thread count; auto uses the routine's workload-dependent thread policy. Default:
        ``'auto'``.
    
    diag_only : bool
        Whether to remove cross-trait covariance terms and use only the diagonal trait variances
        for conditioning. Default: ``False``. Passed to ``PreparedMultivariatePlan`` as
        ``diag_only``.
    
    accuracy : str
        Conditioning precision: 'auto' selects 'exact' below 1024 animals and 'fast' at/above
        1024; 'exact' forces float64/full-kernel conditioning, while 'fast' permits float32 and
        requested kernel compression. prepare_mvBLUP_plan accepts only 'exact' and 'fast'.
        Default: ``'fast'``.
    
    progress : bool or None
        Default None inherits an active prediction scope. True enables the
        preparation phase; False disables preparation reporting.
    
    Returns
    -------
    PreparedMultivariatePlan
        Reusable observed-space covariance operator, preconditioner, trait means, kernel/spec
        metadata and finite-cell indexing. solve returns the dual solution and convergence
        diagnostics; recreating the plan is required after changing phenotype masks or
        covariance inputs.
    
    Complexity
    ----------
    With dense supplied kernels, TIME O(k n²+k t³+nt)+preconditioner setup; SPACE O(k n²+nt+k t²+P), for n animals, t traits, k kernels and P preconditioner storage. Covariance conversion may eigendecompose t-by-t matrices. Diagonal preconditioning is O(k nt) time/O(nt) space; sample blocks are bounded by O(n t³)/O(n t²); trait blocks by O(t n³)/O(t n²), reduced by observed counts. Requested rank-q approximation can add a dense O(n³) eigendecomposition or randomized operator work; preexisting factors avoid dense storage. This function prepares, never runs PCG.
    """
    operation_stage('mvPredict: preparation')
    accuracy = str(accuracy).lower()
    if accuracy not in {"fast", "exact"}:
        raise ValueError("accuracy must be 'fast' or 'exact'")
    traits = _as_pandas_input(traits)
    GRM = _align_labeled_kernels_to_traits(GRM, traits)
    Y = traits.to_numpy(float, copy=True) if isinstance(traits, pd.DataFrame) else np.asarray(traits, float).copy()
    means = np.nanmean(Y, axis=0) if center else np.zeros(Y.shape[1])
    means = np.where(np.isfinite(means), means, 0.0)
    Y -= means[None, :]
    n, t = Y.shape
    valid_work_dtypes = {"auto", "mixed", "float32", "float64", np.float32, np.float64, np.dtype("float32"), np.dtype("float64")}
    if work_dtype not in valid_work_dtypes:
        raise ValueError("work_dtype must be 'auto', 'mixed', 'float32', or 'float64'")
    if accuracy == "exact" and work_dtype in {"mixed", "float32", np.float32, np.dtype("float32")}:
        raise ValueError("accuracy='exact' requires float64 working precision")
    wd = np.float64 if accuracy == "exact" else (np.float32 if work_dtype in {"auto", "mixed", "float32", np.float32, np.dtype("float32")} else np.float64)
    if _legacy._v31_is_multigrm(GRM):
        raw = GRM
    else:
        raw = {"genetic": GRM}
    kernels = {}
    diagnostics = {}
    if accuracy == "exact" and kernel_rank not in {None, False, 0, "full", "auto"}:
        raise ValueError("accuracy='exact' conflicts with an explicitly reduced kernel_rank")
    kr = None if accuracy == "exact" else _resolve_kernel_rank(kernel_rank, n)
    for name, K in raw.items():
        op = as_kernel_operator(K, rank=kr, dtype=wd, random_state=kernel_random_state)
        certified_external=bool(getattr(op,"domino_exact_full_rank",False))
        if accuracy == "exact" and isinstance(op, DenseKernelOperator) and np.dtype(op.dtype) != np.dtype(np.float64):
            op = DenseKernelOperator(op.K, dtype=np.float64)
        elif accuracy == "exact" and isinstance(op, LowRankKernelOperator) and op.U.shape[1] == n and np.dtype(op.dtype) != np.dtype(np.float64):
            op = LowRankKernelOperator(op.U, op.values, bulk=op.bulk, dtype=np.float64, diagnostics=op.diagnostics)
        elif accuracy == "exact" and certified_external and np.dtype(op.dtype) != np.dtype(np.float64):
            raise ValueError("accuracy='exact' requires a certified external kernel operator with float64 accumulation; construct it with dtype=np.float64")
        if accuracy == "exact" and isinstance(op, LowRankKernelOperator) and op.U.shape[1] < n:
            raise ValueError("accuracy='exact' cannot use a pre-compressed kernel unless it has a full basis")
        if accuracy == "exact" and not (isinstance(op, (DenseKernelOperator, LowRankKernelOperator)) or certified_external):
            raise ValueError("accuracy='exact' requires a dense kernel, a certified full-basis kernel, or a certified exact full-rank operator")
        if op.shape != (n, n):
            raise ValueError(f"kernel {name!r} shape {op.shape} does not match {n} trait rows")
        kernels[str(name)] = op
        kd = dict(getattr(op, "diagnostics", {}))
        exact_kernel=bool(isinstance(op, DenseKernelOperator) or (isinstance(op, LowRankKernelOperator) and op.U.shape[1] == n) or getattr(op,"domino_exact_full_rank",False))
        kd.update(resolved_rank=(op.U.shape[1] if isinstance(op, LowRankKernelOperator) else n), resolved_dtype=str(np.dtype(op.dtype)), exact=exact_kernel)
        kd.setdefault("probe_relative_error", 0.0 if kd["exact"] else np.nan)
        kd.setdefault("diagonal_relative_error", 0.0 if kd["exact"] else np.nan)
        diagnostics[str(name)] = kd
    Gspec, Espec = _extract_component_specs(G, E, list(kernels))
    if any(s.n_traits != t for s in Gspec.values()) or Espec.n_traits != t:
        raise ValueError("trait covariance dimensions do not match the trait columns")
    if diag_only:
        Gspec = {name: FactorCovarianceSpec(np.zeros((t, 0)), s.diagonal(), name=name) for name, s in Gspec.items()}
        Espec = FactorCovarianceSpec(np.zeros((t, 0)), Espec.diagonal(), name="E")
    # cast factors to working precision; preserve small trait-space diagonals in float64 semantics
    Gspec = {n0: FactorCovarianceSpec(np.asarray(s.factor, dtype=wd), np.asarray(s.diag_specific, dtype=wd), name=n0) for n0, s in Gspec.items()}
    Espec = FactorCovarianceSpec(np.asarray(Espec.factor, dtype=wd), np.asarray(Espec.diag_specific, dtype=wd), name="E")
    # FactorCovarianceSpec normalizes inference factors to float64.  Prediction
    # working precision must be restored explicitly to avoid promoting every
    # dense kernel product back to float64 in accuracy='fast'.
    for sp in [*Gspec.values(), Espec]:
        sp.factor=np.asarray(sp.factor,dtype=wd)
        sp.diag_specific=np.asarray(sp.diag_specific,dtype=wd)
    obs = _legacy._observed_plan(Y)
    if "flat" not in obs:
        obs["flat"] = obs["animals"].astype(np.int64) * t + obs["traits"].astype(np.int64)
    op = _make_observed_operator(kernels, Gspec, Espec, obs, n, t, wd, jitter=jitter)
    resolved_preconditioner=preconditioner
    if str(preconditioner).lower() == "auto":
        missing_fraction=1.0-float(obs["m"])/max(float(n*t),1.0)
        cheap_submatrices=all(getattr(Kop,"supports_submatrix",True) is not False for Kop in kernels.values())
        coupled=(1<t<=64 and any(np.any(np.abs(C-np.diag(np.diag(C)))>1e-14) for C in
                    [Espec.materialize(),*[sp.materialize() for sp in Gspec.values()]]))
        resolved_preconditioner=("sample_block" if t<=64 and t>1 and coupled else "diag")
    if resolved_preconditioner == "diag":
        M = _diag_preconditioner(kernels, Gspec, Espec, obs, jitter, wd)
    elif resolved_preconditioner == "sample_block":
        M = _sample_block_preconditioner(kernels, Gspec, Espec, obs, n, t, jitter, wd)
    elif resolved_preconditioner == "trait_block":
        M = _trait_block_preconditioner(kernels, Gspec, Espec, obs, jitter, wd)
    elif resolved_preconditioner in {None, "none"}:
        M = None
    else:
        raise ValueError("preconditioner must be 'auto', 'diag', 'sample_block', 'trait_block', or 'none'")
    return PreparedMultivariatePlan(
        kernels, Gspec, Espec, obs, op, M, n, t, wd, float(jitter), str(resolved_preconditioner), means,
        index=traits.index if isinstance(traits, pd.DataFrame) else None,
        columns=traits.columns if isinstance(traits, pd.DataFrame) else None,
        operator_diagnostics=diagnostics,
        accuracy=accuracy, diag_only=bool(diag_only),
    )


def _predict_components(plan, alpha, out_dtype=np.float64):
    """Predict components.

    Parameters
    ----------
    plan : mapping or fitted object
        Previously prepared model/result or solver state consumed by this operation. Use the
        object returned by the corresponding fitting/preparation routine with the same animal
        and trait axes. Passed to ``np.zeros`` as ``dtype``.

    alpha : float
        Regularization coefficient, mixing weight or statistical significance threshold selected
        by this estimator; the local validation and objective determine its precise scale.

    out_dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to ``np.zeros`` as ``dtype``.
    """
    A = np.zeros((plan.n, plan.t), dtype=plan.dtype)
    flat = plan.obs_plan.get("flat", plan.obs_plan["animals"].astype(np.int64) * plan.t + plan.obs_plan["traits"].astype(np.int64))
    A.ravel()[flat] = alpha
    comp = {}
    for name, Kop in plan.kernels.items():
        sp = plan.G_specs[name]
        Z = np.zeros((plan.n, plan.t), dtype=out_dtype)
        if 2*sp.rank >= plan.t:
            Z += (Kop.matmat(A) @ sp.materialize()).astype(out_dtype, copy=False)
        elif np.any(sp.diag_specific):
            Z += sp.apply_right(Kop.matmat(A)).astype(out_dtype,copy=False)
        else:
            if sp.rank:
                Z += (Kop.matmat(A @ sp.factor) @ sp.factor.T).astype(out_dtype, copy=False)
            if np.any(sp.diag_specific):
                Z += Kop.matmat(A * sp.diag_specific[None, :]).astype(out_dtype, copy=False)
        comp[name] = Z
    total = sum(comp.values(), np.zeros((plan.n, plan.t), dtype=out_dtype))
    return total, comp




def _mvblup_dataset(result, arguments):
    """Convert an ``mvBLUP`` return value (matrix, component mapping or (result, aux)) to a Dataset.

    Parameters
    ----------
    result : pandas.DataFrame, numpy.ndarray, mapping or tuple
        Summed breeding values become ``total`` on ('sample','trait'); return_components adds
        one variable per named genetic component (same dims); return_aux diagnostics are
        folded in, with ``means`` on 'trait' and scalar/dict diagnostics in attrs.
    arguments : mapping
        Bound call arguments; ``traits`` supplies sample/trait labels and scalar options are
        recorded as parameters.
    """
    res, aux = result if isinstance(result, tuple) else (result, None)
    values = dict(res) if isinstance(res, dict) else {"total": res}
    dims = {k: ("sample", "trait") for k in values}
    for key, val in dict(aux or {}).items():
        values.setdefault(key, val)
    dims["means"] = ("trait",)
    return _labeled_result_dataset(values, traits=_prediction_traits(arguments.get("traits")), dims=dims,
                                   title="Multivariate BLUP breeding values", software="vigor.multivariate.mvBLUP",
                                   arguments=arguments)


@_dataset_result(_mvblup_dataset)
def mvBLUP(
    traits,
    GRM,
    G=None,
    E=None,
    *,
    missing="exact",
    center=True,
    dtype=np.float64,
    jitter=1e-8,
    return_numpy=False,
    return_aux=False,
    solver_tol=1e-7,
    solver_maxiter=500,
    preconditioner="auto",
    work_dtype="auto",
    blas_threads="auto",
    return_components=False,
    solver_plan=None,
    kernel_rank="full",
    diag_only=False,
    solver="auto",
    accuracy="auto",
    covariance_cv=2,
    optimize_hyperparameters_cv=0,
    covariance_cv_ranks=(3,5,8,12,"full"),
    covariance_kwargs=None,
    hpo_trials=12,
    save_path=None,
    **legacy_kwargs,
):
    """mvBLUP using the reusable factor/operator PCG plan shared with mvGWAS.
    
    Defaults use kernel_rank='full' and accuracy='auto': exact float64 for small
    problems and full-kernel float32 for n>=1024. Use accuracy='exact' to force
    float64 exact conditioning. If G=None, fit sparse G+E with training-only
    animal-fold selection; use optimize_hyperparameters_cv>=2 for Optuna.
    Supplying pre-fitted G/E bypasses fitting, preserving legacy prediction.
    
    Parameters
    ----------
    traits : array-like or pandas.DataFrame
        Animal × trait observations in kernel animal order. In missing=exact, only finite cells
        enter the observed covariance solve; missing and fully unseen rows receive
        covariance-based breeding-value predictions. DataFrame outputs preserve labels unless
        return_numpy=True. Keep outer/test outcomes missing during fitting.
    
    GRM : array-like, kernel operator, or mapping
        Animal relationship kernel with matching row/column animal order. A dense kernel is
        n_animals × n_animals; supported operator representations apply the same matrix without
        materialization. Named multi-kernel inputs require corresponding trait covariance
        components.
    
    G : array-like, covariance specification, xarray.DataArray, xarray.Dataset or None
        Genetic trait covariance in observation trait order. A pre-fitted
        covariance matrix (DataFrame or DataArray such as ``fit['G_prediction']``) or a
        genetic_varcov_PSD Dataset bypasses automatic fitting.
        None triggers training-only sparse G+E factor CV. Default: ``None``.
    
    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``. Passed to the observed-cell solver as ``E``.
    
    save_path : str, os.PathLike or None
        Optional .zarr path; when given the result is written as consolidated, sharded Zarr v3
        and returned reopened lazily. Default: ``None``.
    
    covariance_cv : int
        Training-only whole-animal folds used to select sparse G+E factor rank when
        G is omitted. Every outer project test outcome must remain NaN. Default: ``2``.
    
    optimize_hyperparameters_cv : int
        Optional project-specific Optuna folds. Zero uses deterministic sparse
        rank-grid CV; an integer >=2 enables rank and regularization search
        maximizing unseen-animal genetic prediction. Default: ``0``.
    
    covariance_cv_ranks : tuple
        Candidate factor ranks applied to both G and E for the sparse-FA
        selection; includes full as a convergent candidate. Default: ``(3, 5, 8, 12, 'full')``.
    
    covariance_kwargs : dict or None
        Optional project-level fitting parameters, such as maxiter or
        shrink_E. Ignored only when absent; incompatible with supplied G.
        Default: ``None``.
    
    hpo_trials : int
        Number of Optuna sparse rank and shrinkage trials when optimization is
        enabled; positive integer controlling the search budget. Default: ``12``.
    
    missing : str
        Only 'exact' is supported: finite observed cells define the joint Gaussian
        conditioning system. Retired legacy imputation policies raise ValueError.
        Default: 'exact'.
    
    center : bool
        Whether to subtract the observed/training mean along the modeled observation axis.
        Disable only when inputs have already been centered using training data or a
        zero-intercept model is intended. Default: ``True``. Passed to the observed-cell solver as
        ``center``.
    
    dtype : NumPy dtype or str
        Numerical element type for the corresponding output, working block or accumulated
        matrix. Use a NumPy-compatible dtype; float32 reduces memory while float64 improves
        numerical precision. Default: ``np.float64``. Passed to the observed-cell solver as ``dtype``.
    
    jitter : float
        Small numerical floor or diagonal stabilization used to avoid singular inverses, zero
        denominators or nonpositive factor variances. Choose a positive value on the scale of
        the input quantities. Default: ``1e-08``. Passed to the observed-cell solver as ``jitter``.
    
    return_numpy : bool
        Historical array-output switch, accepted by the supported observed-cell solver as
        ``return_numpy``; the Dataset keeps the input labels as coordinates either way.
        Default: ``False``.
    
    return_aux : bool
        Also fold solver diagnostics into the Dataset: ``means`` ('trait') plus centering,
        observed/total counts, missing fraction, resolved precision/rank, operator errors and
        PCG residual/iterations as attrs; only added when set. Default: ``False``.
    
    solver_tol : float
        Convergence tolerance for the corresponding solver criterion. Use a nonnegative finite
        value; relative, gradient and objective criteria follow the underlying solver named in
        this routine. Default: ``1e-07``. Passed to the observed-cell solver as ``solver_tol``.
    
    solver_maxiter : int
        Maximum solver iteration count. A positive integer caps work; convergence diagnostics
        must still be checked rather than assuming the cap guarantees convergence. Default:
        ``500``. Passed to the observed-cell solver as ``solver_maxiter``.
    
    preconditioner : str or None
        PCG preconditioning: 'auto' selects 'sample_block' when 1<T<=64 and trait covariance is
        coupled, otherwise 'diag'; 'diag' uses observed marginal variances, 'sample_block'
        within-animal observed-trait blocks, and 'trait_block' within-trait animal blocks
        (requires cheap kernel submatrices). 'none'/None disables preconditioning. Default:
        ``'auto'``.
    
    work_dtype : str or NumPy float32/float64 dtype
        Working precision: 'auto'/'mixed' uses float32 in a fast plan; 'float32' and 'float64'
        explicitly select precision, with equivalent NumPy type/dtype objects accepted.
        accuracy='exact' resolves auto to float64 and rejects explicit float32/mixed. Other
        dtypes are rejected. Default: ``'auto'``.
    
    blas_threads : int or str
        BLAS thread limit during numerical operations. Positive integers select an explicit
        thread count; auto uses the routine's workload-dependent thread policy. Default:
        ``'auto'``. Passed to the observed-cell solver as ``blas_threads``.
    
    return_components : bool
        Add one ('sample','trait') variable per named genetic component next to ``total``;
        only added when set. Default: ``False``.
    
    solver_plan : PreparedMultivariatePlan or None
        Reusable plan from prepare_mvBLUP_plan for exactly the same phenotype masks,
        kernel/covariance state and labels. None constructs a new plan. Reusing stale means or
        observation masks changes the conditioning problem, so rebuild after changing training
        data. Default: ``None``.
    
    kernel_rank : int, str or None
        Animal-kernel approximation rank. None, 0, False or 'full' retains the full kernel;
        'auto' uses a size-based rank in fast plans; a positive integer requests that many
        retained eigenvectors plus a residual bulk eigenvalue. Exact plans reject compression.
        This is distinct from trait covariance rank. Default: ``'full'``.
    
    diag_only : bool
        Whether to remove cross-trait covariance terms and use only the diagonal trait variances
        for conditioning. Default: ``False``. Passed to the observed-cell solver as ``diag_only``.
    
    solver : str
        Observed-space solve selection: 'auto' and 'pcg' use the reusable preconditioned
        conjugate-gradient plan. Other values raise ValueError. Default: ``'auto'``.
    
    accuracy : str
        Conditioning precision: 'auto' selects 'exact' below 1024 animals and 'fast' at/above
        1024; 'exact' forces float64/full-kernel conditioning, while 'fast' permits float32 and
        requested kernel compression. prepare_mvBLUP_plan accepts only 'exact' and 'fast'.
        Default: ``'auto'``.
    
    **legacy_kwargs : dict
        Unsupported historical options are rejected with TypeError.
    
    Returns
    -------
    xarray.Dataset
        Data variable ``total`` ('sample','trait'): summed genetic breeding values without the
        fixed trait means, labeled by the trait DataFrame index/columns. return_components adds
        one variable per named component; return_aux adds ``means`` ('trait') and attrs
        method, n_obs, n_total, missing_fraction, operator_diagnostics, accuracy*,
        resolved_work_dtype, kernel_rank*, cg_info, cg_iterations, cg_relative_residual,
        preconditioner (and prediction_sparse_cv/covariance_fit when G=None).
    
    Complexity
    ----------
    For missing='exact' and supplied G/E, TIME O(I k (n²t+nt²)) plus prepare_mvBLUP_plan/preconditioning, SPACE O(k n²+nt+k t²+P), for n animals, t traits, k kernels, I PCG iterations and P preconditioner storage. Low-rank trait/kernel operators replace nt²/n²t with nt r/nqt for ranks r/q. Sample/trait-block preconditioners may add O(n t³)/O(t n³) setup time and O(n t²)/O(t n²) space. G=None additionally performs training-only covariance CV. Legacy non-exact missing policies are rejected; all supported predictions use the observed-cell solver.
    """
    traits=_as_pandas_input(traits); GRM=_kernel_input(GRM); G=_covariance_input(G); E=_as_pandas_input(E)
    covariance_fit=None
    if G is None:
        if E is not None:
            raise ValueError("E must be None when automatically fitting sparse G+E")
        from .prediction_sparse_cv import fit_sparse_prediction_covariance
        covariance_fit=fit_sparse_prediction_covariance(
            traits,GRM,covariance_cv=covariance_cv,
            optimize_hyperparameters_cv=optimize_hyperparameters_cv,
            covariance_cv_ranks=covariance_cv_ranks,covariance_kwargs=covariance_kwargs,
            hpo_trials=hpo_trials,blas_threads=blas_threads)
        covariance_view=_result_view(covariance_fit)
        G=covariance_view["G_prediction"]
        E=covariance_view["E_prediction"]
    elif covariance_kwargs is not None or optimize_hyperparameters_cv:
        raise ValueError("pre-fitted G/E cannot be simultaneously refitted or tuned; use G=None")
    requested_accuracy=str(accuracy).lower()
    n_auto=len(traits) if hasattr(traits,'__len__') else np.asarray(traits).shape[0]
    accuracy=('fast' if (missing!="exact" or n_auto>=1024) else 'exact') if requested_accuracy=='auto' else requested_accuracy
    if accuracy not in {'exact','fast'}: raise ValueError("accuracy must be 'auto', 'exact', or 'fast'")
    if missing != "exact":
        raise ValueError("mvBLUP supports missing='exact' only; legacy missing-data policies were retired")
    if legacy_kwargs:
        bad = ", ".join(sorted(legacy_kwargs))
        raise TypeError(f"unsupported mvBLUP keyword argument(s): {bad}")
    if solver not in {"auto", "pcg"}:
        raise NotImplementedError("this mvBLUP path supports solver='auto' or solver='pcg' only")
    if solver_plan is None:
        plan = prepare_mvBLUP_plan(traits, GRM, G, E, center=center, work_dtype=work_dtype, jitter=jitter, preconditioner=preconditioner, kernel_rank=kernel_rank, blas_threads=blas_threads, diag_only=diag_only, accuracy=accuracy)
    else:
        plan = solver_plan
        Ycheck = traits.to_numpy(float, copy=True) if isinstance(traits, pd.DataFrame) else np.asarray(traits, float).copy()
        if Ycheck.ndim != 2 or Ycheck.shape != (plan.n, plan.t):
            raise ValueError("solver_plan dimensions do not match traits")
        means = np.nanmean(Ycheck, axis=0) if center else np.zeros(plan.t)
        means = np.where(np.isfinite(means), means, 0.0); Ycheck -= means[None, :]
        och = _legacy._observed_plan(Ycheck)
        flat = och.get("flat", och["animals"].astype(np.int64) * plan.t + och["traits"].astype(np.int64))
        pflat = plan.obs_plan.get("flat", plan.obs_plan["animals"].astype(np.int64) * plan.t + plan.obs_plan["traits"].astype(np.int64))
        if not np.array_equal(flat, pflat) or not np.allclose(och["y"], plan.obs_plan["y"], rtol=0, atol=0):
            raise ValueError("solver_plan observation mask or trait data do not match traits")
        if isinstance(traits, pd.DataFrame) and (not traits.index.equals(plan.index) or not traits.columns.equals(plan.columns)):
            raise ValueError("solver_plan row or column labels do not match traits")
        if str(accuracy).lower() != plan.accuracy or bool(diag_only) != plan.diag_only:
            raise ValueError("solver_plan conflicts with requested accuracy or diag_only")
    bt = 4 if blas_threads == "auto" else blas_threads
    ctx = threadpool_limits(limits=int(bt), user_api="blas") if threadpool_limits is not None and bt not in {None, 0, "none"} else nullcontext()
    with ctx:
        alpha, info = plan.solve(rtol=solver_tol, maxiter=solver_maxiter)
        total, comp = _predict_components(plan, alpha, out_dtype=np.dtype(dtype))
    residual_limit = (max(20 * solver_tol, 100 * np.finfo(np.float64).eps * max(plan.obs_plan["m"], 1))
                      if plan.accuracy == "exact" else max(20 * solver_tol, 2e-5))
    if info["cg_info"] != 0 or info["cg_relative_residual"] > residual_limit:
        raise RuntimeError(f"mvBLUP PCG did not converge: {info}")
    def wrap(A):
        """Restore result labels/representation from the enclosing input metadata.

        Parameters
        ----------
        A : array-like
            Numerical operand in ``pd.DataFrame(A, index=traits.index, columns=traits.columns)``.
            Shape must conform to that matrix/vector operation and the enclosing prepared state.

        Returns
        -------
        object
            Computed result from ``pd.DataFrame(A, index=traits.index, columns=traits.columns)``; see the summary and the called implementation for its labeled/numerical representation.
        """
        if return_numpy or not isinstance(traits, pd.DataFrame):
            return A
        return pd.DataFrame(A, index=traits.index, columns=traits.columns)
    totalw = wrap(total)
    result = {"total": totalw, **{n: wrap(v) for n, v in comp.items()}} if return_components else totalw
    if not return_aux:
        return result
    aux = {
        "method": "missing_exact_shared_factor_pcg",
        "means": plan.means,
        "n_obs": plan.obs_plan["m"],
        "n_total": plan.n * plan.t,
        "missing_fraction": 1.0 - plan.obs_plan["m"] / (plan.n * plan.t),
        "operator_diagnostics": plan.operator_diagnostics,
        "accuracy": plan.accuracy,
        "accuracy_requested": requested_accuracy,
        "accuracy_mode": plan.accuracy,
        "resolved_work_dtype": str(np.dtype(plan.dtype)),
        "work_dtype_resolved": str(np.dtype(plan.dtype)),
        "kernel_rank_requested": kernel_rank,
        "resolved_kernel_rank": {k: v.get("resolved_rank") for k, v in (plan.operator_diagnostics or {}).items()},
        "kernel_rank_resolved": {k: v.get("resolved_rank") for k, v in (plan.operator_diagnostics or {}).items()},
        "kernel_approximation_error": {k: v.get("probe_relative_error") for k, v in (plan.operator_diagnostics or {}).items()},
        "diag_only": plan.diag_only,
        "solver": "pcg",
        "version": VIGOR_MULTIVARIATE_VERSION,
        **info,
    }
    if covariance_fit is not None:
        aux["prediction_sparse_cv"]=covariance_view["prediction_sparse_cv"]
        aux["covariance_fit"]=covariance_fit
    return result, aux
















