def mvGWAS(traitdf, genotypes="genotypes/genotypes", *, GRM=None, G=None, E=None,
           gwas_method="exact", mv_kernel_rank="full", **kwargs):
    """Run the exact observed-space score engine; see gwas.scan.exact_mv_gwas.

    Inputs: labeled Gaussian traitdf; genotype DataFrame/source/path; optional
    aligned GRM and matching trait covariance G/E; keyword options forwarded to
    exact_mv_gwas. gwas_method accepts exact or loco_mv_score_exact only, and
    mv_kernel_rank must be full/None. Calibrated fits must be passed explicitly
    as G/E; the estimator never silently changes the null covariance.

    Returns an xarray Dataset with variant-by-trait scores and joint omnibus.
    Complexity: O(m*t) covariance RHS solves plus kernel/eig setup; streamed
    output has bounded block memory. See exact_mv_gwas for detailed inputs,
    missingness, fixed-effect projection, precision and complexity contracts.
    """
    if gwas_method not in {"exact", "loco_mv_score_exact"}:
        raise ValueError("approximate/legacy gwas_method retired; use gwas_method='exact'")
    if mv_kernel_rank not in {None, "full"}:
        raise ValueError("GWAS null kernel rank substitution retired; use mv_kernel_rank='full'")
    from .gwas.scan import exact_mv_gwas
    return exact_mv_gwas(traitdf, genotypes, GRM=GRM, G=G, E=E, **kwargs)


def mvGWAS_local(traitdf, genotypes="genotypes/genotypes", **kwargs):
    """Exact disjoint leave-window-out scan; see gwas.scan.exact_local_gwas.

    Inputs: phenotype DataFrame and genotype source/path, window_mb/exclusion_mb
    plus exact null/scanning controls. Outputs: canonical xarray score Dataset.
    Work: one O(n²m) background reconstruction per window plus exact GLS solves;
    no adaptive or approximate local-score fallback is retained.
    """
    from .gwas.scan import exact_local_gwas
    return exact_local_gwas(traitdf, genotypes, **kwargs)


