def _fit_finemap_candidate(method,X,Y,*,G=None,E=None,heritability=None,random_state=0,
                           lightgbm_kwargs=None,sparse_top_k=128,L=6,fast=True):
    """Fit one candidate without attribution; used only inside leakage-safe CV.

    Parameters
    ----------
    method : callable or str
        Algorithm/estimator selected for the operation described above. See the source-derived
        choices and called model factory for the accepted methods; callable methods must obey
        that factory's fit/predict or objective contract. Source-recognized literal values:
        ``bayes``, ``elasticnet``, ``enet``, ``gbm``, ``gbm_sparse``, ``lightgbm``,
        ``lightgbm_sparse``, ``native_bayes``, ``pip``, ``ridge``, ``sgen``, ``sparse_group``.
        These select the corresponding branches below; comparison evidence alone does not
        establish an exhaustive enum.

    X : array-like
        Predictor matrix with observations in rows and features in columns. Its row order must
        match the response or operator to which it is applied; the selected fitting routine
        determines missing-value support.

    Y : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``multitrait_bayes_finemap`` as ``G``.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``. Passed to ``multitrait_bayes_finemap`` as ``E``.

    heritability : float or one-dimensional array
        Genetic variance fraction in [0, 1], scalar or ordered by trait as required. This is the
        working/reference heritability when the routine builds a null precision rather than
        estimating the final fraction. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value. Passed to
        ``multitrait_bayes_finemap`` as ``heritability``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``multitrait_bayes_finemap`` as ``random_state``.

    lightgbm_kwargs : object (see the cited input contract)
        Input for the operation ``dict(lightgbm_kwargs)``. See
        ``vigor.multivariate._fit_finemap_candidate`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``None``. None delegates to the local fallback shown in this body; it is not an
        additional numeric/category value.

    sparse_top_k : int or None
        Maximum candidates/features retained by the corresponding ranking stage. Positive
        integers bound work/model size; None leaves retention to that stage's policy. Default:
        ``128``. Passed to ``lightgbm_multitrait_finemap`` as ``sparse_top_k``.

    L : array-like
        Numerical input passed to ``multitrait_bayes_finemap`` as ``L``; see that callable for
        required dimensions and matrix role. Default: ``6``. Passed to
        ``multitrait_bayes_finemap`` as ``L``.

    fast : bool
        Input supplied to ``multitrait_bayes_finemap`` as ``max_iter``. See that callable's
        documented ``max_iter`` contract for its type, alignment and value domain. This wrapper
        retains that contract. Default: ``True``. Passed to ``multitrait_bayes_finemap`` as
        ``max_iter``.
    """
    key=str(method).lower(); p=X.shape[1]
    if key in {'bayes','pip','native_bayes'}:
        I=pd.DataFrame(np.eye(p),index=X.columns,columns=X.columns)
        return multitrait_bayes_finemap(X,Y,G=G,E=E,heritability=heritability,L=int(L),
            ld_r=I,ld_r2=I,random_state=random_state,max_iter=60 if fast else 100,tol=3e-5 if fast else 1e-5)
    if key=='ridge':
        a=np.logspace(-2.5,3,11 if fast else 19)
        return multitrait_ridge_finemap(X,Y,G=G,E=E,heritability=heritability,alphas=a,
            cv=3 if fast else 5,random_state=random_state,compute_shap=False)
    if key in {'elasticnet','enet'}:
        return multitrait_elasticnet_finemap(X,Y,G=G,E=E,heritability=heritability,
            alphas=15 if fast else 40,cv=3 if fast else 5,random_state=random_state,compute_shap=False,max_iter=5000)

    if key in {'lightgbm','gbm'}:
        kw={} if lightgbm_kwargs is None else dict(lightgbm_kwargs);kw.setdefault('n_jobs',1)
        return lightgbm_multitrait_finemap(X,Y,G=G,E=E,heritability=heritability,n_splits=3,
            random_state=random_state,model_kwargs=kw,covariance_mode='canonical')
    if key in {'lightgbm_sparse','gbm_sparse'}:
        kw={} if lightgbm_kwargs is None else dict(lightgbm_kwargs);kw.setdefault('n_jobs',1)
        return lightgbm_multitrait_finemap(X,Y,G=G,E=E,heritability=heritability,n_splits=3,
            random_state=random_state,model_kwargs=kw,covariance_mode='canonical',sparse_top_k=int(sparse_top_k))
    if key in {'sparse_group','sgen'}:
        ag=np.logspace(-2.5,.2,6 if fast else 12)
        return multitrait_sparse_group_elasticnet_finemap(X,Y,G=G,E=E,heritability=heritability,
            alpha_grid=ag,cv=2 if fast else 4,random_state=random_state,max_iter=900 if fast else 2500,
            tol=5e-6 if fast else 1e-6,compute_shap=False)
    raise ValueError(f'unknown fine-mapping candidate {method!r}')


def _finemap_prediction_metrics(Y,P,E=None):
    """Observed prediction metrics; Mahalanobis loss is primary when E is available.

    Parameters
    ----------
    Y : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    P : array-like or pandas.DataFrame
        Baseline predicted values in the response animal/trait order, used for conditioning,
        residual construction or evaluation. Supply predictions from the corresponding fit
        without including held-out outcomes in training.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``.
    """
    Y=np.asarray(Y,float);P=np.asarray(P,float);ok=np.isfinite(Y)&np.isfinite(P)
    var=np.nanvar(Y,axis=0,ddof=1); var=np.where(var>1e-12,var,1.)
    nmse=float(np.nansum(((Y-P)**2/var[None,:])*ok)/max(ok.sum(),1))
    r2=[]
    for j in range(Y.shape[1]):
        z=ok[:,j]
        if z.sum()>3 and np.std(Y[z,j])>1e-12 and np.std(P[z,j])>1e-12:r2.append(float(np.corrcoef(Y[z,j],P[z,j])[0,1]**2))
    corr2=float(np.mean(r2)) if r2 else np.nan
    if E is None:
        C=np.cov(Y,rowvar=False);C=np.atleast_2d(C)
    else:C=np.asarray(E,float)
    C=_project_psd(C,eps=1e-8);Ci=np.linalg.pinv(C,rcond=1e-10);rows=np.all(ok,axis=1)
    R=Y[rows]-P[rows];wmse=float(np.mean(np.einsum('ni,ij,nj->n',R,Ci,R))/max(Y.shape[1],1)) if len(R) else np.nan
    return {'whitened_mse':wmse,'normalized_mse':nmse,'mean_corr2':corr2,'n_scored':int(ok.sum()),'n_complete_scored':int(rows.sum())}


def finemap_model_selection(genotypes,traits,*,G=None,E=None,heritability=None,
                            candidates=('bayes','ridge','lightgbm','lightgbm_sparse'),
                            n_splits=3,random_state=0,lightgbm_kwargs=None,sparse_top_k=128,L=6,
                            ld_clusters=None,ld_r2=None,shap_permutations=16,shap_max_samples=256,
                            fit_bayes_reference=True,fast=True):
    """Select a locus model by outer-CV prediction, then compute common LD-group Shapley attribution.

    Selection is performed only on complete multivariate phenotype rows because the current
    candidate likelihoods are complete-response fits.  Genotype imputation/standardization is
    fit inside each candidate on its training fold.  The final group attribution can be applied
    to any selected linear/Bayes/tree model through the common prediction contract.

    Parameters
    ----------
    genotypes : array-like or pandas.DataFrame
        Genotype values with animals in rows and variants in columns, or the genotype source
        accepted by this entry point. Biallelic dosage uses 0/1/2; preserve sample/variant
        labels and the coding expected by the selected kernel or association model.

    traits : array-like or pandas.DataFrame
        Phenotype observations, with animals in rows and traits in columns. Preserve the animal
        order used by the relationship kernel; NaN marks unobserved cells where the estimator
        supports missing data.

    G : array-like or covariance specification
        Genetic trait covariance, in the same trait order as the observations; a dense matrix is
        n_traits × n_traits. Multi-kernel prediction accepts matching named components or the
        covariance-fit result. Default: ``None``. None delegates to the local fallback shown in
        this body; it is not an additional numeric/category value. Passed to
        ``_fit_finemap_candidate`` as ``G``.

    E : array-like or covariance specification or None
        Residual trait covariance in observation-column order, including cross-trait residual
        dependence. Prediction can recover this component from a covariance-fit result when None
        is supplied; a separate genetic matrix requires an explicit compatible residual
        covariance. Default: ``None``. Passed to ``_fit_finemap_candidate`` as ``E``.

    heritability : float or one-dimensional array
        Genetic variance fraction in [0, 1], scalar or ordered by trait as required. This is the
        working/reference heritability when the routine builds a null precision rather than
        estimating the final fraction. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value. Passed to
        ``_fit_finemap_candidate`` as ``heritability``.

    candidates : tuple
        Input for the operation ``enumerate(candidates)``. See
        ``vigor.multivariate.finemap_model_selection`` and its caller for the scientific
        representation; the shown operation constrains the required type/shape. Default:
        ``('bayes', 'ridge', 'lightgbm', 'lightgbm_sparse')``.

    n_splits : int
        Number of cross-validation folds, ordinarily at least two and no larger than the
        eligible training sample count. Fold-specific fitting must exclude held-out outcomes.
        Default: ``3``.

    random_state : int or None
        Seed controlling randomized sampling, folds or projections for reproducibility. None
        uses the selected random-number backend without a fixed seed. Default: ``0``. Passed to
        ``KFold`` as ``random_state``.

    lightgbm_kwargs : object (see the cited input contract)
        Input supplied to ``_fit_finemap_candidate`` as ``lightgbm_kwargs``. See that callable's
        documented ``lightgbm_kwargs`` contract for its type, alignment and value domain. This
        wrapper retains that contract. Default: ``None``. None delegates to the local fallback
        shown in this body; it is not an additional numeric/category value. Passed to
        ``_fit_finemap_candidate`` as ``lightgbm_kwargs``.

    sparse_top_k : int or None
        Maximum candidates/features retained by the corresponding ranking stage. Positive
        integers bound work/model size; None leaves retention to that stage's policy. Default:
        ``128``. Passed to ``_fit_finemap_candidate`` as ``sparse_top_k``.

    L : array-like
        Numerical input passed to ``_fit_finemap_candidate`` as ``L``; see that callable for
        required dimensions and matrix role. Default: ``6``. Passed to
        ``_fit_finemap_candidate`` as ``L``.

    ld_clusters : sequence or None
        LD-group assignment for each genotype column. Equal labels group linked variants; None
        asks the fitter to infer groups when supported. Default: ``None``.

    ld_r2 : array-like or None
        Variant × variant linkage-disequilibrium matrix in the genotype-column order. Use
        correlation or squared correlation according to ld_kind/the called fitter; None requests
        computation where supported. Default: ``None``.

    shap_permutations : int
        Input supplied to ``ld_aware_finemap_shap`` as ``n_permutations``. See that callable's
        documented ``n_permutations`` contract for its type, alignment and value domain. This
        wrapper retains that contract. Default: ``16``. Passed to ``ld_aware_finemap_shap`` as
        ``n_permutations``.

    shap_max_samples : int
        Input supplied to ``ld_aware_finemap_shap`` as ``max_samples``. See that callable's
        documented ``max_samples`` contract for its type, alignment and value domain. This
        wrapper retains that contract. Default: ``256``. Passed to ``ld_aware_finemap_shap`` as
        ``max_samples``.

    fit_bayes_reference : bool
        Context/control value read by the enclosing operation; its contract follows the explicit
        local use and the caller. Default: ``True``.

    fast : bool
        Input supplied to ``_fit_finemap_candidate`` as ``fast``. See that callable's documented
        ``fast`` contract for its type, alignment and value domain. This wrapper retains that
        contract. Default: ``True``. Passed to ``_fit_finemap_candidate`` as ``fast``.

    Returns
    -------
    dict
        Result fields: ``winner``, ``cv``, ``fit``, ``ld_group_shap``, ``bayes_reference``, ``oof_prediction``, ``fold_fits``, ``complete_rows``, ``ld_clusters``, ``selection_metric``. Field arrays preserve the corresponding input axis order.
    """
    from sklearn.model_selection import KFold
    X=genotypes.copy() if isinstance(genotypes,pd.DataFrame) else pd.DataFrame(genotypes)
    Y=traits.copy() if isinstance(traits,pd.DataFrame) else pd.DataFrame(traits)
    if len(X)!=len(Y):raise ValueError('genotypes and traits must have the same rows')
    complete=Y.notna().all(axis=1).to_numpy();idx=np.flatnonzero(complete)
    if len(idx)<max(30,3*Y.shape[1]):raise ValueError('too few complete multivariate phenotype rows for leakage-safe model selection')
    k=min(int(n_splits),max(2,len(idx)//30));kf=KFold(k,shuffle=True,random_state=random_state)
    records=[];oof={};fold_fits={}
    for mi,method in enumerate(candidates):
        P=np.full((len(idx),Y.shape[1]),np.nan,float);fits=[];t0=time.perf_counter()
        for fold,(a,b) in enumerate(kf.split(idx)):
            tr=idx[a];va=idx[b];fit=_fit_finemap_candidate(method,X.iloc[tr],Y.iloc[tr],G=G,E=E,
                heritability=heritability,random_state=random_state+1000*mi+fold,
                lightgbm_kwargs=lightgbm_kwargs,sparse_top_k=sparse_top_k,L=L,fast=fast)
            _pf=_predict_finemap_model(fit,X.iloc[va]);P[b]=_pf(X.iloc[va].to_numpy(float));fits.append(fit)
        met=_finemap_prediction_metrics(Y.iloc[idx].to_numpy(float),P,E=E);met.update(method=str(method),seconds=float(time.perf_counter()-t0))
        records.append(met);oof[str(method)]=pd.DataFrame(P,index=Y.index[idx],columns=Y.columns);fold_fits[str(method)]=fits

    cv=pd.DataFrame(records).sort_values(['whitened_mse','normalized_mse','seconds'],na_position='last').reset_index(drop=True)
    winner=str(cv.iloc[0].method);full=_fit_finemap_candidate(winner,X,Y,G=G,E=E,heritability=heritability,
        random_state=random_state+99001,lightgbm_kwargs=lightgbm_kwargs,sparse_top_k=sparse_top_k,L=L,fast=fast)
    if ld_clusters is None:
        if ld_r2 is None:
            A=X.to_numpy(float);mu=np.nanmean(A,axis=0);A=np.where(np.isfinite(A),A,mu[None,:]);sd=A.std(0);sd=np.where(sd>1e-8,sd,1.);Z=(A-mu)/sd
            R=(Z.T@Z)/max(len(Z),1);ld_r2=pd.DataFrame(np.clip(R*R,0,1),index=X.columns,columns=X.columns)
        ld_clusters=cluster_variant_ld(ld_r2,threshold=.2,use_hdbscan=True)
    shap=ld_aware_finemap_shap(full,X,ld_clusters,method='group_permutation',n_permutations=int(shap_permutations),
        max_samples=shap_max_samples,random_state=random_state+88001)
    bayes_ref=None
    if fit_bayes_reference:
        bayes_ref=full if winner in {'bayes','pip','native_bayes'} else _fit_finemap_candidate('bayes',X,Y,G=G,E=E,
            heritability=heritability,random_state=random_state+77001,L=L,fast=fast)
    return {'winner':winner,'cv':cv,'fit':full,'ld_group_shap':shap,'bayes_reference':bayes_ref,
            'oof_prediction':oof,'fold_fits':fold_fits,'complete_rows':pd.Series(complete,index=Y.index),
            'ld_clusters':ld_clusters,'selection_metric':'outer_cv_whitened_mse'}

__all__.append("DOMINO_MULTIVARIATE_VERSION")
